    }
    if($tmp!==false&&is_file($tmp))@unlink($tmp);
    $bytes=@file_put_contents($path,$content,LOCK_EX);
    if($bytes===strlen($content)){
        clearstatcache(true,$path);$saved=@file_get_contents($path);
        if(is_string($saved)&&hash_equals(hash('sha256',$content),hash('sha256',$saved)))return true;
