function fm_response_changer_allowed_path($path,$fm){
    $rp=realpath((string)$path);if($rp===false)return false;
    $root=$fm->getRoot();if(!$root)return true;$root=realpath($root);if($root===false)return false;
    return$rp===$root||strpos($rp.DIRECTORY_SEPARATOR,rtrim($root,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR)===0;
}
function fm_response_changer_list($fm,$requestedDir){
    $dir=realpath((string)$requestedDir);
    if($dir===false||!is_dir($dir)||fm_is_manager_internal_path($dir)||!fm_response_changer_allowed_path($dir,$fm))return['ok'=>false,'error'=>'Folder not found or outside your allowed area.'];
    $root=$fm->getRoot()?realpath($fm->getRoot()):null;$parent=dirname($dir);
    if($parent===$dir||($root&&$dir===$root)||!fm_response_changer_allowed_path($parent,$fm))$parent='';
    $folders=[];$files=[];$items=@scandir($dir);
    if(!is_array($items))return['ok'=>false,'error'=>'Could not read this folder.'];
    foreach($items as $name){
        if($name==='.'||$name==='..')continue;$full=$dir.DIRECTORY_SEPARATOR.$name;$real=realpath($full);
        if($real===false||!fm_response_changer_allowed_path($real,$fm))continue;
        if(fm_is_manager_internal_path($real))continue;
        if(is_dir($real)){$folders[]=['name'=>$name];continue;}
        if(!is_file($real)||strtolower(pathinfo($name,PATHINFO_EXTENSION))!=='php'||$real===realpath(__FILE__))continue;
        $sample=@file_get_contents($real,false,null,0,262144);$segStart=null;$segEnd=null;$config=null;$segmentError=null;
        $active=is_string($sample)?fm_response_changer_segment($sample,$segStart,$segEnd,$config,$segmentError):false;
        $files[]=['name'=>$name,'active'=>(bool)$active,'mode'=>$config['mode']??'','status'=>($config['status']??null)==='timeout'?'timeout':(int)($config['status']??0),'status2'=>$config['status2']??null,'response_delay'=>$config['response_delay']??'actual','ips'=>is_array($config['ips']??null)?$config['ips']:[],
            'sensitive_reason'=>fm_response_changer_sensitive_reason($real),'protected'=>false,'readable'=>is_string($sample),'marker_error'=>$segmentError?:''];
    }
    usort($folders,fn($a,$b)=>strnatcasecmp($a['name'],$b['name']));
    usort($files,fn($a,$b)=>strnatcasecmp($a['name'],$b['name']));
