}
function fm_response_changer_change_file($path,$operation,$settings,&$error=null,&$changed=null){
    $error=null;$changed=false;$path=realpath((string)$path);
    if($path===false||!is_file($path)){$error='PHP file not found.';return false;}
    if($path===realpath(__FILE__)){$error='The File Manager has a separate protected control and cannot be changed as a regular file.';return false;}
    if(fm_is_manager_internal_path($path)){$error='File Manager internal files cannot be changed with this tool.';return false;}
    $size=@filesize($path);if($size===false||$size>20*1024*1024){$error='Files larger than 20 MB cannot be changed with this tool.';return false;}
    $source=@file_get_contents($path);if(!is_string($source)){$error='Could not read the PHP file.';return false;}
    $start=null;$end=null;$existing=null;$markerError=null;
    $active=fm_response_changer_segment($source,$start,$end,$existing,$markerError);
    if($markerError!==null&&$markerError!==''){$error=$markerError;return false;}
    if($operation==='disable'){
        if(!$active)return true;
        $updated=substr($source,0,$start).substr($source,$end);
    }elseif($operation==='enable'){
        $snippet=fm_response_changer_snippet($settings);
        if($active)$updated=substr($source,0,$start).$snippet.substr($source,$end);
        else{
            $insertAt=fm_response_changer_insertion_offset($source,$offsetError);
            if($insertAt===false){$error=$offsetError?:'Could not safely find an insertion point.';return false;}
            $updated=substr($source,0,$insertAt).$snippet.substr($source,$insertAt);
        }
