}
function fm_response_changer_store_manager($settings,&$error=null){
    $error=null;$file=fm_response_changer_config_file();$hadFile=is_file($file);$old=$hadFile?@file_get_contents($file):'';
    if($hadFile&&!is_string($old)){$error='Could not read the previous File Manager rule.';return false;}
    $data=$settings?json_encode($settings,JSON_UNESCAPED_SLASHES):json_encode(['enabled'=>false]);
    if($data===false){$error='Could not encode the manager settings.';return false;}
    $tmp=@tempnam(__DIR__,'.mfm-response-manager-');
    if($tmp!==false&&@file_put_contents($tmp,$data,LOCK_EX)===strlen($data)){
        @chmod($tmp,0600);
        if(@rename($tmp,$file)){clearstatcache(true,$file);$saved=@file_get_contents($file);if(is_string($saved)&&hash_equals(hash('sha256',$data),hash('sha256',$saved)))return true;}
        if(is_file($tmp))@unlink($tmp);
    }
    $bytes=@file_put_contents($file,$data,LOCK_EX);
    if($bytes===strlen($data)){@chmod($file,0600);$saved=@file_get_contents($file);if(is_string($saved)&&hash_equals(hash('sha256',$data),hash('sha256',$saved)))return true;}
