                        $size=(int)@filesize($path);
                        $found[]=[
                            'path'=>$path,'path_b64'=>base64_encode($path),'name'=>basename($path),
                            'directory'=>dirname($path),'size'=>$size,'modified'=>(int)@filemtime($path),
                            'too_large'=>$size>2097152
