    public function readConfigFile($path){
        $path=$this->inspectionPath($path);
        if($path===false||fm_is_manager_internal_path($path)||!$this->configFileName(basename($path),dirname($path)))return['ok'=>false,'error'=>'This configuration file is not available in your permitted scope.'];
