            }catch(Throwable $e){continue;}
        }
        $add('privilege','SGID program inventory',$sgidFound?'review':($sgidVisited?'good':'unknown'),$sgidFound?'low':'info',count($sgidFound).' discovered',$sgidFound?'SGID use can expose group-level access; compare with the operating-system baseline.':'No SGID programs were seen in readable standard binary directories.',implode(', ',array_slice(array_unique($sgidFound),0,20)));

        $sshFiles=[];$sshMain='/etc/ssh/sshd_config';
        if(is_readable($sshMain))$sshFiles[]=$sshMain;
        $sshIncludes=function_exists('glob')?@glob('/etc/ssh/sshd_config.d/*.conf'):false;
        if(is_array($sshIncludes))foreach(array_slice($sshIncludes,0,24) as $sshFile)if(is_file($sshFile)&&is_readable($sshFile))$sshFiles[]=$sshFile;
        $sshSettings=['permitrootlogin'=>[],'passwordauthentication'=>[],'permitemptypasswords'=>[]];
        foreach($sshFiles as $sshFile){
            $sshContent=$read($sshFile,65536);if(!is_string($sshContent))continue;
            foreach(preg_split('/\r?\n/',$sshContent) as $line){
                if(preg_match('/^\s*(PermitRootLogin|PasswordAuthentication|PermitEmptyPasswords)\s+(\S+)/i',$line,$sshMatch)){
                    $key=strtolower($sshMatch[1]);$sshSettings[$key][]=['value'=>strtolower($sshMatch[2]),'file'=>basename($sshFile)];
                }
            }
        }
        foreach([
            ['permitrootlogin','SSH root login',function($v){return $v==='yes'?'review':($v==='no'?'good':'review');},'Root login should normally be disabled; key-only values still require site policy review.'],
            ['passwordauthentication','SSH password authentication',function($v){return $v==='yes'?'review':($v==='no'?'good':'review');},'Password-based SSH increases exposure to credential guessing; verify the effective SSH policy.'],
            ['permitemptypasswords','SSH empty passwords',function($v){return $v==='yes'?'risk':($v==='no'?'good':'review');},'Empty-password SSH access should be disabled.']
        ] as $sshRule){
            $key=$sshRule[0];$label=$sshRule[1];$items=$sshSettings[$key];
            if(!$items){$add('privilege',$label,$sshFiles?'unknown':'unknown','info',$sshFiles?'No explicit directive found':'SSH config is not readable','The effective daemon setting may come from includes, defaults, Match blocks, or a service not visible to PHP.');continue;}
            $last=$items[count($items)-1];$state=$sshRule[2]($last['value']);
            $severity=$state==='risk'?'high':($state==='review'?'medium':'info');
            $add('privilege',$label,$state,$severity,strtoupper($last['value']),'Observed in configuration only; included files, Match rules, and the running daemon were not resolved.',$last['file'].(count($items)>1?' · '.count($items).' directives observed':''));
        }

        $listeners=[];$listenerFiles=['/proc/net/tcp','/proc/net/tcp6'];$listenerAvailable=false;
        foreach($listenerFiles as $listenerFile){
            $tcpText=$read($listenerFile,1048576);if(!is_string($tcpText))continue;$listenerAvailable=true;
            $lines=preg_split('/\r?\n/',$tcpText);
            foreach(array_slice($lines,1) as $line){
                $parts=preg_split('/\s+/',trim($line));
                if(count($parts)<4||strtoupper($parts[3])!=='0A')continue;
                $colon=strrpos($parts[1],':');if($colon===false)continue;
                $addr=substr($parts[1],0,$colon);$port=(int)hexdec(substr($parts[1],$colon+1));
                $wildcard=trim($addr,'0')==='';
                $listeners[]=['port'=>$port,'family'=>substr($listenerFile,-1)==='6'?'IPv6':'IPv4','wildcard'=>$wildcard];
                if(count($listeners)>=160)break 2;
            }
        }
        $wildListeners=array_values(array_filter($listeners,function($entry){return $entry['wildcard'];}));
        $listenerSummary=[];
        foreach(array_slice($listeners,0,24) as $entry)$listenerSummary[]=$entry['family'].' :'.$entry['port'].($entry['wildcard']?' *':'');
        $add('web','Listening TCP ports',$listenerAvailable?($wildListeners?'review':'good'):'unknown',$wildListeners?'low':'info',$listenerAvailable?count($listeners).' listening sockets':'Not visible',$wildListeners?'Some processes listen on all interfaces; firewall reachability and owning services cannot be confirmed from PHP.':($listenerAvailable?'No wildcard-bound TCP listeners were observed.':'Kernel socket table is not readable.'),implode(', ',$listenerSummary));

        $docRoot=realpath((string)($_SERVER['DOCUMENT_ROOT']??''));$webFindings=[];$webScanned=0;$webTruncated=false;$webStart=microtime(true);
        if($docRoot!==false&&is_dir($docRoot)&&is_readable($docRoot)){
            $skipDirs=['node_modules','vendor','cache','caches','uploads','.trash','backups'];
            try{
                $rootIt=new RecursiveDirectoryIterator($docRoot,FilesystemIterator::SKIP_DOTS);
                $rootFilter=new RecursiveCallbackFilterIterator($rootIt,function($current)use($skipDirs,$docRoot,&$webFindings){
                    try{
                        if($current->isLink()||fm_is_manager_internal_path($current->getPathname()))return false;
                        if($current->isDir()){
                            $directoryName=strtolower($current->getFilename());
                            if(in_array($directoryName,['.git','.svn','.hg'],true)){
                                $webFindings[]=['path'=>ltrim(substr($current->getPathname(),strlen($docRoot)),'/'),'severity'=>'medium'];
                                return false;
                            }
                            if(in_array($directoryName,$skipDirs,true))return false;
                        }
                        return true;
                    }catch(Throwable $e){return false;}
                });
                $webIt=new RecursiveIteratorIterator($rootFilter,RecursiveIteratorIterator::LEAVES_ONLY,RecursiveIteratorIterator::CATCH_GET_CHILD);
                foreach($webIt as $entry){
                    if(++$webScanned>12000||microtime(true)-$webStart>2.5){$webTruncated=true;break;}
                    $name=strtolower($entry->getFilename());$path=$entry->getPathname();$relative=ltrim(substr($path,strlen($docRoot)),'/');
                    if(preg_match('/^\.env(?:\.[a-z0-9_-]+)?$/i',$name)&&!in_array($name,['.env.example','.env.sample'],true))$webFindings[]=['path'=>$relative,'severity'=>'high'];
                    elseif(in_array($name,['.git','.svn','.hg'],true))$webFindings[]=['path'=>$relative,'severity'=>'medium'];
                    elseif(preg_match('/(?:^|\.)(?:bak|backup|old|orig|save|swp|sql|dump|zip|tar|tgz|gz|7z)$/i',$name)||preg_match('/(?:wp-config|configuration|database|credentials|secret)[^\/]*\.(?:bak|old|orig|save|zip|sql|gz)$/i',$name))$webFindings[]=['path'=>$relative,'severity'=>'high'];
                    elseif(in_array($name,['id_rsa','id_ed25519','authorized_keys'],true))$webFindings[]=['path'=>$relative,'severity'=>'high'];
                    if(count($webFindings)>=40){$webTruncated=true;break;}
                }
            }catch(Throwable $e){$webTruncated=true;}
            $htaccess=$read(rtrim($docRoot,'/').'/.htaccess',65536);
            $indexOn=is_string($htaccess)&&preg_match('/^\s*Options\s+\+?Indexes\b/im',$htaccess);
            $indexOff=is_string($htaccess)&&preg_match('/^\s*Options\s+-Indexes\b/im',$htaccess);
            $add('web','Apache directory index directive',$indexOn?'review':($indexOff?'good':'unknown'),$indexOn?'medium':'info',$indexOn?'Indexes enabled':($indexOff?'Indexes disabled':'Not explicitly set'),$indexOn?'A readable .htaccess contains an Indexes directive; effective server behavior was not tested.':($indexOff?'A readable .htaccess disables indexes.':'No effective Apache directory-index setting could be confirmed.'));
        }else{
            $add('web','Document root scan','unknown','info','Not visible','The current document root is not available to this PHP account.');
        }
        $webState=$webFindings?'review':($docRoot===false?'unknown':'good');
        $webSeverity='info';
        foreach($webFindings as $finding)if($finding['severity']==='high')$webSeverity='high';elseif($webSeverity==='info')$webSeverity='medium';
        $webEvidence=[];
        foreach(array_slice($webFindings,0,20) as $finding)$webEvidence[]=$finding['path'];
        $webDetail=$webFindings?'Sensitive-looking files or metadata directories were found below the document root. Direct HTTP access and server rules were not tested.':'No matching sensitive filenames were found within the bounded document-root scan.';
        if($webTruncated)$webDetail.=' The scan reached its entry, time, or result limit.';
        $add('web','Potentially exposed web-root files',$webState,$webSeverity,count($webFindings).' candidates',$webDetail,implode(', ',$webEvidence));
        $add('web','Web-root scan coverage',$docRoot===false?'unknown':($webTruncated?'review':'good'),$webTruncated?'low':'info',$docRoot===false?'Unavailable':number_format($webScanned).' entries checked', 'Read-only filename scan only; no file contents or HTTP requests were made.', $docRoot?:'');
        $add('web','Remote attack simulation','info','info','Not performed','No payloads, login attempts, HTTP fuzzing, exploit code, or privilege-escalation attempts are sent.');

        $counts=['critical'=>0,'high'=>0,'medium'=>0,'low'=>0,'good'=>0,'review'=>0,'unknown'=>0,'info'=>0];$score=0;
        $weights=['critical'=>35,'high'=>20,'medium'=>10,'low'=>4];
        foreach($checks as $check){
            if(isset($counts[$check['status']]))$counts[$check['status']]++;
            if(in_array($check['status'],['risk','review'],true)){
                if($check['status']==='risk')$counts[$check['severity']]=($counts[$check['severity']]??0)+1;
                $weight=$weights[$check['severity']]??0;
                $score+=($check['status']==='review'?max(1,(int)ceil($weight/2)):$weight);
            }
        }
        $score=min(100,$score);
        $overall=$counts['critical']?'critical':($counts['high']?'high':($counts['medium']?'elevated':($counts['review']?'review':'low-indicators')));
        return['meta'=>[
            'scanned_at'=>date(DATE_ATOM),'duration_ms'=>(int)round((microtime(true)-$started)*1000),
            'checks_count'=>count($checks),'score'=>$score,'overall'=>$overall,'counts'=>$counts,
            'worker_is_root'=>$euid===null?null:$euid===0,
            'os_family'=>$osFamily,
            'scope'=>'Local PHP worker and readable host metadata only',
            'limits'=>'Read-only checks; no commands, writes, exploit attempts, external probes, or live CVE feed.'
        ],'checks'=>$checks];
    }
    private function serverLogName($name){
        $n=strtolower((string)$name);
        if(preg_match('/\.(?:log|out|err)(?:\.[0-9]+)?$/i',$n))return true;
        if(preg_match('/(?:^|[_\-.])(access|error|audit|auth|syslog|messages|secure|daemon|kern|cron|mail|journal|debug|php.*fpm|nginx|apache|httpd)(?:[_\-.]|$)/i',$n))return true;
        return in_array($n,['syslog','messages','secure','auth','daemon','kern','cron','maillog','boot.log','btmp','wtmp','lastlog'],true);
    }
    public function getServerLogs(){
        $found=[];$seen=[];
        $configured=$this->errLogPath();
        if($configured){
            $path=$this->inspectionPath($configured);
            if($path!==false&&isset($seen[$path])===false&&$this->serverLogName(basename($path))){
                $seen[$path]=true;
                $found[]=['path'=>$path,'name'=>basename($path),'directory'=>dirname($path),'size'=>(int)@filesize($path),'modified'=>(int)@filemtime($path),'source'=>'PHP error_log'];
            }
        }
        foreach($this->inspectionRoots() as $root){
            $it=$this->inspectionIterator($root);if(!$it)continue;
            foreach($it as $item){
                try{
                    if(!$item->isFile()||!$this->serverLogName($item->getFilename()))continue;
                    $path=$this->inspectionPath($item->getPathname());
                    if($path===false||isset($seen[$path]))continue;
                    $seen[$path]=true;
                    $found[]=['path'=>$path,'name'=>basename($path),'directory'=>dirname($path),'size'=>(int)@filesize($path),'modified'=>(int)@filemtime($path),'source'=>'Server log'];
                }catch(Throwable $e){continue;}
            }
        }
        usort($found,function($a,$b){return strcasecmp($a['path'],$b['path']);});
        foreach($found as &$entry)$entry['path_b64']=base64_encode($entry['path']);
        unset($entry);
        return['logs'=>$found,'scanned_roots'=>$this->inspectionRoots()];
    }
    public function readServerLog($path){
        $path=$this->inspectionPath($path);
        if($path===false||!$this->serverLogName(basename((string)$path)))return['error'=>'This log is unavailable or outside the allowed scope.'];
        $content=@file_get_contents($path);
        if($content===false)return['error'=>'The log could not be read. Check the server permissions.'];
        return['path'=>$path,'name'=>basename($path),'directory'=>dirname($path),'size'=>(int)@filesize($path),'modified'=>(int)@filemtime($path),'content_b64'=>base64_encode($content)];
    }

    /* Large-file scanner (recursive, time-capped) */
    public function findLargeFiles($minBytes){
        $sd=$this->currentDir;$res=[];$start=microtime(true);$cap=8;$capped=false;$cnt=0;
        try{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($sd,RecursiveDirectoryIterator::SKIP_DOTS),RecursiveIteratorIterator::LEAVES_ONLY);}
        catch(Exception $e){return['files'=>[],'capped'=>false];}
        foreach($it as $item){
            if(microtime(true)-$start>$cap){$capped=true;break;}
            if(!$item->isFile())continue;
            $p=$item->getPathname();if(strpos($p,$this->trashDir)===0)continue;if($p===__FILE__)continue;
            $sz=$item->getSize();if($sz<$minBytes)continue;
            $res[]=['path'=>$p,'name'=>$item->getFilename(),'dir'=>dirname($p),'size'=>$sz];
            $cnt++;if($cnt>=500){$capped=true;break;}
        }
        usort($res,fn($a,$b)=>$b['size']<=>$a['size']);
        return['files'=>$res,'capped'=>$capped];
    }

    /* Duplicate-file finder (size, then md5, time-capped) */
    public function findDuplicates(){
        $sd=$this->currentDir;$bySize=[];$start=microtime(true);$cap=8;$capped=false;$cnt=0;
        try{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($sd,RecursiveDirectoryIterator::SKIP_DOTS),RecursiveIteratorIterator::LEAVES_ONLY);}
        catch(Exception $e){return['groups'=>[],'capped'=>false];}
        foreach($it as $item){
            if(microtime(true)-$start>$cap){$capped=true;break;}
            if(!$item->isFile())continue;
            $p=$item->getPathname();if(strpos($p,$this->trashDir)===0)continue;if($p===__FILE__)continue;
            $sz=$item->getSize();if($sz===0)continue;
            $bySize[$sz][]=$p;$cnt++;if($cnt>=5000){$capped=true;break;}
        }
        $groups=[];
        foreach($bySize as $sz=>$paths){
            if(count($paths)<2)continue;
            if(microtime(true)-$start>$cap){$capped=true;break;}
            $byHash=[];
            foreach($paths as $p){$h=@md5_file($p);if($h===false)continue;$byHash[$h][]=$p;}
            foreach($byHash as $h=>$fps){
                if(count($fps)<2)continue;
                $groups[]=['hash'=>$h,'size'=>$sz,'files'=>array_map(fn($p)=>['path'=>$p,'name'=>basename($p),'dir'=>dirname($p)],$fps)];
            }
        }
        usort($groups,fn($a,$b)=>$b['size']<=>$a['size']);
        return['groups'=>$groups,'capped'=>$capped];
    }

    /* One-click backup of current folder as .zip */
    private function backupDir(){
        if(!class_exists('ZipArchive')){$this->addMsg('ZIP extension not available.','danger');return;}
        $bdir=__DIR__.'/.backups';if(!is_dir($bdir))@mkdir($bdir,0755,true);
        $name='backup_'.preg_replace('/[^A-Za-z0-9_-]/','_',basename($this->currentDir)).'_'.date('Ymd_His').'.zip';
        $zp=$bdir.'/'.$name;
        $z=new ZipArchive();if($z->open($zp,ZipArchive::CREATE)!==true){$this->addMsg('Could not create backup archive.','danger');return;}
        $this->zadd($z,$this->currentDir,basename($this->currentDir));
        $z->close();
        $this->log('backup_dir',$name);
        $this->addMsg('Backup created: .backups/'.$name,'success');
    }

    /* Delete an absolute path, restricted to inside the current directory tree (used by the large-file / duplicate tools) */
    private function deleteAbs(){
        if($this->readonly){$this->addMsg('Read-only account.','danger');return;}
        $p=isset($_POST['abs_path'])?$_POST['abs_path']:'';
        $rp=realpath($p);
        $base=rtrim($this->currentDir,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR;
        if(!$rp||$rp===__FILE__||strpos($rp.DIRECTORY_SEPARATOR,$base)!==0){$this->addMsg('Invalid or out-of-scope path.','danger');return;}
        $n=basename($rp);
        if($this->isProtectedItem($n,$rp)){$this->addMsg('Access denied.','danger');return;}
        if($this->rmdirR($rp)){$this->log('delete_abs',$n);$this->addMsg('Deleted "'.$n.'".','warning');}
        else $this->addMsg('Delete failed.','danger');
    }

    /* Checksum */
    public function checksum($fn){
        $p=realpath($this->currentDir.'/'.$fn);
        if(!$p||!is_file($p)||$p===__FILE__)return null;
        return['md5'=>md5_file($p),'sha1'=>sha1_file($p),'sha256'=>hash_file('sha256',$p),'size'=>filesize($p),'name'=>$fn];
    }

    /* Terminal */
    public function getTerminalPromptPath(){
        $base=$this->root?:__DIR__;
        $cwd=$this->currentDir;
        if($cwd===$base)return'~';
        $prefix=rtrim($base,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR;
        if(strpos($cwd,$prefix)===0)return'~/'.str_replace(DIRECTORY_SEPARATOR,'/',substr($cwd,strlen($prefix)));
        return str_replace(DIRECTORY_SEPARATOR,'/',$cwd);
    }
    private function terminalPathAllowed($path){
        if(!$this->root)return true;
        $prefix=rtrim($this->root,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR;
        return $path===$this->root||strpos($path,$prefix)===0;
    }
    public function runCmd($cmd){
        if(empty(trim($cmd)))return['output'=>'','exit'=>0,'ms'=>0];
        $t=microtime(true);$out=[];$exit=0;
        $shellBin='internal-cd';
        $cmd=trim($cmd);
         /* Some providers occasionally serialize the complete shell command
           as one quoted string. Strip only a matching outer pair; quotes
           inside the command remain untouched and continue to be handled by
            the shell. Without this, bash -lc receives the whole command as a
           literal executable name and reports "No such file or directory". */
        if(strlen($cmd)>=2&&(($cmd[0]==="'"&&substr($cmd,-1)==="'")||($cmd[0]==='"'&&substr($cmd,-1)==='"'))){
            $cmd=trim(substr($cmd,1,-1));
        }
        if(preg_match('/^cd(?:\s+(.*))?$/s',$cmd,$m)){
            $arg=trim($m[1]??'');
            if($arg!==''&&(($arg[0]==="'"&&substr($arg,-1)==="'")||($arg[0]==='"'&&substr($arg,-1)==='"')))$arg=substr($arg,1,-1);
            $base=$this->root?:__DIR__;
            if($arg===''||$arg==='~')$target=$base;
            elseif($arg==='-')$target=$_SESSION['fm_terminal_previous_dir']??$this->currentDir;
            elseif(strpos($arg,'~/')===0)$target=$base.'/'.substr($arg,2);
            elseif($arg[0]==='/'||preg_match('/^[A-Za-z]:[\\\\\/]/',$arg))$target=$arg;
            else $target=$this->currentDir.'/'.$arg;
            $resolved=realpath($target);
            if($resolved===false||!is_dir($resolved)||!$this->terminalPathAllowed($resolved)){
                $out[]='bash: cd: '.($arg===''?'~':$arg).': No such file or directory';$exit=1;
            }else{
                $_SESSION['fm_terminal_previous_dir']=$this->currentDir;
                $this->currentDir=$resolved;$_SESSION['fm_terminal_dir']=$resolved;
            }
        }else{
            if(!function_exists('exec')){
                return['output'=>'Terminal is unavailable: PHP exec() is disabled by the hosting provider. Enable exec in disable_functions or use the hosting control panel terminal.','exit'=>127,'ms'=>0,'cwd'=>$this->currentDir,'prompt'=>$this->getTerminalPromptPath(),'shell'=>'unavailable'];
            }
            $cwd=escapeshellarg($this->currentDir);
            /* Assistant Agent commands are complete shell scripts. Prefer
               bash when the host provides it because provider-generated
               scripts commonly use bash redirections, arrays, and heredocs.
               Falling back to sh keeps the terminal portable on minimal
               shared-hosting systems. */
            $shellBin='/bin/sh';
            foreach(['/bin/bash','/usr/bin/bash'] as $candidate){
                if(is_executable($candidate)){$shellBin=$candidate;break;}
            }
            $timeoutBin='';
            foreach(['/usr/bin/timeout','/bin/timeout'] as $candidate)if(is_executable($candidate)){$timeoutBin=$candidate;break;}
            $shellCommand=escapeshellarg($shellBin).' -lc '.escapeshellarg($cmd);
            $run=$timeoutBin!==''?$timeoutBin.' 120s '.$shellCommand:$shellCommand;
            exec("cd $cwd && $run 2>&1",$out,$exit);
        }
        $this->log('terminal',$cmd);
        return['output'=>implode("\n",$out),'exit'=>$exit,'ms'=>round((microtime(true)-$t)*1000),'cwd'=>$this->currentDir,'prompt'=>$this->getTerminalPromptPath(),'shell'=>$shellBin];
    }

    /* Autocomplete */
    public function autocomplete($prefix){
        $items=@scandir($this->currentDir);if(!$items)return[];
        $res=[];$p=basename($prefix);
        foreach($items as $i){if($i==='.'||$i==='..')continue;if($p===''||stripos($i,$p)===0)$res[]=$i.(is_dir($this->currentDir.'/'.$i)?'/':'');}
        return array_slice($res,0,12);
    }

    /* Handle request */
    public function handle(){
        if($_SERVER['REQUEST_METHOD']!=='POST')return;
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){$this->addMsg('Security error.','danger');return;}
        $a=isset($_POST['action'])?$_POST['action']:'';
        $wA=['upload','upload_chunk','create_folder','create_file','delete','rename','save_edit','bypass_perms','bulk_delete','bulk_copy','bulk_move','zip_create','zip_extract','restore_trash','trash_perm','trash_empty','duplicate','tar_create','tar_extract','clear_log','batch_rename','create_symlink','chmod_item','create_share','revoke_share','backup_dir','clear_errlog','delete_abs','bulk_chmod','copy_clipboard','cut_clipboard','paste_clipboard','chown_item','set_tag','remove_tag','remote_download','ssh_install','ssh_create_user','ssh_delete_user','ssh_update_user','cms_create_user','cms_delete_user','cms_update_role','cms_change_pass','cms_update_visibility','cms_toggle_plugin','cms_delete_plugin','cms_toggle_extension','cms_maintenance_toggle','wp_core_update'];
        if($this->readonly&&in_array($a,$wA)){$this->addMsg('Read-only account.','danger');return;}
        /* the permission set is read from the account file on every request,
           so a change made in MFM Admin applies to sessions already open */
        if(in_array($a,$wA,true)&&function_exists('fm_mfm_op_perm')){
            $mfaNeed=fm_mfm_op_perm($a);
            if($mfaNeed!==''&&!fm_can($mfaNeed)){$this->addMsg('This account may not '.strtolower(fm_mfm_perm_name($mfaNeed)).'. An administrator can grant it in MFM Admin.','danger');return;}
        }
        switch($a){
            case 'upload':         $this->upload();break;
            case 'upload_chunk':   $this->uploadChunk();break;
            case 'create_folder':  $this->mkDir();break;
            case 'create_file':    $this->mkFile();break;
            case 'delete':         $this->delItem();break;
            case 'rename':         $this->renItem();break;
            case 'save_edit':      $this->saveFile();break;
            case 'bypass_perms':   $this->bypassPerms();break;
            case 'go_to_path':     $this->goPath();break;
            case 'bulk_delete':    $this->bulkDel();break;
            case 'bulk_copy':      $this->bulkCopyMove(false);break;
            case 'bulk_move':      $this->bulkCopyMove(true);break;
            case 'zip_create':     $this->zipCreate();break;
            case 'zip_extract':    $this->zipExtract();break;
            case 'restore_trash':  $this->restoreTrash(isset($_POST['trash_id'])?$_POST['trash_id']:'');break;
            case 'trash_perm':     $this->permDelTrash(isset($_POST['trash_id'])?$_POST['trash_id']:'');break;
            case 'trash_empty':    $this->emptyTrash();break;
            case 'duplicate':      $this->dupFile();break;
            case 'tar_create':     $this->tarCreate();break;
            case 'tar_extract':    $this->tarExtract();break;
            case 'clear_log':      $this->clearLog();break;
            case 'batch_rename':   $this->batchRename();break;
            case 'create_symlink': $this->mkSymlink();break;
            case 'chmod_item':     $this->chmodItem();break;
            case 'create_share':   $this->createShare();break;
