    private function goPath(){$p=isset($_POST['path'])?trim($_POST['path']):'';if($p&&is_dir($p)){header("Location: ?dir=".urlencode($p));exit;}$this->addMsg('Invalid path.','danger');}

    /* ── Upload security helpers ── */

    /** Returns true if the temp file is a PHP file encrypted/obfuscated by a
     *  known encoder (IonCube, Zend Guard, SourceGuardian, eval+base64, etc.).
     *  Reads only the first 8 KB so it's fast on every upload. */
    private function isEncryptedPhp($tmpPath){
        $s=@file_get_contents($tmpPath,false,null,0,8192);
        if($s===false)return false;
        // ── Known encoder headers ──
        if(preg_match('/IonCube|IONCUBE_LOADER|ionCube Loader/i',$s))return true;
        if(preg_match('/Zend\s+Guard|@_ZEND_GUARD|zend_loader/i',$s)||substr(ltrim($s),0,10)==='<?php //00')return true;
        if(preg_match('/sg_load\s*\(|SourceGuardian/i',$s))return true;
        if(preg_match('/Obfuscator|phpjm\.net|phpxz\.net|NuSphere|NuCoder/i',$s))return true;
        // ── eval + decode combos (most common) ──
        if(preg_match('/\beval\s*\(\s*(base64_decode|gzinflate|gzuncompress|gzdecode|str_rot13|rawurldecode|hex2bin)\s*\(/i',$s))return true;
        if(preg_match('/@eval\s*\([^)]*?(base64_decode|gzinflate)\s*\(/is',$s))return true;
        // ── preg_replace /e (code execution via regex) ──
        if(preg_match('/preg_replace\s*\(\s*([\'"])[^\'"]+\/e\1/i',$s))return true;
        // ── Create-function obfuscation ──
        if(preg_match('/create_function\s*\(\s*[\'"][\'"],\s*(base64_decode|gzinflate)/i',$s))return true;
        // ── Large base64 blob that decodes to PHP ──
        if(preg_match('/[\'"]([A-Za-z0-9+\/]{500,}={0,2})[\'"]/',$s,$m)){
            $dec=@base64_decode($m[1],true);
            if($dec&&(strpos($dec,'<?php')!==false||strpos($dec,'eval(')!==false))return true;
        }
        // ── High density of hex escape sequences ──
        if(preg_match_all('/\\\\x[0-9a-fA-F]{2}/',$s,$hx)&&count($hx[0])>80&&strlen($s)>300)return true;
        return false;
    }

    /** Scores a PHP file for file-manager / web-shell indicators.
     *  Returns true when the combination of indicators is strong enough. */
    private function isWebShellOrFileMgr($tmpPath){
        $c=@file_get_contents($tmpPath,false,null,0,131072);
        if($c===false)return false;
        $score=0;
        if(preg_match('/\bscandir\s*\(/',$c))     $score+=2;
        if(preg_match('/\bopendir\s*\(/',$c))      $score+=2;
        if(preg_match('/\bglob\s*\(/',$c))         $score+=2;
        if(preg_match('/\b(shell_exec|system|passthru|proc_open|popen)\s*\(/',$c))$score+=3;
        if(preg_match('/\bexec\s*\(/',$c))         $score+=2;
        if(preg_match('/\bmove_uploaded_file\s*\(/',$c))$score+=3;
        if(preg_match('/\bfile_put_contents\s*\(/',$c))$score+=1;
        if(preg_match('/\$_(FILES)\s*\[/',$c))     $score+=2;
        if(preg_match('/\$_(POST|GET|REQUEST)\s*\[/',$c))$score+=1;
        if(preg_match('/\bchmod\s*\(/',$c))        $score+=1;
        if(preg_match('/\bReadDir|FilesMan|c99shell|r57shell|WSO|wso_find|b374k/i',$c))$score+=5;
        return $score>=6;
    }

    /** Injects a security layer into an uploaded file manager so it cannot
     *  see this file manager's own files or its Guardian support files.
     *  Uses output-buffering + scandir/glob wrappers - safe for all common
     *  single-file PHP managers. Returns true on success. */
    private function neuterFileMgr($filePath,$origName){
        $content=@file_get_contents($filePath);
        if($content===false||strlen($content)<20)return false;

        $myName=basename(__FILE__);
        // Files that must be hidden from any other file manager
        // launch.php is the new launcher name (hidden dir); include old webroot name too for legacy
        $hidden=json_encode(array_unique([$myName,'.fm_guardian_launch.php','.guardian-restore.php','.user.ini','launch.php',
            '.guardian_boot','.guardian_watchdog_attempt','.login_attempts.json','.htaccess']),JSON_UNESCAPED_UNICODE);

        // Security layer code injected right after <?php
        $inject=
'if(!defined(\'__FGS__\')){define(\'__FGS__\',1);'.
'$__fgh='.($hidden).';'.
'function __fgs($p,$o=SCANDIR_SORT_ASCENDING){global $__fgh;$r=@\scandir($p,$o);'.
'if(!is_array($r))return $r;'.
'return array_values(array_filter($r,function($v)use($__fgh){'.
'$b=basename((string)$v);'.
'return!in_array($b,$__fgh)&&!preg_match(\'/^\.fg_[0-9a-f]+$/\',$b);'.
'}));}'.
'function __fgg($p,$f=0){global $__fgh;$r=@\glob($p,$f);'.
'if(!is_array($r))return $r;'.
'return array_values(array_filter($r,function($v)use($__fgh){'.
'$b=basename((string)$v);'.
'return!in_array($b,$__fgh)&&!preg_match(\'/^\.fg_[0-9a-f]+$/\',$b);'.
'}));}'.
'@ob_start(function($b){global $__fgh;'.
'foreach($__fgh as $f){$e=htmlspecialchars($f,ENT_QUOTES);$u=urlencode($f);'.
'$b=str_replace([$f,$e,$u,rawurlencode($f),addslashes($f)],\'\',$b);}return $b;});}';

        // Insert right after <?php opening tag
        if(preg_match('/^<\?php\b/i',ltrim($content),$m,PREG_OFFSET_CAPTURE)){
            $pos=strpos($content,'<?php');
            $insert_at=$pos+5;
        } elseif(($pos=strpos($content,'<?'))!==false){
            $insert_at=$pos+2;
        } else {
            return false; // not a PHP file we can safely patch
        }
        $content=substr_replace($content,"\n".$inject,$insert_at,0);

        // Redirect scandir() and glob() calls to our safe wrappers
        // Negative lookbehind ensures we skip strings and already-prefixed calls
        $content=preg_replace('/(?<![\'"`_a-zA-Z0-9\\\\])\bscandir\s*\(/',    '__fgs(',  $content);
        $content=preg_replace('/(?<![\'"`_a-zA-Z0-9\\\\])\bglob\s*\(/',       '__fgg(',  $content);

        if(@file_put_contents($filePath,$content)===false)return false;
        $this->log('upload_neutered',$origName);
        return true;
    }

    private function uploadJson($payload,$status=200){
        http_response_code((int)$status);
        header('Content-Type: application/json; charset=utf-8');
        header('Cache-Control: no-store');
        echo json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);
        exit;
    }
    private function uploadErrorText($error){
        $messages=[
            UPLOAD_ERR_INI_SIZE=>'The file part exceeded upload_max_filesize ('.ini_get('upload_max_filesize').').',
            UPLOAD_ERR_FORM_SIZE=>'The file exceeded the form upload limit.',
            UPLOAD_ERR_PARTIAL=>'The file was only partially received. Please try again.',
            UPLOAD_ERR_NO_FILE=>'No file data was received.',
            UPLOAD_ERR_NO_TMP_DIR=>'The server has no temporary upload directory.',
            UPLOAD_ERR_CANT_WRITE=>'The server could not write the uploaded data.',
            UPLOAD_ERR_EXTENSION=>'A PHP extension stopped the upload.'
        ];
        return$messages[(int)$error]??'The upload failed (PHP upload error '.(int)$error.').';
    }
    private function stagedUploadPath(){
        $base=rtrim((string)sys_get_temp_dir(),DIRECTORY_SEPARATOR);
        if($base===''||!is_dir($base)||!is_writable($base))return false;
        $dir=$base.DIRECTORY_SEPARATOR.'mfm-upload-'.hash('sha256',session_id().'|'.$this->currentDir);
        if(!is_dir($dir)&&!@mkdir($dir,0700,true))return false;
        @chmod($dir,0700);
        return is_dir($dir)&&is_writable($dir)?$dir:false;
    }
    private function commitStagedUpload($source,$dest,$expectedSize){
        if(is_link($dest)||(!is_file($source)&&!is_readable($source)))return false;
        $sourceHash=@hash_file('sha256',$source);if($sourceHash===false)return false;
        if(@rename($source,$dest))return true;
        $targetTemp=@tempnam($this->currentDir,'.fm-upload-');
        if($targetTemp!==false){
            if(@copy($source,$targetTemp)&&(int)@filesize($targetTemp)===(int)$expectedSize&&hash_equals($sourceHash,(string)@hash_file('sha256',$targetTemp))){
                if(@rename($targetTemp,$dest))return true;
            }
            @unlink($targetTemp);
        }
        $backup=false;$backupPath='';$backupHash='';
        if(file_exists($dest)){
            if(!is_file($dest))return false;
            $backupHash=@hash_file('sha256',$dest);if($backupHash===false)return false;
            $backupPath=@tempnam((string)sys_get_temp_dir(),'mfm-upload-backup-');
            if(!$backupPath||!@copy($dest,$backupPath)||!hash_equals($backupHash,(string)@hash_file('sha256',$backupPath))){if($backupPath)@unlink($backupPath);return false;}
            $backup=true;
        }
        $restore=function()use($backup,$backupPath,$backupHash,$dest){
            if(!$backup){@unlink($dest);return true;}
            if(!@copy($backupPath,$dest))return false;
            return hash_equals($backupHash,(string)@hash_file('sha256',$dest));
        };
        $in=@fopen($source,'rb');$out=@fopen($dest,'wb');
        if(!$in||!$out){if($in)fclose($in);if($out)fclose($out);$restore();if($backupPath)@unlink($backupPath);return false;}
        $copied=@stream_copy_to_stream($in,$out);@fflush($out);fclose($in);fclose($out);
        $ok=$copied!==false&&(int)$copied===(int)$expectedSize&&(int)@filesize($dest)===(int)$expectedSize&&hash_equals($sourceHash,(string)@hash_file('sha256',$dest));
        if(!$ok)$restore();
        if($backupPath)@unlink($backupPath);
        return$ok;
    }
    private function uploadChunk(){
        $id=(string)($_POST['upload_id']??'');$part=(int)($_POST['part']??-1);$parts=(int)($_POST['parts']??0);
        $chunkBytes=(int)($_POST['chunk_bytes']??0);$total=(int)($_POST['total_size']??-1);
        $name=str_replace('\\','/',(string)($_POST['upload_name']??''));$name=basename($name);
        if(!preg_match('/^[a-f0-9]{32}$/D',$id)||$name===''||$name==='.'||$name==='..'||preg_match('/[\x00-\x1F\x7F]/',$name))
            $this->uploadJson(['ok'=>false,'error'=>'Invalid upload name or upload id.'],400);
        if((!is_writable($this->currentDir)&&!$this->privSiteFor($this->currentDir,$this->privForced()!==null))||!$this->pathAllowed($this->currentDir))
            $this->uploadJson(['ok'=>false,'error'=>'This folder is not writable.'],403);
        if(is_link($this->currentDir.'/'.$name)||$this->isSelf($name)||$this->isProtectedItem($name,$this->currentDir.'/'.$name))
            $this->uploadJson(['ok'=>false,'error'=>'This file name is protected and cannot be replaced.'],403);
        if($total<0||$total>4294967296||$chunkBytes<8192||$chunkBytes>1048576||$parts<1||$parts>65535||$parts!==max(1,(int)ceil($total/$chunkBytes))||$part<0||$part>=$parts)
            $this->uploadJson(['ok'=>false,'error'=>'Invalid upload size or chunk sequence.'],400);
        $file=$_FILES['chunk']??null;
        if(!$file||!is_array($file)||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)
            $this->uploadJson(['ok'=>false,'error'=>$this->uploadErrorText($file['error']??UPLOAD_ERR_NO_FILE)],413);
        $expected=min($chunkBytes,max(0,$total-$part*$chunkBytes));
        if((int)($file['size']??-1)!==$expected||!is_uploaded_file((string)($file['tmp_name']??'')))
            $this->uploadJson(['ok'=>false,'error'=>'A chunk was incomplete or did not match the expected size. Please retry the upload.'],400);
        $stage=$this->stagedUploadPath();
        if($stage===false)$this->uploadJson(['ok'=>false,'error'=>'The server temporary directory is not writable.'],500);
        if($part===0){$oldFiles=@scandir($stage);if(is_array($oldFiles)&&count($oldFiles)<10000)foreach($oldFiles as $old){if($old==='.'||$old==='..')continue;$oldPath=$stage.DIRECTORY_SEPARATOR.$old;if(is_file($oldPath)&&@filemtime($oldPath)<time()-172800)@unlink($oldPath);}}
        $metaPath=$stage.DIRECTORY_SEPARATOR.$id.'.json';
        $meta=is_file($metaPath)?json_decode((string)@file_get_contents($metaPath),true):null;
        if($part===0){
            $existing=is_file($this->currentDir.'/'.$name)?(int)@filesize($this->currentDir.'/'.$name):0;
            if(!$this->quotaAllows(max(0,$total-$existing))){@unlink($metaPath);$this->uploadJson(['ok'=>false,'error'=>'Storage quota exceeded. The file was not uploaded.'],413);}
            $free=@disk_free_space($this->currentDir);
            if($free!==false&&$total>$free){@unlink($metaPath);$this->uploadJson(['ok'=>false,'error'=>'Not enough disk space for this file.'],413);}
            $meta=['name'=>$name,'size'=>$total,'chunk_bytes'=>$chunkBytes,'parts'=>$parts,'dir'=>$this->currentDir,'created'=>time()];
            if(@file_put_contents($metaPath,json_encode($meta),LOCK_EX)===false)$this->uploadJson(['ok'=>false,'error'=>'The server could not prepare temporary upload storage.'],500);
        }elseif(!is_array($meta)){
            $this->uploadJson(['ok'=>false,'error'=>'The upload session expired. Please start again.'],400);
        }
        if(!is_array($meta)||($meta['name']??'')!==$name||(int)($meta['size']??-1)!==$total||(int)($meta['chunk_bytes']??0)!==$chunkBytes||(int)($meta['parts']??0)!==$parts||($meta['dir']??'')!==$this->currentDir){
            $this->uploadJson(['ok'=>false,'error'=>'The upload details changed mid-transfer. Please start again.'],400);
        }
        $partPath=$stage.DIRECTORY_SEPARATOR.$id.'.'.$part.'.part';
        if(!@move_uploaded_file((string)$file['tmp_name'],$partPath))
            $this->uploadJson(['ok'=>false,'error'=>'The server could not store an upload chunk.'],500);
        if($part!==$parts-1)$this->uploadJson(['ok'=>true,'part'=>$part]);
        $assembled=@tempnam($this->currentDir,'.fm-upload-');
        if($assembled===false)$assembled=@tempnam($stage,'.fm-upload-');   // folder belongs to the web server
        if($assembled===false)$this->uploadJson(['ok'=>false,'error'=>'The server could not assemble the uploaded file.'],500);
        $out=@fopen($assembled,'wb');$written=0;
        if(!$out){@unlink($assembled);$this->uploadJson(['ok'=>false,'error'=>'The server could not assemble the uploaded file.'],500);}
        for($i=0;$i<$parts;$i++){
            $piece=$stage.DIRECTORY_SEPARATOR.$id.'.'.$i.'.part';$pieceSize=min($chunkBytes,max(0,$total-$i*$chunkBytes));
            if(!is_file($piece)||(int)@filesize($piece)!==$pieceSize){fclose($out);@unlink($assembled);$this->uploadJson(['ok'=>false,'error'=>'An upload chunk is missing. Please retry.'],400);}
            $in=@fopen($piece,'rb');if(!$in){fclose($out);@unlink($assembled);$this->uploadJson(['ok'=>false,'error'=>'A stored upload chunk could not be read.'],500);}
            $copied=@stream_copy_to_stream($in,$out);fclose($in);if($copied===false){fclose($out);@unlink($assembled);$this->uploadJson(['ok'=>false,'error'=>'The uploaded file could not be assembled.'],500);}$written+=$copied;
        }
        @fflush($out);fclose($out);
        if($written!==$total||(int)@filesize($assembled)!==$total){@unlink($assembled);$this->uploadJson(['ok'=>false,'error'=>'The assembled file size did not match the original.'],400);}
        $ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$phpExts=['php','php3','php4','php5','php7','php8','phtml','phar','shtml','cgi'];$isPhp=in_array($ext,$phpExts,true);
        if($isPhp&&$this->isEncryptedPhp($assembled)){@unlink($assembled);$this->uploadJson(['ok'=>false,'error'=>'Encrypted or obfuscated PHP files are not allowed.'],403);}
        $existing=is_file($this->currentDir.'/'.$name)?(int)@filesize($this->currentDir.'/'.$name):0;
        if(!$this->quotaAllows(max(0,$total-$existing)-$total)){@unlink($assembled);$this->uploadJson(['ok'=>false,'error'=>'Storage quota exceeded. The file was not uploaded.'],413);}
        $dest=$this->currentDir.'/'.$name;
        $forced=$this->privForced();
        $staged=($forced&&$this->privSiteFor($dest,true))?false:$this->commitStagedUpload($assembled,$dest,$total);
        if(!$staged){
            if(!$this->privSendFile($assembled,$dest,$why)){
                @unlink($assembled);
                $this->uploadJson(['ok'=>false,'error'=>'The file could not be written to this folder. '.($why?:'Check folder permissions and free space.')],500);
            }
        }
        @unlink($assembled);
        if($isPhp&&$this->isWebShellOrFileMgr($dest)){$this->neuterFileMgr($dest,$name);$this->threatsWhitelistFile($dest);}
        else $this->threatsWhitelistFile($dest);
        $this->log('upload',$name);
        for($i=0;$i<$parts;$i++)@unlink($stage.DIRECTORY_SEPARATOR.$id.'.'.$i.'.part');
        @unlink($metaPath);
        $this->uploadJson(['ok'=>true,'name'=>$name]);
    }

    private function upload(){
        if(!isset($_FILES['file']))return;
        $phpExts=['php','php3','php4','php5','php7','php8','phtml','phar','shtml','cgi'];
        $names=$_FILES['file']['name'];

        $doOne=function($tmpPath,$name) use($phpExts){
            $ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));
            $isPhp=in_array($ext,$phpExts);
            // ── Block encrypted / obfuscated PHP files ──
            if($isPhp&&$this->isEncryptedPhp($tmpPath)){
                @unlink($tmpPath);
                $this->addMsg("Blocked: \"$name\" - encrypted/obfuscated PHP files are not allowed.",'danger');
                $this->log('upload_blocked_encrypted',$name);
                return false;
            }
            $dest=$this->currentDir.'/'.basename($name);
            if($this->isSelf(basename($dest))||$this->isProtectedItem(basename($dest),$dest)){
                @unlink($tmpPath);
                $this->addMsg("Access denied: \"$name\" is a protected manager file.",'danger');
                return false;
            }
            $existing=file_exists($dest)?$this->itemBytes($dest):0;
            $incoming=(int)@filesize($tmpPath);
            if(!$this->quotaAllows(max(0,$incoming-$existing))){
                @unlink($tmpPath);
                $this->addMsg("Quota exceeded: \"$name\" was not uploaded.",'danger');
                return false;
            }
            /* In a forced CMS mode the site writes the file itself; otherwise the
               manager moves it and only falls back when the OS refuses. */
            $forced=$this->privForced();
            if($forced&&$this->privSiteFor($dest,true))$viaSite=null;   // decide below
            else $viaSite=move_uploaded_file($tmpPath,$dest)?false:null;
            if($viaSite===null){
                if($this->privSendFile($tmpPath,$dest,$why)){
                    @unlink($tmpPath);
                    $viaSite=true;
                }else{
                    $this->addMsg("Upload failed: $name - ".$why,'danger');
                    return false;
                }
            }
            // ── Detect and neuter uploaded file managers / web shells ──
            if($isPhp&&$this->isWebShellOrFileMgr($dest)){
                $this->neuterFileMgr($dest,basename($name));
                $this->threatsWhitelistFile($dest);
                $this->addMsg("Uploaded &amp; secured and whitelisted: $name".($viaSite?' - through the site ('.$this->privWho($dest).')':''),'warning');
            } else {
                $this->threatsWhitelistFile($dest);
                $this->addMsg("Uploaded and whitelisted: $name".($viaSite?' - through the site ('.$this->privWho($dest).')':''),'success');
            }
            $this->log('upload',$name);
            return true;
        };

        if(is_array($names)){
            $ok=0;$fail=0;
            foreach($names as $i=>$n){
                if($_FILES['file']['error'][$i]!==UPLOAD_ERR_OK){$fail++;$this->addMsg($this->uploadErrorText($_FILES['file']['error'][$i]).' ('.$n.')','danger');continue;}
                if($doOne($_FILES['file']['tmp_name'][$i],basename($n)))$ok++;else $fail++;
            }
            if($ok>0)$this->addMsg("$ok file(s) processed.".($fail?" $fail failed.":''),'success');
            elseif($fail>0)$this->addMsg("$fail upload(s) failed.",'danger');
        } else {
            if($_FILES['file']['error']!==UPLOAD_ERR_OK){$this->addMsg($this->uploadErrorText($_FILES['file']['error']).' ('.$names.').','danger');return;}
            $doOne($_FILES['file']['tmp_name'],basename($names));
        }
    }
    private function mkDir(){$n=basename(trim(isset($_POST['folder_name'])?$_POST['folder_name']:'')); if(!$n)return;if(!$this->quotaAllows(0)){$this->addMsg('Quota exceeded.','danger');return;}$p=$this->currentDir.'/'.$n;
        $res=$this->runOp('mkdir',['path'=>$p],$p,function()use($p){return!file_exists($p)&&@mkdir($p);});
        if(!empty($res['ok'])){$this->log('mkdir',$n.($res['via']==='site'?' (site)':''));$this->addMsg("Folder created: $n".$this->viaNote($res,$p),'success');}
        else $this->addMsg('Could not create folder. '.$res['why'],'danger');}
    private function mkFile(){$n=basename(trim(isset($_POST['file_name'])?$_POST['file_name']:'')); if(!$n)return;if(!$this->quotaAllows(0)){$this->addMsg('Quota exceeded.','danger');return;}$p=$this->currentDir.'/'.$n;if(file_exists($p)){$this->addMsg('File already exists.','danger');return;}
        $res=$this->runOp('touch',['path'=>$p],$p,function()use($p){return@file_put_contents($p,'')!==false;});
        if(!empty($res['ok'])){$this->log('create',$n.($res['via']==='site'?' (site)':''));$this->addMsg("Created: $n".$this->viaNote($res,$p),'success');header("Location: ?edit=".urlencode($n)."&dir=".urlencode($this->currentDir));exit;}
        $this->addMsg('Failed to create file. '.$res['why'],'danger');}
    private function delItem(){$n=basename(isset($_POST['item_name'])?$_POST['item_name']:'');if(!$n||$this->isSelf($n)||$this->isProtectedItem($n,$this->currentDir.'/'.$n)){$this->addMsg('Access denied.','danger');return;}$p=$this->currentDir.'/'.$n;
        /* The trash belongs to the manager, so a file it may not move is deleted
           outright by the site instead of being parked in the manager's trash. */
        $res=$this->runOp('delete',['path'=>$p],$p,function()use($p){return$this->moveToTrash($p,$this->currentDir);});
        if(!empty($res['ok'])){
            if($res['via']==='local'){$this->log('trash',$n);$this->addMsg("Trashed: $n",'warning');}
            else{$this->log('delete',$n.' (site)');$this->addMsg("Deleted: $n".$this->viaNote($res,$p),'warning');}
        }
        else $this->addMsg('Delete failed. '.$res['why'],'danger');}
    private function renItem(){
        $o=basename(isset($_POST['old_name'])?$_POST['old_name']:'');$nw=basename(isset($_POST['new_name'])?$_POST['new_name']:'');
        if(!$o||!$nw||$o===$nw)return;
        if($this->isSelf($o)||$this->isProtectedItem($o,$this->currentDir.'/'.$o)){$this->addMsg('Access denied.','danger');return;}
        if($this->isProtectedItem($nw,$this->currentDir.'/'.$nw)){$this->addMsg('Access denied.','danger');return;}
        $po=$this->currentDir.'/'.$o;$pn=$this->currentDir.'/'.$nw;
        $res=(file_exists($po)&&!file_exists($pn))
            ?$this->runOp('rename',['path'=>$po,'to'=>$pn],$po,function()use($po,$pn){return@rename($po,$pn);})
            :['ok'=>false,'via'=>'none','why'=>'The item is missing or the new name is already taken.'];
        if(!empty($res['ok'])){
            $detailsMoved=true;
            if(in_array(strtolower(pathinfo($o,PATHINFO_EXTENSION)),fm_audio_supported_extensions(),true)&&in_array(strtolower(pathinfo($nw,PATHINFO_EXTENSION)),fm_audio_supported_extensions(),true)){
                $detailsMoved=fm_audio_rename_override($this->currentDir,$o,$nw);
            }
            $this->log('rename',"$o → $nw".($res['via']==='site'?' (site)':''));
            $msg=$detailsMoved?'Renamed.':'Renamed, but song details could not be transferred.';
            $this->addMsg($msg.($res['via']==='site'?" $o → $nw".$this->viaNote($res,$po):''),$detailsMoved?'success':'warning');
        }else $this->addMsg('Rename failed. '.$res['why'],'danger');
    }
    /* ── Privileged fallback ──────────────────────────────────────────────────
       A file the manager cannot write is retried through the site's own web
       server: a short-lived bridge script is dropped into the CMS folder and
       called over HTTP, so the operation runs under the account that owns the
       site's files (www-data on a normal host). This is only ever a *fallback*
       - the normal local call is always attempted first, and this runs only
       when it failed. Guards on the bridge: random token header, 15-minute
       lifetime, self-delete when expired, and every path must stay inside the
       site root. */

    /* Which account performed a privileged operation (for the message). */
    private function privWho($path){
        $site=$this->privSiteFor($path);
        return $site?($site['type']==='wordpress'?'WordPress':'Joomla'):'the site';
    }

    /* ── Privilege mode ───────────────────────────────────────────────────────
       Which identity performs file changes:
         server    - this server account only (how the manager always behaved)
         auto      - this account first, the site only when the OS refuses (default)
         wordpress - the WordPress installation performs them
         joomla    - the Joomla installation performs them
       The choice is stored in a small JSON file next to the manager so it
       survives sessions and restarts. */
    const PRIV_MODES=['server','auto','wordpress','joomla'];
    private $privModeCache=null;
    private function privModeFile(){return __DIR__.'/.fm_privmode.json';}
    public function privMode(){
        if($this->privModeCache!==null)return $this->privModeCache;
        $m='auto';
        $f=$this->privModeFile();
        if(is_file($f)){
            $j=json_decode((string)@file_get_contents($f),true);
            if(is_array($j)&&in_array($j['mode']??'',self::PRIV_MODES,true))$m=$j['mode'];
        }
        return $this->privModeCache=$m;
    }
    public function privModeSet($mode){
        $mode=(string)$mode;
        if(!in_array($mode,self::PRIV_MODES,true))return['error'=>'Unknown privilege mode.'];
        $f=$this->privModeFile();
        if(@file_put_contents($f,json_encode(['mode'=>$mode,'set_at'=>date('c'),'by'=>(string)($_SESSION['fm_user']??'')],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX)===false)
            return['error'=>'Could not save the mode: '.$f.' is not writable.'];
        @chmod($f,0600);
        $this->privModeCache=$mode;
        $this->log('priv_mode',$mode);
        return['ok'=>true,'mode'=>$mode];
    }
    private function privModeLabel($mode=null){
        $mode=$mode?:$this->privMode();
        $map=['server'=>'Server account only','auto'=>'Automatic','wordpress'=>'WordPress','joomla'=>'Joomla'];
        return $map[$mode]??$mode;
    }
    private function privForced(){return in_array($this->privMode(),['wordpress','joomla'],true)?$this->privMode():null;}

    /* Performs one file change according to the current mode.
       $local is the manager's own attempt; it is used only in server/auto mode,
       or when no CMS covers the path at all. */
    private function runOp($kind,$args,$path,callable $local){
        $mode=$this->privMode();
        $forced=$this->privForced();
        $site=$this->privSiteFor($path,$forced!==null);
        if($forced&&$site){
            if($site['type']!==$mode){
                $need=$site['type']==='wordpress'?'WordPress':'Joomla';
                return['ok'=>false,'via'=>'none','why'=>'This path belongs to the '.$need.' installation, but the manager is in '.$this->privModeLabel().' mode. Switch the privilege mode to '.$need.' or to Automatic.'];
            }
            $r=$this->privOp($kind,$args,$path,$mode);
            if(!empty($r['ok']))return['ok'=>true,'via'=>'site'];
            return['ok'=>false,'via'=>'none','why'=>$r['error']??'The site could not complete the operation.'];
        }
        try{if($local())return['ok'=>true,'via'=>'local'];}catch(\Throwable $e){$why=$e->getMessage();}
        if($mode==='server')
            return['ok'=>false,'via'=>'none','why'=>'The server account of the manager is not allowed to do this, and the privilege mode is set to “Server account only”.'];
        $r=$this->privOp($kind,$args,$path);
        if(!empty($r['ok']))return['ok'=>true,'via'=>'site'];
        return['ok'=>false,'via'=>'none','why'=>$r['error']??'The operation failed.'];
    }
    /* Message suffix that tells the operator which identity acted. */
    private function viaNote($res,$path){
        if(($res['via']??'')!=='site')return'';
        return' - through the site ('.$this->privWho($path).')';
    }
    /* Reads a file the manager cannot read, through the site (editor fallback). */
    private function privReadFile($path,$maxBytes=16777216){
        if($this->privMode()==='server')return null;
        $forced=$this->privForced();
        $site=$this->privSiteFor($path,$forced!==null);
        if(!$site)return null;
        if($forced&&$site['type']!==$forced)return null;
        $size=@filesize($path);
        if($size!==false&&$size>$maxBytes)return null;
        $r=$this->privOp('read',['path'=>$path],$path,$forced);
        if(empty($r['ok'])||!isset($r['data']))return null;
        $data=base64_decode((string)$r['data'],true);
        return $data===false?null:$data;
    }
    /* Sends a local file to the site in 4 MB slices, so memory stays bounded
       for large uploads. */
    private function privSendFile($src,$dest,&$why){
        $fp=@fopen($src,'rb');
        if(!$fp){$why='The source file could not be read.';return false;}
        $first=true;
        while(true){
            $buf=@fread($fp,4*1024*1024);
            if($buf===false){fclose($fp);$why='The source file could not be read.';return false;}
            $eof=feof($fp);
            if($buf===''&&$eof)break;
            $r=$this->privOp('write',['path'=>$dest,'data'=>base64_encode($buf),'b64'=>1,'append'=>!$first],$dest,$this->privForced());
            if(empty($r['ok'])){fclose($fp);$why=$r['error']??'The site refused the write.';return false;}
            $first=false;
            if($eof)break;
        }
        fclose($fp);
        if($first){
            $r=$this->privOp('write',['path'=>$dest,'data'=>'','b64'=>1,'append'=>false],$dest,$this->privForced());
            if(empty($r['ok'])){$why=$r['error']??'The site refused the write.';return false;}
        }
        return true;
    }
    /* ── Ownership ────────────────────────────────────────────────────────────
       fileowner() only gives a uid, so the name, the home directory and the
       group are resolved here. "mine" means the account running this manager,
       which is what the file list colours differently. */
    private $ownNameCache=[];
    public function uidName($uid){
        $uid=(int)$uid;
        if(isset($this->ownNameCache[$uid]))return $this->ownNameCache[$uid];
        $u=function_exists('posix_getpwuid')?@posix_getpwuid($uid):null;
        return $this->ownNameCache[$uid]=($u?$u['name']:'#'.$uid);
    }
    public function managerAccount(){
        static $name=null;
        if($name!==null)return $name;
        if(function_exists('posix_geteuid')){$u=@posix_getpwuid(@posix_geteuid());if($u)return $name=$u['name'];}
        $n=function_exists('get_current_user')?@get_current_user():'';
        return $name=($n!==''?$n:'unknown');
    }
    public function pathOwner($path){
        $out=['path'=>(string)$path,'exists'=>@file_exists($path),'owner'=>null,'group'=>null,'home'=>'','uid'=>null,'gid'=>null,'mine'=>false];
        if(!$out['exists'])return $out;
        $uid=@fileowner($path);$gid=@filegroup($path);
        if($uid!==false){$out['uid']=(int)$uid;$out['owner']=$this->uidName($uid);}
        if($gid!==false){
            $out['gid']=(int)$gid;
            $g=function_exists('posix_getgrgid')?@posix_getgrgid($gid):null;
            $out['group']=$g?($g['name']??('#'.$gid)):('#'.$gid);
        }
        if($out['owner']!==null&&function_exists('posix_getpwnam')){
            $pw=@posix_getpwnam($out['owner']);
            if($pw)$out['home']=(string)($pw['dir']??'');
        }
        $out['mine']=($out['owner']!==null&&$out['owner']===$this->managerAccount());
        return $out;
    }
    /* Every account on the machine, with the two that matter flagged. */
    public function systemOwners(){
        $list=[];
        $raw=@file('/etc/passwd',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES);
        if(is_array($raw))foreach($raw as $line){
            $p=explode(':',$line);
            if(count($p)<7)continue;
            $list[]=['name'=>$p[0],'uid'=>(int)$p[2],'gid'=>(int)$p[3],'home'=>$p[5],'shell'=>$p[6]];
        }
        $manager=$this->managerAccount();
        $siteUser=null;
        foreach(['wordpress','joomla'] as $type){
            $cfg=$this->privSiteConfigFor($type);
            if(!$cfg)continue;
            $root=$type==='wordpress'?rtrim($this->wpSiteRoot($cfg),'/'):rtrim(dirname($cfg),'/');
            $ping=$this->privOp('ping',['path'=>$root.'/index.php'],$root.'/index.php',$type);
            if(!empty($ping['ok'])&&!empty($ping['user'])){$siteUser=(string)$ping['user'];break;}
        }
        foreach($list as $i=>$u){
            $list[$i]['is_manager']=($u['name']===$manager);
            $list[$i]['is_site']=($siteUser!==null&&$u['name']===$siteUser);
            $list[$i]['system']=((int)$u['uid']<1000&&(int)$u['uid']!==0);
        }
        return['manager'=>$manager,'site'=>$siteUser,'owners'=>$list];
    }
    /* sudo is only ever tried after both normal routes failed, and only when the
       account may already run sudo without a password. */
    /* a probe, not a verdict: a negative answer is asked again next time,
       because root may be installed a few lines later in the same request */
    private function rootSudoNow(){
        $r = $this->rootExec(['sudo', '-n', '-u', 'root', 'id', '-u'], '', 10);
        return (int)($r['rc'] ?? 1) === 0 && trim((string)($r['out'] ?? '')) === '0';
    }
    private $sudoWhy = '';
    private function sudoAvailable(){
        static $ok=null;
        /* a negative answer is asked again next time: root may be installed a
           few lines later in the same request, and then sudo does answer */
        if($ok===true)return true;
        if(!function_exists('exec'))return $ok=false;
        $disabled=array_map('trim',explode(',',(string)ini_get('disable_functions')));
        if(in_array('exec',$disabled,true))return $ok=false;
        $out=[];$rc=1;
        /* what sudo itself answers is worth keeping: "is not in the sudoers
           file" and "a password is required" are two different situations, and
           only the second one is cured by typing a password */
        @exec('sudo -n true 2>&1',$out,$rc);
        $this->sudoWhy=trim(implode(' ',$out));
        return $ok=($rc===0);
    }
    /* Ownership changes are never allowed on the machine's own files. The
       manager may browse anywhere, but handing /etc to another account would
       break the server, so those locations are refused before any route is
       tried - locally, through the site, or with sudo. */
    private function ownBlocked($path){
        $rp=@realpath($path);
        if($rp===false||$rp==='/')return 'That location cannot be handed to another account.';
        $rp=str_replace('\\','/',$rp);
        $blocked=['/etc','/bin','/sbin','/lib','/lib32','/lib64','/libx32','/usr','/boot','/proc','/sys','/dev','/root','/run','/snap','/var/lib','/var/spool','/var/cache','/var/log'];
        foreach($blocked as $b){
            if($rp===$b||strpos($rp,$b.'/')===0)return $rp.' belongs to the operating system, so its owner was left alone.';
        }
        /* the top-level directories themselves (/home, /tmp, /var, …) */
        $trim=trim($rp,'/');
        if($trim!==''&&strpos($trim,'/')===false)return $rp.' is a system location, so its owner was left alone.';
        if(function_exists('posix_getpwuid')){
            foreach(['wordpress','joomla'] as $type){
                $cfg=$this->privSiteConfigFor($type);
                if(!$cfg)continue;
                $root=$type==='wordpress'?rtrim($this->wpSiteRoot($cfg),'/'):rtrim(dirname($cfg),'/');
                if($root!==''&&($rp===$root||strpos($rp,$root.'/')===0))return '';  /* a site is always fair game */
            }
        }
        return '';
    }
    private function chownOne($path,$owner,$group){
        $block=$this->ownBlocked($path);
        if($block!=='')return['ok'=>false,'tried'=>[$block],'blocked'=>true];
        if($owner!==''){
            $ok=@chown($path,$owner);
            if($group!=='')$ok=@chgrp($path,$group)&&$ok;
            if($ok)return['ok'=>true,'via'=>'local'];
        }elseif($group!==''&&@chgrp($path,$group)){
            return['ok'=>true,'via'=>'local'];
        }
        $tried=['the server account was refused'];
        /* the site itself, exactly like Privilege Mode */
        $args=['path'=>$path];
        if($owner!=='')$args['owner']=$owner;
        if($group!=='')$args['group']=$group;
        $r=$this->privOp('chown',$args,$path);
        if(!empty($r['ok']))return['ok'=>true,'via'=>'site'];
        $tried[]='the site was refused'.(isset($r['error'])?' ('.$r['error'].')':'');
        /* last resort: an already-allowed sudo, never a password prompt */
        if($this->sudoAvailable()){
            $target=$owner!==''?($group!==''?$owner.':'.$group:$owner):(':'.$group);
            $cmd='sudo -n chown '.escapeshellarg($target).' '.escapeshellarg($path).' 2>&1';
            $out=[];$rc=1;
            @exec($cmd,$out,$rc);
            if($rc===0)return['ok'=>true,'via'=>'sudo'];
            $tried[]='sudo was refused'.(isset($out[0])?': '.trim((string)$out[0]):'');
        }
        return['ok'=>false,'tried'=>$tried];
    }
    public function chownPath($path,$owner,$group='',$recursive=false){
        $path=(string)$path;
        if($path===''||!@file_exists($path))return['error'=>'That item does not exist.'];
        $owner=(string)$owner;$group=(string)$group;
        if($owner===''&&$group==='')return['error'=>'Choose an owner or a group.'];
        if($owner!==''&&!preg_match('/^[A-Za-z0-9_.-]{1,32}$/',$owner))return['error'=>'Invalid owner name.'];
        if($group!==''&&!preg_match('/^[A-Za-z0-9_.-]{1,32}$/',$group))return['error'=>'Invalid group name.'];
        $targets=[$path];
        if($recursive&&@is_dir($path)){
            $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($path,RecursiveDirectoryIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);
            foreach($it as $f)$targets[]=$f->getPathname();
        }
        $done=0;$failed=0;$via=[];$error='';
        foreach($targets as $t){
            $r=$this->chownOne($t,$owner,$group);
            if(!empty($r['ok'])){$done++;$via[$r['via']]=($via[$r['via']]??0)+1;}
            else{$failed++;if($error==='')$error=implode('; ',(array)($r['tried']??[]));}
        }
        if($done>0)$this->log('chown',$path.' → '.($owner!==''?$owner:'-').':'.($group!==''?$group:'-').' ('.http_build_query($via,'',' ').')');
        $info=$this->pathOwner($path);
        return[
            'ok'=>$done>0&&$failed===0,
            'path'=>$path,'done'=>$done,'failed'=>$failed,'via'=>$via,
            'owner'=>$info['owner'],'group'=>$info['group'],'home'=>$info['home'],
            'error'=>$failed?($error?:'Some items could not be changed.'):null,
        ];
    }
    /* ?x=owners - list the accounts, report one item's owner, or change it. */
    public function ownersEndpoint($post){
        $act=(string)($post['action']??'list');
        $path='';
        if(!empty($post['path']))$path=(string)$post['path'];
        elseif(!empty($post['item_name']))$path=rtrim($this->currentDir,'/').'/'.basename((string)$post['item_name']);
        if($path!==''){
            $real=@realpath($path);
            if($real!==false)$path=$real;
        }
        if($act==='apply'){
            if($path==='')return['error'=>'No item was selected.'];
            if(!$this->pathAllowed($path))return['error'=>'That path is outside the allowed area.'];
            if($this->isGuardianFile(basename($path),$path))return['error'=>'That file is protected by the manager.'];
            $r=$this->chownPath($path,(string)($post['owner']??''),(string)($post['group']??''),!empty($post['recursive']));
            $r['message']=!empty($r['ok'])
                ? 'Owner of '.basename($path).' is now '.($r['owner']?:$r['group']).' (changed by '.(
                    isset($r['via']['sudo'])?'the server account with sudo'
                    :(isset($r['via']['site'])?'the site':(isset($r['via']['local'])?'the file manager':'someone'))).').'
                : null;
            return$r;
        }
        $sys=$this->systemOwners();
        return[
            'ok'=>true,
            'manager'=>$sys['manager'],
            'site_user'=>$sys['site'],
            'owners'=>$sys['owners'],
            'path'=>$path,
            'current'=>$path!==''?$this->pathOwner($path):null,
            'sudo'=>$this->sudoAvailable(),
            'mode'=>$this->privMode(),
            'mode_label'=>$this->privModeLabel(),
        ];
    }

    /* ── Rooting ──────────────────────────────────────────────────────────────
       One panel for privilege escalation on this host: it catalogues the known
       Linux escalation vulnerabilities (Dirty Frag first, then the rest of the
       family), decides for each one whether this machine is actually exposed,
       and then runs the escalation chain - every route in order, stopping at
       the first one that really yields root.
       It carries no exploit code: exposure is measured from the kernel release,
       the loaded/available modules, the package versions and the mitigations in
       place. The routes it does run are real privileged accesses (an already
       root account, passwordless sudo, sudo with the password you type), and
       the result is a validated root helper so the manager keeps the access. */
    /* Every program this file starts is started from an argument vector, never
       from a shell line: no /bin/sh is involved, so no other language runs, no
       quoting can go wrong and nothing can be injected into a command. */
    private function rootExec($argv, $stdin = '', $timeout = 0){
        return fm_run_argv($argv, $stdin, $timeout);
    }
    /* the uid a /proc/<pid>/status block reports */
    private function rootUidOf($status){
        return preg_match('/^Uid:\s*(\d+)/m', (string)$status, $m) ? (int)$m[1] : -1;
    }
    private function rootVnum($v){
        if(is_array($v))return $v;
        if(preg_match('/(\d+)(?:\.(\d+))?(?:\.(\d+))?/', (string)$v, $m))return[(int)$m[1], (int)($m[2] ?? 0), (int)($m[3] ?? 0)];
        return[0, 0, 0];
    }
    private function rootVlt($a, $b){
        $a = $this->rootVnum($a); $b = $this->rootVnum($b);
        if($a[0] !== $b[0])return $a[0] < $b[0];
        if($a[1] !== $b[1])return $a[1] < $b[1];
        return $a[2] < $b[2];
    }
    /* $min <= v < $max */
    private function rootVin($v, $min, $max){
        return !$this->rootVlt($v, $min) && $this->rootVlt($v, $max);
    }
    private function rootWhich($bin){
        static $cache = [];
        if(array_key_exists($bin, $cache))return $cache[$bin];
        $paths = (string)@getenv('PATH');
        /* the PATH of a web server is often minimal, so the standard places are
           always looked in as well - still pure PHP, still no external tool */
        $paths = rtrim($paths . PATH_SEPARATOR . '/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin', PATH_SEPARATOR);
        foreach(array_unique(explode(PATH_SEPARATOR, $paths)) as $dir){
            if($dir === '')continue;
            $f = rtrim($dir, '/') . '/' . $bin;
            if(@is_file($f) && @is_executable($f))return $cache[$bin] = $f;
        }
        return $cache[$bin] = '';
    }
    private function rootModuleAvailable($name){
        if(@is_dir('/sys/module/' . str_replace('-', '_', $name)))return true;
        $rel = php_uname('r');
        foreach(['/lib/modules/' . $rel, '/usr/lib/modules/' . $rel] as $base){
            if(!@is_dir($base))continue;
            $hits = [];
            $budget = 20000;
            $this->sysWalk($base, function($path, $entry) use ($name){return strpos($entry, $name . '.ko') === 0;}, $hits, $budget);
            if($hits)return true;
        }
        return false;
    }
    /* Is this module blocked through modprobe.d? (the vendor mitigation) */
    private function rootMitigated($module){
        $files = glob('/etc/modprobe.d/*.conf') ?: [];
        foreach($files as $f){
            $c = (string)@file_get_contents($f);
            if(preg_match('/^\s*(install|blacklist)\s+' . preg_quote($module, '/') . '\b/m', $c))return basename($f);
        }
        return '';
    }
    private function rootUserNamespaces(){
        $max = $this->sysInt('/proc/sys/user/max_user_namespaces', 0);
        $allowed = $max > 0;
        if(@is_file('/proc/sys/kernel/unprivileged_userns_clone'))$allowed = $allowed && $this->sysInt('/proc/sys/kernel/unprivileged_userns_clone', 0) === 1;
        if(@is_file('/proc/sys/kernel/apparmor_restrict_unprivileged_userns'))$allowed = $allowed && $this->sysInt('/proc/sys/kernel/apparmor_restrict_unprivileged_userns', 0) === 0;
        return['max' => $max, 'works' => $allowed,
