        if($this->rootVlt($B['up'], $A['up']))return false;
        $na = preg_match_all('/\d+/', $A['rev'], $m) ? array_map('intval', $m[0]) : [];
        $nb = preg_match_all('/\d+/', $B['rev'], $n) ? array_map('intval', $n[0]) : [];
        for($i = 0; $i < max(count($na), count($nb)); $i++){
