           extension scope: this is a bounded hash-only comparison against a
           signature the admin explicitly marked as Threat. It does not run
           heuristic analysis on PDFs or ordinary documents, but it must still
           catch that exact payload after its filename or extension changes. */
        $content=@file_get_contents($path,false,null,0,$this->threatsMaxBytes()+1);
        if($content===false||strlen($content)>$this->threatsMaxBytes())return;
        $hash=hash('sha256',$content);$sig=$this->threatsKnownSignature($state,$hash);
        if(!$sig||$this->threatsIsWhitelisted($state,$path,$hash))return;
        $state['priority_last_path']=$path;
        if($this->readonly)return;
        if(@unlink($path)){
            $state['auto_deleted']=(int)$state['auto_deleted']+1;
            $state['priority_auto_deleted']=(int)$state['priority_auto_deleted']+1;
            $state['last_path']=$path;
            $state['last_reason']='Priority auto-deleted: '.$sig['reason'];
            unset($state['known'][$path]);$this->threatsRemoveFinding($state,$path);
            $this->log('threat_priority_auto_delete',basename($path));
        }
    }
    private function threatsPrioritySlice(&$state,$deadline){
        $dirs=$state['priority_dirs'];$n=count($dirs);if(!$n)return;
        $budget=8;$steps=0;$cursor=((int)($state['priority_cursor']??0))%$n;
        while(microtime(true)<$deadline&&$budget>0&&$steps<min($n,4)){
            $idx=($cursor+$steps)%$n;$dir=$dirs[$idx]??'';
            $state['priority_cursor']=($idx+1)%$n;$steps++;
            if(!$dir||!is_dir($dir))continue;
            $savedCursor=$state['priority_dir_cursors'][$dir]??'';
            $batch=$this->threatsReadDir(['path'=>$dir,'cursor'=>$savedCursor===''?0:(int)$savedCursor]);
            foreach($batch['entries'] as $entry){
                if(is_file($entry)){
                    $this->threatsPriorityInspectFile($state,$entry);$budget--;
                    if($budget<=0||microtime(true)>=$deadline)break;
                }
            }
            $state['priority_dir_cursors'][$dir]=!empty($batch['done'])?'':$batch['cursor'];
            $state['priority_last_run']=time();
        }
    }
    private function threatsDeleteMatchingFiles(&$state,$hash){
        $root=$this->threatsRoot();if(!$root||$hash==='')return 0;
        $deleted=0;
        try{
            $base=new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS);
            $filter=new RecursiveCallbackFilterIterator($base,function($current){
                return !$current->isDir()||(!$this->threatsSkip($current->getPathname())&&$this->threatsPathAllowed($current->getPathname()));
            });
            $files=new RecursiveIteratorIterator($filter,RecursiveIteratorIterator::LEAVES_ONLY);
            foreach($files as $info){
                if(!$info->isFile())continue;
                $path=realpath($info->getPathname());
                if(!$path||$this->threatsSkip($path)||!$this->threatsPathAllowed($path))continue;
                $size=(int)@filesize($path);if($size<1||$size>$this->threatsMaxBytes()||!is_readable($path))continue;
                $content=@file_get_contents($path,false,null,0,$this->threatsMaxBytes()+1);
                if($content===false||strlen($content)>$this->threatsMaxBytes()||hash('sha256',$content)!==$hash)continue;
                if($this->threatsIsWhitelisted($state,$path,$hash))continue;
                if(@unlink($path)){
                    $deleted++;unset($state['known'][$path]);$this->threatsRemoveFinding($state,$path);$this->log('threat_delete',basename($path));
                }
            }
        }catch(Throwable $e){}
        return $deleted;
    }
    private function threatsIsWhitelisted($state,$path,$hash=''){
        return in_array($path,$state['whitelist_files'],true)||($hash!==''&&in_array($hash,$state['whitelist_hashes'],true));
    }
    private function threatsInspectFile(&$state,$path){
        $path=realpath($path);if(!$path||$this->threatsSkip($path)||!$this->threatsPathAllowed($path)||!is_file($path)||!$this->threatsScannableFile($path))return;
        $size=(int)@filesize($path);if($size<1||$size>$this->threatsMaxBytes()){$state['known'][$path]=['size'=>$size,'mtime'=>(int)@filemtime($path)];return;}
        $item=$this->threatsAnalyze($path);$hash=$item['hash']??'';
        $state['known'][$path]=['size'=>$size,'mtime'=>(int)@filemtime($path),'hash'=>$hash];
        if($this->threatsIsWhitelisted($state,$path,$hash)){$this->threatsRemoveFinding($state,$path);return;}
        if($hash!==''&&($sig=$this->threatsKnownSignature($state,$hash))){
            if(!$this->readonly&&@unlink($path)){$state['auto_deleted']=(int)$state['auto_deleted']+1;$state['last_path']=$path;$state['last_reason']='Auto-deleted: '.$sig['reason'];$this->log('threat_auto_delete',basename($path));}
            return;
        }
        if($item){
            $item['url']=$this->threatsPublicUrl($path);
            $exists=false;foreach($state['findings'] as $f)if(($f['path']??'')===$path){$exists=true;break;}
            if(!$exists)$state['findings'][]=$item;
            else foreach($state['findings'] as &$f)if(($f['path']??'')===$path)$f=array_merge($f,$item);
            unset($f);$state['last_path']=$path;$state['last_reason']=$item['reason'];
        }else $this->threatsRemoveFinding($state,$path);
        $this->threatsSortFindings($state);
