    }
    private function threatsReadDir($frame){
        $path=$frame['path']??'';$cursor=max(0,(int)($frame['cursor']??0));
        if(!$path||!is_dir($path)||$this->threatsSkip($path))return['entries'=>[],'cursor'=>$cursor,'done'=>true];
        $h=@opendir($path);if(!$h)return['entries'=>[],'cursor'=>$cursor,'done'=>true];
        $out=[];$valid=0;$next=$cursor;$done=true;$limit=48;
        while(($name=@readdir($h))!==false){
            if($name==='.'||$name==='..')continue;
            $p=$path.DIRECTORY_SEPARATOR.$name;
            if($this->threatsSkip($p))continue;
            if($valid++<$cursor)continue;
            if(is_dir($p)||is_file($p))$out[]=$p;
            $next++;
            if(count($out)>=$limit){$done=false;break;}
        }
        @closedir($h);
        return['entries'=>$out,'start'=>$cursor,'cursor'=>$next,'done'=>$done];
    }
    private function threatsInitialSlice(&$state,$deadline,&$fileBudget){
        $steps=0;
        while(microtime(true)<$deadline&&$fileBudget>0&&$steps<12&&!empty($state['dirs'])){
            $steps++;
            $last=count($state['dirs'])-1;$frame=&$state['dirs'][$last];
            if($frame['entries']===null){
                $batch=$this->threatsReadDir($frame);$frame['entries']=$batch['entries'];$frame['cursor']=$batch['cursor'];$frame['done']=$batch['done'];$frame['batch']=true;$frame['index']=0;
                if(!in_array($frame['path'],$state['watch_dirs'],true))$state['watch_dirs'][]=$frame['path'];
                $state['dir_mtimes'][$frame['path']]=(int)@filemtime($frame['path']);
            }
            if(($frame['index']??0)>=count($frame['entries'])){
                if(!empty($frame['batch'])&&!empty($frame['done'])){array_pop($state['dirs']);unset($frame);continue;}
                $frame['entries']=null;$frame['index']=0;unset($frame);continue;
            }
            $p=$frame['entries'][$frame['index']++];unset($frame);
            if(is_dir($p))$state['dirs'][]=['path'=>$p,'entries'=>null,'index'=>0,'batch'=>true];
            elseif(is_file($p)){$this->threatsInspectFile($state,$p);$fileBudget--;}
        }
        if(empty($state['dirs']))$state['complete']=true;
    }
    private function threatsWatchSlice(&$state,$deadline,&$fileBudget){
        $dirs=$state['watch_dirs'];$n=count($dirs);if(!$n)return;
        $steps=0;
        while(microtime(true)<$deadline&&$steps<1&&$fileBudget>0&&$n){
            /* Prioritize directories whose mtime changed so a fresh upload
               is checked immediately instead of waiting for the full
               round-robin pass. Keep the round-robin fallback because some
               shared hosts expose only second-level mtimes. */
            $round=((int)($state['watch_cursor']??0))%$n;$idx=null;
            for($offset=0;$offset<$n;$offset++){
                $probe=($round+$offset)%$n;$candidate=$dirs[$probe]??'';
                if(!$candidate||!is_dir($candidate))continue;
                $currentMtime=(int)@filemtime($candidate);
                $savedMtime=(int)($state['dir_mtimes'][$candidate]??0);
                if($currentMtime!==$savedMtime){$idx=$probe;break;}
            }
            if($idx===null)$idx=$round;
            $dir=$dirs[$idx];$state['watch_cursor']=($idx+1)%$n;$steps++;
            if(!is_dir($dir))continue;
            $mtime=(int)@filemtime($dir);$old=(int)($state['dir_mtimes'][$dir]??0);
            /* Do not rely on directory mtime alone: some hosts expose
               second-level timestamps, so delete-and-reupload can happen
               before the timestamp changes. A bounded directory listing is
               cheap and lets the known-path map catch that case too. */
            $state['dir_mtimes'][$dir]=$mtime;
            $cursor=($mtime!==$old)?0:(int)($state['watch_dir_cursors'][$dir]??0);
            $batch=$this->threatsReadDir(['path'=>$dir,'cursor'=>$cursor]);$entries=$batch['entries'];$nextCursor=$batch['cursor'];
            foreach($entries as $entryIndex=>$p){
                if(is_dir($p)&&!in_array($p,$state['watch_dirs'],true)){
                    $state['watch_dirs'][]=$p;$state['dir_mtimes'][$p]=(int)@filemtime($p);$n=count($state['watch_dirs']);
                    $state['dirs'][]=['path'=>$p,'entries'=>null,'index'=>0,'batch'=>true];$state['complete']=false;
                }
                elseif(is_file($p)){
                    $meta=$state['known'][$p]??null;$sz=(int)@filesize($p);$mt=(int)@filemtime($p);
                    if(!$meta||$meta['size']!==$sz||$meta['mtime']!==$mt){$this->threatsInspectFile($state,$p);$fileBudget--; $nextCursor=(int)$batch['start']+$entryIndex+1;}
                    if($fileBudget<=0)break;
                }
            }
            $state['watch_dir_cursors'][$dir]=!empty($batch['done'])?'':$nextCursor;
        }
    }
    public function threatsTick($force=false,$severityFilter=''){
        if(empty($_SESSION['fm_admin']))return['ok'=>false,'error'=>'Admins only.'];
        $state=$this->threatsLoadState();
         /* Reaching the end of the initial tree is not the end of monitoring.
            Start another bounded full-tree cycle on the next active request so
            new or changed files are eventually checked even when their parent
            directory mtime did not change. The priority pass below remains
            independent and runs before every general-scan slice. */
         if(!empty($state['complete'])||empty($state['dirs'])){
             $base=$this->threatsRoot();
             if($base){
                 $state['dirs']=[['path'=>$base,'entries'=>null,'index'=>0,'batch'=>true]];
                 $state['complete']=false;
                 $state['scan_cycle']=(int)($state['scan_cycle']??0)+1;
             }
         }
         /* The priority pass is independent from the general cursor. It runs
            first on every active tick, so a known payload in a remembered
            directory is checked even when the general scan is still traversing
            the rest of the site. */
         $priorityDeadline=microtime(true)+($force?.16:.08);
         $this->threatsPrioritySlice($state,$priorityDeadline);
         /* Keep the ordinary endpoint cooperative while avoiding an
            unnecessarily slow one-file-per-poll scan. */
         $deadline=microtime(true)+($force?.45:.18);$fileBudget=6;
         $this->threatsInitialSlice($state,$deadline,$fileBudget);
        $state['last_run']=time();$this->threatsSaveState($state);
        $allFindings=$state['findings']??[];
        $findingCounts=['Critical'=>0,'High'=>0,'Medium'=>0,'Low'=>0];
        foreach($allFindings as $finding){
            $level=['Critical','High','Medium','Low'];
            $findingSeverity=in_array($finding['severity']??'', $level, true)?$finding['severity']:'Low';
            $findingCounts[$findingSeverity]++;
        }
        $severityFilter=in_array($severityFilter,['Critical','High','Medium','Low'],true)?$severityFilter:'';
        $visibleFindings=$severityFilter===''?$allFindings:array_values(array_filter($allFindings,function($finding)use($severityFilter){
            return ($finding['severity']??'Low')===$severityFilter;
        }));
        $view=[
            'complete'=>(bool)($state['complete']??false),
            'findings'=>$visibleFindings,
            'finding_total'=>count($allFindings),
            'finding_counts'=>$findingCounts,
            'severity_filter'=>$severityFilter,
            'scanned'=>(int)($state['scanned']??0),
            'auto_deleted'=>(int)($state['auto_deleted']??0),
            'last_path'=>(string)($state['last_path']??''),
            'last_reason'=>(string)($state['last_reason']??''),
            'priority_dirs'=>count((array)($state['priority_dirs']??[])),
            'priority_last_run'=>(int)($state['priority_last_run']??0),
            'priority_last_path'=>(string)($state['priority_last_path']??''),
             'priority_auto_deleted'=>(int)($state['priority_auto_deleted']??0),
             'continuous_monitoring'=>true,
             'scan_cycle'=>(int)($state['scan_cycle']??0)
        ];
        foreach($view['findings'] as &$finding)$this->threatsApplyPriority($finding);
        unset($finding);$this->threatsSortFindings($view);
        $view['findings']=array_map(function($f){unset($f['content_b64']);return $f;},$view['findings']);
        return['ok'=>true,'state'=>$view];
    }
    public function threatsWhitelist(){
        if(empty($_SESSION['fm_admin']))return['ok'=>false,'error'=>'Admins only.'];
        $state=$this->threatsLoadState();$files=[];$existing=0;
        foreach(array_values(array_unique((array)($state['whitelist_files']??[]))) as $path){
            $rp=realpath((string)$path);
            if(!$rp||!is_file($rp)||!$this->threatsPathAllowed($rp)||$this->threatsSkip($rp))continue;
            $existing++;
            $files[]=['path'=>$rp,'name'=>basename($rp),'size'=>(int)@filesize($rp),'mtime'=>(int)@filemtime($rp)];
        }
        usort($files,function($a,$b){return strcasecmp((string)($a['path']??''),(string)($b['path']??''));});
        return['ok'=>true,'files'=>$files,'count'=>$existing,'hashes'=>count((array)($state['whitelist_hashes']??[]))];
    }
    public function threatsConfig($configPath=''){
        $state=$this->threatsLoadState();$sites=[];
        if($configPath!==''){
            $rp=realpath($configPath);
            if($rp&&is_file($rp)&&in_array(strtolower(basename($rp)),['wp-config.php','configuration.php'],true))$state['cms_config']=$rp;
        }
        if(!empty($state['cms_config'])&&!is_file($state['cms_config']))unset($state['cms_config']);
        if(empty($state['cms_config'])){
            $scan=$this->cmsScan();$sites=$scan['sites']??[];
            $preferred=$scan['current_wp_config']??null;
            if($preferred&&is_file($preferred))$state['cms_config']=realpath($preferred);
        }
        $this->threatsSaveState($state);
        return['ok'=>true,'config'=>$state['cms_config']??null,'sites'=>$sites,'root'=>$this->threatsRoot()];
    }
    private function threatsCmsFingerprint($u){
        return hash('sha256',strtolower(trim((string)($u['name']??''))).'|'.strtolower(trim((string)($u['email']??''))).'|'.strtolower(trim((string)($u['role']??''))));
    }
    private function threatsSuspiciousUser($u){
        $name=(string)($u['name']??'');$hay=$name.' '.(string)($u['email']??'');$why=[];
        foreach(['upload','hack','hacked','hacker','nx-zd','nx-dz','nxploited'] as $w)if(stripos($hay,$w)!==false)$why[]='Suspicious username/email: '.$w;
        if(preg_match('/(?<![A-Za-z])Nx(?![A-Za-z])/i',$hay))$why[]='Suspicious username/email: Nx';
        return $why?implode(' · ',$why):'';
    }
    public function threatsUsers($configPath=''){
        $cfg=$this->threatsConfig($configPath);$config=$cfg['config']??'';
        if(!$config)return['ok'=>true,'config'=>null,'sites'=>$cfg['sites']??[],'users'=>[],'error'=>'Select a CMS configuration first.'];
        $result=$this->cmsListUsers($config);if(!empty($result['error']))return['ok'=>false,'config'=>$config,'error'=>$result['error']];
        $state=$this->threatsLoadState();$users=[];$changed=false;
        foreach($result['users']??[] as $u){
            $u['fingerprint']=$this->threatsCmsFingerprint($u);$u['suspicion']=$this->threatsSuspiciousUser($u);
            $blocked=false;
            foreach($state['user_signatures'] as $sig)if(($sig['fingerprint']??'')===$u['fingerprint']||(($sig['name']??'')===$u['name']))$blocked=true;
            if($blocked&&!in_array($u['name'],$state['user_whitelist_names'],true)&&!in_array($u['fingerprint'],$state['user_whitelist_fingerprints'],true)){
                if(!$this->readonly&&$this->threatsDeleteCmsUser($config,$u)){$state['auto_deleted']=(int)$state['auto_deleted']+1;$changed=true;continue;}
            }
            if($u['suspicion']!==''&&!in_array($u['name'],$state['user_whitelist_names'],true)&&!in_array($u['fingerprint'],$state['user_whitelist_fingerprints'],true))$u['suspicion']=$u['suspicion'];
            $users[]=$u;
        }
        if($changed)$this->threatsSaveState($state);
        return['ok'=>true,'config'=>$config,'sites'=>$cfg['sites']??[],'users'=>$users,'auto_deleted'=>$changed];
    }
    private function threatsDeleteCmsUser($config,$u){
        list($link,$c,$err)=$this->cmsConnect($config);if($err||!$link)return false;
        $id=(int)($u['id']??0);if(!$id){mysqli_close($link);return false;}
        $t=$c['prefix'];
        if($c['type']==='wordpress'){$ok=(bool)mysqli_query($link,"DELETE FROM `{$t}users` WHERE ID=$id")&&(bool)mysqli_query($link,"DELETE FROM `{$t}usermeta` WHERE user_id=$id");}
        else {$ok=(bool)mysqli_query($link,"DELETE FROM `{$t}users` WHERE id=$id")&&(bool)mysqli_query($link,"DELETE FROM `{$t}user_usergroup_map` WHERE user_id=$id");}
        if($ok)$this->cmsSyncHiddenVisibility($config,$c,$link);mysqli_close($link);return $ok;
    }
    public function threatsFileAction($action,$path){
        if(!$path||!$this->threatsPathAllowed($path)||$this->threatsSkip($path))return['ok'=>false,'error'=>'Invalid threat file.'];
        $path=realpath($path);if(!$path||!is_file($path))return['ok'=>false,'error'=>'File no longer exists.'];
        $state=$this->threatsLoadState();$item=$this->threatsAnalyze($path);$hash=$item['hash']??'';
        if($action==='safe'){
            if(!in_array($path,$state['whitelist_files'],true))$state['whitelist_files'][]=$path;
            if($hash!==''&&!in_array($hash,$state['whitelist_hashes'],true))$state['whitelist_hashes'][]=$hash;
            $this->threatsRemoveFinding($state,$path);$this->threatsSaveState($state);$this->log('threat_safe',basename($path));return['ok'=>true];
        }
        if($action!=='threat'||$this->readonly)return['ok'=>false,'error'=>$this->readonly?'Read-only account.':'Invalid action.'];
        if($item){
            $exists=false;foreach($state['signatures'] as $s)if(($s['hash']??'')===$hash)$exists=true;
            if(!$exists)$state['signatures'][]=['hash'=>$hash,'size'=>$item['size'],'reason'=>$item['reason'],'created'=>time(),'by'=>$_SESSION['fm_user']??''];
            $this->threatsRememberPriorityDir($state,$path);
        }
        /* Do not recursively read the whole site inside the click request.
           That made Threat unusably slow on large sites because every readable
           file up to 3 MB was opened just to find same-content copies. The
           selected file is removed immediately; its signature and priority
           directory are saved first so the independent priority/background
           passes remove any other current or future copies without blocking
           this action. */
        $deleted=@unlink($path)?1:0;
        $this->threatsRemoveFinding($state,$path);$this->threatsSaveState($state);
        $ok=$deleted>0;
        return['ok'=>$ok,'deleted_count'=>$deleted,'background_monitoring'=>($item&&$hash!==''),
            'error'=>$ok?'':'Could not delete the file.'];
    }
    public function threatsDownload($path){
        $path=realpath((string)$path);
        if(!$path||!is_file($path)||!is_readable($path)||!$this->threatsPathAllowed($path)||$this->threatsSkip($path)){
            http_response_code(404);header('Content-Type: text/plain;charset=utf-8');echo 'Threat file not found.';return;
        }
        $filename=basename($path);
        $fallback=preg_replace('/[^A-Za-z0-9._-]+/','_',$filename);
        $fallback=$fallback!==''?$fallback:'download';
        while(ob_get_level()>0)@ob_end_clean();
        $mime=function_exists('mime_content_type')?@mime_content_type($path):'application/octet-stream';
        if(!$mime)$mime='application/octet-stream';
        header('Content-Type: '.$mime);
        header('Content-Length: '.(int)@filesize($path));
        header('Content-Disposition: attachment; filename="'.$fallback.'"; filename*=UTF-8\'\''.rawurlencode($filename));
        header('X-Content-Type-Options: nosniff');
        readfile($path);
    }
    public function threatsScanFile($path){
        $input=trim((string)$path);$root=$this->threatsRoot();
        if($input===''||!$root)return['ok'=>false,'error'=>'Enter a file path.'];
        if($input[0]!==DIRECTORY_SEPARATOR)$input=$root.DIRECTORY_SEPARATOR.ltrim($input,'./'.DIRECTORY_SEPARATOR);
        $rp=realpath($input);
        if(!$rp||!is_file($rp)||!$this->threatsPathAllowed($rp)||$this->threatsSkip($rp))return['ok'=>false,'error'=>'The path must point to a file inside the site root.'];
        if(!$this->threatsScannableFile($rp))return['ok'=>true,'skipped'=>true,'reason'=>'Only PHP and executable files are scanned.'];
        $size=(int)@filesize($rp);if($size<1)return['ok'=>true,'skipped'=>true,'reason'=>'The file is empty.'];
        if($size>$this->threatsMaxBytes())return['ok'=>true,'skipped'=>true,'reason'=>'The file is larger than the 3 MB scan limit.'];
        $state=$this->threatsLoadState();$this->threatsInspectFile($state,$rp);$this->threatsSaveState($state);
        $found=null;foreach($state['findings'] as $item)if(($item['path']??'')===$rp){$found=$item;unset($found['content_b64']);break;}
        return['ok'=>true,'skipped'=>false,'found'=>$found];
    }
    public function threatsUserAction($action,$configPath,$user){
        if($this->readonly)return['ok'=>false,'error'=>'Read-only account.'];
        $config=$this->threatsConfig($configPath)['config']??'';if(!$config||!is_array($user))return['ok'=>false,'error'=>'Invalid CMS user.'];
        $listed=$this->cmsListUsers($config);$found=null;
        foreach($listed['users']??[] as $u)if((int)($u['id']??0)===(int)($user['id']??0)&&($u['name']??'')===($user['name']??'')){$found=$u;break;}
        if(!$found)return['ok'=>false,'error'=>'The CMS user no longer exists.'];
        $state=$this->threatsLoadState();$fp=$this->threatsCmsFingerprint($found);
        if($action==='safe'){
            if(!in_array($found['name'],$state['user_whitelist_names'],true))$state['user_whitelist_names'][]=$found['name'];
            if(!in_array($fp,$state['user_whitelist_fingerprints'],true))$state['user_whitelist_fingerprints'][]=$fp;
            $this->threatsSaveState($state);return['ok'=>true];
        }
        if($action!=='threat')return['ok'=>false,'error'=>'Invalid action.'];
        $state['user_signatures'][]=['name'=>$found['name'],'email'=>$found['email']??'','role'=>$found['role']??'','fingerprint'=>$fp,'created'=>time(),'by'=>$_SESSION['fm_user']??''];
        $ok=$this->threatsDeleteCmsUser($config,$found);$this->threatsSaveState($state);
        if($ok)$this->log('threat_cms_user_delete',$found['name']);
        return['ok'=>$ok,'error'=>$ok?'':'Could not delete the CMS user.'];
    }

    /* ══ SSH check / install (best-effort; requires root & a package manager) ══ */
    public function sshStatus(){
        $bin=trim((string)@shell_exec('command -v sshd 2>/dev/null'));
        $client=trim((string)@shell_exec('command -v ssh 2>/dev/null'));
        $portOpen=false;
        $c=@fsockopen('127.0.0.1',22,$errno,$errstr,1.5);
        if($c){$portOpen=true;fclose($c);}
        $running=false;
        $ps=trim((string)@shell_exec("ps aux 2>/dev/null | grep -i '[s]shd'"));
        if($ps)$running=true;
        $pkgMgr='';
        foreach(['apt-get'=>'apt','dnf'=>'dnf','yum'=>'yum','apk'=>'apk','nix-env'=>'nix'] as $bin2=>$label){
            if(trim((string)@shell_exec("command -v $bin2 2>/dev/null")))$pkgMgr=$label;
            if($pkgMgr)break;
        }
        $ipInfo=$this->sshDetectIp();
        return ['installed'=>(bool)$bin,'client'=>(bool)$client,'running'=>$running||$portOpen,'port_open'=>$portOpen,'pkg_mgr'=>$pkgMgr,'sshd_path'=>$bin,
            'server_ip'=>$ipInfo['ip'],'server_ip_method'=>$ipInfo['method'],'server_ip_external'=>$ipInfo['external'],'server_ip_reachable'=>$ipInfo['reachable']];
    }

    /**
     * Detect the real, usable IP address for connecting to this server over SSH.
     * Tries several methods in order of reliability (route table -> all bound
     * addresses -> DNS -> web server binding), discards loopback/link-local
     * addresses, and prefers whichever candidate actually answers on port 22.
     * Falls back to loopback (clearly marked as local-only) only if nothing
     * else is found, and returns an explicit "undetermined" result rather than
     * ever silently pretending 127.0.0.1 is a reachable external address.
     */
    public function sshDetectIp(){
        $candidates=[]; // ip => detection method label
        $add=function($ip,$method) use (&$candidates){
            $ip=trim((string)$ip);
            if($ip&&filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4)&&!isset($candidates[$ip]))$candidates[$ip]=$method;
        };
        // 1) Address the kernel would actually use to reach the outside world (most reliable single pick)
        $route=trim((string)@shell_exec('ip route get 1.1.1.1 2>/dev/null'));
        if($route&&preg_match('/\bsrc\s+(\d{1,3}(?:\.\d{1,3}){3})/',$route,$m))$add($m[1],'default route');
        // 2) All addresses bound to any interface
        $hI=trim((string)@shell_exec('hostname -I 2>/dev/null'));
        if($hI)foreach(preg_split('/\s+/',$hI) as $ip)$add($ip,'hostname -I');
        // 3) Parse `ip addr` directly (covers systems where hostname -I is unavailable/limited)
        $ipAddr=trim((string)@shell_exec('ip -4 -o addr show scope global 2>/dev/null'));
        if($ipAddr)foreach(explode("\n",$ipAddr) as $line)if(preg_match('/inet\s+(\d{1,3}(?:\.\d{1,3}){3})/',$line,$m))$add($m[1],'ip addr (global scope)');
        // 4) DNS resolution of the machine's own hostname
        $host=gethostname();
        if($host){$resolved=@gethostbyname($host);if($resolved&&$resolved!==$host)$add($resolved,'hostname DNS lookup');}
        // 5) Whatever address the web server itself reports being bound to
        if(!empty($_SERVER['SERVER_ADDR']))$add($_SERVER['SERVER_ADDR'],'web server SERVER_ADDR');

        // Drop loopback / link-local / unusable addresses - these are never valid "connect to me" addresses
        $filtered=[];
        foreach($candidates as $ip=>$method){
            if(str_starts_with($ip,'127.')||str_starts_with($ip,'169.254.')||$ip==='0.0.0.0')continue;
            $filtered[$ip]=$method;
        }

        // Prefer a candidate that actually answers on port 22 - that is a guaranteed-usable address
        foreach($filtered as $ip=>$method){
            $c=@fsockopen($ip,22,$errno,$errstr,1.0);
            if($c){fclose($c);return['ip'=>$ip,'method'=>$method,'reachable'=>true,'external'=>true,'candidates'=>$candidates];}
        }
        // None answered directly on :22 (sshd may bind only to 0.0.0.0/loopback) - still surface the
        // best non-loopback address found, since that is what a remote client needs to type in.
        if($filtered){
            $ip=array_key_first($filtered);
            return['ip'=>$ip,'method'=>$filtered[$ip],'reachable'=>false,'external'=>true,'candidates'=>$candidates];
        }
        // Genuinely nothing but loopback exists - be explicit that it is local-only, never disguise it as external.
        $c=@fsockopen('127.0.0.1',22,$errno,$errstr,1.0);
        if($c){fclose($c);return['ip'=>'127.0.0.1','method'=>'loopback only (no external interface detected)','reachable'=>true,'external'=>false,'candidates'=>$candidates];}
        return['ip'=>null,'method'=>null,'reachable'=>false,'external'=>false,'candidates'=>$candidates];
    }

    /**
     * Run a system-account-management shell command and judge success purely from the
     * real process exit code - never from guessing at substrings in the output. Tools like
     * chpasswd/usermod/chsh can fail with many different phrasings (PAM errors, locked
     * files, policy rejections, etc.) that don't contain the word "permission", so pattern
     * matching on output text is unreliable and was the root cause of false "success" reports.
     */
    private function sshRunAdmin($cmd){
        $out=[];$exit=0;
        exec($cmd.' 2>&1',$out,$exit);
        return ['ok'=>$exit===0,'out'=>implode("\n",$out),'exit'=>$exit];
    }
    private function sshInstall(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $st=$this->sshStatus();
        if($st['installed']){$this->addMsg('OpenSSH server is already installed.','warning');return;}
        if(!$st['pkg_mgr']){$this->addMsg('No supported package manager (apt/dnf/yum/apk/nix) found on this server, so it cannot be installed automatically. This is common on shared hosting where SSH must be enabled by your host.','danger');return;}
        $cmds=['apt'=>'apt-get update -y && apt-get install -y openssh-server','dnf'=>'dnf install -y openssh-server','yum'=>'yum install -y openssh-server','apk'=>'apk add --no-cache openssh','nix'=>'nix-env -iA nixpkgs.openssh'];
        $cmd=$cmds[$st['pkg_mgr']];
        $out=[];$exit=0;
        exec($cmd.' 2>&1',$out,$exit);
        $tail=implode("\n",array_slice($out,-25));
        if($exit===0){
            @exec('service ssh start 2>&1 || systemctl start sshd 2>&1 || systemctl start ssh 2>&1');
            $this->log('ssh_install','via '.$st['pkg_mgr']);
            $this->addMsg("OpenSSH server installed. Output:\n$tail",'success');
        } else {
            $this->addMsg("Install failed (exit $exit). This usually means the process lacks root privileges. Output:\n$tail",'danger');
        }
    }

    /* ══ SSH User Management ══ */
    public function sshListUsers(){
        $users=[];
        $lines=@file('/etc/passwd')?:[];
        // collect sudoers
        $sudoers=[];
        foreach(['sudo','wheel','admin'] as $grp){
            $g=trim((string)@shell_exec("getent group ".escapeshellarg($grp)." 2>/dev/null"));
            if($g){$p=explode(':',$g);if(isset($p[3])&&$p[3]!=='')foreach(explode(',',$p[3]) as $u)if(trim($u))$sudoers[]=trim($u);}
        }
        foreach(glob('/etc/sudoers.d/*')?:[] as $sf){
            $sc=@file_get_contents($sf);
            if($sc&&preg_match_all('/^([a-z_][a-z0-9_-]*)\s+ALL/im',$sc,$m))foreach($m[1] as $su)$sudoers[]=$su;
        }
        $sudoers=array_unique($sudoers);
        foreach($lines as $line){
            $line=trim($line);if(!$line||$line[0]==='#')continue;
            $p=explode(':',$line);if(count($p)<7)continue;
            [$uname,$pwd,$uid,$gid,$gecos,$home,$shell]=array_pad($p,7,'');
            $uid=(int)$uid;$shell=trim($shell);
            $hasLogin=!in_array(basename($shell),['nologin','false','sync','halt','shutdown','']);
            if($uid<1000&&!$hasLogin)continue;
            if(in_array($uname,['nobody','nfsnobody']))continue;
            // count authorized keys
            $keyCount=0;$akPath=rtrim($home,'/').'/.ssh/authorized_keys';
            if(is_file($akPath)){$ak=@file_get_contents($akPath)?:'';$keyCount=count(array_filter(explode("\n",$ak),fn($l)=>trim($l)&&$l[0]!=='#'));}
            // locked status via shadow
            $locked=false;
            $shadow=trim((string)@shell_exec("getent shadow ".escapeshellarg($uname)." 2>/dev/null"));
            if($shadow){$sp=explode(':',$shadow);if(isset($sp[1])&&strlen($sp[1])&&($sp[1][0]==='!'||$sp[1][0]==='*'))$locked=true;}
            // last login
            $lastLogin=trim((string)@shell_exec("lastlog -u ".escapeshellarg($uname)." 2>/dev/null | tail -1"));
            $users[]=['username'=>$uname,'uid'=>$uid,'gid'=>$gid,'home'=>$home,'shell'=>$shell,'gecos'=>$gecos,'sudo'=>in_array($uname,$sudoers),'key_count'=>$keyCount,'locked'=>$locked,'last_login'=>$lastLogin];
        }
        usort($users,fn($a,$b)=>$a['uid']<=>$b['uid']);
        return $users;
    }
    /* Translate common shell command error output into a user-friendly message */
    private function sshCmdErr($raw){
        $r=strtolower($raw);
        if(str_contains($r,'permission denied')||str_contains($r,'cannot lock')||str_contains($r,'not permitted'))
            return "Permission denied - this server requires root (sudo) access to manage system users. The current PHP process does not have root privileges.";
        if(str_contains($r,'already exists')||str_contains($r,'already in use'))
            return "A user with that name already exists.";
        if(str_contains($r,'does not exist')||str_contains($r,'no such user'))
            return "User does not exist on this system.";
        if(str_contains($r,'invalid user')||str_contains($r,'unknown user'))
            return "Invalid or unknown username.";
        return $raw?:"Unknown error - no output from the system command.";
    }
    private function sshCreateUser(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $uname=trim($_POST['ssh_user']??'');$pass=$_POST['ssh_pass']??'';
        $shell=$_POST['ssh_shell']??'/bin/bash';$sudo=!empty($_POST['ssh_sudo']);$key=trim($_POST['ssh_key']??'');
        if(!preg_match('/^[a-z_][a-z0-9_-]{0,31}$/',$uname)){$this->addMsg('Invalid username - use only lowercase letters, digits, _ or -.','danger');return;}
        $allowed=['/bin/bash','/bin/sh','/bin/rbash','/usr/bin/bash','/usr/bin/sh','/usr/bin/zsh','/bin/zsh'];
        if(!in_array($shell,$allowed))$shell='/bin/bash';
        $out=trim((string)shell_exec('useradd -m -s '.escapeshellarg($shell).' '.escapeshellarg($uname).' 2>&1'));
        $exists=trim((string)shell_exec('id '.escapeshellarg($uname).' 2>/dev/null'));
        if(!$exists){$this->addMsg("Failed to create user \"{$uname}\": ".$this->sshCmdErr($out),'danger');return;}
        if($pass){
            $esc=escapeshellarg($uname.':'.$pass);
            $r=$this->sshRunAdmin("echo $esc | chpasswd");
            if(!$r['ok']){
                $this->addMsg("User \"{$uname}\" was created, but setting the initial password failed: ".$this->sshCmdErr($r['out']).' You can retry from the edit-user dialog.','warning');
            }
        }
        if($sudo){
            shell_exec("usermod -aG sudo ".escapeshellarg($uname)." 2>/dev/null");
            shell_exec("usermod -aG wheel ".escapeshellarg($uname)." 2>/dev/null");
        }
        if($key&&(str_starts_with($key,'ssh-')||str_starts_with($key,'ecdsa-')||str_starts_with($key,'sk-'))){
            $hm=trim((string)shell_exec("getent passwd ".escapeshellarg($uname)." 2>/dev/null | cut -d: -f6"));
            if($hm){$sd=$hm.'/.ssh';
                shell_exec("mkdir -p ".escapeshellarg($sd)." && chmod 700 ".escapeshellarg($sd)." && chown $uname ".escapeshellarg($sd));
                @file_put_contents($sd.'/authorized_keys',$key."\n",FILE_APPEND);
                shell_exec("chmod 600 ".escapeshellarg($sd.'/authorized_keys')." && chown $uname ".escapeshellarg($sd.'/authorized_keys'));
            }
        }
        $this->log('ssh_create_user',$uname);
        $this->addMsg("SSH user \"{$uname}\" created successfully.".($sudo?' (sudo granted)':''),'success');
    }
    private function sshDeleteUser(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $uname=trim($_POST['ssh_user']??'');
        if(!preg_match('/^[a-z_][a-z0-9_-]{0,31}$/',$uname)){$this->addMsg('Invalid username.','danger');return;}
        if($uname==='root'||$uname===get_current_user()){$this->addMsg('Cannot delete this account.','danger');return;}
        $out=trim((string)shell_exec("userdel -r ".escapeshellarg($uname)." 2>&1"));
        $exists=trim((string)shell_exec("id ".escapeshellarg($uname)." 2>/dev/null"));
        if($exists){$this->addMsg("Failed to delete \"{$uname}\": ".$this->sshCmdErr($out),'danger');return;}
        $this->log('ssh_delete_user',$uname);
        $this->addMsg("User \"{$uname}\" deleted.",'warning');
    }
    private function sshUpdateUser(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $uname=trim($_POST['ssh_user']??'');$act=trim($_POST['ssh_action']??'');
        if(!preg_match('/^[a-z_][a-z0-9_-]{0,31}$/',$uname)){$this->addMsg('Invalid username.','danger');return;}
        switch($act){
            case 'lock':
                $r=$this->sshRunAdmin("usermod -L ".escapeshellarg($uname));
                if(!$r['ok'])$this->addMsg("Failed to lock \"{$uname}\": ".$this->sshCmdErr($r['out']),'danger');
                else $this->addMsg("Account \"{$uname}\" locked.",'warning');
                break;
            case 'unlock':
                $r=$this->sshRunAdmin("usermod -U ".escapeshellarg($uname));
                if(!$r['ok'])$this->addMsg("Failed to unlock \"{$uname}\": ".$this->sshCmdErr($r['out']),'danger');
                else $this->addMsg("Account \"{$uname}\" unlocked.",'success');
                break;
            case 'add_sudo':
                $r1=$this->sshRunAdmin("usermod -aG sudo ".escapeshellarg($uname));
                $r2=$this->sshRunAdmin("usermod -aG wheel ".escapeshellarg($uname));
                // Succeeds if at least one of the sudo/wheel groups actually exists and accepted the user;
                // only report failure when BOTH attempts genuinely failed.
                if(!$r1['ok']&&!$r2['ok'])
                    $this->addMsg("Failed to grant sudo to \"{$uname}\": ".$this->sshCmdErr($r1['out'].' '.$r2['out']),'danger');
                else $this->addMsg("Sudo privileges granted to \"{$uname}\".",'success');
                break;
            case 'remove_sudo':
                $r1=$this->sshRunAdmin("gpasswd -d ".escapeshellarg($uname)." sudo");
                $r2=$this->sshRunAdmin("gpasswd -d ".escapeshellarg($uname)." wheel");
                if(!$r1['ok']&&!$r2['ok'])
                    $this->addMsg("Failed to remove sudo from \"{$uname}\": ".$this->sshCmdErr($r1['out'].' '.$r2['out']),'danger');
                else $this->addMsg("Sudo privileges removed from \"{$uname}\".",'warning');
                break;
            case 'change_shell':
                $shell=$_POST['ssh_shell']??'/bin/bash';
                $allowed=['/bin/bash','/bin/sh','/bin/rbash','/usr/bin/bash','/usr/bin/sh','/usr/bin/zsh','/bin/zsh'];
                if(!in_array($shell,$allowed)){$this->addMsg('Invalid shell.','danger');return;}
                $r=$this->sshRunAdmin("chsh -s ".escapeshellarg($shell)." ".escapeshellarg($uname));
                if(!$r['ok'])$this->addMsg("Failed to change shell: ".$this->sshCmdErr($r['out']),'danger');
                else $this->addMsg("Shell updated to {$shell} for \"{$uname}\".",'success');
                break;
            case 'change_pass':
                $pass=$_POST['ssh_pass']??'';
                if(strlen($pass)<6){$this->addMsg('Password must be at least 6 characters.','danger');return;}
                // Capture the real shadow hash before the change so we can verify it actually moved -
                // some failure modes (PAM rejection, policy blocks) still exit non-zero but it is
                // cheap insurance to also confirm the stored credential genuinely changed.
                $shadowBefore=trim((string)@shell_exec('getent shadow '.escapeshellarg($uname).' 2>/dev/null'));
                $hashBefore=explode(':',$shadowBefore)[1]??null;
                $esc=escapeshellarg($uname.':'.$pass);
                $r=$this->sshRunAdmin("echo $esc | chpasswd");
                if(!$r['ok']){
                    $this->addMsg("Failed to change password for \"{$uname}\": ".$this->sshCmdErr($r['out']),'danger');
                    return;
                }
                $shadowAfter=trim((string)@shell_exec('getent shadow '.escapeshellarg($uname).' 2>/dev/null'));
                $hashAfter=explode(':',$shadowAfter)[1]??null;
                if($hashBefore!==null&&$hashAfter!==null&&$hashBefore===$hashAfter){
                    $this->addMsg("Password change for \"{$uname}\" was rejected by the system (the stored credential did not actually change) even though the command exited without error. This typically means PAM/system policy blocked the update - check account locks, password complexity rules, or restricted authentication modules on this server.",'danger');
                    return;
                }
                $this->addMsg("Password changed for \"{$uname}\" and verified on the system - it is safe to connect with the new password.",'success');
                break;
            case 'add_key':
                $key=trim($_POST['ssh_key']??'');
                if(!$key||(!str_starts_with($key,'ssh-')&&!str_starts_with($key,'ecdsa-')&&!str_starts_with($key,'sk-'))){$this->addMsg('Invalid public key format (must start with ssh-rsa, ssh-ed25519, ecdsa-sha2, etc.).','danger');return;}
                $hm=trim((string)shell_exec("getent passwd ".escapeshellarg($uname)." 2>/dev/null | cut -d: -f6"));
                if($hm){$sd=$hm.'/.ssh';
                    shell_exec("mkdir -p ".escapeshellarg($sd)." && chmod 700 ".escapeshellarg($sd)." && chown {$uname} ".escapeshellarg($sd));
                    @file_put_contents($sd.'/authorized_keys',$key."\n",FILE_APPEND);
                    shell_exec("chmod 600 ".escapeshellarg($sd.'/authorized_keys')." && chown {$uname} ".escapeshellarg($sd.'/authorized_keys'));
                    $this->addMsg("SSH public key added for \"{$uname}\".",'success');
                } else $this->addMsg("Home directory not found for \"{$uname}\" - cannot write authorized_keys.",'danger');
                break;
            default:$this->addMsg('Unknown action.','danger');
        }
        $this->log('ssh_update_user',"{$uname}:{$act}");
    }

    private function sshTerminalAccount($uname,$allowLocked=false){
        $uname=trim((string)$uname);
        if(!preg_match('/^[a-z_][a-z0-9_-]{0,31}$/',$uname))return['error'=>'Invalid system username.'];
        foreach(@file('/etc/passwd',FILE_IGNORE_NEW_LINES)?:[] as $line){
            $p=explode(':',$line);
            if(count($p)<7||$p[0]!==$uname)continue;
            $shell=trim($p[6]);
            if(!$allowLocked&&(!in_array(basename($shell),['bash','sh','rbash','zsh'],true)||!is_executable($shell)))
                return['error'=>'This account does not have an interactive shell.'];
            $shadow=trim((string)@shell_exec('getent shadow '.escapeshellarg($uname).' 2>/dev/null'));
            $sp=$shadow?explode(':',$shadow):[];
            if(!$allowLocked&&isset($sp[1])&&$sp[1]!==''&&($sp[1][0]==='!'||$sp[1][0]==='*'))
                return['error'=>'This system account is locked. Unlock it before using Login as.'];
            $home=realpath($p[5]);
            if($home===false||!is_dir($home))return['error'=>'The account home directory is not available.'];
            return['username'=>$uname,'uid'=>(int)$p[2],'gid'=>(int)$p[3],'home'=>$home,'shell'=>$shell];
        }
        return['error'=>'System account not found.'];
    }

    private function sshCurrentEuid(){
        if(function_exists('posix_geteuid')){
            $uid=@posix_geteuid();
            if(is_int($uid)&&$uid>=0)return$uid;
        }
        $status=@file_get_contents('/proc/self/status');
        if(is_string($status)&&preg_match('/^Uid:\s+\d+\s+(\d+)/m',$status,$m))return(int)$m[1];
        $out=[];$exit=1;@exec('id -u 2>/dev/null',$out,$exit);
        if($exit===0&&isset($out[0])&&ctype_digit(trim($out[0])))return(int)trim($out[0]);
        return null;
    }

    private function sshTerminalRunner($account){
        $currentUid=$this->sshCurrentEuid();
        if($currentUid===null)return['error'=>'The File Manager cannot determine the Linux user running PHP. The server must allow a POSIX UID check, read access to /proc/self/status, or the id -u command.'];
        if($currentUid!==null&&(int)$currentUid===(int)$account['uid'])return['mode'=>'self','prefix'=>''];

        if($currentUid===0){
            $bin=trim((string)@shell_exec('command -v runuser 2>/dev/null'));
            if($bin!==''){
                $prefix=escapeshellarg($bin).' -u '.escapeshellarg($account['username']).' -- ';
                $out=[];$exit=1;@exec($prefix.'id -u 2>/dev/null',$out,$exit);
                if($exit===0&&isset($out[0])&&(int)trim($out[0])===(int)$account['uid'])
                    return['mode'=>'runuser','prefix'=>$prefix];
            }
        }

        $sudo=trim((string)@shell_exec('command -v sudo 2>/dev/null'));
        if($sudo!==''){
            $prefix=escapeshellarg($sudo).' -n -u '.escapeshellarg($account['username']).' -- ';
            $out=[];$exit=1;@exec($prefix.'id -u 2>/dev/null',$out,$exit);
            if($exit===0&&isset($out[0])&&(int)trim($out[0])===(int)$account['uid'])
                return['mode'=>'sudo','prefix'=>$prefix];
        }
        return['error'=>'PHP runs as Linux UID '.$currentUid.', but this SSH account is UID '.(int)$account['uid'].'. This web request cannot reuse an SSH login automatically. Login as requires PHP to run as this account or an existing server-authorized account switch.'];
    }

    public function sshTerminalInfo($uname){
        if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
        $account=$this->sshTerminalAccount($uname);
        if(!empty($account['error']))return$account;
        $runner=$this->sshTerminalRunner($account);
        if(!empty($runner['error']))return['error'=>$runner['error']];
        return['ok'=>true,'username'=>$account['username'],'home'=>$account['home'],'mode'=>$runner['mode']];
    }

    public function sshTerminalRunAs($uname,$cmd){
        if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
        if($this->isRO())return['error'=>'Read-only account: terminal execution is disabled.'];
        $cmd=trim((string)$cmd);
        if($cmd===''||strlen($cmd)>20000)return['error'=>$cmd===''?'Enter a command.':'Command is too long.'];
        $account=$this->sshTerminalAccount($uname);
        if(!empty($account['error']))return['error'=>$account['error']];
        $runner=$this->sshTerminalRunner($account);
        if(!empty($runner['error']))return['error'=>$runner['error']];

        $dirKey='fm_ssh_terminal_dir_'.hash('sha256',$account['username']);
        $prevKey='fm_ssh_terminal_prev_'.hash('sha256',$account['username']);
        $cwd=realpath((string)($_SESSION[$dirKey]??$account['home']));
        if($cwd===false||!is_dir($cwd))$cwd=$account['home'];
        $shellBin=$account['shell'];
        $timeoutBin='';
        foreach(['/usr/bin/timeout','/bin/timeout'] as $candidate)if(is_executable($candidate)){$timeoutBin=$candidate;break;}

        if(preg_match('/^cd(?:\s+(.*))?$/s',$cmd,$m)){
            $arg=trim($m[1]??'');
            if($arg!==''&&(($arg[0]==="'"&&substr($arg,-1)==="'")||($arg[0]==='"'&&substr($arg,-1)==='"')))
                $arg=substr($arg,1,-1);
            if($arg===''||$arg==='~')$target=$account['home'];
            elseif($arg==='-')$target=$_SESSION[$prevKey]??$cwd;
            elseif(strpos($arg,'~/')===0)$target=$account['home'].'/'.substr($arg,2);
            elseif($arg[0]==='/')$target=$arg;
            else $target=$cwd.'/'.$arg;
            $resolved=realpath($target);
            if($resolved===false||!is_dir($resolved))
                return['output'=>'bash: cd: '.($arg===''?'~':$arg).': No such file or directory','exit'=>1,'ms'=>0,'cwd'=>$cwd,'prompt'=>$this->sshTerminalPromptPath($cwd,$account['home'])];
            $test='test -d '.escapeshellarg($resolved).' && test -x '.escapeshellarg($resolved);
            $testCmd=$runner['prefix'].escapeshellarg($shellBin).' -lc '.escapeshellarg($test).' 2>/dev/null';
            $testOut=[];$testExit=1;@exec($testCmd,$testOut,$testExit);
            if($testExit!==0)return['output'=>'bash: cd: '.$arg.': Permission denied','exit'=>1,'ms'=>0,'cwd'=>$cwd,'prompt'=>$this->sshTerminalPromptPath($cwd,$account['home'])];
            $_SESSION[$prevKey]=$cwd;$_SESSION[$dirKey]=$resolved;
            return['output'=>'','exit'=>0,'ms'=>0,'cwd'=>$resolved,'prompt'=>$this->sshTerminalPromptPath($resolved,$account['home']),'shell'=>$shellBin];
        }

        $started=microtime(true);$out=[];$exit=1;
        $script='cd '.escapeshellarg($cwd).' && '.$cmd;
        $shellCommand=escapeshellarg($shellBin).' -lc '.escapeshellarg($script);
        $run=$timeoutBin!==''?escapeshellarg($timeoutBin).' 120s '.$shellCommand:$shellCommand;
        @exec($runner['prefix'].$run.' 2>&1',$out,$exit);
        $this->log('ssh_terminal','as '.$account['username']);
        return['output'=>implode("\n",$out),'exit'=>$exit,'ms'=>round((microtime(true)-$started)*1000),
            'cwd'=>$cwd,'prompt'=>$this->sshTerminalPromptPath($cwd,$account['home']),'shell'=>$shellBin];
    }

    private function sshTerminalPromptPath($path,$home){
        if($path===$home)return'~';
        $prefix=rtrim($home,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR;
        if(strpos($path,$prefix)===0)return'~/'.str_replace(DIRECTORY_SEPARATOR,'/',substr($path,strlen($prefix)));
        return str_replace(DIRECTORY_SEPARATOR,'/',$path);
    }

    private function sshAppendLoginKeyAsSudo($account,$publicKey){
        if(!function_exists('proc_open'))return['error'=>'Passwordless SSH setup needs proc_open to write the key as the target account.'];
        $sudo=trim((string)@shell_exec('command -v sudo 2>/dev/null'));
        if($sudo===''||!is_executable($sudo))return['error'=>'The PHP process cannot write this account home. Run PHP as the account owner/root or allow non-interactive sudo to this exact Linux account.'];
        $script=<<<'SH'
set -eu
dir=$1
file=$2
[ ! -L "$dir" ] || { echo 'The SSH directory is a symbolic link.' >&2; exit 20; }
if [ -e "$dir" ] && [ ! -d "$dir" ]; then echo 'The SSH path is not a directory.' >&2; exit 21; fi
umask 077
mkdir -p "$dir" || { echo 'Could not create the account SSH directory.' >&2; exit 22; }
[ ! -L "$dir" ] || { echo 'The SSH directory is a symbolic link.' >&2; exit 20; }
chmod 700 "$dir" || { echo 'Could not secure the account SSH directory.' >&2; exit 23; }
[ ! -L "$file" ] || { echo 'authorized_keys is a symbolic link.' >&2; exit 24; }
if [ -e "$file" ] && [ ! -f "$file" ]; then echo 'authorized_keys is not a regular file.' >&2; exit 25; fi
: >> "$file" || { echo 'Could not create or write authorized_keys.' >&2; exit 26; }
chmod 600 "$file" || { echo 'Could not secure authorized_keys.' >&2; exit 26; }
IFS= read -r key || { echo 'Could not receive the generated public key.' >&2; exit 27; }
[ -n "$key" ] || { echo 'The generated public key was empty.' >&2; exit 27; }
if command -v flock >/dev/null 2>&1; then
    exec 9>>"$file"
    flock -x 9 || { echo 'Could not lock authorized_keys safely.' >&2; exit 28; }
    printf '%s\n' "$key" >&9
else
    printf '%s\n' "$key" >> "$file" || { echo 'Could not append the generated key.' >&2; exit 26; }
fi
grep -Fqx -- "$key" "$file" || { echo 'The generated key could not be verified.' >&2; exit 29; }
SH;
        $cmd=[$sudo,'-n','-u',$account['username'],'--','/bin/sh','-c',$script,'ssh-key-install',$account['home'].'/.ssh',$account['home'].'/.ssh/authorized_keys'];
        $pipes=[];$proc=@proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);
        if(!is_resource($proc))return['error'=>'Could not start the account-safe SSH key writer.'];
        $input=rtrim($publicKey)."\n";
        $sent=@fwrite($pipes[0],$input);
        @fclose($pipes[0]);
        $stdout=stream_get_contents($pipes[1]);@fclose($pipes[1]);
        $stderr=stream_get_contents($pipes[2]);@fclose($pipes[2]);
        $exit=proc_close($proc);
        if($exit===0)return['ok'=>true];
        if($exit===20||$exit===24)return['error'=>'Refusing to write through a symbolic link in the SSH key directory.'];
        if($exit===22)return['error'=>'Could not create the account SSH directory. Check that the target account home is writable by that account.'];
        if($exit===28)return['error'=>'Could not lock authorized_keys safely; no key was accepted.'];
        if($sent!==strlen($input))return['error'=>'Could not send the complete generated public key to the account-safe writer.'];
        $detail=trim((string)$stderr);
        return['error'=>$detail!==''?'Could not install the passwordless SSH key: '.substr($detail,0,300):'Could not install the passwordless SSH key. Confirm sudo permits this PHP process to switch to the target account without a password.'];
    }

    private function sshAppendLoginKey($account,$publicKey){
        $home=$account['home'];$dir=$home.'/.ssh';$file=$dir.'/authorized_keys';
        if(is_link($dir)||is_link($file))return['error'=>'Refusing to write through a symbolic link in the SSH key directory.'];
        $euid=$this->sshCurrentEuid();
        if($euid!==0&&$euid!==(int)$account['uid']){
            $runner=$this->sshTerminalRunner($account);
            if(($runner['mode']??'')==='self')$euid=(int)$account['uid'];
            elseif(($runner['mode']??'')==='sudo')return$this->sshAppendLoginKeyAsSudo($account,$publicKey);
            else return['error'=>'The PHP process cannot write this account home. Run PHP as the account owner/root or allow non-interactive sudo to this exact Linux account.'];
        }
        if(!is_dir($dir)&&!@mkdir($dir,0700,true)&&!is_dir($dir)){
            clearstatcache(true,$home);
            return['error'=>'Could not create the account SSH directory. The PHP process needs write permission to '.$home.'.'];
        }
        clearstatcache(true,$dir);
        if(is_link($dir)||!is_dir($dir))return['error'=>'The account SSH path is not a safe directory.'];
        if(!@chmod($dir,0700)||((@fileperms($dir)&0777)!==0700))return['error'=>'Could not secure the account SSH directory with mode 0700.'];
        if(is_link($file))return['error'=>'Refusing to write through a symbolic link in the SSH key directory.'];
        if(!is_file($file)&&!@touch($file))return['error'=>'Could not create authorized_keys for this account. Check the account home permissions.'];
        clearstatcache(true,$file);
        if(is_link($file)||!is_file($file))return['error'=>'authorized_keys is not a safe regular file.'];
        if(!@chmod($file,0600)||((@fileperms($file)&0777)!==0600))return['error'=>'Could not secure authorized_keys with mode 0600.'];
        $fp=@fopen($file,'ab');
        if(!$fp)return['error'=>'Could not write authorized_keys. The PHP process needs permission to manage this account.'];
        $line=rtrim($publicKey)."\n";
        $ok=false;
        if(@flock($fp,LOCK_EX)){
            $ok=@fwrite($fp,$line)===strlen($line);
            @fflush($fp);@flock($fp,LOCK_UN);
        }
        @fclose($fp);
        if(!$ok)return['error'=>'Could not safely append the SSH public key.'];
        if($euid===0){
            @chown($dir,$account['uid']);@chgrp($dir,$account['gid']);
            @chown($file,$account['uid']);@chgrp($file,$account['gid']);
        }
        clearstatcache(true,$dir);clearstatcache(true,$file);
        if(function_exists('fileowner')&&(@fileowner($file)!==(int)$account['uid']||@fileowner($dir)!==(int)$account['uid'])){
            if(preg_match('/\s(mfm-login-as-[a-f0-9]{24})$/',trim($publicKey),$m))$this->sshRevokeManagedKeyLine($account,$m[1]);
            return['error'=>'authorized_keys is not owned by the target Linux account; the generated key was not accepted.'];
        }
        $saved=@file_get_contents($file);
        if(!is_string($saved)||strpos($saved,rtrim($publicKey))===false){
            if(preg_match('/\s(mfm-login-as-[a-f0-9]{24})$/',trim($publicKey),$m))$this->sshRevokeManagedKeyLine($account,$m[1]);
            return['error'=>'The public key could not be verified in authorized_keys.'];
        }
        return['ok'=>true];
    }

    private function sshRequestIsSecure(){
        if(!empty($_SERVER['HTTPS'])&&strtolower((string)$_SERVER['HTTPS'])!=='off')return true;
        if(strtolower((string)($_SERVER['REQUEST_SCHEME']??''))==='https')return true;
        $origin=parse_url((string)($_SERVER['HTTP_ORIGIN']??''));
        if(is_array($origin)&&strtolower((string)($origin['scheme']??''))==='https')return true;
        $forwarded=strtolower(trim(explode(',',(string)($_SERVER['HTTP_X_FORWARDED_PROTO']??''))[0]));
        return$forwarded==='https';
    }

    public function sshCreateLoginBundle($uname){
        if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
        if($this->isRO())return['error'=>'Read-only account: SSH key setup is disabled.'];
        if(!$this->sshRequestIsSecure())return['error'=>'Passwordless SSH setup requires HTTPS so the private key cannot be intercepted.'];
        @ignore_user_abort(true);
        $account=$this->sshTerminalAccount($uname);
        if(!empty($account['error']))return$account;
        $status=$this->sshStatus();
        if(empty($status['installed'])||empty($status['running'])||empty($status['server_ip'])||empty($status['server_ip_external']))
            return['error'=>'A running SSH server with a usable server address is required before preparing a local connection.'];
        $host=(string)$status['server_ip'];
        if(!filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4))return['error'=>'The detected SSH server address is invalid.'];
        $keygen=trim((string)@shell_exec('command -v ssh-keygen 2>/dev/null'));
        if($keygen===''||!is_executable($keygen))return['error'=>'ssh-keygen is not available on this server.'];

        $nonce=bin2hex(random_bytes(12));
        $comment='mfm-login-as-'.$nonce;
        $tmp=rtrim(sys_get_temp_dir(),DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR.'mfm-key-'.$nonce;
        $keyCmd=escapeshellarg($keygen).' -q -t ed25519 -N '.escapeshellarg(''). ' -C '.escapeshellarg($comment).' -f '.escapeshellarg($tmp).' 2>&1';
        $keyOut=[];$keyExit=1;
        @exec($keyCmd,$keyOut,$keyExit);
        if($keyExit!==0||!is_file($tmp)||!is_file($tmp.'.pub')){
            @unlink($tmp);@unlink($tmp.'.pub');
            return['error'=>'Could not generate an Ed25519 SSH key on this server.'];
        }
        @chmod($tmp,0600);
        $private=(string)@file_get_contents($tmp);
        $public=trim((string)@file_get_contents($tmp.'.pub'));
        if($private===''||!preg_match('/^ssh-ed25519\s+[A-Za-z0-9+\/=]+\s+'.preg_quote($comment,'/').'$/',$public)){
            @unlink($tmp);@unlink($tmp.'.pub');
            return['error'=>'The generated SSH key pair could not be validated.'];
        }

        $known=[];
        foreach(glob('/etc/ssh/ssh_host_*.pub')?:[] as $pubPath){
            $parts=preg_split('/\s+/',trim((string)@file_get_contents($pubPath)));
            if(count($parts)>=2&&preg_match('/^ssh-|^ecdsa-/',$parts[0])&&base64_decode($parts[1],true)!==false)
                $known[]=$host.' '.$parts[0].' '.$parts[1];
        }
        if(!$known){
            // Do not trust an unauthenticated network scan or disable host-key checking.
            @unlink($tmp);@unlink($tmp.'.pub');
            return['error'=>'No local SSH host public key was available to verify the server. The key setup was cancelled safely.'];
        }

        $target=$account['username'].'@'.$host;
        $win="@echo off\r\nsetlocal\r\nwhere ssh >nul 2>&1\r\nif errorlevel 1 (echo OpenSSH Client is not installed. Enable it in Windows Optional Features.& pause & exit /b 1)\r\nfor /f \"delims=\" %%U in ('whoami') do set \"SSH_USER=%%U\"\r\nicacls \"%~dp0id_ed25519\" /inheritance:r /grant:r \"%SSH_USER%:R\" >nul 2>&1\r\nssh -i \"%~dp0id_ed25519\" -o IdentitiesOnly=yes -o PreferredAuthentications=publickey -o PubkeyAuthentication=yes -o PasswordAuthentication=no -o KbdInteractiveAuthentication=no -o BatchMode=yes -o StrictHostKeyChecking=yes -o UserKnownHostsFile=\"%~dp0known_hosts\" ".$target."\r\npause\r\n";
        $linux="#!/bin/sh\nset -eu\nDIR=\$(CDPATH= cd -- \"\$(dirname -- \"$0\")\" && pwd)\nchmod 600 \"$DIR/id_ed25519\"\ncommand -v ssh >/dev/null 2>&1 || { echo 'OpenSSH client is not installed.'; exit 1; }\nexec ssh -i \"$DIR/id_ed25519\" -o IdentitiesOnly=yes -o PreferredAuthentications=publickey -o PubkeyAuthentication=yes -o PasswordAuthentication=no -o KbdInteractiveAuthentication=no -o BatchMode=yes -o StrictHostKeyChecking=yes -o UserKnownHostsFile=\"$DIR/known_hosts\" ".escapeshellarg($target)."\n";
        $readme="SSH access is ready for the account: ".$account['username']."\nServer address: ".$host."\n\nWindows: extract the files, then run connect-windows.bat.\nLinux: extract the files, then run connect-linux.sh in a terminal.\n\nThe connection does not ask for a username or a password. If the server rejects the key you will see an error instead of a password prompt. Keep the id_ed25519 file inside a private, safe folder and never send it to anyone; whoever holds it can sign in to this account. Deleting the package does not remove the key from the server. To delete the Login as keys created by File Manager, use the Revoke option in the Login as window.\n";
        $zip=$this->sshBuildZip([
            'id_ed25519'=>['data'=>$private,'mode'=>0600],
            'known_hosts'=>['data'=>implode("\n",array_unique($known))."\n",'mode'=>0644],
            'connect-windows.bat'=>['data'=>$win,'mode'=>0644],
            'connect-linux.sh'=>['data'=>$linux,'mode'=>0755],
            'README.txt'=>['data'=>$readme,'mode'=>0644]
        ]);
        if(strlen($zip)<22){
            @unlink($tmp);@unlink($tmp.'.pub');
            return['error'=>'Could not build the SSH connection package.'];
        }
        $added=$this->sshAppendLoginKey($account,$public);
        if(!empty($added['error'])){
            @unlink($tmp);@unlink($tmp.'.pub');
            return$added;
        }
        @unlink($tmp);@unlink($tmp.'.pub');
        $this->log('ssh_login_key_added',$account['username'].' ('.$nonce.')');
        return['ok'=>true,'bytes'=>$zip,'filename'=>'ssh-login-'.$account['username'].'.zip'];
    }

    private function sshBuildZip($files){
        $local='';$central='';$offset=0;$count=0;
        $now=getdate();$dosTime=(($now['hours']&31)<<11)|(($now['minutes']&63)<<5)|((int)($now['seconds']/2)&31);
        $dosDate=((max(1980,(int)$now['year'])-1980)<<9)|($now['mon']<<5)|$now['mday'];
        foreach($files as $name=>$entry){
            $data=(string)$entry['data'];$name=(string)$name;$nameLen=strlen($name);$size=strlen($data);
            $crc=hexdec(hash('crc32b',$data));$mode=0100000|((int)$entry['mode']&0777);
            $local.=pack('VvvvvvVVVvv',0x04034b50,20,0,0,$dosTime,$dosDate,$crc,$size,$size,$nameLen,0).$name.$data;
            $central.=pack('VvvvvvvVVVvvvvvVV',0x02014b50,0x0314,20,0,0,$dosTime,$dosDate,$crc,$size,$size,$nameLen,0,0,0,0,$mode<<16,$offset).$name;
            $offset=strlen($local);$count++;
        }
        return$local.$central.pack('VvvvvVVv',0x06054b50,0,0,$count,$count,strlen($central),strlen($local),0);
    }

    private function sshRevokeManagedKeyLine($account,$marker){
        $file=$account['home'].'/.ssh/authorized_keys';
        if(is_link($file)||!is_file($file))return false;
        $fp=@fopen($file,'r+b');
        if(!$fp)return false;
        if(!@flock($fp,LOCK_EX)){@fclose($fp);return false;}
        $backup=stream_get_contents($fp);
        if(!is_string($backup)){@flock($fp,LOCK_UN);@fclose($fp);return false;}
        $lines=preg_split('/\r\n|\n|\r/',$backup);
        $kept=[];$removed=0;
        foreach($lines as $line){
            if(preg_match('/(?:^|\s)'.preg_quote($marker,'/').'\r?$/',$line)){$removed++;continue;}
            $kept[]=$line;
        }
        if(!$removed){@flock($fp,LOCK_UN);@fclose($fp);return false;}
        $new=implode("\n",$kept);
        if($new!==''&&!str_ends_with($new,"\n"))$new.="\n";
        $written=false;
        if(@ftruncate($fp,0)&&@rewind($fp)){
            $written=@fwrite($fp,$new)===strlen($new)&&@fflush($fp);
        }
        if(!$written){
            @ftruncate($fp,0);@rewind($fp);@fwrite($fp,$backup);@fflush($fp);
            @flock($fp,LOCK_UN);@fclose($fp);return false;
        }
        @rewind($fp);$saved=stream_get_contents($fp);
        if($saved!==$new){
            @ftruncate($fp,0);@rewind($fp);@fwrite($fp,$backup);@fflush($fp);
            @flock($fp,LOCK_UN);@fclose($fp);return false;
        }
        @chmod($file,0600);@flock($fp,LOCK_UN);@fclose($fp);
        return$removed;
    }

    public function sshRevokeLoginKeys($uname){
        if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
        if($this->isRO())return['error'=>'Read-only account: SSH key revocation is disabled.'];
        $account=$this->sshTerminalAccount($uname,true);
        if(!empty($account['error']))return$account;
        $file=$account['home'].'/.ssh/authorized_keys';
        if(is_link($file)||!is_file($file))return['error'=>'No File Manager login keys were found for this account.'];
        $contents=@file_get_contents($file);
        if(!is_string($contents))return['error'=>'Could not read authorized_keys.'];
        preg_match_all('/(?:^|\s)(mfm-login-as-[a-f0-9]{24})\r?$/m',$contents,$matches);
        $markers=array_values(array_unique($matches[1]??[]));
        if(!$markers)return['error'=>'No File Manager login keys were found for this account.'];
        $removed=0;
        foreach($markers as $marker){$n=$this->sshRevokeManagedKeyLine($account,$marker);if(is_int($n))$removed+=$n;}
        if(!$removed)return['error'=>'Could not safely remove the File Manager login keys.'];
        $this->log('ssh_login_keys_revoked',$account['username'].' ('.$removed.')');
        return['ok'=>true,'removed'=>$removed];
    }

    /* ══ CMS detection & user management (WordPress / Joomla) ══ */
    /*
     * WordPress permits wp-config.php to live one directory above the public
     * site root. Keep the config path separate from the actual WordPress root
     * so MU-plugins, core updates, and recovery use the right wwwroot.
     */
    private function wpCurrentWebRoots(){
        $roots=[
            $_SERVER['DOCUMENT_ROOT']??null,
            __DIR__,
            dirname($_SERVER['SCRIPT_FILENAME']??''),
            $this->currentDir,
            getcwd(),
        ];
        $out=[];
        foreach($roots as $root){
            if(!$root)continue;
            $real=realpath($root);
            for($i=0;$real&&is_dir($real)&&$i<9;$i++){
                if(!in_array($real,$out,true))$out[]=$real;
                $parent=dirname($real);
                if($parent===$real)break;
                $real=$parent;
            }
        }
        return $out;
    }
    private function wpSiteRoot($configPath){
        $configPath=realpath($configPath)?:$configPath;
        $configDir=realpath(dirname($configPath))?:dirname($configPath);
        $candidates=[$configDir,dirname($configDir)];
        foreach($this->wpCurrentWebRoots() as $root){
            $candidates[]=$root;
            $candidates[]=dirname($root);
        }
        $candidates=array_values(array_unique(array_filter(array_map(function($p){
            $r=realpath($p);return $r&&is_dir($r)?$r:null;
        },$candidates))));
        $best=$configDir;$bestScore=-1;
        foreach($candidates as $dir){
            $score=0;
            if(is_dir($dir.'/wp-content'))$score+=5;
            if(is_dir($dir.'/wp-includes'))$score+=3;
            if(is_dir($dir.'/wp-admin'))$score+=3;
            if($dir===$configDir)$score+=2;
            foreach($this->wpCurrentWebRoots() as $current)if($dir===$current)$score+=2;
            if($score>$bestScore){$bestScore=$score;$best=$dir;}
        }
        return $best;
    }
    private function cmsCurrentSiteFromScan($sites,$type=null){
        $roots=$this->wpCurrentWebRoots();$best=null;$bestScore=0;
        foreach((array)$sites as $site){
            if($type!==null&&($site['type']??'')!==$type)continue;
            $dir=realpath($site['dir']??dirname($site['config']??''))?:dirname($site['config']??'');
            if(!$dir)continue;
            $score=0;
            foreach($roots as $root){
                if($dir===$root)$score=max($score,1000);
                elseif(strpos($root,rtrim($dir,'/').'/')===0)$score=max($score,900-strlen($root)+strlen($dir));
                elseif(strpos($dir,rtrim($root,'/').'/')===0)$score=max($score,800-strlen($dir)+strlen($root));
                if(dirname($site['config']??'')===$root)$score=max($score,950);
            }
            if($score>$bestScore){$bestScore=$score;$best=$site;}
        }
        return $best;
    }
    private function wpCurrentSiteFromScan($sites){
        return $this->cmsCurrentSiteFromScan($sites,'wordpress');
    }
    private function wpCurrentDomainConfig($sites=[]){
        /* The current folder is the strongest signal. A domain can be nested
           several levels below the file manager's own directory, and a broad
           scan can otherwise select a neighbouring site's wp-config.php. */
        $starts=[];
        foreach([$this->currentDir,$_SERVER['DOCUMENT_ROOT']??null,__DIR__,dirname($_SERVER['SCRIPT_FILENAME']??'')] as $start){
            $real=$start?realpath($start):false;
            if($real&&!in_array($real,$starts,true))$starts[]=$real;
        }
        foreach($starts as $start){
            $probe=$start;
            for($i=0;$probe&&$i<64;$i++){
                $cfg=rtrim($probe,'/').'/wp-config.php';
                if(is_file($cfg)&&is_readable($cfg))return realpath($cfg)?:$cfg;
                $parent=dirname($probe);if($parent===$probe)break;$probe=$parent;
            }
