            foreach([$root,dirname($root),dirname(dirname($root))] as $probe){
                $cfg=rtrim($probe,'/').'/wp-config.php';
                if(is_file($cfg)&&is_readable($cfg))return realpath($cfg)?:$cfg;
            }
        }
        $site=$this->wpCurrentSiteFromScan($sites);
