    public function cmsDetect($dir){
        $dir=realpath($dir)?:rtrim($dir,'/');
        /* Resolve the installation nearest to the folder being browsed.
           This handles /domain/public_html/site/a/b/... without requiring a
           recursive scan and also keeps sibling domains separate. */
        $probe=$dir;
        for($i=0;$probe&&$i<64;$i++){
            $wp=$probe.'/wp-config.php';
            if(is_file($wp)&&is_readable($wp))return['type'=>'wordpress','config'=>realpath($wp)?:$wp];
            $joomla=$probe.'/configuration.php';
            if(is_file($joomla)&&strpos((string)@file_get_contents($joomla),'JConfig')!==false)return['type'=>'joomla','config'=>realpath($joomla)?:$joomla];
            $parent=dirname($probe);if($parent===$probe)break;$probe=$parent;
        }
        return['type'=>null];
    }
    private function cmsInstallerBase(){
        $base=$this->root?:__DIR__;
        return realpath($base)?:rtrim($base,'/');
    }
    private function cmsInstallerWithin($path,$base){
        $path=rtrim((string)$path,'/\\');$base=rtrim((string)$base,'/\\');
        return $path===$base||strpos($path.$this->pathSep(),$base.$this->pathSep())===0;
    }
    private function cmsInstallerPublicUrl($target,$type){
        $docroot=realpath((string)($_SERVER['DOCUMENT_ROOT']??''));$target=realpath((string)$target);
        if($docroot===false||$target===false||!$this->cmsInstallerWithin($target,$docroot))return'';
        $base=rtrim($docroot,'/\\');if($base==='')$base=DIRECTORY_SEPARATOR;
        $relative=$base===DIRECTORY_SEPARATOR?ltrim($target,DIRECTORY_SEPARATOR):ltrim(substr($target,strlen($base)),'/\\');
        $parts=array_values(array_filter(explode(DIRECTORY_SEPARATOR,$relative),function($part){return$part!=='';}));
        $url='/'.implode('/',array_map('rawurlencode',$parts));if($url!=='/')$url.='/';
        return$url.($type==='joomla'?'installation/':'wp-admin/install.php');
    }
    private function pathSep(){return DIRECTORY_SEPARATOR;}
    private function cmsInstallerResolveTarget($raw,&$error=null){
        $error=null;$raw=trim((string)$raw);
        if($raw==='')$raw=$this->currentDir.DIRECTORY_SEPARATOR.'cms-site';
        if($raw[0]!=='/'&&!preg_match('/^[A-Za-z]:[\\\\\/]/',$raw))$raw=$this->currentDir.DIRECTORY_SEPARATOR.$raw;
        $raw=str_replace(['\\','/'],DIRECTORY_SEPARATOR,$raw);
        $segments=[];$probe=$raw;$guard=0;
        while(!is_dir($probe)&&$guard++<64){
            $name=basename($probe);
            if($name===''||$name==='.'||$name==='..'||!preg_match('/^[A-Za-z0-9._-]+$/',$name)){
                $error='The target directory name contains unsupported characters.';return null;
            }
            array_unshift($segments,$name);$next=dirname($probe);
            if($next===$probe){$error='The target directory could not be resolved.';return null;}
            $probe=$next;
        }
        $parent=realpath($probe);
        if($parent===false||!is_dir($parent)){$error='The target parent directory does not exist.';return null;}
        $target=$parent;
        foreach($segments as $segment)$target.=$this->pathSep().$segment;
        if(is_link($raw)&&realpath($raw)!==false)$target=realpath($raw);
        $base=$this->cmsInstallerBase();
        if(!$this->cmsInstallerWithin($target,$base)){$error='The target directory must be inside the authorized File Manager workspace.';return null;}
        return rtrim($target,DIRECTORY_SEPARATOR);
    }
    private function cmsInstallerExisting($target){
        $markers=[];
        if(is_file($target.'/wp-config.php'))$markers[]='wp-config.php';
        if(is_file($target.'/configuration.php')&&strpos((string)@file_get_contents($target.'/configuration.php'),'JConfig')!==false)$markers[]='configuration.php';
        if(is_dir($target.'/wp-admin')&&is_dir($target.'/wp-includes'))$markers[]='WordPress core directories';
        if(is_dir($target.'/administrator')&&is_dir($target.'/libraries')&&is_file($target.'/index.php'))$markers[]='Joomla core directories';
        return $markers;
    }
    private function cmsInstallerClearTree($dir){
        if(!is_dir($dir))return;
        foreach(@scandir($dir)?:[] as $name){
            if($name==='.'||$name==='..')continue;
            $p=$dir.DIRECTORY_SEPARATOR.$name;
            if(is_link($p)||is_file($p)){@unlink($p);continue;}
            if(is_dir($p)){$this->cmsInstallerClearTree($p);@rmdir($p);}
        }
    }
    private function cmsInstallerRemoveTree($dir){
        if(!file_exists($dir)&&!is_link($dir))return;
        if(is_link($dir)||is_file($dir)){@unlink($dir);return;}
        $this->cmsInstallerClearTree($dir);@rmdir($dir);
    }
    private function cmsInstallerCopyTree($source,$target,&$error=null){
        $error=null;
        if(!is_dir($target)&&!@mkdir($target,0755,true)){$error='The installer could not create the target directory.';return false;}
        foreach(@scandir($source)?:[] as $name){
            if($name==='.'||$name==='..')continue;
            $src=$source.DIRECTORY_SEPARATOR.$name;$dst=$target.DIRECTORY_SEPARATOR.$name;
            if(is_link($src)){$error='The official package contains an unsafe symbolic link.';return false;}
            if(is_dir($src)){
                if(!$this->cmsInstallerCopyTree($src,$dst,$error))return false;
                @chmod($dst,0755);
            }elseif(is_file($src)){
                if(file_exists($dst)||!@copy($src,$dst)){$error='The installer could not write '.$name.'.';return false;}
                @chmod($dst,0644);
            }
        }
        return true;
    }
    private function cmsInstallerDownload($url,$destination,&$error=null){
        $error=null;$fp=@fopen($destination,'wb');
        if(!$fp){$error='The installer could not create its temporary download file.';return false;}
        $ok=false;$code=0;
        if(function_exists('curl_init')){
            $ch=curl_init($url);
            curl_setopt_array($ch,[CURLOPT_FILE=>$fp,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>4,CURLOPT_CONNECTTIMEOUT=>15,CURLOPT_TIMEOUT=>240,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_USERAGENT=>'Syrah File Manager CMS Installer/1.0',CURLOPT_FAILONERROR=>true,CURLOPT_MAXFILESIZE=>128*1024*1024]);
            $ok=curl_exec($ch)!==false;$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$ce=curl_error($ch);curl_close($ch);
            if(!$ok&&$ce!=='')$error='Official package download failed: '.$ce;
        }else{
            $ctx=stream_context_create(['http'=>['method'=>'GET','timeout'=>240,'follow_location'=>1,'max_redirects'=>4,'ignore_errors'=>false,'header'=>"User-Agent: Syrah File Manager CMS Installer/1.0\r\n"],'https'=>['method'=>'GET','timeout'=>240,'follow_location'=>1,'max_redirects'=>4,'ignore_errors'=>false,'header'=>"User-Agent: Syrah File Manager CMS Installer/1.0\r\n"]]);
            $in=@fopen($url,'rb',false,$ctx);
