                    $chunk=@fread($in,1024*1024);
                    if($chunk===false){$error='Official package download was interrupted.';break;}
                    $bytes+=strlen($chunk);
                    if($bytes>128*1024*1024){$error='The official package is larger than the safe download limit.';break;}
                    if($chunk!==''&&!@fwrite($fp,$chunk)){$error='The installer could not save the official package.';break;}
                }
                @fclose($in);$ok=$error===null;
            }else $error='Official package download failed.';
        }
        @fclose($fp);
        clearstatcache(true,$destination);
        if(!$ok||!is_file($destination)||(int)@filesize($destination)<1024){
            if($error===null)$error='The official package returned an empty or invalid response.'.($code?' HTTP '.$code:'');
            @unlink($destination);return false;
        }
        return true;
    }
    private function cmsInstallerJoomlaUrl(&$version=null,&$error=null){
        $version='';$error=null;
        $pageUrl='https://downloads.joomla.org/latest';
        $html=false;
        if(function_exists('curl_init')){
            $ch=curl_init($pageUrl);
            curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>3,CURLOPT_CONNECTTIMEOUT=>15,CURLOPT_TIMEOUT=>45,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_IPRESOLVE=>CURL_IPRESOLVE_V4,CURLOPT_USERAGENT=>'Syrah File Manager CMS Installer/1.0',CURLOPT_MAXFILESIZE=>2*1024*1024]);
            $html=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$ce=curl_error($ch);curl_close($ch);
            if($html===false||$code<200||$code>=400){$error='The official Joomla download page could not be read.'.($ce?' '.$ce:'');return false;}
        }else{
            $ctx=stream_context_create(['http'=>['method'=>'GET','timeout'=>45,'follow_location'=>1,'max_redirects'=>3,'ignore_errors'=>false,'header'=>"User-Agent: Syrah File Manager CMS Installer/1.0\r\n"],'https'=>['method'=>'GET','timeout'=>45,'follow_location'=>1,'max_redirects'=>3,'ignore_errors'=>false,'header'=>"User-Agent: Syrah File Manager CMS Installer/1.0\r\n"]]);
            $html=@file_get_contents($pageUrl,false,$ctx);
            if($html===false){$error='The official Joomla download page could not be read.';return false;}
        }
        if(!is_string($html)||strlen($html)>2*1024*1024){$error='The official Joomla download page returned an invalid response.';return false;}
        $links=[];
        if(preg_match_all('/(?:href|data-href)\s*=\s*["\']([^"\']+\.tar\.gz(?:\?[^"\']*)?)["\']/i',$html,$matches)){
            foreach($matches[1] as $raw){
                $raw=html_entity_decode(trim((string)$raw),ENT_QUOTES|ENT_HTML5,'UTF-8');
                if(stripos($raw,'/cms/joomla')!==0||stripos($raw,'full_package')===false)continue;
                $url='https://downloads.joomla.org'.$raw;
                $major=0;$ver='';
                if(preg_match('#/joomla([0-9]+)/([0-9][^/]+)/#i',$raw,$vm)){$major=(int)$vm[1];$ver=$vm[2];}
                /* Joomla 6 requires PHP 8.3+, while Joomla 5 supports PHP
                   8.1+. The downloads page lists the newest branch first;
                   skip a branch the current server cannot run instead of
                   downloading it and failing later during bootstrap. */
                if($major>=6&&PHP_VERSION_ID<80300)continue;
                if($major>0)$links[]=['url'=>$url,'version'=>$ver,'major'=>$major];
            }
        }
        if(!$links){$error='The official Joomla download page did not expose a supported full-package archive.';return false;}
        $version=$links[0]['version']?:'latest';
        return $links[0]['url'];
    }
    private function cmsInstallerExtract($archive,$stage,&$packageRoot,&$error=null){
        $packageRoot=null;$error=null;
        $tar='tar';
        foreach(['/usr/bin/tar','/bin/tar'] as $candidate)if(is_executable($candidate)){$tar=$candidate;break;}
        if(!function_exists('exec')){$error='The server does not provide a safe archive extraction command (tar or exec is unavailable).';return false;}
        $list=[];$exit=1;
        @exec(escapeshellarg($tar).' -tzf '.escapeshellarg($archive).' 2>&1',$list,$exit);
        if($exit!==0||!$list){$error='The official package is not a valid gzip tar archive.';return false;}
        $count=0;
        foreach($list as $entry){
            $name=str_replace('\\','/',trim((string)$entry));
            if($name===''||preg_match('#^(?:/|[A-Za-z]:[\\\\/])#',$name)||preg_match('#(^|/)\.\.?(/|$)#',$name)||strlen($name)>1024)
                {$error='The downloaded archive contains an unsafe path.';return false;}
            if(++$count>30000){$error='The downloaded archive contains too many files.';return false;}
        }
        $details=[];$detailExit=1;
        @exec(escapeshellarg($tar).' -tvzf '.escapeshellarg($archive).' 2>&1',$details,$detailExit);
        if($detailExit!==0){$error='The official package could not be inspected safely.';return false;}
        foreach($details as $line)if(isset($line[0])&&in_array($line[0],['l','h'],true)){$error='The official package contains an unsafe symbolic or hard link.';return false;}
        if(!@mkdir($stage,0700,true)){$error='The temporary extraction directory could not be created.';return false;}
        $out=[];$extractExit=1;
        @exec(escapeshellarg($tar).' --no-same-owner --no-same-permissions -xzf '.escapeshellarg($archive).' -C '.escapeshellarg($stage).' 2>&1',$out,$extractExit);
        if($extractExit!==0){$error='The official package could not be extracted safely.';return false;}
        $candidate=$stage;
        foreach(['wordpress','joomla'] as $wrapper)if(is_dir($stage.'/'.$wrapper)&&is_file($stage.'/'.$wrapper.'/index.php')){$candidate=$stage.'/'.$wrapper;break;}
        if(!is_file($candidate.'/index.php')){$error='The official package did not contain a valid CMS root.';return false;}
        $packageRoot=$candidate;return true;
    }
    private function cmsInstallerDb($host,$port,$db,$user,$pass,&$error=null){
        $error=null;$host=trim((string)$host);$port=(int)$port;$db=trim((string)$db);$user=(string)$user;$pass=(string)$pass;$socket=null;
        if(preg_match('#^([^:]+):(/.+)$#',$host,$m)){$host=$m[1];$socket=$m[2];}
        elseif($host!==''&&$host[0]==='/'){$socket=$host;$host='localhost';}
        if($db===''||!preg_match('/^[A-Za-z0-9_$-]{1,64}$/',$db)){$error='Use a valid MySQL database name.';return null;}
        if($user===''||strlen($user)>128){$error='A database username is required.';return null;}
        if($host===''){$error='Enter the database host found in its configuration or provided by your hosting provider.';return null;}
        if(!$socket&&($port<1||$port>65535)){$error='Enter the database port found in its configuration or provided by your hosting provider.';return null;}
        if(!extension_loaded('mysqli')){$error='The mysqli PHP extension is not available.';return null;}
        mysqli_report(MYSQLI_REPORT_OFF);$link=@mysqli_init();
        if(!$link||!@mysqli_options($link,MYSQLI_OPT_CONNECT_TIMEOUT,10)||!@mysqli_real_connect($link,$host,$user,$pass,'',$port?:null,$socket)){
            $error='The installer could not connect to MySQL with the supplied credentials.';return null;
        }
        $quoted='`'.str_replace('`','``',$db).'`';
        @mysqli_query($link,"CREATE DATABASE IF NOT EXISTS ".$quoted." CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
        if(!@mysqli_select_db($link,$db)){
            @mysqli_close($link);$error='The database does not exist and this account could not create it.';return null;
        }
        @mysqli_set_charset($link,'utf8mb4');
        return $link;
    }
    private function cmsInstallerWpConfig($target,$db,$user,$pass,$host,$port,$prefix){
        $salts=[];for($i=0;$i<8;$i++)$salts[]=bin2hex(function_exists('random_bytes')?random_bytes(32):openssl_random_pseudo_bytes(32));
        $keys=['AUTH_KEY','SECURE_AUTH_KEY','LOGGED_IN_KEY','NONCE_KEY','AUTH_SALT','SECURE_AUTH_SALT','LOGGED_IN_SALT','NONCE_SALT'];
        $out="<?php\n";
        foreach(['DB_NAME'=>$db,'DB_USER'=>$user,'DB_PASSWORD'=>$pass,'DB_HOST'=>$host.($port&&$port!==3306?':'.$port:'')] as $k=>$v)$out.="define('".$k."', ".var_export($v,true).");\n";
        $out.="$"."table_prefix = ".var_export($prefix,true).";\n";
        foreach($keys as $i=>$k)$out.="define('".$k."', ".var_export($salts[$i],true).");\n";
        $out.="define('DB_CHARSET', 'utf8mb4');\ndefine('DB_COLLATE', '');\n";
        $out.="if (!defined('ABSPATH')) define('ABSPATH', __DIR__ . '/');\nrequire_once ABSPATH . 'wp-settings.php';\n";
        return @file_put_contents($target.'/wp-config.php',$out,LOCK_EX)!==false;
    }
    private function cmsInstallerRunJoomlaCli($target,$siteTitle,$adminUser,$adminPass,$adminEmail,$db,$user,$pass,$host,$port,$prefix,&$output=null){
        $output='';$script=$target.'/installation/joomla.php';
        if(!is_file($script)||!function_exists('proc_open'))return false;
        $php=defined('PHP_BINARY')?PHP_BINARY:'php';
        $args=[$php,$script,'install','--site-name='.$siteTitle,'--admin-user='.$adminUser,'--admin-username='.$adminUser,'--admin-password='.$adminPass,'--admin-email='.$adminEmail,'--db-type=mysqli','--db-host='.$host,'--db-name='.$db,'--db-user='.$user,'--db-pass='.$pass,'--db-prefix='.$prefix,'--db-encryption=0','--db-sslverifyservercert=0'];
        $cmd=implode(' ',array_map('escapeshellarg',$args));
        $spec=[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']];$proc=@proc_open($cmd,$spec,$pipes,$target);
        if(!is_resource($proc))return false;
        @fclose($pipes[0]);$start=microtime(true);
        while(true){$status=proc_get_status($proc);if(!$status['running']||microtime(true)-$start>180)break;usleep(100000);}
        if(!empty($status['running'])){@proc_terminate($proc);$output='Joomla command-line installation timed out.';}
        $output=trim((string)stream_get_contents($pipes[1])."\n".(string)stream_get_contents($pipes[2]));@fclose($pipes[1]);@fclose($pipes[2]);$exit=proc_close($proc);
        return $exit===0&&is_file($target.'/configuration.php');
    }
    public function cmsInstallerDiscoverDb(){
        if(!extension_loaded('mysqli'))return['ok'=>true,'found'=>false,'tested'=>0,'message'=>'The mysqli extension is not available.'];
        $scan=$this->sqlScan();$seen=[];$tested=0;
        foreach(($scan['databases']??[]) as $candidate){
            if(strtolower((string)($candidate['driver']??''))!=='mysql')continue;
            $hostExplicit=!empty($candidate['host_explicit']);
            $host=$hostExplicit?trim((string)($candidate['host']??'')):trim((string)ini_get('mysqli.default_host'));
            $socket=trim((string)($candidate['socket']??''));
            if($host!==''&&$host[0]==='/'){$socket=$host;$host=trim((string)ini_get('mysqli.default_host'));}
            if($socket&&$host==='')$host='localhost';
            $user=(string)($candidate['user']??'');$pass=(string)($candidate['pass']??'');
            $db=trim((string)($candidate['db']??''));$port=0;
            if(!empty($candidate['port_explicit']))$port=(int)($candidate['port']??0);
            else{
                $runtimePort=(int)ini_get('mysqli.default_port');
                if($runtimePort>0&&$runtimePort<=65535)$port=$runtimePort;
            }
            if($user===''||$db===''||$host===''||(!$socket&&($port<1||$port>65535)))continue;
            $fingerprint=hash('sha256',implode("\0",[$host,(string)$port,$socket,$user,$pass,$db]));
            if(isset($seen[$fingerprint]))continue;$seen[$fingerprint]=true;
            if($tested>=12)break;$tested++;
            $link=@mysqli_init();if(!$link)continue;
            @mysqli_options($link,MYSQLI_OPT_CONNECT_TIMEOUT,2);
            $connected=@mysqli_real_connect($link,$host,$user,$pass,$db,$port?:null,$socket?:null);
            if($connected){
                @mysqli_close($link);
                $displayHost=$socket?($host.':'.$socket):$host;
                return['ok'=>true,'found'=>true,'tested'=>$tested,'source_type'=>(string)($candidate['type']??'database config'),
                    'source_db'=>$db,'credentials'=>['host'=>$displayHost,'port'=>$socket?'':$port,'user'=>$user,'pass'=>$pass]];
            }
            @mysqli_close($link);
        }
        return['ok'=>true,'found'=>false,'tested'=>$tested,'message'=>$tested
            ?'No working MySQL login was found in the first saved configuration entries checked.'
            :'No complete MySQL username and database were found in readable configurations.'];
    }
    public function cmsInstallerStatus($target=''){
        $requirements=['mysqli'=>'Required for database installation','json'=>'Required by both CMSs','openssl'=>'Required for secure salts and HTTPS'];
        foreach(['mbstring','xml','curl','zip','intl'] as $ext)$requirements[$ext]='Recommended or required by some CMS features';
        $checks=[];foreach($requirements as $ext=>$label)$checks[]=['extension'=>$ext,'label'=>$label,'available'=>extension_loaded($ext)];
        $base=$this->cmsInstallerBase();$det=$this->cmsDetect($this->currentDir);$free=@disk_free_space($base);
        return['ok'=>true,'php_version'=>PHP_VERSION,'server_software'=>(string)($_SERVER['SERVER_SOFTWARE']??'unknown'),'sapi'=>PHP_SAPI,'current_directory'=>$this->currentDir,'workspace'=>$base,'current_cms'=>$det,'requirements'=>$checks,'free_bytes'=>$free===false?0:$free,'workspace_writable'=>is_writable($base),'installer_available'=>!$this->readonly&&extension_loaded('mysqli'),'message'=>$this->readonly?'The current account is read-only.':(empty($det['type'])?'No CMS was detected in the current directory.':'A CMS is already detected in the current directory; choose a new empty target directory.')];
    }
    public function cmsInstall($input){
        if($this->readonly)return['ok'=>false,'error'=>'The current account is read-only.'];
        $type=strtolower(trim((string)($input['cms_type']??'')));
        if(!in_array($type,['wordpress','joomla'],true))return['ok'=>false,'error'=>'Choose WordPress or Joomla.'];
        $error='';$target=$this->cmsInstallerResolveTarget($input['target_dir']??'',$error);
        if(!$target)return['ok'=>false,'error'=>$error];
        $existing=$this->cmsInstallerExisting($target);
        if($existing)return['ok'=>false,'error'=>'Installation stopped: the target already contains '.implode(', ',$existing).'. The installer never overwrites an existing CMS.'];
        $entries=@scandir($target);$targetExists=is_dir($target);
        if($targetExists&&is_array($entries)&&count(array_diff($entries,['.','..']))>0)return['ok'=>false,'error'=>'The target directory is not empty. Choose an empty directory so existing files cannot be overwritten.'];
        $parent=dirname($target);if(!is_writable($parent)&&(!$targetExists||!is_writable($target)))return['ok'=>false,'error'=>'The target directory is not writable by PHP.'];
        $version=(string)($input['cms_version']??'');
        if($type==='wordpress')$url='https://wordpress.org/latest.tar.gz';
        else{
            $resolvedVersion='';$url=$this->cmsInstallerJoomlaUrl($resolvedVersion,$error);
            if(!$url)return['ok'=>false,'error'=>$error?:'The official Joomla package URL could not be resolved.'];
            if($version==='')$version=$resolvedVersion;
        }
        $siteTitle=trim((string)($input['site_title']??'My Site'));$siteTitle=substr($siteTitle,0,120)?:'My Site';
        $adminUser=trim((string)($input['admin_user']??''));$adminPass=(string)($input['admin_password']??'');$adminEmail=trim((string)($input['admin_email']??''));
        if(!preg_match('/^[A-Za-z0-9._-]{2,60}$/',$adminUser))return['ok'=>false,'error'=>'Use a valid administrator username.'];
        if(strlen($adminPass)<10)return['ok'=>false,'error'=>'The administrator password must be at least 10 characters.'];
        if(!filter_var($adminEmail,FILTER_VALIDATE_EMAIL))return['ok'=>false,'error'=>'Use a valid administrator email address.'];
        $host=trim((string)($input['db_host']??''));$port=(int)($input['db_port']??0);$db=trim((string)($input['db_name']??''));$dbUser=(string)($input['db_user']??'');$dbPass=(string)($input['db_password']??'');$prefix=trim((string)($input['db_prefix']??($type==='wordpress'?'wp_':'j_')));
        if(!preg_match('/^[A-Za-z][A-Za-z0-9_]{1,30}$/',$prefix))return['ok'=>false,'error'=>'Use a valid database table prefix.'];
        if(PHP_VERSION_ID<($type==='wordpress'?70300:80100))return['ok'=>false,'error'=>'This CMS requires a newer PHP version. Current PHP is '.PHP_VERSION.'.'];
        foreach(['mysqli','json','openssl'] as $ext)if(!extension_loaded($ext))return['ok'=>false,'error'=>'Required PHP extension is missing: '.$ext.'.'];
        if($type==='joomla'&&!extension_loaded('mbstring'))return['ok'=>false,'error'=>'Joomla requires the mbstring PHP extension.'];
        $free=@disk_free_space($parent);if($free!==false&&$free<100*1024*1024)return['ok'=>false,'error'=>'At least 100 MB of free disk space is required before installation.'];
        $link=$this->cmsInstallerDb($host,$port,$db,$dbUser,$dbPass,$error);if(!$link)return['ok'=>false,'error'=>$error];@mysqli_close($link);
        $token=bin2hex(function_exists('random_bytes')?random_bytes(12):openssl_random_pseudo_bytes(12));$tmpBase=$parent.DIRECTORY_SEPARATOR.'.fm-cms-installer-'.$token;$archive=$tmpBase.'.tar.gz';$stage=$tmpBase.'.stage';$packageRoot=null;$createdTarget=false;$warning='';
        try{
