            $createdTarget=true;
            if(!$this->cmsInstallerExtract($archive,$stage,$packageRoot,$error))throw new RuntimeException($error);
            if(!$this->cmsInstallerCopyTree($packageRoot,$target,$error))throw new RuntimeException($error);
            if($type==='wordpress'){
                if(!$this->cmsInstallerWpConfig($target,$db,$dbUser,$dbPass,$host,$port,$prefix))throw new RuntimeException('WordPress configuration could not be written.');
                $oldCwd=getcwd();$installed=false;$installError='';
                try{
