                    chdir($target);ob_start();require_once $target.'/wp-load.php';require_once $target.'/wp-admin/includes/upgrade.php';
                    if(function_exists('wp_install')){$result=wp_install($siteTitle,$adminUser,$adminEmail,true,'',$adminPass);$installed=!empty($result);}
                    ob_end_clean();
