            }else{
                $cliOutput='';$complete=$this->cmsInstallerRunJoomlaCli($target,$siteTitle,$adminUser,$adminPass,$adminEmail,$db,$dbUser,$dbPass,$host,$port,$prefix,$cliOutput);
                if(!$complete)$warning='Joomla files were installed and the database connection was verified. Finish the official web installer at /installation/ to create the Joomla tables and administrator account.'.($cliOutput?' Installer output: '.substr(preg_replace('/\s+/',' ',$cliOutput),0,180):'');
            }
