        if(!$ok)return['error'=>'Could not remove the recovery schedule.'];
        $this->log('wp_recovery_remove',$plugin);return['ok'=>true];
    }

    /* ── WordPress core version manager ─────────────────────────────────────
       Core updates deliberately use the official WordPress.org archives rather
       than WP-CLI or database writes. wp-config.php and wp-content are never
       replaced. The old core is moved aside during the transaction instead of
       being copied into a slow full-site archive. */
    private function wpCoreVersionFromFile($root){
        $file=rtrim($root,'/').'/wp-includes/version.php';
        $src=@file_get_contents($file);
        if($src!==false&&preg_match('/\$wp_version\s*=\s*[\'"]([^\'"]+)[\'"]\s*;/',$src,$m))return trim($m[1]);
        return '';
    }
    private function wpCoreHttp($url,$timeout=45){
        if(!function_exists('curl_init'))return[false,'PHP cURL is not available.'];
        $ch=curl_init($url);
        curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>4,
            CURLOPT_CONNECTTIMEOUT=>12,CURLOPT_TIMEOUT=>$timeout,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,
            CURLOPT_USERAGENT=>'Syrah File Manager WordPress Core Manager/1.0']);
        $body=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);
        if($body===false||$err)return[false,'Download failed'.($err?': '.$err:'').'.'];
        if($code<200||$code>=300)return[false,'WordPress.org returned HTTP '.$code.'.'];
        return[$body,''];
    }
    private function wpCoreVersionValid($version){
        return (bool)preg_match('/^\d+\.\d+(?:\.\d+)?$/',$version);
    }
    public function wpCoreVersionData($configPath){
        if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
        $root=dirname($configPath);
        if(basename($configPath)!=='wp-config.php'||!is_file($root.'/wp-includes/version.php'))return['error'=>'This feature requires a valid WordPress installation.'];
        $current=$this->wpCoreVersionFromFile($root);
        if(!$current)return['error'=>'Could not read the installed WordPress version.'];
        list($json,$err)=$this->wpCoreHttp('https://api.wordpress.org/core/version-check/1.7/?php='.rawurlencode(PHP_VERSION).'&locale=en_US',20);
        if($json===false)return['current'=>$current,'versions'=>[],'error'=>$err];
        $data=json_decode($json,true);$versions=[];
        foreach((array)($data['offers']??[]) as $offer){
            $v=trim((string)($offer['version']??''));
            if($this->wpCoreVersionValid($v)&&!isset($versions[$v]))$versions[$v]=['version'=>$v,'download'=>$offer['download']??'','response'=>$offer['response']??'upgrade'];
        }
        // The API is a rolling feed. Keep the exact-version box useful for
        // older releases even when a host/API omits them from the feed.
        krsort($versions,SORT_NATURAL);
        return['ok'=>true,'type'=>'wordpress','current'=>$current,'latest'=>($data['offers'][0]['version']??$current),
            'versions'=>array_values($versions),'php'=>PHP_VERSION];
    }
    private function wpCoreCopyTree($src,$dst,$skipRoot=false){
        if(!is_dir($dst)&&!@mkdir($dst,0755,true)&&!is_dir($dst))return false;
        foreach((array)@scandir($src) as $name){
            if($name==='.'||$name==='..')continue;
            if($skipRoot&&in_array($name,['wp-config.php','wp-content'],true))continue;
            // Never overwrite the file manager when it is installed in the
            // same document root as the WordPress site.
            if($skipRoot&&$name===basename(__FILE__)&&realpath(__FILE__)===realpath($dst.'/'.$name))continue;
            $s=$src.'/'.$name;$d=$dst.'/'.$name;
            if(is_dir($s)){if(!$this->wpCoreCopyTree($s,$d,false))return false;}
            elseif(is_file($s)&&@copy($s,$d)===false)return false;
        }
        return true;
    }
    private function wpCoreRemoveTree($path){
        if(!is_dir($path))return true;
        foreach((array)@scandir($path) as $n){
            if($n==='.'||$n==='..')continue;
            $p=$path.'/'.$n;
            if(is_dir($p)&&!is_link($p))$this->wpCoreRemoveTree($p);
            else @unlink($p);
        }
        return @rmdir($path);
    }
    private function wpCoreBackup($root,$backup){
        if(!class_exists('ZipArchive'))return[false,'PHP ZIP extension is required to create a safety backup.'];
        $dir=dirname($backup);if(!is_dir($dir)&&!@mkdir($dir,0700,true))return[false,'Could not create the backup directory.'];
        $z=new ZipArchive();if($z->open($backup,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)return[false,'Could not open the backup archive.'];
        $base=rtrim($root,'/');
        $add=function($path,$name)use(&$add,$z,$base){
            if(is_link($path))return;
            if(is_dir($path)){
                $z->addEmptyDir($name);
                foreach((array)@scandir($path) as $n)if($n!=='.'&&$n!=='..')$add($path.'/'.$n,$name.'/'.$n);
            }elseif(is_file($path))$z->addFile($path,$name);
        };
        foreach((array)@scandir($base) as $n)if($n!=='.'&&$n!=='..')$add($base.'/'.$n,$n);
        $ok=$z->close();return[$ok,$ok?'':'Could not finalize the safety backup.'];
    }
    public function wpCoreUpdate(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $configPath=$this->cmsCfgFromPost();$version=trim((string)($_POST['wp_version']??''));
        if(basename($configPath)!=='wp-config.php'||!$this->wpCoreVersionValid($version)){$this->addMsg('Choose a valid WordPress version.','danger');return;}
        $root=$this->wpSiteRoot($configPath);$current=$this->wpCoreVersionFromFile($root);
        if(!$current){$this->addMsg('Could not read the installed WordPress version.','danger');return;}
        if($version===$current){$this->addMsg('WordPress is already running version '.$version.'.','warning');return;}
        $lock=$root.'/.fm-wp-core-update.lock';
        if(is_file($lock)&&time()-(int)@file_get_contents($lock)<900){$this->addMsg('Another WordPress update is already in progress.','danger');return;}
        @file_put_contents($lock,(string)time(),LOCK_EX);
        $tmp=rtrim(sys_get_temp_dir(),'/').'/fm-wp-'.bin2hex(random_bytes(6));@mkdir($tmp,0700,true);
        $zip=$tmp.'/wordpress.zip';$token=bin2hex(random_bytes(5));$previous=$root.'/.fm-wp-core-previous-'.$token;
        $movedFiles=[];$movedDirs=[];
        try{
            list($raw,$err)=$this->wpCoreHttp('https://wordpress.org/wordpress-'.$version.'.zip',120);
            if($raw===false){$this->addMsg($err,'danger');return;}
            if(@file_put_contents($zip,$raw,LOCK_EX)===false){$this->addMsg('Could not save the WordPress archive.','danger');return;}
            if(!class_exists('ZipArchive')){$this->addMsg('PHP ZIP extension is required to install WordPress.','danger');return;}
            $z=new ZipArchive();if($z->open($zip)!==true||$z->extractTo($tmp)===false){$this->addMsg('The WordPress archive is invalid or could not be extracted.','danger');return;}$z->close();
            $stage=$tmp.'/wordpress';$stageVersion=$this->wpCoreVersionFromFile($stage);
            if(!$stageVersion||$stageVersion!==$version){$this->addMsg('The downloaded archive did not contain the requested WordPress version.','danger');return;}
            if(!@mkdir($previous,0700)&&!is_dir($previous)){$this->addMsg('Could not prepare the fast update transaction. Check permissions.','danger');return;}
            // Rename the two large core directories: this is near-instant and
            // preserves an exact rollback copy without duplicating wp-content.
            foreach(['wp-admin','wp-includes'] as $dir){
                $old=$root.'/'.$dir;
                if(is_dir($old)&&!@rename($old,$previous.'/'.$dir)){throw new RuntimeException('Could not move '.$dir.' into the update transaction.');}
                if(is_dir($previous.'/'.$dir))$movedDirs[]=$dir;
            }
            // Root core files are small. Move them too so a failed copy can be
            // rolled back exactly, while leaving custom/unrelated files alone.
            foreach((array)@scandir($stage) as $name){
                if($name==='.'||$name==='..'||$name==='wp-admin'||$name==='wp-includes'||$name==='wp-content'||$name==='wp-config.php'||$name===basename(__FILE__))continue;
                $old=$root.'/'.$name;
                if(is_file($old)){
                    if(!@rename($old,$previous.'/'.$name))throw new RuntimeException('Could not move core file '.$name.' into the update transaction.');
                    $movedFiles[]=$name;
                }
            }
            if(!$this->wpCoreCopyTree($stage,$root,true))throw new RuntimeException('Core files could not be copied completely.');
            // Never report success based on the HTTP request alone. This is
            // the same postcondition WordPress uses: the installed core must
            // now advertise the requested version from version.php.
            clearstatcache(true,$root.'/wp-includes/version.php');
            $installedAfter=$this->wpCoreVersionFromFile($root);
            if($installedAfter!==$version)throw new RuntimeException('Post-update verification found version '.($installedAfter?:'unknown').' instead of '.$version.'.');
            // A successful transaction needs no permanent full-site archive.
            $this->wpCoreRemoveTree($previous);
            $this->addMsg('WordPress updated quickly from '.$current.' to '.$version.'. Site data and wp-content were not copied or changed.','success');
            $this->log('wp_core_update',$current.' -> '.$version);
        }catch(Throwable $e){
            // Remove the partially installed core, then restore the moved
            // directories/files without touching wp-content or the database.
            $this->wpCoreRemoveTree($root.'/wp-admin');$this->wpCoreRemoveTree($root.'/wp-includes');
            foreach($movedDirs as $dir)@rename($previous.'/'.$dir,$root.'/'.$dir);
            foreach($movedFiles as $name){@unlink($root.'/'.$name);@rename($previous.'/'.$name,$root.'/'.$name);}
            $this->wpCoreRemoveTree($previous);
            $this->addMsg('WordPress update was rolled back safely: '.$e->getMessage(),'danger');
        }finally{
            $this->wpCoreRemoveTree($tmp);@unlink($lock);
        }
    }
    public function wpCoreCurrentVersion($configPath){
        if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
        if(basename($configPath)!=='wp-config.php')return['error'=>'This feature requires WordPress.'];
        $root=$this->wpSiteRoot($configPath);$v=$this->wpCoreVersionFromFile($root);
        return $v?['ok'=>true,'version'=>$v]:['error'=>'Could not read wp-includes/version.php after the update.'];
    }
    /* WordPress calculates Site Health from test results. The manager can
       optionally install an explicit, reversible override filter in the
       site's MU-plugins directory; the default remains the real core result. */
    public function wpSiteHealth($configPath){
        if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
        if(basename($configPath)!=='wp-config.php')return['error'=>'This feature requires a valid WordPress installation.'];
        $root=$this->wpSiteRoot($configPath);
        if(!is_file($root.'/wp-includes/version.php'))return['error'=>'This feature requires a valid WordPress installation.'];
        $override='auto';
        list($overrideLink,$overrideCms,$overrideErr)=$this->cmsConnect($configPath);
        if(!$overrideErr){
            $ot=$overrideCms['prefix'].'options';
            $or=@mysqli_query($overrideLink,"SELECT option_value FROM `{$ot}` WHERE option_name='fm_site_health_override' LIMIT 1");
            if($or&&($ov=mysqli_fetch_assoc($or))){
                $stored=(string)$ov['option_value'];
                $override=in_array($stored,['automatic','good','recommended','critical'],true)?$stored:($stored==='auto'?'automatic':'auto');
            }
            mysqli_close($overrideLink);
        }
        $checks=[];$add=function($id,$label,$status,$detail,$action=null)use(&$checks){
            $checks[]=['id'=>$id,'label'=>$label,'status'=>$status,'detail'=>$detail,'action'=>$action];
        };
        $current=$this->wpCoreVersionFromFile($root);
        $latest=$current;$versionError='';
        list($json,$err)=$this->wpCoreHttp('https://api.wordpress.org/core/version-check/1.7/?php='.rawurlencode(PHP_VERSION).'&locale=en_US',12);
        if($json!==false){
            $data=json_decode($json,true);
            $latest=trim((string)($data['offers'][0]['version']??$current))?:$current;
        }else $versionError=$err;
        if($versionError)$add('core-update','WordPress core','recommended','Could not check WordPress.org right now. The installed version is '.$current.'.','version');
        elseif(version_compare($current,$latest,'<'))$add('core-update','WordPress core','recommended','Version '.$latest.' is available; the site is running '.$current.'.','version');
        else $add('core-update','WordPress core','good','WordPress is running the latest version checked ('.$current.').');
        $phpOk=version_compare(PHP_VERSION,'7.2.0','>=');
        $add('php','PHP version',$phpOk?'good':'critical',$phpOk?'PHP '.PHP_VERSION.' is supported by WordPress.':'PHP '.PHP_VERSION.' is too old for a supported WordPress installation.');
        list($link,$c,$err)=$this->cmsConnect($configPath);
        if($err)$add('database','Database','critical','WordPress could not connect to its database: '.$err);
        else{
            $table=$c['prefix'].'options';$siteUrl='';$home='';
            foreach(['siteurl','home'] as $name){
                $n=mysqli_real_escape_string($link,$name);
                $res=@mysqli_query($link,"SELECT option_value FROM `{$table}` WHERE option_name='$n' LIMIT 1");
                $row=$res?mysqli_fetch_assoc($res):null;
                if($name==='siteurl')$siteUrl=trim((string)($row['option_value']??''));
                else $home=trim((string)($row['option_value']??''));
            }
            mysqli_close($link);
            if(!$siteUrl)$add('database','Database','critical','The WordPress site URL could not be read from wp_options.');
            else $add('database','Database','good','WordPress database connection and core options are readable.');
            $https=(bool)preg_match('#^https://#i',$home?:$siteUrl);
            $add('https','HTTPS',$https?'good':'recommended',$https?'The site URL uses HTTPS.':'The site URL does not use HTTPS. Enable HTTPS at the server/proxy before forcing redirects.','https');
        }
        $content=$root.'/wp-content';
        $writable=is_dir($content)&&is_writable($content);
        $add('filesystem','Filesystem',$writable?'good':'recommended',$writable?'wp-content is writable for normal WordPress updates.':'wp-content is not writable by PHP; automatic updates may fail.','permissions');
        $cfg=(string)@file_get_contents($configPath);
        $debugOn=(bool)preg_match("/define\s*\(\s*['\"]WP_DEBUG['\"]\s*,\s*true\s*\)/i",$cfg);
        $displayOn=(bool)preg_match("/define\s*\(\s*['\"]WP_DEBUG_DISPLAY['\"]\s*,\s*true\s*\)/i",$cfg);
        if($debugOn&&$displayOn)$add('debug','Debug display','recommended','WP_DEBUG and WP_DEBUG_DISPLAY are enabled; PHP errors may be exposed to visitors.','debug');
        else $add('debug','Debug display','good','Debug output is not configured to display publicly.');
        $critical=count(array_filter($checks,fn($x)=>$x['status']==='critical'));
        $recommended=count(array_filter($checks,fn($x)=>$x['status']==='recommended'));
        $actualOverall=$critical?'critical':($recommended?'recommended':'good');
        $overall=$override==='automatic'?'good':($override==='auto'?$actualOverall:$override);
        return['ok'=>true,'type'=>'wordpress','overall'=>$overall,'actual_overall'=>$actualOverall,'summary'=>['critical'=>$critical,'recommended'=>$recommended,'good'=>count($checks)-$critical-$recommended],
            'current'=>$current,'latest'=>$latest,'override'=>$override,'checked_at'=>date('c'),'checks'=>$checks];
    }
    public function wpSiteHealthControl($configPath,$mode){
        if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
        if(basename($configPath)!=='wp-config.php'||!is_file($this->wpSiteRoot($configPath).'/wp-includes/version.php'))return['error'=>'This feature requires a valid WordPress installation.'];
        $allowed=['automatic','auto','good','recommended','critical'];
        if(!in_array($mode,$allowed,true))return['error'=>'Invalid Site Health mode.'];
        list($link,$c,$err)=$this->cmsConnect($configPath);
        if($err)return['error'=>$err];
        if($c['type']!=='wordpress'){mysqli_close($link);return['error'=>'This control is available for WordPress only.'];}
        $root=$this->wpSiteRoot($configPath);$muDir=$root.'/wp-content/mu-plugins';$muFile=$muDir.'/000-fm-site-health-control.php';
        if($mode==='auto'){
            $ok=true;
            if(is_file($muFile))$ok=@unlink($muFile);
            $t=$c['prefix'];
            @mysqli_query($link,"DELETE FROM `{$t}options` WHERE option_name IN ('fm_site_health_override','_transient_health-check-site-status-result','_transient_timeout_health-check-site-status-result') LIMIT 3");
            mysqli_close($link);
            if(!$ok)return['error'=>'The Site Health control could not be removed.'];
            $this->log('wp_site_health_control','auto');
            return['ok'=>true,'mode'=>'auto','message'=>'WordPress Site Health is now calculated from its real tests.'];
        }
        if(!is_dir($muDir)&&!@mkdir($muDir,0755,true)&&!is_dir($muDir)){mysqli_close($link);return['error'=>'Could not create wp-content/mu-plugins.'];}
        $code="<?php\n/* Plugin Name: File Manager Site Health Control (reversible) */\n"
            ."if(!defined('ABSPATH'))exit;\n"
            ."add_filter('site_status_tests',function(\$tests){\n"
            ."    \$mode=get_option('fm_site_health_override','auto');\n"
            ."    if(\$mode==='automatic')\$mode='good';\n"
            ."    if(!in_array(\$mode,array('good','recommended','critical'),true))return \$tests;\n"
            ."    \$labels=array('good'=>'Good','recommended'=>'Should be improved','critical'=>'Critical problems');\n"
            ."    \$tests['direct']=array('fm_site_health_override'=>array('label'=>'File Manager Site Health status','test'=>function()use(\$mode,\$labels){return array('test'=>'fm_site_health_override','status'=>\$mode,'label'=>\$labels[\$mode],'badge'=>array('label'=>'File Manager control','color'=>'blue'),'description'=>'<p>Site Health is explicitly controlled by the File Manager. Choose Auto to restore WordPress tests.</p>','actions'=>'');}));\n"
            ."    \$tests['async']=array();\n"
            ."    return \$tests;\n"
            ."},99);\n"
            ."add_filter('site_status_test_result',function(\$result,\$test){\n"
            ."    \$mode=get_option('fm_site_health_override','auto');\n"
            ."    if(\$mode==='automatic')\$mode='good';\n"
            ."    if(!in_array(\$mode,array('good','recommended','critical'),true))return \$result;\n"
            ."    \$labels=array('good'=>'Good','recommended'=>'Should be improved','critical'=>'Critical problems');\n"
            ."    \$result['status']=\$mode;\n"
            ."    \$result['label']=\$labels[\$mode];\n"
            ."    \$result['description']='<p>Site Health status is controlled explicitly by the File Manager. Set it back to Auto to restore WordPress test results.</p>';\n"
            ."    return \$result;\n"
            ."},10,2);\n";
        if(@file_put_contents($muFile,$code,LOCK_EX)===false){mysqli_close($link);return['error'=>'Could not install the Site Health control.'];}
        @chmod($muFile,0644);
        $t=$c['prefix'];$m=mysqli_real_escape_string($link,$mode==='auto'?'automatic':$mode);
        $res=@mysqli_query($link,"SELECT option_name FROM `{$t}options` WHERE option_name='fm_site_health_override' LIMIT 1");
        $ok=$res&&mysqli_num_rows($res)>0
            ?@mysqli_query($link,"UPDATE `{$t}options` SET option_value='$m' WHERE option_name='fm_site_health_override' LIMIT 1")
            :@mysqli_query($link,"INSERT INTO `{$t}options` (option_name,option_value,autoload) VALUES ('fm_site_health_override','$m','yes')");
        $countJson=mysqli_real_escape_string($link,json_encode(['good'=>in_array($mode,['automatic','good'],true)?1:0,'recommended'=>$mode==='recommended'?1:0,'critical'=>$mode==='critical'?1:0]));
        $tr=@mysqli_query($link,"SELECT option_name FROM `{$t}options` WHERE option_name='_transient_health-check-site-status-result' LIMIT 1");
        if($tr&&mysqli_num_rows($tr)>0)@mysqli_query($link,"UPDATE `{$t}options` SET option_value='$countJson' WHERE option_name='_transient_health-check-site-status-result' LIMIT 1");
        else @mysqli_query($link,"INSERT INTO `{$t}options` (option_name,option_value,autoload) VALUES ('_transient_health-check-site-status-result','$countJson','no')");
        mysqli_close($link);
        if(!$ok){@unlink($muFile);return['error'=>'Could not save the Site Health control.'];}
        $this->log('wp_site_health_control',$mode);
        return['ok'=>true,'mode'=>$mode,'message'=>'WordPress Site Health is now controlled as '.$mode.'.'];
    }

    private function cmsToggleExtension(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $configPath=$this->cmsCfgFromPost();
        $id=(int)(isset($_POST['ext_id'])?$_POST['ext_id']:0);
        $enable=!empty($_POST['enable'])&&$_POST['enable']!=='0';
        if(!$id){$this->addMsg('Invalid extension.','danger');return;}
        list($link,$c,$err)=$this->cmsConnect($configPath);
        if($err){$this->addMsg($err,'danger');return;}
        if($c['type']!=='joomla'){mysqli_close($link);$this->addMsg('Not a Joomla site.','danger');return;}
        $t=$c['prefix'];
        $res=@mysqli_query($link,"SELECT protected,name FROM `{$t}extensions` WHERE extension_id=$id LIMIT 1");
        $row=$res?mysqli_fetch_assoc($res):null;
        if(!$row){mysqli_close($link);$this->addMsg('Extension not found.','danger');return;}
        if($row['protected']&&!$enable){mysqli_close($link);$this->addMsg('This is a protected core extension and cannot be disabled.','danger');return;}
        mysqli_query($link,"UPDATE `{$t}extensions` SET enabled=".($enable?1:0)." WHERE extension_id=$id");
        mysqli_close($link);
        $this->addMsg('Extension "'.$row['name'].'" '.($enable?'enabled':'disabled').'.',$enable?'success':'warning');
        $this->log('cms_toggle_extension',$id.':'.($enable?'on':'off'));
    }

    /* ── Maintenance mode ─────────────────────────────────────────────────────
       WordPress core's own ".maintenance" file trick only holds for 10 minutes
       (it's meant for core auto-updates, not deliberate site-down toggles), so
       instead this drops a tiny must-use plugin (auto-loaded by WP with zero
       activation step) that gates every front-end request on a plain
       wp_options flag - which stays on indefinitely until switched off here,
       and always still lets logged-in admins and wp-admin itself through.
       Joomla already has a real, permanent offline flag baked into
       configuration.php ($offline / $offline_message) that core checks on
       every request, so that one is just edited directly. */
    public function cmsMaintenanceStatus($configPath){
        list($link,$c,$err)=$this->cmsConnect($configPath);
        if($err)return['error'=>$err];
        if($c['type']==='wordpress'){
            $t=$c['prefix'];$on=false;$msg='';
            $res=@mysqli_query($link,"SELECT option_value FROM `{$t}options` WHERE option_name='fm_maintenance_mode' LIMIT 1");
            if($res&&($r=mysqli_fetch_assoc($res)))$on=$r['option_value']==='1';
            $res=@mysqli_query($link,"SELECT option_value FROM `{$t}options` WHERE option_name='fm_maintenance_message' LIMIT 1");
            if($res&&($r=mysqli_fetch_assoc($res)))$msg=$r['option_value'];
            mysqli_close($link);
            return['type'=>'wordpress','active'=>$on,'message'=>$msg];
        }
        mysqli_close($link);
        $src=@file_get_contents($configPath);$on=false;$msg='';
        if($src){
            /* Joomla's own installer writes $offline as a quoted '0'/'1' string, but some
               configs (including boolean-style ones) use bare true/false instead - accept
               either so detection never silently reports the wrong state. */
            if(preg_match('/public\s+\$offline\s*=\s*(?:[\'"](1|true)[\'"]|(true))\s*;/i',$src,$m))$on=true;
            elseif(preg_match('/public\s+\$offline\s*=\s*(?:[\'"](0|false)[\'"]|(false))\s*;/i',$src,$m))$on=false;
            if(preg_match('/public\s+\$offline_message\s*=\s*[\'"](.*?)[\'"]\s*;/s',$src,$m))$msg=stripslashes($m[1]);
        }
        return['type'=>'joomla','active'=>$on,'message'=>$msg];
    }
    private function cmsMaintenanceToggle(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $configPath=$this->cmsCfgFromPost();
        $enable=!empty($_POST['enable'])&&$_POST['enable']!=='0';
        $msg=trim(isset($_POST['message'])?$_POST['message']:'');
        list($link,$c,$err)=$this->cmsConnect($configPath);
        if($err){$this->addMsg($err,'danger');return;}
        if($c['type']==='wordpress'){
            $t=$c['prefix'];
            if($enable){
                $muDir=$this->wpSiteRoot($configPath).'/wp-content/mu-plugins';
                if(!is_dir($muDir))@mkdir($muDir,0755,true);
                $muFile=$muDir.'/000-fm-maintenance.php';
                if(is_dir($muDir)&&!is_file($muFile)){
                    $code="<?php\n/* Plugin Name: File Manager Maintenance Mode (auto-generated) */\n"
                         ."if(!defined('ABSPATH'))exit;\n"
                         ."add_action('init',function(){\n"
                         ."    if(is_admin())return;\n"
                         ."    if(function_exists('current_user_can')&&current_user_can('manage_options'))return;\n"
                         ."    if(get_option('fm_maintenance_mode')){\n"
                         ."        if(function_exists('nocache_headers'))nocache_headers();\n"
                         ."        header('Retry-After: 3600');\n"
                         ."        wp_die(get_option('fm_maintenance_message')?:'We are currently performing scheduled maintenance. Please check back soon.','Maintenance',array('response'=>503));\n"
                         ."    }\n"
                         ."},0);\n";
                    @file_put_contents($muFile,$code);
                }
            }
            $ev=$enable?'1':'0';
            $me=$msg?:'We are currently performing scheduled maintenance. Please check back soon.';
            $evE=mysqli_real_escape_string($link,$ev);$meE=mysqli_real_escape_string($link,$me);
            $res=@mysqli_query($link,"SELECT option_value FROM `{$t}options` WHERE option_name='fm_maintenance_mode' LIMIT 1");
            if($res&&mysqli_num_rows($res)>0)mysqli_query($link,"UPDATE `{$t}options` SET option_value='$evE' WHERE option_name='fm_maintenance_mode'");
            else mysqli_query($link,"INSERT INTO `{$t}options` (option_name,option_value,autoload) VALUES ('fm_maintenance_mode','$evE','yes')");
            $res=@mysqli_query($link,"SELECT option_value FROM `{$t}options` WHERE option_name='fm_maintenance_message' LIMIT 1");
            if($res&&mysqli_num_rows($res)>0)mysqli_query($link,"UPDATE `{$t}options` SET option_value='$meE' WHERE option_name='fm_maintenance_message'");
            else mysqli_query($link,"INSERT INTO `{$t}options` (option_name,option_value,autoload) VALUES ('fm_maintenance_message','$meE','yes')");
            mysqli_close($link);
            $this->addMsg('Maintenance mode '.($enable?'enabled':'disabled').' for this WordPress site.',$enable?'warning':'success');
            $this->log('cms_maintenance','wordpress '.($enable?'on':'off'));
            return;
        }
        mysqli_close($link);
        $src=@file_get_contents($configPath);
        if($src===false){$this->addMsg('Could not read configuration.php.','danger');return;}
        $val=$enable?'1':'0';
        $safeMsg=addslashes($msg?:'This site is currently offline for maintenance.');
        /* $offline may be written as a quoted '0'/'1' string OR a bare true/false boolean
           depending on how the config was generated - match either form so we always
           replace the real declaration in place instead of appending a duplicate
           (a duplicate "public $offline" property declaration is a PHP fatal error). */
        $offlineRe='/public\s+\$offline\s*=\s*(?:[\'"](?:0|1)[\'"]|true|false)\s*;/i';
        $src=preg_match($offlineRe,$src)
            ?preg_replace($offlineRe,"public \$offline = '$val';",$src,1)
            :preg_replace('/(class\s+JConfig\s*\{)/',"$1\n\tpublic \$offline = '$val';",$src,1);
        $src=preg_match('/public\s+\$offline_message\s*=\s*[\'"].*?[\'"]\s*;/s',$src)
            ?preg_replace('/public\s+\$offline_message\s*=\s*[\'"].*?[\'"]\s*;/s',"public \$offline_message = '$safeMsg';",$src,1)
            :preg_replace('/(class\s+JConfig\s*\{)/',"$1\n\tpublic \$offline_message = '$safeMsg';",$src,1);
        @copy($configPath,$configPath.'.bak_'.time());
        if(@file_put_contents($configPath,$src)===false&&!$this->privWriteFile($configPath,$src)){$this->addMsg('Failed to write configuration.php (check file permissions).','danger');return;}
        $this->addMsg('Offline (maintenance) mode '.($enable?'enabled':'disabled').' for this Joomla site.',$enable?'warning':'success');
        $this->log('cms_maintenance','joomla '.($enable?'on':'off'));
    }

    /* ── CMS password vault ───────────────────────────────────────────────────
       WordPress/Joomla store passwords as one-way hashes, so they can never be
       read back from the CMS database - not by this tool, not by anyone. The
       only plaintext moment is right when *this* admin panel sets it (create or
       change password). We save that plaintext here, encrypted at rest with a
       locally-generated key, so the user can reveal it again later without
       having to reset it every time they forget it. */
    private function cmsVaultKeyPath(){return __DIR__.'/.cms_vault_key.php';}
    private function cmsVaultPath(){return __DIR__.'/.cms_pw_vault.php';}
    private function cmsVaultKey(){
        $p=$this->cmsVaultKeyPath();
        fm_store_migrate($p,__DIR__.'/.cms_vault_key');
        if(file_exists($p)){$k=@base64_decode(trim(fm_store_strip_guard((string)@file_get_contents($p))),true);if($k&&strlen($k)===32)return $k;}
        $k=random_bytes(32);
        @file_put_contents($p,fm_store_guard(base64_encode($k)));@chmod($p,0600);
        return $k;
    }
    private function cmsVaultLoad(){
        $p=$this->cmsVaultPath();
        if(!file_exists($p))return[];
        fm_store_migrate($p,__DIR__.'/.cms_pw_vault.json');
        $j=json_decode(fm_store_strip_guard((string)@file_get_contents($p)),true);
        return is_array($j)?$j:[];
    }
    private function cmsVaultSave($data){
        @file_put_contents($this->cmsVaultPath(),fm_store_guard(json_encode($data,JSON_PRETTY_PRINT)));
        @chmod($this->cmsVaultPath(),0600);
    }
    private function cmsVaultEnc($plain){
        $iv=random_bytes(16);
        $ct=openssl_encrypt($plain,'aes-256-cbc',$this->cmsVaultKey(),OPENSSL_RAW_DATA,$iv);
        return $ct===false?null:base64_encode($iv.$ct);
    }
    private function cmsVaultDec($enc){
        $raw=@base64_decode($enc,true);
        if($raw===false||strlen($raw)<17)return null;
        $pt=openssl_decrypt(substr($raw,16),'aes-256-cbc',$this->cmsVaultKey(),OPENSSL_RAW_DATA,substr($raw,0,16));
        return $pt===false?null:$pt;
    }
    private function cmsVaultSet($configPath,$id,$plain,$uname=null){
        $data=$this->cmsVaultLoad();$k=md5($configPath).':'.$id;
        $enc=$this->cmsVaultEnc($plain);if($enc===null)return;
        $entry=['pass'=>$enc,'ts'=>time()];
        if($uname!==null)$entry['user']=$uname;
        elseif(isset($data[$k]['user']))$entry['user']=$data[$k]['user'];
        $data[$k]=$entry;
        $this->cmsVaultSave($data);
    }
    private function cmsVaultDelete($configPath,$id){
        $data=$this->cmsVaultLoad();$k=md5($configPath).':'.$id;
        if(isset($data[$k])){unset($data[$k]);$this->cmsVaultSave($data);}
    }
    public function cmsGetSavedPass($configPath,$id){
        $data=$this->cmsVaultLoad();$k=md5($configPath).':'.$id;
        if(!isset($data[$k]))return['error'=>'No saved password for this account. It was likely set before this feature existed, or changed outside this panel - use "Change Password" to set a new one.'];
        $p=$this->cmsVaultDec($data[$k]['pass']);
        if($p===null)return['error'=>'Could not decrypt the saved password.'];
        return['pass'=>$p];
    }

    /* ── "Login as user" (WordPress / Joomla) ────────────────────────────────
       The original account password is never readable - WordPress (phpass) and
       Joomla (bcrypt) store it as a one-way hash, and the vault above only ever
       has passwords *this tool* itself set. To actually get into an account
       without touching its password, we drop a tiny one-time PHP "bridge" file
       into the site's own webroot (next to wp-config.php / configuration.php).
       When opened, it boots that CMS's real framework and calls its own native
       login primitives (wp_set_auth_cookie() for WordPress, the same session
       fork() + Session::set('user',...) sequence Joomla's core login plugin
       uses) to establish a fully valid session for the target user - then
       deletes itself so the link only ever works once, within a short window. */
    public function cmsLoginAsUser($configPath,$id){
        if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
        $id=(int)$id;
        if(!$id)return['error'=>'Invalid user id.'];
        list($link,$c,$err)=$this->cmsConnect($configPath);
        if($err)return['error'=>$err];
        $dir=$c['type']==='wordpress'?$this->wpSiteRoot($configPath):dirname($configPath);
        $siteUrl=null;$uname=null;
        if($c['type']==='wordpress'){
            $t=$c['prefix'];
            $res=@mysqli_query($link,"SELECT ID,user_login FROM `{$t}users` WHERE ID=$id");
            $row=$res?mysqli_fetch_assoc($res):null;
            if(!$row){mysqli_close($link);return['error'=>'User not found.'];}
            $uname=$row['user_login'];
            $r2=@mysqli_query($link,"SELECT option_name,option_value FROM `{$t}options` WHERE option_name IN ('siteurl','home')");
            $opts=[];if($r2)while($o=mysqli_fetch_assoc($r2))$opts[$o['option_name']]=$o['option_value'];
            $siteUrl=$opts['siteurl']??($opts['home']??null);
        } else {
            $t=$c['prefix'];
            $res=@mysqli_query($link,"SELECT id,username FROM `{$t}users` WHERE id=$id");
            $row=$res?mysqli_fetch_assoc($res):null;
            if(!$row){mysqli_close($link);return['error'=>'User not found.'];}
            $uname=$row['username'];
            $siteUrl=$this->cmsJoomlaLiveSite($configPath);
        }
        mysqli_close($link);
        if(!is_writable($dir)&&!$this->privSiteFor($dir))return['error'=>'The site folder ('.$dir.') is not writable, so the one-time login file could not be created.'];
        $token=bin2hex(random_bytes(16));
        $fname='fm-bridge-'.bin2hex(random_bytes(8)).'.php';
        $bridgePath=$dir.'/'.$fname;
        $expires=time()+180;
        $code=$c['type']==='wordpress'?$this->cmsWpBridgeCode($id,$token,$expires):$this->cmsJoomlaBridgeCode($id,$token,$expires);
        if(@file_put_contents($bridgePath,$code)===false){
            /* The folder belongs to the web server - write the file through the
               site itself so a one-time login link still works. */
            $w=$this->privOp('write',['path'=>$bridgePath,'data'=>base64_encode($code),'b64'=>1],$bridgePath);
            if(empty($w['ok']))return['error'=>'Could not write the temporary login file into '.$dir.'. '.($w['error']??'')];
        }
        if(!@chmod($bridgePath,0644))$this->privOp('chmod',['path'=>$bridgePath,'mode'=>0644],$bridgePath);
        /* Never hand back a guessed URL - actively verify it first. We build
           every plausible base URL for this folder (cPanel-resolved domain
           for its exact document root, the current request's host, domain-
           looking path segments, and the CMS's own stored siteurl/live_site -
           each with https/http and www/non-www variants) and fire them all in
           parallel at the bridge file itself using a deliberately-wrong token.
           The bridge checks the token BEFORE it deletes itself, so a wrong
           token always yields a safe, distinctive 403 without consuming the
           real one-time link or logging anyone in. Whichever base URL is the
           first to actually reach that exact file (real 403 + sentinel text)
           is proven to route to this exact folder right now, on this exact
           site's structure - so the real link we return is guaranteed to work,
           instead of hoping a guessed domain/path happens to be correct. */
        $sentinel='login link is invalid or has expired';
        $candidates=$this->cmsBuildCandidateUrls($dir,$siteUrl);
        $probe=$this->cmsProbeUrls($candidates,$fname,$sentinel);
        if(!$probe['ok']){
            if(!@unlink($bridgePath))$this->privOp('delete',['path'=>$bridgePath],$bridgePath);
            $triedList=implode("\n",array_map(fn($t)=>' - '.$t,array_slice($probe['tried'],0,10)));
            return['error'=>"Could not verify a working login URL for this site - every URL this tool could construct failed to actually reach the site's folder from this server. Tried:\n{$triedList}\n\nThis usually means the site is served from a different server/hosting account than this file manager, or under a domain this account can't resolve. No broken link was opened."];
        }
        $this->log('cms_login_as',$c['type'].':'.($uname?:$id));
        return['url'=>$probe['ok'].'/'.$fname.'?t='.$token];
    }
    private function cmsJoomlaLiveSite($configPath){
        $src=@file_get_contents($configPath);if(!$src)return null;
        if(preg_match('/public\s+\$live_site\s*=\s*[\'"](.*?)[\'"]\s*;/s',$src,$m)&&trim($m[1])!=='')return rtrim(trim($m[1]),'/');
        return null;
    }
    /* Ask cPanel's own local API (works via the same zero-credential path
       cpanelAutoConnect uses) which domain's document root this exact folder
       belongs to. This is the only source that can be *authoritative* on
       shared hosting with multiple domains/addon domains/subdomains per
       account, where "the current request's host" and "the CMS's stored
       siteurl" are both frequently wrong for a folder that isn't the primary
       site. Never throws - degrades to an empty list if unavailable. */
    private function cmsCpanelDomainMatches($real){
        $matches=[];
        $collect=function($entries)use(&$matches,$real){
            if(!is_array($entries))return;
            foreach($entries as $e){
                if(!is_array($e))continue;
                $dom=$e['domain']??($e['domainname']??null);
                $droot=$e['documentroot']??($e['docroot']??($e['homedir']??null));
                if(!$dom||!$droot)continue;
                $droot=rtrim(realpath($droot)?:$droot,'/');
                if($droot&&($real===$droot||strpos($real,$droot.'/')===0)){
                    $matches[]=['domain'=>$dom,'rel'=>substr($real,strlen($droot)),'len'=>strlen($droot),'authoritative'=>!empty($e['documentroot'])||!empty($e['docroot'])];
                }
            }
        };
        $res=$this->cpNativeCall('DomainInfo','domains_data');
        if(is_array($res)){
            $collect($res['result']['data']??($res['data']??($res['cpanelresult']['data']??null)));
        }
        if(!array_filter($matches,fn($match)=>!empty($match['authoritative']))){
            // Older cPanel builds don't expose domains_data - fall back to
            // listing domain names, then asking for each one's docroot
            // individually via single_domain_data.
            $list=$this->cpNativeCall('DomainInfo','list_domains');
            $data=is_array($list)?($list['result']['data']??($list['data']??null)):null;
            $names=[];
            if(is_array($data)){
                foreach(['main_domain'=>false,'domains'=>true,'sub_domains'=>true,'addon_domains'=>true,'parked_domains'=>true] as $k=>$isList){
                    if(!isset($data[$k]))continue;
                    if($isList&&is_array($data[$k]))foreach($data[$k] as $d)if(is_string($d))$names[]=$d;
                    elseif(!$isList&&is_string($data[$k]))$names[]=$data[$k];
                }
            }
            foreach(array_unique($names) as $dom){
                $sres=$this->cpNativeCall('DomainInfo','single_domain_data',['domain'=>$dom]);
                $sd=is_array($sres)?($sres['result']['data']??($sres['data']??null)):null;
                if(is_array($sd))$collect([$sd+['domain'=>$sd['domain']??$dom]]);
            }
        }
        usort($matches,fn($a,$b)=>$b['len']-$a['len']);
        return $matches;
    }
    private function filePublicHost($host){
        $host=strtolower(rtrim(trim((string)$host),'.'));
        if($host===''||!preg_match('/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)(?:\.(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?))*$/i',$host))return'';
        return $this->cmsLoginHostAllowed($host)?$host:'';
    }
    private function filePublicBaseForDirectory($directory){
        foreach($this->cmsCpanelDomainMatches($directory) as $match){
            if(empty($match['authoritative']))continue;
            $host=$this->filePublicHost($match['domain']??'');
            if($host==='')continue;
            $relative=str_replace('\\','/',(string)($match['rel']??''));
            $segments=array_values(array_filter(explode('/',$relative),fn($part)=>$part!==''));
            return['host'=>$host,'segments'=>$segments];
        }
        $parts=array_values(array_filter(explode('/',str_replace('\\','/',(string)$directory)),fn($part)=>$part!==''));
        foreach($parts as $i=>$segment){
            $marker=strtolower($segment);$rootName='';
            if($marker==='vhosts')$rootName='httpdocs';
            elseif($marker==='domains')$rootName='public_html';
            if($rootName===''||!isset($parts[$i+1],$parts[$i+2])||strtolower($parts[$i+2])!==$rootName)continue;
            $host=$this->filePublicHost($parts[$i+1]);
            if($host==='')continue;
            return['host'=>$host,'segments'=>array_slice($parts,$i+3)];
        }
        return null;
    }
    public function publicFileUrl($path){
        $real=realpath((string)$path);
        if($real===false||!is_file($real))return'';
        $directory=dirname($real);
        if(!array_key_exists($directory,$this->filePublicBaseCache)){
            $this->filePublicBaseCache[$directory]=$this->filePublicBaseForDirectory($directory);
        }
        $base=$this->filePublicBaseCache[$directory];
        if(!is_array($base)||empty($base['host']))return'';
        $segments=array_merge($base['segments']??[],[basename($real)]);
        return'https://'.$base['host'].'/'.implode('/',array_map('rawurlencode',$segments));
    }
    /* Build every plausible base URL (scheme://host[/rel]) for a folder,
       highest-confidence first. cmsProbeUrls verifies each one live, so
       false candidates here just get discarded - the goal is coverage across
       every hosting layout (single site, addon domain, subdomain, CMS in a
       subfolder, migrated/stale siteurl), not precision. */
    private function cmsLoginHostAllowed($host){
        $host=trim((string)$host);
        if($host==='')return false;
        /*
         * A reverse-proxied PHP request can expose the local listener as
         * HTTP_HOST (for example 127.0.0.1) even though the browser reached
         * the manager through a public domain. Never turn that internal host
         * into a Login as URL; it can pass the local probe while being
         * unreachable to the user and is not the CMS site's address.
         */
        $hostOnly=$host;
        if($hostOnly[0]==='['){
            $end=strpos($hostOnly,']');
            if($end!==false)$hostOnly=substr($hostOnly,1,$end-1);
        }elseif(substr_count($hostOnly,':')===1){
            $hostOnly=(string)strtok($hostOnly,':');
        }
        $hostOnly=strtolower(rtrim(trim($hostOnly,'[]'),'.'));
        if(in_array($hostOnly,['localhost','localhost.localdomain','ip6-localhost','ip6-loopback','0.0.0.0','::1'],true))return false;
        /* *.localhost is reserved (RFC 6761) and can only ever resolve on the
           machine running this manager, so it can pass the local probe while
           being unreachable from the visitor's browser. *.local is deliberately
           NOT blocked: mDNS names can be valid on a real LAN and blocking them
           would change behaviour for existing LAN/hosting setups. */
        if(substr($hostOnly,-10)==='.localhost')return false;
        if(filter_var($hostOnly,FILTER_VALIDATE_IP)!==false){
            return filter_var($hostOnly,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)!==false;
        }
        return true;
    }
    private function cmsBuildCandidateUrls($dir,$storedUrl){
        $real=realpath($dir)?:rtrim($dir,'/');
        $urls=[];
        $add=function($scheme,$host,$rel='')use(&$urls){
            $host=trim((string)$host,'.');
            if(!$host||strpos($host,' ')!==false||!$this->cmsLoginHostAllowed($host))return;
            $rel=$rel?('/'.trim($rel,'/')):'';
            $u=$scheme.'://'.$host.$rel;
            if(!in_array($u,$urls,true))$urls[]=$u;
        };
        $addHost=function($host,$rel='')use($add){
            $add('https',$host,$rel);$add('http',$host,$rel);
            if(stripos($host,'www.')===0){$bare=substr($host,4);$add('https',$bare,$rel);$add('http',$bare,$rel);}
            else{$add('https','www.'.$host,$rel);$add('http','www.'.$host,$rel);}
        };
        // 1) cPanel-authoritative: this folder's exact document root, whichever domain(s) map to it.
        foreach($this->cmsCpanelDomainMatches($real) as $m)$addHost($m['domain'],$m['rel']);
        // 2) The CMS's own stored URL (siteurl/home for WP, live_site for Joomla).
        //    Keep the port: a site on localhost:8081 or example.com:8080 lives
        //    on that port, and dropping it builds a URL that can never match.
        if($storedUrl){
            $p=@parse_url($storedUrl);
            if($p&&!empty($p['host'])){
                $storedHost=$p['host'].(!empty($p['port'])?':'.(int)$p['port']:'');
                $addHost($storedHost,$p['path']??'');
            }
        }
        // 3) The current admin request's public host, if this folder sits
        // under a known local web root. In a reverse proxy, HTTP_HOST may be
        // the internal listener; X-Forwarded-Host is the browser-facing host.
        $reqHosts=[];
        foreach([$_SERVER['HTTP_X_FORWARDED_HOST']??null,
                 $_SERVER['HTTP_X_ORIGINAL_HOST']??null,
                 $_SERVER['HTTP_HOST']??($_SERVER['SERVER_NAME']??null)] as $rawHost){
            foreach(explode(',',(string)$rawHost) as $reqHost){
                $reqHost=trim($reqHost);
                if($reqHost!==''&&!in_array($reqHost,$reqHosts,true))$reqHosts[]=$reqHost;
            }
        }
        if($reqHosts){
            foreach([$_SERVER['DOCUMENT_ROOT']??null,$this->root] as $base){
                if(!$base)continue;
                $baseReal=rtrim(realpath($base)?:$base,'/');
                if($baseReal&&($real===$baseReal||strpos($real,$baseReal.'/')===0)){
                    $rel=substr($real,strlen($baseReal));
                    foreach($reqHosts as $reqHost)$addHost($reqHost,$rel);
                }
            }
        }
        /* 3.b) Port-in-hostname reverse proxies (e.g. a preview/preview tunnel
           that exposes every local port as <port>-<id>.example.com). The host
           the manager itself was reached on is by definition browser-reachable,
           so swapping its leading port for the CMS site's own port yields a URL
           the visitor's browser can actually open. cmsProbeUrls then verifies
           it through the local listener on that port. */
        $cmsPort=0;$priorityUrls=[];
        if($storedUrl){$__su=@parse_url($storedUrl);if($__su&&!empty($__su['port']))$cmsPort=(int)$__su['port'];}
        $selfHost=trim((string)($_SERVER['HTTP_HOST']??($_SERVER['SERVER_NAME']??'')));
        if($cmsPort&&preg_match('/^\d+-/',$selfHost)){
            $cmsFolder=basename($real);
            $addFirst=function($scheme,$host,$rel='')use(&$priorityUrls,$addHost){
                $host=trim((string)$host,'.');
                if(!$host||strpos($host,' ')!==false||!$this->cmsLoginHostAllowed($host))return;
                $rel=$rel?('/'.trim($rel,'/')):'';
                $u=$scheme.'://'.$host.$rel;
                if(!in_array($u,$priorityUrls,true))$priorityUrls[]=$u;
            };
            foreach($reqHosts as $rh){
                if(!preg_match('/^(\d+)-(.+)$/',$rh,$hm))continue;
                if((int)$hm[1]===$cmsPort)continue;
                $mappedHost=$cmsPort.'-'.$hm[2];
                /* A dedicated host per port is the browser-facing address the
                   visitor already used, so verify it first; both a bare root
                   and a folder name are tried because the CMS may be the
                   vhost's document root or live one level below it. */
                $addFirst('https',$mappedHost);
                $addFirst('http',$mappedHost);
                if($cmsFolder&&$cmsFolder!=='.'){
                    $addFirst('https',$mappedHost,$cmsFolder);
                    $addFirst('http',$mappedHost,$cmsFolder);
                }
            }
        }
        // 4) Domain-looking folder names in the path itself (cPanel's
        //    .../domains/<domain>/public_html or similar addon-domain layouts).
        foreach(explode('/',$real) as $seg){
            if($seg&&preg_match('/^[a-z0-9]([a-z0-9\-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9\-]*[a-z0-9])?)+$/i',$seg))$addHost($seg);
        }
        /* Browser-facing port-mapped URLs win over anything the server alone
           could reach: they are the only ones the visitor's browser can open. */
        if($priorityUrls)$urls=array_values(array_unique(array_merge($priorityUrls,$urls)));
        return array_slice($urls,0,20);
    }
    /* Fire every candidate base URL at the bridge file in parallel with a
       deliberately-wrong token and pick the first that gives back the
       bridge's own 403 response (proving the request actually reached that
       exact file) rather than a 404/timeout/someone-else's-403-page. Runs
       concurrently via curl_multi so total wait stays ~one request's time
       regardless of how many candidates there are. */
    /* Verification URL for one candidate base. A base whose hostname carries
       the port (the port-in-hostname proxy layout handled in
       cmsBuildCandidateUrls) usually cannot be dialled from this server - the
       tunnel may require a browser token or be unroutable from inside. The
       service itself, however, is listening locally on exactly that port, so
       the same path is verified against 127.0.0.1:<port>. The browser-facing
       base is still what gets handed back to the user. */
    private function cmsProbeTargetUrl($base,$suffix){
        $fallback=$base.'/'.$suffix;
        $p=@parse_url($base);
        if(!$p||empty($p['host']))return $fallback;
        $selfHost=trim((string)($_SERVER['HTTP_HOST']??($_SERVER['SERVER_NAME']??'')));
        if(!preg_match('/^\d+-/',$selfHost))return $fallback;
        if(!preg_match('/^(\d+)-(.+)$/',$p['host'],$pm))return $fallback;
        $port=(int)$pm[1];
        if($port<1||$port>65535)return $fallback;
        $path=rtrim((string)($p['path']??''),'/');
        return 'http://127.0.0.1:'.$port.$path.'/'.$suffix;
    }
    /* When no known URL works (a Joomla site without live_site, for example)
       and the manager sits behind a proxy that exposes each port on its own
       hostname, find which port actually serves the bridge file on 127.0.0.1
       and rebuild the browser-facing URL from it: https://<port>-<rest>.
       The file name is random, so no other site can answer for it. */
    private function cmsDiscoverLocalPort($fname,$qs,$sentinel,$timeoutSec=3){
        $selfHost=trim((string)($_SERVER['HTTP_HOST']??($_SERVER['SERVER_NAME']??'')));
        /* Supported deployments: the port-in-hostname proxy (8123-xxx) and a plain
           local host (127.0.0.1, localhost, LAN IP) where each site simply listens
           on another port. Anything else (a real domain) must not be probed. */
        $portHosted=preg_match('/^\d+-(.+)$/',$selfHost);
        $plainLocal=preg_match('/^(localhost|(\d{1,3}\.){3}\d{1,3})(:\d+)?$/i',$selfHost);
        if(!$portHosted&&!$plainLocal)return null;
        $ports=[80];
        for($p=8000;$p<=8100;$p++)$ports[]=$p;
        if(!function_exists('curl_multi_init')){
            foreach($ports as $port){
                $r=$this->cmsHttpProbeOne('http://127.0.0.1:'.$port.'/'.$fname.$qs,min(2,$timeoutSec));
                if($r['code']===403&&stripos($r['body'],$sentinel)!==false)return $port;
            }
            return null;
        }
        $mh=curl_multi_init();$hs=[];
        foreach($ports as $port){
            $ch=curl_init('http://127.0.0.1:'.$port.'/'.$fname.$qs);
            curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>$timeoutSec,
                CURLOPT_CONNECTTIMEOUT_MS=>400,CURLOPT_FOLLOWLOCATION=>false]);
            curl_multi_add_handle($mh,$ch);$hs[$port]=$ch;
        }
        $running=null;
        do{$st=curl_multi_exec($mh,$running);if($running>0)curl_multi_select($mh,0.2);}while($running>0&&$st===CURLM_OK);
        $found=null;
        foreach($hs as $port=>$ch){
            $body=(string)curl_multi_getcontent($ch);
            $code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);
            if($found===null&&$code===403&&stripos($body,$sentinel)!==false)$found=$port;
            curl_multi_remove_handle($mh,$ch);curl_close($ch);
        }
        curl_multi_close($mh);
        return $found?:null;
    }
    private function cmsProbeUrls($baseUrls,$fname,$sentinel,$timeoutSec=6){
        $probeQs='?t=probe-'.bin2hex(random_bytes(4));
        $tried=[];
        if(!function_exists('curl_init')){
            foreach($baseUrls as $base){
                $r=$this->cmsHttpProbeOne($this->cmsProbeTargetUrl($base,$fname.$probeQs),$timeoutSec);
                $tried[]=$base.' → '.($r['code']?:'no response');
                if($r['code']===403&&stripos($r['body'],$sentinel)!==false)return['ok'=>$base,'tried'=>$tried];
            }
            return['ok'=>null,'tried'=>$tried];
        }
        $mh=curl_multi_init();$handles=[];
        foreach($baseUrls as $i=>$base){
            $ch=curl_init($this->cmsProbeTargetUrl($base,$fname.$probeQs));
            curl_setopt_array($ch,[
                CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,
                CURLOPT_TIMEOUT=>$timeoutSec,CURLOPT_CONNECTTIMEOUT=>$timeoutSec,
                CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0,
                CURLOPT_USERAGENT=>'Mozilla/5.0 (compatible; FileManagerLoginProbe/1.0)',
            ]);
            curl_multi_add_handle($mh,$ch);
            $handles[$i]=['ch'=>$ch,'base'=>$base];
        }
        $running=null;
        do{
            $status=curl_multi_exec($mh,$running);
            if($running>0)curl_multi_select($mh,0.2);
        }while($running>0&&$status===CURLM_OK);
        $winner=null;
        foreach($handles as $i=>$h){
            $body=(string)curl_multi_getcontent($h['ch']);
            $code=(int)curl_getinfo($h['ch'],CURLINFO_HTTP_CODE);
            $tried[$i]=$h['base'].' → '.($code?:'no response/timeout');
            if($winner===null&&$code===403&&stripos($body,$sentinel)!==false)$winner=$h['base'];
            curl_multi_remove_handle($mh,$h['ch']);curl_close($h['ch']);
        }
        curl_multi_close($mh);
        ksort($tried);
        if($winner===null){
            $port=$this->cmsDiscoverLocalPort($fname,$probeQs,$sentinel);
            if($port){
                $selfHost=trim((string)($_SERVER['HTTP_HOST']??($_SERVER['SERVER_NAME']??'')));
                if(preg_match('/^\d+-(.+)$/',$selfHost,$hm)){
                    $tried[]='127.0.0.1:'.$port.' → 403 (port discovered on 127.0.0.1)';
                    return['ok'=>'https://'.$port.'-'.$hm[1],'tried'=>array_values($tried)];
                }
                /* Plain host:port deployment (localhost, LAN, IP address): the
                   discovered port on the same machine is the site itself. */
                $selfName=trim((string)($_SERVER['HTTP_HOST']??($_SERVER['SERVER_NAME']??'127.0.0.1')));
                $selfName=preg_replace('/:\d+$/','',$selfName);
                if(in_array($selfName,['','0.0.0.0','::','[::]'],true))$selfName='127.0.0.1';
                if($selfName!==''&&$port){
                    $scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';
                    $tried[]=$selfName.':'.$port.' → 403 (port discovered on the local server)';
                    return['ok'=>$scheme.'://'.$selfName.':'.$port,'tried'=>array_values($tried)];
                }
            }
        }
        return['ok'=>$winner,'tried'=>array_values($tried)];
    }
    private function cmsHttpProbeOne($url,$timeoutSec){
        $ctx=stream_context_create([
            'http'=>['timeout'=>$timeoutSec,'ignore_errors'=>true,'follow_location'=>1,'max_redirects'=>5],
            'ssl'=>['verify_peer'=>false,'verify_peer_name'=>false],
        ]);
        $body=@file_get_contents($url,false,$ctx);
        $code=0;
        if(isset($http_response_header)&&is_array($http_response_header)){
            foreach($http_response_header as $h){if(preg_match('#^HTTP/\S+\s+(\d+)#',$h,$m))$code=(int)$m[1];}
        }
        return['code'=>$code,'body'=>(string)$body];
    }
    /* ═══ Session & Cookie Inspector ═════════════════════════════════════════
       Lists the real login sessions of the current site (WordPress or Joomla),
       lets an admin extend or revoke them, and reports the session-lifetime
       policy. Everything runs against the site's own database - no passwords. */
    private function sessionInspectorCfg($post,&$diag=null){
        return $this->cmsFindConfig($post,$diag);
    }
    /* ── Config discovery ─────────────────────────────────────────────────────
       Locating wp-config.php / configuration.php is the one step that fails on
       unusual layouts, so it runs in stages, cheapest first: the exact path the
       admin supplied, a cached answer, the folders around this request, the
       document roots the web server itself declares, running PHP servers, the
       generic scan, and finally a bounded filesystem search for the CMS
       markers. Every stage is recorded in $diag, so the panel can show what was
       tried instead of a dead end. A candidate is accepted only after its
       database answers, which means the returned path is a *working* one. */

    /* WordPress or Joomla config? Decided by the file name, then by the
       contents, so a config that was renamed or copied still resolves. */
    private function cmsConfigType($path){
        if(!is_string($path)||$path===''||!@is_file($path))return null;
        $head=@file_get_contents($path,false,null,0,65536);
        if(is_string($head)&&$head!==''){
            if(strpos($head,'JConfig')!==false)return 'joomla';
            if(preg_match('/\$table_prefix\s*=|DB_NAME|wp-settings\.php/',$head))return 'wordpress';
            if(preg_match('/public\s+\$(dbprefix|host|user)\s*=/',$head))return 'joomla';
        }
        $base=strtolower(basename($path));
        if($base==='wp-config.php')return 'wordpress';
        if($base==='configuration.php')return 'joomla';
        return null;
    }

    /* The config file that belongs to a site folder - or to its parent, which
       is the hardened WordPress layout (wp-config.php above the web root). */
    private function cmsConfigIn($dir){
        $dir=rtrim((string)$dir,'/');
        if($dir===''||!@is_dir($dir))return null;
        foreach(['wp-config.php','configuration.php'] as $n){
            if(@is_file("$dir/$n")&&@is_readable("$dir/$n"))return "$dir/$n";
        }
        $up=dirname($dir);
        $parent="$up/wp-config.php";
        if($up!=='/'&&$up!==$dir&&@is_file($parent)&&@is_readable($parent)
           &&(@is_dir("$dir/wp-content")||@is_dir("$dir/wp-includes")))return $parent;
        return null;
    }

    /* Looser variant used when nothing else matches: walks up $levels folders
       looking for a config file, without insisting the folder looks like a web
       root. Safe because the caller validates the candidate against the
       database before trusting it. */
    private function cmsConfigNear($dir,$levels=3){
        $cur=rtrim((string)$dir,'/');
        for($i=0;$i<$levels&&$cur!==''&&$cur!=='/';$i++){
            foreach(['wp-config.php','configuration.php'] as $n){
                if(@is_file("$cur/$n")&&@is_readable("$cur/$n"))return "$cur/$n";
            }
            $up=dirname($cur);
            if($up===$cur)break;
            $cur=$up;
        }
        return null;
    }

    /* Accepts a config file, a site folder, a folder above it, or a relative
       path. Returns the config path or null. */
    private function cmsConfigResolve($raw){
        $raw=trim((string)$raw);
        if($raw==='')return null;
        if(strpos($raw,'~')===0)$raw=rtrim((string)getenv('HOME'),'/').substr($raw,1);
        if($raw===''||$raw[0]!=='/'){
            foreach([$this->currentDir,$this->root] as $base){
                if($base&&@file_exists(rtrim($base,'/').'/'.$raw)){$raw=rtrim($base,'/').'/'.$raw;break;}
            }
        }
        if($raw===''||$raw[0]!=='/')return null;
        if(@is_dir($raw))return $this->cmsConfigIn($raw) ?: $this->cmsConfigNear($raw,4);
        if(@is_file($raw)&&@is_readable($raw)){
            $r=@realpath($raw);
            if($r&&$this->cmsConfigType($r))return $r;
            /* The name may be wrong but the folder may still hold a config. */
            return $this->cmsConfigIn(dirname($raw)) ?: $this->cmsConfigNear(dirname($raw),3);
        }
        return $this->cmsConfigIn(dirname($raw)) ?: $this->cmsConfigNear(dirname($raw),3);
    }

    /* Document roots declared by the web server (Apache, nginx, lighttpd,
       Caddy). This is the most dependable source when a site lives on an
       unexpected path: whatever the server actually serves is where the site
       is, no guessing involved. */
    private function cmsServerRoots(){
        $dirs=['/etc/apache2/sites-enabled','/etc/apache2/sites-available','/etc/apache2/conf-enabled',
               '/etc/httpd/conf.d','/etc/httpd/conf','/etc/nginx/sites-enabled','/etc/nginx/sites-available',
               '/etc/nginx/conf.d','/usr/local/etc/nginx/sites-enabled','/etc/lighttpd','/etc/caddy'];
        $roots=[];
        foreach($dirs as $d){
            if(!@is_dir($d))continue;
            foreach((array)@scandir($d) as $f){
                if(!is_string($f)||$f===''||$f[0]==='.')continue;
                $p="$d/$f";
                if(!@is_file($p))continue;
                $txt=@file_get_contents($p,false,null,0,262144);
                if(!is_string($txt)||$txt==='')continue;
                if(preg_match_all('/^\s*DocumentRoot\s+"?([^"\r\n]+?)"?\s*$/mi',$txt,$m))foreach($m[1] as $r)$roots[]=trim($r);
                if(preg_match_all('/^\s*root\s+([^;\r\n]+)\s*;/mi',$txt,$m))foreach($m[1] as $r)$roots[]=trim($r);
                if(preg_match_all('/^\s*server\.document-root\s*=\s*"?([^"\r\n]+?)"?\s*$/mi',$txt,$m))foreach($m[1] as $r)$roots[]=trim($r);
            }
        }
        $out=[];
        foreach($roots as $r){
            $r=rtrim($r,'/');
            if($r!==''&&$r[0]==='/'&&@is_dir($r))$out[$r]=1;
        }
        return array_keys($out);
    }

    /* Document roots of the PHP built-in servers running on this machine. */
    private function cmsRunningServerRoots(){
        $out=[];
        if(!function_exists('exec'))return [];
        $lines=[];
        @exec('ps -eo args= 2>/dev/null',$lines);
        foreach($lines as $line){
            if(!preg_match('/\bphp[\d.]*\s+.*\s-S\s/',$line))continue;
            if(preg_match('/\s-t\s+(\S+)/',$line,$m)){
                $d=rtrim($m[1],'/');
                if($d!==''&&$d[0]==='/'&&@is_dir($d))$out[$d]=1;
            }
        }
        return array_keys($out);
    }

    /* Last resort: look for the CMS itself, not only its config. A folder that
       contains wp-includes/version.php is a WordPress root even if its
       wp-config.php was moved one level up or renamed. */
    private function cmsFindByMarkers($maxDepth=8){
        $out=[];
        if(!function_exists('exec'))return $out;
        $bases=[];
        foreach(['/home','/var/www','/srv','/opt','/usr/share/wordpress','/data','/var/lib','/web','/www'] as $b){
            if(@is_dir($b))$bases[]=$b;
        }
        if(!$bases)return $out;
        $cmd='timeout 15 find '.implode(' ',array_map('escapeshellarg',$bases))
            .' -maxdepth '.(int)$maxDepth
            .' \\( -name node_modules -o -name vendor -o -name .git -o -name .cache -o -name .local \\) -prune -o '
            .'\\( -name wp-config.php -o -name configuration.php -o -path "*/wp-includes/version.php" \\) -print 2>/dev/null | head -80';
        $lines=[];
        @exec($cmd,$lines);
        foreach((array)$lines as $line){
            $line=trim((string)$line);
            if($line==='')continue;
            if(strpos($line,'/wp-includes/version.php')!==false){
                $root=dirname(dirname($line));
                $c=$this->cmsConfigIn($root) ?: $this->cmsConfigNear($root,4);
                if($c)$out[$c]=1;
                continue;
            }
            if($this->cmsConfigType($line))$out[$line]=1;
        }
        return array_keys($out);
    }

    /* Public entry points used by the CMS Manager, which needs the candidate
       list itself (to show every site it can reach) rather than one answer. */
    public function cmsDiscovery($post=null,$deep=false){
        $diag=[];
        $best=$this->cmsFindConfig(is_array($post)?$post:[],$diag,(bool)$deep);
        $sites=[];
        foreach(($diag['candidates']??[]) as $c){
            if(!is_array($c)||empty($c['path']))continue;
            $label=$c['stage'];
            if($label==='cached')$label='last used';
            $sites[]=['type'=>$this->cmsConfigType($c['path']),'config'=>$c['path'],
                      'dir'=>dirname($c['path']),'source'=>$label];
        }
        return ['best'=>$best,'source'=>$diag['source']??null,'tried'=>$diag['tried']??[],'sites'=>$sites];
    }
    /* Resolves anything an admin may type: a config file, a site folder, the web
       root above it, a relative path - or nothing. */
    public function cmsResolvePath($raw){
        $p=$this->cmsConfigResolve($raw);
        return $p?:null;
    }
    public function cmsPathType($path){
        return $this->cmsConfigType($path);
    }
    /* Resolves the config file for the current site. $diag receives the stage
       that succeeded and everything that was tried. */
    private function cmsFindConfig($post=null,&$diag=null,$deep=true){
        $post=is_array($post)?$post:[];
        $diag=['source'=>null,'tried'=>[],'candidates'=>[]];

        /* Stage 1 - the path the admin typed (or the UI remembered). */
        foreach(['cfg_path','cfg_b64'] as $k){
            if(empty($post[$k]))continue;
            $raw=$k==='cfg_b64'?base64_decode((string)$post[$k],true):(string)$post[$k];
            if(!is_string($raw)||trim($raw)==='')continue;
            $p=$this->cmsConfigResolve($raw);
            if($p){
                $diag['source']='manual';$diag['tried'][]="manual path → $p";
                $diag['candidates']=[['path'=>$p,'stage'=>'manual']];
                return $p;
            }
            /* A path the admin typed is never silently ignored: acting on a
               different site's sessions than the one they asked for would be
               worse than an error. */
            $diag['manual']=trim($raw);
            $diag['tried'][]='manual path not usable: '.trim($raw);
            return null;
        }

        /* Stage 2 - the answer from the previous request, if still valid. */
        if(empty($post['rescan'])&&!empty($_SESSION['fm_cfg_path'])){
            $p=(string)$_SESSION['fm_cfg_path'];
            if($this->cmsConfigType($p)){
                $diag['source']='cached';$diag['tried'][]="cached → $p";
                $diag['candidates']=[['path'=>$p,'stage'=>'cached']];
                return $p;
            }
            unset($_SESSION['fm_cfg_path']);
        }

        $cands=[];$seen=[];
        $add=function($p,$stage)use(&$cands,&$seen){
            if(!$p)return;
            $r=@realpath($p)?:$p;
            if(isset($seen[$r]))return;
            if(!$this->cmsConfigType($r))return;
            $seen[$r]=1;
            $cands[]=['path'=>$r,'stage'=>$stage];
        };

        /* Stage 3 - this request's own surroundings: the current folder, the
           manager root, the document root, then up to five levels above each
           and one level into the usual site folders. */
        $starts=[];
        foreach([$this->currentDir,$this->root,getcwd(),$_SERVER['DOCUMENT_ROOT']??null,
                  dirname($_SERVER['SCRIPT_FILENAME']??''),dirname($_SERVER['DOCUMENT_ROOT']??'')] as $d){
            if(is_string($d)&&$d!==''&&@is_dir($d))$starts[rtrim($d,'/')]=1;
        }
        /* The folder being browsed comes first: if the manager is already
           inside a site, that site is the one the admin means. */
        foreach([$this->currentDir,getcwd(),$_SERVER['DOCUMENT_ROOT']??null] as $d){
            if(!is_string($d)||$d===''||!@is_dir($d))continue;
            $hit=$this->cmsDetect($d);
            if(!empty($hit['config']))$add($hit['config'],'current folder');
        }
        $subs=['public_html','public','www','htdocs','httpdocs','web','html','site','sites','wp','wordpress','blog','joomla','cms'];
        foreach(array_keys($starts) as $d){
            $cur=$d;
            for($i=0;$i<5;$i++){
                $add($this->cmsConfigIn($cur),'nearby folder');
                foreach($subs as $s)$add($this->cmsConfigIn($cur.'/'.$s),'nearby folder');
                $up=dirname($cur);
                if($up===$cur||$up==='/')break;
                $cur=$up;
            }
        }

        /* Stage 4 - whatever the web server serves. */
        foreach($this->cmsServerRoots() as $d){
            $add($this->cmsConfigIn($d),'web server document root');
            $add($this->cmsConfigIn($d.'/..'),'web server document root');
        }

        /* Stage 5 - PHP built-in servers (-t). */
        foreach($this->cmsRunningServerRoots() as $d)$add($this->cmsConfigIn($d),'running PHP server');

        /* Stage 6 - the generic scan, then the marker search. Both are more
           expensive, so they only run when nothing cheaper matched, and only
           when the caller asked for a deep search. */
        if($deep&&!$cands){
            foreach(($this->cmsScan()['sites']??[]) as $s){
                if(is_array($s))$add($s['config']??null,'server scan');
            }
        }
        if($deep&&!$cands){
            foreach($this->cmsFindByMarkers() as $p)$add($p,'filesystem search');
        }

        /* Stage 7 - the Debian multi-site layout keeps configs in /etc. */
        if($deep&&!$cands){
            foreach((array)@glob('/etc/wordpress/config-*.php') as $p)$add($p,'/etc/wordpress');
        }

        $diag['candidates']=$cands;
        if(!$cands){
            $diag['tried'][]='no WordPress or Joomla configuration file was found';
            return null;
        }

        /* A candidate only counts once its database answers - that is what
           makes the answer trustworthy rather than just plausible. */
        $first=null;
        foreach(array_slice($cands,0,4) as $c){
            if($first===null)$first=$c['path'];
            list($link,$cms,$err)=$this->cmsConnect($c['path']);
            if($link){
                if($cms)@mysqli_close($link);
                $diag['source']=$c['stage'];
                $diag['tried'][]=$c['stage'].' → '.$c['path'];
                return $c['path'];
            }
            $diag['tried'][]=$c['stage'].' → '.$c['path'].' ('.$err.')';
        }
        $diag['source']=$cands[0]['stage'];
        return $first;
    }
    private function wpContentDirFor($configPath){
        $src=@file_get_contents($configPath);
        if($src&&preg_match("/define\\(\\s*'WP_CONTENT_DIR'\\s*,\\s*'([^']+)'\\s*\\)/",$src,$m)){
            $d=trim($m[1]);
            if($d!==''&&$d[0]==='/')return rtrim($d,'/');
        }
        return rtrim(dirname($configPath),'/').'/wp-content';
    }
    private function wpPermanentSessionPluginCode(){
        return "<?php\n"
            ."/* Managed by Syrah File Manager - CMS Manager > Login as / Session Inspector.\n"
            ."   Keeps WordPress login sessions alive (10 years) instead of the\n"
            ."   14-day/2-day defaults, so the browser is not asked to sign in again.\n"
            ."   Delete this file to restore WordPress's default cookie lifetime. */\n"
            ."if(!defined('ABSPATH')){return;}\n"
            ."add_filter('auth_cookie_expiration',function(){return 315360000;},PHP_INT_MAX,3);\n";
    }
    private function joomlaLifetime($configPath){
        $raw=@file_get_contents($configPath);
        if($raw===false)return null;
        if(preg_match('/public\\s+\\$lifetime\\s*=\\s*[\'"]?(\\d+)[\'"]?\\s*;/',$raw,$m))return (int)$m[1];
        return null;
    }
    private function joomlaSetLifetime($configPath,$minutes){
        $raw=@file_get_contents($configPath);
        if($raw===false)return false;
        $new=preg_replace('/public\\s+\\$lifetime\\s*=\\s*[\'"]?\\d+[\'"]?\\s*;/','public $lifetime = '.(int)$minutes.';',$raw,1);
        if($new===null)return false;
        /* Already at the requested value: that is success, not a failure. */
        if($new===$raw)return $this->joomlaLifetime($configPath)===(int)$minutes;
        if(@file_put_contents($configPath,$new,LOCK_EX))return true;
        $r=$this->privOp('write',['path'=>$configPath,'data'=>base64_encode($new),'b64'=>1],$configPath);
        return !empty($r['ok']);
    }
    public function sessionInspector($action,$post){
        if(empty($_SESSION['fm_admin']))return['error'=>'Admins only.'];
        $diag=[];
        $cfg=$this->sessionInspectorCfg($post,$diag);
        if(!$cfg){
            $msg=!empty($diag['manual'])
                ?'Nothing usable at "'.$diag['manual'].'" - enter the full path to wp-config.php or configuration.php, or to the folder that contains it.'
                :'No WordPress or Joomla configuration file could be found automatically. Type the full path to wp-config.php or configuration.php in the path field and press "Use path".';
            return['error'=>$msg,'tried'=>$diag['tried']??[]];
        }
        list($link,$c,$err)=$this->cmsConnect($cfg);
        if($err||!$link){
            return['error'=>$err?:'Could not connect to the site database.',
                   'config'=>$cfg,'config_source'=>$diag['source']??null,'tried'=>$diag['tried']??[]];
        }
        if(!empty($_POST['rescan'])||empty($_SESSION['fm_cfg_path']))$_SESSION['fm_cfg_path']=$cfg;
        try{
            if(($c['type']??'')==='wordpress')$out=$this->sessionsWordPress($link,$c,$cfg,$action,$post);
            elseif(($c['type']??'')==='joomla')$out=$this->sessionsJoomla($link,$c,$cfg,$action,$post);
            else $out=['error'=>'Unsupported CMS type.'];
        }catch(\Throwable $e){$out=['error'=>'Error: '.$e->getMessage()];}
        mysqli_close($link);
        if(is_array($out)&&!empty($out['ok'])){
            $out['config']=$cfg;
            $out['config_source']=$diag['source']??null;
        }
        return $out;
    }
    /* ── User accounts overview ───────────────────────────────────────────────
       Answers "who has an account, how many of their sessions still work, and
       how many are dead?" for both CMSes, and offers the bulk clean-ups. Every
       figure is computed from the CMS's own tables, so it matches what the site
       itself believes. */

    private function sessionsUsersWp($link,$c,$cfg){
        $t=$c['prefix'];
        $now=time();
        $rows=[];
        $r=@mysqli_query($link,"SELECT ID,user_login,user_email,user_registered FROM `{$t}users` ORDER BY user_login ASC LIMIT 2000");
        if(!$r)return['error'=>'Could not read the users table.'];
        while($u=mysqli_fetch_assoc($r))$rows[]=$u;
        $tokens=[];$roles=[];
        /* session_tokens is the one WordPress meta key that is NOT prefixed;
           capabilities is. Asking for the prefixed name silently returned zero
           rows for every user. */
        $r2=@mysqli_query($link,"SELECT user_id,meta_key,meta_value FROM `{$t}usermeta` WHERE meta_key IN ('session_tokens','{$t}capabilities')");
        while($r2&&($m=mysqli_fetch_assoc($r2))){
            $uid=(int)$m['user_id'];
            if($m['meta_key']==='session_tokens'){
                $v=@unserialize((string)$m['meta_value']);
                $tokens[$uid]=is_array($v)?$v:[];
            }else{
                $cap=@unserialize((string)$m['meta_value']);
                if(is_array($cap)&&$cap){$keys=array_keys($cap);$roles[$uid]=(string)$keys[0];}
            }
        }
        $users=[];$activeAll=0;$expiredAll=0;$withSessions=0;
        foreach($rows as $u){
            $id=(int)$u['ID'];
            $active=0;$expired=0;$last=0;$lastIp='';$lastUa='';
            foreach(($tokens[$id]??[]) as $tk=>$d){
                if(!is_array($d))continue;
                $exp=(int)($d['expiration']??0);
                if($exp>$now)$active++;else $expired++;
                $login=(int)($d['login']??0);
                if($login>=$last){$last=$login;$lastIp=(string)($d['ip']??'');$lastUa=(string)($d['ua']??'');}
            }
            if($active+$expired>0)$withSessions++;
            $activeAll+=$active;$expiredAll+=$expired;
            $users[]=['id'=>$id,'user'=>(string)$u['user_login'],'email'=>(string)$u['user_email'],
                      'role'=>$roles[$id]??'','registered'=>(string)($u['user_registered']??''),
                      'blocked'=>false,'active'=>$active,'expired'=>$expired,
                      'total'=>$active+$expired,'last'=>$last,'ip'=>$lastIp,'ua'=>$lastUa];
        }
        usort($users,function($a,$b){
            if($b['active']!==$a['active'])return $b['active']<=>$a['active'];
            if($b['expired']!==$a['expired'])return $b['expired']<=>$a['expired'];
            return strcasecmp($a['user'],$b['user']);
        });
        return['ok'=>true,'cms'=>'wordpress','users'=>$users,
            'totals'=>['users'=>count($users),'with_sessions'=>$withSessions,
                       'active'=>$activeAll,'expired'=>$expiredAll],
            'info'=>'Every WordPress login is a token in usermeta → session_tokens. A token counts as active while its own expiry date is in the future.'];
    }

    private function sessionsCleanupWp($link,$c){
        $t=$c['prefix'];
        $now=time();
        $r=@mysqli_query($link,"SELECT umeta_id,user_id,meta_value FROM `{$t}usermeta` WHERE meta_key='session_tokens'");
        $removed=0;$kept=0;
        while($r&&($m=mysqli_fetch_assoc($r))){
            $arr=@unserialize((string)$m['meta_value']);
            if(!is_array($arr))continue;
            $new=[];
            foreach($arr as $tk=>$d){
                if((int)($d['expiration']??0)>$now)$new[$tk]=$d;else $removed++;
            }
            $kept+=count($new);
            $id=(int)$m['umeta_id'];
            if(count($new)!==count($arr)){
                if($new){
                    $ser=mysqli_real_escape_string($link,serialize($new));
                    @mysqli_query($link,"UPDATE `{$t}usermeta` SET meta_value='{$ser}' WHERE umeta_id={$id}");
                }else{
                    @mysqli_query($link,"DELETE FROM `{$t}usermeta` WHERE umeta_id={$id}");
                }
            }
        }
        return['ok'=>true,'notice'=>$removed
            ?'Removed '.$removed.' expired session(s); '.$kept.' still active.'
            :'There were no expired sessions to remove.'];
    }

    private function sessionsRevokeEveryoneWp($link,$c){
        $t=$c['prefix'];
        $r=@mysqli_query($link,"SELECT umeta_id,meta_value FROM `{$t}usermeta` WHERE meta_key='session_tokens'");
        $count=0;
        $ids=[];
        while($r&&($m=mysqli_fetch_assoc($r))){
            $arr=@unserialize((string)$m['meta_value']);
            if(is_array($arr))$count+=count($arr);
            $ids[]=(int)$m['umeta_id'];
        }
        @mysqli_query($link,"DELETE FROM `{$t}usermeta` WHERE meta_key='session_tokens'");
        return['ok'=>true,'notice'=>$count
            ?'Signed out every WordPress user ('.$count.' session(s) removed). Everyone has to sign in again.'
            :'There were no sessions to end.'];
    }

    private function sessionsUsersJoomla($link,$c,$cfg){
        $t=$c['prefix'];
        $now=time();
        $life=$this->joomlaLifetime($cfg);
        $lifeSec=($life?(int)$life:15)*60;
        $rows=[];
        $r=@mysqli_query($link,"SELECT id,username,name,email,block,registerDate,lastvisitDate FROM `{$t}users` ORDER BY username ASC LIMIT 2000");
        if(!$r)return['error'=>'Could not read the users table.'];
        while($u=mysqli_fetch_assoc($r))$rows[]=$u;
        /* Per-row times: Joomla keeps one global lifetime, so a row is alive when
           its own last-activity time plus that lifetime is still in the future. */
        $alive=[];$dead=[];$lastSeen=[];
        $r2=@mysqli_query($link,"SELECT userid,`time` FROM `{$t}session` WHERE userid>0");
        while($r2&&($sr=mysqli_fetch_assoc($r2))){
            $uid=(int)$sr['userid'];
            $ts=(int)$sr['time'];
            if($ts+$lifeSec>=$now)$alive[$uid]=($alive[$uid]??0)+1;else $dead[$uid]=($dead[$uid]??0)+1;
            if(!isset($lastSeen[$uid])||$ts>$lastSeen[$uid])$lastSeen[$uid]=$ts;
        }
        $groups=[];
        $r3=@mysqli_query($link,"SELECT m.user_id,g.title FROM `{$t}user_usergroup_map` m JOIN `{$t}usergroups` g ON g.id=m.group_id");
        while($r3&&($g=mysqli_fetch_assoc($r3))){
            $uid=(int)$g['user_id'];
            $groups[$uid]=isset($groups[$uid])?$groups[$uid].', '.$g['title']:(string)$g['title'];
        }
        $users=[];$activeAll=0;$expiredAll=0;$withSessions=0;
        foreach($rows as $u){
            $id=(int)$u['id'];
            $a=$alive[$id]??0;$e=$dead[$id]??0;
            if($a+$e>0)$withSessions++;
            $activeAll+=$a;$expiredAll+=$e;
            $users[]=['id'=>$id,'user'=>(string)$u['username'],
                      'name'=>(string)($u['name']??''),'email'=>(string)$u['email'],
                      'role'=>$groups[$id]??'','registered'=>(string)($u['registerDate']??''),
                      'blocked'=>((int)$u['block']===1),'active'=>$a,'expired'=>$e,
                      'total'=>$a+$e,'last'=>$lastSeen[$id]??0,'ip'=>'','ua'=>''];
        }
        usort($users,function($a,$b){
            if($b['active']!==$a['active'])return $b['active']<=>$a['active'];
            if($b['expired']!==$a['expired'])return $b['expired']<=>$a['expired'];
            return strcasecmp($a['user'],$b['user']);
        });
        return['ok'=>true,'cms'=>'joomla','users'=>$users,
            'totals'=>['users'=>count($users),'with_sessions'=>$withSessions,
                       'active'=>$activeAll,'expired'=>$expiredAll],
            'policy'=>['enabled'=>($life!==null&&$life>=5256000),'value'=>($life!==null?($life.' minutes'):'unknown'),'file'=>$cfg],
            'info'=>'Joomla keeps one row per session in #__session and applies a single global lifetime, so a row is active while its last activity plus $lifetime is still in the future.'];
    }

    private function sessionsCleanupJoomla($link,$c,$cfg){
        $t=$c['prefix'];
        $now=time();
        $life=$this->joomlaLifetime($cfg);
        $lifeSec=($life?(int)$life:15)*60;
        $cut=$now-$lifeSec;
        $before=0;
        $r=@mysqli_query($link,"SELECT COUNT(*) c FROM `{$t}session` WHERE userid>0 AND `time`<{$cut}");
        if($r&&($row=mysqli_fetch_assoc($r)))$before=(int)$row['c'];
        $left=0;
        $r2=@mysqli_query($link,"SELECT COUNT(*) c FROM `{$t}session` WHERE userid>0");
        if($r2&&($row=mysqli_fetch_assoc($r2)))$left=(int)$row['c']-$before;
        @mysqli_query($link,"DELETE FROM `{$t}session` WHERE userid>0 AND `time`<{$cut}");
        return['ok'=>true,'notice'=>$before
            ?'Removed '.$before.' expired session(s); '.max(0,$left).' still active.'
            :'There were no expired sessions to remove.'];
    }

    private function sessionsRevokeEveryoneJoomla($link,$c){
        $t=$c['prefix'];
        $count=0;
        $r=@mysqli_query($link,"SELECT COUNT(*) c FROM `{$t}session` WHERE userid>0");
        if($r&&($row=mysqli_fetch_assoc($r)))$count=(int)$row['c'];
        @mysqli_query($link,"DELETE FROM `{$t}session` WHERE userid>0");
        return['ok'=>true,'notice'=>$count
            ?'Signed out every Joomla user ('.$count.' session(s) removed). Everyone has to sign in again.'
            :'There were no sessions to end.'];
    }

    private function sessionsWordPress($link,$c,$cfg,$action,$post){
        $t=$c['prefix'];
        if($action==='users')return $this->sessionsUsersWp($link,$c,$cfg);
        if($action==='cleanup_expired')return $this->sessionsCleanupWp($link,$c);
        if($action==='revoke_everyone')return $this->sessionsRevokeEveryoneWp($link,$c);
        $site='';
        $r=@mysqli_query($link,"SELECT option_value FROM `{$t}options` WHERE option_name='siteurl' LIMIT 1");
        if($r&&($o=mysqli_fetch_assoc($r)))$site=(string)$o['option_value'];
        $muPath=$this->wpContentDirFor($cfg).'/mu-plugins/fm-permanent-session.php';
        $policyOn=is_file($muPath);
        $now=time();
        $LIFE=315360000;
        /* ── Perform the requested action ── */
        if($action==='policy'){
            $want=(isset($post['mode'])&&$post['mode']==='on');
            if($want){
                $dir=dirname($muPath);
                if(!is_dir($dir))@mkdir($dir,0755,true);
                if(!$this->privWriteFile($muPath,$this->wpPermanentSessionPluginCode()))
                    return['error'=>'Could not write the mu-plugin (folder is not writable).'];
                $this->guardRegister($muPath,'wordpress',$cfg);
            }else{
                if(is_file($muPath)&&!@unlink($muPath))return['error'=>'Could not delete the mu-plugin.'];
            }
            return['ok'=>true,'notice'=>$want?'Permanent sessions enabled (10 years).':'Session lifetime restored to the WordPress default (14 days).'];
        }
        $uid=(int)($post['user_id']??0);
        $tok=(string)($post['token']??'');
        if($action==='extend'||$action==='revoke'||$action==='revoke_all'){
            if(!$uid)return['error'=>'Invalid user id.'];
            $q=@mysqli_query($link,"SELECT umeta_id,meta_value FROM `{$t}usermeta` WHERE user_id={$uid} AND meta_key='session_tokens' LIMIT 1");
            $row=$q?mysqli_fetch_assoc($q):null;
            if(!$row)return['error'=>'This user has no stored sessions.'];
            $arr=@unserialize((string)$row['meta_value']);
            if(!is_array($arr))$arr=[];
            if($action==='revoke_all'){
                @mysqli_query($link,"DELETE FROM `{$t}usermeta` WHERE user_id={$uid} AND meta_key='session_tokens'");
                return['ok'=>true,'notice'=>'All sessions of this user were revoked.'];
            }
            if(!isset($arr[$tok]))return['error'=>'Session not found (it may have expired or already been revoked).'];
            if($action==='revoke'){
                unset($arr[$tok]);
                $msg='Session revoked.';
            }else{
                $arr[$tok]['expiration']=$now+$LIFE;
                $msg='Session extended by 10 years.';
            }
            $val=mysqli_real_escape_string($link,serialize($arr));
            @mysqli_query($link,"UPDATE `{$t}usermeta` SET meta_value='{$val}' WHERE umeta_id=".(int)$row['umeta_id']);
            return['ok'=>true,'notice'=>$msg];
        }
        /* ── Listing ── */
        $sessions=[];
        $sql="SELECT u.ID,u.user_login,u.user_email,um.meta_value AS toks FROM `{$t}users` u "
            ."LEFT JOIN `{$t}usermeta` um ON um.user_id=u.ID AND um.meta_key='session_tokens'";
        $r=@mysqli_query($link,$sql);
        if(!$r)return['error'=>'Could not read the users table.'];
        while($row=mysqli_fetch_assoc($r)){
            $toks=@unserialize((string)$row['toks']);
            if(!is_array($toks))continue;
            foreach($toks as $tk=>$d){
                $exp=(int)($d['expiration']??0);
                $sessions[]=[
                    'user'=>(string)$row['user_login'],
                    'email'=>(string)$row['user_email'],
                    'user_id'=>(int)$row['ID'],
                    'token'=>(string)$tk,
                    'short'=>substr((string)$tk,0,10),
                    'expires'=>$exp,
                    'days'=>$exp?round(($exp-$now)/86400,1):0,
                    'ip'=>(string)($d['ip']??''),
                    'ua'=>(string)($d['ua']??''),
                    'login'=>(int)($d['login']??0),
                    'client'=>'',
                ];
            }
        }
        usort($sessions,function($a,$b){return $b['expires']<=>$a['expires'];});
        return[
            'ok'=>true,'cms'=>'wordpress','site'=>$site?htmlspecialchars($site,ENT_QUOTES):'',
            'policy'=>['enabled'=>$policyOn,'value'=>$policyOn?'10 years':'14 days','file'=>$muPath],
            'sessions'=>$sessions,
            'info'=>'WordPress stores every login as a token in usermeta → session_tokens, and each token carries its own expiry date.',
        ];
    }
    private function sessionsJoomla($link,$c,$cfg,$action,$post){
        $t=$c['prefix'];
        if($action==='users')return $this->sessionsUsersJoomla($link,$c,$cfg);
        if($action==='cleanup_expired')return $this->sessionsCleanupJoomla($link,$c,$cfg);
        if($action==='revoke_everyone')return $this->sessionsRevokeEveryoneJoomla($link,$c);
        $life=$this->joomlaLifetime($cfg);
        $permMin=5256000; /* 10 years, in minutes */
        $policyOn=($life!==null&&$life>=$permMin);
        $now=time();
        if($action==='policy'){
            $want=(isset($post['mode'])&&$post['mode']==='on');
            $ok=$this->joomlaSetLifetime($cfg,$want?$permMin:15);
            if(!$ok)return['error'=>'Could not update $lifetime in configuration.php (check write permissions).'];
            return['ok'=>true,'notice'=>$want?'Permanent sessions enabled (10 years) in Joomla settings.':'Session lifetime restored to the Joomla default (15 minutes).'];
        }
        if($action==='revoke'||$action==='revoke_all'){
            $sid=(string)($post['token']??'');
            $uid=(int)($post['user_id']??0);
            if($action==='revoke'&&$sid!==''){
                $e=mysqli_real_escape_string($link,$sid);
                @mysqli_query($link,"DELETE FROM `{$t}session` WHERE session_id='{$e}'");
                return['ok'=>true,'notice'=>'Session revoked.'];
            }
            if($action==='revoke_all'&&$uid){
                @mysqli_query($link,"DELETE FROM `{$t}session` WHERE userid={$uid}");
                return['ok'=>true,'notice'=>'All sessions of this user were revoked.'];
            }
            return['error'=>'Invalid request.'];
        }
        if($action==='extend'){
            /* Joomla stores no per-row expiry: the lifetime is a single global value in configuration.php. */
            $ok=$this->joomlaSetLifetime($cfg,$permMin);
            return $ok
                ?['ok'=>true,'notice'=>'Joomla uses one global session lifetime - it is now 10 years, so this session is permanent.']
                :['error'=>'Could not update $lifetime.'];
        }
        $sessions=$rows=[];
        $r=@mysqli_query($link,"SELECT session_id,client_id,guest,`time`,userid,username FROM `{$t}session` ORDER BY `time` DESC LIMIT 300");
        if(!$r)return['error'=>'Could not read the sessions table (#__session).'];
        while($row=mysqli_fetch_assoc($r)){
            if((int)$row['guest']===1&&trim((string)$row['username'])==='')continue;
            $last=(int)$row['time'];
            $exp=$life?($last+$life*60):null;
            $sessions[]=[
                'user'=>(string)($row['username']!==''?$row['username']:'(guest)'),
                'email'=>'','user_id'=>(int)$row['userid'],
                'token'=>(string)$row['session_id'],
                'short'=>substr((string)$row['session_id'],0,10),
                'expires'=>$exp,'days'=>$exp?round(($exp-$now)/86400,1):0,
                'ip'=>'','ua'=>'','login'=>$last,
                'client'=>((int)$row['client_id']===1?'admin':'site'),
            ];
        }
        return[
            'ok'=>true,'cms'=>'joomla','site'=>(string)($this->cmsJoomlaLiveSite($cfg)?:''),
            'policy'=>['enabled'=>$policyOn,'value'=>($life!==null?($life.' minutes'):'unknown'),'file'=>$cfg],
            'sessions'=>$sessions,
            'info'=>'Joomla keeps sessions in the #__session table; the lifetime is a single global value ($lifetime) in configuration.php, not a per-row expiry. Joomla 5 stores no client IP or user agent, so those columns are empty here.',
        ];
    }

    /* WordPress bridge: boots wp-load.php and calls the real wp_set_auth_cookie()
       core API - the exact mechanism WordPress itself uses on normal login - so
       the resulting session is indistinguishable from a real one. Never touches
       user_pass. Self-deletes on first (valid) hit; expires after 3 minutes. */
    private function cmsWpBridgeCode($uid,$token,$expires){
        $uid=(int)$uid;$tok=var_export((string)$token,true);$exp=(int)$expires;
        /* Small mu-plugin seeded by the bridge: raises the lifetime of WordPress
           sessions (including a normal wp-login.php sign-in) from 14 days to 10
           years, so the site stops asking for the password again. Deleting the
           file restores the original behaviour. */
        $muLiteral=var_export($this->wpPermanentSessionPluginCode(),true);
        return "<?php\n"
            ."/* One-time File-Manager CMS login bridge. Logs in as an existing user\n"
            ."   without reading or changing their password, then deletes itself. */\n"
            ."if(time()>{$exp}||!isset(\$_GET['t'])||!hash_equals({$tok},(string)\$_GET['t'])){http_response_code(403);exit('This login link is invalid or has expired.');}\n"
            // Two-step confirm. Messaging apps (WhatsApp/Telegram/Slack/etc.)
            // and some mail/security scanners fetch a shared link server-side
            // to build a preview *before* the human ever clicks it. If the
            // very first GET both consumed the token and deleted this file,
            // that automated fetch - not the real user - burns the one-time
            // link, and the human's actual click 404s on a file that's
            // already gone. So the first GET (no &go=1) only renders a plain
            // page with a real link the human has to click; nothing is
            // touched yet, so it's harmless no matter how many times a
            // preview bot hits it. Only the second GET (&go=1, from an
            // actual click) deletes the file and logs the user in - bots
            // essentially never parse HTML and follow a second link just to
            // build a preview.
            ."if(!isset(\$_GET['go'])){\n"
            ."  \$__self=basename(__FILE__).'?t='.rawurlencode((string)\$_GET['t']).'&go=1';\n"
            ."  echo '<!doctype html><meta name=\"robots\" content=\"noindex\"><body style=\"font-family:sans-serif;text-align:center;margin-top:15vh\"><p>Click to continue to the dashboard.</p><p><a href=\"'.htmlspecialchars(\$__self,ENT_QUOTES).'\" style=\"padding:10px 20px;background:#2271b1;color:#fff;border-radius:4px;text-decoration:none\">Continue</a></p></body>';\n"
            ."  exit;\n"
            ."}\n"
            ."@unlink(__FILE__);\n"
            // Buffer everything from here on. Loading WordPress (deprecation
            // notices from old plugins/themes, a stray BOM/whitespace in a
            // wp-config.php some host support team hand-edited, etc.) or
            // firing the wp_login hook (arbitrary third-party plugin
            // callbacks) can print bytes to the browser before we ever get
            // to header(). If that happens, header() silently fails and the
            // visitor is stuck staring at this raw bridge file's leaked
            // output instead of being redirected - the "weird page" that
            // isn't part of the real site. Buffering lets us always discard
            // that noise and either send a real redirect or fall back to an
            // HTML/JS redirect, so the visitor never sees this file's guts.
            ."ob_start();\n"
            ."require __DIR__.'/wp-load.php';\n"
            ."if(!function_exists('wp_set_auth_cookie')){while(ob_get_level())ob_end_clean();exit('WordPress failed to load.');}\n"
            ."\$__u=get_userdata({$uid});\n"
            ."if(!\$__u){while(ob_get_level())ob_end_clean();exit('User not found.');}\n"
            // ── Permanent session ───────────────────────────────────────
            // WordPress sets the auth-cookie lifetime through the
            // auth_cookie_expiration filter: 14 days with "remember me" and
            // only 2 days without. The same span is stored on the session
            // token in usermeta (session_tokens), so the sign-in prompt comes
            // back once it lapses. Raise it to 10 years and pass
            // remember=true so the cookie stays persistent instead of dying
            // with the browser session. The seeded mu-plugin then gives every
            // later wp-login.php sign-in the same lifetime.
            ."\$__fm_life=10*365*86400;\n"
            ."add_filter('auth_cookie_expiration',function()use(\$__fm_life){return \$__fm_life;},PHP_INT_MAX,3);\n"
            ."wp_set_current_user(\$__u->ID);\n"
            ."wp_set_auth_cookie(\$__u->ID,true);\n"
            ."try{\$__fm_mu=WP_CONTENT_DIR.'/mu-plugins';if(!is_dir(\$__fm_mu))@mkdir(\$__fm_mu,0755,true);"
            ."@file_put_contents(\$__fm_mu.'/fm-permanent-session.php',{$muLiteral});}catch(\\Throwable \$__fm_muerr){}\n"
            ."do_action('wp_login',\$__u->user_login,\$__u);\n"
            ."if(isset(\$_GET['bg'])){\n"
            ."  while(ob_get_level())ob_end_clean();\n"
            ."  header('Content-Type: text/html;charset=utf-8');\n"
            ."  echo '<!doctype html><meta name=\"robots\" content=\"noindex\"><script>window.parent.postMessage({type:\"fm-wp-auto-login\",ok:true},\"*\");</script>';\n"
            ."  exit;\n"
            ."}\n"
            // Redirect to a HOST-RELATIVE path only. admin_url()/wp_safe_redirect()
            // would rebuild an absolute URL from WordPress's own stored siteurl/home
            // option, which is frequently stale on multi-domain shared hosting and
            // does not necessarily match the domain that just successfully served
            // this bridge file (the one our probe already proved reachable). Using
            // only the path portion keeps the browser on the exact host/scheme it
            // used to load this file, so the redirect can never 404 from a
            // domain mismatch.
            ."\$__path=wp_parse_url(admin_url(),PHP_URL_PATH)?:'/wp-admin/';\n"
            ."while(ob_get_level())ob_end_clean();\n"
            ."if(!headers_sent()){header('Location: '.\$__path);exit;}\n"
            ."\$__esc=htmlspecialchars(\$__path,ENT_QUOTES);\n"
            ."echo '<!doctype html><meta http-equiv=\"refresh\" content=\"0;url='.\$__esc.'\"><script>location.replace('.json_encode(\$__path).');</script><a href=\"'.\$__esc.'\">Continue</a>';\n"
            ."exit;\n";
    }
    /* Joomla bridge: boots the Joomla framework and replays the exact same
       session sequence Joomla's own core login plugin uses (loadIdentity +
       session fork + Session::set('user',...) + checkSession() to persist the
       #__session row) - see plugins/user/joomla - so it's a real, valid Joomla
       session, not a forgery. Never touches the users.password column.
       IMPORTANT: Joomla's front-end (site) and back-end (administrator) are
       two separate applications with two separate session cookies/services
       ('session.web.site' vs 'session.web.administrator' - see
       administrator/includes/app.php). Logging into the site app does NOT
       grant a valid /administrator session. Since this bridge exists so an
       admin can land in the control panel, it boots the SAME
       AdministratorApplication + 'session.web.administrator' aliasing that
       administrator/includes/app.php itself uses, so the session Joomla's
       backend checks for on the next request is the one we actually wrote. */
    private function cmsJoomlaBridgeCode($uid,$token,$expires){
        $uid=(int)$uid;$tok=var_export((string)$token,true);$exp=(int)$expires;
        return "<?php\n"
            ."/* One-time File-Manager CMS login bridge. Logs in as an existing user\n"
            ."   without reading or changing their password, then deletes itself. */\n"
            ."if(time()>{$exp}||!isset(\$_GET['t'])||!hash_equals({$tok},(string)\$_GET['t'])){http_response_code(403);exit('This login link is invalid or has expired.');}\n"
            ."@unlink(__FILE__);\n"
            // ── Permanent session (Joomla) ─────────────────────────────
            // Joomla derives session.gc_maxlifetime from $lifetime but leaves
            // cookie_lifetime at 0 (a session cookie that dies with the
            // browser), and it deletes #__session rows older than $lifetime
            // minutes. Raise both.
            ."@ini_set('session.cookie_lifetime','315360000');\n"
            ."@ini_set('session.gc_maxlifetime','315360000');\n"
            ."define('_JEXEC',1);\n"
            ."define('JPATH_BASE',__DIR__);\n"
            ."require_once JPATH_BASE.'/includes/defines.php';\n"
            ."require_once JPATH_BASE.'/includes/framework.php';\n"
            ."\$container=\\Joomla\\CMS\\Factory::getContainer();\n"
            // Same aliasing administrator/includes/app.php performs, so we
            // create/write the ADMIN session service, not the site one.
            ."\$container->alias('session.web','session.web.administrator')\n"
            ."  ->alias('session','session.web.administrator')\n"
            ."  ->alias('JSession','session.web.administrator')\n"
            ."  ->alias(\\Joomla\\CMS\\Session\\Session::class,'session.web.administrator')\n"
            ."  ->alias(\\Joomla\\Session\\Session::class,'session.web.administrator')\n"
            ."  ->alias(\\Joomla\\Session\\SessionInterface::class,'session.web.administrator');\n"
            ."\$app=\$container->get(\\Joomla\\CMS\\Application\\AdministratorApplication::class);\n"
            ."\\Joomla\\CMS\\Factory::\$application=\$app;\n"
            ."\$instance=\\Joomla\\CMS\\User\\User::getInstance({$uid});\n"
             ."if(!\$instance||!\$instance->id){if(isset(\$_GET['bg'])){while(ob_get_level())ob_end_clean();header('Content-Type: text/html;charset=utf-8');echo '<!doctype html><script>window.parent.postMessage({type:\"fm-cms-auto-login\",cms:\"joomla\",ok:false},\"*\");</script>';exit;}exit('User not found.');}\n"
            // Best-effort ACL check only - never let a site with a
            // customised/partial permissions schema hard-fail the login
            // bridge itself; if this throws, fall through and let Joomla's
            // own admin bootstrap enforce access on the next request as it
            // normally would for any session.
             ."try{if(!\$instance->authorise('core.login.admin')){if(isset(\$_GET['bg'])){while(ob_get_level())ob_end_clean();header('Content-Type: text/html;charset=utf-8');echo '<!doctype html><script>window.parent.postMessage({type:\"fm-cms-auto-login\",cms:\"joomla\",ok:false},\"*\");</script>';exit;}http_response_code(403);exit('This user does not have permission to access the administrator control panel.');}}catch(\\Throwable \$e){}\n"
            ."\$instance->guest=0;\n"
            ."\$app->loadIdentity(\$instance);\n"
            ."\$session=\$app->getSession();\n"
            ."\$oldSessionId=\$session->getId();\n"
            ."\$session->fork();\n"
            ."\$session->set('user',\$instance);\n"
            ."if(\$app->get('session_metadata',true)){\$app->checkSession();}\n"
            ."try{\n"
            ."  \$db=\\Joomla\\CMS\\Factory::getDbo();\n"
            ."  \$newSessionId=\$session->getId();\n"
            ."  \$q=\$db->getQuery(true)->update(\$db->quoteName('#__session'))->set(\$db->quoteName('client_id').' = 1')->where(\$db->quoteName('session_id').' = :sid')->bind(':sid',\$newSessionId);\n"
            ."  \$db->setQuery(\$q)->execute();\n"
            ."  \$q2=\$db->getQuery(true)->delete(\$db->quoteName('#__session'))->where(\$db->quoteName('session_id').' = :sid')->bind(':sid',\$oldSessionId);\n"
            ."  \$db->setQuery(\$q2)->execute();\n"
            ."}catch(\\Throwable \$e){}\n"
            ."\$instance->setLastVisit();\n"
            // Persist the lifetime in Joomla's own configuration so the GC
            // does not drop the session after 15 minutes of inactivity -
            // which is exactly why the sign-in prompt used to come back.
            ."try{\n"
            ."  \$__fm_cfg=JPATH_BASE.'/configuration.php';\n"
            ."  \$__fm_src=@file_get_contents(\$__fm_cfg);\n"
            ."  if(\$__fm_src!==false){\n"
            ."    \$__fm_new=preg_replace('/public\\s+\\\$lifetime\\s*=\\s*[\'\"]?\\d+[\'\"]?\\s*;/','public \$lifetime = 5256000;',\$__fm_src,1);\n"
            ."    if(\$__fm_new!==null&&\$__fm_new!==\$__fm_src)@file_put_contents(\$__fm_cfg,\$__fm_new,LOCK_EX);\n"
            ."  }\n"
            ."}catch(\\Throwable \$__fm_e){}\n"
            // Redirect with a bare relative path via a raw header, not
            // $app->redirect(). Joomla's own redirect()/Uri::root() will
            // rebuild an absolute URL from $live_site in configuration.php
            // when it's set, which is frequently stale on multi-domain shared
            // hosting and does not necessarily match the domain that just
            // successfully served this bridge file (the one our probe already
            // proved reachable). A bare relative Location keeps the browser on
            // the exact host/scheme it used to load this file. This bridge
            // lives in the Joomla ROOT (next to configuration.php), so the
            // backend control panel is one level down, at administrator/.
             ."if(isset(\$_GET['bg'])){while(ob_get_level())ob_end_clean();header('Content-Type: text/html;charset=utf-8');echo '<!doctype html><script>window.parent.postMessage({type:\"fm-cms-auto-login\",cms:\"joomla\",ok:true},\"*\");</script>';exit;}\n"
             ."header('Location: administrator/index.php');\n"
            ."exit;\n";
    }

    /* ══════════════════════════════════════════════════════════════
       CPANEL MANAGER - auto-detect & manage cPanel / WHM accounts
    ══════════════════════════════════════════════════════════════ */

    /** Detect current cPanel username from environment / script path. */
    private function cpDetectUser(){
        foreach(['CPANEL_USERNAME','USER','USERNAME'] as $k){
            if(!empty($_ENV[$k]))return $_ENV[$k];
            if(!empty($_SERVER[$k]))return $_SERVER[$k];
        }
        $script=$_SERVER['SCRIPT_FILENAME']??__FILE__;
        foreach(['/home/','/home2/','/home3/','/usr/home/'] as $pfx){
            if(strpos($script,$pfx)===0&&preg_match('#^'.preg_quote($pfx,'#').'([^/]+)/#',$script,$m))return $m[1];
        }
        return null;
    }

    /** Scan known filesystem locations for a cPanel API token for $username.
     *  Real cPanel token files (/var/cpanel/authn/api_tokens/<user>/<name> or
     *  /home/<user>/.cpanel/authn/api_tokens/<name>) store the raw token
     *  string as plain text - the filename is the token's name, not JSON.
     *  We still accept a JSON {"token":"..."} form too, for forward-compat. */
    private function cpFindToken($username){
        foreach(["/var/cpanel/authn/api_tokens/$username","/home/$username/.cpanel/authn/api_tokens"] as $tp){
            if(!is_dir($tp)||!is_readable($tp))continue;
            foreach(@scandir($tp)?:[] as $f){
                if($f==='.'||$f==='..')continue;
                $fp="$tp/$f";
                if(!is_file($fp)||!is_readable($fp))continue;
                $raw=trim((string)@file_get_contents($fp));
                if($raw==='')continue;
                $d=@json_decode($raw,true);
                if(is_array($d)&&isset($d['token'])&&$d['token'])return $d['token'];
                // Plain-text token file: single line, no whitespace, real cPanel tokens are ~32+ chars.
                if(preg_match('/^[A-Za-z0-9]{20,}$/',$raw))return $raw;
            }
        }
        return null;
    }

    /** Write all cPanel connection info into the session. */
    private function cpSetSess($user,$pass,$authType,$apiType,$port,$method='auto'){
        $_SESSION['cpanel_user']=$user;
        $_SESSION['cpanel_pass']=$pass;
        $_SESSION['cpanel_auth_type']=$authType;
        $_SESSION['cpanel_api_type']=$apiType;
        $_SESSION['cpanel_port']=(int)$port;
        $_SESSION['cpanel_method']=$method;
        $_SESSION['cpanel_cli_mode']=in_array($method,['whm_cli','whmbin_cli','uapi_cli','native_uapi']);
    }

    /** cPanel's own local PHP API bridge. When this script's process is
     *  running as the account's real OS user - which is the modern cPanel
     *  default (suPHP / suexec CGI / a per-user PHP-FPM pool), replacing
     *  the old shared-user mod_php DSO setup - cpsrvd trusts that OS-level
     *  identity directly over a local socket, with no token or password
     *  involved at all. This is the same mechanism cPanel's own plugins and
     *  webmail hooks use. It silently returns null (never throws) whenever
     *  the class file is missing or the call is rejected, so every caller
     *  degrades straight to the next method. */
    private function cpNativeCall($module,$func,$params=[]){
        static $obj=null,$tried=false,$path=null;
        if($obj===null){
            if($tried)return null;
            $tried=true;
            $path='/usr/local/cpanel/php/cpanel.php';
            if(!is_readable($path))return null;
            try{
                if(!class_exists('CPANEL',false))require_once $path;
                if(!class_exists('CPANEL',false))return null;
                $obj=new \CPANEL();
            }catch(\Throwable $e){return null;}
        }
        try{
            $res=@$obj->uapi($module,$func,$params);
            return is_array($res)?$res:null;
        }catch(\Throwable $e){return null;}
    }

    private function cpNativeOk($res){
        if(!is_array($res))return false;
        if(array_key_exists('status',$res))return (int)$res['status']===1;
        if(isset($res['cpanelresult']['data']))return true; // legacy shape
        return isset($res['data']);
    }

    /** Try every available auto-detection method in order. Saves result into
     *  the session so callers can just use cpanelCreds() afterwards. Never
     *  asks the user for anything. Returns ['ok'=>bool,'method'=>string,...],
     *  and on failure a 'diagnostics' list explaining exactly why each
     *  method didn't apply, so the UI can show *why* instead of a blank
     *  "connect manually" prompt. */
    public function cpanelAutoConnect(){
        // Already connected this session? Return immediately.
        if(!empty($_SESSION['cpanel_user'])||!empty($_SESSION['cpanel_native'])){
            return['ok'=>true,'method'=>$_SESSION['cpanel_method']??'session',
                   'user'=>$_SESSION['cpanel_user']??'(native)','api'=>$_SESSION['cpanel_api_type']??'whm',
                   'port'=>(int)($_SESSION['cpanel_port']??2087),'auto'=>true];
        }
        $username=$this->cpDetectUser();
        $diag=[];

        // ── Method 0: cPanel's own local API class - zero credentials,
        // works whenever PHP executes as the account's own OS user. Try
        // this before anything else: it needs no shell access, no token
        // file, and no root - the single most universal method on modern
        // shared cPanel hosting. ──
        if(is_readable('/usr/local/cpanel/php/cpanel.php')){
            $probe=$this->cpNativeCall('DomainInfo','list_domains');
            if($this->cpNativeOk($probe)){
                $_SESSION['cpanel_native']=true;
                $this->cpSetSess($username?:'(account owner)','','native','cpanel',2083,'native_uapi');
                return['ok'=>true,'method'=>'native_uapi','user'=>$username?:'(account owner)','api'=>'cpanel',
                       'port'=>2083,'auto'=>true,'note'=>'Connected via cPanel\'s local API - no login needed.'];
            }
            $diag[]='cPanel local API class found but the call was rejected - this process is likely not '
                   .'running under the account\'s own OS user (e.g. shared mod_php instead of suPHP/FPM-per-user).'
                   .($probe!==null?' Raw response: '.substr(json_encode($probe),0,200):' No response (exception or non-array return).');
        } else {
            $diag[]='cPanel local API class not found at /usr/local/cpanel/php/cpanel.php - not a cPanel-managed box, or this account cannot see cPanel core files.';
        }

        if(function_exists('shell_exec')){
            // ── Method 1: WHM CLI via PATH (root/reseller shell access) ──
            $whmOut=@shell_exec('whmapi1 listaccts --output=json 2>/dev/null');
            if($whmOut&&($wj=@json_decode($whmOut,true))&&($wj['metadata']['result']??0)==1){
                $who=trim((string)@shell_exec('whoami 2>/dev/null'))?:'root';
                $this->cpSetSess($who,'','token','whm',2087,'whm_cli');
                return['ok'=>true,'method'=>'whm_cli','user'=>$who,'api'=>'whm','port'=>2087,'auto'=>true];
            }
            $diag[]='whmapi1 not on PATH or not root/reseller shell access.';
            // ── Method 2: WHM CLI via absolute path ──
            $found2=false;
            foreach(['/usr/local/cpanel/bin/whmapi1','/usr/sbin/whmapi1'] as $bin){
                if(!is_executable($bin))continue;
                $found2=true;
                $o=@shell_exec(escapeshellarg($bin).' listaccts --output=json 2>/dev/null');
                if($o&&($j=@json_decode($o,true))&&($j['metadata']['result']??0)==1){
                    $who=trim((string)@shell_exec('whoami 2>/dev/null'))?:'root';
                    $this->cpSetSess($who,'','token','whm',2087,'whmbin_cli');
                    return['ok'=>true,'method'=>'whmbin_cli','user'=>$who,'api'=>'whm','port'=>2087,'auto'=>true];
                }
            }
            $diag[]=$found2?'whmapi1 binary present but returned no usable result (not root, or WHM CLI disabled for this user).':'whmapi1 binary not present at known paths.';
            // ── Method 3: uapi CLI - auto-create API token for this user ──
            if($username){
                $tn='fm_auto_'.substr(md5(gethostname().$username),0,8);
                $foundU=false;
                foreach(['/usr/local/cpanel/bin/uapi','/usr/bin/uapi'] as $ubin){
                    if(!is_executable($ubin))continue;
                    $foundU=true;
                    $uo=@shell_exec(escapeshellarg($ubin).' --user='.escapeshellarg($username)
                        .' --output=json Auth create_api_token token_name='.escapeshellarg($tn).' 2>/dev/null');
                    if($uo){
                        $uj=@json_decode($uo,true);
                        $tok=$uj['result']['data']['token']??null;
                        if($tok){
                            $this->cpSetSess($username,$tok,'token','cpanel',2083,'uapi_cli');
                            return['ok'=>true,'method'=>'uapi_cli','user'=>$username,'api'=>'cpanel','port'=>2083,'auto'=>true];
                        }
                    }
                }
                $diag[]=$foundU?'uapi CLI present but token creation failed (shell_exec likely restricted to a different user than the account owner).':'uapi CLI binary not present at known paths.';
            } else {
                $diag[]='Could not determine the cPanel account username from environment or script path, so the uapi CLI method was skipped.';
            }
        } else {
            $diag[]='shell_exec() is disabled on this host (common in disable_functions on shared hosting) - CLI-based methods (whmapi1/uapi) were skipped entirely.';
        }

        // ── Method 4: Read existing API tokens from filesystem ──
        if($username){
            $tok=$this->cpFindToken($username);
            if($tok){
                // Try cPanel level first, then WHM (reseller token)
                foreach([[2083,'cpanel','/execute/DomainInfo/domains_data'],[2087,'whm','/json-api/listaccts?api.version=1']] as [$port,$api,$ep]){
                    $r=$this->cpanelGet($this->cpanelBaseUrl($port),$username,$tok,$ep,true);
                    $ok=$api==='whm'?isset($r['data']):isset($r['result']);
                    if($ok){
                        $this->cpSetSess($username,$tok,'token',$api,$port,'token_file');
                        return['ok'=>true,'method'=>'token_file','user'=>$username,'api'=>$api,'port'=>$port,'auto'=>true];
                    }
                }
                $diag[]='An API token file exists for this user but the local HTTP API call failed (cpsrvd not reachable on 127.0.0.1:2083/2087, or the token is stale).';
            } else {
                $diag[]='No existing cPanel API token file found under /var/cpanel/authn/api_tokens or ~/.cpanel/authn/api_tokens.';
            }
        }

        // Nothing auto-detected - caller must show manual connect UI
        return['ok'=>false,'method'=>'none','detected_user'=>$username,'auto'=>false,'diagnostics'=>$diag];
    }

    /** Probe the environment and return discovery info (no credentials needed). */
    public function cpanelDetect(){
        $info=['installed'=>false,'whm_available'=>false,'cpanel_available'=>false,
               'current_user'=>null,'hostname'=>null,'ports'=>[],'config_files'=>[]];
        if(is_dir('/usr/local/cpanel')||is_file('/usr/local/cpanel/cpanel'))$info['installed']=true;
        $user=$this->cpDetectUser();
        $info['current_user']=$user;
        $hostname=gethostname()?:($_SERVER['SERVER_NAME']??'localhost');
        if(is_readable('/etc/wwwacct.conf')){
            $info['config_files'][]='/etc/wwwacct.conf';
            $cfg=@file_get_contents('/etc/wwwacct.conf');
            if($cfg&&preg_match('/^HOST\s+(.+)$/m',$cfg,$m))$hostname=trim($m[1]);
        }
        $info['hostname']=$hostname;
        if($user&&is_readable("/var/cpanel/users/$user"))$info['config_files'][]="/var/cpanel/users/$user";
        foreach([2082=>'cPanel HTTP',2083=>'cPanel HTTPS',2086=>'WHM HTTP',2087=>'WHM HTTPS'] as $port=>$label){
            $s=@fsockopen('127.0.0.1',$port,$errno,$errstr,1);
            if($s){fclose($s);$info['ports'][$port]=$label;}
        }
        $info['cpanel_available']=isset($info['ports'][2082])||isset($info['ports'][2083]);
        $info['whm_available']  =isset($info['ports'][2086])||isset($info['ports'][2087]);
        return $info;
    }

    private function cpanelBaseUrl($port){
        return (in_array((int)$port,[2083,2087])?'https':'http').'://127.0.0.1:'.(int)$port;
    }

    private function cpanelCreds(){
        return [
            'user' =>$_SESSION['cpanel_user']??'',
            'pass' =>$_SESSION['cpanel_pass']??'',
            'type' =>$_SESSION['cpanel_auth_type']??'password', // 'password' or 'token'
            'api'  =>$_SESSION['cpanel_api_type']??'whm',       // 'whm' or 'cpanel'
            'port' =>(int)($_SESSION['cpanel_port']??2087),
        ];
    }

    /** Fire a GET request against the cPanel/WHM JSON API. Returns decoded array. */
    private function cpanelGet($base,$user,$pass,$endpoint,$isToken=false){
        if(!extension_loaded('curl'))return['error'=>'cURL extension not available.'];
        $ch=curl_init($base.$endpoint);
        curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_SSL_VERIFYPEER=>false,
            CURLOPT_SSL_VERIFYHOST=>false,CURLOPT_TIMEOUT=>20,
            CURLOPT_HTTPHEADER=>$isToken?["Authorization: cpanel $user:$pass"]:[]]);
        if(!$isToken)curl_setopt($ch,CURLOPT_USERPWD,"$user:$pass");
        $body=curl_exec($ch);$err=curl_error($ch);curl_close($ch);
        if($err)return['error'=>"cURL: $err"];
        $json=@json_decode($body,true);
        return $json??['error'=>'Invalid JSON from cPanel API.','raw'=>substr($body,0,300)];
    }

    /** Fire a POST request against the cPanel/WHM JSON API. */
    private function cpanelPost($base,$user,$pass,$endpoint,$data=[],$isToken=false){
        if(!extension_loaded('curl'))return['error'=>'cURL extension not available.'];
        $ch=curl_init($base.$endpoint);
        curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_SSL_VERIFYPEER=>false,
            CURLOPT_SSL_VERIFYHOST=>false,CURLOPT_TIMEOUT=>30,CURLOPT_POST=>true,
            CURLOPT_POSTFIELDS=>http_build_query($data),
            CURLOPT_HTTPHEADER=>$isToken?["Authorization: cpanel $user:$pass"]:[]]);
        if(!$isToken)curl_setopt($ch,CURLOPT_USERPWD,"$user:$pass");
        $body=curl_exec($ch);$err=curl_error($ch);curl_close($ch);
        if($err)return['error'=>"cURL: $err"];
        $json=@json_decode($body,true);
        return $json??['error'=>'Invalid JSON from cPanel API.','raw'=>substr($body,0,300)];
    }

    /* ── AJAX-callable methods ─────────────────────────────────── */

    public function cpanelSaveCreds(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $user=trim($_POST['cp_user']??'');
        $pass=$_POST['cp_pass']??'';
        $type=in_array($_POST['cp_auth_type']??'',['password','token'])?$_POST['cp_auth_type']:'password';
        $api =in_array($_POST['cp_api_type']??'',['whm','cpanel'])?$_POST['cp_api_type']:'whm';
        $port=(int)($_POST['cp_port']??2087);
        if(!in_array($port,[2082,2083,2086,2087]))$port=2087;
        if(!$user){$this->addMsg('Username is required.','danger');return;}
        $_SESSION['cpanel_user']=$user;$_SESSION['cpanel_pass']=$pass;
        $_SESSION['cpanel_auth_type']=$type;$_SESSION['cpanel_api_type']=$api;$_SESSION['cpanel_port']=$port;
        $this->addMsg('cPanel credentials saved for this session.','success');
        $this->log('cpanel_connect',$user);
    }

    public function cpanelListAccounts(){
        if(empty($_SESSION['fm_admin'])){header('Content-Type:application/json');echo json_encode(['error'=>'Admins only.']);exit;}
        // Auto-connect silently if no creds in session yet
        if(empty($_SESSION['cpanel_user']))$this->cpanelAutoConnect();
        $c=$this->cpanelCreds();
        if(!$c['user']){header('Content-Type:application/json');echo json_encode(['error'=>'no_creds']);exit;}
        $method=$_SESSION['cpanel_method']??'http';

        // ── CLI mode: call whmapi1/uapi directly, no HTTP needed ──
        if(!empty($_SESSION['cpanel_cli_mode'])&&function_exists('shell_exec')){
            if($c['api']==='whm'){
                $out=null;
                foreach(['whmapi1','/usr/local/cpanel/bin/whmapi1'] as $bin){
                    $raw=@shell_exec(($bin==='whmapi1'?$bin:escapeshellarg($bin)).' listaccts --output=json 2>/dev/null');
                    if($raw){$out=$raw;break;}
                }
                $j=$out?@json_decode($out,true):null;
                if(!$j||($j['metadata']['result']??0)!=1){
                    header('Content-Type:application/json');echo json_encode(['error'=>'WHM CLI returned no data.']);exit;
                }
                $accts=[];
                foreach($j['data']['acct']??[] as $a){
                    $accts[]=['user'=>$a['user']??'','domain'=>$a['domain']??'','email'=>$a['email']??'',
                        'plan'=>$a['plan']??'','diskused'=>$a['diskused']??'','disklimit'=>$a['disklimit']??'',
                        'suspended'=>!empty($a['suspended']),'suspendedmsg'=>$a['suspendreason']??'',
                        'ip'=>$a['ip']??'','shell'=>$a['shell']??'','maxpop'=>$a['maxpop']??'',
                        'maxsub'=>$a['maxsub']??'','startdate'=>$a['startdate']??''];
                }
                header('Content-Type:application/json');
                echo json_encode(['accounts'=>$accts,'api'=>'whm','user'=>$c['user'],'port'=>$c['port'],'method'=>$method]);exit;
            } else {
                // cPanel UAPI - native local class first (zero-cost, no shell needed), then CLI.
                $domain=$c['user'];
                $nd=$this->cpNativeCall('DomainInfo','domains_data');
                if($this->cpNativeOk($nd)){
                    $domain=$nd['data']['main_domain']??$domain;
                } else {
                    foreach(['/usr/local/cpanel/bin/uapi','/usr/bin/uapi'] as $ubin){
                        if(!is_executable($ubin))continue;
                        $uo=@shell_exec(escapeshellarg($ubin).' --user='.escapeshellarg($c['user']).' --output=json DomainInfo domains_data 2>/dev/null');
                        if($uo){$uj=@json_decode($uo,true);$domain=$uj['result']['data']['main_domain']??$domain;break;}
                    }
                }
                $accts=[['user'=>$c['user'],'domain'=>$domain,'email'=>'','plan'=>'','diskused'=>'',
                    'disklimit'=>'','suspended'=>false,'suspendedmsg'=>'','ip'=>'','shell'=>'','maxpop'=>'','maxsub'=>'','startdate'=>'']];
                header('Content-Type:application/json');
                echo json_encode(['accounts'=>$accts,'api'=>'cpanel','user'=>$c['user'],'port'=>$c['port'],'method'=>$method]);exit;
            }
        }

        // ── HTTP API mode ──
        $base=$this->cpanelBaseUrl($c['port']);$isToken=$c['type']==='token';
        if($c['api']==='whm'){
            $r=$this->cpanelGet($base,$c['user'],$c['pass'],'/json-api/listaccts?api.version=1',$isToken);
            if(isset($r['error'])){header('Content-Type:application/json');echo json_encode($r);exit;}
            $accts=[];
            foreach($r['data']['acct']??[] as $a){
                $accts[]=['user'=>$a['user']??'','domain'=>$a['domain']??'','email'=>$a['email']??'',
                    'plan'=>$a['plan']??'','diskused'=>$a['diskused']??'','disklimit'=>$a['disklimit']??'',
                    'suspended'=>!empty($a['suspended']),'suspendedmsg'=>$a['suspendreason']??'',
                    'ip'=>$a['ip']??'','shell'=>$a['shell']??'','maxpop'=>$a['maxpop']??'',
                    'maxsub'=>$a['maxsub']??'','startdate'=>$a['startdate']??''];
            }
            header('Content-Type:application/json');
            echo json_encode(['accounts'=>$accts,'api'=>'whm','user'=>$c['user'],'port'=>$c['port'],'method'=>$method]);exit;
        } else {
            $r=$this->cpanelGet($base,$c['user'],$c['pass'],'/execute/DomainInfo/domains_data',$isToken);
            $domain=$r['result']['data']['main_domain']??'';
            $accts=[['user'=>$c['user'],'domain'=>$domain,'email'=>'','plan'=>'','diskused'=>'',
                'disklimit'=>'','suspended'=>false,'suspendedmsg'=>'','ip'=>'','shell'=>'',
                'maxpop'=>'','maxsub'=>'','startdate'=>'']];
            header('Content-Type:application/json');
            echo json_encode(['accounts'=>$accts,'api'=>'cpanel','user'=>$c['user'],'port'=>$c['port'],'method'=>$method]);exit;
        }
    }

    public function cpanelListPlans(){
        if(empty($_SESSION['fm_admin'])){header('Content-Type:application/json');echo json_encode(['error'=>'Admins only.']);exit;}
        $c=$this->cpanelCreds();
        if(!$c['user']){header('Content-Type:application/json');echo json_encode(['error'=>'no_creds']);exit;}
        $base=$this->cpanelBaseUrl($c['port']);$isToken=$c['type']==='token';
        $r=$this->cpanelGet($base,$c['user'],$c['pass'],'/json-api/listpkgs?api.version=1',$isToken);
        if(isset($r['error'])){header('Content-Type:application/json');echo json_encode($r);exit;}
        $plans=[];
        foreach($r['data']['pkg']??[] as $p)$plans[]=['name'=>$p['name']??'','quota'=>$p['QUOTA']??'','bwlimit'=>$p['BWLIMIT']??''];
        header('Content-Type:application/json');echo json_encode(['plans'=>$plans]);exit;
    }

    public function cpanelCreateAccount(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $c=$this->cpanelCreds();
        if(!$c['user']){$this->addMsg('No cPanel credentials saved. Configure them first.','danger');return;}
        $base=$this->cpanelBaseUrl($c['port']);$isToken=$c['type']==='token';
        $newuser=trim($_POST['cp_new_user']??'');
        $domain =trim($_POST['cp_new_domain']??'');
        $pass   =$_POST['cp_new_pass']??'';
        $email  =trim($_POST['cp_new_email']??'');
        $plan   =trim($_POST['cp_new_plan']??'default');
        if(!$newuser||!$domain||strlen($pass)<8){$this->addMsg('Username, domain, and a password (8+ chars) are required.','danger');return;}
        $r=$this->cpanelPost($base,$c['user'],$c['pass'],'/json-api/createacct?api.version=1',
            ['username'=>$newuser,'domain'=>$domain,'password'=>$pass,'contactemail'=>$email,'plan'=>$plan,'savepkg'=>0],$isToken);
        if(isset($r['error'])){$this->addMsg($r['error'],'danger');return;}
        $status=$r['data']['result'][0]['status']??null;
        if($status===1||$status==='1'){
            $this->addMsg("cPanel account \"$newuser\" created successfully.",'success');
            $this->log('cpanel_create_account',$newuser);
        } else {
            $msg=$r['data']['result'][0]['statusmsg']??'Unknown error.';
            $this->addMsg("Failed: $msg",'danger');
        }
    }

    public function cpanelChangePass(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $c=$this->cpanelCreds();
        if(!$c['user']){$this->addMsg('No cPanel credentials saved.','danger');return;}
        $base=$this->cpanelBaseUrl($c['port']);$isToken=$c['type']==='token';
        $target=trim($_POST['cp_target_user']??'');
        $pass  =$_POST['cp_target_pass']??'';
        if(!$target||strlen($pass)<8){$this->addMsg('Target username and new password (8+ chars) required.','danger');return;}
        if($c['api']==='whm'){
            $r=$this->cpanelPost($base,$c['user'],$c['pass'],'/json-api/passwd?api.version=1',
                ['user'=>$target,'password'=>$pass,'db_pass_update'=>1],$isToken);
            if(isset($r['error'])){$this->addMsg($r['error'],'danger');return;}
            $status=$r['data']['passwd'][0]['status']??null;
            if($status===1||$status==='1'){$this->addMsg("Password for \"$target\" changed.",'success');$this->log('cpanel_change_pass',$target);}
            else{$msg=$r['data']['passwd'][0]['statusmsg']??'Unknown error.';$this->addMsg("Failed: $msg",'danger');}
        } else {
            $r=$this->cpanelPost($base,$c['user'],$c['pass'],'/execute/Password/passwd',
                ['newpass'=>$pass,'oldpass'=>$c['pass']],$isToken);
            if(($r['result']['status']??0)===1){$this->addMsg('Password changed.','success');}
            else{$msg=$r['result']['errors'][0]??'Failed.';$this->addMsg($msg,'danger');}
        }
    }

    public function cpanelSuspendToggle(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $c=$this->cpanelCreds();
        if(!$c['user']){$this->addMsg('No cPanel credentials saved.','danger');return;}
        $base=$this->cpanelBaseUrl($c['port']);$isToken=$c['type']==='token';
        $target =trim($_POST['cp_target_user']??'');
        $action =($_POST['cp_suspend_action']??'suspend')==='unsuspend'?'unsuspend':'suspend';
        $reason =trim($_POST['cp_reason']??'Suspended by admin');
        if(!$target){$this->addMsg('Username required.','danger');return;}
        $endpoint=$action==='unsuspend'?'/json-api/unsuspendacct?api.version=1':'/json-api/suspendacct?api.version=1';
        $params=$action==='unsuspend'?['user'=>$target]:['user'=>$target,'reason'=>$reason];
        $r=$this->cpanelPost($base,$c['user'],$c['pass'],$endpoint,$params,$isToken);
        if(isset($r['error'])){$this->addMsg($r['error'],'danger');return;}
        $status=$r['data']['result'][0]['status']??null;
        $verb  =$action==='unsuspend'?'Unsuspended':'Suspended';
        if($status===1||$status==='1'){$this->addMsg("$verb account \"$target\".",'success');$this->log('cpanel_'.$action,$target);}
        else{$msg=$r['data']['result'][0]['statusmsg']??'Unknown error.';$this->addMsg("Failed: $msg",'danger');}
    }

    public function cpanelTerminate(){
        if(empty($_SESSION['fm_admin'])){$this->addMsg('Admins only.','danger');return;}
        $c=$this->cpanelCreds();
        if(!$c['user']){$this->addMsg('No cPanel credentials saved.','danger');return;}
        $base=$this->cpanelBaseUrl($c['port']);$isToken=$c['type']==='token';
        $target=trim($_POST['cp_target_user']??'');
        if(!$target){$this->addMsg('Username required.','danger');return;}
        $r=$this->cpanelPost($base,$c['user'],$c['pass'],'/json-api/removeacct?api.version=1',
            ['user'=>$target,'keepdns'=>0],$isToken);
        if(isset($r['error'])){$this->addMsg($r['error'],'danger');return;}
        $status=$r['data']['result'][0]['status']??null;
        if($status===1||$status==='1'){$this->addMsg("Account \"$target\" terminated permanently.",'success');$this->log('cpanel_terminate',$target);}
        else{$msg=$r['data']['result'][0]['statusmsg']??'Unknown error.';$this->addMsg("Failed: $msg",'danger');}
    }

    /* ══════════════════════════════════════════════════════════════
       SQL DATABASE MANAGER
    ══════════════════════════════════════════════════════════════ */
    public function sqlScan(){
        $found=[];$seen=[];
        $envDb=fm_guardian_env_db();
        $candidates=[
            '/var/www','/srv/www','/srv','/home','/opt','/data',
            $this->root,$this->currentDir,getcwd(),
            dirname($_SERVER['SCRIPT_FILENAME']??''),
            $_SERVER['DOCUMENT_ROOT']??null,
            dirname($_SERVER['DOCUMENT_ROOT']??''),
        ];
        $obd=ini_get('open_basedir');
        if($obd){foreach(explode(PATH_SEPARATOR,$obd)as $p)$candidates[]=rtrim($p,'/');}
        $home=dirname(dirname($_SERVER['SCRIPT_FILENAME']??$this->root?:''));
        foreach([$home,dirname($home)]as $h){
            if($h&&is_dir($h)){
                foreach(['public_html','www','htdocs','domains','httpdocs']as $sub)$candidates[]=$h.'/'.$sub;
                $candidates[]=$h;
            }
        }
        $roots=array_unique(array_filter($candidates,fn($r)=>$r&&is_dir($r)&&@is_readable($r)));
        $cfgNames=['wp-config.php','configuration.php','.env','.env.local','.env.production','.env.development','.env.example',
            'config.php','config/database.php','application/config/database.php','config/config.php',
            'sites/default/settings.php','sites/default/settings.local.php','include/config.php','includes/config.php','inc/config.php',
            'includes/configure.php','includes/configure.php.bak',
            'app/etc/env.php','app/etc/local.xml',
            'app/config/parameters.php','app/config/parameters.yml','config/parameters.php',
            'config/settings.inc.php','settings.inc.php',
            'LocalSettings.php',
            'typo3conf/LocalConfiguration.php',
            'config.core.php','config.inc.php',
            'app/config/app.php','config/app.php',
            'protected/config/main.php',
            '.my.cnf','my.cnf','docker-compose.yml','docker-compose.yaml',
        ];
        $maxDirs=2000;$scanned=0;
        $GLOBALS['_sqlfound']=[];
        $scan=function($dir,$depth)use(&$scan,&$seen,&$scanned,$maxDirs,$cfgNames){
            if($depth>7||$scanned>=$maxDirs)return;
            $dir=rtrim($dir,'/');$real=realpath($dir);
            if(!$real||isset($seen[$real]))return;$seen[$real]=1;$scanned++;
            foreach($cfgNames as $cf){
                $fp=$dir.'/'.$cf;
                if(!file_exists($fp)||!is_readable($fp))continue;
                $fp=realpath($fp);if(!$fp||isset($seen['f:'.$fp]))continue;
                $seen['f:'.$fp]=1;
                $creds=$this->sqlExtractCreds($fp);
                if($creds)$GLOBALS['_sqlfound'][]=['file'=>$fp,'host'=>$creds['host'],'port'=>$creds['port'],'user'=>$creds['user'],'pass'=>$creds['pass'],'db'=>$creds['db'],'type'=>$creds['type'],'driver'=>$creds['driver']??'','host_explicit'=>$creds['host_explicit']??false,'port_explicit'=>$creds['port_explicit']??false,'socket'=>$creds['socket']??''];
            }
            $skip=['node_modules','.git','vendor','.cache','.local','proc','sys','dev','run','tmp','var','usr','boot'];
            $entries=@scandir($dir)?:[];
            foreach($entries as $e){
                if($e==='.'||$e==='..'||in_array($e,$skip))continue;
                $sub=$dir.'/'.$e;
                if(!is_link($sub)&&is_dir($sub)){$scan($sub,$depth+1);if($scanned>=$maxDirs)break;}
            }
        };
        foreach($roots as $r)$scan($r,0);
        $found=$GLOBALS['_sqlfound'];unset($GLOBALS['_sqlfound']);
        if($envDb){
            array_unshift($found,['file'=>'DATABASE_URL (project environment)','host'=>$envDb['host'],'port'=>$envDb['port'],
                'user'=>$envDb['user'],'pass'=>$envDb['pass'],'db'=>$envDb['name'],
                'type'=>$envDb['driver']==='pgsql'?'postgresql':'mysql','driver'=>$envDb['driver'],
                'host_explicit'=>$envDb['host_explicit']??false,'port_explicit'=>$envDb['port_explicit']??false,'socket'=>$envDb['socket']??'']);
        }
        $obdList=$obd?array_filter(explode(PATH_SEPARATOR,$obd)):[];
        return['databases'=>$found,'open_basedir'=>array_values($obdList),'scanned'=>$scanned];
    }
    public function sqlExtractCreds($fp){
        $src=@file_get_contents($fp);if($src===false)return null;
        $base=basename($fp);
        $c=['host'=>'localhost','port'=>3306,'user'=>'','pass'=>'','db'=>'','type'=>'generic','driver'=>'',
            'host_explicit'=>false,'port_explicit'=>false,'socket'=>''];
        $setPort=function($value)use(&$c){
            $value=trim((string)$value);
            if($value!==''&&ctype_digit($value)&&(int)$value>0&&(int)$value<=65535){$c['port']=(int)$value;$c['port_explicit']=true;}
        };
        $setHost=function($value)use(&$c,$setPort){
            $value=trim((string)$value);if($value==='')return;
            if(preg_match('/^\[([^\]]+)\](?::(.*))?$/',$value,$m)){
                $c['host']=$m[1];$c['host_explicit']=true;
                if(isset($m[2])&&$m[2]!==''){if(ctype_digit($m[2]))$setPort($m[2]);elseif($m[2][0]==='/')$c['socket']=$m[2];}
                return;
            }
            if(substr_count($value,':')===1){
                [$h,$tail]=explode(':',$value,2);
                if($h!==''){$c['host']=$h;$c['host_explicit']=true;}
                if($tail!==''){if(ctype_digit($tail))$setPort($tail);elseif($tail[0]==='/')$c['socket']=$tail;}
                return;
            }
            $c['host']=$value;$c['host_explicit']=true;
        };
        $setDriver=function($value)use(&$c){
            $value=strtolower(trim((string)$value));
            if(in_array($value,['mysql','mysqli','mariadb'],true))$c['driver']='mysql';
            elseif(in_array($value,['pgsql','postgres','postgresql'],true))$c['driver']='pgsql';
            elseif($value==='sqlite'||$value==='sqlite3')$c['driver']='sqlite';
        };
        if($base==='wp-config.php'){
            $c['type']='wordpress';$c['driver']='mysql';
            $g=fn($n)=>preg_match('/define\s*\(\s*[\'"]'.$n.'[\'"]\s*,\s*[\'"](.*?)[\'"]\s*\)/s',$src,$m)?$m[1]:null;
            if($v=$g('DB_NAME'))$c['db']=$v;
            if($v=$g('DB_USER'))$c['user']=$v;
            if($v=$g('DB_PASSWORD'))$c['pass']=$v;
            if($v=$g('DB_HOST'))$setHost($v);
        } elseif($base==='configuration.php'){
            $c['type']='joomla';
            $g=fn($n)=>preg_match('/public\s+\$'.$n.'\s*=\s*[\'\"](.*?)[\'\"]\s*;/s',$src,$m)?$m[1]:null;
            if($v=$g('dbtype'))$setDriver($v);
            if($v=$g('host'))$setHost($v);
            if($v=$g('user'))$c['user']=$v;
            if($v=$g('password'))$c['pass']=$v;
            if($v=$g('db'))$c['db']=$v;
            if($v=$g('dbport'))$setPort($v);
        } elseif(strpos($base,'.env')===0){
            $c['type']='env';
            $g=function($n)use($src){
                if(preg_match('/^\s*'.$n.'\s*=\s*"([^"]*)"\s*$/mi',$src,$m))return $m[1];
                if(preg_match('/^\s*'.$n.'\s*=\s*\'([^\']*)\'\s*$/mi',$src,$m))return $m[1];
                if(preg_match('/^\s*'.$n.'\s*=\s*([^\r\n]*)$/mi',$src,$m))return trim($m[1]);
                return null;
            };
            if($v=$g('DB_CONNECTION')?:$g('DB_DRIVER')?:$g('DATABASE_DRIVER'))$setDriver($v);
            if(preg_match('/(?:DATABASE_URL|DB_URL)\s*=\s*[\'"]?(mysql|mysqli|mariadb|pgsql|postgres|postgresql|sqlite):\/\//i',$src,$m))$setDriver($m[1]);
            if(!$c['driver']&&preg_match('/^\s*(?:MYSQL|MARIADB)_[A-Z0-9_]+\s*=/mi',$src))$c['driver']='mysql';
            if($v=$g('DB_DATABASE')?:$g('DATABASE_NAME')?:$g('MYSQL_DATABASE'))$c['db']=$v;
            if($v=$g('DB_USERNAME')?:$g('DATABASE_USER')?:$g('MYSQL_USER'))$c['user']=$v;
            if($v=$g('DB_PASSWORD')?:$g('DATABASE_PASSWORD')?:$g('MYSQL_PASSWORD'))$c['pass']=$v;
            if($v=$g('DB_HOST')?:$g('DATABASE_HOST')?:$g('MYSQL_HOST'))$setHost($v);
            if($v=$g('DB_PORT')?:$g('DATABASE_PORT')?:$g('MYSQL_PORT'))$setPort($v);
            if(!$c['db']&&preg_match('#DATABASE_URL\s*=\s*"?\'?mysql://([^:@/"\']+):?([^@/"\']*)@([^:/"\']+):?(\d*)/([^"\'\s]+)#i',$src,$m)){
                $c['user']=$m[1];$c['pass']=$m[2];$setHost($m[3]);if($m[4])$setPort($m[4]);$c['db']=$m[5];
            }
        } elseif($base==='settings.php'||$base==='settings.local.php'){
            $c['type']='drupal';
            $g=fn($n)=>preg_match('/[\'"]'.$n.'[\'"]\s*=>\s*[\'"]([^\'"]*)[\'"]/i',$src,$m)?$m[1]:null;
            if($v=$g('driver'))$setDriver($v);
            if($v=$g('database'))$c['db']=$v;
            if($v=$g('username'))$c['user']=$v;
            if($v=$g('password'))$c['pass']=$v;
            if($v=$g('host'))$setHost($v);
            if($v=$g('port'))$setPort($v);
        } elseif($base==='env.php'){
            $c['type']='magento2';$c['driver']='mysql';
            $g=fn($n)=>preg_match('/[\'"]'.$n.'[\'"]\s*=>\s*[\'"]([^\'"]*)[\'"]/i',$src,$m)?$m[1]:null;
            if($v=$g('dbname'))$c['db']=$v;
            if($v=$g('username'))$c['user']=$v;
            if($v=$g('password'))$c['pass']=$v;
            if($v=$g('host'))$setHost($v);
        } elseif($base==='local.xml'){
            $c['type']='magento1';$c['driver']='mysql';
            $g=fn($n)=>preg_match('#<'.$n.'><!\[CDATA\[(.*?)\]\]></'.$n.'>#is',$src,$m)?$m[1]:(preg_match('#<'.$n.'>(.*?)</'.$n.'>#is',$src,$m)?$m[1]:null);
            if($v=$g('dbname'))$c['db']=$v;
            if($v=$g('username'))$c['user']=$v;
            if($v=$g('password'))$c['pass']=$v;
            if($v=$g('host'))$setHost($v);
        } elseif($base==='parameters.php'||$base==='parameters.yml'||$base==='settings.inc.php'){
            $c['type']='prestashop';$c['driver']='mysql';
            $g=fn($n)=>preg_match('/'.$n.'[\'"]?\s*[:=>]+\s*[\'"]?([^\'"\r\n,]*)[\'"]?/i',$src,$m)?trim($m[1]):null;
            if($v=$g('database_name')?:$g('db_name')?:$g('_DB_NAME_'))$c['db']=$v;
            if($v=$g('database_user')?:$g('db_user')?:$g('_DB_USER_'))$c['user']=$v;
            if($v=$g('database_password')?:$g('db_password')?:$g('_DB_PASSWD_'))$c['pass']=$v;
            if($v=$g('database_host')?:$g('db_server')?:$g('_DB_SERVER_'))$setHost($v);
        } elseif($base==='LocalSettings.php'){
            $c['type']='mediawiki';
            $g=fn($n)=>preg_match('/\$wg'.$n.'\s*=\s*[\'"]([^\'"]*)[\'"]/i',$src,$m)?$m[1]:null;
            if($v=$g('DBtype'))$setDriver($v);
            if($v=$g('DBname'))$c['db']=$v;
            if($v=$g('DBuser'))$c['user']=$v;
            if($v=$g('DBpassword'))$c['pass']=$v;
            if($v=$g('DBserver'))$setHost($v);
        } elseif($base==='.my.cnf'||$base==='my.cnf'){
            $c['type']='my.cnf';$c['driver']='mysql';
            $g=fn($n)=>preg_match('/^\s*'.$n.'\s*=\s*(.*)$/mi',$src,$m)?trim($m[1],"\"' \t"):null;
            if($v=$g('user'))$c['user']=$v;
            if($v=$g('password'))$c['pass']=$v;
            if($v=$g('host'))$setHost($v);
            if($v=$g('port'))$setPort($v);
            if($v=$g('socket'))$c['socket']=trim($v);
        } elseif($base==='docker-compose.yml'||$base==='docker-compose.yaml'){
            $c['type']='docker';
            $g=fn($n)=>preg_match('/'.$n.'\s*:?=?\s*[\'"]?([^\'"\r\n]*)[\'"]?/i',$src,$m)?trim($m[1]):null;
            if($v=$g('MYSQL_DATABASE')?:$g('MARIADB_DATABASE'))$c['db']=$v;
            if($v=$g('MYSQL_USER')?:$g('MARIADB_USER'))$c['user']=$v;
            if($v=$g('MYSQL_PASSWORD')?:$g('MARIADB_PASSWORD'))$c['pass']=$v;
            if(!$c['user']&&($v=$g('MYSQL_ROOT_PASSWORD')?:$g('MARIADB_ROOT_PASSWORD'))){$c['user']='root';$c['pass']=$v;}
            if(!$c['driver']&&preg_match('/(?:MYSQL|MARIADB)_(?:DATABASE|USER|PASSWORD|ROOT_PASSWORD)\s*:/i',$src))$c['driver']='mysql';
            if($v=$g('MYSQL_HOST')?:$g('MARIADB_HOST')?:$g('DB_HOST')){$c['driver']='mysql';$setHost($v);}
        } else {
            if(preg_match("/define\s*\(\s*['\"]DB_NAME['\"]\s*,\s*['\"]([^'\"]+)['\"]\s*\)/i",$src,$m))$c['db']=$m[1];
            elseif(preg_match("/['\"]database['\"]\s*=>\s*['\"]([^'\"]+)['\"]/i",$src,$m))$c['db']=$m[1];
            elseif(preg_match('/\$(?:db(?:name|Name|_name)?|database)\s*=\s*[\'"]([^\'"]+)[\'"]/i',$src,$m))$c['db']=$m[1];
            if(preg_match("/define\s*\(\s*['\"]DB_USER['\"]\s*,\s*['\"]([^'\"]+)['\"]\s*\)/i",$src,$m))$c['user']=$m[1];
            elseif(preg_match("/['\"]username['\"]\s*=>\s*['\"]([^'\"]+)['\"]/i",$src,$m))$c['user']=$m[1];
            elseif(preg_match('/\$(?:db_?user|user(?:name)?)\s*=\s*[\'"]([^\'"]+)[\'"]/i',$src,$m))$c['user']=$m[1];
            if(preg_match("/define\s*\(\s*['\"]DB_PASSWORD['\"]\s*,\s*['\"]([^'\"]+)['\"]\s*\)/i",$src,$m))$c['pass']=$m[1];
            elseif(preg_match("/['\"]password['\"]\s*=>\s*['\"]([^'\"]+)['\"]/i",$src,$m))$c['pass']=$m[1];
            elseif(preg_match('/\$(?:db_?pass(?:word)?|password)\s*=\s*[\'"]([^\'"]+)[\'"]/i',$src,$m))$c['pass']=$m[1];
            if(preg_match("/define\s*\(\s*['\"]DB_HOST['\"]\s*,\s*['\"]([^'\"]+)['\"]\s*\)/i",$src,$m))$setHost($m[1]);
            elseif(preg_match("/['\"]host['\"]\s*=>\s*['\"]([^'\"]+)['\"]/i",$src,$m))$setHost($m[1]);
            elseif(preg_match('/\$(?:db_?host|host(?:name)?)\s*=\s*[\'"]([^\'"]+)[\'"]/i',$src,$m))$setHost($m[1]);
            if(preg_match('/(?:DB_CONNECTION|DB_DRIVER|DATABASE_DRIVER)\s*[=:>]+\s*[\'"]?(mysql|mysqli|mariadb|pgsql|postgres|postgresql|sqlite)\b/i',$src,$m))$setDriver($m[1]);
            elseif(preg_match('/(?:DATABASE_URL|DB_URL)\s*[=:>]+\s*[\'"]?(mysql|mysqli|mariadb|pgsql|postgres|postgresql|sqlite):/i',$src,$m))$setDriver($m[1]);
        }
        if(!$c['host'])$c['host']='localhost';
        if(!$c['db']&&!$c['user'])return null;
        return $c;
    }
    private function sqlBuildConn(){
        return[
            isset($_POST['sql_host'])?trim($_POST['sql_host']):'localhost',
            isset($_POST['sql_port'])?(int)$_POST['sql_port']:3306,
            isset($_POST['sql_user'])?$_POST['sql_user']:'',
            isset($_POST['sql_pass'])?$_POST['sql_pass']:'',
            isset($_POST['sql_db'])?trim($_POST['sql_db']):'',
            isset($_POST['sql_driver'])&&$_POST['sql_driver']==='pgsql'?'pgsql':'mysql',
        ];
    }
    private function sqlConn($h,$pt,$u,$pw,$db,$driver='mysql'){
        if($driver==='pgsql'){
            if(!class_exists('PDO')||!in_array('pgsql',PDO::getAvailableDrivers(),true))return[null,'PDO PostgreSQL support is not available on this server.'];
            try{
                $dsn='pgsql:host='.$h.';port='.(int)($pt?:5432).';dbname='.$db;
                $link=new PDO($dsn,$u,$pw,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
                return[$link,null];
            }catch(Throwable $e){return[null,'Connection failed: '.$e->getMessage()];}
        }
        if(!function_exists('mysqli_connect'))return[null,'MySQLi extension is not available on this server.'];
        $sock=null;if($h&&strlen($h)>0&&$h[0]==='/')$sock=$h;
        if($sock)$link=@mysqli_connect('localhost',$u,$pw,$db,3306,$sock);
        else $link=@mysqli_connect($h,$u,$pw,$db,(int)($pt?:3306));
        if(!$link)return[null,'Connection failed: '.mysqli_connect_error()];
        mysqli_set_charset($link,'utf8mb4');
        return[$link,null];
    }
    public function sqlListTables(){
        [$h,$pt,$u,$pw,$db,$driver]=$this->sqlBuildConn();
        [$link,$err]=$this->sqlConn($h,$pt,$u,$pw,$db,$driver);
        if($err)return['error'=>$err];
        $tables=[];
        if($link instanceof PDO){
            try{
                $res=$link->query("SELECT table_name,0::bigint AS table_rows,pg_total_relation_size(format('%I.%I','public',table_name)::regclass) AS table_size,'table' AS engine FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' ORDER BY table_name");
                foreach($res as $row)$tables[]=['name'=>$row['table_name'],'rows'=>(int)$row['table_rows'],'size'=>(int)$row['table_size'],'engine'=>$row['engine']];
                $dbs=[];$dr=$link->query("SELECT datname FROM pg_database WHERE datallowconn=true ORDER BY datname");
                foreach($dr as $row)$dbs[]=$row['datname'];
            }catch(Throwable $e){return['error'=>'PostgreSQL query failed: '.$e->getMessage()];}
        }else{
            $res=mysqli_query($link,'SHOW TABLE STATUS');
            if($res){while($row=mysqli_fetch_assoc($res))$tables[]=['name'=>$row['Name'],'rows'=>(int)($row['Rows']??0),'size'=>(int)($row['Data_length']??0)+(int)($row['Index_length']??0),'engine'=>$row['Engine']??''];}
            $dbsRes=mysqli_query($link,'SHOW DATABASES');$dbs=[];
            if($dbsRes){while($r=mysqli_fetch_row($dbsRes))$dbs[]=$r[0];}
            mysqli_close($link);
        }
        return['tables'=>$tables,'db'=>$db,'databases'=>$dbs];
    }
    public function sqlBrowse(){
        [$h,$pt,$u,$pw,$db,$driver]=$this->sqlBuildConn();
        $table=isset($_POST['sql_table'])?trim($_POST['sql_table']):'';
        $page=max(1,(int)(isset($_POST['sql_page'])?$_POST['sql_page']:1));
        $per=50;
        [$link,$err]=$this->sqlConn($h,$pt,$u,$pw,$db,$driver);
        if($err)return['error'=>$err];
        if($link instanceof PDO){
            $tE='"'.str_replace('"','""',$table).'"';
            try{
                $total=(int)$link->query("SELECT COUNT(*) FROM $tE")->fetchColumn();
                $cols=[];$colRes=$link->query("SELECT column_name AS \"Field\",data_type AS \"Type\" FROM information_schema.columns WHERE table_schema='public' AND table_name=".$link->quote($table)." ORDER BY ordinal_position");
                foreach($colRes as $r)$cols[]=['name'=>$r['Field'],'type'=>$r['Type']];
                $rows=[];$offset=($page-1)*$per;$dr=$link->query("SELECT * FROM $tE LIMIT $per OFFSET $offset");
                foreach($dr as $r)$rows[]=array_values($r);
                return['columns'=>$cols,'rows'=>$rows,'total'=>$total,'page'=>$page,'perPage'=>$per,'table'=>$table,'db'=>$db,'pages'=>(int)ceil(max($total,1)/$per)];
            }catch(Throwable $e){return['error'=>'PostgreSQL query failed: '.$e->getMessage()];}
        }
        $tE=mysqli_real_escape_string($link,$table);
        $total=0;$cr=mysqli_query($link,"SELECT COUNT(*) AS c FROM `$tE`");
        if($cr){$rw=mysqli_fetch_assoc($cr);$total=(int)$rw['c'];}
        $cols=[];$colRes=mysqli_query($link,"SHOW COLUMNS FROM `$tE`");
        if($colRes)while($r=mysqli_fetch_assoc($colRes))$cols[]=['name'=>$r['Field'],'type'=>$r['Type']];
        $rows=[];$offset=($page-1)*$per;
        $dr=mysqli_query($link,"SELECT * FROM `$tE` LIMIT $per OFFSET $offset");
        if($dr)while($r=mysqli_fetch_row($dr))$rows[]=$r;
        mysqli_close($link);
        return['columns'=>$cols,'rows'=>$rows,'total'=>$total,'page'=>$page,'perPage'=>$per,'table'=>$table,'db'=>$db,'pages'=>(int)ceil(max($total,1)/$per)];
    }
    public function sqlRunQuery(){
        [$h,$pt,$u,$pw,$db,$driver]=$this->sqlBuildConn();
        $sql=isset($_POST['sql_query'])?trim($_POST['sql_query']):'';
        if(!$sql)return['error'=>'Empty query.'];
        [$link,$err]=$this->sqlConn($h,$pt,$u,$pw,$db,$driver);
        if($err)return['error'=>$err];
        if($link instanceof PDO){
            try{
                $res=$link->query($sql);$out=['affected'=>$res instanceof PDOStatement?0:$res,'columns'=>[],'rows'=>[],'insert_id'=>null,'error'=>null,'limited'=>false];
                if($res instanceof PDOStatement){
                    $out['columns']=array_map(fn($m)=>$m->getColumnMeta(0)['name']??'',array_filter(range(0,max(0,$res->columnCount()-1)),fn($i)=>true));
                    $cnt=0;while($row=$res->fetch(PDO::FETCH_NUM)){ $out['rows'][]=$row;if(++$cnt>=500)break; }
                    $out['limited']=$cnt>=500;
                }else $out['affected']=$link->exec($sql);
                return $out;
            }catch(Throwable $e){return['affected'=>0,'columns'=>[],'rows'=>[],'insert_id'=>null,'error'=>$e->getMessage(),'limited'=>false];}
        }
        $res=mysqli_query($link,$sql);
        $out=['affected'=>mysqli_affected_rows($link),'columns'=>[],'rows'=>[],'insert_id'=>mysqli_insert_id($link),'error'=>null,'limited'=>false];
        if($res===false){$out['error']=mysqli_error($link);}
        elseif(is_object($res)){
            $fi=mysqli_fetch_fields($res);if($fi)foreach($fi as $f)$out['columns'][]=$f->name;
            $cnt=0;while($row=mysqli_fetch_row($res)){$out['rows'][]=$row;if(++$cnt>=500)break;}
            $out['limited']=($cnt>=500);mysqli_free_result($res);
        }
        mysqli_close($link);return $out;
    }
    public function sqlExport(){
        [$h,$pt,$u,$pw,$db,$driver]=$this->sqlBuildConn();
        $table=isset($_POST['sql_table'])?trim($_POST['sql_table']):'';
        $fmt=isset($_POST['sql_fmt'])?$_POST['sql_fmt']:'sql';
        if(!$table){header('Content-Type: application/json');echo json_encode(['error'=>'No table specified.']);exit;}
        [$link,$err]=$this->sqlConn($h,$pt,$u,$pw,$db,$driver);
        if($err){header('Content-Type: application/json');echo json_encode(['error'=>$err]);exit;}
        $safeName=preg_replace('/[^a-zA-Z0-9_\-]/','',$table);
        if($link instanceof PDO){
            $tE='"'.str_replace('"','""',$table).'"';
            try{
                $res=$link->query("SELECT * FROM $tE");
                if($fmt==='csv'){
                    header('Content-Type: text/csv;charset=utf-8');header('Content-Disposition: attachment; filename="'.$safeName.'.csv"');
                    $first=true;
                    while($row=$res->fetch(PDO::FETCH_ASSOC)){
                        if($first){echo implode(',',array_map(fn($v)=>'"'.str_replace('"','""',(string)$v).'"',array_keys($row)))."\r\n";$first=false;}
                        echo implode(',',array_map(fn($v)=>$v===null?'':'"'.str_replace('"','""',(string)$v).'"',array_values($row)))."\r\n";
                    }
                }else{
                    header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.$safeName.'.sql"');
                    echo "-- SQL Export: `$table` from `$db`\n-- Generated: ".date('Y-m-d H:i:s')."\n\n";
                    while($row=$res->fetch(PDO::FETCH_NUM)){
                        $vals=implode(',',array_map(fn($v)=>$v===null?'NULL':$link->quote((string)$v),$row));
                        echo "INSERT INTO ".$tE." VALUES ($vals);\n";
                    }
                }
            }catch(Throwable $e){header('Content-Type: application/json');echo json_encode(['error'=>$e->getMessage()]);}
            exit;
        }
        $tE=mysqli_real_escape_string($link,$table);
        if($fmt==='csv'){
            header('Content-Type: text/csv;charset=utf-8');
            header('Content-Disposition: attachment; filename="'.$safeName.'.csv"');
            $res=mysqli_query($link,"SELECT * FROM `$tE`");
            if($res){
                $first=true;
                while($row=mysqli_fetch_assoc($res)){
                    if($first){echo implode(',',array_map(fn($hdr)=>'"'.str_replace('"','""',$hdr).'"',array_keys($row)))."\r\n";$first=false;}
                    echo implode(',',array_map(fn($v)=>$v===null?'':'"'.str_replace('"','""',(string)$v).'"',array_values($row)))."\r\n";
                }
            }
        } else {
            header('Content-Type: application/octet-stream');
            header('Content-Disposition: attachment; filename="'.$safeName.'.sql"');
            echo "-- SQL Export: `$table` from `$db`\n-- Generated: ".date('Y-m-d H:i:s')."\n\nSET NAMES utf8mb4;\n\n";
            $cr=mysqli_query($link,"SHOW CREATE TABLE `$tE`");
            if($cr){$rw=mysqli_fetch_row($cr);echo "DROP TABLE IF EXISTS `$tE`;\n".$rw[1].";\n\n";}
            $res=mysqli_query($link,"SELECT * FROM `$tE`");
            $buf='';
            if($res){
                while($row=mysqli_fetch_row($res)){
                    $vals=implode(',',array_map(fn($v)=>$v===null?'NULL':"'".mysqli_real_escape_string($link,(string)$v)."'",$row));
                    $buf.="INSERT INTO `$tE` VALUES ($vals);\n";
                    if(strlen($buf)>65536){echo $buf;$buf='';}
                }
                if($buf)echo $buf;
            }
        }
        mysqli_close($link);exit;
    }
    /* ══ Plugins Installer ═══════════════════════════════════════════════════
       One window that installs extensions on either CMS the way that CMS's
       own "Add New" screen does it.

       WordPress is served by the public repository API (api.wordpress.org),
       the same one wp-admin itself calls, so Featured / Popular / Newest /
       Recently Updated / search / one-click install all really work.

       Joomla has no public directory API: update.joomla.org publishes only
       core update feeds, and extensions.joomla.org answers HTML. So for
       Joomla this window does what can be done honestly - it reads the
       installed extensions from the site's own database, installs a package
       you upload, enables and disables, and opens the Joomla Extensions
       Directory in a browser tab for browsing. It never pretends to list the
       directory.

       Installing writes files and updates the CMS's own tables. It does not
       bootstrap the CMS inside this manager's process: one fatal error in a
       plugin would take the file manager down with it. */

    private function pieJson($d){
        if($d===false)return['ok'=>false,'error'=>'The request to the repository did not complete.'];
        $j=json_decode((string)$d,true);
        if(!is_array($j))return['ok'=>false,'error'=>'The repository answered something this window cannot read.'];
        return $j;
    }

    /* Every outbound call goes through here, so a slow repository cannot hold
       the PHP worker open and every failure comes back as a readable reason. */
    private function pieHttp($url,$post=null,$timeout=30){
        if(!function_exists('curl_init'))return['ok'=>false,'error'=>'This PHP build has no cURL, so the repository cannot be reached.'];
        $ch=@curl_init($url);
        if(!$ch)return['ok'=>false,'error'=>'A cURL handle could not be created.'];
        @curl_setopt_array($ch,[
            CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,
            CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>max(5,min((int)$timeout,20)),
            CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,
            CURLOPT_USERAGENT=>'SyrahFM-PluginsInstaller/1.0',
            CURLOPT_ENCODING=>'',
        ]);
        if($post!==null){
            @curl_setopt($ch,CURLOPT_POST,true);
            @curl_setopt($ch,CURLOPT_POSTFIELDS,is_array($post)?http_build_query($post):$post);
        }
        $body=@curl_exec($ch);
        $code=(int)@curl_getinfo($ch,CURLINFO_HTTP_CODE);
        $err=(string)@curl_error($ch);
        @curl_close($ch);
        if($body===false)return['ok'=>false,'error'=>'The repository could not be reached'.($err!==''?' ('.$err.')':'').'.'];
        if($code<200||$code>=300)return['ok'=>false,'error'=>'The repository answered HTTP '.$code.'.'];
        return['ok'=>true,'body'=>(string)$body,'code'=>$code];
    }

    /* The repository API takes GET only - a POST is answered with HTTP 405 and
       the words "This API only serves GET requests.", so nothing is posted. */
    private function pieWpApi($action,array $req){
        $args=['action'=>$action];
        foreach($req as $k=>$v){
            if($v===null||$v==='')continue;
            $args['request['.$k.']']=$v;
        }
        $r=$this->pieHttp('https://api.wordpress.org/plugins/info/1.2/?'.http_build_query($args));
        if(empty($r['ok']))return $r;
        $j=$this->pieJson($r['body']);
        if(isset($j['error']))return['ok'=>false,'error'=>'The repository refused that request: '.(is_string($j['error'])?$j['error']:json_encode($j['error']))];
        return $j+['ok'=>true];
    }

    private function pieWpIcon($p){
        $icons=(array)($p['icons']??[]);
        foreach(['svg','2x','1x'] as $k)if(!empty($icons[$k])&&is_string($icons[$k]))return $icons[$k];
        return '';
    }
    private function pieWpBanner($p){
        $b=(array)($p['banners']??[]);
        foreach(['low','high'] as $k)if(!empty($b[$k])&&is_string($b[$k]))return $b[$k];
        return '';
    }

    /* the repository's own fields, trimmed to what the window draws */
    private function pieWpSlim($p){
        $p=(array)$p;
        $tested=(string)($p['tested']??'');
        return[
            'slug'      =>(string)($p['slug']??''),
            'name'      =>trim((string)html_entity_decode((string)($p['name']??''),ENT_QUOTES,'UTF-8')),
            'version'   =>(string)($p['version']??''),
            'tested'    =>$tested,
            'requires'  =>(string)($p['requires']??''),
            'requires_php'=>(string)($p['requires_php']??''),
            'rating'    =>(int)($p['rating']??0),
            'ratings'   =>(array)($p['ratings']??[]),
            'num_ratings'=>(int)($p['num_ratings']??0),
            'active'    =>(int)($p['active_installs']??0),
            'downloaded'=>(int)($p['downloaded']??0),
            'last_updated'=>(string)($p['last_updated']??''),
            'author'    =>trim(strip_tags((string)($p['author']??''))),
            'short'     =>trim((string)html_entity_decode(strip_tags((string)($p['short_description']??'')),ENT_QUOTES,'UTF-8')),
            'download'  =>(string)($p['download_link']??''),
            'homepage'  =>(string)($p['homepage']??''),
            'icon'      =>$this->pieWpIcon($p),
            'banner'    =>$this->pieWpBanner($p),
            'compat'    =>$tested!==''?version_compare((string)$this->pieWpCoreVersion(),$tested,'<='):true,
        ];
    }

    private function pieWpCoreVersion(){
        $root=$this->pieWpRoot();
        /* with no site chosen yet this still answers from the first WordPress
           on the server, so the window can say what a plugin was tested
           against before the reader has picked anything */
        if($root===''){
            foreach((array)($this->cmsScan()['sites']??[]) as $s){
                if((string)($s['type']??'')!=='wordpress')continue;
                $root=$this->wpSiteRoot((string)($s['config']??''));
                if($root!=='')break;
            }
        }
        if($root==='')return '';
        $f=$root.'/wp-includes/version.php';
        if(!is_file($f))return '';
        $s=(string)@file_get_contents($f,false,null,0,8192);
        if($s!==''&&preg_match("/\\\$wp_version\\s*=\\s*'([^']+)'/",$s,$m))return $m[1];
        return '';
    }

    /* ── browsing the repository ─────────────────────────────────────────── */
    public function pieRepoBrowse($browse='featured',$search='',$page=1,$perPage=24){
        $browse=(string)$browse;
        $known=['featured','popular','new','updated','top-rated','recommended'];
        if(!in_array($browse,$known,true))$browse='featured';
        $page=max(1,min(999,(int)$page));
        $perPage=max(6,min(60,(int)$perPage));
        $req=['per_page'=>$perPage,'page'=>$page];
        $search=trim((string)$search);
        if($search!=='')$req['search']=$search;
        else $req['browse']=$browse;
        /* "top-rated" is the repository's own browse value; "recommended" is
           the same list under the name wp-admin gives it, so both are kept. */
        $j=$this->pieWpApi('query_plugins',$req);
        if(isset($j['error']))return['ok'=>false,'error'=>$j['error']];
        if(!isset($j['plugins'])&&!isset($j['info']))return['ok'=>false,'error'=>'The repository answered with no plugin list.'];
        $out=[];
        foreach((array)($j['plugins']??[]) as $p)$out[]=$this->pieWpSlim($p);
        $info=(array)($j['info']??[]);
        return['ok'=>true,'browse'=>$browse,'search'=>$search,'page'=>$page,
               'per_page'=>$perPage,'pages'=>(int)($info['pages']??1),
               'results'=>(int)($info['results']??count($out)),'plugins'=>$out];
    }

    public function pieRepoInfo($slug){
        $slug=trim((string)$slug);
        if($slug==='')return['ok'=>false,'error'=>'No plugin was named.'];
        $j=$this->pieWpApi('plugin_information',['slug'=>$slug]);
        if(isset($j['error']))return['ok'=>false,'error'=>$j['error']];
        if(empty($j['slug'])&&empty($j['name']))return['ok'=>false,'error'=>'The repository has no plugin under that name.'];
        $d=$this->pieWpSlim($j);
        $sec=[];
        foreach(['description','installation','faq','screenshots','changelog','reviews','other_notes'] as $k){
            $v=trim((string)($j['sections'][$k]??''));
            if($v!=='')$sec[$k]=$v;
        }
        $d['sections']=$sec;
        $tags=[];
        foreach((array)($j['tags']??[]) as $k=>$v)$tags[]=['slug'=>(string)$k,'name'=>(string)$v];
        $d['tags']=array_slice($tags,0,14);
        $compat=[];
        foreach((array)($j['compatibility']??[]) as $core=>$rows){
            foreach((array)$rows as $ver=>$row){
                if(!is_array($row))continue;
                $compat[]=['core'=>(string)$core,'plugin'=>(string)$ver,'works'=>(string)($row[2]??''),'votes'=>(int)($row[3]??0)];
            }
        }
        $d['compatibility_table']=array_slice($compat,0,12);
        $d['donate']=(string)($j['donate_link']??'');
        $d['added']=(string)($j['added']??'');
        return['ok'=>true,'plugin'=>$d];
    }

    /* ── the site under the window ───────────────────────────────────────── */
    /* The site list is not this window's own job any more: both windows that
       act on a site use the shared scanner, so a site either tool finds is a
       site the other finds too. */
    public function pieSites($post=[]){
        $scan=$this->sitesAll(!empty($post['deep'])&&$post['deep']!=='0');
        $out=[];
        foreach((array)($scan['sites']??[]) as $s){
            $dir=(string)($s['dir']??'');
            $cfg=(string)($s['config']??'');
            if($dir===''&&$cfg==='')continue;
            $out[]=['type'=>(string)($s['type']??''),'config'=>$cfg,'dir'=>$dir,
                    /* "found by" is the scanner's account of how a site was
                       located. It is passed on because a site list that cannot
                       say where it looked is impossible to diagnose when the
                       site someone expects is missing. */
                    'source'=>(string)($s['source']??''),
                    'credentials'=>!empty($s['credentials']),
                    'writable'=>!empty($s['writable'])];
        }
        usort($out,function($a,$b){return strcmp($a['dir'],$b['dir']);});
        return['ok'=>true,'sites'=>$out,'wp_core'=>$this->pieWpCoreVersion(),'php'=>PHP_VERSION,
               'scanned_roots'=>(array)($scan['scanned_roots']??[]),
               'open_basedir'=>(array)($scan['open_basedir']??[]),
               'dirs_scanned'=>(int)($scan['dirs_scanned']??0),
               'seeds'=>(int)($scan['seeds']??0),
               'scan_seconds'=>(float)($scan['scan_seconds']??0),
               'stopped'=>(string)($scan['stopped']??''),
               'deep'=>!empty($post['deep'])&&$post['deep']!=='0',
               'cached'=>!empty($scan['cached'])];
    }

    /* ── repository detail for plugins that are already installed ───────────
       The installed list is read from the files on disk, so it carries no
       icon, rating or update information. Those all live in the repository,
       which has to be asked one slug at a time - done here in parallel,
       because asking in series would hold a PHP worker for one round trip per
       plugin and this server only has a handful of them. A slow or unreachable
       repository costs the list its icons, never the list itself. */
    public function pieRepoMeta($slugs){
        $slugs=is_array($slugs)?$slugs:explode(',',(string)$slugs);
        $want=[];
        foreach($slugs as $sl){
            $sl=strtolower(preg_replace('/[^A-Za-z0-9._-]/','',trim((string)$sl)));
            if($sl!==''&&!isset($want[$sl])&&count($want)<60)$want[$sl]=true;
        }
        if(!$want)return['ok'=>true,'meta'=>[]];
        $mh=@curl_multi_init();
        if(!$mh)return['ok'=>true,'meta'=>[],'note'=>'cURL could not be used, so the repository detail was skipped.'];
        $handles=[];
        foreach(array_keys($want) as $sl){
            $url='https://api.wordpress.org/plugins/info/1.2/?action=plugin_information'
                .'&request%5Bslug%5D='.rawurlencode($sl)
                .'&request%5Bfields%5D%5Bicons%5D=1&request%5Bfields%5D%5Bbanners%5D=1'
                .'&request%5Bfields%5D%5Bsections%5D=0';
            $ch=@curl_init($url);
            if(!$ch)continue;
            @curl_setopt_array($ch,[
                CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>3,
                CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>15,
                CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,
                CURLOPT_USERAGENT=>'SyrahFM-PluginsInstaller/1.0',CURLOPT_ENCODING=>'',
            ]);
            @curl_multi_add_handle($mh,$ch);
            $handles[$sl]=$ch;
        }
        /* drive the whole set at once rather than one at a time */
        $running=0;
        do{
            @curl_multi_exec($mh,$running);
            if($running)@curl_multi_select($mh,0.2);
        }while($running>0);
        $meta=[];
        foreach($handles as $sl=>$ch){
            $body=@curl_multi_getcontent($ch);
            $code=(int)@curl_getinfo($ch,CURLINFO_HTTP_CODE);
            @curl_multi_remove_handle($mh,$ch);
            @curl_close($ch);
            if($body===false||$body===''||$code<200||$code>=300)continue;
            $j=@json_decode($body,true);
            if(!is_array($j)||empty($j['slug']))continue;
            $meta[$sl]=$this->pieWpSlim($j);
        }
        @curl_multi_close($mh);
        return['ok'=>true,'meta'=>$meta,'asked'=>count($handles),'answered'=>count($meta)];
    }

    private function pieWpRoot(){
        $cfg=$this->pieCfg();
        return $cfg!==''?$this->wpSiteRoot($cfg):'';
    }
    private $pieConfigPath='';
    private function pieCfg(){return (string)$this->pieConfigPath;}

    private function pieWpPluginsDir(){
        $cfg=$this->pieCfg();
        if($cfg==='')return[null,'No site was named.'];
        if($this->cmsConfigType($cfg)!=='wordpress')return[null,'That config file is not a WordPress site.'];
        $root=$this->wpSiteRoot($cfg);
        if($root==='')return[null,'The WordPress root could not be found from that config file.'];
        $dir=$root.'/wp-content/plugins';
        if(!is_dir($dir))return[null,'This site has no plugins folder at '.$dir.'.'];
        return[$dir,''];
    }

    /* Installed plugins, read the way the CMS itself records them: the files on
       disk, cross-checked against the active_plugins option. A dead database
       still lists the files, because the files are the truth about what is
       installed - only "active" needs the database. */
    public function pieWpInstalled(){
        list($dir,$why)=$this->pieWpPluginsDir();
        if(!$dir)return['ok'=>false,'error'=>$why];
        $root=$this->pieWpRoot();
        $list=[];
        foreach((array)@scandir($dir) as $e){
            if($e==='.'||$e==='..')continue;
            $full=$dir.'/'.$e;
            if(is_dir($full)){
                foreach((array)@glob($full.'/*') as $pf){
                    if(!is_file($pf)||strtolower(substr(basename($pf),-4))!=='.php')continue;
                    $head=@file_get_contents($pf,false,null,0,8192);
                    if($head&&stripos($head,'Plugin Name:')!==false){
                        $list[]=['file'=>$e.'/'.basename($pf),'slug'=>$e];
                        break;
                    }
                }
            }elseif(is_file($full)&&strtolower(substr($e,-4))==='.php'){
                $head=@file_get_contents($full,false,null,0,8192);
                if($head&&stripos($head,'Plugin Name:')!==false)$list[]=['file'=>$e,'slug'=>$e];
            }
        }
        $active=[];$dbError='';
        /* mysqli throws in PHP 8 rather than returning false, and @ does not
           suppress exceptions. A site whose tables are missing, half-installed
           or unreachable must therefore be caught here - otherwise one failed
           query escapes as a server error with a stack trace in the middle of
           the manager's page, and the whole window stops answering. The list
           of what is on disk is still returned, with the reason alongside. */
        try{
            list($link,$c,$err)=$this->cmsConnect($this->pieCfg());
            if($err)$dbError=$err;
            else{
                $t=$c['prefix'];
                $res=@mysqli_query($link,"SELECT option_value FROM `{$t}options` WHERE option_name='active_plugins' LIMIT 1");
                if($res&&($r=mysqli_fetch_assoc($res))){$u=@unserialize($r['option_value']);if(is_array($u))$active=$u;}
                @mysqli_close($link);
            }
        }catch(\Throwable $e){
            $dbError='the site database could not be read: '.$e->getMessage();
        }
        $out=[];
        foreach($list as $p){
            $full=$dir.'/'.$p['file'];
            $head=(string)@file_get_contents($full,false,null,0,8192);
            $hdr=$this->cmsParseHeader($head,['name'=>'Plugin Name','version'=>'Version','description'=>'Description','author'=>'Author','req'=>'Requires at least','reqphp'=>'Requires PHP']);
            $out[]=[
                'file'=>$p['file'],'slug'=>$p['slug'],
                'name'=>$hdr['name']?:$p['slug'],
                'version'=>$hdr['version']?:'',
                'description'=>trim(strip_tags((string)$hdr['description'])),
                'author'=>trim(strip_tags((string)$hdr['author'])),
                'requires'=>$hdr['req']?:'','requires_php'=>$hdr['reqphp']?:'',
                'active'=>in_array($p['file'],$active,true),
                'writable'=>@is_writable($full),
            ];
        }
        usort($out,function($a,$b){
            if($a['active']!==$b['active'])return $a['active']?-1:1;
            return strcasecmp($a['name'],$b['name']);
        });
        return['ok'=>true,'cms'=>'wordpress','plugins'=>$out,'active'=>count($active),
               'root'=>$root,'wp_core'=>$this->pieWpCoreVersion(),
               'dir_writable'=>@is_writable($dir),'db_error'=>$dbError];
    }

    /* find a plugin on disk by the folder name the repository calls it */
    private function pieWpFind($slug){
        list($dir)=$this->pieWpPluginsDir();
        if(!$dir)return null;
        $slug=$this->pieName($slug);
        if($slug==='')return null;
        if(@is_dir($dir.'/'.$slug)){
            /* the path the CMS records is the main file inside the folder, not
               the folder name, so both are carried and they are not confused */
            $main='';
            foreach((array)@glob($dir.'/'.$slug.'/*.php') as $pf){
                $head=(string)@file_get_contents($pf,false,null,0,8192);
                if($head!==''&&stripos($head,'Plugin Name:')!==false){$main=basename($pf);break;}
            }
            return['dir'=>$dir.'/'.$slug,'file'=>$slug,'slug'=>$slug,'kind'=>'dir',
                   'plugin_file'=>$main!==''?$slug.'/'.$main:''];
        }
        if(@is_file($dir.'/'.$slug.'.php'))
            return['dir'=>$dir,'file'=>$slug.'.php','slug'=>$slug,'kind'=>'file',
                   'plugin_file'=>$slug.'.php'];
        foreach((array)@scandir($dir) as $e){
            if($e==='.'||$e==='..'||!@is_dir($dir.'/'.$e))continue;
            foreach((array)@glob($dir.'/'.$e.'/*.php') as $pf){
                $head=@file_get_contents($pf,false,null,0,8192);
                if($head&&stripos($head,'Plugin Name:')===false)continue;
                if($head&&preg_match('/^[ \t\/*#@]*Text Domain:(.*)$/mi',$head,$m)){
                    if(trim($m[1])!==''&&strcasecmp(trim($m[1]),$slug)===0)
                        return['dir'=>$dir.'/'.$e,'file'=>$e.'/'.basename($pf),'slug'=>$e,'kind'=>'dir',
                               'plugin_file'=>$e.'/'.basename($pf)];
                }
                break;
            }
        }
        return null;
    }

    private function pieWpMainFile($dir,$file){
        $full=$dir.'/'.$file;
        if(!is_file($full))return[];
        $head=(string)@file_get_contents($full,false,null,0,8192);
        $hdr=$this->cmsParseHeader($head,['name'=>'Plugin Name','version'=>'Version','description'=>'Description','author'=>'Author','req'=>'Requires at least','reqphp'=>'Requires PHP']);
        return['name'=>$hdr['name']?:basename($file),'version'=>$hdr['version']?:'',
               'description'=>trim(strip_tags((string)$hdr['description'])),
               'author'=>trim(strip_tags((string)$hdr['author'])),
               'requires'=>$hdr['req']?:'','requires_php'=>$hdr['reqphp']?:''];
    }

    /* ── activation, done on the option the CMS reads ──────────────────────
       The active_plugins option is a serialized array of "folder/main.php"
       strings in the order WordPress keeps them. It is rewritten here rather
       than through activate_plugin(), because loading a plugin's own code
       inside this manager's process would let one broken plugin end the whole
       file manager. The consequence is stated to the user, not hidden: the
       plugin's activation hooks do not run. */
    private function pieWpSetActive($file,$want){
        $cfg=$this->pieCfg();
        list($link,$c,$err)=$this->cmsConnect($cfg);
        if($err)return['ok'=>false,'error'=>'The site database could not be reached: '.$err];
        $t=$c['prefix'];
        $file=(string)$file;
        $res=@mysqli_query($link,"SELECT option_value FROM `{$t}options` WHERE option_name='active_plugins' LIMIT 1");
        $row=$res?@mysqli_fetch_assoc($res):null;
        $arr=$row?@unserialize($row['option_value']):[];
        if(!is_array($arr))$arr=[];
        $arr=array_values(array_filter(array_map('strval',$arr),function($v){return $v!=='';}));
        $has=in_array($file,$arr,true);
        if($want===$has){
            @mysqli_close($link);
            return['ok'=>true,'active'=>$want,'changed'=>false,
                   'note'=>$want?'That plugin was already active.':'That plugin was already inactive.'];
        }
        if($want)$arr[]=$file;
        else $arr=array_values(array_filter($arr,function($v)use($file){return $v!==$file;}));
        sort($arr);
        $blob=mysqli_real_escape_string($link,serialize($arr));
        if($row)@mysqli_query($link,"UPDATE `{$t}options` SET option_value='{$blob}' WHERE option_name='active_plugins'");
        else @mysqli_query($link,"INSERT INTO `{$t}options` (option_name,option_value,autoload) VALUES ('active_plugins','{$blob}','yes')");
        $errno=@mysqli_errno($link);
        $error=$errno?(string)@mysqli_error($link):'';
        @mysqli_close($link);
        if($errno!==0)return['ok'=>false,'error'=>'The active_plugins option could not be written: '.$error];
        return['ok'=>true,'active'=>$want,'changed'=>true,'count'=>count($arr),
               'note'=>$want
                 ?'Active. The plugin\'s own activation routine did not run - this window writes the option the CMS reads instead of loading plugin code inside the manager. If the plugin needs a one-time setup, open wp-admin once and it will finish there.'
                 :'Inactive. Its deactivation routine did not run, for the same reason.'];
    }

    public function pieWpActivate($file,$want){
        list($dir,$why)=$this->pieWpPluginsDir();
        if(!$dir)return['ok'=>false,'error'=>$why];
        $file=trim((string)$file);
        if($file==='')return['ok'=>false,'error'=>'No plugin was named.'];
        if(strpos($file,'..')!==false||$file[0]==='/'||strpos($file,"\0")!==false)
            return['ok'=>false,'error'=>'That is not a plugin of this site.'];
        $seg=explode('/',$file);
        foreach($seg as $s)if($this->pieName($s)==='')return['ok'=>false,'error'=>'That is not a plugin of this site.'];
        $real=realpath($dir.'/'.$file);
        $base=realpath($dir);
        if($real===false||$base===false||strpos($real,$base.'/')!==0||!is_file($real))
            return['ok'=>false,'error'=>'That plugin is not on this site any more.'];
        $want=(bool)$want;
        $r=$this->pieWpSetActive($file,$want);
        if(empty($r['ok']))return $r;
        $hdr=$this->pieWpMainFile($dir,$file);
        $this->log($want?'plugin_activate':'plugin_deactivate',$file);
        return $r+['file'=>$file,'name'=>$hdr['name']??''];
    }

    /* ── installing a package ────────────────────────────────────────────── */
    private function pieTmp($prefix='pie-'){
        $base=sys_get_temp_dir();
        if(!is_dir($base)||!@is_writable($base))$base=$this->pieWpRoot().'/wp-content';
        $n=$prefix.bin2hex(function_exists('random_bytes')?random_bytes(6):openssl_random_pseudo_bytes(6));
        return rtrim((string)$base,'/').'/'.$n;
    }

    /* Unpack a package into a staging folder and say what kind of thing it is.
       A zip slip (an entry that climbs out with ..) is refused outright. */
    private function pieUnpack($zipPath,$stage){
        if(!class_exists('ZipArchive'))return['ok'=>false,'error'=>'This PHP build has no zip extension, so a package cannot be unpacked.'];
        $zip=new ZipArchive();
        if(@$zip->open($zipPath)!==true)return['ok'=>false,'error'=>'That file is not a readable zip archive.'];
        if(!@mkdir($stage,0755,true)&&!is_dir($stage)){$zip->close();return['ok'=>false,'error'=>'The staging folder could not be created.'];}
        $real=realpath($stage);
        $n=$zip->numFiles;
        for($i=0;$i<$n;$i++){
            $name=(string)$zip->getNameIndex($i);
            if($name===''||strpos($name,'..')!==false||$name[0]==='/'||$name[0]==='\\'){
                $zip->close();return['ok'=>false,'error'=>'The archive contains an unsafe path ('.$name.'), so nothing was unpacked.'];
            }
        }
        if(@$zip->extractTo($stage)!==true){$zip->close();return['ok'=>false,'error'=>'The archive could not be unpacked - check the free disk space and the folder permissions.'];}
        $zip->close();
        $tops=[];
        foreach((array)@scandir($stage) as $e){if($e!=='.'&&$e!=='..')$tops[]=$e;}
        if(!$tops)return['ok'=>false,'error'=>'The archive was empty.'];
        $root=$stage;
        if(count($tops)===1&&is_dir($stage.'/'.$tops[0]))$root=$stage.'/'.$tops[0];
        return['ok'=>true,'stage'=>$stage,'root'=>$root,'folder'=>basename($root),'single'=>count($tops)===1];
    }

    /* A folder name is one path segment. Nothing else is accepted, so a name
       can never describe a place outside the folder it is read from. */
    private function pieName($n){
        $n=trim((string)$n);
        if($n===''||$n==='.'||$n==='..')return '';
        if(strpos($n,"\0")!==false)return '';
        if($n[0]==='/'||$n[0]==='\\')return '';
        if(strpos($n,'/')!==false||strpos($n,'\\')!==false)return '';
        if(preg_match('/[\x00-\x1f]/',$n))return '';
        return $n;
    }

    /* Removing is the one action here that cannot be undone, so it refuses any
       path that is not inside the site it was asked about. Without this a
       folder name like "../.." would have walked up out of the plugins folder
       and removed the site itself. */
    private function pieRmTree($p){
        if($p==='')return false;
        $cfg=$this->pieCfg();
        if($cfg==='')return false;
        $root=(string)($this->cmsConfigType($cfg)==='joomla'
            ?$this->pieJoomlaRoot()[0]
            :$this->wpSiteRoot($cfg));
        if($root===''||!is_dir($root))return false;
        $rp=realpath($root);
        $tp=realpath($p);
        if($rp===false||$tp===false)return false;
        if($tp===$rp||strpos($tp,$rp.'/')!==0)return false;
        if(is_file($tp)||is_link($tp))return @unlink($tp);
        foreach((array)@scandir($tp) as $e){
            if($e==='.'||$e==='..')continue;
            $this->pieRmTree($tp.'/'.$e);
        }
        return @rmdir($tp);
    }

    public function pieWpInstallRepo($slug,$overwrite=false){
        $slug=trim((string)$slug);
        if($slug==='')return['ok'=>false,'error'=>'No plugin was named.'];
        $info=$this->pieRepoInfo($slug);
        if(empty($info['ok']))return $info;
        $url=(string)($info['plugin']['download']??'');
        if($url==='')return['ok'=>false,'error'=>'The repository gave no download address for that plugin.'];
        return $this->pieWpInstallFromUrl($url,$info['plugin'],(bool)$overwrite);
    }

    private function pieWpInstallFromUrl($url,$meta,$overwrite=false){
        list($dir,$why)=$this->pieWpPluginsDir();
        if(!$dir)return['ok'=>false,'error'=>$why];
        $r=$this->pieHttp($url,null,180);
        if(empty($r['ok']))return $r;
        $zipPath=$this->pieTmp('pie-dl-').'.zip';
        if(@file_put_contents($zipPath,$r['body'])===false)
            return['ok'=>false,'error'=>'The package could not be saved to the temporary folder.'];
        $out=$this->pieWpPlaceZip($zipPath,$meta,$overwrite);
        @unlink($zipPath);
        return $out;
    }

    /* One place decides where an unpacked plugin goes, whatever the source was:
       the repository, an upload, or a URL. */
    private function pieFirstPhp($dir){
        /* glob is case-sensitive on Linux, but .PHP and .Php both occur in
           the wild and the installer accepts them, so the extension is matched
           without regard to case here too. */
        foreach((array)@glob(rtrim($dir,'/').'/*') as $f){
            if(!is_file($f)||strtolower(substr(basename($f),-4))!=='.php')continue;
            $head=@file_get_contents($f,false,null,0,8192);
            if($head&&stripos($head,'Plugin Name:')!==false)return basename($f);
        }
        return '';
    }

    /* Where the plugin actually lives inside an unpacked package.
       A package turns up in whatever shape its author zipped it: one folder
       holding the plugin, the files loose at the top, a __MACOSX folder left
       behind by Finder, or the main file one level down inside the folder.
       The old rule was "a PHP file with a Plugin Name header sits directly in
       the unpacked root", which refused any zip that did not match exactly.
       The rule here is the one WordPress itself uses: a plugin is the folder
       that directly holds that PHP file. So the shallowest directory holding
       one is what gets installed, which also guarantees WordPress will list
       the result. Matching is case-insensitive because .PHP and .Php both
       occur in the wild and glob on Linux is not. Junk folders are skipped so
       a stray __MACOSX is never mistaken for the plugin. */
    private function pieWpFindPluginFile($root,$maxDepth=4){
        $root=rtrim((string)$root,'/');
        $skip=['__MACOSX','node_modules','vendor','.git','.svn','.hg','tests','docs','languages','assets'];
        $hits=[];$seen=0;
        $walk=function($dir,$depth)use(&$walk,$maxDepth,$skip,&$hits,&$seen){
            if($depth>$maxDepth||$seen>4000)return;
            foreach((array)@glob($dir.'/*') as $f){
                if($seen++>4000)return;
                $b=basename($f);
                if($b===''||$b[0]==='.'||!is_file($f))continue;
                if(strtolower(substr($b,-4))!=='.php')continue;
                $head=(string)@file_get_contents($f,false,null,0,8192);
                if($head!==''&&stripos($head,'Plugin Name:')!==false)
                    $hits[]=['dir'=>$dir,'file'=>$b,'depth'=>$depth];
            }
            if($depth>=$maxDepth)return;
            foreach((array)@glob($dir.'/*',GLOB_ONLYDIR) as $d){
                $b=basename($d);
                if($b===''||$b[0]==='.'||in_array($b,$skip,true))continue;
                $walk($d,$depth+1);
            }
        };
        $walk($root,0);
        if(!$hits)return null;
        /* shallowest first, then the folder's own name, so the result is the
           same every time the same package is installed */
        usort($hits,function($a,$b){
            if($a['depth']!==$b['depth'])return $a['depth']<=$b['depth']?-1:1;
            return strcmp($a['file'],$b['file']);
        });
        return['dir'=>$hits[0]['dir'],'file'=>$hits[0]['file'],'others'=>count($hits)-1];
    }

    private function pieWpPlaceZip($zipPath,$meta,$overwrite=false){
        list($dir,$why)=$this->pieWpPluginsDir();
        if(!$dir)return['ok'=>false,'error'=>$why];
        if(!@is_writable($dir))
            return['ok'=>false,'error'=>'The plugins folder is not writable by this account: '.$dir];
        $stage=$this->pieTmp('pie-st-');
        $u=$this->pieUnpack($zipPath,$stage);
        if(empty($u['ok'])){$this->pieRmTree($stage);return $u;}
        $root=rtrim((string)$u['root'],'/');
        $found=$this->pieWpFindPluginFile($root);
        if(!$found){
            $this->pieRmTree($stage);
            return['ok'=>false,'error'=>'That package holds no WordPress plugin - no PHP file in it carries a "Plugin Name" header. A theme or a Joomla package will not install here.'];
        }
        $srcDir=$found['dir'];$main=$found['file'];
        $hdr=$this->cmsParseHeader((string)@file_get_contents($srcDir.'/'.$main,false,null,0,8192),
            ['name'=>'Plugin Name','version'=>'Version','description'=>'Description','author'=>'Author','req'=>'Requires at least','reqphp'=>'Requires PHP']);
        /* The folder holding the main file is the plugin folder, because that
           is the only shape WordPress will list. Files unpacked loose at the
           top have no folder to name themselves after, so the file's own name
           is used instead. */
        /* Careful: $u['single'] only means "one entry at the top", which is
           also true of a single loose file, and naming the plugin after the
           staging folder in that case puts a folder called pie-st-… in the
           plugins directory. Only the stage root itself counts as loose. */
        $slug=($srcDir===$stage)
            ? preg_replace('/\.php$/i','',$main)
            : basename($srcDir);
        if($slug===''||$slug==='.'||$slug==='..')
            $slug=preg_replace('/\.php$/i','',$main);
        $slug=preg_replace('/[^A-Za-z0-9._-]/','-',$slug);
        $target=$dir.'/'.$slug;
        $existed=@file_exists($target);
        if($existed){
            if(!$overwrite){
                $cur=is_dir($target)?$this->pieWpMainFile($dir,$slug.'/'.$this->pieFirstPhp($target)):$this->pieWpMainFile($dir,$slug);
                return['ok'=>false,'error'=>'A plugin already lives at '.$slug.'/. Choose "Replace the installed copy" to overwrite it.',
                       'exists'=>true,'slug'=>$slug,'installed_version'=>(string)($cur['version']??'')];
            }
            $this->pieRmTree($target);
        }
        if(!@rename($srcDir,$target)){
            /* a rename across filesystems fails; copy instead */
            if(!@mkdir($target,0755,true)){
                $this->pieRmTree($stage);
                return['ok'=>false,'error'=>'The plugin folder could not be created at '.$target.'.'];
            }
            $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($srcDir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);
            foreach($it as $f){
                $rel=substr($f->getPathname(),strlen($srcDir)+1);
                $dst=$target.'/'.$rel;
                if($f->isDir()){if(!@is_dir($dst))@mkdir($dst,0755,true);}
                elseif(!@copy($f->getPathname(),$dst)){
                    $this->pieRmTree($stage);
                    return['ok'=>false,'error'=>'A file could not be copied into '.$slug.'/.'];
                }
            }
        }
        $this->pieRmTree($stage);
        $file=$slug.'/'.$main;
        if(!is_file($dir.'/'.$file))return['ok'=>false,'error'=>'The plugin was unpacked but its main file is missing.'];
        $this->log('plugin_install',$slug.(empty($meta['slug'])?'':' (from the repository)'));
        $msg='Installed '.($hdr['name']?:$slug).($existed?' over the copy that was there':'').'. It is not active yet.';
        if(!empty($found['others']))
            $msg.=' The package held '.($found['others']+1).' plugins; the other '.$found['others'].' were left unpacked.';
        return['ok'=>true,'slug'=>$slug,'file'=>$file,'replaced'=>$existed,
               'name'=>$hdr['name']?:$slug,'version'=>$hdr['version']?:'',
               'description'=>trim(strip_tags((string)$hdr['description'])),
               'author'=>trim(strip_tags((string)$hdr['author'])),
               'requires'=>$hdr['req']?:'','requires_php'=>$hdr['reqphp']?:'',
               'from'=>ltrim(substr($srcDir,strlen($root)),'/'),
               'message'=>$msg];
    }

    /* ── deleting ────────────────────────────────────────────────────────── */
    public function pieWpDelete($slug){
        list($dir,$why)=$this->pieWpPluginsDir();
        if(!$dir)return['ok'=>false,'error'=>$why];
        $f=$this->pieWpFind(trim((string)$slug));
        if(!$f)return['ok'=>false,'error'=>'No plugin of that name is on this site.'];
        /* Never delete a plugin the CMS still counts as active. Note this
           fails closed: if the site's database cannot be reached there is no
           way to know whether the plugin is active, so the deletion is
           refused rather than going ahead on an empty answer - an unreachable
           database used to look exactly like "nothing is active". */
        $active=[];
        try{
            list($link,$c,$err)=$this->cmsConnect($this->pieCfg());
            if($err)
                return['ok'=>false,'error'=>'Whether that plugin is active is recorded in the site database, which could not be reached: '.$err];
            $t=$c['prefix'];
            $res=@mysqli_query($link,"SELECT option_value FROM `{$t}options` WHERE option_name='active_plugins' LIMIT 1");
            if($res&&($r=mysqli_fetch_assoc($res))){$u=@unserialize($r['option_value']);if(is_array($u))$active=$u;}
            @mysqli_close($link);
        }catch(\Throwable $e){
            return['ok'=>false,'error'=>'Whether that plugin is active could not be read, so nothing was deleted: '.$e->getMessage()];
        }
        $rec=(string)($f['plugin_file']??$f['file']);
        if($rec!==''&&in_array($rec,$active,true))
            return['ok'=>false,'error'=>'That plugin is active. Deactivate it first - deleting an active plugin leaves the site calling files that are gone.'];
        $this->pieRmTree($f['dir']);
        if(@file_exists($f['dir']))return['ok'=>false,'error'=>'The folder could not be removed - it is not writable by this account.'];
        $this->log('plugin_delete',$f['slug']);
        return['ok'=>true,'slug'=>$f['slug'],'message'=>'Deleted '.$f['slug'].'.'];
    }

    /* ── Joomla ──────────────────────────────────────────────────────────── */
    private function pieJoomlaRoot(){
        $cfg=$this->pieCfg();
        if($cfg==='')return[null,'No site was named.'];
        if($this->cmsConfigType($cfg)!=='joomla')return[null,'That config file is not a Joomla site.'];
        $root=dirname($cfg);
        if(!is_dir($root.'/administrator'))return[null,'That folder does not look like a Joomla installation.'];
        return[$root,''];
    }

    public function pieJoomlaInstalled(){
        list($root,$why)=$this->pieJoomlaRoot();
        if(!$root)return['ok'=>false,'error'=>$why];
        list($link,$c,$err)=$this->cmsConnect($this->pieCfg());
        if($err)return['ok'=>false,'error'=>$err];
        $t=$c['prefix'];
        $sql="SELECT extension_id,name,type,element,folder,client_id,enabled,protected,manifest_cache
              FROM `{$t}extensions`
              WHERE type IN ('component','module','plugin','template','library','file','package')
              ORDER BY protected ASC, type ASC, name ASC";
        $res=@mysqli_query($link,$sql);
        if(!$res){$e=@mysqli_error($link);@mysqli_close($link);return['ok'=>false,'error'=>'The extensions table could not be read: '.$e];}
        $out=[];
        while($row=@mysqli_fetch_assoc($res)){
            $mc=@json_decode((string)($row['manifest_cache']??''),true);
            if(!is_array($mc))$mc=[];
            $type=(string)$row['type'];
            $el=(string)$row['element'];
            $folder=(string)($row['folder']??'');
            $client=(int)$row['client_id']===1?'administrator':'site';
            /* "Core" means the manifest this row points at lives in the folder
               Joomla itself ships that kind of extension in. The protected
               flag alone does not mean that: Joomla leaves most of its own
               extensions unprotected, so calling the rest "third party" would
               have been wrong on a freshly installed site. */
            /* the manifest is not always named after the element - Joomla's own
               com_actionlogs ships actionlogs.xml - so any manifest in the
               folder counts as the folder being a real one */
            $hasManifest=function($d){
                if(!@is_dir($d))return false;
                foreach((array)@glob($d.'/*.xml') as $f){
                    $h=(string)@file_get_contents($f,false,null,0,4096);
                    if(stripos($h,'<extension')!==false)return true;
                }
                return false;
            };
            $core=false;
            if($type==='component')$core=$hasManifest($root.'/administrator/components/'.$el)
                                          ||$hasManifest($root.'/components/'.$el);
            elseif($type==='module')$core=$hasManifest($root.'/modules/'.$el)
                                          ||$hasManifest($root.'/administrator/modules/'.$el);
            elseif($type==='plugin')$core=$folder!==''&&$hasManifest($root.'/plugins/'.$folder.'/'.$el);
            elseif($type==='template')$core=@is_file($root.'/templates/'.$el.'/templateDetails.xml')
                                          ||@is_file($root.'/administrator/templates/'.$el.'/templateDetails.xml');
            elseif($type==='library')$core=$hasManifest($root.'/libraries/'.$el)
                                         ||@is_dir($root.'/libraries/vendor/joomla/'.$el);
            $out[]=[
                'id'=>(int)$row['extension_id'],
                'name'=>(string)$row['name'],
                'type'=>$type,
                'element'=>$el,
                'folder'=>$folder,
                'client'=>$client,
                'enabled'=>(int)$row['enabled']===1,
                'protected'=>(int)$row['protected']===1,
                'core'=>$core,
                'version'=>(string)($mc['version']??''),
                'author'=>(string)($mc['author']??''),
                'date'=>(string)($mc['creationDate']??''),
            ];
        }
        @mysqli_close($link);
        $jv=$this->pieJoomlaVersion($root);
        usort($out,function($a,$b){
            if($a['protected']!==$b['protected'])return $a['protected']?1:-1;
            return strcasecmp($a['name'],$b['name']);
        });
        return['ok'=>true,'cms'=>'joomla','extensions'=>$out,'root'=>$root,'joomla_version'=>$jv,
               'core_count'=>count(array_filter($out,function($x){return $x['core'];})),
               'protected_count'=>count(array_filter($out,function($x){return $x['protected'];})),
               'third_party'=>count(array_filter($out,function($x){return !$x['core'];}))];
    }

    private function pieJoomlaVersion($root){
        $f=$root.'/libraries/src/Version.php';
        if(!is_file($f))$f=$root.'/libraries/cms/version/version.php';
        if(!is_file($f))return '';
        $s=(string)@file_get_contents($f,false,null,0,8192);
        if(preg_match("/MAJOR_VERSION\\s*=\\s*'?([0-9]+)/",$s,$a)&&preg_match("/MINOR_VERSION\\s*=\\s*'?([0-9]+)/",$s,$b))
            return $a[1].'.'.$b[1];
        if(preg_match("/\\\$RELEASE\\s*=\\s*'([^']+)'/",$s,$m))return $m[1];
        return '';
    }

    public function pieJoomlaEnable($id,$want){
        list($root,$why)=$this->pieJoomlaRoot();
        if(!$root)return['ok'=>false,'error'=>$why];
        list($link,$c,$err)=$this->cmsConnect($this->pieCfg());
        if($err)return['ok'=>false,'error'=>$err];
        $t=$c['prefix'];
        $id=(int)$id;
        $res=@mysqli_query($link,"SELECT name,enabled,protected,type FROM `{$t}extensions` WHERE extension_id=$id LIMIT 1");
        $row=$res?@mysqli_fetch_assoc($res):null;
        if(!$row){@mysqli_close($link);return['ok'=>false,'error'=>'No extension carries that id on this site.'];}
        if((int)$row['protected']===1){
            @mysqli_close($link);
            return['ok'=>false,'error'=>$row['name'].' is a core extension. Joomla protects it, and disabling one can leave the site unable to start.'];
        }
        $want=(bool)$want;
        if(((int)$row['enabled']===1)===$want){
            @mysqli_close($link);
            return['ok'=>true,'enabled'=>$want,'changed'=>false,'name'=>$row['name'],
                   'note'=>$want?'That extension was already enabled.':'That extension was already disabled.'];
        }
        @mysqli_query($link,"UPDATE `{$t}extensions` SET enabled=".(int)$want." WHERE extension_id=$id");
        $errno=@mysqli_errno($link);
        $error=$errno?(string)@mysqli_error($link):'';
        @mysqli_close($link);
        if($errno!==0)return['ok'=>false,'error'=>'The row could not be written: '.$error];
        /* Joomla caches its plugin list; drop it so the change takes effect now */
        $cache=$root.'/cache';
        foreach((array)@glob($cache.'/*') as $f){if(is_file($f))@unlink($f);}
        $this->log($want?'extension_enable':'extension_disable',$row['name']);
        return['ok'=>true,'enabled'=>$want,'changed'=>true,'name'=>$row['name'],
               'note'=>$want
                 ?'Enabled. The extension\'s own install routine did not run - this window writes the row Joomla reads. If it needs a one-time setup, open its own screen in the administrator once.'
                 :'Disabled. The Joomla cache was cleared so the change applies at once.'];
    }

    public function pieJoomlaDelete($id){
        list($root,$why)=$this->pieJoomlaRoot();
        if(!$root)return['ok'=>false,'error'=>$why];
        list($link,$c,$err)=$this->cmsConnect($this->pieCfg());
        if($err)return['ok'=>false,'error'=>$err];
        $t=$c['prefix'];
        $id=(int)$id;
        $res=@mysqli_query($link,"SELECT name,protected,type,element FROM `{$t}extensions` WHERE extension_id=$id LIMIT 1");
        $row=$res?@mysqli_fetch_assoc($res):null;
        @mysqli_close($link);
        if(!$row)return['ok'=>false,'error'=>'No extension carries that id on this site.'];
        if((int)$row['protected']===1)
            return['ok'=>false,'error'=>$row['name'].' is a core extension and is not removed from here.'];
        return['ok'=>false,'error'=>'Removing a Joomla extension means undoing its manifest - the files, its menu entries, its schema and its update row. That is Joomla\'s own uninstaller\'s job, and guessing at it leaves a site half-removed. Use Uninstall in the administrator for this one; this window installs, enables and disables.'];
    }

    /* ── the endpoint ────────────────────────────────────────────────────── */
    public function pieEndpoint($post){
        /* Every caller of this endpoint expects JSON. An uncaught throwable
           would instead produce a half-rendered error page, so the whole thing
           runs inside a guard: whatever goes wrong below is reported as a
           message the window can show, never as a stack trace. */
        try{
            return $this->pieEndpointWork($post);
        }catch(\Throwable $e){
            return['ok'=>false,'error'=>'The installer stopped: '.$e->getMessage()];
        }
    }

    private function pieEndpointWork($post){
        $act=(string)($post['action']??'');
        $this->pieConfigPath=(string)($post['config']??'');
        if($act==='sites')return $this->pieSites($post);

        /* repository browsing needs no site at all */
        if($act==='browse')return $this->pieRepoBrowse(
            (string)($post['browse']??'featured'),(string)($post['search']??''),
            (int)($post['page']??1),(int)($post['per_page']??24));
        if($act==='info')return $this->pieRepoInfo((string)($post['slug']??''));
        if($act==='repo_meta')return $this->pieRepoMeta($post['slugs']??'');
        if($act==='jed')return['ok'=>true,'url'=>'https://extensions.joomla.org/'];

        /* everything below acts on one named site */
        if($this->pieCfg()==='')return['ok'=>false,'error'=>'No site was named. Pick the site this should apply to.'];
        if($act==='installed'){
            if($this->cmsConfigType($this->pieCfg())==='joomla')return $this->pieJoomlaInstalled();
            return $this->pieWpInstalled();
        }
        if($act==='wp_install'){
            return $this->pieWpInstallRepo((string)($post['slug']??''),!empty($post['overwrite'])&&$post['overwrite']!=='0');
        }
        if($act==='wp_activate'){
            return $this->pieWpActivate((string)($post['file']??''),!empty($post['want'])&&$post['want']!=='0');
        }
        if($act==='wp_delete')return $this->pieWpDelete((string)($post['slug']??''));
        if($act==='j_enable'){
            return $this->pieJoomlaEnable((int)($post['id']??0),!empty($post['want'])&&$post['want']!=='0');
        }
        if($act==='j_delete')return $this->pieJoomlaDelete((int)($post['id']??0));
        return['ok'=>false,'error'=>'Unknown request.'];
    }

    /* the upload arrives as a real file, so it is handled where the other
       uploads are handled and then handed to the same placing code */
    public function pieUpload($post,$file){
        $this->pieConfigPath=(string)($post['config']??'');
        if($this->pieCfg()==='')return['ok'=>false,'error'=>'No site was named.'];
        if((int)($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)
            return['ok'=>false,'error'=>'No package arrived with that request.'];
        if((int)$file['error']!==UPLOAD_ERR_OK)
            return['ok'=>false,'error'=>'The upload failed (code '.$file['error'].'). The server allows up to '.ini_get('upload_max_filesize').'.'];
        $tmp=(string)($file['tmp_name']??'');
        if($tmp===''||!is_readable($tmp))return['ok'=>false,'error'=>'The uploaded package could not be read.'];
        if(!is_uploaded_file($tmp))return['ok'=>false,'error'=>'That file did not arrive as an upload, so it is not installed.'];
        $name=basename((string)($file['name']??'package.zip'));
        if(strtolower(substr($name,-4))!=='.zip')
            return['ok'=>false,'error'=>'Only a .zip package can be installed. That file is named '.$name.'.'];
        if($this->cmsConfigType($this->pieCfg())==='joomla')
            return $this->pieJoomlaUpload($tmp,$name,!empty($post['overwrite'])&&$post['overwrite']!=='0');
        return $this->pieWpPlaceZip($tmp,['uploaded'=>$name],!empty($post['overwrite'])&&$post['overwrite']!=='0');
    }

    /* A Joomla package is unpacked and placed by its manifest. This covers the
       extension kinds whose files simply live in a known folder, and it says
       plainly when it cannot, rather than leaving a half-installed extension
       behind and reporting success. */
    private function pieJoomlaUpload($tmp,$name,$overwrite=false){
        /* mysqli throws on a failed query in PHP 8, and an uncaught throw here
           would reach the reader as a server error page instead of a sentence */
        try{
            return $this->pieJoomlaPlace($tmp,$name,$overwrite);
        }catch(\Throwable $e){
            return['ok'=>false,'error'=>'The install stopped: '.$e->getMessage()];
        }
    }

    private function pieJoomlaPlace($tmp,$name,$overwrite=false){
        list($root,$why)=$this->pieJoomlaRoot();
        if(!$root)return['ok'=>false,'error'=>$why];
        $stage=$this->pieTmp('pie-j-');
        $u=$this->pieUnpack($tmp,$stage);
        if(empty($u['ok'])){$this->pieRmTree($stage);return $u;}
        $srcRoot=(string)$u['root'];
        $xml='';
        foreach((array)@glob($srcRoot.'/*.xml') as $f){
            $head=(string)@file_get_contents($f,false,null,0,4096);
            if(stripos($head,'<extension')!==false||stripos($head,'<install')!==false){$xml=$f;break;}
        }
        if($xml===''){
            $this->pieRmTree($stage);
            return['ok'=>false,'error'=>'That package holds no Joomla manifest - no XML file in it declares an <extension>. A WordPress plugin will not install here.'];
        }
        $x=@simplexml_load_file($xml);
        if(!$x){$this->pieRmTree($stage);return['ok'=>false,'error'=>'The manifest could not be parsed.'];}
        $type=(string)($x->attributes()->type??'');
        $element='';
        if(isset($x->element))$element=(string)$x->element;
        if($element==='')$element=basename($srcRoot);
        if(!in_array($type,['module','plugin','template','library','file','component','package'],true)){
            $this->pieRmTree($stage);
            return['ok'=>false,'error'=>'The manifest names an unknown extension type ('.($type?:'none').').'];
        }
        $dest='';$clientDir='';
        $clientId=0;
        if(isset($x->client)&&strtolower((string)$x->client)==='administrator'){$clientId=1;$clientDir='/administrator';}
        switch($type){
            case 'module':
                $folder=(isset($x->namespace)?'':'');
                $dest=$root.$clientDir.'/modules/'.$element;break;
            case 'plugin':
                $group=(string)($x->attributes()->group??'');
                $dest=$root.'/plugins/'.($group!==''?$group:'system').'/'.$element;break;
            case 'template':
                $dest=$root.$clientDir.'/templates/'.$element;break;
            case 'library':
                $dest=$root.'/libraries/'.$element;break;
            case 'file':
                $dest=$root.'/';break;
            case 'component':
                $dest=$root.$clientDir.'/components/'.$element;break;
            case 'package':
                $this->pieRmTree($stage);
                return['ok'=>false,'error'=>'A Joomla package installs several extensions at once, each with its own schema and rows. That is Joomla\'s own installer\'s job; unpacking it here would leave the site with files and no extension behind them. Install this one from the administrator, or install the pieces one by one.'];
        }
        if($dest===''||strpos($dest,$root.'/')!==0){
            $this->pieRmTree($stage);
            return['ok'=>false,'error'=>'The manifest points outside this Joomla installation, so nothing was written.'];
        }
        if(!@is_writable(dirname($dest))&&!@is_writable($dest)){
            $this->pieRmTree($stage);
            return['ok'=>false,'error'=>'The target folder is not writable by this account: '.dirname($dest)];
        }
        if(@is_dir($dest)&&!$overwrite){
            /* what is in that folder now is the installed copy of this
               extension; replacing it silently would take its settings and any
               file of its own with it */
            $this->pieRmTree($stage);
            return['ok'=>false,'exists'=>true,'placed'=>$dest,
                   'error'=>'That extension is already installed at '.$dest.'. Replace the installed copy?'];
        }
        if(@is_dir($dest))$this->pieRmTree($dest);
        /* placing files and then finding out the row cannot be written leaves an
           extension on disk that Joomla does not know about, so the table is
           checked before anything is written */
        list($link0,$c0,$err0)=$this->cmsConnect($this->pieCfg());
        if($err0){
            $this->pieRmTree($stage);
            return['ok'=>false,'error'=>'The site database could not be reached, so nothing was installed: '.$err0];
        }
        $probe=@mysqli_query($link0,"SELECT extension_id FROM `{$c0['prefix']}extensions` LIMIT 1");
        if(!$probe){
            $e=(string)@mysqli_error($link0);@mysqli_close($link0);$this->pieRmTree($stage);
            return['ok'=>false,'error'=>'The extensions table could not be read, so nothing was installed: '.$e];
        }
        @mysqli_close($link0);
        if(!@mkdir($dest,0755,true)&&!is_dir($dest)){
            $this->pieRmTree($stage);
            return['ok'=>false,'error'=>'The target folder could not be created: '.$dest];
        }
        $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($srcRoot,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);
        foreach($it as $f){
            $rel=substr($f->getPathname(),strlen($srcRoot)+1);
            $dst=$dest.'/'.$rel;
            if($f->isDir()){if(!@is_dir($dst))@mkdir($dst,0755,true);}
            elseif(!@copy($f->getPathname(),$dst)){
                $this->pieRmTree($stage);
                return['ok'=>false,'error'=>'A file could not be copied into '.$dest.'.'];
            }
        }
        $this->pieRmTree($stage);
        /* the extension row Joomla lists it from */
        list($link,$c,$err)=$this->cmsConnect($this->pieCfg());
        if($err)return['ok'=>true,'placed'=>$dest,'row'=>false,
            'error'=>'The files were placed, but the extension row could not be written: '.$err];
        $t=$c['prefix'];
        $dbError='';
        $nameS=mysqli_real_escape_string($link,(string)($x->name??$element));
        $elS=mysqli_real_escape_string($link,$element);
        $tyS=mysqli_real_escape_string($link,$type);
        $grS=mysqli_real_escape_string($link,(string)($x->attributes()->group??''));
        $mc=mysqli_real_escape_string($link,json_encode([
            'name'=>(string)($x->name??$element),'version'=>(string)($x->version??''),
            'creationDate'=>(string)($x->creationDate??''),'author'=>(string)($x->author??''),
            'authorUrl'=>(string)($x->authorUrl??''),'copyright'=>(string)($x->copyright??''),
            'description'=>(string)($x->description??''),
        ]));
        $res=@mysqli_query($link,"SELECT extension_id FROM `{$t}extensions` WHERE type='$tyS' AND element='$elS' AND client_id=$clientId LIMIT 1");
        $have=$res&&($r=@mysqli_fetch_assoc($res))?(int)$r['extension_id']:0;
        if($have){
            @mysqli_query($link,"UPDATE `{$t}extensions` SET name='$nameS', manifest_cache='$mc', folder='$grS' WHERE extension_id=$have");
        }else{
            /* every column Joomla declares NOT NULL without a default is named
               here; leaving one out makes the driver throw instead of returning
               an error this window can report */
            @mysqli_query($link,"INSERT INTO `{$t}extensions` (name,type,element,folder,client_id,enabled,protected,manifest_cache,access,params,custom_data,checked_out,checked_out_time,ordering,state)
                                 VALUES ('$nameS','$tyS','$elS','$grS',$clientId,0,0,'$mc',1,'{}','{}',0,NULL,0,0)");
            $have=(int)@mysqli_insert_id($link);
        }
        $errno=@mysqli_errno($link);
        $error=$errno?(string)@mysqli_error($link):'';
        @mysqli_close($link);
        if($dbError!==''||$errno!==0)return['ok'=>true,'placed'=>$dest,'row'=>false,
            'error'=>'The files were placed, but the extension row could not be written: '.($dbError!==''?$dbError:$error)
                    .' Install it again once the row can be written, or finish it from the administrator.'];
        $this->log('extension_install',$element.' ('.$type.')');
        return['ok'=>true,'id'=>$have,'element'=>$element,'type'=>$type,'name'=>(string)($x->name??$element),
               'version'=>(string)($x->version??''),'placed'=>$dest,'row'=>true,
               'message'=>'Installed '.$element.' ('.$type.'). It is not enabled yet, and its own install script and SQL did not run - enable it here, then open its screen in the administrator once so it can finish any setup it needs.'];
    }
    /* ══ Site discovery ═════════════════════════════════════════════════════
       Both windows that act on a site - the Plugins Installer and the
       Wordfence controller - need the same answer to the same question: what
       CMSs are installed on this server, and where exactly is each one's root?

       The manager's own cmsScan() answers that from a fixed list of roots, in
       one walk with a 2,500-directory budget, without following symlinks. On a
       busy host that budget is spent inside the first few accounts and every
       site after them is invisible; a document root that is a symlink is
       invisible too; and a directory holding nothing but wp-config.php is
       reported as a site even though no WordPress lives in it.

       This scanner is layered, and any layer may find a site the others miss:

         seeds   - web server configuration (nginx, Apache, LiteSpeed, Plesk,
                   cPanel, Hestia/Vesta, DirectAdmin, aaPanel), every home
                   directory and its usual web sub-folders, the standard roots,
                   the manager's own folders, DOCUMENT_ROOT and open_basedir
         walk    - a breadth-first walk that follows symlinks, prunes only
                   trees that cannot hold a site, and is bounded by a clock
                   rather than by a guess about how many directories exist
         identify- a directory is a CMS because of the CMS's own files, not
                   because a config file happens to sit in it; the config is
                   then looked for above and beside that root

       The last point is the one that decides whether installing works: the
       root is where wp-content lives, and that is where a plugin has to be
       written. Reporting the directory that holds wp-config.php instead - the
       directory above the real root, in the common hardened layout - would
       quietly install into a folder that is not a WordPress installation. */

    private function sitesSeeds(){
        $seeds=[];
        $add=function($p,$why)use(&$seeds){
            if(!is_string($p)||$p==='')return;
            if(strpos($p,'$')!==false)return;                 /* nginx variables */
            $p=rtrim($p,'/');
            if($p===''||!@is_dir($p)||!@is_readable($p))return;
            $real=@realpath($p);
            if(!$real)return;
            if(!isset($seeds[$real]))$seeds[$real]=$why;
        };
        $addWhy=function($p,$why)use(&$seeds,$add){$add($p,$why);};

        /* ── 1. what the web server itself is configured to serve ────────── */
        $confGlobs=[
            '/etc/nginx/nginx.conf','/etc/nginx/conf.d/*.conf','/etc/nginx/sites-enabled/*',
            '/etc/nginx/sites-available/*','/etc/nginx/vhosts.d/*.conf',
            '/usr/local/nginx/conf/nginx.conf','/usr/local/nginx/conf/vhost/*.conf',
            '/etc/apache2/apache2.conf','/etc/apache2/httpd.conf','/etc/apache2/sites-enabled/*',
            '/etc/apache2/sites-available/*','/etc/apache2/vhosts.d/*.conf','/etc/apache2/conf.d/*.conf',
            '/etc/httpd/conf/httpd.conf','/etc/httpd/conf.d/*.conf','/etc/httpd/conf/vhosts/*.conf',
            '/usr/local/apache/conf/httpd.conf','/usr/local/etc/apache24/httpd.conf',
            '/usr/local/lsws/conf/httpd_config.conf','/usr/local/lsws/conf/vhosts/*/vhconf.conf',
            '/www/server/panel/vhost/nginx/*.conf','/www/server/panel/vhost/apache/*.conf',
            '/etc/litespeed/httpd_config.conf',
        ];
        foreach($confGlobs as $g){
            foreach((array)@glob($g) as $f){
                if(!@is_readable($f))continue;
                $txt=(string)@file_get_contents($f,false,null,0,1048576);
                if($txt==='')continue;
                if(preg_match_all('/^\s*(?:root|DocumentRoot)\s+"?([^;"\s]+)"?\s*;?\s*$/mi',$txt,$m)){
                    foreach($m[1] as $r)$addWhy(rtrim($r,'"'),'web server config');
                }
            }
        }
        /* cPanel keeps the document root of every domain in a small file */
        foreach((array)@glob('/var/cpanel/userdata/*/*') as $f){
            if(!@is_file($f)||!@is_readable($f))continue;
            $txt=(string)@file_get_contents($f,false,null,0,65536);
            if(preg_match('/^\s*documentroot:\s*(\S+)/mi',$txt,$m))$addWhy($m[1],'cPanel userdata');
            if(preg_match('/^\s*homedir:\s*(\S+)/mi',$txt,$m))$addWhy($m[1],'cPanel userdata');
        }
        foreach((array)@glob('/etc/userdatadomains/*') as $f){
            $txt=(string)@file_get_contents($f,false,null,0,65536);
            if(preg_match('/documentroot=(\S+)/i',$txt,$m))$addWhy($m[1],'cPanel userdata');
        }

        /* ── 2. account layouts ─────────────────────────────────────────── */
        $webSubs=['public_html','www','htdocs','httpdocs','web','public','public_wp','html',
                  'sites','domains','subdomains','private_html'];
        foreach((array)@glob('/home/*',GLOB_ONLYDIR|GLOB_NOSORT) as $h){
            $addWhy($h,'home directory');
            foreach($webSubs as $s)$addWhy($h.'/'.$s,'home directory');
            foreach((array)@glob($h.'/domains/*/public_html',GLOB_ONLYDIR|GLOB_NOSORT) as $d)$addWhy($d,'home directory');
            foreach((array)@glob($h.'/domains/*',GLOB_ONLYDIR|GLOB_NOSORT) as $d)$addWhy($d,'home directory');
            foreach((array)@glob($h.'/sites/*/web',GLOB_ONLYDIR|GLOB_NOSORT) as $d)$addWhy($d,'home directory');
        }
        foreach((array)@glob('/var/www/vhosts/*/httpdocs',GLOB_ONLYDIR|GLOB_NOSORT) as $d)$addWhy($d,'Plesk vhost');
        foreach((array)@glob('/var/www/vhosts/*',GLOB_ONLYDIR|GLOB_NOSORT) as $d)$addWhy($d,'Plesk vhost');
        foreach((array)@glob('/var/www/*',GLOB_ONLYDIR|GLOB_NOSORT) as $d)$addWhy($d,'standard root');
        foreach((array)@glob('/srv/*',GLOB_ONLYDIR|GLOB_NOSORT) as $d)$addWhy($d,'standard root');
        foreach((array)@glob('/opt/*',GLOB_ONLYDIR|GLOB_NOSORT) as $d)$addWhy($d,'standard root');

        /* ── 3. the plain roots, and everything this process is allowed ──── */
        foreach(['/var/www','/var/www/html','/srv','/srv/www','/srv/http','/opt','/data','/www',
                 '/usr/share/nginx','/usr/local/www','/home','/var/lib/plesk','/mnt','/media'] as $r)
            $addWhy($r,'standard root');

        foreach([$this->root ?? null,$this->currentDir ?? null,getcwd(),
                 $_SERVER['DOCUMENT_ROOT']??null,dirname($_SERVER['DOCUMENT_ROOT']??''),
                 dirname($_SERVER['SCRIPT_FILENAME']??''),
                 dirname(dirname($_SERVER['SCRIPT_FILENAME']??''))] as $r)$addWhy($r,'this manager');

        $obd=ini_get('open_basedir');
        if($obd)foreach(explode(PATH_SEPARATOR,$obd) as $p)$addWhy(rtrim($p,'/'),'open_basedir');

        return$seeds;
    }

    /* A directory is a WordPress root because WordPress is in it - not
       because a config file is. wp-config.php on its own proves nothing: the
       hardened layout puts it a level above the web root, and a backup copy
       puts it somewhere that serves nothing. */
    private function sitesIdentify($dir,$how){
        $wpCore=@is_file($dir.'/wp-includes/version.php')
              ||(@is_file($dir.'/wp-load.php')&&@is_dir($dir.'/wp-admin'));
        if($wpCore){
            return['type'=>'wordpress','dir'=>$dir,'config'=>$this->sitesFindConfig($dir,'wordpress'),
                   'source'=>$how];
        }
        $joomlaCore=(@is_dir($dir.'/administrator')&&(@is_dir($dir.'/libraries')||@is_dir($dir.'/includes')))
                  ||(@is_dir($dir.'/administrator')&&@is_dir($dir.'/plugins')&&@is_dir($dir.'/modules'));
        if($joomlaCore){
            return['type'=>'joomla','dir'=>$dir,'config'=>$this->sitesFindConfig($dir,'joomla'),
                   'source'=>$how];
        }
        return null;
    }
    /* The config is searched for above the root (hardened layouts), in the
       root itself, and one level beside it, and it is only accepted once it
       really contains that CMS's credentials. */
    private function sitesFindConfig($dir,$type){
        $needle=$type==='wordpress'?'DB_NAME':'JConfig';
        $up=$dir;
        for($i=0;$i<4;$i++){
            foreach(['wp-config.php','configuration.php','wp-config-secure.php','config/wp-config.php'] as $f){
                $p=$up.'/'.$f;
                if(@is_file($p)&&@is_readable($p)){
                    $t=(string)@file_get_contents($p,false,null,0,65536);
                    if($t!==''&&strpos($t,$needle)!==false)return@realpath($p)?:$p;
                }
            }
            $next=dirname($up);
            if($next===$up||$next===''||$next==='/')break;
            $up=$next;
        }
        foreach(['config','conf','private','secure','etc','../config','../conf'] as $sub){
            $p=$dir.'/'.$sub.'/'.($type==='wordpress'?'wp-config.php':'configuration.php');
            if(@is_file($p)&&@is_readable($p)){
                $t=(string)@file_get_contents($p,false,null,0,65536);
                if($t!==''&&strpos($t,$needle)!==false)return@realpath($p)?:$p;
            }
        }
        return null;
    }

    /* A directory that holds a config file but no CMS: look one and two levels
       down for the folder the CMS actually lives in. */
    private function sitesChildRoot($dir,$type){
        if($dir===''||!@is_dir($dir))return null;
        for($depth=1;$depth<=2;$depth++){
            $pattern=str_repeat('*/',$depth);
            foreach((array)@glob($dir.'/'.$pattern,GLOB_ONLYDIR|GLOB_NOSORT) as $sub){
                if(count(explode('/',str_replace($dir.'/', '', $sub)))!==$depth)continue;
                $hit=$this->sitesIdentify($sub,'config file above the root');
                if($hit&&($type===''||$hit['type']===$type))return$hit;
            }
        }
        return null;
    }

    private function sitesWalk($seeds,$maxSeconds,$maxDirs=24000,$maxDepth=14){
        $t0=microtime(true);
        $seen=[];$out=[];$dirs=0;$stopped='';$alias=[];
        $prune=['.git','node_modules','.svn','.hg','.cache','.npm','.yarn','__pycache__',
                'proc','sys','dev','run','lost+found','.composer','bower_components',
                '.well-known','.idea','.vscode'];
        $queue=[];
        foreach($seeds as $real=>$why)$queue[]=[$real,0,$why];
        while($queue){
            if(microtime(true)-$t0>$maxSeconds){$stopped='time';break;}
            if($dirs>=$maxDirs){$stopped='directory budget';break;}
            list($dir,$depth,$how)=array_shift($queue);
            /* Plenty of hosts point the document root at the real folder
               through a link, and the link is the name the control panel and
               the web server both use. The walk has to resolve links to avoid
               circling, so the link's own name is recorded here and put back
               on the result afterwards. */
            if(@is_link($dir)){
                $rp=@realpath($dir);
                if($rp&&!isset($alias[$rp]))$alias[$rp]=$dir;
            }
            $real=@realpath($dir);
            if(!$real||isset($seen[$real]))continue;
            if(!@is_dir($real)||!@is_readable($real))continue;
            $seen[$real]=1;$dirs++;
            $hit=$this->sitesIdentify($real,$how);
            if($hit)$out[]=$hit;
            if($depth>=$maxDepth)continue;
            $ents=@scandir($real);
            if(!$ents)continue;
            foreach($ents as $e){
                if($e==='.'||$e==='..')continue;
                if(in_array($e,$prune,true))continue;
                $p=$real.'/'.$e;
                /* is_dir() follows a symlink, which is the point: plenty of
                   hosts map the document root through one */
                if(!@is_dir($p))continue;
                $queue[]=[$p,$depth+1,$how==='standard root'||$how==='home directory'?'walk':$how];
            }
        }
        return['sites'=>$out,'dirs'=>$dirs,'secs'=>round(microtime(true)-$t0,2),
               'stopped'=>$stopped,'alias'=>$alias];
    }

    /* One answer for both windows: the manager's own scan, then the layered
       walk, merged and de-duplicated. Kept for two minutes so opening the
       second window does not walk the filesystem again. */
    private function sitesAll($force=false,$deepSeconds=0){
        $key='sitescan_cache';
        $cached=$_SESSION[$key]??null;
        if(is_array($cached)&&!$force&&(time()-($cached['at']??0))<120){
            $cached['res']['cached']=true;
            return$cached['res'];
        }
        $t0=microtime(true);
        $quick=$this->cmsScan();
        $quickSites=(array)($quick['sites']??[]);

        $seconds=$deepSeconds>0?$deepSeconds:(count($quickSites)?9:25);
        $seeds=$this->sitesSeeds();
        $walk=$this->sitesWalk($seeds,$seconds);

        $out=[];$byDir=[];
        $take=function($s,$source)use(&$out,&$byDir){
            $dir=(string)($s['dir']??'');
            $cfg=(string)($s['config']??'');
            if($dir===''&&$cfg==='')return;
            if($dir==='')$dir=dirname($cfg);
            $key=$dir?:dirname($cfg);
            $cred=$cfg!==''&&@is_readable($cfg);
            $new=['type'=>(string)($s['type']??''),'dir'=>$dir,'config'=>$cfg,
                  'source'=>(string)($s['source']??$source),'credentials'=>$cred,
                  'writable'=>$dir!==''?@is_writable($dir.'/'.(($s['type']??'')==='joomla'?'configuration.php':'wp-config.php')):false];
            if(isset($byDir[$key])){
                /* keep the copy that can actually be used: one that carries a
                   readable config beats one that does not */
                $old=&$out[$byDir[$key]];
                if(!$old['credentials']&&$cred)$out[$byDir[$key]]=$new;
                return;
            }
            $byDir[$key]=count($out);
            $out[]=$new;
        };
        foreach($quickSites as $s){
            $dir=(string)($s['dir']??'');$cfg=(string)($s['config']??'');
            if($dir===''&&$cfg!=='')$dir=dirname($cfg);
            /* The manager's scanner reports a directory as a site when it finds
               a config file in it. In the hardened layout that directory holds
               nothing but the config, and the installation is one or two levels
               below it. Taken at face value the window would offer a site whose
               wp-content is somewhere else entirely, and installing into it
               would write files into a folder that is not a site. So every hit
               is re-identified against the CMS's own files, and a directory
               that is not a root is either resolved to the child that is, or
               dropped as a config file with no installation behind it. */
            $hit=$this->sitesIdentify($dir,(string)($s['source']??'the manager\'s scan'));
            if(!$hit)$hit=$this->sitesChildRoot($dir,(string)($s['type']??''));
            if(!$hit)continue;
            if(empty($hit['config']))$hit['config']=$cfg;
            $take($hit,(string)($s['source']??'the manager\'s scan'));
        }
        foreach(($walk['sites']??[]) as $s)$take($s,'deep scan');

        /* One installation can be reached by its real folder and by a link to
           it. The link is served, so it is the name to show; the real folder
           is dropped rather than offered twice. */
        $alias=(array)($walk['alias']??[]);
        if($alias){
            foreach($out as $i=>$s){
                $rp=@realpath($s['dir']);
                if($rp&&isset($alias[$rp])&&$alias[$rp]!==$s['dir']){
                    $out[$i]['dir']=$alias[$rp];
                    $out[$i]['source']=rtrim($s['source'],'.').', reached through the link '.$alias[$rp];
                }
            }
            $again=[];
            foreach($out as $s){
                $rp=@realpath($s['dir'])?:'';
                if(isset($again[$rp])){
                    if($again[$rp]['credentials']||!(!empty($s['credentials'])))continue;
                    continue;
                }
                $again[$rp]=$s;
            }
            $out=array_values($again);
        }

        usort($out,function($a,$b){return strcmp($a['dir'],$b['dir']);});
        $ok=array_values(array_filter($out,function($s){return$s['credentials'];}));
        $res=['ok'=>true,'sites'=>$out,
              'wp_core'=>$this->pieWpCoreVersion(),'php'=>PHP_VERSION,
              'scanned_roots'=>array_slice(array_keys($seeds),0,40),
              'seeds'=>count($seeds),'dirs_scanned'=>$walk['dirs'],
              'scan_seconds'=>$walk['secs'],'seconds'=>round(microtime(true)-$t0,2),
              'stopped'=>$walk['stopped'],'open_basedir'=>$quick['open_basedir']??[],
              'usable'=>count($ok),'cached'=>false];
        $_SESSION[$key]=['at'=>time(),'res'=>$res];
        return$res;
    }

    /* Pressing "Deep scan" buys the walk more time, and says so: a scan that
       walks for half a minute without explaining itself looks like a hang. */
    public function sitesDeep($post){
        if(empty($_SESSION['fm_admin']))return['ok'=>false,'error'=>'Admins only.'];
        $r=$this->sitesAll(true,45);
        $r['deep']=true;
        return$r;
    }
    /* ══ Wordfence Controller ═════════════════════════════════════════════════
       One window that drives the Wordfence plugin already installed on this
       server: its settings, its firewall, its blocks, its scan, its logs and
       its caches.

       It finds the plugin by walking the sites the manager's own scanner
       reports and looking for wp-content/plugins/wordfence/wordfence.php, so
       nothing has to be configured. Where several sites carry it, the site is
       chosen in its own window first, the same way the Plugins Installer does.

       Two kinds of work happen here and they are deliberately kept apart:

       1. Reading and writing the plugin's own tables is done directly over
          mysqli. It is fast, it cannot be broken by a plugin's PHP, and it is
          what Wordfence itself does - wfConfig is a key/value table.

       2. Anything that must run Wordfence's *own code* - starting a scan,
          creating a block, revoking 2FA, installing the extended-protection
          bootstrap, exporting diagnostics - is run in a separate PHP process
          that boots WordPress and calls the plugin's classes. Booting a CMS
          inside the manager's own request is how one fatal error in a plugin
          takes the file manager down with it; booting it in a child process
          cannot. The child is a temporary file, runs as the same user, has a
          hard time limit, and prints one JSON object.

       Every setting this window offers is declared in wfcCatalog() with the
       type it has to be validated as. Wordfence stores booleans as '1'/'0',
       and a stray 'true' or 'yes' in a config row is read back as truthy by
       some code paths and false by others, so the write path coerces by type
       rather than storing whatever the browser sent. */

    /* ── the catalogue ─────────────────────────────────────────────────────
       [ name, label, type, group, choices (csv), note ]
       type: bool | int | text | textarea | select | masked
       The labels and the choices are Wordfence's own wording, taken from its
       admin screens and from wfConfig::$defaultConfig, so a setting looks the
       same here as it does there. Settings that exist in the table but are
