        header('Pragma: no-cache');
        header('X-Content-Type-Options: nosniff');
        header('Content-Length: '.strlen($bundle['bytes']));
        echo $bundle['bytes'];exit;
    }
    if($xop==='ssh_login_revoke'){
        if($_SERVER['REQUEST_METHOD']!=='POST'||!hash_equals((string)($_SESSION['csrf_token']??''),(string)($_POST['csrf_token']??''))){http_response_code(403);echo json_encode(['error'=>'Security error.']);exit;}
        if(empty($_SESSION['fm_admin'])){http_response_code(403);echo json_encode(['error'=>'Admins only.']);exit;}
        $result=$fm->sshRevokeLoginKeys($_POST['ssh_user']??'');
        if(!empty($result['error']))http_response_code(400);
        echo json_encode($result,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
    }
    /* ── cPanel Manager endpoints ── */
    if($xop==='cpanel_auto_connect'){
        // Attempt fully-automatic connection - tries CLI, token files, HTTP API.
        // Returns {ok, method, user, api, port} so the JS can act immediately.
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        $ac=$fm->cpanelAutoConnect();
        echo json_encode($ac);exit;
    }
    if($xop==='cpanel_detect'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        $det=$fm->cpanelDetect();
        $c=$_SESSION['cpanel_user']??null;
        $det['has_creds']=(bool)$c;
        $det['saved_user']=$c;
        $det['saved_api']=$_SESSION['cpanel_api_type']??null;
        $det['saved_port']=(int)($_SESSION['cpanel_port']??0);
        $det['method']=$_SESSION['cpanel_method']??null;
        echo json_encode($det);exit;
    }
    if($xop==='cpanel_accounts'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        $fm->cpanelListAccounts();/* exits internally */exit;
    }
    if($xop==='cpanel_plans'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        $fm->cpanelListPlans();/* exits internally */exit;
    }
    if($xop==='sqlscan'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        echo json_encode($fm->sqlScan());exit;
    }
    if($xop==='sqltables'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['error'=>'Security error.']);exit;}
        echo json_encode($fm->sqlListTables());exit;
    }
    if($xop==='sqlbrowse'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['error'=>'Security error.']);exit;}
        echo json_encode($fm->sqlBrowse());exit;
    }
    if($xop==='sqlquery'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['error'=>'Security error.']);exit;}
        echo json_encode($fm->sqlRunQuery());exit;
    }
    if($xop==='sqlexport'){
        if(empty($_SESSION['fm_admin'])){http_response_code(403);header('Content-Type: text/plain');echo 'Admins only.';exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){http_response_code(403);header('Content-Type: text/plain');echo 'Security error.';exit;}
        $fm->sqlExport();exit;
    }
    /* ── File Guardian endpoints (admins only) ── */
    if($xop==='guardian_status'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        $st=fm_guardian_status();$st['update_paused']=fm_guardian_update_paused();
        echo json_encode($st);exit;
    }
    if($xop==='guardian_pause_update'){
        // Deliberately pause the fully-automatic remote update check only -
        // auto-update is ON by default and this is meant to be a short,
        // reversible pause, never a silent permanent disable.
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['error'=>'Security error.']);exit;}
        $pause=!isset($_POST['paused'])||$_POST['paused']!=='0';
        // Persist this setting in the current file's own PHP source, not in a
        // sidecar flag file. The rewrite is atomic and syntax-checked.
        $ok=fm_guardian_rewrite_constant('FM_UPDATE_PAUSED',$pause,true);
        if($fm)$fm->log('guardian_settings','auto-update '.($pause?'paused':'resumed'));
        echo json_encode(['ok'=>$ok,'paused'=>fm_guardian_update_paused()]);exit;
    }
    if($xop==='guardian_ping'){
        /* Lightweight 30s heartbeat fired from the browser while an admin has
           any page of the app open. ONLY updates last_check in the database -
           it never fetches remote URLs or applies updates (that is done only
           when the admin explicitly clicks "Check for updates now"). */
        if(empty($_SESSION['fm_admin'])){echo json_encode(['ok'=>false]);exit;}
        $c=fm_guardian_conn();
        fm_guardian_touch_check($c);
        echo json_encode(['ok'=>true,'applied'=>false]);exit;
    }
    if($xop==='guardian_save'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['error'=>'Security error.']);exit;}
        $newUrl=trim(isset($_POST['update_url'])?$_POST['update_url']:'');
        if($newUrl!==''&&!preg_match('#^https?://#i',$newUrl)){echo json_encode(['error'=>'The update URL must start with http:// or https://']);exit;}
        $ok1=fm_guardian_rewrite_constant('FM_UPDATE_URL',$newUrl);
        if($fm)$fm->log('guardian_settings',"url=".($newUrl?:'(empty)'));
        echo json_encode(['ok'=>$ok1,'reload'=>true]);exit;
    }
    if($xop==='guardian_autocheck'){
        /* Check-only pass fired when an admin opens the manager's main folder.
           It must never silently replace the local file: the yellow notice
           sends the admin to the explicit Guardian action for review/apply. */
        if(empty($_SESSION['fm_admin'])){echo json_encode(['ok'=>false]);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['ok'=>false]);exit;}
        $requestedPath='';
        if(isset($_POST['fm_path_b64'])){$decoded=@base64_decode($_POST['fm_path_b64'],true);if($decoded!==false)$requestedPath=$decoded;}
        $mainPath=realpath(__DIR__);$currentPath=realpath($requestedPath?:$fm->getCwd());
        if(!$mainPath||!$currentPath||$currentPath!==$mainPath){echo json_encode(['ok'=>true,'available'=>false,'skipped'=>'not_main_path']);exit;}
        if(FM_UPDATE_URL===''){echo json_encode(['ok'=>true,'applied'=>false]);exit;}
        /* The check runs even while auto-update is paused: the notice then
           appears for information only, with its install action locked.
           Freshness comes from the state file written by the last real
           fetch (15 minutes): inside that window the answer is computed
           locally from the stored remote hash vs the installed file, so
           page loads stay cheap and offline hosts never hang. (The old
           six-hour throttle read last_check in the Guardian database -
           the very column the 30-second browser heartbeat keeps updating,
           so in practice the check almost never fetched at all.) */
        $paused=fm_guardian_update_paused();
        $statePath=__DIR__.'/.guardian_update_state.php';
        fm_store_migrate($statePath,__DIR__.'/.guardian_update_state.json');
        $state=@json_decode(fm_store_strip_guard((string)@file_get_contents($statePath)),true);
        if(is_array($state)&&($state['url']??'')===FM_UPDATE_URL&&!empty($state['remote_hash'])&&(time()-(int)($state['checked_at']??0))<900){
            $curHash=@hash_file('sha256',__FILE__);
            echo json_encode(['ok'=>true,'available'=>($curHash!==false&&$state['remote_hash']!==$curHash),'paused'=>$paused,'checked'=>false,'cached'=>true,'size'=>(int)($state['size']??0),'release_timestamp'=>(int)($state['release_timestamp']??0),'auto_install_after'=>300,'remote_hash'=>$state['remote_hash']]);exit;
        }
        session_write_close(); // don't hold the session lock across the outbound HTTP call
        $r=fm_guardian_apply_from_url(FM_UPDATE_URL,true);
        fm_guardian_touch_check();
        echo json_encode(['ok'=>!empty($r['ok']),'available'=>!empty($r['available']),'paused'=>$paused,'checked'=>true,'size'=>$r['size']??0,'release_timestamp'=>$r['release_timestamp']??0,'auto_install_after'=>300,'remote_hash'=>$r['remote_hash']??null,'error'=>$r['error']??null]);exit;
    }
    if($xop==='guardian_check_now'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['error'=>'Security error.']);exit;}
        if(FM_UPDATE_URL===''){echo json_encode(['error'=>'No update URL configured yet.']);exit;}
        $logUser=$_SESSION['fm_user']??'';
        // Release the session file lock BEFORE the slow outbound network call: PHP holds an
        // exclusive lock on the session file for the whole request, so without this, every
        // other tab/request/AJAX call from this admin (in fact the whole site, since most
        // requests share this session) queues up and appears to hang/crash for as long as
        // the remote host takes to answer (or fails to, e.g. a slow/blackholed TLS handshake).
        session_write_close();
        $r=fm_guardian_apply_from_url(FM_UPDATE_URL);
        if(!empty($r['ok'])&&!empty($r['changed'])){
            // Re-open the session just long enough to persist the log entry.
            session_start();
            $fm->log('guardian_update','Applied update from '.FM_UPDATE_URL);
            session_write_close();
        }
        echo json_encode($r);exit;
    }
    if($xop==='guardian_sync_now'){
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['error'=>'Security error.']);exit;}
        $ok=fm_guardian_sync();
        if($ok)$fm->log('guardian_sync','Manual sync to database');
        echo json_encode(['ok'=>$ok]);exit;
    }
    if($xop==='guardian_provision'){
        /* One-click fix for "Not reachable": admin pastes a MySQL login that
           already works on this server (their hosting DB root/admin account,
           for example), we use it once to create Guardian's own database +
           low-privilege user + grants, then never touch those admin
           credentials again - they aren't written to disk or the DB. */
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['error'=>'Security error.']);exit;}
        $au=trim($_POST['admin_user']??'');$ap=(string)($_POST['admin_pass']??'');
        if($au===''){echo json_encode(['error'=>'Enter a MySQL admin username first.']);exit;}
        $r=fm_guardian_autoprovision($au,$ap);
        if(!empty($r['ok'])&&$fm)$fm->log('guardian_provision','Auto-provisioned Guardian database/user'.(!empty($r['steps']['grant_autoheal'])?' (+FILE/EVENT)':''));
        echo json_encode($r);exit;
    }
    if($xop==='guardian_autocreate'){
        /* Explicit "create a new database" option: skip trying to reuse this
           site's existing CMS database and go straight to creating a brand
           new, isolated Guardian database via a genuine zero-credential
           local-trust login (OS-user socket, blank-password root, etc.) -
           the same last-resort logic autodiscover falls back to
           automatically, just triggered directly and unconditionally. Also
           arms the disk-level auto-restore-when-deleted EVENT right away. */
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['error'=>'Security error.']);exit;}
        $r=fm_guardian_autoprovision_zero_cred();
        if(!empty($r['ok'])&&$fm)$fm->log('guardian_autocreate','Created a new Guardian database automatically'.(!empty($r['autoheal_active'])?' (+auto-restore)':''));
        echo json_encode($r);exit;
    }
    if($xop==='guardian_autodiscover'){
        /* No-typing fix for "Not reachable": scans this server for a database
           config this SAME site already uses (WordPress/Joomla/generic) and,
           if one connects, adopts it as Guardian's own storage instead of
           requiring a separate admin login. */
        if(empty($_SESSION['fm_admin'])){echo json_encode(['error'=>'Admins only.']);exit;}
        if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){echo json_encode(['error'=>'Security error.']);exit;}
        $r=fm_guardian_autodiscover($fm);
        if(!empty($r['ok'])&&$fm)$fm->log('guardian_autodiscover','Adopted existing site database: '.($r['adopted']['type']??'').'/'.($r['adopted']['db']??''));
        echo json_encode($r);exit;
    }
    echo json_encode(['error'=>'Unknown']);exit;
}

/* ── Embedded audio artwork ── */
function fm_audio_embedded_art($path){
    $fh=@fopen($path,'rb');if(!$fh)return null;
    $sig=fread($fh,4);$art=null;
    if($sig==='fLaC'){
        $scanned=0;
        while(!feof($fh)&&$scanned<16777216){
            $h=fread($fh,4);if(strlen($h)!==4)break;
            $last=(ord($h[0])&0x80)!==0;$kind=ord($h[0])&0x7f;
            $len=(ord($h[1])<<16)|(ord($h[2])<<8)|ord($h[3]);$scanned+=$len+4;
            if($kind===6&&$len>32&&$len<=8388608){
                $b=fread($fh,$len);$p=0;
                $read32=function()use(&$b,&$p){if($p+4>strlen($b))return null;$v=unpack('N',substr($b,$p,4))[1];$p+=4;return $v;};
                $readString=function()use(&$b,&$p,$read32){$n=$read32();if($n===null||$n<0||$n>1048576||$p+$n>strlen($b))return null;$v=substr($b,$p,$n);$p+=$n;return $v;};
                $read32();$mime=$readString();$readString();$read32();$read32();$read32();$read32();$dataLen=$read32();
                if($mime!==null&&$dataLen!==null&&$dataLen>0&&$dataLen<=4194304&&$p+$dataLen<=strlen($b)){
                    $art=['mime'=>preg_match('~^image/(?:jpeg|png|gif|webp|avif)$~i',$mime)?$mime:'image/jpeg','data'=>substr($b,$p,$dataLen)];
                }
                break;
            }
            if($len>0&&fseek($fh,$len,SEEK_CUR)!==0)break;
            if($last)break;
        }
    }elseif($sig==="ID3\3"||$sig==="ID3\4"||$sig==="ID3\2"){
        $head=substr($sig,3,1);$rest=fread($fh,6);
        if(strlen($rest)===6){
            $major=ord($head);$tagSize=(ord($rest[2])<<21)|(ord($rest[3])<<14)|(ord($rest[4])<<7)|ord($rest[5]);
            if($tagSize>0&&$tagSize<=8388608){
                $tag=fread($fh,$tagSize);$p=0;$frameHead=$major===2?6:10;
                while(strlen($tag)-$p>=$frameHead){
                    $id=substr($tag,$p,$major===2?3:4);if($id===''||trim($id,"\0")==='')break;
                    if($major===2){$sz=(ord($tag[$p+3])<<16)|(ord($tag[$p+4])<<8)|ord($tag[$p+5]);}
                    else{$sz=unpack('N',substr($tag,$p+4,4))[1];if($major===4)$sz=(ord($tag[$p+4])<<21)|(ord($tag[$p+5])<<14)|(ord($tag[$p+6])<<7)|ord($tag[$p+7]);}
                    $p+=$frameHead;if($sz<1||$sz>4194304||$p+$sz>strlen($tag))break;
                    $want=$major===2?$id==='PIC':$id==='APIC';
                    if($want){
                        $payload=substr($tag,$p,$sz);$enc=ord($payload[0]);$q=1;
                        if($major===2){$fmt=strtoupper(substr($payload,1,3));$mime=$fmt==='PNG'?'image/png':'image/jpeg';$q=5;}
                        else{$mimeEnd=strpos($payload,"\0",$q);if($mimeEnd===false){$p+=$sz;continue;}$mime=substr($payload,$q,$mimeEnd-$q);$q=$mimeEnd+2;}
                        $term=$enc===1||$enc===2?"\0\0":"\0";
                        if($term==="\0\0"){$descEnd=false;for($j=$q;$j+1<strlen($payload);$j+=2)if($payload[$j]==="\0"&&$payload[$j+1]==="\0"){$descEnd=$j;break;}}
                        else $descEnd=strpos($payload,"\0",$q);
                        if($descEnd!==false){
                            $imgStart=$descEnd+strlen($term);$img=substr($payload,$imgStart);
                            if(strlen($img)>12&&strlen($img)<=4194304&&preg_match('~^image/(?:jpeg|png|gif|webp|avif)$~i',$mime))$art=['mime'=>$mime,'data'=>$img];
                        }
                        if($art)break;
                    }
                    $p+=$sz;
                }
            }
        }
    }
    fclose($fh);return $art;
}
function fm_audio_artwork_map($dir){
    $map=['tracks'=>[],'album'=>'','lyrics'=>[]];$items=@scandir($dir);if(!$items)return$map;
    $imageExt=['jpg','jpeg','png','webp','gif','avif','bmp','tif','tiff'];$albumNames=['cover','folder','album','front','artwork'];
    $audioExt='mp1|mp2|mp3|mpa|mpga|mpeg|wav|wave|rf64|bwf|flac|ogg|oga|opus|spx|aac|adts|m4a|m4b|m4p|alac|aiff|aif|aifc|wma|amr|caf|mid|midi|3gp|ape|ac3|dsf|dff|weba|ra|ram|au|snd|wv|wvc|tta|mpc|mp\+';
    foreach($items as $name){
        if($name==='.'||$name==='..'||$name===''||$name[0]==='.')continue;
        $path=$dir.DIRECTORY_SEPARATOR.$name;$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));
        if(!is_file($path)||is_link($path)||fm_is_manager_internal_path($path))continue;
        if($ext==='lrc'){
            $base=strtolower(pathinfo($name,PATHINFO_FILENAME));$url='?audio_lyrics=1&raw='.urlencode($name).'&dir='.urlencode($dir);
            if(!isset($map['lyrics'][$base]))$map['lyrics'][$base]=$url;
            if(preg_match('/\.('.$audioExt.')$/i',$base)){$short=preg_replace('/\.('.$audioExt.')$/i','',$base);if($short!==''&&!isset($map['lyrics'][$short]))$map['lyrics'][$short]=$url;}
            continue;
        }
        if(!in_array($ext,$imageExt,true))continue;
        $base=strtolower(pathinfo($name,PATHINFO_FILENAME));
        $url='?raw='.urlencode($name).'&dir='.urlencode($dir);
        if(!isset($map['tracks'][$base]))$map['tracks'][$base]=$url;
        if(preg_match('/\.('.$audioExt.')$/i',$base)){$short=preg_replace('/\.('.$audioExt.')$/i','',$base);if($short!==''&&!isset($map['tracks'][$short]))$map['tracks'][$short]=$url;}
        if($map['album']===''&&in_array($base,$albumNames,true))$map['album']=$url;
    }
    return$map;
}
function fm_ini_bytes($value){
    $value=trim((string)$value);if($value===''||$value==='-1')return PHP_INT_MAX;
    if(!preg_match('/^([0-9]+(?:\.[0-9]+)?)\s*([kmgtpe]?)b?$/i',$value,$m))return PHP_INT_MAX;
    $n=(float)$m[1];$unit=strtolower($m[2]??'');$power=[''=>0,'k'=>1,'m'=>2,'g'=>3,'t'=>4,'p'=>5,'e'=>6][$unit]??0;
    return(int)min(PHP_INT_MAX,$n*pow(1024,$power));
}
function fm_upload_chunk_bytes(){
    $maxUpload=fm_ini_bytes(ini_get('upload_max_filesize'));$postLimit=trim((string)ini_get('post_max_size'));$maxPost=$postLimit==='0'?PHP_INT_MAX:fm_ini_bytes($postLimit);
    $usable=min($maxUpload,$maxPost>65536?$maxPost-65536:$maxPost);
    return min(1048576,max(8192,(int)floor($usable*.60)));
}
function fm_audio_tag_text($raw){
    if($raw==='')return'';
    $enc=ord($raw[0]);$text=substr($raw,1);
    if($enc===0&&function_exists('iconv'))$text=@iconv('ISO-8859-1','UTF-8//IGNORE',$text);
    elseif(($enc===1||$enc===2)&&function_exists('iconv'))$text=@iconv($enc===1?'UTF-16':'UTF-16BE','UTF-8//IGNORE',$text);
    elseif($enc===3&&function_exists('iconv'))$text=@iconv('UTF-8','UTF-8//IGNORE',$text);
    if($text===false||$text===null)$text='';
    $text=str_replace("\0",'',$text);
    if(!function_exists('iconv'))$text=preg_replace('/[^\x09\x0A\x0D\x20-\x7E]/','',$text);
    return trim(preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u','',(string)$text)??'');
}
function fm_audio_embedded_tags($path){
    $tags=['title'=>'','artist'=>'','album'=>'','year'=>'','genre'=>''];$fh=@fopen($path,'rb');if(!$fh)return$tags;
    $sig=fread($fh,4);
    if($sig==="ID3\2"||$sig==="ID3\3"||$sig==="ID3\4"){
        $major=ord($sig[3]);$rest=fread($fh,6);
        if(strlen($rest)===6){
            $size=(ord($rest[2])<<21)|(ord($rest[3])<<14)|(ord($rest[4])<<7)|ord($rest[5]);
            if($size>0&&$size<=4194304){
                $data=fread($fh,$size);$p=0;$header=$major===2?6:10;
                while(strlen($data)-$p>=$header){
                    $id=substr($data,$p,$major===2?3:4);if(trim($id,"\0")==='')break;
                    if($major===2)$frameSize=(ord($data[$p+3])<<16)|(ord($data[$p+4])<<8)|ord($data[$p+5]);
                    else{$frameSize=unpack('N',substr($data,$p+4,4))[1];if($major===4)$frameSize=(ord($data[$p+4])<<21)|(ord($data[$p+5])<<14)|(ord($data[$p+6])<<7)|ord($data[$p+7]);}
                    $p+=$header;if($frameSize<1||$frameSize>1048576||$p+$frameSize>strlen($data))break;
                    $fields=$major===2?['TT2'=>'title','TP1'=>'artist','TAL'=>'album','TYE'=>'year','TCO'=>'genre']:['TIT2'=>'title','TPE1'=>'artist','TALB'=>'album','TDRC'=>'year','TYER'=>'year','TCON'=>'genre'];
                    $key=$fields[$id]??'';
                    if($key!==''){
                        $value=fm_audio_tag_text(substr($data,$p,$frameSize));
                        if($key==='year'&&preg_match('/\b\d{4}\b/',$value,$yearMatch))$value=$yearMatch[0];
                        if($value!=='')$tags[$key]=$value;
                    }
                    $p+=$frameSize;
                    if($tags['title']!==''&&$tags['artist']!==''&&$tags['album']!==''&&$tags['year']!==''&&$tags['genre']!=='')break;
                }
            }
        }
    }elseif($sig==='fLaC'){
        $scanned=0;$fieldMap=['title'=>'title','artist'=>'artist','album'=>'album','date'=>'year','year'=>'year','genre'=>'genre'];
        while(!feof($fh)&&$scanned<8388608){
            $h=fread($fh,4);if(strlen($h)!==4)break;
            $last=(ord($h[0])&0x80)!==0;$kind=ord($h[0])&0x7f;$len=(ord($h[1])<<16)|(ord($h[2])<<8)|ord($h[3]);$scanned+=$len+4;
            if($kind===4&&$len>8&&$len<=4194304){
                $b=fread($fh,$len);$pos=0;
                if(strlen($b)<8)break;
                $vendor=unpack('V',substr($b,$pos,4))[1];$pos+=4+$vendor;
                if($pos+4>strlen($b))break;
                $count=unpack('V',substr($b,$pos,4))[1];$pos+=4;
                for($i=0;$i<min($count,2000)&&$pos+4<=strlen($b);$i++){
                    $n=unpack('V',substr($b,$pos,4))[1];$pos+=4;if($n<1||$n>65536||$pos+$n>strlen($b))break;
                    $entry=substr($b,$pos,$n);$pos+=$n;$eq=strpos($entry,'=');if($eq===false)continue;
                    $key=strtolower(substr($entry,0,$eq));
                    $field=$fieldMap[$key]??'';
                    if($field!==''){
                        $value=substr($entry,$eq+1);
                        if(function_exists('iconv'))$value=@iconv('UTF-8','UTF-8//IGNORE',$value);
                        $value=trim(str_replace("\0",'',(string)$value));
                        if($field==='year'&&preg_match('/\b\d{4}\b/',$value,$yearMatch))$value=$yearMatch[0];
                        if($value!==''&&$tags[$field]==='')$tags[$field]=$value;
                    }
                }
                break;
            }
            if($len>0&&fseek($fh,$len,SEEK_CUR)!==0)break;
            if($last)break;
        }
    }
    fclose($fh);return$tags;
}
function fm_audio_supported_extensions(){
    return['mp1','mp2','mp3','mpa','mpga','mpeg','wav','wave','rf64','bwf','flac','ogg','oga','opus','spx','aac','adts','m4a','m4b','m4p','alac','aiff','aif','aifc','wma','amr','caf','mid','midi','3gp','ape','ac3','dsf','dff','weba','ra','ram','au','snd','wv','wvc','tta','mpc','mp+'];
