/* ══ LAYOUT ══ */
.shell{display:grid;grid-template:"tb tb" var(--th) "sb main" 1fr "bar bar" var(--bh) / var(--sw) 1fr;height:100vh;overflow:hidden}

/* ══ TOPBAR ══ */
.topbar{grid-area:tb;background:var(--panel);border-bottom:1px solid var(--border);display:flex;align-items:center;padding:0 10px;gap:6px;z-index:200;min-width:0}
.brand{display:flex;align-items:center;gap:8px;width:var(--sw);flex-shrink:0;text-decoration:none;padding-right:4px;min-width:0}
 .brand-wordmark{font-family:'Michroma',sans-serif;font-weight:400;font-style:normal;font-size:14px;line-height:1;letter-spacing:.035em;color:var(--t1);white-space:nowrap;flex-shrink:0}
.brand:hover .brand-wordmark{color:#fff}
.dv{width:1px;height:18px;background:var(--border);flex-shrink:0}
.bc{display:flex;align-items:center;flex:1;overflow:hidden;min-width:0}
.bc-crumb{display:flex;align-items:center;animation:fadeSlide .3s var(--spring) both}
@keyframes fadeSlide{from{opacity:0;transform:translateX(-6px)}to{opacity:1;transform:none}}
.bc-crumb:nth-child(n+2){animation-delay:.05s}
.bc a{font-family:'JetBrains Mono',monospace;font-size:11px;color:var(--t2);text-decoration:none;padding:3px 6px;border-radius:6px;transition:background .15s,color .15s;white-space:nowrap;max-width:120px;overflow:hidden;text-overflow:ellipsis;display:inline-block}
.bc a:hover{background:var(--hov);color:var(--link)}.bc a.last{color:var(--t1);font-weight:600}
.bc-sep{font-family:'JetBrains Mono',monospace;font-size:11px;color:var(--t3);padding:0 1px;user-select:none}
.tb-right{display:flex;align-items:center;gap:6px;margin-left:auto;flex-shrink:0}
.tb-right .btn{height:32px;justify-content:center}
.tb-right .btn-icon{width:32px;min-width:32px;padding:0}
.tb-right .btn-sm{min-width:32px;padding:0 10px}
.tb-right .btn svg{flex-shrink:0}
.tsearch{height:32px;display:flex;align-items:center;gap:6px;background:var(--field);border:1px solid var(--border);border-radius:var(--r);padding:0 4px 0 10px;transition:border-color .18s}
.tsearch:focus-within{border-color:rgba(133,137,140,.55)}
.tsearch svg{width:13px;height:13px;stroke:var(--t3);fill:none;stroke-width:2;stroke-linecap:round;flex-shrink:0}
.tsearch input{background:transparent;border:none;outline:none;color:var(--t1);font-size:12px;padding:6px 4px;width:150px}
.tsearch input::placeholder{color:var(--t3)}
/* ══ TOP SEARCH ANYTHING ══ */
.topbar{position:relative;background:color-mix(in srgb,var(--panel) 86%,transparent);-webkit-backdrop-filter:blur(14px) saturate(150%);backdrop-filter:blur(14px) saturate(150%)}
.tsearch{transition:border-color .2s ease,background .35s ease,box-shadow .45s cubic-bezier(.22,1,.36,1),border-radius .45s cubic-bezier(.22,1,.36,1),padding .35s ease,gap .35s ease}
.topbar>#menuBtn,.topbar>.dv,.topbar>.bc,.topbar .tb-right>*{transition:opacity .24s ease,transform .32s cubic-bezier(.22,1,.36,1),visibility .24s ease}
.topbar.search-hiding>#menuBtn,.topbar.search-hiding>.dv,.topbar.search-hiding>.bc,.topbar.search-restoring>#menuBtn,.topbar.search-restoring>.dv,.topbar.search-restoring>.bc,.topbar.search-hiding .tb-right>*:not(.top-logout-form),.topbar.search-restoring .tb-right>*:not(.top-logout-form){opacity:0;visibility:hidden;transform:translateY(-4px) scale(.96);pointer-events:none}
.topbar.search-expanded>#menuBtn,.topbar.search-expanded>.dv,.topbar.search-expanded>.bc,.topbar.search-expanded .tb-right>*:not(.top-logout-form){display:none!important}
.topbar.search-expanded .brand{width:auto;flex-basis:auto;padding-right:0;position:relative;z-index:6}
.topbar.search-expanded .tb-right{margin-left:auto;position:relative;z-index:6}
.topbar.search-expanded .tsearch{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(780px,calc(100% - 290px));height:38px;border-radius:14px;padding:0 6px 0 16px;gap:9px;background:linear-gradient(180deg,rgba(255,255,255,.055),rgba(255,255,255,0)),var(--surf);border-color:rgba(148,163,184,.48);box-shadow:0 18px 42px rgba(0,0,0,.32),0 0 0 4px rgba(148,163,184,.09),inset 0 1px 0 rgba(255,255,255,.07);z-index:5}
.topbar.search-expanded .tsearch>svg{width:16px;height:16px;stroke:var(--link)}
.topbar.search-expanded .tsearch input{width:auto;flex:1;font-size:13px;padding:7px 2px}
.tsearch-close{width:26px;height:26px;min-width:26px;display:grid;place-items:center;padding:0;border:0;border-radius:8px;background:var(--hov);color:var(--t2);cursor:pointer;opacity:0;visibility:hidden;transform:scale(.55) rotate(-45deg);transition:opacity .22s ease,transform .3s cubic-bezier(.22,1.35,.36,1),background .15s,color .15s}
.tsearch-close svg{width:13px;height:13px;stroke:currentColor;fill:none;stroke-width:2.2;stroke-linecap:round}
.tsearch-close:hover{background:var(--act);color:var(--t1)}
.topbar.search-expanded .tsearch-close{opacity:1;visibility:visible;transform:none;pointer-events:auto}
.tsearch-panel{position:absolute;top:calc(100% + 10px);left:0;width:100%;max-height:min(64vh,520px);overflow-y:auto;padding:7px;border:1px solid var(--border);border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,.045),rgba(255,255,255,0) 42%),var(--panel);box-shadow:0 30px 70px rgba(0,0,0,.48),0 10px 28px rgba(0,0,0,.28),inset 0 1px 0 rgba(255,255,255,.06);opacity:0;visibility:hidden;transform:translateY(-8px) scale(.985);transform-origin:top center;transition:opacity .24s ease,transform .34s cubic-bezier(.22,1.2,.36,1),visibility .24s;pointer-events:none;z-index:400;text-align:left}
.tsearch-panel.open{opacity:1;visibility:visible;transform:none;pointer-events:auto}
.ts-backdrop{position:fixed;inset:0;z-index:150;background:rgba(6,8,12,.20);-webkit-backdrop-filter:blur(7px) saturate(125%);backdrop-filter:blur(7px) saturate(125%);opacity:0;visibility:hidden;transition:opacity .38s ease,visibility .38s;pointer-events:none}
.ts-backdrop.on{opacity:1;visibility:visible}
:root[data-theme="light"] .ts-backdrop{background:rgba(15,23,42,.10)}
.ts-thumb{width:26px;height:26px;min-width:26px;display:block;border-radius:7px;object-fit:cover;background:rgba(148,163,184,.10)}
.tsearch-panel::-webkit-scrollbar{width:4px}.tsearch-panel::-webkit-scrollbar-thumb{background:rgba(255,255,255,.12);border-radius:99px}
.ts-head{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:6px 8px 4px;font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:.11em;color:var(--t3)}
.ts-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:3px}
.ts-list{display:flex;flex-direction:column;gap:3px}
.ts-item{display:flex;align-items:center;gap:8px;width:100%;padding:5px 8px;border:0;border-radius:8px;background:transparent;color:var(--t1);font:inherit;text-align:left;text-decoration:none;cursor:pointer;transition:background .14s,transform .16s}
.ts-item:hover,.ts-item.active{background:var(--hov)}
.ts-item.active{box-shadow:inset 0 0 0 1px var(--border)}
.ts-ico{width:26px;height:26px;min-width:26px;display:grid;place-items:center;border-radius:7px;background:rgba(148,163,184,.10);color:var(--t2)}
.ts-ico svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.ts-ico.type-folder{color:#fbbf24;background:rgba(251,191,36,.12)}
.ts-ico.type-image{color:#fbbf24;background:rgba(245,158,11,.11)}
.ts-ico.type-code{color:#a5b4fc;background:rgba(129,140,248,.12)}
.ts-ico.type-audio{color:#c4b5fd;background:rgba(167,139,250,.12)}
.ts-ico.type-video{color:#f9a8d4;background:rgba(236,72,153,.11)}
.ts-ico.type-archive{color:#fdba74;background:rgba(249,115,22,.11)}
.ts-main{min-width:0;flex:1;display:flex;flex-direction:column;gap:1px}
.ts-name{font-size:12px;font-weight:650;color:var(--t1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ts-name mark,.ts-sub mark{background:transparent;color:var(--amber);font-weight:850}
.ts-sub{font-size:10.5px;color:var(--t3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ts-kind{flex-shrink:0;padding:2px 6px;border-radius:6px;background:var(--field);border:1px solid var(--border);color:var(--t3);font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.07em}
.ts-more,.ts-hint,.ts-empty{padding:6px 8px 3px;font-size:11px;line-height:1.5;color:var(--t3)}
.ts-loading{display:flex;align-items:center;gap:7px;padding:8px;font-size:11.5px;color:var(--t2)}
.ts-spinner{width:16px;height:16px;min-width:16px;border-radius:50%;border:2px solid rgba(148,163,184,.25);border-top-color:var(--amber);animation:tsSpin .7s linear infinite}
@keyframes tsSpin{to{transform:rotate(360deg)}}
.ts-foot{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:6px;padding:7px 8px;border-top:1px solid var(--border);font-size:10.5px;color:var(--t3)}
.ts-foot kbd{font:600 10px 'Inter',ui-sans-serif,system-ui,sans-serif;padding:2px 5px;border:1px solid var(--border);border-bottom-width:2px;border-radius:5px;background:var(--field);color:var(--t2)}
:root[data-theme="light"] .tsearch-panel{box-shadow:0 30px 70px rgba(15,23,42,.20),0 10px 28px rgba(15,23,42,.12)}
:root[data-theme="light"] .topbar.search-expanded .tsearch{box-shadow:0 18px 42px rgba(15,23,42,.16),0 0 0 4px rgba(100,116,139,.10)}
@media(max-width:900px){.topbar.search-expanded .tsearch{width:calc(100% - 190px)}.ts-grid{grid-template-columns:1fr}}
@media(max-width:720px){.topbar.search-expanded .tsearch{width:calc(100% - 148px);height:38px}.tsearch-panel{border-radius:10px}.ts-kind{display:none}}
@media(prefers-reduced-motion:reduce){.tsearch-panel,.tsearch-close,.topbar>#menuBtn,.topbar>.dv,.topbar>.bc,.topbar .tb-right>*{transition:none}.ts-spinner{animation-duration:1.4s}}

/* ══ SIDEBAR ══ */
.sidebar{grid-area:sb;background:var(--panel);border-right:1px solid var(--border);display:flex;flex-direction:column;overflow:hidden}
.sb-sec{padding:14px 10px 0}
.sb-label{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.9px;color:var(--t3);padding:4px 10px 7px;display:flex;align-items:center;justify-content:space-between}
.sb-nav{display:flex;flex-direction:column;gap:3px}
.sb-item{display:flex;align-items:center;gap:10px;padding:8px 11px;border-radius:var(--r);color:var(--t2);text-decoration:none;font-size:12.5px;font-weight:var(--fw-medium);transition:background .15s,color .15s,transform .18s var(--spring);cursor:pointer;border:none;background:transparent;width:100%;text-align:left;white-space:nowrap;overflow:hidden;min-height:34px}
.sb-item svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0;transition:transform .18s var(--spring)}
.sb-item:hover{background:var(--hov);color:var(--t1);transform:translateX(2px)}.sb-item:hover svg{transform:scale(1.1)}.sb-item:active{transform:scale(.97)}
.sb-item.danger:hover{background:rgba(239,68,68,.08);color:#fca5a5}
.sb-topsec{padding-top:8px}
.sb-topnav{gap:2px}
.sb-topnav .sb-item{min-height:27px;padding:4px 9px;font-size:11.5px;gap:7px;border-radius:8px}
.sb-topnav .sb-item svg{width:14px;height:14px}
.sb-collapsible>summary.sb-label{cursor:pointer;user-select:none;list-style:none;padding:6px 10px;margin:0 -2px;border-radius:8px;transition:background .15s,color .15s}
.sb-collapsible>summary.sb-label:hover{background:var(--hov);color:var(--t2)}
.sb-collapsible>summary.sb-label::-webkit-details-marker{display:none}
.sb-collapsible>summary.sb-label::after{content:'▾';font-size:13px;line-height:1;color:var(--t2);margin-left:6px;transition:transform .18s ease;flex-shrink:0}
.sb-collapsible:not([open])>summary.sb-label::after{transform:rotate(-90deg)}
.sb-gold{padding:6px;border:1px solid rgba(251,191,36,.22);border-radius:12px;background:linear-gradient(180deg,rgba(245,158,11,.10),rgba(245,158,11,.03));box-shadow:inset 0 1px 0 rgba(255,255,255,.045),0 4px 14px rgba(0,0,0,.18)}
.sb-gold .sb-item{color:#f0d98a;font-weight:650;background:rgba(245,158,11,.055);border:1px solid transparent}
.sb-gold .sb-item:hover{color:#fff7e6;background:rgba(245,158,11,.20);border-color:rgba(251,191,36,.38)}
.sb-gold .sb-item svg{stroke:#fcd34d;filter:drop-shadow(0 0 5px rgba(245,158,11,.32))}
.sb-div{height:1px;background:var(--border);margin:10px 10px}
.threats-tab{padding:10px 14px;background:none;border:0;border-bottom:2px solid transparent;color:var(--t3);font-size:12.5px;font-weight:600;cursor:pointer;font-family:inherit;margin-bottom:-1px}
.threats-tab:hover{color:var(--t1)}.threats-tab-active{color:#fca5a5;border-bottom-color:#ef4444}
.threat-row{display:grid;grid-template-columns:minmax(180px,1.2fr) minmax(200px,1.7fr) minmax(78px,.55fr) minmax(165px,1.25fr) minmax(270px,1.7fr);align-items:start;gap:10px;padding:13px 14px;border-bottom:1px solid var(--border)}
.threat-row:hover{background:var(--hov)}.threat-file,.threat-user,.threat-reason,.threat-muted{min-width:0}.threat-name{font-size:12px;font-weight:700;color:var(--t1);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.threat-path{font:10px/1.45 'JetBrains Mono',monospace;color:var(--t3);overflow-wrap:anywhere;margin-top:3px}.threat-reason{font-size:11px;color:#fca5a5;line-height:1.45;overflow-wrap:anywhere}.threat-risk{display:inline-block;margin-top:4px;padding:2px 6px;border-radius:999px;font-size:9.5px;font-weight:800;letter-spacing:.02em}.threat-risk-critical{background:rgba(239,68,68,.2);color:#fecaca}.threat-risk-high{background:rgba(249,115,22,.18);color:#fed7aa}.threat-risk-medium{background:rgba(234,179,8,.16);color:#fef08a}.threat-risk-low{background:rgba(148,163,184,.14);color:#cbd5e1}.threat-muted{font-size:10.5px;color:var(--t3);line-height:1.45}.threat-actions{display:flex;flex-wrap:wrap;align-items:stretch;gap:5px;width:100%;min-width:0}.threat-actions .btn{flex:1 1 82px;min-width:82px;min-height:30px;white-space:normal;overflow:visible;text-overflow:clip;justify-content:center;padding:6px 7px;line-height:1.15;text-align:center}
.threat-user-grid{display:grid;grid-template-columns:minmax(180px,1.2fr) minmax(150px,1fr) minmax(110px,.7fr) minmax(210px,1.4fr) auto;align-items:center;gap:12px;padding:12px 16px;border-bottom:1px solid var(--border)}
.threat-user-grid:hover{background:var(--hov)}.threat-toolbar{padding:12px 16px;background:var(--raised);border-bottom:1px solid var(--border);display:flex;align-items:center;gap:8px;flex-wrap:wrap}.threat-file-toolbar{display:grid;grid-template-columns:minmax(220px,1fr) minmax(320px,1.35fr) auto;align-items:center}.threat-file-info{min-width:0;font-size:11.5px;color:var(--t2);line-height:1.45}.threat-scan-control{display:flex;align-items:center;gap:6px;min-width:0}.threat-scan-control .lbl{margin:0;white-space:nowrap}.threat-scan-control .inp{height:30px;min-width:0;flex:1;font-family:monospace}.threat-file-count{display:flex;align-items:center;gap:6px;white-space:nowrap;font-size:10.5px;color:var(--t3)}.threat-filter-label{font-size:10px;color:var(--t3)}.threat-filter-select{height:30px;min-width:118px;padding:0 8px;font-size:11px}.threat-whitelist-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:12px;padding:13px 16px;border-bottom:1px solid var(--border)}.threat-whitelist-row:hover{background:var(--hov)}.threat-whitelist-status{font-size:10px;color:var(--green);white-space:nowrap}.threat-whitelist-meta{font-size:10.5px;color:var(--t3);white-space:nowrap}
@media(max-width:900px){.threat-file-toolbar{grid-template-columns:1fr}.threat-file-count{justify-self:start}}
@media(max-width:760px){.threat-row,.threat-user-grid{grid-template-columns:1fr;gap:6px}.threat-actions{justify-content:stretch}.threat-row .threat-actions,.threat-user-grid .threat-actions{margin-top:5px}}
.ft tbody tr.threat-focus-hit{background:rgba(133,137,140,.16);outline:2px solid rgba(133,137,140,.6);outline-offset:-2px}
.sb-scroll{flex:1;overflow-y:auto;overflow-x:hidden;padding:0 10px 10px;min-height:0}
.sb-scroll::-webkit-scrollbar{width:3px}.sb-scroll::-webkit-scrollbar-thumb{background:rgba(255,255,255,.07);border-radius:6px}
.sb-flink{display:flex;align-items:center;gap:8px;padding:7px 11px;border-radius:var(--r);color:var(--t2);text-decoration:none;font-size:12.5px;transition:background .15s,color .15s,transform .18s var(--spring);min-height:32px}
.sb-flink svg{width:14px;height:14px;flex-shrink:0;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round}
.sb-flink span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}
.sb-flink:hover{background:var(--hov);color:var(--t1);transform:translateX(2px)}.sb-flink:active{transform:scale(.97)}
.sb-empty{font-size:11.5px;font-weight:var(--fw-muted);color:var(--t3);padding:8px 10px;font-style:italic}
.sb-footer{padding:8px;flex-shrink:0;border-top:1px solid var(--border)}
.disk-w{padding:4px 2px 2px}
.disk-lbl{display:flex;justify-content:space-between;font-size:10px;color:var(--t3);margin-bottom:5px;font-family:'JetBrains Mono',monospace}
.disk-tr{height:5px;background:var(--raised);border-radius:5px;overflow:hidden}
.disk-fi{height:100%;background:linear-gradient(90deg,var(--indigo2),var(--indigo));border-radius:5px;transition:width .4s var(--out)}
.disk-fi.warn{background:linear-gradient(90deg,#d97706,var(--amber))}.disk-fi.crit{background:linear-gradient(90deg,#b91c1c,var(--red))}

/* ══ MAIN ══ */
.main{grid-area:main;display:flex;flex-direction:column;overflow:hidden;min-width:0;position:relative}
.toolbar{padding:10px 12px;border-bottom:1px solid var(--border);background:var(--panel);display:flex;flex-direction:column;flex-wrap:nowrap;gap:8px;align-items:stretch;flex-shrink:0}
.toolbar .tb-row{display:flex;align-items:center;flex-wrap:nowrap!important;gap:8px;width:100%;min-width:0}
.toolbar .tb-row .inp{height:32px;padding-top:0;padding-bottom:0}
.toolbar .tb-row .btn-sm,.toolbar .tb-row .upl-lbl{height:29px;justify-content:center;padding-top:0;padding-bottom:0}
.toolbar .tb-row .btn-sm{flex-shrink:0}
.tb-new{position:relative;flex-shrink:0}
.tb-new-menu{position:absolute;left:0;top:calc(100% + 6px);z-index:80;display:none;flex-direction:column;gap:8px;width:260px;max-width:calc(100vw - 32px);padding:10px;border:1px solid var(--border2);border-radius:12px;background:var(--surf);box-shadow:0 18px 46px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,255,255,.05)}
.tb-new.open .tb-new-menu{display:flex}
.tb-new-menu .tb-new-form{display:flex;align-items:center;gap:6px;width:100%}
.tb-new-menu .inp{flex:1;min-width:0;width:auto!important;height:32px}
.tb-new-menu .btn-sm{flex-shrink:0;height:32px}
.content{flex:1;overflow-y:auto;padding:12px;position:relative}
.content::-webkit-scrollbar{width:4px}.content::-webkit-scrollbar-thumb{background:rgba(255,255,255,.07);border-radius:6px}
.content.drag-over::after{content:'Drop files to upload';position:absolute;inset:8px;border:2px dashed var(--indigo);border-radius:var(--rlg);background:rgba(133,137,140,.07);display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:600;color:var(--link);pointer-events:none;z-index:50}

/* ══ ALERTS ══ */
.alerts{display:flex;flex-direction:column;gap:6px;margin-bottom:10px}
.alert{display:flex;align-items:center;gap:9px;padding:9px 12px;border-radius:var(--r);font-size:13px;border:1px solid transparent;animation:alertIn .3s var(--spring) both}
.guardian-update-card{position:relative;isolation:isolate;overflow:hidden;display:block;margin:0 0 14px;padding:20px 22px;border:1px solid rgba(251,191,36,.48);border-radius:18px;color:#fde68a;background:radial-gradient(560px 190px at 6% -25%,rgba(251,191,36,.30),rgba(251,191,36,0) 62%),radial-gradient(500px 220px at 98% -35%,rgba(249,115,22,.22),rgba(249,115,22,0) 62%),linear-gradient(135deg,rgba(120,72,10,.44),rgba(62,36,8,.34) 48%,rgba(22,17,7,.58));box-shadow:0 18px 42px rgba(0,0,0,.34),0 10px 28px rgba(245,158,11,.14),inset 0 1px 0 rgba(255,255,255,.11),inset 0 0 0 1px rgba(255,255,255,.03);backdrop-filter:blur(14px) saturate(140%);-webkit-backdrop-filter:blur(14px) saturate(140%);animation:guardianUpdateIn .45s cubic-bezier(.22,1.25,.36,1) both}
.guardian-update-card::before{content:"";position:absolute;inset:0 0 auto;height:3px;background:linear-gradient(90deg,rgba(251,191,36,0),#fbbf24 28%,#f97316 55%,#fde68a 78%,rgba(253,230,138,0));opacity:.95}
.guardian-update-card::after{content:"";position:absolute;top:-90px;right:-50px;width:250px;height:250px;border-radius:50%;background:radial-gradient(circle,rgba(251,191,36,.22),rgba(251,191,36,0) 68%);pointer-events:none;z-index:-1}
.guardian-update-card .guardian-update-top{display:flex;align-items:center;gap:16px}
.guardian-update-card .guardian-update-icon{position:relative;width:52px;height:52px;display:grid;place-items:center;flex:0 0 52px;border-radius:16px;background:linear-gradient(145deg,#fde68a,#f59e0b 55%,#ea580c);color:#451a03;box-shadow:0 12px 26px rgba(245,158,11,.35),inset 0 1px 0 rgba(255,255,255,.6),inset 0 -8px 16px rgba(120,53,15,.25);animation:guardianIconFloat 3.2s ease-in-out infinite}
.guardian-update-card .guardian-update-icon::after{content:"";position:absolute;inset:-6px;border:1px solid rgba(251,191,36,.35);border-radius:20px;animation:guardianIconRing 2.6s ease-out infinite;pointer-events:none}
.guardian-update-card .guardian-update-icon svg{width:26px;height:26px;stroke:currentColor;fill:none;stroke-width:2.1;stroke-linecap:round;stroke-linejoin:round}
.guardian-update-card .guardian-update-copy{min-width:0;flex:1}
.guardian-update-card .guardian-update-heading{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-bottom:5px}
.guardian-update-card .guardian-update-title{font-size:17px;font-weight:850;letter-spacing:-.02em;color:#fef3c7;text-shadow:0 2px 14px rgba(245,158,11,.25)}
.guardian-update-card .guardian-update-badge{display:inline-flex;align-items:center;gap:6px;padding:4px 9px;border-radius:999px;background:linear-gradient(135deg,#fde68a,#fbbf24);color:#451a03;font-size:9.5px;font-weight:850;letter-spacing:.11em;text-transform:uppercase;box-shadow:0 6px 16px rgba(245,158,11,.30),inset 0 1px 0 rgba(255,255,255,.65)}
.guardian-update-card .guardian-update-badge-dot{width:6px;height:6px;border-radius:50%;background:#b45309;animation:guardianBadgePulse 1.6s ease-in-out infinite}
.guardian-update-card .guardian-update-text{font-size:12.5px;line-height:1.65;color:rgba(254,243,199,.86);max-width:720px}
.guardian-update-card .guardian-update-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-left:auto}
.guardian-update-card .guardian-update-actions .btn{white-space:nowrap}
.guardian-update-card .guardian-update-install{height:38px;padding:0 17px;border:1px solid rgba(255,255,255,.38);border-radius:999px;background:linear-gradient(135deg,#fde68a,#fbbf24 48%,#f97316);color:#3d1e02;font-size:12.5px;font-weight:800;box-shadow:0 12px 24px rgba(245,158,11,.30),inset 0 1px 0 rgba(255,255,255,.65),inset 0 -7px 14px rgba(146,64,14,.22)}
.guardian-update-card .guardian-update-install svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.guardian-update-card .guardian-update-install:hover{background:linear-gradient(135deg,#fef3c7,#fcd34d 48%,#fb923c);color:#3d1e02;transform:translateY(-1px);box-shadow:0 16px 30px rgba(245,158,11,.38),inset 0 1px 0 rgba(255,255,255,.7),inset 0 -7px 14px rgba(146,64,14,.20)}
.guardian-update-card .guardian-update-install:active{transform:scale(.97)}
.guardian-update-card .alert-x{align-self:center;width:32px;height:32px;min-width:32px;display:grid;place-items:center;padding:0;margin-left:0;border:1px solid rgba(255,255,255,.12);border-radius:50%;background:rgba(255,255,255,.07);color:#fde68a;opacity:.9}
.guardian-update-card .alert-x:hover{background:rgba(255,255,255,.15);opacity:1;transform:rotate(90deg) scale(1.05)}
.guardian-update-card .alert-x svg{width:14px;height:14px}
.guardian-update-details{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:18px 0 0;padding-top:16px;border-top:1px solid rgba(251,191,36,.20)}
.guardian-update-detail{display:flex;align-items:center;gap:10px;min-width:0;padding:11px 12px;border:1px solid rgba(251,191,36,.24);border-radius:13px;background:linear-gradient(145deg,rgba(255,255,255,.075),rgba(0,0,0,.14));box-shadow:inset 0 1px 0 rgba(255,255,255,.06)}
.guardian-update-detail-icon{width:30px;height:30px;min-width:30px;display:grid;place-items:center;border-radius:10px;background:rgba(251,191,36,.15);color:#fcd34d}
.guardian-update-detail-icon svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.guardian-update-detail-label{font-size:9.5px;font-weight:750;text-transform:uppercase;letter-spacing:.09em;color:rgba(254,243,199,.62);margin-bottom:3px}
.guardian-update-detail-value{font-size:12.5px;font-weight:800;color:#ffed9b;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.guardian-update-auto{margin-top:12px;padding:9px 12px;border:1px dashed var(--border);border-radius:10px;background:rgba(148,163,184,.06);font-size:11.5px;line-height:1.5;color:var(--t2)}
.guardian-update-auto:empty{display:none}
.guardian-update-auto b{color:var(--amber);font-variant-numeric:tabular-nums}
.guardian-update-install:disabled{opacity:.5;cursor:not-allowed;filter:grayscale(.35)}
.guardian-update-progress{display:none;margin-top:16px}
.guardian-update-progress.is-active{display:block}
.guardian-update-progress-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:7px;font-size:11px;font-weight:700;color:rgba(254,243,199,.85)}
.guardian-update-progress-head span:last-child{padding:3px 8px;border-radius:999px;background:rgba(251,191,36,.14);border:1px solid rgba(251,191,36,.22)}
.guardian-update-progress-track{height:9px;overflow:hidden;border-radius:999px;background:rgba(0,0,0,.35);border:1px solid rgba(255,255,255,.05);box-shadow:inset 0 1px 3px rgba(0,0,0,.45)}
.guardian-update-progress-bar{position:relative;height:100%;width:8%;overflow:hidden;border-radius:999px;background:linear-gradient(90deg,#f59e0b,#fbbf24,#fde68a);transition:width .35s ease;box-shadow:0 0 16px rgba(251,191,36,.55)}
.guardian-update-progress-bar::after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(135deg,rgba(255,255,255,.28) 0 8px,rgba(255,255,255,0) 8px 16px);transform:translateX(-16px);animation:guardianProgressChunks .8s linear infinite}
@keyframes guardianUpdateIn{from{opacity:0;transform:translateY(-10px) scale(.98);filter:blur(3px)}to{opacity:1;transform:none;filter:blur(0)}}
@keyframes guardianIconFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-2px)}}
@keyframes guardianIconRing{0%{opacity:.85;transform:scale(.96)}70%{opacity:0;transform:scale(1.10)}100%{opacity:0;transform:scale(1.10)}}
@keyframes guardianBadgePulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.45;transform:scale(.72)}}
:root[data-theme="light"] .guardian-update-card{background:radial-gradient(560px 190px at 6% -25%,rgba(251,191,36,.38),rgba(251,191,36,0) 62%),linear-gradient(135deg,#fff7d6,#ffedb5 55%,#fef3c7);color:#92400e;box-shadow:0 18px 38px rgba(146,64,14,.16),inset 0 1px 0 rgba(255,255,255,.8)}
:root[data-theme="light"] .guardian-update-card .guardian-update-title{color:#78350f;text-shadow:none}
