:root[data-theme="light"] .guardian-update-detail-value{color:#7c2d12}
:root[data-theme="light"] .guardian-update-progress-track{background:rgba(120,53,15,.14)}
@media(max-width:720px){.guardian-update-card{padding:18px 16px;border-radius:16px}.guardian-update-card .guardian-update-top{gap:12px}.guardian-update-card .guardian-update-icon{width:46px;height:46px;flex-basis:46px;border-radius:14px}.guardian-update-card .guardian-update-title{font-size:15.5px}.guardian-update-card .guardian-update-actions{width:100%;margin-left:0}.guardian-update-card .guardian-update-install{flex:1;justify-content:center}.guardian-update-details{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.guardian-update-card,.guardian-update-card .guardian-update-icon,.guardian-update-card .guardian-update-badge-dot{animation:none}.guardian-update-card .guardian-update-icon::after{display:none}.guardian-update-progress-bar::after{animation:none}}
@keyframes guardianProgressChunks{to{transform:translateX(0)}}
@media(max-width:720px){.guardian-update-card .guardian-update-top{flex-wrap:wrap}.guardian-update-card .guardian-update-actions{width:100%;margin-left:52px}.guardian-update-details{grid-template-columns:1fr}}
@keyframes alertIn{from{opacity:0;transform:translateY(-8px) scale(.97)}to{opacity:1;transform:none}}
.alert svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;flex-shrink:0}
.alert.success{background:rgba(34,197,94,.07);border-color:rgba(34,197,94,.2);color:#86efac}
.alert.danger{background:rgba(239,68,68,.07);border-color:rgba(239,68,68,.2);color:#fca5a5}
.alert.warning{background:rgba(245,158,11,.07);border-color:rgba(245,158,11,.2);color:#fcd34d}
.alert-x{margin-left:auto;background:none;border:none;cursor:pointer;color:inherit;opacity:.5;padding:2px;border-radius:4px;display:flex;transition:opacity .15s,transform .15s var(--spring)}
.alert-x:hover{opacity:1;transform:scale(1.15)}.alert-x svg{width:13px;height:13px;stroke:currentColor;fill:none;stroke-width:2}

/* ══ FILE TABLE ══ */
.card{background:var(--surf);border:1px solid var(--border);border-radius:var(--rlg);overflow:hidden}
.tw{overflow-x:auto}
.ft{width:100%;border-collapse:collapse}
.ft thead tr{background:var(--raised);border-bottom:1px solid var(--border)}
.ft th{padding:7px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.7px;color:var(--t3);text-align:left;white-space:nowrap;user-select:none}
.ft th a{color:inherit;text-decoration:none;display:inline-flex;align-items:center;gap:3px;transition:color .15s}
.ft th a:hover{color:var(--t2)}.sa a{color:var(--link)!important}.sa .arr{color:var(--link)}
.arr{display:inline-flex;align-items:center;opacity:.5;margin-left:2px}
.arr svg{width:10px;height:10px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.ft tbody tr{border-bottom:1px solid var(--border);transition:background .12s;animation:rIn .25s var(--spring) both}
.ft tbody tr:last-child{border-bottom:none}.ft tbody tr:hover{background:var(--hov)}.ft tbody tr.selected{background:rgba(133,137,140,.09)}
.ft tbody tr:focus{outline:2px solid rgba(133,137,140,.5);outline-offset:-2px}
<?php for($i=1;$i<=60;$i++) echo ".ft tbody tr:nth-child($i){animation-delay:".($i*.018)."s}\n";?>
@keyframes rIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.ft td{padding:6px 10px;vertical-align:middle}
/* ══ GLOBAL INPUTS DARK THEME ══ */
input[type=checkbox],input[type=radio]{
  appearance:none;-webkit-appearance:none;cursor:pointer;
  width:15px;height:15px;
  background:var(--field);
  border:1.5px solid var(--fieldb);
  border-radius:4px;
  display:inline-flex;align-items:center;justify-content:center;
  flex-shrink:0;position:relative;
  transition:background .15s,border-color .15s,box-shadow .15s;
  vertical-align:middle;
}
input[type=radio]{border-radius:50%}
input[type=checkbox]:hover,input[type=radio]:hover{border-color:var(--fieldb-h);background:var(--fieldh)}
input[type=checkbox]:checked,input[type=radio]:checked{background:var(--check);border-color:var(--check-border);box-shadow:0 0 0 3px rgba(125,129,132,.1)}
input[type=checkbox]:checked::after{content:'';position:absolute;left:3px;top:.5px;width:5px;height:8px;border:solid #fff;border-width:0 2px 2px 0;transform:rotate(45deg)}
input[type=radio]:checked::after{content:'';position:absolute;width:6px;height:6px;background:#fff;border-radius:50%;top:50%;left:50%;transform:translate(-50%,-50%)}
input[type=checkbox]:focus,input[type=radio]:focus{outline:none;box-shadow:0 0 0 3px rgba(125,129,132,.16)}
.cc{width:32px}.rck{width:15px;height:15px;cursor:pointer;appearance:none;-webkit-appearance:none;background:var(--field);border:1.5px solid var(--fieldb);border-radius:4px;display:inline-block;position:relative;flex-shrink:0;transition:background .15s,border-color .15s}
.rck:hover{border-color:rgba(160,160,160,.28)}.rck:checked{background:var(--check);border-color:var(--check-border)}
.rck:checked::after{content:'';position:absolute;left:3px;top:.5px;width:5px;height:8px;border:solid #fff;border-width:0 2px 2px 0;transform:rotate(45deg)}
.nc{display:flex;align-items:center;gap:9px;cursor:pointer;min-width:0}
.ib{width:29px;height:29px;flex-shrink:0;border-radius:8px;display:flex;align-items:center;justify-content:center;transition:transform .18s var(--spring)}
.ft tbody tr:hover .ib{transform:scale(1.08)}.ib .ti{width:17px;height:17px}
.nm{min-width:0}
.tag-dot{margin-right:6px;vertical-align:middle}
.nt{color:var(--t1);font-weight:var(--fw-medium);font-size:13px;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:240px;text-decoration:none;transition:color .15s}
a.nt:hover{color:var(--link)}
.eb{display:inline-block;margin-top:1px;font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;padding:1px 5px;border-radius:4px;background:var(--raised);color:var(--t3)}
.mono{font-family:'JetBrains Mono',monospace;font-size:11.5px;color:var(--t2);padding:2px 7px;border-radius:5px;background:var(--raised);white-space:nowrap}
.sz{font-family:'JetBrains Mono',monospace;font-size:11.5px;color:var(--t2);white-space:nowrap}
.mt{font-family:'JetBrains Mono',monospace;font-size:10.5px;color:var(--t3);white-space:nowrap}

/* OWNER column */
.own-cell{display:inline-flex;align-items:center;line-height:1.3;max-width:180px;cursor:pointer;border-radius:6px;padding:2px 5px;transition:background .15s}
.own-cell:hover{background:var(--raised)}
.own-name{display:flex;align-items:center;gap:5px;font-family:'JetBrains Mono',monospace;font-size:11.5px;color:var(--t1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.own-cell.own-mine .own-name{color:#7ee2a8}
.own-me{font-family:inherit;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:#7ee2a8;border:1px solid rgba(126,226,168,.45);border-radius:5px;padding:0 4px;line-height:1.5}
/* owner picker */
.own-target{padding:9px 11px;border:1px solid var(--border);border-radius:8px;background:var(--raised)}
.own-target-name{font-size:13px;font-weight:700;color:var(--t1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.own-target-path{font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--t3);margin-top:2px;word-break:break-all}
.own-target-now{font-size:11.5px;color:var(--t2);margin-top:6px}
.own-list{max-height:232px;overflow:auto;border:1px solid var(--border);border-radius:8px}
.own-row{display:flex;align-items:center;gap:8px;padding:7px 10px;cursor:pointer;border-bottom:1px solid var(--border)}
.own-row:last-child{border-bottom:0}
.own-row:hover{background:var(--raised)}
.own-row.sel{background:rgba(126,226,168,.13);box-shadow:inset 0 0 0 1px rgba(126,226,168,.45)}
.own-row .own-n{font-family:'JetBrains Mono',monospace;font-size:12px;color:var(--t1)}
.own-row .own-h{font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--t3);margin-left:auto;max-width:46%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.own-b{font-size:9px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;padding:1px 5px;border-radius:5px;border:1px solid}
.own-b.mgr{color:#7ee2a8;border-color:rgba(126,226,168,.45)}
.own-b.site{color:#7cc7ff;border-color:rgba(124,199,255,.45)}
.own-b.sys{color:#a1a1aa;border-color:rgba(161,161,170,.32)}
.own-empty{padding:14px;font-size:12px;color:var(--t3);text-align:center}
.own-result{font-size:11.5px;color:var(--t2);min-height:16px;line-height:1.5}
.own-result.bad{color:#fca5a5}
.own-result.good{color:#7ee2a8}
.own-chk{display:flex;align-items:center;gap:7px;font-size:11.5px;color:var(--t2);text-transform:none;letter-spacing:0}

/* ROOTING */
.root-mod{max-width:680px}
.root-body{display:flex;flex-direction:column;gap:12px;max-height:calc(90dvh - 70px);overflow:auto}
.root-sec{border:1px solid var(--border);border-radius:10px;background:var(--surf);padding:10px 12px}
.root-sec h4{margin:0 0 7px;font-size:10.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;color:var(--t3);display:flex;align-items:center;gap:6px}
.root-sec h4 .n{font-weight:600;letter-spacing:0;text-transform:none;color:var(--t3);font-size:10px}
.root-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.root-kv{display:flex;flex-direction:column;gap:1px;padding:5px 8px;border-radius:7px;background:var(--raised)}
.root-kv span:first-child{font-size:9.5px;letter-spacing:.6px;text-transform:uppercase;color:var(--t3)}
.root-kv span:last-child{font-family:'JetBrains Mono',monospace;font-size:11px;color:var(--t1);word-break:break-all}
.root-chips{display:flex;flex-wrap:wrap;gap:6px}
.root-chip{font-size:10.5px;padding:2px 8px;border-radius:20px;border:1px solid;line-height:1.7}
.root-chip.v{color:#fca5a5;border-color:rgba(252,165,165,.55);background:rgba(252,165,165,.1)}
.root-chip.c{color:#fcd34d;border-color:rgba(252,211,77,.5);background:rgba(252,211,77,.08)}
.root-chip.m{color:#7cc7ff;border-color:rgba(124,199,255,.45)}
.root-chip.p{color:#7ee2a8;border-color:rgba(126,226,168,.4)}
.root-chip.a{color:#a1a1aa;border-color:rgba(161,161,170,.32)}
.root-row{border:1px solid var(--border);border-radius:9px;margin-bottom:6px;overflow:hidden;background:var(--raised)}
.root-row:last-child{margin-bottom:0}
.root-head{display:flex;align-items:center;gap:8px;padding:8px 10px;cursor:pointer}
.root-head:hover{background:var(--hov)}
.root-head .nm{font-size:12.5px;font-weight:600;color:var(--t1)}
.root-head .cve{font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--t3)}
.root-head .st{margin-left:auto;font-size:9.5px;font-weight:700;letter-spacing:.5px;text-transform:uppercase;padding:2px 7px;border-radius:20px;border:1px solid}
.root-head .st.v{color:#fca5a5;border-color:rgba(252,165,165,.55)}
.root-head .st.c{color:#fcd34d;border-color:rgba(252,211,77,.5)}
.root-head .st.m{color:#7cc7ff;border-color:rgba(124,199,255,.45)}
.root-head .st.p{color:#7ee2a8;border-color:rgba(126,226,168,.4)}
.root-head .st.a{color:#a1a1aa;border-color:rgba(161,161,170,.32)}
.root-detail{display:none;padding:0 10px 10px;font-size:11.5px;line-height:1.65;color:var(--t2)}
.root-row.open .root-detail{display:block}
.root-detail b{color:var(--t1)}
.root-detail .lab{font-size:9.5px;letter-spacing:.6px;text-transform:uppercase;color:var(--t3);margin:8px 0 2px}
.root-detail ul{margin:3px 0 0 16px;padding:0}
.root-detail li{font-family:'JetBrains Mono',monospace;font-size:10.5px;color:var(--t2)}
.root-acts{display:flex;flex-wrap:wrap;gap:8px;margin-top:9px}
.root-out{font-size:11.5px;line-height:1.6;color:var(--t2);white-space:pre-wrap;word-break:break-word;min-height:16px}
.root-out.good{color:#7ee2a8}
.root-out.bad{color:#fca5a5}
.root-steps{display:flex;flex-direction:column;gap:3px;margin-top:8px}
.root-step{display:flex;gap:8px;align-items:flex-start;font-size:11.5px;padding:3px 0;border-bottom:1px solid var(--border)}
.root-step:last-child{border-bottom:0}
.root-step .t{flex-shrink:0;width:15px;text-align:center;font-weight:700}
.root-step .t svg,.root-item .t svg,.root-adv svg{width:15px;height:15px;display:block}
.root-step.ok .t{color:#7ee2a8}.root-step.bad .t{color:#fca5a5}
.root-step .r{color:var(--t1)}
.root-step .w{color:var(--t3);font-size:10.5px}
.root-banner{border-radius:9px;padding:9px 11px;font-size:12px;line-height:1.6;display:none}
.root-banner.good{display:block;background:rgba(126,226,168,.1);border:1px solid rgba(126,226,168,.45);color:#a7ecc5}
.root-banner.bad{display:block;background:rgba(252,165,165,.09);border:1px solid rgba(252,165,165,.45);color:#fca5a5}
.root-danger{font-size:10.5px;color:#fcd34d;line-height:1.6;margin-top:7px}
 .root-step .tag{display:inline-block;margin-left:6px;padding:1px 5px;border:1px solid rgba(229,177,93,.35);border-radius:4px;color:#e2bc71;font:7.5px 'JetBrains Mono',monospace;letter-spacing:.6px;vertical-align:middle}
 .root-step.meas .r{color:#e5c07b}
 .root-grants .root-item,.root-checks .root-step{justify-content:flex-start}
 .root-grants svg,.root-checks svg{width:15px;height:15px}

/* ── the rooted screen: a Magisk-like front page for the whole machine ──── */
.rr{display:flex;flex-direction:column;gap:12px;animation:rrIn .35s ease both}
@keyframes rrIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.rr-hero{display:flex;gap:16px;align-items:center;padding:16px 18px;border-radius:16px;border:1px solid rgba(52,211,153,.38);background:radial-gradient(120% 140% at 12% 0%,rgba(52,211,153,.16),rgba(52,211,153,.03) 55%,transparent 75%),var(--surf)}
.rr-art{width:126px;height:126px;flex:0 0 126px;filter:drop-shadow(0 6px 18px rgba(52,211,153,.25));animation:rrGlow 4s ease-in-out infinite}
@keyframes rrGlow{0%,100%{filter:drop-shadow(0 6px 18px rgba(52,211,153,.22))}50%{filter:drop-shadow(0 8px 26px rgba(52,211,153,.45))}}
.rr-art svg{width:100%;height:100%;display:block}
.rr-main{min-width:0;display:flex;flex-direction:column;gap:5px}
.rr-kicker{font-size:10px;font-weight:800;letter-spacing:2.4px;color:#7ee2a8}
.rr-title{font-size:20px;font-weight:800;color:var(--t1);line-height:1.15}
.rr-sub{font-size:11.5px;color:var(--t2);line-height:1.55}
.rr-sub b{color:var(--t1);font-weight:700}
.rr-badges{display:flex;flex-wrap:wrap;gap:5px;margin-top:2px}
.rr-badge{display:inline-flex;align-items:center;gap:4px;font-size:10px;font-weight:700;padding:2px 8px;border-radius:999px;border:1px solid rgba(126,226,168,.4);background:rgba(126,226,168,.08);color:#a7f3d0}
.rr-badge.off{border-color:rgba(161,161,170,.3);background:rgba(161,161,170,.07);color:var(--t3)}
.rr-badge svg{width:11px;height:11px}
.rr-acts{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
.rr-sec{border:1px solid var(--border);border-radius:10px;background:var(--surf);padding:10px 12px}
.rr-sec h4{margin:0 0 7px;font-size:10.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;color:var(--t3);display:flex;align-items:center;gap:6px}
.rr-sec h4 .n{font-weight:600;letter-spacing:0;text-transform:none;font-size:10px;color:var(--t3)}
.root-kv-os{grid-column:1 / -1}
.osrow{display:flex;align-items:center;gap:7px;min-width:0;flex-wrap:wrap}
.osico{border-radius:6px;flex:0 0 auto;image-rendering:auto;background:transparent}
.osmain{font-size:12px;color:var(--t1);font-weight:700}
.ossub{font:9.5px/1.4 'JetBrains Mono',monospace;color:var(--t3);word-break:break-word}
.rr-os{display:inline-flex;align-items:center;gap:5px;margin-left:8px;font-size:10px;letter-spacing:.4px;color:var(--t3);font-weight:700}
.rr-ctl{display:grid;grid-template-columns:repeat(auto-fill,minmax(196px,1fr));gap:7px}
.rr-tile{border:1px solid var(--border);border-radius:10px;background:var(--raised);padding:8px 9px;display:flex;flex-direction:column;gap:4px}
.rr-tile.done{border-color:rgba(126,226,168,.45);background:rgba(126,226,168,.05)}
.rr-tile.fail{border-color:rgba(252,165,165,.4);background:rgba(252,165,165,.05)}
.rr-tile-top{display:flex;align-items:center;gap:6px}
.rr-tile-ic{width:26px;height:26px;flex:0 0 26px;border-radius:8px;display:flex;align-items:center;justify-content:center;background:rgba(126,226,168,.12);color:#7ee2a8}
.rr-tile-ic svg{width:15px;height:15px}
.rr-tile-name{font-size:11.5px;font-weight:700;color:var(--t1);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-tile-idea{font-size:10px;color:var(--t3);line-height:1.45}
.rr-tile-cmd{font:9.5px/1.4 'JetBrains Mono',monospace;color:var(--t3);background:rgba(0,0,0,.25);border-radius:5px;padding:3px 5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-tile-out{font:9.5px/1.45 'JetBrains Mono',monospace;color:var(--t2);word-break:break-word;max-height:64px;overflow:auto;white-space:pre-wrap}
.rr-tile .btn{min-height:26px;font-size:10.5px;padding:3px 9px}
.rr-log{display:flex;flex-direction:column;gap:4px;max-height:200px;overflow:auto}
.rr-log-row{display:grid;grid-template-columns:58px 1fr;gap:7px;font-size:10px;padding:4px 6px;border-radius:6px;background:var(--raised);border:1px solid var(--border)}
.rr-log-time{font:9.5px 'JetBrains Mono',monospace;color:var(--t3)}
.rr-log-what{color:var(--t1);font-weight:700}
.rr-log-meta{font:9px/1.4 'JetBrains Mono',monospace;color:var(--t3);word-break:break-word}
.rr-methods{display:flex;flex-direction:column;gap:5px}
.rr-method{display:flex;gap:8px;align-items:flex-start;padding:6px 8px;border-radius:8px;background:var(--raised);border:1px solid var(--border)}
.rr-method.on{border-color:rgba(126,226,168,.45);background:rgba(126,226,168,.06)}
.rr-method.off{opacity:.72}
.rr-method-ic{width:18px;height:18px;flex:0 0 18px;margin-top:1px;color:#7ee2a8}
.rr-method.off .rr-method-ic{color:var(--t3)}
.rr-method-n{font-size:11px;font-weight:700;color:var(--t1)}
.rr-method-i{font-size:10px;color:var(--t3);line-height:1.5}
.rr-method-tag{font-size:9px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;padding:1px 5px;border-radius:4px;background:rgba(161,161,170,.14);color:var(--t3);margin-left:5px}
.rr-method.on .rr-method-tag{background:rgba(126,226,168,.16);color:#a7f3d0}
/* ── the front of the panel: one dial, and nothing else to read ───────────
   The panel used to open on nine sections at once, which hid the one thing a
   person comes here for. Now the first thing on screen is a button and a
   sentence; the measurements are still taken, and "Full report" shows them. */
.rk{display:flex;flex-direction:column;align-items:center;gap:11px;padding:16px 14px 15px;border:1px solid var(--border);border-radius:14px;background:radial-gradient(120% 96% at 50% -10%,rgba(126,226,168,.08),transparent 62%),var(--surf)}
.rk-dial{position:relative;width:184px;height:184px;flex:0 0 auto;border:0;padding:0;background:none;cursor:pointer;-webkit-tap-highlight-color:transparent}
.rk-dial:focus-visible{outline:2px solid #7ee2a8;outline-offset:6px;border-radius:50%}
.rk-ring{position:absolute;inset:0;width:100%;height:100%;transform:rotate(-90deg)}
.rk-track{fill:none;stroke:var(--border);stroke-width:9}
.rk-fill{fill:none;stroke:#7ee2a8;stroke-width:9;stroke-linecap:round;stroke-dasharray:540.35;stroke-dashoffset:540.35;transition:stroke-dashoffset .45s ease,stroke .4s ease}
.rk-spin{position:absolute;inset:11px;border-radius:50%;opacity:0;transition:opacity .3s ease;background:conic-gradient(from 0deg,rgba(126,226,168,0) 0deg,rgba(126,226,168,.9) 54deg,rgba(126,226,168,0) 148deg);-webkit-mask:radial-gradient(circle,transparent 0 61%,#000 62%);mask:radial-gradient(circle,transparent 0 61%,#000 62%)}
.rk.run .rk-spin{opacity:1;animation:rkSpin 1.1s linear infinite}
@keyframes rkSpin{to{transform:rotate(360deg)}}
.rk-face{position:absolute;inset:17px;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;text-align:center;background:radial-gradient(circle at 50% 32%,rgba(126,226,168,.17),rgba(126,226,168,.03) 56%,transparent 74%),var(--raised);border:1px solid var(--border);box-shadow:0 12px 34px rgba(0,0,0,.36),inset 0 1px 0 rgba(255,255,255,.04);transition:border-color .4s ease,box-shadow .4s ease}
.rk.idle .rk-face{animation:rkBreath 3.4s ease-in-out infinite}
@keyframes rkBreath{0%,100%{box-shadow:0 12px 34px rgba(0,0,0,.36),inset 0 1px 0 rgba(255,255,255,.04)}50%{box-shadow:0 12px 40px rgba(52,211,153,.20),inset 0 1px 0 rgba(255,255,255,.05)}}
.rk.ok .rk-face{border-color:rgba(126,226,168,.58);box-shadow:0 12px 38px rgba(52,211,153,.24),inset 0 1px 0 rgba(255,255,255,.05)}
.rk.bad .rk-face{border-color:rgba(252,165,165,.5);box-shadow:0 12px 38px rgba(252,165,165,.16)}
.rk.bad .rk-fill{stroke:#fca5a5}
.rk-glyph{width:34px;height:34px;color:#7ee2a8;display:block}
.rk-glyph svg{width:34px;height:34px;display:block}
.rk-word{font-size:23px;font-weight:800;letter-spacing:3px;color:var(--t1);line-height:1}
.rk.bad .rk-word{font-size:18px;letter-spacing:2px}
.rk-pct{font:600 10.5px/1 'JetBrains Mono',monospace;color:var(--t3);padding:0 8px}
.rk.ok .rk-pct{color:#7ee2a8}
.rk.bad .rk-pct{color:#fca5a5}
.rk-status{font-size:12.5px;color:var(--t2);text-align:center;line-height:1.6;max-width:520px;min-height:19px}
.rk-status b{color:var(--t1);font-weight:700}
.rk-now{display:flex;align-items:center;justify-content:center;gap:5px;min-height:16px;font:11px/1.5 'JetBrains Mono',monospace;color:var(--t3);text-align:center}
.rk.run .rk-now{color:#7ee2a8}
.rk-dot{width:5px;height:5px;border-radius:50%;background:currentColor;animation:rkDot 1s infinite ease-in-out}
.rk-dot:nth-child(2){animation-delay:.15s}
.rk-dot:nth-child(3){animation-delay:.3s}
@keyframes rkDot{0%,80%,100%{opacity:.22;transform:translateY(0)}40%{opacity:1;transform:translateY(-3px)}}
.rk-facts{display:flex;flex-wrap:wrap;gap:6px;justify-content:center}
.rk-steps{width:100%;display:flex;flex-direction:column;gap:3px;margin-top:2px}
.rk-step{display:flex;align-items:flex-start;gap:8px;padding:6px 9px;border-radius:9px;background:var(--raised);border:1px solid var(--border);font-size:11px;color:var(--t3);opacity:.42;transition:opacity .25s ease,border-color .25s ease,background .25s ease,transform .25s ease}
.rk-step .ic{width:15px;height:15px;flex:0 0 15px;display:block;margin-top:1px}
.rk-step .ic svg{width:15px;height:15px;display:block}
.rk-step .nm{color:var(--t1);font-weight:700;font-size:11px}
.rk-step .w{display:block;font-size:10px;color:var(--t3);line-height:1.5;margin-top:1px;word-break:break-word}
.rk-step.now{opacity:1;border-color:rgba(126,226,168,.45);background:rgba(126,226,168,.06);transform:translateX(2px)}
.rk-step.pass{opacity:1;border-color:rgba(126,226,168,.4)}
.rk-step.fail{opacity:.95;border-color:rgba(252,165,165,.3)}
.rk-step.skip{opacity:.55}
.rk-tag{font:8.5px/1 'JetBrains Mono',monospace;letter-spacing:.5px;text-transform:uppercase;padding:2px 5px;border-radius:4px;background:rgba(161,161,170,.14);color:var(--t3);margin-left:6px;white-space:nowrap}
.rk-step.pass .rk-tag{background:rgba(126,226,168,.16);color:#a7f3d0}
.rk-step.fail .rk-tag{background:rgba(252,165,165,.14);color:#fca5a5}
.rk-spin-ic{display:block;width:14px;height:14px;border-radius:50%;border:2px solid rgba(126,226,168,.25);border-top-color:#7ee2a8;animation:rkSpin .8s linear infinite}
.rk-more{display:flex;flex-wrap:wrap;gap:7px;justify-content:center;align-items:center;margin-top:1px}
.rk-more .inp{width:212px}
@media (max-width:520px){.rk-dial{width:158px;height:158px}.rk-face{inset:14px}.rk-word{font-size:20px}}.rooted .root-legacy{display:none}
.rooted.showreport .root-legacy{display:block}
/* the measured sections are read by the tool whether they are shown or
   not; they stay out of the way until they are asked for */
#rootOv:not(.rk-report) .root-sec{display:none}
#rootOv.rk-report .root-sec{display:block}
@media (max-width:520px){
  .rr-hero{flex-direction:column;align-items:flex-start}
  .rr-art{width:104px;height:104px;flex:none}
  .rr-ctl{grid-template-columns:1fr}
}

.root-item{display:flex;gap:8px;align-items:flex-start;font-size:11.5px;color:var(--t2);padding:3px 0;border-bottom:1px solid var(--border)}
.root-item:last-child{border-bottom:0}
.root-item .t{width:15px;flex-shrink:0;text-align:center;font-weight:700}
.root-adv{display:flex;flex-direction:column;gap:5px;margin-top:8px}
.root-adv div{display:flex;gap:7px;font-size:11.5px;color:var(--t2);line-height:1.55}
.root-adv svg{margin-top:2px;flex-shrink:0}
.root-item.ok .t{color:#7ee2a8}.root-item.bad .t{color:#fca5a5}
.root-item .w{color:var(--t3);font-size:10.5px}
.acts{display:flex;gap:3px;justify-content:flex-end}

/* ══ GRID VIEW ══ */
.gv{display:grid;grid-template-columns:repeat(auto-fill,minmax(112px,1fr));gap:6px;padding:2px}
.gi{background:var(--surf);border:1px solid var(--border);border-radius:var(--r);padding:9px 8px 8px;display:flex;flex-direction:column;align-items:center;gap:5px;cursor:pointer;transition:background .15s,border-color .15s,transform .18s var(--spring);position:relative;animation:rIn .25s var(--spring) both}
.gi:hover{background:var(--hov);border-color:var(--border2);transform:translateY(-2px)}.gi:active{transform:scale(.97)}
.gi.selected{border-color:var(--indigo);background:rgba(133,137,140,.07)}
.gi-ic{width:38px;height:38px;border-radius:9px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.gi-ic .ti{width:22px;height:22px}.gi-th{width:38px;height:38px;border-radius:8px;object-fit:cover;display:block}
.gi-n{font-size:11.5px;font-weight:var(--fw-medium);color:var(--t1);text-align:center;word-break:break-word;max-width:100px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.gi-m{font-size:10px;color:var(--t3);font-family:'JetBrains Mono',monospace}
.gi-ck{position:absolute;top:6px;left:6px;opacity:0;transition:opacity .15s}
.gi:hover .gi-ck,.gi.selected .gi-ck{opacity:1}

/* ══ FILTER BAR ══ */
.fm-top-strip{position:relative;display:block;width:100%;margin:0 0 12px;border-radius:12px;overflow:hidden;line-height:0;background:#5b21b6}
.fm-top-strip-link{display:block;border-radius:12px;line-height:0;text-decoration:none}
.fm-top-strip-link img{display:block;width:100%;height:auto;border-radius:12px}
.fm-top-strip-close{position:absolute;top:0;right:0;z-index:2;width:34px;height:34px;margin:0;padding:0;border:0;cursor:pointer;background:rgba(255,255,255,.22);-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);color:#fff;border-radius:0 12px 0 12px;display:flex;align-items:center;justify-content:center;transition:background .18s ease}
.fm-top-strip-close:hover{background:rgba(255,255,255,.38)}
.fm-top-strip-close:focus-visible{outline:2px solid rgba(255,255,255,.85);outline-offset:-2px}
.fm-top-strip-close svg{width:15px;height:15px;stroke:#fff;fill:none;stroke-width:2.4;stroke-linecap:round;pointer-events:none}
.filter-bar{display:flex;align-items:center;gap:5px;padding:0 0 8px;flex-wrap:nowrap;overflow-x:auto;-webkit-overflow-scrolling:touch}
.filter-bar::-webkit-scrollbar{display:none}
.fb-btn{display:inline-flex;align-items:center;gap:4px;padding:4px 10px;border-radius:20px;font-size:11.5px;font-weight:600;border:1px solid var(--border);background:transparent;color:var(--t2);cursor:pointer;white-space:nowrap;transition:all .15s;-webkit-user-select:none;user-select:none}
.fb-btn:hover{background:var(--hov);color:var(--t1);border-color:var(--border2)}.fb-btn.active{background:rgba(133,137,140,.12);color:var(--link);border-color:rgba(133,137,140,.3)}

/* ══ STATUS BAR ══ */
 .bar{grid-area:bar;background:linear-gradient(90deg,var(--indigo2),#606467);display:flex;align-items:center;padding:0 12px;gap:16px;overflow:hidden}
.bs{display:flex;align-items:center;gap:4px;font-size:10.5px;font-family:'JetBrains Mono',monospace;color:rgba(255,255,255,.7);white-space:nowrap}
.bs svg{width:11px;height:11px;stroke:rgba(255,255,255,.8);fill:none;stroke-width:2;stroke-linecap:round}.bs strong{color:#fff;font-weight:700}
.bs-click{cursor:pointer;transition:opacity .15s}.bs-click:hover{opacity:.72;text-decoration:underline}
.br{margin-left:auto;display:flex;gap:16px;align-items:center}

/* ══ BUTTONS ══ */
.btn{display:inline-flex;align-items:center;gap:5px;padding:7px 13px;border-radius:var(--r);font-family:'Inter',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;font-size:12.5px;font-weight:var(--fw-medium);border:none;cursor:pointer;text-decoration:none;white-space:nowrap;line-height:1;transition:background .15s,transform .18s var(--spring),box-shadow .15s;-webkit-user-select:none;user-select:none}
.btn svg{width:13px;height:13px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}.btn:active{transform:scale(.93)!important}
.btn-sm{padding:5px 11px;font-size:12px;border-radius:8px}.btn-sm svg{width:12px;height:12px}
.btn-icon{padding:6px;border-radius:8px}.btn-icon svg{width:14px;height:14px}
.btn-xs{padding:4px 8px;font-size:11.5px;border-radius:7px;gap:3px}.btn-xs svg{width:12px;height:12px}
.btn-del-icon{width:24px;height:24px;min-width:24px;padding:0;display:inline-flex;align-items:center;justify-content:center}
.btn-del-icon svg{width:13px;height:13px}
/* Compact text actions keep the top bar and file toolbar aligned with the
   smaller action buttons used throughout the manager. Icon-only controls
   intentionally keep their 32px touch target. */
.topbar .btn-sm{height:29px;padding:4px 9px;font-size:11.5px;border-radius:7px}
.topbar .btn-sm svg{width:12px;height:12px;stroke-width:2}
.topbar .tb-right .btn-icon{width:29px;min-width:29px;height:29px;padding:5px;border-radius:7px}
.topbar .tb-right .btn-icon svg{width:12px;height:12px}
.toolbar .tb-row .btn-sm,.toolbar .tb-row .upl-lbl{padding-left:9px;padding-right:9px;font-size:11.5px;border-radius:7px}
.toolbar .tb-row .btn-sm svg,.toolbar .tb-row .upl-lbl svg{width:12px;height:12px}
 .btn-p{background:#C9C6C2;color:#101010;box-shadow:0 2px 8px rgba(201,198,194,.13)}.btn-p:hover{background:#E1DDD8;transform:translateY(-1px);box-shadow:0 5px 16px rgba(201,198,194,.2)}
 .btn-g{background:#454744;color:#C9C6C2;border:1px solid #606467}.btn-g:hover{background:#606467;color:#101010;border-color:#C9C6C2;transform:translateY(-1px)}
.btn-green{background:rgba(34,197,94,.1);color:#86efac;border:1px solid rgba(34,197,94,.2)}.btn-green:hover{background:rgba(34,197,94,.17);transform:translateY(-1px)}
.btn-amb{background:rgba(245,158,11,.1);color:#fcd34d;border:1px solid rgba(245,158,11,.2)}.btn-amb:hover{background:rgba(245,158,11,.17);transform:translateY(-1px)}
.btn-red{background:rgba(239,68,68,.1);color:#fca5a5;border:1px solid rgba(239,68,68,.18)}.btn-red:hover{background:rgba(239,68,68,.17);transform:translateY(-1px)}
.btn-blue,.btn-purp{background:rgba(80,81,77,.28);color:#A6A7A6;border:1px solid rgba(112,116,119,.36)}.btn-blue:hover,.btn-purp:hover{background:rgba(112,116,119,.42);color:#D8D4D0;transform:translateY(-1px)}

/* ══ INPUTS ══ */
.inp{background:var(--field);border:1px solid var(--border);color:var(--t1);border-radius:var(--r);padding:7px 11px;font-size:12.5px;font-family:'Inter',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;outline:none;min-width:0;transition:border-color .18s,box-shadow .18s}
.inp::placeholder{color:var(--t3)}
select.inp{color-scheme:dark}
:root[data-theme="light"] select.inp{color-scheme:light}
.inp::placeholder{color:var(--t3)}.inp:focus{border-color:rgba(133,137,140,.6);box-shadow:0 0 0 3px rgba(133,137,140,.16)}
.upl-lbl{display:inline-flex;align-items:center;gap:6px;padding:7px 13px;border-radius:var(--r);font-size:12.5px;font-weight:var(--fw-medium);font-family:'Inter',ui-sans-serif,system-ui,sans-serif;cursor:pointer;white-space:nowrap;border:1.5px dashed rgba(133,137,140,.45);color:var(--t2);background:rgba(133,137,140,.06);transition:border-color .18s,color .18s,background .18s,transform .18s var(--spring)}
.upl-lbl svg{width:13px;height:13px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round}
.upl-lbl:hover{border-color:var(--indigo);color:var(--link);background:rgba(133,137,140,.12);transform:translateY(-1px)}.upl-lbl:active{transform:scale(.97)}
input[type=file]{display:none}

/* ══ OVERLAY / MODAL ══ */
.ov{display:none;position:fixed;inset:0;background:rgba(0,0,0,.75);backdrop-filter:blur(8px);z-index:150;opacity:0;transition:opacity .25s}
.ov.vis{opacity:1}
.mod-ov{display:none;position:fixed;inset:0;z-index:300;background:rgba(0,0,0,.8);backdrop-filter:blur(10px);align-items:center;justify-content:center;padding:20px}
.mod-ov.open{display:flex}
.mod-ov#fileInfoOv{z-index:450}
.mod{background:var(--surf);border:1px solid var(--border2);border-radius:var(--rlg);display:flex;flex-direction:column;overflow:hidden;animation:fadeUp .3s var(--spring) both;max-height:88vh}
.mod-sm{width:min(400px,92vw)}.mod-md{width:min(560px,94vw)}.mod-lg{width:min(760px,95vw)}
.file-info-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.file-info-row{min-width:0;padding:9px 10px;border:1px solid var(--border);border-radius:9px;background:var(--raised)}
.file-info-label{display:block;margin-bottom:4px;color:var(--t3);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.45px}
.file-info-value{color:var(--t1);font-size:12px;line-height:1.45;overflow-wrap:anywhere}
.file-info-open{display:flex;align-items:center;gap:7px;padding:12px 14px;border-top:1px solid var(--border);background:var(--raised);font-size:12px;color:var(--t2)}
.file-info-open a{display:flex;align-items:center;gap:6px;min-width:0;color:var(--link);font-weight:700;overflow-wrap:anywhere}
.file-info-open a[hidden]{display:none}
.file-info-open svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}
@media(max-width:560px){.file-info-grid{grid-template-columns:1fr}.file-info-grid .file-info-row:nth-child(1),.file-info-grid .file-info-row:nth-child(7){grid-column:auto}}
.wa-row{display:flex;flex-direction:column;gap:5px;padding:10px 12px;border:1px solid var(--border);border-radius:9px;background:var(--raised);margin-bottom:8px}
.wa-label{color:var(--t3);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.5px}
.wa-val{display:flex;align-items:center;gap:8px;min-width:0}
.wa-val code{flex:1;min-width:0;color:var(--t1);font:600 12.5px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere;word-break:break-word;user-select:all}
.wa-copy{flex:0 0 auto;padding:5px 10px;border:1px solid var(--border2);border-radius:7px;background:var(--surf);color:var(--t1);font:600 11px/1 'Inter',ui-sans-serif,system-ui,sans-serif;cursor:pointer;transition:background .15s,border-color .15s,color .15s}
.wa-copy:hover{background:var(--hov);border-color:var(--t3)}
.wa-copy.is-copied{color:#34d399;border-color:rgba(52,211,153,.5);background:rgba(52,211,153,.1)}
.wa-note{margin:0 0 10px;color:var(--t3);font-size:11.5px;line-height:1.5}
.wa-actions{display:flex;justify-content:flex-end;margin-top:2px}
.perm-t{border-collapse:collapse;font-size:12.5px}.perm-t th{text-align:center;color:var(--t3);font-weight:600;font-size:10.5px;text-transform:uppercase;letter-spacing:.5px;padding:4px 8px}.perm-t td{text-align:center;padding:6px 8px;color:var(--t2)}.perm-t td:first-child{text-align:left;font-weight:600;color:var(--t1)}.perm-t input[type=checkbox]{width:16px;height:16px;cursor:pointer}
/* <<MFMA-CSS-BEGIN>> */
/* ══ MFM Admin - accounts, permissions, sessions ══════════════════════════ */
.mfa-mod{width:min(1120px,96vw);height:min(780px,90vh);max-height:90vh}
.mfa-wrap{display:flex;min-height:0;flex:1}
.mfa-rail{width:188px;flex-shrink:0;border-right:1px solid var(--border);background:var(--raised);display:flex;flex-direction:column;gap:3px;padding:10px 8px;overflow:auto}
.mfa-tab{display:flex;align-items:center;gap:9px;padding:9px 10px;border-radius:9px;border:1px solid transparent;background:transparent;color:var(--t2);font-size:12.5px;font-weight:600;cursor:pointer;text-align:left;width:100%;transition:background .15s,color .15s}
.mfa-tab svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}
.mfa-tab span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mfa-tab b{margin-left:auto;font-size:10px;background:rgba(133,137,140,.18);padding:1px 6px;border-radius:20px;color:var(--t2);font-weight:700}
.mfa-tab:hover{background:var(--hov);color:var(--t1)}
.mfa-tab.is-on{background:rgba(37,99,235,.14);border-color:rgba(37,99,235,.35);color:#bfdbfe}
.mfa-tab.is-on b{background:rgba(37,99,235,.3);color:#dbeafe}
.mfa-railfoot{margin-top:auto;padding:9px 8px 2px;border-top:1px solid var(--border);font-size:10.5px;color:var(--t3);line-height:1.45}
.mfa-railfoot b{color:var(--t2);font-weight:700}
.mfa-panes{flex:1;min-width:0;overflow:auto;padding:14px;position:relative}
.mfa-pane{display:none}
.mfa-pane.is-on{display:block}
.mfa-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(132px,1fr));gap:9px}
.mfa-card{background:var(--raised);border:1px solid var(--border);border-radius:11px;padding:11px 12px}
.mfa-card .k{font-size:9.5px;letter-spacing:.6px;text-transform:uppercase;color:var(--t3);font-weight:700}
.mfa-card .v{font-size:22px;font-weight:700;color:var(--t1);margin-top:3px;line-height:1.1}
.mfa-card .s{font-size:10.5px;color:var(--t3);margin-top:2px}
.mfa-sec{margin-top:16px}
.mfa-sec>.h{display:flex;align-items:center;gap:8px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.7px;color:var(--t3);margin-bottom:8px}
.mfa-sec>.h .r{margin-left:auto;font-size:10px;letter-spacing:0;text-transform:none;color:var(--t3)}
.mfa-tbl{width:100%;border-collapse:collapse;font-size:12px}
.mfa-tbl th{text-align:left;font-size:9.5px;text-transform:uppercase;letter-spacing:.5px;color:var(--t3);border-bottom:1px solid var(--border);padding:6px 8px;font-weight:700;white-space:nowrap}
.mfa-tbl td{padding:7px 8px;border-bottom:1px solid var(--border);color:var(--t2);vertical-align:middle}
.mfa-tbl tbody tr:hover td{background:var(--hov)}
.mfa-name{display:flex;align-items:center;gap:7px;color:var(--t1);font-weight:600;min-width:0}
.mfa-ava{width:22px;height:22px;border-radius:7px;background:rgba(37,99,235,.16);color:#bfdbfe;display:inline-flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;flex-shrink:0;text-transform:uppercase}
.mfa-ava.g{background:rgba(34,197,94,.16);color:#86efac}
.mfa-chip{display:inline-flex;align-items:center;gap:4px;font-size:10px;padding:1px 7px;border-radius:20px;background:rgba(133,137,140,.15);color:var(--t2);white-space:nowrap;margin-right:3px}
.mfa-chip.adm{background:rgba(37,99,235,.16);color:#bfdbfe}
.mfa-chip.ro{background:rgba(245,158,11,.14);color:#fcd34d}
.mfa-chip.lock{background:rgba(239,68,68,.14);color:#fca5a5}
.mfa-chip.on{background:rgba(34,197,94,.14);color:#86efac}
.mfa-chip.off{background:rgba(133,137,140,.12);color:var(--t3)}
.mfa-dot{width:7px;height:7px;border-radius:50%;display:inline-block;margin-right:5px;vertical-align:middle}
.mfa-dot.a{background:#22c55e}.mfa-dot.i{background:#f59e0b}.mfa-dot.e{background:#71717a}.mfa-dot.x{background:#ef4444}
.mfa-row-acts{display:flex;gap:5px;justify-content:flex-end;flex-wrap:wrap}
.mfa-mini{border:1px solid var(--border2);background:transparent;color:var(--t2);border-radius:7px;padding:3px 7px;font-size:10.5px;font-weight:600;cursor:pointer;white-space:nowrap;transition:background .15s,color .15s}
.mfa-mini:hover{background:var(--hov);color:var(--t1)}
.mfa-mini.p{border-color:rgba(37,99,235,.45);color:#bfdbfe}
.mfa-mini.p:hover{background:rgba(37,99,235,.16)}
.mfa-mini.d{border-color:rgba(239,68,68,.35);color:#fca5a5}
.mfa-mini.d:hover{background:rgba(239,68,68,.12)}
.mfa-mini:disabled{opacity:.45;cursor:not-allowed}
.mfa-tools{display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap}
.mfa-tools .sp{margin-left:auto}
.mfa-in{background:var(--surf);border:1px solid var(--border2);border-radius:8px;color:var(--t1);font-size:12px;padding:6px 9px;font-family:inherit}
.mfa-in:focus{outline:none;border-color:rgba(37,99,235,.5)}
.mfa-lbl{display:block;font-size:9.5px;font-weight:700;text-transform:uppercase;letter-spacing:.55px;color:var(--t3);margin:0 0 4px}
.mfa-fld{margin-bottom:10px}
.mfa-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(238px,1fr));gap:7px}
.mfa-ck{display:flex;gap:8px;align-items:flex-start;padding:7px 9px;border:1px solid var(--border);border-radius:8px;background:var(--raised);cursor:pointer;transition:border-color .15s}
.mfa-ck:hover{border-color:var(--border2)}
.mfa-ck input{margin-top:2px;flex-shrink:0}
.mfa-ck .n{font-size:11.5px;color:var(--t1);font-weight:600;line-height:1.3}
.mfa-ck .t{font-size:10px;color:var(--t3);line-height:1.35;margin-top:1px}
.mfa-drawer{position:absolute;top:0;bottom:0;right:0;width:min(430px,94%);background:var(--surf);border-left:1px solid var(--border2);box-shadow:-18px 0 42px rgba(0,0,0,.55);display:flex;flex-direction:column;transform:translateX(102%);transition:transform .22s ease;z-index:5}
.mfa-drawer.open{transform:none}
.mfa-drawer .dh{display:flex;align-items:center;gap:8px;padding:11px 13px;border-bottom:1px solid var(--border);background:var(--raised);flex-shrink:0}
.mfa-drawer .dh .t{font-size:12.5px;font-weight:700;color:var(--t1);flex:1}
.mfa-drawer .db{overflow:auto;padding:12px 13px;flex:1}
.mfa-drawer .df{padding:10px 13px;border-top:1px solid var(--border);background:var(--raised);display:flex;gap:8px;align-items:center;flex-shrink:0}
.mfa-presets{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px}
.mfa-box{border:1px solid var(--border);border-radius:9px;background:var(--raised);padding:9px 10px;margin-bottom:10px}
.mfa-box .bh{font-size:9.5px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;color:var(--t3);margin-bottom:6px;display:flex;align-items:center;gap:6px}
.mfa-box .bh .sp{margin-left:auto}
.mfa-danger{border-color:rgba(239,68,68,.3)}
.mfa-danger .bh{color:#fca5a5}
.mfa-note{font-size:10.5px;color:var(--t3);line-height:1.5}
.mfa-kv{display:flex;justify-content:space-between;gap:10px;font-size:11.5px;padding:3px 0;color:var(--t2)}
.mfa-kv span:first-child{color:var(--t3)}
.mfa-kv b{color:var(--t1);font-weight:600;text-align:right;overflow-wrap:anywhere}
.mfa-health{display:flex;flex-direction:column;gap:6px}
.mfa-hrow{display:flex;align-items:center;gap:8px;padding:7px 10px;border:1px solid var(--border);border-radius:8px;background:var(--raised);font-size:11.5px;color:var(--t2)}
.mfa-hrow svg{width:14px;height:14px;flex-shrink:0;fill:none;stroke-width:2.1;stroke-linecap:round;stroke-linejoin:round}
.mfa-hrow .n{color:var(--t1);font-weight:600}
.mfa-hrow .sp{margin-left:auto;color:var(--t3);font-size:10.5px;text-align:right}
.mfa-log{display:flex;flex-direction:column;gap:5px}
.mfa-lrow{display:flex;gap:9px;align-items:baseline;padding:6px 9px;border-left:2px solid rgba(37,99,235,.4);background:var(--raised);border-radius:0 7px 7px 0;font-size:11.5px;color:var(--t2)}
.mfa-lrow time{color:var(--t3);font-size:10.5px;white-space:nowrap}
.mfa-lrow b{color:var(--t1)}
.mfa-empty{padding:18px;text-align:center;color:var(--t3);font-size:11.5px;border:1px dashed var(--border);border-radius:9px}
.mfa-msg{font-size:11px;margin:0 0 9px;min-height:14px}
.mfa-msg.good{color:#86efac}.mfa-msg.bad{color:#fca5a5}
@media(max-width:760px){
  .mfa-mod{width:96vw;height:92vh}
  .mfa-wrap{flex-direction:column}
  .mfa-rail{width:auto;flex-direction:row;border-right:0;border-bottom:1px solid var(--border);overflow-x:auto;padding:7px}
  .mfa-tab{width:auto;white-space:nowrap;padding:7px 10px}
  .mfa-tab b{display:none}
  .mfa-railfoot{display:none}
  .mfa-drawer{width:100%}
}
/* the live pill: the window tells the administrator it is asking the server,
   and a click pauses it when the numbers must stay still */
.mfa-live{display:inline-flex;align-items:center;gap:5px;margin-left:10px;padding:3px 9px;border-radius:999px;
  border:1px solid rgba(134,239,172,.26);background:rgba(134,239,172,.07);color:#86efac;
  font:inherit;font-size:10px;letter-spacing:.3px;cursor:pointer;line-height:1.5}
.mfa-live:hover{border-color:rgba(134,239,172,.46)}
.mfa-live i{width:6px;height:6px;border-radius:50%;background:#86efac;animation:mfaPulse 2s infinite}
.mfa-live.off{border-color:rgba(148,163,184,.28);background:rgba(148,163,184,.07);color:#94a3b8}
.mfa-live.off i{background:#94a3b8;animation:none}
@keyframes mfaPulse{0%{box-shadow:0 0 0 0 rgba(134,239,172,.45)}70%{box-shadow:0 0 0 7px rgba(134,239,172,0)}100%{box-shadow:0 0 0 0 rgba(134,239,172,0)}}
/* <<MFMA-CSS-END>> */

/* <<PMA-CSS-BEGIN>> */
/* ══ phpMyAdmin Manager - installations, addresses, sign-in ═══════════════ */
.pma-mod{width:min(1180px,96vw);height:min(820px,92vh);max-height:92vh;min-height:0}
.pma-wrap{display:flex;min-height:0;flex:1;overflow:hidden}
/* the pane shows either the placeholder or the body - never both, whatever
   display the two of them ask for */
.pma-pane>[hidden],#pmaOv [hidden]{display:none!important}
.pma-rail{width:264px;flex-shrink:0;border-right:1px solid var(--border);background:var(--raised);display:flex;flex-direction:column;min-height:0}
.pma-rail-lab{padding:11px 12px 6px;font-size:10px;letter-spacing:.8px;text-transform:uppercase;color:var(--t3);font-weight:700}
.pma-list{overflow:auto;padding:0 8px;display:flex;flex-direction:column;gap:4px;flex:1;min-height:0}
.pma-item{display:flex;align-items:center;gap:9px;padding:8px 9px;border-radius:9px;border:1px solid transparent;background:transparent;color:var(--t2);cursor:pointer;text-align:left;width:100%;font:inherit}
.pma-item:hover{background:var(--hov);color:var(--t1)}
.pma-item.is-on{background:rgba(37,99,235,.14);border-color:rgba(37,99,235,.35);color:#bfdbfe}
.pma-item svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}
.pma-item .t{display:flex;flex-direction:column;gap:1px;min-width:0}
.pma-item .t b{font-size:12px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:186px}
.pma-item .t span{font-size:10px;color:var(--t3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:186px}
.pma-item.is-on .t span{color:#93b4e8}
.pma-add{border-top:1px solid var(--border);padding:10px 12px 12px;display:flex;flex-direction:column;gap:6px}
.pma-add label{font-size:10.5px;color:var(--t3);font-weight:600}
.pma-add input{width:100%;font:inherit;font-size:11.5px;padding:7px 9px;border-radius:8px;border:1px solid var(--border);background:var(--surf);color:var(--t1)}
.pma-add input:focus{outline:none;border-color:rgba(37,99,235,.5)}
.pma-pane{flex:1;min-width:0;min-height:0;overflow:auto;padding:14px;display:flex;flex-direction:column}
.pma-pane>.pma-body{flex:0 0 auto}
.pma-placeholder{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;color:var(--t3);text-align:center;padding:40px 30px}
.pma-placeholder svg{width:38px;height:38px;stroke:currentColor;fill:none;stroke-width:1.4;opacity:.55}
.pma-placeholder b{font-size:13.5px;color:var(--t2)}
.pma-placeholder span{font-size:11.5px;max-width:430px;line-height:1.6}
.pma-body{display:flex;flex-direction:column;gap:12px;min-width:0}
.pma-head{display:flex;flex-direction:column;align-items:stretch;gap:7px}
.pma-name{font-size:15px;font-weight:700;color:var(--t1);overflow-wrap:anywhere}
.pma-sub{font-size:11px;color:var(--t3);margin-top:3px;word-break:break-all}
.pma-chips{display:flex;flex-wrap:wrap;gap:5px;max-width:100%}
.pma-chip{font-size:10px;padding:2.5px 8px;border-radius:20px;border:1px solid var(--border);background:var(--raised);color:var(--t2);white-space:nowrap}
.pma-chip.ok{border-color:rgba(134,239,172,.32);background:rgba(134,239,172,.09);color:#86efac}
.pma-chip.warn{border-color:rgba(252,211,77,.3);background:rgba(252,211,77,.08);color:#fcd34d}
.pma-chip.bad{border-color:rgba(148,163,184,.3);background:rgba(148,163,184,.08);color:#94a3b8}
.pma-chip.acc{border-color:rgba(37,99,235,.4);background:rgba(37,99,235,.13);color:#bfdbfe}
.pma-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,380px);gap:12px;align-items:start}
@media (max-width:1000px){.pma-grid{grid-template-columns:1fr}}
.pma-col{display:flex;flex-direction:column;gap:12px;min-width:0}
.pma-block{border:1px solid var(--border);border-radius:11px;background:var(--surf);padding:11px 12px;min-width:0}
.pma-block-h{display:flex;align-items:center;gap:7px;font-size:11px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:var(--t3);margin-bottom:9px}
.pma-block-h svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.pma-table{width:100%;border-collapse:collapse;font-size:11.5px}
.pma-table th{text-align:left;font-size:10px;letter-spacing:.5px;text-transform:uppercase;color:var(--t3);font-weight:700;padding:5px 6px;border-bottom:1px solid var(--border)}
.pma-table td{padding:6px;border-bottom:1px solid rgba(255,255,255,.045);color:var(--t2);vertical-align:top}
.pma-table tr:last-child td{border-bottom:none}
.pma-table td.path{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10.5px;color:var(--t3);max-width:1px;width:60%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pma-table td{white-space:nowrap}
.pma-table td.path{white-space:nowrap}
.pma-table td b{color:var(--t1);font-weight:650}
.pma-line{display:flex;gap:8px;font-size:11.5px;padding:3px 0;align-items:baseline}
.pma-line .k{color:var(--t3);flex-shrink:0;min-width:96px;max-width:96px}
.pma-line .v{color:var(--t1);overflow-wrap:anywhere;word-break:normal;min-width:0}
.pma-lab{display:block;font-size:10.5px;color:var(--t3);font-weight:600;margin:9px 0 5px}
.pma-row{display:flex;gap:7px;align-items:center}
.pma-row input{flex:1;min-width:0;font:inherit;font-size:11.5px;padding:7px 9px;border-radius:8px;border:1px solid var(--border);background:var(--raised);color:var(--t1)}
.pma-row input:focus{outline:none;border-color:rgba(37,99,235,.5)}
.pma-note{font-size:10.5px;color:var(--t3);line-height:1.55;margin-top:7px}
.pma-answers{display:flex;flex-direction:column;gap:3px;margin-top:8px;max-height:132px;overflow:auto}
.pma-ans{display:flex;gap:7px;font-size:10.5px;color:var(--t3);align-items:center}
.pma-ans .u{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;word-break:break-all;flex:1;min-width:0}
.pma-ans .c{flex-shrink:0;font-weight:700}
.pma-ans.yes .c{color:#86efac}
.pma-ans.yes .u{color:var(--t2)}
.pma-creds{display:flex;flex-direction:column;gap:5px}
.pma-cred{display:flex;gap:8px;align-items:center;padding:6px 8px;border-radius:8px;border:1px solid var(--border);background:var(--raised);cursor:pointer;font-size:11.5px;color:var(--t2)}
.pma-cred:hover{background:var(--hov)}
.pma-cred input{margin:0;flex-shrink:0}
.pma-cred .u{font-weight:650;color:var(--t1)}
.pma-cred .s{font-size:10px;color:var(--t3);margin-left:auto;text-align:right;max-width:200px}
.pma-cred .s.bad{color:#94a3b8}
.pma-cred .s.ok{color:#86efac}
.pma-empty{font-size:11px;color:var(--t3);padding:8px 12px}
.pma-foot{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:8px 0 2px;position:sticky;bottom:-14px;background:var(--surf);z-index:2}
.pma-foot .btn{display:inline-flex;align-items:center;gap:6px}
.pma-foot .btn svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.pma-msg{font-size:11px;color:var(--t3)}
.pma-msg.bad{color:#fca5a5}
.pma-msg.good{color:#86efac}
.pma-result{margin-top:10px;border:1px solid rgba(134,239,172,.28);background:rgba(134,239,172,.06);border-radius:11px;padding:10px 12px}
.pma-result .h{display:flex;align-items:center;gap:7px;font-size:11.5px;font-weight:700;color:#86efac;margin-bottom:7px}
.pma-result .h svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.pma-result .link{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10.5px;color:var(--t1);word-break:break-all;background:var(--raised);border:1px solid var(--border);border-radius:8px;padding:7px 9px}
.pma-result .acts{display:flex;gap:7px;margin-top:8px;align-items:center}
.pma-result .txt{font-size:10.5px;color:var(--t3);margin-top:7px;line-height:1.55}
.pma-live{font-size:10px;padding:2px 8px;border-radius:20px;border:1px solid var(--border);color:var(--t3);background:var(--raised);margin-left:9px}

/* <<PMA-CSS-END>> */
/* <<CPM-CSS-BEGIN>> */
/* ══ cPanel Manager - the accounts of a cPanel server, opened as any of them ══
   The window is built out of the same pieces as phpMyAdmin Manager (.pma-*),
   so the two read as one family; only the few things that are particular to
   cPanel accounts are new here. */
.cpm-mod{width:min(1240px,97vw);height:min(860px,94vh);max-height:94vh;min-height:0}
.cpm-rail{width:288px}
.cpm-list .pma-item .t b{max-width:200px}
.cpm-list .pma-item .t span{max-width:200px}
.cpm-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0;background:#86efac}
.cpm-dot.off{background:#94a3b8}
.cpm-search{width:100%;font:inherit;font-size:11.5px;padding:7px 9px;border-radius:8px;border:1px solid var(--border);background:var(--surf);color:var(--t1)}
.cpm-search:focus{outline:none;border-color:rgba(37,99,235,.5)}
.cpm-sec{border:1px solid var(--border);border-radius:11px;background:var(--surf);padding:11px 12px;min-width:0}
.cpm-sec-h{display:flex;align-items:center;gap:7px;font-size:11px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:var(--t3);margin-bottom:9px}
.cpm-sec-h svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.cpm-sec-h .r{margin-left:auto;font-size:10px;font-weight:600;text-transform:none;letter-spacing:0;color:var(--t3)}
.cpm-open{display:flex;gap:7px;flex-wrap:wrap}
.cpm-open .btn{display:inline-flex;align-items:center;gap:6px}
.cpm-open .btn svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.cpm-open .btn[disabled]{opacity:.5;cursor:not-allowed}
.cpm-sso{margin-top:10px;border:1px solid rgba(134,239,172,.28);background:rgba(134,239,172,.06);border-radius:11px;padding:10px 12px}
.cpm-sso.hide{display:none}
.cpm-sso .h{display:flex;align-items:center;gap:7px;font-size:11.5px;font-weight:700;color:#86efac;margin-bottom:7px}
.cpm-sso .h svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.cpm-sso .link{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10.5px;color:var(--t1);word-break:break-all;background:var(--raised);border:1px solid var(--border);border-radius:8px;padding:7px 9px}
.cpm-sso .acts{display:flex;gap:7px;margin-top:8px;align-items:center;flex-wrap:wrap}
.cpm-sso .txt{font-size:10.5px;color:var(--t3);margin-top:7px;line-height:1.55}
.cpm-bar{height:6px;border-radius:6px;background:var(--raised);border:1px solid var(--border);overflow:hidden;margin:6px 0 3px}
.cpm-bar i{display:block;height:100%;background:linear-gradient(90deg,#3b82f6,#60a5fa)}
.cpm-bar.warn i{background:linear-gradient(90deg,#f59e0b,#fbbf24)}
.cpm-bar.bad i{background:linear-gradient(90deg,#dc2626,#f87171)}
.cpm-kv{display:grid;grid-template-columns:104px minmax(0,1fr);gap:3px 8px;font-size:11.5px}
.cpm-kv .k{color:var(--t3)}
.cpm-kv .v{color:var(--t1);overflow-wrap:anywhere;min-width:0}
.cpm-kv .v.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10.5px;color:var(--t2)}
.cpm-pill{font-size:10px;padding:2px 8px;border-radius:20px;border:1px solid var(--border);background:var(--raised);color:var(--t2);white-space:nowrap}
.cpm-pill.ok{border-color:rgba(134,239,172,.32);background:rgba(134,239,172,.09);color:#86efac}
.cpm-pill.warn{border-color:rgba(252,211,77,.3);background:rgba(252,211,77,.08);color:#fcd34d}
.cpm-pill.acc{border-color:rgba(37,99,235,.4);background:rgba(37,99,235,.13);color:#bfdbfe}
.cpm-inp,.cpm-sel{width:100%;font:inherit;font-size:11.5px;padding:7px 9px;border-radius:8px;border:1px solid var(--border);background:var(--raised);color:var(--t1);box-sizing:border-box}
.cpm-inp:focus,.cpm-sel:focus{outline:none;border-color:rgba(37,99,235,.5)}
.cpm-lab{display:block;font-size:10.5px;color:var(--t3);font-weight:600;margin:8px 0 4px}
.cpm-row{display:flex;gap:7px;align-items:center;flex-wrap:wrap}
.cpm-msg{font-size:11px;color:var(--t3);margin-top:8px;line-height:1.55;min-height:14px}
.cpm-msg.bad{color:#fca5a5}
.cpm-msg.good{color:#86efac}
.cpm-danger{border-color:rgba(248,113,113,.35)!important;color:#fca5a5!important}
.cpm-mark{display:flex;gap:8px;align-items:center;font-size:11px;padding:3px 0;color:var(--t3)}
.cpm-mark .p{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10.5px;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cpm-mark .s{flex-shrink:0;font-weight:700;width:14px;text-align:center}
.cpm-mark.yes .s{color:#86efac}
.cpm-mark.yes .p{color:var(--t2)}
.cpm-mark.no .s{color:#94a3b8}
.cpm-reasons{display:flex;flex-direction:column;gap:3px;margin-top:8px;font-size:10.5px;color:var(--t3)}
.cpm-reasons .r{display:flex;gap:6px;align-items:baseline}
.cpm-reasons .r:before{content:"·";color:#94a3b8}
.cpm-create{display:none}
.cpm-create.on{display:block}
@media (max-width:900px){
  .cpm-mod{width:97vw;height:94vh}
  .pma-wrap{flex-direction:column}
  .cpm-rail{width:auto;border-right:none;border-bottom:1px solid var(--border);max-height:210px}
  .cpm-list{padding-bottom:6px}
}
/* <<CPM-CSS-END>> */


@keyframes fadeUp{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes toastIn{from{opacity:0;transform:translate(-50%,14px)}to{opacity:1;transform:translate(-50%,0)}}
.mod-head{display:flex;align-items:center;gap:9px;padding:10px 14px;border-bottom:1px solid var(--border);background:var(--raised);flex-shrink:0}
.mod-icon{width:24px;height:24px;border-radius:7px;display:flex;align-items:center;justify-content:center;background:rgba(133,137,140,.15);flex-shrink:0}
.mod-icon svg{width:13px;height:13px;stroke:var(--link);fill:none;stroke-width:2;stroke-linecap:round}
.mod-title{font-size:13px;font-weight:700;color:var(--t1);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mod-body{overflow:auto;flex:1;padding:13px}
.mod-body::-webkit-scrollbar{width:4px}.mod-body::-webkit-scrollbar-thumb{background:rgba(255,255,255,.08);border-radius:6px}
.cms-install-section{padding:12px;margin-bottom:10px;border:1px solid var(--b2);border-radius:10px;background:var(--raised)}
.cms-install-section-title{margin-bottom:8px;color:var(--t1);font-size:12px;font-weight:700}
.cms-installer-spin{animation:cmsInstallerSpin .9s linear infinite}
@keyframes cmsInstallerSpin{to{transform:rotate(360deg)}}
.cms-install-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 12px}
.cms-install-advanced{margin-top:10px;padding-top:8px;border-top:1px solid var(--b2)}
.cms-install-advanced summary{color:var(--t2);font-size:11px;cursor:pointer;user-select:none}
.cms-install-advanced[open] summary{margin-bottom:7px}
.cms-install-badges{display:flex;flex-wrap:wrap;gap:5px;margin-top:7px}
@media(max-width:600px){.cms-install-grid{grid-template-columns:1fr}}
.rc-mod{width:min(1080px,96vw);height:min(760px,calc(100vh - 40px));max-height:calc(100vh - 40px);min-height:0}
.rc-body{display:flex;flex-direction:column;gap:10px;min-height:0;overflow:hidden}
.rc-manager{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid rgba(139,92,246,.38);border-radius:9px;background:rgba(139,92,246,.08);cursor:pointer;flex:0 0 auto}
.rc-manager input,.rc-file-check{width:16px;height:16px;accent-color:#8b5cf6;flex:0 0 auto}
.rc-manager-copy{display:flex;flex-direction:column;gap:2px;min-width:0;flex:1}
.rc-manager-copy strong{font-size:12px;color:var(--t1)}
.rc-manager-copy small{font-size:10.5px;color:var(--t2);line-height:1.4}
.rc-badge{display:inline-flex;align-items:center;border-radius:999px;padding:3px 7px;font-size:9.5px;font-weight:700;white-space:nowrap;background:rgba(125,129,132,.14);color:var(--t2)}
.rc-badge.active{background:rgba(34,197,94,.12);color:#86efac}
.rc-badge.warn{background:rgba(245,158,11,.12);color:#fbbf24}
.rc-layout{display:grid;grid-template-columns:minmax(280px,.95fr) minmax(310px,1.05fr);gap:12px;flex:1;min-height:0;overflow:hidden}
.rc-pane{min-width:0;min-height:0;border:1px solid var(--border);border-radius:9px;background:var(--panel);display:flex;flex-direction:column;overflow:hidden}
.rc-pane-head{display:flex;align-items:center;gap:6px;padding:8px;border-bottom:1px solid var(--border);background:var(--raised);min-width:0}
.rc-path{font:10px/1.4 'JetBrains Mono',monospace;color:var(--t2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}
.rc-select-tools{display:flex;align-items:center;gap:8px;padding:7px 9px;border-bottom:1px solid var(--border);font-size:10.5px;color:var(--t3)}
.rc-select-tools button{padding:0;border:0;background:none;color:var(--link);font:inherit;cursor:pointer}
.rc-items{overflow:auto;min-height:150px;flex:1}
.rc-row{display:flex;align-items:center;gap:8px;width:100%;padding:8px 10px;border:0;border-bottom:1px solid var(--border);background:transparent;color:var(--t1);text-align:left;font-family:inherit}
.rc-row:hover{background:var(--hov)}
button.rc-row{cursor:pointer}
.rc-row-name{min-width:0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:11px 'JetBrains Mono',monospace}
.rc-row-meta{display:flex;align-items:center;gap:5px;flex:0 0 auto}
.rc-settings{padding:12px;gap:9px;overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain}
.rc-field{display:flex;flex-direction:column;gap:5px}
.rc-field[hidden]{display:none}
.rc-field label{font-size:10.5px;font-weight:700;color:var(--t2)}
.rc-field .inp{width:100%;min-width:0}
.rc-field textarea.inp{min-height:92px;resize:vertical;font:11px/1.5 'JetBrains Mono',monospace}
.rc-hint{font-size:10px;line-height:1.45;color:var(--t3)}
.rc-detected-ip{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:8px;font-size:11px;color:var(--t2)}
.rc-detected-ip code{color:var(--t1);font-family:ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}
.rc-warning{padding:9px 10px;border:1px solid rgba(245,158,11,.3);border-radius:8px;background:rgba(245,158,11,.07);font-size:10.5px;line-height:1.45;color:#fbbf24}
.rc-message{font-size:10.5px;line-height:1.45;color:var(--t2);min-height:16px;white-space:pre-wrap}
.rc-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:auto;padding:9px 0 max(4px,env(safe-area-inset-bottom));position:sticky;bottom:0;z-index:2;background:var(--panel);border-top:1px solid var(--border)}
.rc-actions .btn{flex:1}
@supports (height: 100dvh){.rc-mod{height:min(760px,calc(100dvh - 40px));max-height:calc(100dvh - 40px)}}
@media(max-width:760px){
  #responseChangerOv{padding:max(8px,env(safe-area-inset-top)) max(8px,env(safe-area-inset-right)) max(8px,env(safe-area-inset-bottom)) max(8px,env(safe-area-inset-left))}
  .rc-mod{width:100%;height:calc(100vh - 16px);max-height:calc(100vh - 16px);border-radius:12px}
  @supports (height: 100dvh){#responseChangerOv .rc-mod{height:calc(100dvh - max(16px,env(safe-area-inset-top) + env(safe-area-inset-bottom)));max-height:calc(100dvh - max(16px,env(safe-area-inset-top) + env(safe-area-inset-bottom)))}}
  .rc-body{gap:8px;padding:10px}
  .rc-layout{grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(0,.82fr) minmax(0,1.18fr);gap:8px}
  .rc-pane{min-height:0}
  .rc-items{max-height:none;min-height:0}
  .rc-settings{min-height:0;max-height:none;padding:10px;gap:8px}
  .rc-actions{margin:0 -10px -10px;padding:9px 10px max(9px,env(safe-area-inset-bottom))}
}
.server-log-item{display:block;width:100%;padding:10px 12px;text-align:left;border:0;border-bottom:1px solid var(--border);background:transparent;color:var(--t1);cursor:pointer;font-family:inherit;transition:background .15s,border-color .15s}
.server-log-item:hover{background:var(--hov)}.server-log-item.active{background:rgba(133,137,140,.13);box-shadow:inset 3px 0 var(--link)}
.server-log-item strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;font-weight:650}
.server-log-item span{display:block;margin-top:4px;color:var(--t3);font-family:'JetBrains Mono',monospace;font-size:9.5px;line-height:1.45;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* ══ PREVIEW ══ */
.prev-ov{display:none;position:fixed;inset:0;z-index:300;background:rgba(0,0,0,.85);backdrop-filter:blur(10px);align-items:center;justify-content:center;padding:20px}
.prev-ov.open{display:flex}
.prev-box{background:var(--surf);border:1px solid var(--border2);border-radius:var(--rlg);max-width:min(920px,94vw);max-height:92vh;display:flex;flex-direction:column;overflow:hidden;animation:fadeUp .3s var(--spring) both}
.prev-head{display:flex;align-items:center;gap:10px;padding:11px 14px;border-bottom:1px solid var(--border);background:var(--raised)}
.prev-head span{font-size:13px;font-weight:600;color:var(--t1);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.prev-body{overflow:auto;display:flex;align-items:center;justify-content:center;background:#000;min-height:200px}
.prev-body img{max-width:100%;max-height:80vh;display:block}
.prev-body video{max-width:100%;max-height:80vh}
.prev-body iframe{width:min(870px,90vw);height:77vh;border:none;background:#fff}
.prev-body pre{width:min(870px,90vw);max-height:77vh;overflow:auto;padding:18px;font-family:'JetBrains Mono',monospace;font-size:12.5px;color:#cdd6f4;background:#07090e;text-align:left;white-space:pre-wrap;word-break:break-word}
.prev-body .md-render{width:min(870px,90vw);max-height:77vh;overflow:auto;padding:24px 28px;background:var(--panel);color:var(--t1);text-align:left;border-radius:8px;line-height:1.6;font-size:14px}
.prev-body .md-render h1,.prev-body .md-render h2,.prev-body .md-render h3,.prev-body .md-render h4{margin:18px 0 8px;font-weight:700;color:var(--t1)}
.prev-body .md-render h1{font-size:24px;border-bottom:1px solid var(--border);padding-bottom:6px}
.prev-body .md-render h2{font-size:19px;border-bottom:1px solid var(--border);padding-bottom:5px}
.prev-body .md-render p{margin:8px 0}
.prev-body .md-render code{background:var(--raised);padding:2px 5px;border-radius:4px;font-family:'JetBrains Mono',monospace;font-size:12.5px}
.prev-body .md-render pre{background:#07090e;padding:14px;border-radius:8px;overflow:auto;width:auto;max-height:none}
.prev-body .md-render pre code{background:none;padding:0}
.prev-body .md-render blockquote{border-left:3px solid var(--indigo);margin:10px 0;padding:2px 14px;color:var(--t2)}
.prev-body .md-render ul,.prev-body .md-render ol{margin:8px 0 8px 22px}
.prev-body .md-render a{color:var(--link)}
.prev-body .md-render hr{border:none;border-top:1px solid var(--border);margin:16px 0}
.prev-body .md-render img{max-width:100%;border-radius:6px}

/* ══ CONTEXT MENU (desktop right-click) ══ */
.ctx{display:none;position:fixed;z-index:500;background:var(--raised);border:1px solid var(--border2);border-radius:var(--rlg);padding:5px;min-width:180px;box-shadow:0 20px 60px rgba(0,0,0,.7),0 4px 16px rgba(0,0,0,.4);animation:ctxIn .18s var(--spring) both}
.ctx.open{display:block}
@keyframes ctxIn{from{opacity:0;transform:scale(.93)}to{opacity:1;transform:none}}
.ctx-item{display:flex;align-items:center;gap:9px;padding:8px 12px;border-radius:8px;color:var(--t2);font-size:12.5px;font-weight:500;cursor:pointer;transition:background .12s,color .12s;white-space:nowrap;user-select:none}
.ctx-item svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;flex-shrink:0}
.ctx-item:hover{background:var(--hov);color:var(--t1)}.ctx-item.danger:hover{background:rgba(239,68,68,.1);color:#fca5a5}.ctx-item.ctx-disabled{opacity:.4;pointer-events:none}
.ctx-sep{height:1px;background:var(--border);margin:4px 0}
.ctx-header{padding:6px 12px 4px;font-size:10.5px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.6px;display:flex;align-items:center;gap:7px;overflow:hidden;max-width:220px}
.ctx-header span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* ══ MOBILE BOTTOM SHEET ══ */
.sheet-ov{display:none;position:fixed;inset:0;z-index:400;background:rgba(0,0,0,.7);backdrop-filter:blur(8px)}
.sheet-ov.open{display:block}
.sheet{position:fixed;bottom:0;left:0;right:0;background:var(--panel);border-top:1px solid var(--border2);border-radius:20px 20px 0 0;padding:0 0 max(env(safe-area-inset-bottom),16px);z-index:401;transform:translateY(100%);transition:transform .35s var(--spring);max-height:85dvh;overflow-y:auto}
.sheet.open{transform:translateY(0)}
.sheet-handle{width:36px;height:4px;background:rgba(255,255,255,.15);border-radius:4px;margin:12px auto 16px}
.sheet-info{padding:0 16px 14px;border-bottom:1px solid var(--border)}
.sheet-name{font-size:14px;font-weight:700;color:var(--t1);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sheet-meta{font-size:11.5px;color:var(--t2);margin-top:3px;font-family:'JetBrains Mono',monospace}
.sheet-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:12px 12px 0}
.sh-btn{display:flex;flex-direction:column;align-items:center;gap:8px;padding:14px 10px;background:var(--raised);border:1px solid var(--border);border-radius:var(--rlg);cursor:pointer;font-size:12.5px;font-weight:600;color:var(--t2);transition:background .15s,color .15s,transform .18s var(--spring);-webkit-user-select:none;user-select:none}
.sh-btn svg{width:22px;height:22px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round}
.sh-btn:active{transform:scale(.95)}
.sh-btn:hover{background:var(--hov);color:var(--t1)}.sh-btn.sh-red:hover{background:rgba(239,68,68,.08);color:#fca5a5;border-color:rgba(239,68,68,.2)}
.sh-btn.sh-blue:hover{background:rgba(59,130,246,.08);color:#93c5fd;border-color:rgba(59,130,246,.2)}
.sh-btn.sh-green:hover{background:rgba(34,197,94,.08);color:#86efac;border-color:rgba(34,197,94,.2)}
.sh-btn.sh-amb:hover{background:rgba(245,158,11,.08);color:#fcd34d;border-color:rgba(245,158,11,.2)}
.sh-btn.sh-purp:hover{background:rgba(139,92,246,.08);color:#c4b5fd;border-color:rgba(139,92,246,.2)}

/* ══ TERMINAL (the supplied DNT Shell layout, full-screen and borderless) ══ */
.term-ov{padding:0;background:#1c1c1c;backdrop-filter:none;align-items:stretch;justify-content:stretch}
.term-ov.open{display:block}
.term-win{position:fixed;inset:0;width:100vw;height:100dvh;background:#1c1c1c;color:#b3b3b3;border:0;border-radius:0;box-shadow:none;overflow-y:auto;overflow-x:hidden;display:block;padding-bottom:35px;box-sizing:border-box;font-family:monospace;font-size:0;line-height:0}
.term-out{display:block;overflow:visible;padding:8px 0 0;font-family:monospace;font-size:0;line-height:0;color:#b3b3b3;background:#1c1c1c;white-space:pre-wrap;word-break:break-word}
.term-out::-webkit-scrollbar{width:5px}.term-out::-webkit-scrollbar-thumb{background:#4a4a4a;border-radius:4px}
.term-line{display:block;font-size:14px;line-height:1.25;min-height:0;margin:0 0 0 2px;white-space:pre-wrap;word-break:break-word}
.term-line.cmd-line{color:#7db8ba}
.term-line.ok-line{color:#b3b3b3}
.term-line.err-line{color:#e88080}
.term-line.info-line{color:#7db8ba;font-style:normal}
.term-line.success-line{color:#5ec97e}
.term-prompt-str{color:#5ec97e}
.term-at{color:#d4d454}
.term-path{color:#7db8ba}
.term-dollar{color:#b3b3b3}
.term-prompt-wrap{position:relative;display:block;background:#1c1c1c;font-size:14px;line-height:normal}
.term-row{display:flex;align-items:center;padding:0;margin:0 0 -2px 2px;background:#1c1c1c;gap:0;font-size:14px;line-height:normal}
.term-ps{font-family:monospace;font-size:14px;line-height:normal;white-space:nowrap;flex-shrink:0}
.term-inp{flex:0 1 auto;width:.1ch;max-width:calc(100vw - 220px);background:transparent;border:none;outline:none;font-family:monospace;font-size:14px;line-height:1;color:#b3b3b3;caret-color:transparent;padding:0;margin:0;resize:none;letter-spacing:0}
.term-inp::placeholder{color:#636363}
.term-cursor{display:inline-block;width:8px;height:14px;background:#b3b3b3;animation:blink 1s step-end infinite;vertical-align:-2px;margin-left:1px;flex-shrink:0}
@keyframes blink{0%,100%{opacity:1}50%{opacity:0}}
.term-suggest{position:absolute;background:#252525;border:1px solid #555;border-radius:4px;padding:4px 0;z-index:9;min-width:180px;box-shadow:0 8px 24px rgba(0,0,0,.6)}
.term-sug-item{padding:5px 12px;font-family:monospace;font-size:12px;color:#d4d454;cursor:pointer;transition:background .1s}
.term-sug-item:hover,.term-sug-item.active{background:#3b3b3b}
.term-footer{position:fixed;left:0;right:0;bottom:0;z-index:1000;display:flex;align-items:center;min-height:25px;height:25px;background:#131313;border:1px solid #636363;padding-left:5px;box-sizing:border-box;overflow:hidden;font-family:monospace;font-size:10px;line-height:1;color:#fff}
.term-footer-item{display:flex;align-items:center;margin-right:8px;white-space:nowrap;font-size:10px!important;line-height:1;flex-shrink:0}
.term-footer-label{display:inline-block;color:#d4d454;font-size:10px!important;line-height:1;font-weight:700;margin:0 3px}
.term-footer-value{display:inline-block;color:#fff;font-size:10px!important;line-height:1;margin-right:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:150px}
.term-footer-sep{width:2px;height:60%;background:#7db8ba;margin:0 5px;flex-shrink:0}
.term-footer-graph{width:50px;height:12px;background:#000;border:.5px solid #646464;overflow:hidden;display:inline-block;vertical-align:middle}
.term-footer-graph canvas{width:100%;height:100%;display:block}
.term-win,.term-win *{font-family:'TerminalTMT',monospace!important;font-variant-ligatures:none}
.term-footer-spacer{flex:1}
.term-footer-hide-sm,.term-footer-hide-md,.term-footer-hide-lg{display:none}
@media (min-width:768px){
  .term-footer-hide-sm{display:flex}
  .term-footer-sep.term-footer-hide-sm{display:block}
}
@media (min-width:1024px){
  .term-footer-hide-md{display:flex}
  .term-footer-sep.term-footer-hide-md{display:block}
}
@media (min-width:1280px){
  .term-footer-hide-lg{display:flex}
  .term-footer-sep.term-footer-hide-lg{display:block}
}
/* A terminal opened from the manager gets its own browser tab/window. */
body.term-standalone{background:#1c1c1c;overflow:hidden}
body.term-standalone .shell{display:none!important}
body.term-standalone .mod-ov:not(.term-ov){display:none!important}
body.term-standalone .term-ov{display:block!important;position:fixed;inset:0}
body.term-standalone .term-win{position:fixed;inset:0}

/* ══ Plugins Installer ══════════════════════════════════════════════════════
   Built from the app's own tokens so the window belongs to the manager in
   either theme, and sized so a plugin card grid and a long description both
   fit without the window itself scrolling. */
/* --accent does not exist in the manager's palette; the blue token does, and
   it is what the rest of the app uses for a selected/focused edge. */
.pie-win{--accent:var(--blue);
  width:min(1120px,96vw);height:min(860px,92vh);background:var(--surf);
  border:1px solid var(--border2);border-radius:var(--rlg);display:flex;flex-direction:column;
  overflow:hidden;animation:fadeUp .3s var(--spring) both}
.pie-hd{display:flex;align-items:center;justify-content:space-between;gap:12px;
  padding:13px 16px;border-bottom:1px solid var(--border2);background:var(--panel);flex:none}
.pie-hd-l{display:flex;align-items:center;gap:11px;min-width:0}
.pie-ico{width:34px;height:34px;flex:none;border-radius:9px;display:grid;place-items:center;
  background:var(--raised);border:1px solid var(--border2);color:var(--t1)}
.pie-ico svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.7;
  stroke-linecap:round;stroke-linejoin:round}
.pie-hd .mod-title{display:block;font-size:14px;font-weight:var(--fw-strong);color:var(--t1)}
.pie-sub{display:block;font-size:11.5px;color:var(--t3);margin-top:2px;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:min(620px,52vw)}

.pie-lab{font-size:10.5px;text-transform:uppercase;letter-spacing:.07em;color:var(--t3);flex:none}
.pie-sel,.pie-inp{background:var(--field);border:1px solid var(--fieldb);color:var(--t1);
  border-radius:8px;font:inherit;font-size:12px;padding:7px 10px;outline:none;min-width:0}
.pie-sel:focus,.pie-inp:focus{border-color:var(--fieldb-h);background:var(--fieldh)}
.pie-sel{max-width:min(430px,42vw);flex:1 1 auto}

.pie-tabs{display:flex;gap:2px;padding:8px 16px 0;flex:none;background:var(--panel)}
.pie-tab{background:none;border:1px solid transparent;border-bottom:none;color:var(--t2);
  font:inherit;font-size:12.5px;font-weight:var(--fw-medium);padding:8px 14px;border-radius:9px 9px 0 0;
  cursor:pointer;transition:.15s}
.pie-tab:hover{color:var(--t1);background:var(--hov)}
.pie-tab.is-on{color:var(--t1);background:var(--surf);border-color:var(--border2)}

.pie-pane{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;overflow:hidden}
.pie-pane[hidden]{display:none}
.pie-bar{display:flex;align-items:center;gap:10px;padding:12px 16px;flex:none;flex-wrap:wrap;
  background:var(--panel);border-bottom:1px solid var(--border)}
.pie-search{position:relative;flex:1 1 240px;min-width:200px;max-width:420px}
.pie-search svg{position:absolute;left:10px;top:50%;transform:translateY(-50%);width:14px;height:14px;
  fill:none;stroke:var(--t3);stroke-width:2;stroke-linecap:round;pointer-events:none}
.pie-search .pie-inp{width:100%;padding-left:31px}
.pie-browses{display:flex;gap:5px;flex-wrap:wrap;margin-left:auto}
.pie-chip{background:var(--raised);border:1px solid var(--border2);color:var(--t2);
  font:inherit;font-size:11.5px;padding:6px 12px;border-radius:99px;cursor:pointer;transition:.15s;white-space:nowrap}
.pie-chip:hover{color:var(--t1);border-color:var(--fieldb-h)}
.pie-chip.is-on{background:var(--t1);border-color:var(--t1);color:var(--bg);font-weight:var(--fw-medium)}
.pie-jed{display:inline-flex;align-items:center;gap:5px;font-size:11.5px;color:var(--t2);
  text-decoration:none;border:1px dashed var(--border2);border-radius:99px;padding:5px 11px;transition:.15s}
.pie-jed:hover{color:var(--t1);border-color:var(--fieldb-h)}
.pie-browses:empty,.pie-jed:empty{margin-left:0}
.pie-jed svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}

.pie-note{padding:0 16px 9px;font-size:11.5px;color:var(--t3);flex:none}
/* the same wording sits inside the pager row, where it is a sibling of the
   buttons rather than a block of its own */
.pie-pager .pie-note{padding:0;flex:1 1 100%;text-align:center}
.pie-note:empty{display:none}
.pie-note b{color:var(--t2);font-weight:var(--fw-medium)}

.pie-grid{flex:1 1 auto;min-height:0;overflow-y:auto;padding:2px 16px 14px;
  display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:10px;align-content:start}
.pie-card{background:var(--panel);border:1px solid var(--border);border-radius:var(--r);
  padding:12px;display:flex;flex-direction:column;gap:8px;transition:.15s}
.pie-card:hover{border-color:var(--border2);background:var(--raised)}
.pie-c-top{display:flex;gap:10px;align-items:flex-start}
.pie-c-ico{width:38px;height:38px;flex:none;border-radius:8px;background:var(--raised);
  border:1px solid var(--border);object-fit:contain;display:grid;place-items:center;color:var(--t3);font-size:15px;font-weight:var(--fw-strong)}
.pie-c-ico img{width:100%;height:100%;object-fit:contain;border-radius:8px}
.pie-c-id{min-width:0;flex:1 1 auto}
.pie-c-name{display:block;font-size:12.5px;font-weight:var(--fw-medium);color:var(--t1);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}
.pie-c-name:hover{text-decoration:underline}
.pie-c-meta{display:block;font-size:10.5px;color:var(--t3);margin-top:2px;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pie-c-desc{font-size:11.5px;color:var(--t2);line-height:1.5;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:34px}
.pie-c-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:auto}
.pie-stats{display:flex;gap:12px;font-size:11px;color:var(--t3);flex-wrap:wrap}
.pie-stats b{color:var(--t1);font-weight:var(--fw-medium)}
.pie-stat{display:inline-flex;align-items:center;gap:6px}
.pie-stars{display:inline-flex;align-items:center;gap:3px;color:var(--amber);font-size:11px}
.pie-stars svg{width:11px;height:11px;fill:currentColor;stroke:none}
.pie-c-acts{display:flex;gap:5px}
.pie-tagline{display:inline-block;font-size:10px;padding:2px 7px;border-radius:99px;
  background:var(--raised);border:1px solid var(--border);color:var(--t3)}
.pie-tagline.installed{color:var(--green);border-color:rgba(34,197,94,.3)}
.pie-tagline.active{color:var(--green);border-color:rgba(34,197,94,.35);background:rgba(34,197,94,.08)}
.pie-tagline.warn{color:var(--amber);border-color:rgba(245,158,11,.3)}

.pie-pager{display:flex;align-items:center;justify-content:center;gap:9px;padding:11px 16px;
  border-top:1px solid var(--border);flex:none;font-size:11.5px;color:var(--t3)}
.pie-pager:empty{display:none}

.pie-empty,.pie-busy{grid-column:1/-1;padding:44px 18px;text-align:center;color:var(--t3);font-size:12.5px;line-height:1.7}
.pie-empty b,.pie-busy b{display:block;color:var(--t2);font-size:13px;margin-bottom:5px;font-weight:var(--fw-medium)}
.pie-spin{width:20px;height:20px;margin:0 auto 10px;border:2px solid var(--border2);
  border-top-color:var(--t1);border-radius:50%;animation:pieSpin .7s linear infinite}
@keyframes pieSpin{to{transform:rotate(360deg)}}

.pie-list{flex:1 1 auto;min-height:0;overflow-y:auto;padding:0 16px 14px;display:flex;flex-direction:column;gap:7px}
.pie-row{background:var(--panel);border:1px solid var(--border);border-radius:var(--r);
  padding:10px 12px;display:flex;align-items:center;gap:11px}
.pie-row:hover{border-color:var(--border2)}
.pie-r-id{min-width:0;flex:1 1 auto}
.pie-r-name{font-size:12.5px;color:var(--t1);font-weight:var(--fw-medium);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pie-r-sub{font-size:10.5px;color:var(--t3);margin-top:2px;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pie-r-acts{display:flex;gap:5px;flex:none;align-items:center}

.pie-up{padding:18px 16px;display:flex;flex-direction:column;gap:13px;overflow-y:auto}
.pie-drop{border:1.5px dashed var(--border2);border-radius:var(--rlg);padding:38px 20px;
  text-align:center;color:var(--t2);display:flex;flex-direction:column;align-items:center;gap:7px;
  cursor:pointer;transition:.15s;background:var(--panel);position:relative}
.pie-drop:hover,.pie-drop.is-over{border-color:var(--t2);background:var(--raised)}
.pie-drop svg{width:26px;height:26px;fill:none;stroke:var(--t3);stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.pie-drop b{font-size:13px;color:var(--t1);font-weight:var(--fw-medium)}
.pie-drop span{font-size:11.5px;color:var(--t3);max-width:520px;line-height:1.6}
.pie-drop input[type=file]{position:absolute;inset:0;opacity:0;cursor:pointer}
.pie-up-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.pie-file-name{font-size:11.5px;color:var(--t2);font-family:ui-monospace,SFMono-Regular,Menlo,monospace;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:280px}
.pie-check{display:inline-flex;align-items:center;gap:6px;font-size:11.5px;color:var(--t2);cursor:pointer}
.pie-check input{accent-color:var(--green)}
.pie-msg{font-size:11.5px;color:var(--t3);line-height:1.65;background:var(--panel);
  border:1px solid var(--border);border-left:2px solid var(--border2);border-radius:8px;padding:10px 12px}
.pie-msg code{font-size:11px;background:var(--raised);padding:1px 4px;border-radius:4px;color:var(--t1)}
.pie-msg.good{border-left-color:var(--green);color:var(--t2)}
.pie-msg.bad{border-left-color:var(--red);color:var(--t2)}
.pie-msg b{color:var(--t1)}

.pie-ft{flex:none;padding:9px 16px;border-top:1px solid var(--border);background:var(--panel);
  font-size:11px;color:var(--t3);display:flex;gap:14px;flex-wrap:wrap}
.pie-ft:empty{display:none}
.pie-ft b{color:var(--t2);font-weight:var(--fw-medium)}

/* one plugin, read before it is installed */
.pie-detail{width:min(880px,94vw);height:min(760px,90vh)}
.pie-d-bar{display:flex;align-items:center;justify-content:space-between;gap:14px;
  padding:12px 16px;border-bottom:1px solid var(--border);flex:none;flex-wrap:wrap}
.pie-acts{display:flex;gap:7px;flex:none}
.pie-d-tabs{display:flex;gap:2px;padding:9px 16px 0;flex:none;flex-wrap:wrap}
.pie-d-body{flex:1 1 auto;min-height:0;overflow-y:auto;padding:14px 16px 22px;
  font-size:12.5px;line-height:1.7;color:var(--t2)}
.pie-d-body h1,.pie-d-body h2,.pie-d-body h3,.pie-d-body h4{color:var(--t1);margin:16px 0 7px;line-height:1.35}
.pie-d-body h1{font-size:16px}.pie-d-body h2{font-size:14.5px}.pie-d-body h3{font-size:13px}
.pie-d-body p{margin:0 0 10px}
.pie-d-body ul,.pie-d-body ol{margin:0 0 10px;padding-left:20px}
.pie-d-body li{margin-bottom:4px}
.pie-d-body a{color:var(--blue)}
.pie-d-body code{font-size:11.5px;background:var(--raised);padding:1px 5px;border-radius:4px;color:var(--t1)}
.pie-d-body pre{background:var(--field);border:1px solid var(--border);border-radius:8px;
  padding:11px;overflow-x:auto;font-size:11.5px;line-height:1.55}
.pie-d-body pre code{background:none;padding:0}
.pie-d-body img{max-width:100%;height:auto;border-radius:8px}
.pie-d-body table{border-collapse:collapse;width:100%;margin:0 0 12px;font-size:11.5px}
.pie-d-body th,.pie-d-body td{border:1px solid var(--border);padding:6px 9px;text-align:left}
.pie-d-body th{background:var(--raised);color:var(--t1);font-weight:var(--fw-medium)}
.pie-d-body blockquote{margin:0 0 10px;padding-left:11px;border-left:2px solid var(--border2);color:var(--t3)}
.pie-facts{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:8px;margin-bottom:14px}
.pie-fact{background:var(--panel);border:1px solid var(--border);border-radius:8px;padding:8px 10px}
.pie-fact i{display:block;font-style:normal;font-size:10px;text-transform:uppercase;
  letter-spacing:.06em;color:var(--t3);margin-bottom:3px}
.pie-fact b{font-size:12px;color:var(--t1);font-weight:var(--fw-medium);word-break:break-word}
.pie-bars{display:flex;flex-direction:column;gap:4px;margin-bottom:14px}
.pie-bar-row{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--t3)}
.pie-bar-row span:first-child{width:34px;flex:none}
.pie-track{flex:1 1 auto;height:6px;border-radius:99px;background:var(--raised);overflow:hidden}
.pie-track i{display:block;height:100%;background:var(--amber);border-radius:99px}
.pie-bar-row em{font-style:normal;width:52px;text-align:right;flex:none}

@media (max-width:760px){
  .pie-grid{grid-template-columns:1fr}
  .pie-sub{display:none}
  .pie-row{flex-wrap:wrap}
  .pie-r-acts{width:100%;justify-content:flex-end}
}

/* ── the site list ────────────────────────────────────────────────────────
   One card per installation found, shaped after the manager's own CMS
   Manager: a badge for the kind of site, the folder that will be installed
   into, and the config file it was recognised by. */
.pie-sites{flex:none;border-bottom:1px solid var(--border);background:var(--panel);
  display:flex;flex-direction:column}
.pie-sites-hd{display:flex;align-items:center;gap:9px;padding:9px 16px}
.pie-sites-hd .btn{margin-left:auto}
.pie-sites-n{font-size:11px;color:var(--t3)}
.pie-site-list{display:flex;flex-direction:column;max-height:172px;overflow-y:auto}
.pie-site-list:empty{display:none}
.pie-scanning{display:flex;align-items:center;gap:9px;padding:11px 16px;font-size:11.5px;color:var(--t3)}
.pie-scanning .pie-spin{width:13px;height:13px;border-width:2px}
.pie-site{display:flex;align-items:center;gap:11px;padding:11px 16px;width:100%;
  background:none;border:0;border-bottom:1px solid var(--border);color:inherit;
  font:inherit;text-align:left;cursor:pointer;transition:background .15s}
.pie-site:hover{background:var(--hov)}
.pie-site.is-on{background:var(--raised)}
.pie-site-badge{flex:none;font-size:10px;font-weight:700;padding:2px 9px;border-radius:99px;
  letter-spacing:.02em}
.pie-site-badge.w{background:rgba(33,117,155,.2);color:#5bc0de}
.pie-site-badge.j{background:rgba(244,163,51,.15);color:#f4a333}
.pie-site-id{min-width:0;flex:1 1 auto;display:flex;flex-direction:column;gap:2px}
.pie-site-dir{font-size:12px;font-weight:600;color:var(--t1);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pie-site-cfg{font-size:10.5px;color:var(--t3);font-family:var(--mono,ui-monospace,monospace);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pie-site-tick{flex:none;width:16px;height:16px;color:var(--t1)}
.pie-site-tick svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2.4;
  stroke-linecap:round;stroke-linejoin:round}
.pie-sites-foot{padding:0 16px 10px;font-size:11px;color:var(--t3);line-height:1.5}
.pie-sites-foot:empty{display:none}
@keyframes pieNudge{0%,100%{box-shadow:none}25%,75%{box-shadow:inset 0 0 0 2px var(--amber)}}
.pie-nudge{animation:pieNudge 1.1s ease-in-out 2}

/* ── installed plugins, with what the repository knows about them ──────── */
.pie-inst{display:flex;flex-direction:column;gap:9px;padding:2px 16px 14px}
.pie-i-card{display:flex;gap:13px;padding:13px;background:var(--panel);
  border:1px solid var(--border);border-radius:var(--r);transition:.15s}
.pie-i-card:hover{border-color:var(--border2);background:var(--raised)}
.pie-i-ico{position:relative;width:56px;height:56px;flex:none;border-radius:10px;background:var(--raised);
  border:1px solid var(--border);display:grid;place-items:center;overflow:hidden;
  font-size:19px;font-weight:var(--fw-strong);color:var(--t2)}
.pie-i-ini{position:absolute;inset:0;display:grid;place-items:center}
.pie-i-ico img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;
  background:var(--raised);border-radius:10px}
.pie-i-body{min-width:0;flex:1 1 auto;display:flex;flex-direction:column;gap:5px}
.pie-i-top{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap}
.pie-i-name{font-size:13px;font-weight:var(--fw-medium);color:var(--t1)}
.pie-i-ver{font-size:11px;color:var(--t3)}
.pie-i-desc{font-size:11.5px;color:var(--t3);line-height:1.5;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.pie-i-meta{display:flex;flex-wrap:wrap;gap:10px;font-size:11px;color:var(--t3);align-items:center}
.pie-i-meta b{color:var(--t2);font-weight:var(--fw-medium)}
.pie-i-acts{display:flex;flex-wrap:wrap;gap:6px;margin-top:2px}
.pie-i-state{font-size:10px;font-weight:700;padding:2px 8px;border-radius:99px}
.pie-i-state.on{background:rgba(52,211,153,.15);color:#34d399}
.pie-i-state.off{background:rgba(125,129,132,.16);color:var(--t3)}
.pie-i-upd{background:rgba(244,163,51,.15);color:#f4a333}

/* ── the site is chosen in its own window, before the installer opens ───── */
.pie-choose{width:min(640px,94vw);height:auto;max-height:min(680px,88vh)}
.pie-choose .pie-sites{border-bottom:0;padding-top:4px}
.pie-choose .pie-site-list{display:flex;flex-direction:column;gap:8px;
  padding:0 16px 6px;max-height:min(360px,48vh);overflow-y:auto}
.pie-choose-ft{justify-content:flex-start;color:var(--t3)}
.pie-choose-ft:empty{display:none}

/* One card per site. The badge is a fixed width on purpose: when it sized
   itself to the word ("WordPress" is wider than "Joomla") every card's folder
   started at a different x, so the list read as a staircase. */
.pie-choose .pie-site{align-items:center;gap:13px;padding:12px 14px;
  border:1px solid var(--border);border-radius:11px;background:var(--raised)}
.pie-choose .pie-site:hover{border-color:var(--border2);background:var(--hov)}
.pie-choose .pie-site.is-on{border-color:var(--accent);background:var(--raised)}
.pie-choose .pie-site:last-child{border-bottom:1px solid var(--border)}
.pie-choose .pie-site.is-on:last-child{border-bottom-color:var(--accent)}
.pie-choose .pie-site-badge{width:86px;flex:none;text-align:center;padding:4px 0;
  font-size:10px;border-radius:7px}
.pie-choose .pie-site-id{gap:3px}
.pie-choose .pie-site-dir{font-size:12.5px}
.pie-choose .pie-site-cfg{font-size:10.5px}
.pie-site-go{flex:none;width:16px;height:16px;color:var(--t3);opacity:.55;
  transition:opacity .15s,transform .15s}
.pie-site-go svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2.2;
  stroke-linecap:round;stroke-linejoin:round}
.pie-choose .pie-site:hover .pie-site-go{opacity:1;transform:translateX(2px)}
.pie-choose .pie-site-tick{flex:none;width:16px;height:16px;color:var(--accent)}
.pie-choose .pie-site-tick svg{width:16px;height:16px;fill:none;stroke:currentColor;
  stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.pie-choose .pie-site-tick:empty{display:none}

/* ── and the choice stays visible inside the installer ──────────────────── */
.pie-sitebar{display:flex;align-items:center;gap:11px;padding:10px 16px;flex:none;
  background:var(--panel);border-bottom:1px solid var(--border)}
.pie-sitebar .btn{margin-left:auto}
.pie-sitebar-id{min-width:0;flex:1 1 auto;display:flex;flex-direction:column;gap:1px}
.pie-sitebar .pie-site-dir{font-size:12px;font-weight:600}
.pie-sitebar .pie-site-cfg{font-size:10.5px;color:var(--t3);
  font-family:var(--mono,ui-monospace,monospace);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* ══ Wordfence Controller ════════════════════════════════════════════════════
   Built from the manager's own tokens and from the Plugins Installer's, so the
   two windows belong to the same app in either theme. The controller is denser
   than the installer by necessity: it is a settings surface for a plugin with
   two hundred options, and it is organised in sections with a scroller rather
   than in a card grid.

   The one thing this file insists on is that a setting's control never drifts
   away from its label. Every row is a fixed two-column grid, so the controls
   line up down the whole page no matter how long the labels are. */

.wfc-win{width:min(1080px,96vw);height:min(880px,92vh)}
.wfc-hd-r{display:flex;align-items:center;gap:9px;flex:none}
.wfc-pill{font-size:10.5px;font-weight:var(--fw-strong);padding:3px 9px;border-radius:99px;
  background:var(--raised);border:1px solid var(--border2);color:var(--t2)}
.wfc-pill[hidden]{display:none}

/* the scroller every settings tab shares */
.wfc-scroll{flex:1 1 auto;min-height:0;overflow-y:auto;padding:14px 16px 18px;
  display:flex;flex-direction:column;gap:16px}
/* A flex column shrinks its children to fit when there is more content than
   room, and a section squeezed that way keeps its own height while everything
   inside it spills over the section below - which is what put the login
   options on top of the users table and the health rows on top of the next
   heading. Every block keeps the height it needs and the scroller scrolls. */
.wfc-scroll>*{flex:none}
.wfc-log-scroll{padding:0 16px 12px}

/* ── sections ───────────────────────────────────────────────────────────── */
.wfc-sec{border:1px solid var(--border);border-radius:var(--rlg);background:var(--panel);
  overflow:hidden}
.wfc-sec-hd{display:flex;align-items:baseline;gap:9px;padding:10px 14px;font-size:12px;
  font-weight:var(--fw-strong);color:var(--t1);border-bottom:1px solid var(--border);
  background:var(--raised);flex-wrap:wrap}
.wfc-sec-note{font-size:10.5px;font-weight:400;color:var(--t3);margin-left:auto;text-align:right}
.wfc-note{padding:9px 14px;font-size:11px;color:var(--t3);line-height:1.65;
  border-top:1px solid var(--border)}
.wfc-note:empty{display:none}

/* ── the overview ───────────────────────────────────────────────────────── */
.wfc-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(124px,1fr));gap:9px}
.wfc-stat{background:var(--panel);border:1px solid var(--border);border-radius:10px;
  padding:10px 12px;display:flex;flex-direction:column;gap:3px;min-width:0}
.wfc-stat b{font-size:17px;font-weight:var(--fw-strong);color:var(--t1);line-height:1.1}
.wfc-stat span{font-size:10.5px;color:var(--t3);overflow:hidden;text-overflow:ellipsis;
  white-space:nowrap}
.wfc-stat.bad b{color:var(--red)}
.wfc-stat.warn b{color:var(--amber)}
.wfc-stat.good b{color:var(--green)}

.wfc-health{display:flex;flex-direction:column}
.wfc-h-row{display:flex;align-items:flex-start;gap:9px;padding:8px 14px;
  border-bottom:1px solid var(--border);font-size:11.5px;line-height:1.6}
.wfc-h-row:last-child{border-bottom:0}
.wfc-h-dot{width:8px;height:8px;border-radius:99px;flex:none;margin-top:5px}
.wfc-h-row.ok .wfc-h-dot{background:var(--green)}
.wfc-h-row.warn .wfc-h-dot{background:var(--amber)}
.wfc-h-row.bad .wfc-h-dot{background:var(--red)}
.wfc-h-label{font-weight:var(--fw-medium);color:var(--t1);flex:none;min-width:150px}
.wfc-h-detail{color:var(--t3);min-width:0}

.wfc-switches{display:grid;grid-template-columns:repeat(auto-fit,minmax(238px,1fr));gap:2px 20px;
  padding:6px 14px 10px}
.wfc-kit{display:grid;grid-template-columns:repeat(auto-fit,minmax(238px,1fr));gap:8px;
  padding:12px 14px;align-items:stretch}
/* A button's text cannot wrap while the manager's .btn keeps it on one line,
   so the description used to run straight out of its cell and past the edge of
   the window. It is a second line under the label instead. */
.wfc-kit .btn{justify-content:flex-start;white-space:normal;text-align:left;
  flex-direction:column;align-items:flex-start;gap:3px;padding:8px 10px;
  min-width:0;height:100%;line-height:1.3}
.wfc-kit .btn b{font-weight:var(--fw-medium);line-height:1.35;min-width:0}
.wfc-kit .btn i{font-style:normal;font-size:10px;color:var(--t3);line-height:1.45;
  white-space:normal;overflow-wrap:anywhere}

/* ── a card with its own actions (firewall, scanner) ─────────────────────── */
.wfc-card{border:1px solid var(--border);border-radius:var(--rlg);background:var(--panel);
  overflow:hidden}
.wfc-card-hd{display:flex;align-items:baseline;gap:9px;padding:10px 14px;
  border-bottom:1px solid var(--border);background:var(--raised)}
.wfc-card-hd b{font-size:12.5px;color:var(--t1);font-weight:var(--fw-strong)}
.wfc-card-sub{font-size:10.5px;color:var(--t3);margin-left:auto}
.wfc-card-body{padding:11px 14px;display:flex;flex-direction:column;gap:7px;font-size:11.5px}
.wfc-card-body:empty{display:none}
.wfc-kv{display:flex;gap:9px;align-items:baseline;min-width:0}
.wfc-kv i{font-style:normal;color:var(--t3);flex:none;min-width:132px}
.wfc-kv b{font-weight:var(--fw-medium);color:var(--t1);min-width:0;word-break:break-word}
.wfc-card-acts{display:flex;gap:7px;flex-wrap:wrap;padding:11px 14px;
  border-top:1px solid var(--border);background:var(--raised)}
.wfc-card-acts:empty{display:none}

/* ── settings rows ──────────────────────────────────────────────────────── */
/* two columns: the words on the left, the control on the right, with the
   control column the same width everywhere so the page reads as a table */
.wfc-opts{display:flex;flex-direction:column}
.wfc-opt{display:grid;grid-template-columns:1fr 210px;gap:14px;align-items:center;
  padding:9px 14px;border-bottom:1px solid var(--border)}
.wfc-opt:last-child{border-bottom:0}
.wfc-opt:hover{background:var(--hov)}
.wfc-opt.is-dirty{background:rgba(59,130,246,.08)}
.wfc-opt-l{min-width:0}
.wfc-opt-name{display:block;font-size:11.5px;color:var(--t1);line-height:1.5}
.wfc-opt-help{display:block;font-size:10.5px;color:var(--t3);line-height:1.5;margin-top:2px}
.wfc-opt-key{font-size:9.5px;color:var(--t3);font-family:ui-monospace,SFMono-Regular,Menlo,monospace}
.wfc-opt-r{display:flex;align-items:center;justify-content:flex-end;gap:8px;min-width:0}
.wfc-opt-r .pie-inp,.wfc-opt-r .pie-sel{width:100%;max-width:210px}
.wfc-opt textarea.pie-inp{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10.5px}
.wfc-opt.wide{grid-template-columns:1fr}
.wfc-opt.wide .wfc-opt-r{justify-content:flex-start;margin-top:6px}
.wfc-opt.wide textarea.pie-inp{max-width:none}

/* the toggle */
.wfc-sw{position:relative;width:38px;height:21px;flex:none;background:var(--field);
  border:1px solid var(--fieldb);border-radius:99px;cursor:pointer;transition:.15s;padding:0}
.wfc-sw::after{content:'';position:absolute;top:2px;left:2px;width:15px;height:15px;
  border-radius:99px;background:var(--t3);transition:.15s}
.wfc-sw[aria-checked="true"]{background:rgba(34,197,94,.22);border-color:var(--green)}
.wfc-sw[aria-checked="true"]::after{left:19px;background:var(--green)}
.wfc-sw:disabled{opacity:.5;cursor:not-allowed}
.wfc-sw-val{font-size:10px;color:var(--t3);flex:none;min-width:26px;text-align:right}

/* ── tables ─────────────────────────────────────────────────────────────── */
.wfc-table-wrap{overflow-x:auto;max-height:340px;overflow-y:auto}
.wfc-table{width:100%;border-collapse:collapse;font-size:11px}
.wfc-table th{position:sticky;top:0;z-index:1;background:var(--raised);color:var(--t3);
  font-size:10px;text-transform:uppercase;letter-spacing:.06em;text-align:left;
  padding:7px 12px;border-bottom:1px solid var(--border);font-weight:var(--fw-medium);
  white-space:nowrap}
.wfc-table td{padding:7px 12px;border-bottom:1px solid var(--border);color:var(--t2);
  vertical-align:top;line-height:1.55}
.wfc-table tr:last-child td{border-bottom:0}
.wfc-table tbody tr:hover{background:var(--hov)}
.wfc-table td.mono,.wfc-table td.num{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;
  white-space:nowrap}
.wfc-table td.num{text-align:right}
.wfc-table td.wrap{word-break:break-all;min-width:180px}
.wfc-table td.acts{white-space:nowrap;text-align:right}
.wfc-table .btn{padding:2px 7px;font-size:10.5px}
.wfc-empty-row td{text-align:center;color:var(--t3);padding:22px 12px}

.wfc-tag{display:inline-block;font-size:9.5px;padding:1px 6px;border-radius:99px;
  background:var(--raised);border:1px solid var(--border2);color:var(--t2)}
.wfc-tag.on{border-color:var(--green);color:var(--green)}
.wfc-tag.off{border-color:var(--border2);color:var(--t3)}
.wfc-tag.bad{border-color:var(--red);color:var(--red)}
.wfc-tag.warn{border-color:var(--amber);color:var(--amber)}

/* ── rows of buttons ────────────────────────────────────────────────────── */
.wfc-row-acts{display:flex;gap:7px;flex-wrap:wrap;align-items:center;padding:11px 14px;
  border-top:1px solid var(--border)}
.wfc-grid-acts{display:grid;grid-template-columns:repeat(auto-fit,minmax(196px,1fr));gap:7px;
  padding:12px 14px}
.wfc-grid-acts .btn{justify-content:space-between;min-width:0;white-space:normal}
.wfc-grid-acts .btn i{font-style:normal;color:var(--t3);font-size:10px;flex:none}
.wfc-block-form{display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding:12px 14px;
  border-bottom:1px solid var(--border)}
.wfc-block-form .pie-inp{flex:1 1 220px;max-width:340px}
.wfc-block-form .pie-sel.wfc-kind{flex:none;max-width:170px}
.wfc-check{display:inline-flex;align-items:center;gap:6px;font-size:11.5px;color:var(--t2);
  cursor:pointer}
.wfc-check input{accent-color:var(--green)}
.wfc-pre{margin:0 14px 14px;padding:11px 12px;background:var(--raised);
  border:1px solid var(--border);border-radius:8px;font-size:10.5px;line-height:1.6;
  font-family:ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--t2);
  white-space:pre-wrap;word-break:break-word;max-height:340px;overflow:auto}
.wfc-pre[hidden]{display:none}
.wfc-count{font-size:10.5px;color:var(--t3);margin-left:auto}
.wfc-token{flex:1 1 320px;max-width:100%;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;
  font-size:10.5px;resize:vertical}
.wfc-pager{display:flex;align-items:center;gap:12px;justify-content:center}

/* ── the footer ─────────────────────────────────────────────────────────── */
.wfc-ft{align-items:center}
.wfc-ft-spacer{flex:1 1 auto}
.wfc-ft-saved{color:var(--green);font-weight:var(--fw-medium);opacity:0;transition:opacity .25s}
.wfc-ft-saved.on{opacity:1}

/* ── the site window ────────────────────────────────────────────────────── */
.wfc-choose{width:min(680px,94vw)}
.wfc-choose .pie-site{align-items:center;gap:13px;padding:12px 14px;
  border:1px solid var(--border);border-radius:11px;background:var(--raised)}
.wfc-choose .pie-site:hover{border-color:var(--border2);background:var(--hov)}
.wfc-choose .pie-site.is-on{border-color:var(--accent)}
.wfc-choose .pie-site-badge{width:86px;flex:none;text-align:center;padding:4px 0;
  font-size:10px;border-radius:7px}
.wfc-choose .pie-site-dir{font-size:12.5px}
.wfc-choose .pie-site-missing{display:block;font-size:11px;color:var(--amber);margin-top:3px}
.wfc-sitebar .pie-site-badge{width:auto}
</style>
</head>
