/* ═══════════════════════════════════════
   TOP SEARCH ANYTHING — focus expands the field to the centre of the
   topbar (everything else in that bar fades away except the MFM brand
   and Logout), a suggestions panel offers the Tools from the sidebar,
   and files are searched live and recursively inside the current
   folder via ?x=global_search. Enter opens the active suggestion;
   files land on their folder with the existing FM_FOCUS highlight.
═══════════════════════════════════════ */
(function(){
  const topbar=document.querySelector('.topbar'),form=document.getElementById('topSearchForm'),input=document.getElementById('topSearchInput'),panel=document.getElementById('topSearchPanel'),closeBtn=document.getElementById('topSearchClose');
  if(!topbar||!form||!input||!panel)return;
  const backdrop=document.createElement('div');backdrop.className='ts-backdrop';document.body.appendChild(backdrop);
  const tsEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const tsBytes=b=>{b=Number(b||0);if(b>=1073741824)return(b/1073741824).toFixed(2)+' GB';if(b>=1048576)return(b/1048576).toFixed(1)+' MB';if(b>=1024)return(b/1024).toFixed(1)+' KB';return b+' B';};
  const folderSvg='<svg viewBox="0 0 24 24"><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>';
  function fileSvg(type){
    if(type==='image')return '<svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg>';
    if(type==='code'||type==='data'||type==='config')return '<svg viewBox="0 0 24 24"><polyline points="16 18 22 12 16 6"/><polyline points="8 6 2 12 8 18"/></svg>';
    if(type==='audio')return '<svg viewBox="0 0 24 24"><path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/></svg>';
    if(type==='video')return '<svg viewBox="0 0 24 24"><rect x="2" y="5" width="14" height="14" rx="2"/><path d="M16 10l6-4v12l-6-4z"/></svg>';
    if(type==='archive')return '<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="5" rx="1"/><path d="M5 9v10a1.5 1.5 0 0 0 1.5 1.5h11A1.5 1.5 0 0 0 19 19V9M10 13h4"/></svg>';
    return '<svg viewBox="0 0 24 24"><path d="M13 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><polyline points="13 2 13 9 20 9"/></svg>';
  }
  const tools=(()=>{
    return [...document.querySelectorAll('.sidebar .sb-scroll .sb-item')].map(el=>{
      const c=el.cloneNode(true);c.querySelectorAll('span').forEach(x=>x.remove());
      const name=(c.textContent||'').replace(/\s+/g,' ').trim();
      return{name,icon:el.querySelector('svg')?el.querySelector('svg').outerHTML:folderSvg,el};
    }).filter(t=>t.name);
  })();
  let expanded=false,openTimer=null,activeIndex=-1,items=[],fileResults=[],fileLoading=false,fileTruncated=false,debounce=null,seq=0,controller=null;
  function highlight(text,q){
    text=String(text??'');if(!q)return tsEsc(text);
    const i=text.toLowerCase().indexOf(q.toLowerCase());if(i<0)return tsEsc(text);
    return tsEsc(text.slice(0,i))+'<mark>'+tsEsc(text.slice(i,i+q.length))+'</mark>'+tsEsc(text.slice(i+q.length));
  }
  function currentFolderName(){const p=String(CWD||'').split('/').filter(Boolean);return p.length?p[p.length-1]:'current folder';}
  function setActive(i){
    if(!items.length||i<0){activeIndex=-1;panel.querySelectorAll('.ts-item').forEach(el=>el.classList.remove('active'));return;}
    activeIndex=(i+items.length)%items.length;
    panel.querySelectorAll('.ts-item').forEach((el,j)=>{el.classList.toggle('active',j===activeIndex);if(j===activeIndex)el.scrollIntoView({block:'nearest'});});
  }
  function render(){
    const q=input.value.trim(),ql=q.toLowerCase();
    const matchedTools=tools.filter(t=>!ql||t.name.toLowerCase().includes(ql));
    const shownTools=ql?matchedTools.slice(0,8):matchedTools.slice(0,12);
    items=[];let html='';
    if(shownTools.length){
      html+='<div class="ts-head"><span>Araçlar</span><span>'+matchedTools.length+' kullanılabilir</span></div><div class="ts-grid">';
      shownTools.forEach(t=>{const idx=items.length;items.push({kind:'tool',tool:t});
        html+='<button type="button" class="ts-item" role="option" data-idx="'+idx+'"><span class="ts-ico">'+t.icon+'</span><span class="ts-main"><span class="ts-name">'+highlight(t.name,q)+'</span><span class="ts-sub">Open tool</span></span><span class="ts-kind">Tool</span></button>';});
      html+='</div>';
      if(!ql&&matchedTools.length>shownTools.length)html+='<div class="ts-more">+'+(matchedTools.length-shownTools.length)+' more tools — start typing to filter</div>';
    }
    if(q){
      html+='<div class="ts-head"><span>Files</span><span>'+(fileLoading?'Searching…':'in '+tsEsc(currentFolderName())+' &amp; subfolders')+'</span></div>';
      if(fileLoading&&!fileResults.length){
        html+='<div class="ts-loading"><span class="ts-spinner"></span>Searching this folder and all subfolders…</div>';
      }else if(fileResults.length){
        html+='<div class="ts-list">';
        fileResults.forEach(r=>{const idx=items.length;
          const href=r.is_dir?('?dir='+encodeURIComponent(r.path)):('?dir='+encodeURIComponent(r.dir)+'&focus='+encodeURIComponent(r.name));
          items.push({kind:'file',href});
          const parent=r.rel&&r.rel.includes('/')?r.rel.slice(0,r.rel.lastIndexOf('/')):'Current folder';
          const meta=r.is_dir?'Folder · open path':(String(r.type||'file')+' · '+tsBytes(r.size));
          const icon=r.is_dir?folderSvg:fileSvg(String(r.type||'file'));
          const iconHtml=(String(r.type)==='image'&&!r.is_dir)?('<img class="ts-thumb" loading="lazy" alt="" src="?x=imgprev&f='+encodeURIComponent(r.name)+'&dir='+encodeURIComponent(r.dir)+'">'):('<span class="ts-ico type-'+tsEsc(String(r.type||'file').replace(/[^a-z0-9_-]/gi,''))+'">'+icon+'</span>');
          html+='<a class="ts-item" role="option" data-idx="'+idx+'" href="'+tsEsc(href)+'">'+iconHtml+'<span class="ts-main"><span class="ts-name">'+highlight(r.name,q)+'</span><span class="ts-sub">'+highlight(parent,q)+' · '+tsEsc(meta)+'</span></span><span class="ts-kind">'+(r.is_dir?'Folder':'File')+'</span></a>';});
        html+='</div>';
        if(fileTruncated)html+='<div class="ts-more">Showing the best matches — refine your search for more precise results</div>';
      }else if(!fileLoading){
        html+='<div class="ts-empty">No files match &ldquo;'+tsEsc(q)+'&rdquo; in this folder or its subfolders.</div>';
      }
    }else{
      html+='<div class="ts-head"><span>Files</span><span>recursive</span></div><div class="ts-hint">Type a file or folder name to search '+tsEsc(currentFolderName())+' and everything inside it.</div>';
    }
    html+='<div class="ts-foot"><span><kbd>↑</kbd> <kbd>↓</kbd> navigate</span><span><kbd>Enter</kbd> open</span><span><kbd>Esc</kbd> close</span></div>';
    panel.innerHTML=html;
    panel.querySelectorAll('.ts-item').forEach(el=>{
      const idx=Number(el.dataset.idx);
      el.addEventListener('mouseenter',()=>setActive(idx));
      el.addEventListener('click',e=>{e.preventDefault();activate(idx);});
    });
    setActive(q&&items.length?0:-1);
  }
  function activate(i){
    const item=items[i];if(!item)return;
    if(item.kind==='tool'){const el=item.tool.el;closeSearch();setTimeout(()=>{try{el.click();}catch(e){}},90);}
    else if(item.kind==='file'){location.href=item.href;}
  }
  async function fetchFiles(q){
    const mine=++seq;
    if(controller)try{controller.abort();}catch(e){}
    controller=('AbortController' in window)?new AbortController():null;
    fileLoading=true;render();
    try{
      const res=await fetch('?x=global_search&gsq='+encodeURIComponent(q)+'&dir='+encodeURIComponent(CWD),{credentials:'same-origin',signal:controller?controller.signal:undefined});
      const data=await res.json();
      if(mine!==seq)return;
      fileResults=Array.isArray(data.results)?data.results:[];fileTruncated=!!data.truncated;
    }catch(e){if(mine!==seq||(e&&e.name==='AbortError'))return;fileResults=[];}
    if(mine===seq){fileLoading=false;render();}
  }
  const reduceMotion=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function animateField(before,after,opening){
    if(reduceMotion||!before||!after||typeof form.animate!=='function')return;
    const dx=(before.left+before.width/2)-(after.left+after.width/2),dy=(before.top+before.height/2)-(after.top+after.height/2);
    if(Math.abs(dx)<2&&Math.abs(dy)<2&&Math.abs(before.width-after.width)<4)return;
    try{form.animate([
      {width:before.width+'px',height:before.height+'px',transform:opening?('translate(calc(-50% + '+dx+'px),calc(-50% + '+dy+'px))'):('translate('+dx+'px,'+dy+'px)')},
      {width:after.width+'px',height:after.height+'px',transform:opening?'translate(-50%,-50%)':'none'}
    ],{duration:opening?500:400,easing:'cubic-bezier(.22,1,.36,1)'});}catch(e){}
  }
  function openSearch(){
    if(expanded||openTimer)return;
    render();
    topbar.classList.add('search-hiding');
    openTimer=setTimeout(()=>{
      openTimer=null;expanded=true;
      const before=form.getBoundingClientRect();
      topbar.classList.remove('search-hiding');topbar.classList.add('search-expanded');
      const after=form.getBoundingClientRect();
      animateField(before,after,true);
      input.setAttribute('aria-expanded','true');
      requestAnimationFrame(()=>{panel.classList.add('open');backdrop.classList.add('on');});
    },200);
  }
  function closeSearch(){
    if(openTimer){clearTimeout(openTimer);openTimer=null;}
    if(!expanded)return;
    expanded=false;seq++;if(controller)try{controller.abort();}catch(e){}
    panel.classList.remove('open');backdrop.classList.remove('on');
    const before=form.getBoundingClientRect();
    topbar.classList.add('search-restoring');topbar.classList.remove('search-expanded');
    animateField(before,form.getBoundingClientRect(),false);
    input.setAttribute('aria-expanded','false');
    requestAnimationFrame(()=>requestAnimationFrame(()=>topbar.classList.remove('search-restoring')));
  }
  input.addEventListener('focus',openSearch);
  input.addEventListener('click',openSearch);
  input.addEventListener('input',()=>{
    if(!expanded&&!openTimer)openSearch();
    fileResults=[];fileTruncated=false;
    clearTimeout(debounce);
    const q=input.value.trim();
    if(!q){seq++;if(controller)try{controller.abort();}catch(e){}fileLoading=false;render();return;}
    fileLoading=true;render();
    debounce=setTimeout(()=>fetchFiles(q),180);
  });
  input.addEventListener('keydown',e=>{
    if(e.key==='ArrowDown'){e.preventDefault();setActive(activeIndex+1);}
    else if(e.key==='ArrowUp'){e.preventDefault();setActive(activeIndex-1);}
    else if(e.key==='Enter'&&expanded&&activeIndex>=0&&items[activeIndex]){e.preventDefault();activate(activeIndex);}
    else if(e.key==='Escape'){e.preventDefault();closeSearch();input.blur();}
  });
  form.addEventListener('submit',e=>{
    if(expanded&&activeIndex>=0&&items[activeIndex]&&input.value.trim()){e.preventDefault();activate(activeIndex);}
  });
  closeBtn.addEventListener('mousedown',e=>e.preventDefault());
  closeBtn.addEventListener('click',()=>{
    if(input.value){input.value='';fileResults=[];render();input.focus();}
    else{closeSearch();input.blur();}
  });
  document.addEventListener('mousedown',e=>{if(expanded&&!topbar.contains(e.target))closeSearch();});
})();

/* ── Theme toggle (shared across all users/devices, saved server-side) ── */
(function(){
  const sunIco=document.getElementById('themeIcoSun'),moonIco=document.getElementById('themeIcoMoon');
  function applyThemeIcon(t){
    if(!sunIco||!moonIco)return;
    if(t==='light'){sunIco.style.display='';moonIco.style.display='none';}
    else{sunIco.style.display='none';moonIco.style.display='';}
  }
  applyThemeIcon(document.documentElement.getAttribute('data-theme')||'dark');
  document.getElementById('themeBtn')?.addEventListener('click',async()=>{
    const cur=document.documentElement.getAttribute('data-theme')||'dark';
    const next=cur==='light'?'dark':'light';
    document.documentElement.setAttribute('data-theme',next);
    applyThemeIcon(next);
    try{
      const fd=new FormData();fd.append('theme',next);
      await fetch('?x=set_theme',{method:'POST',body:fd});
    }catch(e){}
  });
})();

/* ═══════════════════════════════════════
   FORM SUBMIT HELPER
═══════════════════════════════════════ */
function af(action,fields){
  document.getElementById('af_a').value=action;
  const map={item_name:'af_n',old_name:'af_o',new_name:'af_nw',items:'af_items',target:'af_tgt',trash_id:'af_tr',perm:'af_perm',color:'af_color',label:'af_label',config_path:'af_cfg',cms_id:'af_cid',cms_role:'af_crole',url:'af_url',fname:'af_fname'};
  Object.entries(map).forEach(([k,id])=>{document.getElementById(id).value='';});
  Object.entries(fields).forEach(([k,v])=>{const id=map[k];if(id)document.getElementById(id).value=v;});
  document.getElementById('af').submit();
}

/* ═══════════════════════════════════════
   FILE ACTIONS
═══════════════════════════════════════ */
function doAction(action,name,extra={}){
  if(action==='del'){
    if(!confirm(`Move "${name}" to trash?`))return;
    af('delete',{item_name:name});
  }else if(action==='ren'){
    const nw=prompt(`Rename "${name}" to:`,name);
    if(nw&&nw.trim()&&nw.trim()!==name)af('rename',{old_name:name,new_name:nw.trim()});
  }else if(action==='unzip'){
    if(!confirm(`Extract "${name}"?`))return;
    af('zip_extract',{item_name:name});
  }else if(action==='tar-x'){
    if(!confirm(`Extract "${name}"?`))return;
    af('tar_extract',{item_name:name});
  }else if(action==='dup'){
    if(!confirm(`Duplicate "${name}"?`))return;
    af('duplicate',{item_name:name});
  }else if(action==='hash'){
    openHash(name);
  }else if(action==='open'){
    if(extra.isDir)location.href='?dir='+encodeURIComponent(CWD+'/'+name);
    else if(extra.raw)openPreview(extra.raw,extra.type||'text',name);
    else location.href='?edit='+encodeURIComponent(name)+'&dir='+encodeURIComponent(CWD);
  }else if(action==='edit'){
    location.href='?edit='+encodeURIComponent(name)+'&dir='+encodeURIComponent(CWD);
  }else if(action==='dl'){
    location.href=extra.raw+'&dl=1';
  }else if(action==='prev'){
    if(extra.raw&&extra.type)openPreview(extra.raw,extra.type,name);
  }else if(action==='path'){
    const p=CWD+'/'+name;
    navigator.clipboard.writeText(p).then(()=>toast('Path copied!'));
  }else if(action==='share'){
    openShareCreate(name);
  }else if(action==='owner'){
    openOwner(name);
  }else if(action==='perm'){
    openPerm(name,extra.perm||'');
  }else if(action==='dirsize'){
    calcDirSize(name,extra.trigger);
  }
}

document.addEventListener('click',e=>{
  const btn=e.target.closest('[data-a]');
  if(!btn)return;
  doAction(btn.dataset.a,btn.dataset.n,{raw:btn.dataset.raw,type:btn.dataset.type,isDir:btn.dataset.isdir==='1'});
});

/* ═══════════════════════════════════════
   KEYBOARD NAVIGATION
═══════════════════════════════════════ */
const tbody=document.querySelector('.ft tbody');
if(tbody){
  tbody.addEventListener('keydown',e=>{
    const rows=Array.from(tbody.querySelectorAll('tr[data-name]'));
    const cur=document.activeElement.closest('tr');
    const idx=cur?rows.indexOf(cur):-1;
    if(e.key==='ArrowDown'){e.preventDefault();const nx=rows[idx+1];if(nx)nx.focus();}
    else if(e.key==='ArrowUp'){e.preventDefault();const pr=rows[idx-1];if(pr)pr.focus();}
    else if(e.key==='Enter'&&cur){
      const isDir=cur.dataset.isdir==='1';
      const name=cur.dataset.name;
      if(isDir)location.href='?dir='+encodeURIComponent(CWD+'/'+name);
      else{const nc=cur.querySelector('.nc[data-preview]');if(nc)openPreview(nc.dataset.preview,nc.dataset.type,nc.dataset.fname);}
    }else if(e.key==='Delete'&&cur&&!RO){doAction('del',cur.dataset.name);}
  });
}

/* ═══════════════════════════════════════
   RIGHT-CLICK CONTEXT MENU (desktop)
═══════════════════════════════════════ */
const ctx=document.getElementById('ctx');
let ctxData={};
function showCtx(x,y,data,overflowOnly=false){
  ctxData=data;
  document.getElementById('ctx-name').textContent=data.name;
  const isDir=data.isDir;const isRO=RO;
  const ext=(String(data.name||'').split('.').pop()||'').toLowerCase();
  const isZip=ext==='zip';
  const isTar=['tar','gz','tgz','bz2','tbz2'].includes(ext)||/\.tar\.(gz|bz2)$/i.test(String(data.name||''));
  // Show/hide items
  qs('ctx-open').style.display=overflowOnly?'none':'flex';
  qs('ctx-info').style.display='flex';
  qs('ctx-edit').style.display=(overflowOnly||isDir)?'none':'flex';
  qs('ctx-dl').style.display=(overflowOnly||isDir)?'none':'flex';
  const ctxExtract=qs('ctx-extract');if(ctxExtract)ctxExtract.style.display=(!isDir&&(isZip||isTar))?'flex':'none';
  qs('ctx-prev').style.display=(data.raw&&!isDir)?'flex':'none';
  qs('ctx-hash').style.display=isDir?'none':'flex';
  qs('ctx-dup').style.display=(isDir||isRO)?'none':'flex';
  qs('ctx-share').style.display=(isDir||isRO)?'none':'flex';
  qs('ctx-dirsize').style.display=isDir?'flex':'none';
  qs('ctx-perm').style.display=isRO?'none':'flex';
  const ctxOwn=qs('ctx-owner');if(ctxOwn)ctxOwn.style.display=isRO?'none':'flex';
  qs('ctx-ren').style.display=(overflowOnly||isRO)?'none':'flex';
  qs('ctx-del').style.display=(overflowOnly||isRO)?'none':'flex';

  // Position
  ctx.style.left=x+'px';ctx.style.top=y+'px';
  ctx.classList.add('open');
  // Adjust if off screen
  requestAnimationFrame(()=>{
    const r=ctx.getBoundingClientRect();
    if(r.right>window.innerWidth)ctx.style.left=(x-r.width)+'px';
    if(r.bottom>window.innerHeight)ctx.style.top=(y-r.height)+'px';
  });
}
function closeCtx(){ctx.classList.remove('open');}
function qs(id){return document.getElementById(id);}
function readFileInfo(el){
  if(!el)return null;
  try{return JSON.parse(el.dataset.info||'{}');}catch(_){return null;}
}
function fileInfoDate(value){
  const timestamp=Number(value);
  if(!Number.isFinite(timestamp)||timestamp<=0)return'-';
  const date=new Date(timestamp*1000);
  return Number.isNaN(date.getTime())?'-':date.toLocaleString();
}
function openFileInfo(info){
  if(typeof info==='string'){try{info=JSON.parse(info);}catch(_){info=null;}}
  if(!info||!info.name){toast('File information is unavailable.');return;}
  const size=info.bytes===null||info.bytes===undefined?'Not calculated for folders':`${formatBytes(Number(info.bytes)||0)} (${Number(info.bytes||0).toLocaleString()} bytes)`;
  const rows=[
    ['Name',info.name],['Kind',info.kind],['File type',info.type||'-'],
    ['Extension',info.extension||'No extension'],['Size',size],['MIME type',info.mime||'-'],
    ['Full path',info.path||'-'],['Permissions',info.permissions?`${info.permissions} · ${info.symbolic_permissions||''}`:'Unavailable'],
    ['Owner',info.owner||'-'],['Owner ID',info.owner_id??'-'],['Group',info.group||'-'],['Group ID',info.group_id??'-'],
    ['Readable',info.readable?'Yes':'No'],['Writable',info.writable?'Yes':'No'],['Executable',info.executable?'Yes':'No'],
    ['Modified',fileInfoDate(info.modified)],['Last accessed',fileInfoDate(info.accessed)],['Metadata changed',fileInfoDate(info.metadata_changed)],
    ['Inode',info.inode??'-'],['Hard links',info.hard_links??'-'],['Device ID',info.device??'-'],
    ['Symbolic link',info.is_symlink?'Yes':'No']
  ];
  if(info.created)rows.splice(18,0,['Created',fileInfoDate(info.created)]);
  if(info.is_symlink&&info.link_target)rows.push(['Link target',info.link_target]);
  document.getElementById('fileInfoTitle').textContent=info.name;
  document.getElementById('fileInfoGrid').innerHTML=rows.map(([label,value])=>`<div class="file-info-row"><span class="file-info-label">${esc(label)}</span><div class="file-info-value">${esc(String(value))}</div></div>`).join('');
  const openLink=document.getElementById('fileInfoOpenLink');
  let openHref='';
  try{const candidate=new URL(String(info.open_url||''),location.href);if(candidate.protocol==='http:'||candidate.protocol==='https:')openHref=candidate.href;}catch(_){}
  openLink.href=openHref||'#';
  openLink.hidden=!openHref;
  openLink.setAttribute('aria-label',`Open ${info.name}`);
  document.getElementById('fileInfoOpenUnavailable').hidden=Boolean(openHref);
  document.getElementById('fileInfoOpenName').textContent=info.name;
  openMod('fileInfoOv');
}

document.addEventListener('contextmenu',e=>{
  const nc=e.target.closest('[data-ctx-name]');
  const row=e.target.closest('tr[data-name],.gi[data-name]');
  if(!nc&&!row){closeCtx();return;}
  e.preventDefault();
  const name=nc?nc.dataset.ctxName:row.dataset.name;
  const isDir=(nc?nc.dataset.ctxIsdir:row.dataset.isdir)==='1';
  const raw=nc?nc.dataset.ctxRaw:row.dataset.ctxRaw||'';
  const type=nc?nc.dataset.ctxType:row.dataset.type||'';
  const perm=(nc?nc.dataset.ctxPerm:row.dataset.ctxPerm)||'';
  showCtx(e.clientX,e.clientY,{name,isDir,raw,type,perm,info:readFileInfo(row||nc)});
});
