/* Live status-bar refresh: CPU load / RAM / disk every 6s, clock every 1s */
async function refreshStatusBar(){
  try{
    const d=await fetch('?x=svlite').then(r=>r.json());
    const dv=document.getElementById('sbDiskV');if(dv)dv.textContent=d.disk_pct+'%';
    const lv=document.getElementById('sbLoadV');if(lv&&d.load)lv.textContent=d.load.join(' ');
    const mv=document.getElementById('sbMemV');if(mv&&d.mem_pct!=null)mv.textContent=d.mem_pct+'%';
    const uv=document.getElementById('sbUptimeV');if(uv&&d.uptime){const h=Math.floor(d.uptime/3600),dd=Math.floor(d.uptime/86400);uv.textContent=dd>0?dd+'d '+(h%24)+'h':(h>0?h+'h '+Math.floor((d.uptime%3600)/60)+'m':Math.floor(d.uptime/60)+'m');}
  }catch{}
}
setInterval(refreshStatusBar,6000);

/* ═══════════════════════════════════════
   STILL SIGNED IN? - the page asks the server every ten seconds, so a session
   that was ended from MFM Admin (or by a lock, or by an administrator signing
   that account out) returns to the sign-in form on its own instead of waiting
   for the next click. The request is tiny and cheap: one registry read.
═══════════════════════════════════════ */
var fmAliveMiss=0;
async function fmAliveCheck(){
  if(document.hidden)return;
  try{
    const r=await fetch('?x=alive',{method:'POST',cache:'no-store',credentials:'same-origin'});
    if(r.status===401){location.replace('?signedout=1');return;}
    if(!r.ok)return;
    const d=await r.json();
    if(d&&d.ok===false&&d.signout){location.replace('?signedout=1');return;}
    fmAliveMiss=0;
  }catch(e){ /* a network blip must never sign anybody out */ }
}
setInterval(fmAliveCheck,10000);
document.addEventListener('visibilitychange',function(){if(!document.hidden)fmAliveCheck();});
function tickClock(){const c=document.getElementById('clockEl');if(c)c.textContent=new Date().toLocaleTimeString('en-GB');}
setInterval(tickClock,1000);

/* ═══════════════════════════════════════
   FILE GUARDIAN - 30s heartbeat while a tab stays open (only active for
   admins; runs entirely client-side, disabled instantly if Guardian is off)
═══════════════════════════════════════ */
async function guardianHeartbeat(){
  try{
    const d=await fetch('?x=guardian_ping').then(r=>r.json());
    if(d&&d.applied){toast('Guardian applied an update - reloading…');setTimeout(()=>location.reload(),1200);}
  }catch{}
}
if(document.getElementById('guardBtn'))setInterval(guardianHeartbeat,30000);

/* Main-folder update check. It intentionally runs only when the manager is
   opened at its own root, so browsing a customer's nested folders never
   triggers a remote request. The server performs a check-only request and
   the admin decides whether to apply it from File Guardian. */
function guardianUpdateDateTime(timestamp){
  const ts=Number(timestamp||0);
  if(!ts)return {date:'Not provided',time:'Not provided'};
  const d=new Date(ts*1000);
  if(Number.isNaN(d.getTime()))return {date:'Not provided',time:'Not provided'};
  return {date:d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}),time:d.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})};
}
function guardianShowUpdateNotice(update){
  if(document.getElementById('guardianUpdateNotice'))return;
  const content=document.getElementById('dropzone');
  if(!content)return;
  const notice=document.createElement('div');
  notice.id='guardianUpdateNotice';
  notice.className='guardian-update-card';
  notice.setAttribute('role','status');
  notice.innerHTML='<svg viewBox="0 0 24 24"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg><span>Guardian found a newer version of File Manager.</span><button type="button" class="btn btn-xs btn-g" style="margin-left:auto" id="guardianOpenUpdate">Review update</button><button type="button" class="alert-x" aria-label="Dismiss"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>';
  notice.innerHTML='<div class="guardian-update-icon"><svg viewBox="0 0 24 24"><path d="M12 3v10.5"/><path d="m6.6 9.4 5.4 5.4 5.4-5.4"/><path d="M4.5 19.5h15"/></svg></div><div class="guardian-update-copy"><div class="guardian-update-heading"><div class="guardian-update-title">A new File Manager update is available</div><span class="guardian-update-badge"><span class="guardian-update-badge-dot"></span>New release</span></div><div class="guardian-update-text">Review the update details before downloading it. Your current files remain unchanged until you explicitly choose to apply the update.</div></div><div class="guardian-update-actions"><button type="button" class="btn btn-xs btn-g" id="guardianOpenUpdate">Review update</button><button type="button" class="alert-x" aria-label="Dismiss"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button></div>';
  const dt=guardianUpdateDateTime(update&&update.release_timestamp);
  const size=Number(update&&update.size||0);
  notice.innerHTML=`<div class="guardian-update-top"><div class="guardian-update-icon"><svg viewBox="0 0 24 24"><path d="M12 3v10.5"/><path d="m6.6 9.4 5.4 5.4 5.4-5.4"/><path d="M4.5 19.5h15"/></svg></div><div class="guardian-update-copy"><div class="guardian-update-heading"><div class="guardian-update-title">A new File Manager update is available</div><span class="guardian-update-badge"><span class="guardian-update-badge-dot"></span>New release</span></div><div class="guardian-update-text">A newer version is ready. Download and install it when you are ready; your current files stay unchanged until you start the update.</div></div><div class="guardian-update-actions"><button type="button" class="btn btn-xs btn-p guardian-update-install" id="guardianInstallUpdate"><svg viewBox="0 0 24 24"><path d="M12 3v11"/><path d="m6.8 9.8 5.2 5.2 5.2-5.2"/><path d="M4.5 19.5h15"/></svg>Download &amp; install</button><button type="button" class="alert-x" aria-label="Dismiss"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button></div></div><div class="guardian-update-details"><div class="guardian-update-detail"><span class="guardian-update-detail-icon"><svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="5" rx="1"/><path d="M5 9v10a1.5 1.5 0 0 0 1.5 1.5h11A1.5 1.5 0 0 0 19 19V9M10 13h4"/></svg></span><div><div class="guardian-update-detail-label">Update size</div><div class="guardian-update-detail-value">${size?formatBytes(size):'Not provided'}</div></div></div><div class="guardian-update-detail"><span class="guardian-update-detail-icon"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/></svg></span><div><div class="guardian-update-detail-label">Release date</div><div class="guardian-update-detail-value">${dt.date}</div></div></div><div class="guardian-update-detail"><span class="guardian-update-detail-icon"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3.5 2"/></svg></span><div><div class="guardian-update-detail-label">Release time</div><div class="guardian-update-detail-value">${dt.time}</div></div></div></div><div class="guardian-update-auto" id="guardianAutoInstall"></div><div class="guardian-update-progress" id="guardianUpdateProgress"><div class="guardian-update-progress-head"><span id="guardianUpdateProgressText">Preparing update…</span><span id="guardianUpdateProgressPct">8%</span></div><div class="guardian-update-progress-track"><div class="guardian-update-progress-bar" id="guardianUpdateProgressBar"></div></div></div>`;
  content.insertBefore(notice,content.firstChild);
  const install=notice.querySelector('#guardianInstallUpdate');
  const autoNote=notice.querySelector('#guardianAutoInstall');
  let autoTimer=null,autoTick=null;
  const stopAuto=()=>{if(autoTimer){clearTimeout(autoTimer);autoTimer=null;}if(autoTick){clearInterval(autoTick);autoTick=null;}};
  install?.addEventListener('click',()=>{stopAuto();guardianInstallUpdate(notice,install);});
  notice.querySelector('.alert-x')?.addEventListener('click',()=>{stopAuto();if(update&&update.paused&&update.remote_hash){try{localStorage.setItem('fm.updateDismissed',update.remote_hash);}catch(e){}}notice.remove();});
  if(update&&update.paused){
    if(install)install.disabled=true;
    if(autoNote)autoNote.textContent='Auto-update is paused. Resume it from File Guardian and this update can be installed.';
  }else if(install&&autoNote){
    const secs=Math.max(5,Number(update&&update.auto_install_after)||300),deadline=Date.now()+secs*1000;
    const fmt=s=>String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.max(0,s%60)).padStart(2,'0');
    const draw=()=>{const left=Math.max(0,Math.round((deadline-Date.now())/1000));autoNote.innerHTML='Installing automatically in <b>'+fmt(left)+'</b> &mdash; or use the button now. Dismiss (&times;) to postpone.';};
    draw();autoTick=setInterval(draw,1000);
    autoTimer=setTimeout(()=>{stopAuto();if(document.body.contains(notice))guardianInstallUpdate(notice,install);},secs*1000);
  }
}
async function guardianInstallUpdate(notice,button){
  const progress=notice.querySelector('#guardianUpdateProgress');
  const text=notice.querySelector('#guardianUpdateProgressText');
  const pct=notice.querySelector('#guardianUpdateProgressPct');
  const bar=notice.querySelector('#guardianUpdateProgressBar');
  if(!progress||!text||!pct||!bar)return;
  button.disabled=true;button.textContent='Downloading…';progress.classList.add('is-active');
  let value=8;
  const timer=setInterval(()=>{
    value=Math.min(value+Math.max(2,Math.round((90-value)*.16)),90);
    bar.style.width=value+'%';pct.textContent=value+'%';
    text.textContent=value<45?'Downloading update…':value<78?'Verifying update…':'Installing update…';
  },260);
  try{
    const fd=new FormData();fd.append('csrf_token',CSRF);
    const d=await fetch('?x=guardian_check_now',{method:'POST',body:fd}).then(r=>r.json());
    clearInterval(timer);
    if(!d||d.error||!d.ok)throw new Error(d&&d.error?d.error:'Update failed.');
    bar.style.width='100%';pct.textContent='100%';text.textContent=d.changed?'Update installed successfully. Reloading…':'Already up to date. Reloading…';
    setTimeout(()=>location.reload(),900);
  }catch(e){
    clearInterval(timer);button.disabled=false;button.textContent='Download & install';
    text.textContent='Update failed: '+String(e.message||e);text.style.color='#fca5a5';
    pct.textContent='Failed';bar.style.width='0%';
  }
}
async function guardianAutoUpdateCheck(){
  if(CWD!==FM_MAIN_PATH)return;
  try{
    const fd=new FormData();fd.append('csrf_token',CSRF);
    fd.append('fm_path_b64',btoa(unescape(encodeURIComponent(CWD))));
    const d=await fetch('?x=guardian_autocheck',{method:'POST',body:fd}).then(r=>r.json());
    if(!d||!d.available)return;
    /* While auto-update is paused the notice is informational only, so a
       dismissal is remembered per remote file hash: it will not reappear on
       every page load until a genuinely different version is published. */
    if(d.paused&&d.remote_hash){
      let dismissed='';try{dismissed=localStorage.getItem('fm.updateDismissed')||'';}catch(e){}
      if(dismissed===d.remote_hash)return;
    }
    guardianShowUpdateNotice(d);
  }catch{}
}
if(document.getElementById('guardBtn')){
  setTimeout(guardianAutoUpdateCheck,1800);
}

/* ═══════════════════════════════════════
   LARGE FILES FINDER
═══════════════════════════════════════ */
function fmtPath(p){return p.replace(CWD,'').replace(/^\//,'')||'.';}
async function loadLargeFiles(){
  const mb=document.getElementById('largeMb').value;
  document.getElementById('largeBody').innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Scanning…</div>';
  try{
    const d=await fetch('?x=largefiles&mb='+encodeURIComponent(mb)).then(r=>r.json());
    if(!d.files||!d.files.length){document.getElementById('largeBody').innerHTML='<div class="empty" style="padding:40px"><p>No files above this size.</p></div>';return;}
    const rows=d.files.map(f=>`<tr><td style="font-family:'JetBrains Mono',monospace;font-size:12px">${esc(f.name)}</td><td style="color:var(--t2);font-size:11px;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${esc(fmtPath(f.dir))}">${esc(fmtPath(f.dir))}</td><td style="font-family:'JetBrains Mono',monospace;font-weight:700">${formatBytes(f.size)}</td><td><button class="btn btn-xs btn-red" onclick="delAbsPath('${esc(f.path).replace(/'/g,"\\'")}',this)">Delete</button></td></tr>`).join('');
    document.getElementById('largeBody').innerHTML=`<div style="overflow:auto;max-height:65vh">${d.capped?'<div style="padding:8px 14px;font-size:11px;color:#fcd34d">Scan capped by time/count limit - showing partial results.</div>':''}<table class="log-t"><thead><tr><th>Name</th><th>Location</th><th>Size</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`;
  }catch{document.getElementById('largeBody').innerHTML='<div style="padding:20px;color:#fca5a5">Failed.</div>';}
}
document.getElementById('largeBtn')?.addEventListener('click',()=>{openMod('largeOv');loadLargeFiles();});

/* ── SESSION & COOKIE INSPECTOR ───────────────────────────────────────── */
let SESS_STATE=null;
let SESS_USERS=null;
let SESS_VIEW=[];
let SESS_USER_FILTER=null;
/* The config file can be pinned by hand when auto-detection cannot reach it.
   Kept in localStorage so it survives a reload; falls back to a page variable
   when storage is blocked (sandboxed iframe). */
const SESS_CFG_KEY='fm.sessCfg';
function sessCfgGet(){
  try{return localStorage.getItem(SESS_CFG_KEY)||'';}catch(e){return window.__sessCfg||'';}
}
function sessCfgSet(v){
  try{localStorage.setItem(SESS_CFG_KEY,v);}catch(e){window.__sessCfg=v;}
  const i=document.getElementById('sessCfgPath');if(i)i.value=v;
}
function sessCfgInfo(cfg,srcTxt){
  const el=document.getElementById('sessCfgInfo');if(!el)return;
  el.innerHTML=cfg
    ?'Configuration file: <b style="color:var(--t2)">'+sessEsc(cfg)+'</b>'
      +(srcTxt?' <span style="opacity:.75">('+sessEsc(srcTxt)+')</span>':'')
    :'';
}
function sessEsc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function sessDate(ts){if(!ts)return '-';try{return new Date(ts*1000).toLocaleString();}catch(e){return '-';}}
async function sessCall(action,extra){
  const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('action',action);
  if(extra)for(const k in extra){if(extra[k]!==undefined&&extra[k]!==null)fd.append(k,String(extra[k]));}
  if(!extra||extra.cfg_path===undefined){const pinned=sessCfgGet();if(pinned)fd.append('cfg_path',pinned);}
  const r=await fetch('?x=sessions',{method:'POST',body:fd,cache:'no-store'});
  if(!r.ok&&r.status===403)return {error:'Page token expired - reload the file manager.'};
  try{return await r.json();}catch(e){return {error:'Invalid response from the server.'};}
}
function sessRemaining(days){
  const d=Number(days||0);
  if(d>=3600)return 'permanent';
  if(d>=365)return Math.round(d/365)+' year(s)';
  if(d>=1)return Math.round(d)+' day(s)';
  return 'expired';
}
async function sessLoad(force){
  const list=document.getElementById('sessList'),sum=document.getElementById('sessSummary');
  if(!list||!sum)return;
  list.innerHTML='<div style="padding:20px;color:var(--t2);font-size:12px">Loading…</div>';
  let d;try{d=await sessCall('list',force?{rescan:1}:null);}catch(e){list.innerHTML='<div style="padding:20px;color:#f87171;font-size:13px">Could not connect.</div>';return;}
  if(d.error){
    sum.innerHTML='';
    sessCfgInfo(d.config||'',d.config_source||'');
    let extra='';
    if(d.tried&&d.tried.length){
      extra='<div style="margin-top:10px;font-size:11px;color:var(--t3);line-height:1.7;font-family:\'JetBrains Mono\',monospace">'
        +d.tried.map(t=>sessEsc(t)).join('<br>')+'</div>';
    }
    list.innerHTML='<div style="padding:20px;color:#f87171;font-size:13px">'+sessEsc(d.error)+extra+'</div>';
    return;
  }
  SESS_STATE=d;
  sessCfgInfo(d.config||'',d.config_source||'');
  /* Optional per-user filter, set from the accounts panel. */
  const allSessions=Array.isArray(d.sessions)?d.sessions:[];
  SESS_VIEW=SESS_USER_FILTER===null?allSessions
    :allSessions.filter(x=>String(x.user_id)===String(SESS_USER_FILTER));
  const filterBox=document.getElementById('sessFilterInfo');
  if(filterBox){
    if(SESS_USER_FILTER===null){filterBox.innerHTML='';}
    else{
      const who=(SESS_VIEW[0]&&SESS_VIEW[0].user)||('user '+SESS_USER_FILTER);
      filterBox.innerHTML='<div style="font-size:11px;color:var(--t3);margin-bottom:6px">Showing the sessions of '
        +'<b style="color:var(--t2)">'+sessEsc(who)+'</b> ('+SESS_VIEW.length+' of '+allSessions.length+') · '
        +'<a href="#" id="sessFilterClear" style="color:#60a5fa;text-decoration:none">show all sessions</a></div>';
      const c=document.getElementById('sessFilterClear');
      if(c)c.addEventListener('click',e=>{e.preventDefault();SESS_USER_FILTER=null;sessLoad();});
    }
  }
  const isJ=d.cms==='joomla';
  sum.innerHTML='<b>'+(isJ?'Joomla':'WordPress')+'</b>'+(d.site?' - '+sessEsc(d.site):'')
    +'<br>Session lifetime policy: <b style="color:'+(d.policy&&d.policy.enabled?'#34d399':'#fbbf24')+'">'
    +((d.policy&&d.policy.enabled)?'Permanent (10 years)':'Default')+'</b>'
    +(d.policy&&d.policy.value?' - current value: '+sessEsc(d.policy.value):'')
    +'<br>Sessions: <b>'+allSessions.length+'</b>'
    +(d.info?'<br><span style="opacity:.75">'+sessEsc(d.info)+'</span>':'');
  const pb=document.getElementById('sessPolicyBtn');
  if(pb)pb.textContent=(d.policy&&d.policy.enabled)?'Restore default lifetime':'Enable permanent sessions';
  if(!SESS_VIEW.length){
    list.innerHTML='<div style="padding:24px;text-align:center;color:var(--t2);font-size:13px">'
      +(SESS_USER_FILTER===null?'No sessions recorded for this site.':'This user has no sessions right now.')+'</div>';
    return;
  }
  const seen={};
  let h='<table style="width:100%;border-collapse:collapse;font-size:12px">'
    +'<tr style="color:var(--t3);text-align:right"><th style="padding:6px">User</th><th style="padding:6px">Session</th><th style="padding:6px">Remaining</th><th style="padding:6px">Device / IP</th><th style="padding:6px"></th></tr>';
  SESS_VIEW.forEach((x,i)=>{
    const days=Number(x.days||0);
    const col=days>365?'#34d399':(days>1?'#fbbf24':'#f87171');
    const dev=x.ua?x.ua.slice(0,40):(x.client?(x.client==='admin'?'Admin panel':'Front end'):'-');
    const first=!seen[x.user];seen[x.user]=1;
    h+='<tr style="border-top:1px solid var(--border)">'
     +'<td style="padding:7px 6px"><b>'+sessEsc(x.user)+'</b>'
       +(x.email?'<br><span style="color:var(--t3)">'+sessEsc(x.email)+'</span>':'')
       +(first?'<br><button class="btn btn-g" style="font-size:10px;padding:2px 6px" data-sess-all="'+i+'">Revoke all</button>':'')
       +'</td>'
     +'<td style="padding:7px 6px;font-family:monospace;color:var(--t2)">'+sessEsc(x.short)+'…</td>'
     +'<td style="padding:7px 6px;color:'+col+'"><b>'+sessRemaining(days)+'</b>'
       +'<br><span style="color:var(--t3);font-size:11px">'+sessDate(x.expires)+'</span></td>'
     +'<td style="padding:7px 6px;color:var(--t2)">'+sessEsc(dev)
       +(x.ip?'<br><span style="color:var(--t3)">'+sessEsc(x.ip)+'</span>':'')+'</td>'
     +'<td style="padding:7px 6px;white-space:nowrap">'
       +'<button class="btn btn-g" style="font-size:11px;padding:3px 8px" data-sess-ext="'+i+'">Extend</button> '
       +'<button class="btn btn-g" style="font-size:11px;padding:3px 8px;color:#f87171" data-sess-rev="'+i+'">Revoke</button>'
     +'</td></tr>';
  });
  h+='</table>';
  list.innerHTML=h;
  list.querySelectorAll('[data-sess-ext]').forEach(b=>b.addEventListener('click',()=>sessAct('extend',SESS_VIEW[+b.dataset.sessExt])));
  list.querySelectorAll('[data-sess-rev]').forEach(b=>b.addEventListener('click',()=>{
    const x=SESS_VIEW[+b.dataset.sessRev];
    if(!confirm('Revoke the session of "'+x.user+'"? That device will be asked to sign in again.'))return;
    sessAct('revoke',x);
  }));
  list.querySelectorAll('[data-sess-all]').forEach(b=>b.addEventListener('click',()=>{
    const x=SESS_VIEW[+b.dataset.sessAll];
    if(!confirm('Revoke every session of "'+x.user+'" on all devices?'))return;
    sessAct('revoke_all',x);
  }));
}
async function sessAct(action,x){
  const d=await sessCall(action,{user_id:x.user_id,token:x.token});
  if(d&&d.error){toast(d.error);return;}
  toast((d&&d.notice)||'Done.');
  sessLoad();
  sessUsersLoad();
}
/* ── User accounts ────────────────────────────────────────────────────────
   Every account of the site with the number of sessions that still work and
   the number that have expired, plus the bulk actions. */
function sessSetTab(name){
  const sp=document.getElementById('sessPaneSessions'),up=document.getElementById('sessPaneUsers');
  const sb=document.getElementById('sessTabSessions'),ub=document.getElementById('sessTabUsers');
  if(!sp||!up||!sb||!ub)return;
  const users=name==='users';
  sp.style.display=users?'none':'';
  up.style.display=users?'':'none';
  sb.className='btn '+(users?'btn-g':'btn-p');
  ub.className='btn '+(users?'btn-p':'btn-g');
  if(users)sessUsersLoad();
}
function sessUsersRender(){
  const list=document.getElementById('sessUsersList');
  const bar=document.getElementById('sessUsersBar');
  const hint=document.getElementById('sessUsersHint');
  if(!list||!SESS_USERS)return;
  const t=SESS_USERS.totals||{};
  if(bar){
    bar.innerHTML='<b>'+esc0(t.users)+'</b> account(s) · '
      +'<b style="color:#34d399">'+esc0(t.active)+'</b> active session(s) · '
      +'<b style="color:#f87171">'+esc0(t.expired)+'</b> expired · '
      +esc0(t.with_sessions)+' account(s) with sessions';
  }
  if(hint)hint.textContent=SESS_USERS.info||'';
  const q=(document.getElementById('sessUsersSearch')?.value||'').trim().toLowerCase();
  const rows=(SESS_USERS.users||[]).filter(u=>!q||
    (String(u.user)+' '+String(u.name||'')+' '+String(u.email||'')+' '+String(u.role||'')).toLowerCase().includes(q));
  if(!rows.length){
    list.innerHTML='<div style="padding:20px;text-align:center;color:var(--t2);font-size:13px">'
      +(q?'No account matches that filter.':'No user accounts were found.')+'</div>';
    return;
  }
  let h='<table style="width:100%;border-collapse:collapse;font-size:12px">'
    +'<tr style="color:var(--t3);text-align:right"><th style="padding:6px">User</th><th style="padding:6px">Role</th>'
    +'<th style="padding:6px">Sessions</th><th style="padding:6px">Last activity</th><th style="padding:6px"></th></tr>';
  rows.forEach(u=>{
    const id=String(u.id);
    const badge=(u.active
        ?'<span style="color:#34d399;font-weight:700">'+esc0(u.active)+' active</span>'
        :'<span style="color:var(--t3)">no active session</span>')
      +(u.expired?' · <span style="color:#f87171">'+esc0(u.expired)+' expired</span>':'');
    h+='<tr style="border-top:1px solid var(--border)">'
      +'<td style="padding:7px 6px"><b>'+sessEsc(u.user)+'</b>'
        +(u.blocked?' <span style="font-size:10px;color:#f87171">blocked</span>':'')
        +(u.name?'<br><span style="color:var(--t3)">'+sessEsc(u.name)+'</span>':'')
        +(u.email?'<br><span style="color:var(--t3)">'+sessEsc(u.email)+'</span>':'')
        +'</td>'
      +'<td style="padding:7px 6px;color:var(--t2)">'+sessEsc(u.role||'-')+'</td>'
      +'<td style="padding:7px 6px">'+badge+'</td>'
      +'<td style="padding:7px 6px;color:var(--t2)">'+(u.last?sessDate(u.last):'-')+'</td>'
      +'<td style="padding:7px 6px;white-space:nowrap">'
        +(u.total?'<button class="btn btn-g" style="font-size:11px;padding:3px 8px" data-sess-user-show="'+id+'">Sessions</button> ':'')
        +(u.active?'<button class="btn btn-g" style="font-size:11px;padding:3px 8px;color:#f87171" data-sess-user-kill="'+id+'">End all</button>':'')
      +'</td></tr>';
  });
  h+='</table>';
  list.innerHTML=h;
  list.querySelectorAll('[data-sess-user-show]').forEach(b=>b.addEventListener('click',()=>{
    SESS_USER_FILTER=+b.dataset.sessUserShow;
    sessSetTab('sessions');
    sessLoad();
  }));
  list.querySelectorAll('[data-sess-user-kill]').forEach(b=>b.addEventListener('click',()=>{
    const u=(SESS_USERS.users||[]).find(x=>String(x.id)===String(b.dataset.sessUserKill));
    if(!u)return;
    if(!confirm('End every session of "'+u.user+'"? That account will have to sign in again.'))return;
    sessBulk('revoke_all',{user_id:u.id});
  }));
}
function esc0(v){return sessEsc(v==null?0:v);}
async function sessUsersLoad(force){
  const list=document.getElementById('sessUsersList');
  if(!list)return;
  list.innerHTML='<div style="padding:20px;color:var(--t2);font-size:12px">Loading…</div>';
  let d;
  try{d=await sessCall('users',force?{rescan:1}:null);}
  catch(e){list.innerHTML='<div style="padding:20px;color:#f87171;font-size:13px">Could not connect.</div>';return;}
  if(d.error){list.innerHTML='<div style="padding:20px;color:#f87171;font-size:13px">'+sessEsc(d.error)+'</div>';return;}
  SESS_USERS=d;
  sessUsersRender();
}
async function sessBulk(action,extra){
  const d=await sessCall(action,extra||{});
  if(d&&d.error){toast(d.error);return;}
  toast((d&&d.notice)||'Done.');
  SESS_USER_FILTER=null;
  sessLoad(true);
  sessUsersLoad(true);
}
document.getElementById('sessBtn')?.addEventListener('click',()=>{
  const i=document.getElementById('sessCfgPath');if(i)i.value=sessCfgGet();
  openMod('sessOv');sessLoad();
});
document.getElementById('sessTabSessions')?.addEventListener('click',()=>sessSetTab('sessions'));
document.getElementById('sessTabUsers')?.addEventListener('click',()=>sessSetTab('users'));
document.getElementById('sessUsersRefresh')?.addEventListener('click',()=>sessUsersLoad(true));
document.getElementById('sessUsersSearch')?.addEventListener('input',sessUsersRender);
document.getElementById('sessCleanup')?.addEventListener('click',()=>{
  if(!confirm('Delete every expired session? Sessions that still work are not touched.'))return;
  sessBulk('cleanup_expired');
});
document.getElementById('sessKillAll')?.addEventListener('click',()=>{
  if(!confirm('End every session of every site user? All of them will have to sign in again. Your file manager sign-in is not affected.'))return;
  sessBulk('revoke_everyone');
});
document.getElementById('sessCfgUse')?.addEventListener('click',()=>{
  const v=(document.getElementById('sessCfgPath')?.value||'').trim();
  if(!v){toast('Enter the full path to wp-config.php or configuration.php, or press Auto-detect.');return;}
  sessCfgSet(v);sessLoad(true);
});
document.getElementById('sessCfgAuto')?.addEventListener('click',()=>{
  sessCfgSet('');sessLoad(true);
});
document.getElementById('sessCfgPath')?.addEventListener('keydown',e=>{
  if(e.key==='Enter'){e.preventDefault();document.getElementById('sessCfgUse')?.click();}
});
/* ── Site Files Guard ──────────────────────────────────────────────────────
   Talks to ?x=guard. The list shows every file this tool installed in a site,
   its state, and one action per row (versions / unguard). */
let SFG_DATA=null, SFG_SEL=null;
async function sfgCall(action,extra){
  const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('action',action);
  if(extra)for(const k in extra){if(extra[k]!==undefined&&extra[k]!==null)fd.append(k,String(extra[k]));}
  try{
    const r=await fetch('?x=guard',{method:'POST',body:fd,cache:'no-store'});
    if(r.status===403){toast('Security token rejected. Reload the page.');return null;}
    return await r.json();
  }catch(e){toast('The request failed.');return null;}
}
function sfgNote(msg){
  const out=document.getElementById('sfgOut');
  if(out)out.textContent=msg||'';
  if(msg)toast(msg);
}
function sfgChip(state){
  const ok=state==='ok';
  const color=ok?'#34d399':(String(state).indexOf('repaired')===0?'#60a5fa':'#f87171');
  return '<span style="font-size:10px;padding:1px 6px;border-radius:6px;border:1px solid '+color+';color:'+color+'">'+sessEsc(state)+'</span>';
}
function sfgRender(){
  const d=SFG_DATA;if(!d)return;
  const sm=document.getElementById('sfgSummary');
  if(sm){
    sm.innerHTML='<b style="color:var(--t1)">'+((d.count||0))+'</b> guarded file(s)'
      +' · guard file on WordPress: '+(d.has_sentinel?'<b style="color:#34d399">installed</b>':'<b style="color:#f87171">missing</b>')
      +' · last check: '+(d.last_check?new Date(d.last_check*1000).toLocaleString():'never')
      +'<br>registry: <span style="font-family:monospace">'+sessEsc(d.registry||'')+'</span>';
  }
  const badge=document.getElementById('sfgBadge');
  if(badge){
    const bad=(d.files||[]).filter(f=>f.status!=='ok').length;
    badge.textContent=bad?('· '+bad+' to fix'):'';
    const btn=document.getElementById('sfgBtn');
    if(btn)btn.title=(d.count||0)+' guarded file(s); '+(bad?bad+' need attention':'all intact');
  }
  const box=document.getElementById('sfgList');
  if(!box)return;
  if(!(d.files||[]).length){box.innerHTML='<div style="font-size:12px;color:var(--t3)">Nothing guarded yet - press <b>Adopt site files</b> to register what this tool already installed.</div>';return;}
  box.innerHTML='<table style="width:100%;border-collapse:collapse;font-size:12px">'
    +'<thead><tr style="text-align:left;color:var(--t3);font-size:11px">'
    +'<th style="padding:6px 4px">File</th><th style="padding:6px 4px">Site</th><th style="padding:6px 4px">State</th>'
    +'<th style="padding:6px 4px">Versions</th><th style="padding:6px 4px"></th></tr></thead><tbody>'
    +(d.files||[]).map(f=>'<tr style="border-top:1px solid var(--border)">'
      +'<td style="padding:6px 4px;color:var(--t2)"><b style="color:var(--t1)">'+sessEsc(f.name)+'</b>'
      +'<br><span style="font-family:monospace;font-size:10px;color:var(--t3)">'+sessEsc(f.path)+'</span></td>'
      +'<td style="padding:6px 4px;color:var(--t2)">'+sessEsc(f.type||'-')+'</td>'
      +'<td style="padding:6px 4px">'+sfgChip(f.status)+'</td>'
      +'<td style="padding:6px 4px;color:var(--t2)">'+(f.versions||0)+'</td>'
      +'<td style="padding:6px 4px;white-space:nowrap">'
      +'<button class="btn btn-g" data-sfg-versions="'+sessEsc(f.key)+'" style="font-size:10px;padding:2px 8px">Versions</button> '
      +'<button class="btn btn-g" data-sfg-unguard="'+sessEsc(f.key)+'" style="font-size:10px;padding:2px 8px;color:#f87171">Unguard</button>'
      +'</td></tr>').join('')
    +'</tbody></table>';
  box.querySelectorAll('[data-sfg-versions]').forEach(b=>b.addEventListener('click',()=>sfgShowVersions(b.getAttribute('data-sfg-versions'))));
  box.querySelectorAll('[data-sfg-unguard]').forEach(b=>b.addEventListener('click',async()=>{
    const key=b.getAttribute('data-sfg-unguard');
    const d2=await sfgCall('unguard',{key:key});
    if(!d2)return;
    sfgNote(d2.error||('Removed from the guard: '+(d2.path||key)));
    sfgLoad();
  }));
}
function sfgVersionsHtml(d){
  const rows=(d.versions||[]).map((v,i)=>'<div style="display:flex;gap:8px;align-items:center;font-size:11px;color:var(--t2);padding:3px 0">'
    +'<span style="font-family:monospace;color:var(--t3)">'+sessEsc((v.sha256||'').slice(0,12))+'</span>'
    +'<span>'+(v.at?new Date(v.at*1000).toLocaleString():'-')+'</span>'
    +'<span>'+(v.size||0)+' B</span>'
    +(v.current?'<span style="color:#34d399;font-size:10px">current</span>':'<button class="btn btn-g" data-sfg-restore="'+i+'" style="font-size:10px;padding:1px 8px">Restore</button>')
    +'</div>').join('');
  return '<div style="font-size:11px;color:var(--t3);margin-bottom:4px">'+sessEsc(d.path||'')+'</div>'+(rows||'<div style="font-size:11px;color:var(--t3)">No stored versions yet.</div>');
}
async function sfgShowVersions(key){
  SFG_SEL=key;
  const d=await sfgCall('versions',{key:key});
  if(!d)return;
  const box=document.getElementById('sfgVersions');
  if(!box)return;
  if(d.error){box.innerHTML='<div style="font-size:11px;color:#f87171">'+sessEsc(d.error)+'</div>';return;}
  box.innerHTML='<div style="border:1px solid var(--border);border-radius:10px;padding:10px">'+sfgVersionsHtml(d)+'</div>';
  box.querySelectorAll('[data-sfg-restore]').forEach(b=>b.addEventListener('click',async()=>{
    const r=await sfgCall('restore_version',{key:key,index:b.getAttribute('data-sfg-restore')});
    if(!r)return;
    sfgNote(r.error||('Restored a previous version of '+(r.path||'')));
    sfgLoad();
  }));
}
