  PRIV_STATE=d.state;PRIV_SEL=PRIV_STATE.mode;privRender();
  const note=(d.notice||'Mode updated.')+' Reload the page to update the toolbar state.';
  if(out)out.textContent=note;toast(d.notice||'Mode updated.');
});
