let configInspectorFiles=[],configInspectorSelected=-1,configInspectorText='';
function resetConfigInspectorView(){
  configInspectorFiles=[];configInspectorSelected=-1;configInspectorText='';
  const list=document.getElementById('configInspectorList'),meta=document.getElementById('configInspectorMeta'),pre=document.getElementById('configInspectorPre'),count=document.getElementById('configInspectorCount'),status=document.getElementById('configInspectorStatus'),copy=document.getElementById('configInspectorCopy');
  if(list)list.replaceChildren();
  if(meta)meta.textContent='Select a configuration file to view its contents.';
  if(pre)pre.textContent='Configuration files are read-only in this tool.';
  if(count)count.textContent='';
  if(status)status.textContent='';
  if(copy)copy.disabled=true;
}
function renderConfigInspectorList(){
  const list=document.getElementById('configInspectorList'),count=document.getElementById('configInspectorCount'),filter=(document.getElementById('configInspectorSearch')?.value||'').trim().toLowerCase();
  if(!list)return;
  list.replaceChildren();
  const visible=configInspectorFiles.map((file,index)=>({file,index})).filter(item=>!filter||(item.file.path||'').toLowerCase().includes(filter));
  visible.forEach(({file,index})=>{
    const button=document.createElement('button');button.type='button';button.className='config-inspector-item';button.dataset.index=String(index);button.title=file.path||file.name;
    button.style.cssText='display:flex;flex-direction:column;align-items:flex-start;gap:3px;width:100%;padding:10px 12px;border:0;border-bottom:1px solid var(--border);background:transparent;color:var(--t2);text-align:left;cursor:pointer;font:inherit';
    const name=document.createElement('strong');name.textContent=file.name||'Configuration file';name.style.cssText='font-size:11.5px;color:var(--t1);font-weight:650;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
    const path=document.createElement('span');path.textContent=file.directory||file.path||'';path.style.cssText='font-size:10px;color:var(--t3);max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
    const size=document.createElement('span');size.textContent=file.too_large?'Over 2 MB preview limit':formatBytes(file.size||0);size.style.cssText='font-size:9.5px;color:'+(file.too_large?'#fca5a5':'var(--t3)');
    button.append(name,path,size);
    if(index===configInspectorSelected)button.style.background='var(--hov)';
    button.addEventListener('click',()=>loadConfigInspectorFile(index));
    list.appendChild(button);
  });
  if(!visible.length){
    const empty=document.createElement('div');empty.textContent=configInspectorFiles.length?'No files match this filter.':'No configuration files found in the accessible folders.';
    empty.style.cssText='padding:22px 12px;text-align:center;font-size:11px;color:var(--t3)';list.appendChild(empty);
  }
  if(count)count.textContent=(configInspectorSelected>=0?(configInspectorSelected+1)+' / ':'')+configInspectorFiles.length+' files';
}
async function loadConfigInspectorFile(index){
  const file=configInspectorFiles[index];if(!file)return;
  configInspectorSelected=index;configInspectorText='';renderConfigInspectorList();
  const meta=document.getElementById('configInspectorMeta'),pre=document.getElementById('configInspectorPre'),copy=document.getElementById('configInspectorCopy');
  if(meta)meta.textContent=file.path||file.name;
  if(pre)pre.textContent='Reading configuration file…';
  if(copy)copy.disabled=true;
  try{
    const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('path_b64',file.path_b64||'');
    const response=await fetch('?x=configread',{method:'POST',body:fd,cache:'no-store',credentials:'same-origin'});
    const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.error||'Could not read this configuration file.');
    configInspectorText=decodeBase64Text(data.content_b64||'');
    if(pre)pre.textContent=configInspectorText;
    if(meta)meta.textContent=(data.path||file.path)+' · '+formatBytes(data.size||0)+' · '+(data.modified?new Date(data.modified*1000).toLocaleString():'');
    if(copy)copy.disabled=false;
  }catch(error){
    if(pre)pre.textContent=String(error.message||error);
  }
}
async function loadConfigInspector(){
  const list=document.getElementById('configInspectorList'),pre=document.getElementById('configInspectorPre'),status=document.getElementById('configInspectorStatus'),meta=document.getElementById('configInspectorMeta');
  if(list)list.innerHTML='<div style="text-align:center;padding:24px 12px;color:var(--t3);font-size:12px">Searching accessible folders…</div>';
  if(pre)pre.textContent='Searching for WordPress, Joomla, .env, PHP, and common application configuration files…';
  if(meta)meta.textContent='Scanning accessible folders…';
  if(status)status.textContent='Searching…';
  configInspectorFiles=[];configInspectorSelected=-1;configInspectorText='';
  const copy=document.getElementById('configInspectorCopy');if(copy)copy.disabled=true;
  try{
    const response=await fetch('?x=configfiles',{cache:'no-store',credentials:'same-origin'});
    const data=await response.json();if(!response.ok||data.error)throw new Error(data.error||'Could not search for configuration files.');
    configInspectorFiles=data.files||[];
    if(status)status.textContent=(data.scanned_entries||0).toLocaleString()+' entries checked'+(data.truncated?' · Search limit reached; some folders may not be included.':'');
    renderConfigInspectorList();
    if(configInspectorFiles.length)await loadConfigInspectorFile(0);
    else if(pre)pre.textContent='No supported configuration files were found in the accessible folders.';
  }catch(error){
    if(status)status.textContent='Search failed';
    if(list)list.innerHTML='<div style="padding:20px;color:#fca5a5;font-size:11px">'+esc(String(error.message||error))+'</div>';
    if(pre)pre.textContent='Configuration search failed.';
  }
}
document.getElementById('configInspectorBtn')?.addEventListener('click',()=>{
  openMod('configInspectorOv');loadConfigInspector();
});
document.getElementById('configInspectorClose')?.addEventListener('click',()=>closeMod('configInspectorOv'));
document.getElementById('configInspectorRefresh')?.addEventListener('click',loadConfigInspector);
document.getElementById('configInspectorSearch')?.addEventListener('input',renderConfigInspectorList);
document.getElementById('configInspectorCopy')?.addEventListener('click',()=>{
  if(!configInspectorText)return;
  navigator.clipboard?.writeText(configInspectorText).then(()=>toast('Configuration contents copied.')).catch(()=>toast('Copy failed.'));
});

let rootingScanReport=null,rootingScanBusy=false;
const rootingCategoryLabels={host:'Host & Runtime',php:'PHP Security',privilege:'Privilege Escalation Paths',web:'Web Exposure'};
function resetRootingScanView(){
  rootingScanReport=null;rootingScanBusy=false;
  const results=document.getElementById('rootingScanResults'),title=document.getElementById('rootingOverall'),state=document.getElementById('rootingScanState'),score=document.getElementById('rootingScore'),ring=document.getElementById('rootingScoreRing'),meta=document.getElementById('rootingMeta'),duration=document.getElementById('rootingDuration'),time=document.getElementById('rootingScanTime'),total=document.getElementById('rootingCheckTotal'),run=document.getElementById('rootingScanRun');
  if(results)results.innerHTML='<div class="rooting-empty"><svg viewBox="0 0 24 24"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="M12 7v5l3 2"/></svg><strong>Ready to inspect this server</strong><span>Run a local read-only scan to check configuration, process privileges, file permissions, and exposed web-root indicators.</span></div>';
  if(title)title.textContent='Local privilege-escalation surface';
  if(state)state.textContent='AWAITING LOCAL SCAN';
  if(score)score.textContent='--';
  if(ring){ring.style.strokeDashoffset='314.16';ring.style.stroke='#51dfba';}
  if(meta)meta.textContent='No scan results loaded.';
  if(duration)duration.textContent='No scan performed';
  if(time)time.textContent='NO SCAN DATA';
  if(total)total.textContent='-- CHECKS';
  ['rootingCritical','rootingHigh','rootingReview','rootingUnknown'].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent='-';});
  if(run){run.disabled=false;run.classList.remove('disabled');}
  document.getElementById('rootingScanOv')?.classList.remove('rooting-scan-running');
}
function renderRootingScan(){
  const results=document.getElementById('rootingScanResults');if(!results||!rootingScanReport)return;
  const checks=Array.isArray(rootingScanReport.checks)?rootingScanReport.checks:[];
  const meta=rootingScanReport.meta||{},counts=meta.counts||{};
  const severity=String(meta.overall||'low-indicators');
  const overallLabels={critical:'Critical privilege exposure observed',high:'High-risk indicators observed',elevated:'Exposure indicators need review',review:'Manual review needed', 'low-indicators':'No strong indicators observed'};
  let headline=overallLabels[severity]||'Local privilege-escalation surface';
  if(meta.worker_is_root===true)headline='PHP worker is running as root';
  else if(meta.worker_is_root===false&&severity==='low-indicators')headline='PHP worker is non-root; no strong indicators observed';
  const title=document.getElementById('rootingOverall');if(title)title.textContent=headline;
  const state=document.getElementById('rootingScanState');if(state)state.textContent=meta.worker_is_root===true?'PHP WORKER RUNS AS ROOT':(severity==='low-indicators'?'SCAN COMPLETE · NO STRONG SIGNALS':'SCAN COMPLETE · REVIEW FINDINGS');
  const score=Math.max(0,Math.min(100,Number(meta.score)||0)),scoreEl=document.getElementById('rootingScore'),ring=document.getElementById('rootingScoreRing');
  if(scoreEl)scoreEl.textContent=String(score);
  if(ring){ring.style.strokeDashoffset=String(314.16*(1-score/100));ring.style.stroke=score>=65?'#f06470':(score>=30?'#e5b65b':'#51dfba');}
  const total=document.getElementById('rootingCheckTotal');if(total)total.textContent=(Number(meta.checks_count)||checks.length)+' CHECKS';
  const time=document.getElementById('rootingScanTime');if(time)time.textContent=meta.scanned_at?new Date(meta.scanned_at).toLocaleString():'SCAN COMPLETE';
  const summary=document.getElementById('rootingMeta');if(summary)summary.textContent='Heuristic index · '+checks.length+' checks · local account view';
  const duration=document.getElementById('rootingDuration');if(duration)duration.textContent='Completed in '+((Number(meta.duration_ms)||0)/1000).toFixed(2)+'s';
  const setCount=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=String(Number(value)||0);};
  setCount('rootingCritical',counts.critical);setCount('rootingHigh',counts.high);setCount('rootingReview',counts.review);setCount('rootingUnknown',counts.unknown);
  const category=document.getElementById('rootingCategory')?.value||'all',statusFilter=document.getElementById('rootingStatusFilter')?.value||'all',query=(document.getElementById('rootingSearch')?.value||'').trim().toLowerCase();
  const groups={};
  checks.forEach(check=>{
    const cat=Object.prototype.hasOwnProperty.call(rootingCategoryLabels,check.category)?check.category:'host';
    const status=['good','risk','review','unknown','info'].includes(check.status)?check.status:'unknown';
    const categoryMatch=category==='all'||category===cat,statusMatch=statusFilter==='all'||statusFilter===status;
    const searchable=[check.label,check.value,check.detail,check.evidence,rootingCategoryLabels[cat]].join(' ').toLowerCase();
    if(!categoryMatch||!statusMatch||(query&&!searchable.includes(query)))return;
    (groups[cat]||(groups[cat]=[])).push({...check,category:cat,status});
  });
  const order=['host','php','privilege','web'];
  let html='';
  order.forEach(cat=>{
    const items=groups[cat]||[];if(!items.length)return;
    html+='<section class="rooting-group"><h3 class="rooting-group-title">'+esc(rootingCategoryLabels[cat])+' <span class="rooting-group-count">'+items.length+' SIGNALS</span></h3><div class="rooting-cards">';
    items.forEach(check=>{
      const label=esc(check.label||'System check'),value=esc(check.value||'-'),detail=esc(check.detail||''),evidence=esc(check.evidence||'');
      const tag=check.status==='risk'?(check.severity||'risk'):check.status;
      html+='<article class="rooting-check-card" data-state="'+check.status+'"><div class="rooting-check-head"><span class="rooting-state-dot"></span><strong class="rooting-check-label" title="'+label+'">'+label+'</strong><span class="rooting-check-tag">'+esc(tag)+'</span></div><div class="rooting-check-value">'+value+'</div><p class="rooting-check-detail">'+detail+'</p>'+(evidence?'<div class="rooting-check-evidence">'+evidence+'</div>':'')+'</article>';
    });
    html+='</div></section>';
  });
  results.innerHTML=html||'<div class="rooting-empty"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><strong>No checks match these filters</strong><span>Change the search text or select a different category or result status.</span></div>';
}
async function runRootingScan(){
  if(rootingScanBusy)return;
  rootingScanBusy=true;
  const modal=document.getElementById('rootingScanOv'),run=document.getElementById('rootingScanRun'),results=document.getElementById('rootingScanResults'),state=document.getElementById('rootingScanState'),title=document.getElementById('rootingOverall'),meta=document.getElementById('rootingMeta'),duration=document.getElementById('rootingDuration');
  modal?.classList.add('rooting-scan-running');
  if(run){run.disabled=true;run.textContent='Scanning…';}
  if(state)state.textContent='READING LOCAL INDICATORS';
  if(title)title.textContent='Inspecting PHP and host-visible settings';
  if(meta)meta.textContent='No files are changed. No commands or exploit attempts are run.';
  if(duration)duration.textContent='Scan in progress…';
  if(results)results.innerHTML='<div class="rooting-empty"><svg viewBox="0 0 24 24"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="M12 7v5l3 2"/></svg><strong>Scanning local indicators</strong><span>Checking PHP settings, worker privileges, host-visible permissions, and web-root filenames. This scan does not run system commands.</span></div>';
  try{
    const fd=new FormData();fd.append('csrf_token',CSRF);
    const response=await fetch('?x=rootingscan',{method:'POST',body:fd,cache:'no-store',credentials:'same-origin'});
    const data=await response.json();if(!response.ok||data.error)throw new Error(data.error||'The local scan could not be completed.');
    rootingScanReport=data;renderRootingScan();
  }catch(error){
    if(title)title.textContent='Scan unavailable';
    if(state)state.textContent='LOCAL SCAN ERROR';
    if(meta)meta.textContent=String(error.message||error);
    if(duration)duration.textContent='No report was returned';
    if(results)results.innerHTML='<div class="rooting-empty rooting-scan-error"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M12 8v5M12 16h.01"/></svg><strong>Could not read the local report</strong><span>'+esc(String(error.message||error))+'</span></div>';
  }finally{
    rootingScanBusy=false;modal?.classList.remove('rooting-scan-running');
    if(run){run.disabled=false;run.innerHTML='<svg viewBox="0 0 24 24"><path d="M20 7v5h-5"/><path d="M4.93 9A8 8 0 0 1 19.07 6L20 7M4 17v-5h5"/><path d="M19.07 15A8 8 0 0 1 4.93 18L4 17"/></svg>Run scan';}
  }
}
document.getElementById('rootingScanBtn')?.addEventListener('click',()=>{
  openMod('rootingScanOv');runRootingScan();
});
document.getElementById('rootingScanRun')?.addEventListener('click',runRootingScan);
document.getElementById('rootingScanClose')?.addEventListener('click',()=>closeMod('rootingScanOv'));
document.getElementById('rootingSearch')?.addEventListener('input',renderRootingScan);
document.getElementById('rootingCategory')?.addEventListener('change',renderRootingScan);
document.getElementById('rootingStatusFilter')?.addEventListener('change',renderRootingScan);

/* ═══════════════════════════════════════
   SSH ACCESS (admin)
═══════════════════════════════════════ */
/* ═══════════════════════════════════════
   SSH ACCESS - tabs: Server Status | User Management
═══════════════════════════════════════ */
let sshActiveTab='status';

document.getElementById('sshBtn')?.addEventListener('click',()=>{
  openMod('sshOv');
  sshSwitchTab(sshActiveTab);
});
document.getElementById('sshClose')?.addEventListener('click',()=>closeMod('sshOv'));

// Tab switching
document.querySelectorAll('.ssh-tab-btn').forEach(btn=>{
  btn.addEventListener('click',()=>sshSwitchTab(btn.dataset.tab));
});

function sshSwitchTab(tab){
  sshActiveTab=tab;
  document.querySelectorAll('.ssh-tab-btn').forEach(b=>{
    const active=b.dataset.tab===tab;
    b.style.color=active?'#85898C':'var(--t3)';
    b.style.borderBottomColor=active?'#85898C':'transparent';
  });
  document.getElementById('sshBody').style.display     = tab==='status'?'':'none';
  document.getElementById('sshUsersBody').style.display= tab==='users' ?'':'none';
  if(tab==='status')  loadSshStatus();
  if(tab==='users')   loadSshUsers();
}

/* ── Server Status tab ── */
async function loadSshStatus(){
  document.getElementById('sshBody').innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Checking…</div>';
  try{
    const d=await fetch('?x=sshstatus').then(r=>r.json());
    if(d.error){document.getElementById('sshBody').innerHTML='<div class="empty" style="padding:40px"><p>'+esc(d.error)+'</p></div>';return;}
    const checkIco=()=>'<svg viewBox="0 0 24 24" style="width:12px;height:12px;stroke:currentColor;fill:none;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;vertical-align:-1px;margin-left:3px"><polyline points="20 6 9 17 4 12"/></svg>';
    const row=(l,v,ok)=>`<div class="info-c"><div class="info-cl">${l}</div><div class="info-cv" style="color:${ok?'#86efac':'#fca5a5'}">${v}</div></div>`;
    let html=`<div class="info-g" style="grid-template-columns:1fr 1fr">
      ${row('SSH Server',d.installed?'Installed'+checkIco():'Not installed',d.installed)}
      ${row('SSH Client',d.client?'Available'+checkIco():'Not found',d.client)}
      ${row('Running / Port 22',d.running?'Active'+checkIco():'Not running',d.running)}
      ${row('Package Manager',d.pkg_mgr||'None detected',!!d.pkg_mgr)}
    </div>`;
    if(d.server_ip){
      const ipOk=d.server_ip_external&&d.server_ip_reachable;
      html+=`<div style="margin-top:14px;padding:12px 14px;background:rgba(133,137,140,.08);border:1px solid rgba(133,137,140,.25);border-radius:10px">
        <div style="font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--t3);margin-bottom:4px">Connect using</div>
        <div style="font-family:monospace;font-size:15px;font-weight:700;color:#C7C8C8">ssh user@${esc(d.server_ip)}</div>
        <div style="font-size:11.5px;color:var(--t3);margin-top:4px">${ipOk?'Detected via '+esc(d.server_ip_method)+' and confirmed reachable on port 22.':(d.server_ip_external?'Detected via '+esc(d.server_ip_method)+' - port 22 did not answer directly on this address; verify sshd is listening on it.':'No external network interface was detected - this address only works for connections made from the same machine.')}</div>
      </div>`;
    } else {
      html+=`<div style="margin-top:14px;padding:12px 14px;background:rgba(252,165,165,.08);border:1px solid rgba(252,165,165,.25);border-radius:10px;font-size:12px;color:#fca5a5">Could not determine a usable server IP address for SSH. Check the server's network configuration.</div>`;
    }
    if(d.installed){
      html+=`<div style="margin-top:14px;padding:12px 14px;background:rgba(134,239,172,.07);border:1px solid rgba(134,239,172,.2);border-radius:10px;font-size:12px;color:#86efac">SSH is installed and ready. Use the <strong>User Management</strong> tab to manage who can connect.</div>`;
    } else {
      html+=`<div style="margin-top:14px;font-size:11.5px;color:var(--t3)">${d.pkg_mgr?'You can attempt an automatic install below (requires root privileges).':'No supported package manager found - ask your host to enable SSH.'}</div>`;
      if(d.pkg_mgr)html+=`<button type="button" id="sshInstallBtn" class="btn btn-p" style="width:100%;margin-top:12px">Install OpenSSH Server</button>`;
    }
    document.getElementById('sshBody').innerHTML=html;
    document.getElementById('sshInstallBtn')?.addEventListener('click',async()=>{
      if(!confirm('Install OpenSSH server? This requires root privileges.'))return;
      document.getElementById('sshBody').innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Installing…</div>';
      const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('action','ssh_install');
      await fetch('',{method:'POST',body:fd}).catch(()=>{});
      toast('Install attempted - check the banner for result.');location.reload();
    });
  }catch{document.getElementById('sshBody').innerHTML='<div style="padding:20px;color:#fca5a5">Failed to check SSH status.</div>';}
}

/* ── User Management tab ── */
function sshOpenBrowserTerminal(username){
  const url=new URL(location.href);
  url.search='';url.hash='';
  url.searchParams.set('terminal','1');
  url.searchParams.set('ssh_user',username);
  let tab=null;
  try{tab=window.open(url.toString(),'_blank');}catch{}
  if(tab){tab.opener=null;toast('Opened the browser terminal as '+username+'.',3500);return;}
  // Mobile browsers and embedded webviews often block a second tab. Continue
  // in the current tab so Login as still works from the original user gesture.
  location.assign(url.toString());
}

function sshLoginChoiceDialog(username,host){
  document.getElementById('sshLoginChoiceOv')?.remove();
  const ov=document.createElement('div');
  ov.className='mod-ov open';ov.id='sshLoginChoiceOv';
  ov.innerHTML=`<div class="mod mod-md" role="dialog" aria-modal="true" aria-labelledby="sshLoginChoiceTitle">
    <div class="mod-head"><div class="mod-icon"><svg viewBox="0 0 24 24"><circle cx="8" cy="15" r="5"/><path d="M21 2l-9.6 9.6M15.5 7.5l3 3L22 7l-3-3"/></svg></div><span class="mod-title" id="sshLoginChoiceTitle">SSH options - ${esc(username)}</span><button type="button" class="btn btn-icon btn-g" data-close><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button></div>
    <div class="mod-body" style="display:flex;flex-direction:column;gap:10px">
      <div style="font-size:12px;color:var(--t2);line-height:1.6">The Login as button opens the browser terminal immediately without asking for this account's password. These options are for other SSH connection methods.</div>
      <button type="button" class="btn btn-s" data-choice="browser" ${RO?'disabled':''} style="justify-content:flex-start;padding:11px 12px"><svg viewBox="0 0 24 24"><polyline points="4 17 10 11 4 5"/><line x1="12" y1="19" x2="20" y2="19"/></svg><span style="text-align:left"><strong>Terminal inside this browser</strong><small style="display:block;color:var(--t3);font-weight:400;margin-top:3px">Runs as the Linux account if server permissions allow; interactive TTY programs may not work.</small></span></button>
      <button type="button" class="btn btn-s" data-choice="local" ${host?'':'disabled'} style="justify-content:flex-start;padding:11px 12px"><svg viewBox="0 0 24 24"><rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8M12 17v4M7 8l3 3-3 3M13 14h4"/></svg><span style="text-align:left"><strong>Open this device's SSH app (may ask for password)</strong><small style="display:block;color:var(--t3);font-weight:400;margin-top:3px">Uses existing keys only; this option does not install a key on the device.</small></span></button>
      <button type="button" class="btn btn-s" data-choice="setup" ${host&&!RO?'':'disabled'} style="justify-content:flex-start;padding:11px 12px"><svg viewBox="0 0 24 24"><path d="M12 3v12m0 0 4-4m-4 4-4-4"/><path d="M5 17v3a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-3"/></svg><span style="text-align:left"><strong>Set up passwordless SSH for this device</strong><small style="display:block;color:var(--t3);font-weight:400;margin-top:3px">Creates and installs a key, then downloads launchers. Extract the ZIP and run the matching launcher, not the regular SSH app.</small></span></button>
      <button type="button" class="btn btn-s" data-choice="revoke" ${RO?'disabled':''} style="justify-content:flex-start;padding:9px 12px;color:#fca5a5;border-color:rgba(239,68,68,.3)"><svg viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m3 0-1 14H6L5 6"/><path d="M10 11v5m4-5v5"/></svg>Revoke File Manager-created login keys</button>
      <div style="font-size:10.5px;color:var(--t3);line-height:1.5">The setup ZIP contains an unencrypted private key. Keep it private. The browser cannot launch programs on your device, so run the downloaded launcher once after extracting it.</div>
    </div></div>`;
  document.body.appendChild(ov);
  const close=()=>ov.remove();
  ov.querySelector('[data-close]')?.addEventListener('click',close);
  ov.addEventListener('click',ev=>{if(ev.target===ov)close();});
  ov.querySelector('[data-choice="browser"]')?.addEventListener('click',()=>{
    sshOpenBrowserTerminal(username);
    close();
  });
  ov.querySelector('[data-choice="local"]')?.addEventListener('click',async()=>{
    if(!host)return;
    const command=`ssh ${username}@${host}`;
    let copied=false;
    try{await navigator.clipboard.writeText(command);copied=true;}catch{
      const clip=document.createElement('textarea');clip.value=command;clip.setAttribute('readonly','');clip.style.position='fixed';clip.style.left='-9999px';document.body.appendChild(clip);clip.select();
      try{copied=document.execCommand('copy');}catch{}clip.remove();
    }
    toast('This opens the existing SSH app and may ask for a password. For passwordless access, use “Set up passwordless SSH for this device”.',7000);
    location.href='ssh://'+encodeURIComponent(username)+'@'+host;
    close();
  });
  ov.querySelector('[data-choice="setup"]')?.addEventListener('click',async()=>{
    if(!host)return;
    if(!window.isSecureContext){toast('Passwordless key setup requires a secure HTTPS connection.',5000);return;}
    if(!confirm('Create a permanent passwordless SSH key for '+username+'? Anyone who gets the downloaded ZIP can sign in as this account.'))return;
    const btn=ov.querySelector('[data-choice="setup"]');btn.disabled=true;btn.querySelector('strong').textContent='Preparing secure connection…';
    try{
      const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('ssh_user',username);
      const r=await fetch('?x=ssh_login_setup',{method:'POST',body:fd,cache:'no-store'});
      const type=r.headers.get('content-type')||'';
      if(!r.ok||!type.includes('application/zip')){
        const data=await r.json().catch(()=>({}));throw new Error(data.error||'Could not prepare the SSH package.');
      }
      const blob=await r.blob();
      if(blob.size<22)throw new Error('The SSH package was empty.');
      const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ssh-login-'+username+'.zip';document.body.appendChild(a);a.click();a.remove();
      setTimeout(()=>URL.revokeObjectURL(a.href),30000);
      toast('Connection ZIP downloaded. Extract it, then open the Windows or Linux launcher. Keep the key private.',7000);
      close();loadSshUsers();
    }catch(err){toast(err.message||'SSH setup failed.',6000);btn.disabled=false;btn.querySelector('strong').textContent='Prepare passwordless SSH for this device';}
  });


  ov.querySelector('[data-choice="revoke"]')?.addEventListener('click',async()=>{
    if(!confirm('Revoke every File Manager-created SSH login key for '+username+'? Existing keys added elsewhere will not be touched.'))return;
    const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('ssh_user',username);
    try{
      const r=await fetch('?x=ssh_login_revoke',{method:'POST',body:fd});
      const data=await r.json();
      if(!r.ok||data.error)throw new Error(data.error||'Could not revoke the generated keys.');
      toast('Revoked '+data.removed+' File Manager-created SSH key(s).');close();loadSshUsers();
    }catch(err){toast(err.message||'Key revocation failed.',5000);}
  });
}

async function loadSshUsers(){
  const el=document.getElementById('sshUsersBody');
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Loading users…</div>';
  try{
    const [users,sshStatus]=await Promise.all([
      fetch('?x=sshusers').then(r=>r.json()),
      fetch('?x=sshstatus').then(r=>r.json()).catch(()=>null)
    ]);
    if(users.error){el.innerHTML='<div class="empty" style="padding:32px"><p>'+esc(users.error)+'</p></div>';return;}
    if(!users.length){el.innerHTML='<div class="empty" style="padding:32px"><p>No user accounts found.</p></div>';return;}
    const sshHost=sshStatus&&!sshStatus.error&&sshStatus.server_ip_external&&sshStatus.server_ip&&sshStatus.installed&&sshStatus.running
      ?String(sshStatus.server_ip):'';

    let rows=users.map(u=>{
      const shellShort=u.shell.split('/').pop();
      const noInteractiveShell=['nologin','false','sync','halt','shutdown',''].includes(shellShort);
      const loginDisabled=!!u.locked||noInteractiveShell||RO;
      const loginTitle=RO?'Read-only account: terminal execution is disabled.':
        u.locked?'Unlock this account before connecting.':
        noInteractiveShell?'This account does not have an interactive shell.':
        'Open the browser terminal immediately as this Linux account without entering its password.';
      const sudoBadge=u.sudo?`<span style="background:rgba(239,68,68,.15);color:#fca5a5;padding:1px 7px;border-radius:20px;font-size:10px;font-weight:700">SUDO</span>`:'';
      const lockBadge=u.locked?`<span style="background:rgba(251,146,60,.12);color:#fb923c;padding:1px 7px;border-radius:20px;font-size:10px;font-weight:700">LOCKED</span>`:
        `<span style="background:rgba(134,239,172,.1);color:#86efac;padding:1px 7px;border-radius:20px;font-size:10px;font-weight:700">ACTIVE</span>`;
      const keyBadge=u.key_count>0?`<span style="background:rgba(133,137,140,.1);color:#85898C;padding:1px 7px;border-radius:20px;font-size:10px;display:inline-flex;align-items:center;gap:3px"><svg viewBox="0 0 24 24" style="width:10px;height:10px;stroke:currentColor;fill:none;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round"><circle cx="7.5" cy="15.5" r="5.5"/><path d="M21 2l-9.6 9.6"/><path d="M15.5 7.5l3 3L22 7l-3-3"/></svg> ${u.key_count}</span>`:'';
      return `<tr>
        <td style="padding:10px 14px">
          <div style="font-weight:600;color:var(--t1)">${esc(u.username)}</div>
          <div style="font-size:11px;color:var(--t3)">UID ${u.uid} · ${esc(shellShort)}</div>
        </td>
        <td style="padding:10px 8px">${lockBadge}</td>
        <td style="padding:10px 8px">${sudoBadge}</td>
        <td style="padding:10px 8px">${keyBadge}</td>
        <td style="padding:10px 14px;text-align:right">
          <button class="btn btn-s ssh-login-btn" data-u="${esc(u.username)}" title="${esc(loginTitle)}" ${loginDisabled?'disabled':''} style="font-size:11px;padding:4px 10px">Login as</button>
          <button class="btn btn-s ssh-options-btn" data-u="${esc(u.username)}" data-host="${esc(sshHost)}" title="Passwordless SSH setup and key revocation" style="font-size:11px;padding:4px 8px"><svg viewBox="0 0 24 24" style="width:13px;height:13px;vertical-align:-2px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round"><circle cx="7.5" cy="15.5" r="5.5"/><path d="M21 2l-9.6 9.6M15.5 7.5l3 3L22 7l-3-3"/></svg> Keys</button>
          <button class="btn btn-s ssh-edit-btn" data-u='${JSON.stringify(u).replace(/'/g,"&#39;")}' style="font-size:11px;padding:4px 10px">Manage</button>
          <button class="btn btn-s ssh-del-btn" data-u="${esc(u.username)}" style="font-size:11px;padding:4px 10px;margin-left:4px;color:#fca5a5;border-color:rgba(239,68,68,.3)">Delete</button>
        </td>
      </tr>`;
    }).join('');

    el.innerHTML=`
      <div style="padding:14px 18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--b2)">
        <span style="font-size:13px;color:var(--t2)">${users.length} system user${users.length!==1?'s':''}</span>
        <button id="sshAddUserBtn" class="btn btn-p" style="font-size:12px;padding:6px 14px">${fmSvgIcon('plus',13)} New User</button>
      </div>
      <div style="overflow:auto;max-height:360px">
      <table style="width:100%;border-collapse:collapse">
        <thead><tr style="font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;color:var(--t3);border-bottom:1px solid var(--b2)">
          <th style="padding:8px 14px;text-align:left">Account</th>
          <th style="padding:8px 8px;text-align:left">Status</th>
          <th style="padding:8px 8px;text-align:left">Sudo</th>
          <th style="padding:8px 8px;text-align:left">Keys</th>
          <th style="padding:8px 14px;text-align:right">Actions</th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table></div>`;

    // Add user button
    document.getElementById('sshAddUserBtn').addEventListener('click',()=>{
      document.getElementById('sshAddUser').value='';document.getElementById('sshAddPass').value='';
      document.getElementById('sshAddKey').value='';document.getElementById('sshAddSudo').checked=false;
      document.getElementById('sshAddShell').value='/bin/bash';
      openMod('sshAddOv');
    });

    // Manage / edit button
    el.querySelectorAll('.ssh-edit-btn').forEach(btn=>{
      btn.addEventListener('click',()=>{
        const u=JSON.parse(btn.dataset.u.replace(/&#39;/g,"'"));
        document.getElementById('sshEditUser').value=u.username;
        document.getElementById('sshEditTitle').textContent='Manage: '+u.username;
        document.getElementById('sshEditShell').value=u.shell||'/bin/bash';
        document.getElementById('sshEditPass').value='';document.getElementById('sshEditKey').value='';
        // sudo toggle button
        const sudoBtn=document.getElementById('sshEditSudoBtn');
        if(u.sudo){sudoBtn.textContent='Remove Sudo';sudoBtn.dataset.action='remove_sudo';sudoBtn.style.color='#fca5a5';sudoBtn.style.borderColor='rgba(239,68,68,.3)';}
        else{sudoBtn.textContent='Grant Sudo';sudoBtn.dataset.action='add_sudo';sudoBtn.style.color='#86efac';sudoBtn.style.borderColor='rgba(134,239,172,.3)';}
        // lock/unlock button
        const lockBtn=document.getElementById('sshEditLockBtn');
        if(u.locked){lockBtn.textContent='Unlock Account';lockBtn.dataset.action='unlock';lockBtn.style.color='#86efac';lockBtn.style.borderColor='rgba(134,239,172,.3)';}
        else{lockBtn.textContent='Lock Account';lockBtn.dataset.action='lock';lockBtn.style.color='#fb923c';lockBtn.style.borderColor='rgba(251,146,60,.3)';}
        openMod('sshEditOv');
      });
    });

    el.querySelectorAll('.ssh-login-btn:not(:disabled)').forEach(btn=>{
      btn.addEventListener('click',()=>sshOpenBrowserTerminal(btn.dataset.u||''));
    });
    el.querySelectorAll('.ssh-options-btn').forEach(btn=>{
      btn.addEventListener('click',()=>sshLoginChoiceDialog(btn.dataset.u||'',btn.dataset.host||''));
    });

    // Delete button
    el.querySelectorAll('.ssh-del-btn').forEach(btn=>{
      btn.addEventListener('click',async()=>{
        const uname=btn.dataset.u;
        if(!confirm(`Delete system user "${uname}"? This will remove their home directory too.`))return;
        const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('action','ssh_delete_user');fd.append('ssh_user',uname);
        const r=await sshPost(fd);
        if(!r.ok&&r.text){alert(r.text);return;}
        loadSshUsers();
      });
    });

  }catch(e){el.innerHTML='<div style="padding:20px;color:#fca5a5">Failed to load users: '+esc(String(e))+'</div>';}
}

/* ── Shared helpers ── */

/** POST and parse the PHP flash message from the response HTML.
 *  Returns {ok:bool, text:string, type:'success'|'danger'|'warning'} */
async function sshPost(fd){
  try{
    const resp=await fetch('',{method:'POST',body:fd});
    const html=await resp.text();
    const doc=new DOMParser().parseFromString(html,'text/html');
    const alert=doc.querySelector('.alert');
    if(!alert)return{ok:true,text:'',type:'success'};
    // extract text without the SVG icon
    const clone=alert.cloneNode(true);
    clone.querySelectorAll('svg').forEach(s=>s.remove());
    const text=clone.textContent.trim();
    const type=alert.classList.contains('danger')?'danger':
                alert.classList.contains('warning')?'warning':'success';
    return{ok:type==='success'||type==='warning',text,type};
  }catch(e){return{ok:false,text:'Network error: '+e.message,type:'danger'};}
}

/** Render a coloured feedback bar inside a modal element */
function sshShowMsg(containerId, text, type){
  let bar=document.getElementById(containerId);
  if(!bar)return;
  const colors={
    success:{bg:'rgba(134,239,172,.1)',border:'rgba(134,239,172,.3)',color:'#86efac'},
    warning:{bg:'rgba(251,191,36,.08)',border:'rgba(251,191,36,.25)',color:'#fcd34d'},
    danger :{bg:'rgba(239,68,68,.1)',  border:'rgba(239,68,68,.3)',  color:'#fca5a5'},
  };
  const c=colors[type]||colors.danger;
  bar.innerHTML=`<div style="margin-bottom:12px;padding:10px 14px;border-radius:8px;font-size:12.5px;line-height:1.5;
    background:${c.bg};border:1px solid ${c.border};color:${c.color}">${esc(text)}</div>`;
}

/* ── Add user form ── */
document.getElementById('sshAddClose')?.addEventListener('click',()=>closeMod('sshAddOv'));
document.getElementById('sshAddApply')?.addEventListener('click',async()=>{
  const uname=document.getElementById('sshAddUser').value.trim();
  if(!uname){sshShowMsg('sshAddFeedback','Username is required.','danger');return;}
  const fd=new FormData();
  fd.append('csrf_token',CSRF);fd.append('action','ssh_create_user');
  fd.append('ssh_user',uname);
  fd.append('ssh_pass',document.getElementById('sshAddPass').value);
  fd.append('ssh_shell',document.getElementById('sshAddShell').value);
  fd.append('ssh_key',document.getElementById('sshAddKey').value);
  if(document.getElementById('sshAddSudo').checked)fd.append('ssh_sudo','1');
  const btn=document.getElementById('sshAddApply');
  btn.textContent='Creating…';btn.disabled=true;
  document.getElementById('sshAddFeedback').innerHTML='';
  const r=await sshPost(fd);
  btn.textContent='Create SSH User';btn.disabled=false;
  if(r.text)sshShowMsg('sshAddFeedback',r.text,r.type);
  if(r.ok&&r.type==='success'){
    setTimeout(()=>{closeMod('sshAddOv');loadSshUsers();},900);
  }
});

/* ── Edit user form ── */
document.getElementById('sshEditClose')?.addEventListener('click',()=>closeMod('sshEditOv'));

async function sshActPost(action,extra={}){
  const uname=document.getElementById('sshEditUser').value;
  const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('action','ssh_update_user');
  fd.append('ssh_user',uname);fd.append('ssh_action',action);
  Object.entries(extra).forEach(([k,v])=>fd.append(k,v));
  document.getElementById('sshEditFeedback').innerHTML='';
  const r=await sshPost(fd);
  if(r.text)sshShowMsg('sshEditFeedback',r.text,r.type);
  if(r.ok&&r.type==='success'){
    setTimeout(()=>{closeMod('sshEditOv');loadSshUsers();},900);
  } else if(r.ok&&r.type==='warning'){
    setTimeout(()=>{closeMod('sshEditOv');loadSshUsers();},900);
  }
}

document.getElementById('sshEditPassBtn')?.addEventListener('click',()=>{
  const p=document.getElementById('sshEditPass').value;
  if(!p||p.length<6){sshShowMsg('sshEditFeedback','Password must be at least 6 characters.','danger');return;}
  sshActPost('change_pass',{ssh_pass:p});
});
document.getElementById('sshEditShellBtn')?.addEventListener('click',()=>{
  sshActPost('change_shell',{ssh_shell:document.getElementById('sshEditShell').value});
});
document.getElementById('sshEditKeyBtn')?.addEventListener('click',()=>{
  const k=document.getElementById('sshEditKey').value.trim();
  if(!k){sshShowMsg('sshEditFeedback','Paste a public key first.','danger');return;}
  sshActPost('add_key',{ssh_key:k});
});
document.getElementById('sshEditSudoBtn')?.addEventListener('click',function(){
  sshActPost(this.dataset.action);
});
document.getElementById('sshEditLockBtn')?.addEventListener('click',function(){
  sshActPost(this.dataset.action);
});

/* ═══════════════════════════════════════
   CMS MANAGER (WordPress / Joomla) - admin
═══════════════════════════════════════ */
/* ═══════════════════════════════════════
   CMS MANAGER - auto-scan + full user CRUD
═══════════════════════════════════════ */
let cmsCurrentCfg=null,cmsCurrentType=null,cmsEditUserId=null,cmsAllRoles=[],cmsQuickPending=false;
let cmsInstallerDbSearching=false,cmsInstallerDbSearchToken=0,cmsInstallerDetectedDbName='';
const cmsInstallerDefaultDir=<?=json_encode($fm->getCwd().DIRECTORY_SEPARATOR.'cms-site',JSON_UNESCAPED_SLASHES)?>;
function fmSvgIcon(name,size=13){
  const paths={
    check:'<path d="m5 12 4 4L19 6"/>',
    close:'<path d="m18 6-12 12M6 6l12 12"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    arrowLeft:'<path d="m15 18-6-6 6-6"/>',
    arrowRight:'<path d="m9 18 6-6-6-6"/>',
    download:'<path d="M12 3v12"/><path d="m7 10 5 5 5-5"/><path d="M4 21h16"/>',
    refresh:'<path d="M20 11a8 8 0 0 0-14.5-4L4 9"/><path d="M4 4v5h5"/><path d="M4 13a8 8 0 0 0 14.5 4L20 15"/><path d="M20 20v-5h-5"/>',
    star:'<path fill="currentColor" stroke="none" d="m12 2 3.1 6.3 6.9 1-5 4.9 1.2 6.8L12 17.8l-6.2 3.2L7 14.2 2 9.3l6.9-1L12 2z"/>',
    folder:'<path d="M3 6h6l2 2h10v11H3z"/>'
  };
  return `<svg aria-hidden="true" viewBox="0 0 24 24" style="width:${size}px;height:${size}px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0;vertical-align:-2px">${paths[name]||''}</svg>`;
}
function cmsInstallerField(label,id,type='text',value='',placeholder='',required=false,disabled=false){
  const extra=id==='cmsInstallAdminPass'?'minlength="10"':'';
  return `<label class="lbl" for="${id}" style="display:block;margin-top:9px">${label}${required?' <span style="color:#fca5a5">*</span>':''}</label><input class="inp" id="${id}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" style="width:100%" ${required?'required':''} ${disabled?'disabled':''} ${extra}>`;
}
function cmsInstallerState(d,type){
  const minimum=type==='joomla'?'8.1':'7.3',current=String(d.php_version||'0').split('.').map(Number);
  const min=minimum.split('.').map(Number);
  const versionOk=(current[0]||0)>min[0]||((current[0]||0)===min[0]&&(current[1]||0)>=min[1]);
  const required=['mysqli','json','openssl',...(type==='joomla'?['mbstring']:[])];
  const available=new Set((d.requirements||[]).filter(x=>x.available).map(x=>x.extension));
  const missing=required.filter(name=>!available.has(name));
  const reasons=[];
  if(!d.installer_available)reasons.push('PHP mysqli or installer write access is unavailable.');
  if(!d.workspace_writable)reasons.push('The File Manager workspace is not writable by PHP.');
  if(!versionOk)reasons.push(`${type==='joomla'?'Joomla':'WordPress'} requires PHP ${minimum} or later.`);
  if(missing.length)reasons.push(`Missing required PHP extensions: ${missing.join(', ')}.`);
  if(d.free_bytes&&d.free_bytes<100*1024*1024)reasons.push('At least 100 MB of free disk space is required.');
  return{minimum,required,available,missing,versionOk,reasons,ok:!!d.installer_available&&!!d.workspace_writable&&versionOk&&!missing.length&&!(d.free_bytes&&d.free_bytes<100*1024*1024)};
}
function cmsInstallerRequirementBadges(d,type,state){
  const phpColor=state.versionOk?'#86efac':'#fca5a5';
  const phpIcon=fmSvgIcon(state.versionOk?'check':'close',11);
  const php=`<span style="display:inline-flex;align-items:center;gap:4px;padding:4px 7px;border-radius:8px;background:${state.versionOk?'rgba(34,197,94,.12)':'rgba(239,68,68,.12)'};color:${phpColor}">${phpIcon}PHP ${esc(d.php_version)} · minimum ${state.minimum}</span>`;
  const badges=(d.requirements||[]).map(x=>{
    const required=state.required.includes(x.extension),available=!!x.available;
    const color=available?'#86efac':(required?'#fca5a5':'var(--t3)');
    const icon=available?fmSvgIcon('check',11):(required?fmSvgIcon('close',11):'');
    const label=required?esc(x.extension):esc(x.extension)+' optional';
    return`<span title="${required?'Required':'Optional'} PHP extension" style="display:inline-flex;align-items:center;gap:4px;padding:4px 7px;border-radius:8px;background:${available?'rgba(34,197,94,.12)':(required?'rgba(239,68,68,.12)':'rgba(125,129,132,.1)')};color:${color}">${icon}${label}</span>`;
  }).join('');
  return php+badges;
}
function cmsInstallerUpdateReadiness(d){
  const type=document.getElementById('cmsInstallType')?.value||'wordpress',state=cmsInstallerState(d,type);
  const checks=document.getElementById('cmsInstallerChecks'),note=document.getElementById('cmsInstallerReady'),btn=document.getElementById('cmsInstallerSubmit');
  if(checks)checks.innerHTML=cmsInstallerRequirementBadges(d,type,state);
  if(note){note.textContent=state.ok?'Server requirements are ready.':state.reasons.join(' ');note.style.color=state.ok?'#86efac':'#fca5a5';note.style.background=state.ok?'rgba(34,197,94,.08)':'rgba(239,68,68,.08)';}
  if(btn){btn.disabled=!state.ok||cmsInstallerDbSearching;btn.textContent=cmsInstallerDbSearching?'Searching database settings…':(state.ok?'Install CMS':'Resolve requirements first');}
  return state;
}
/* Encode the config path as base64 and POST it - never place "wp-config.php"
   literally in a URL or query string, since many hosts' WAF/ModSecurity rules
   block requests that look like an attempt to read that file. */
function cmsB64(s){return btoa(unescape(encodeURIComponent(s)));}
async function cmsPost(op,extra){
  const fd=new FormData();
  fd.append('csrf_token',CSRF);
  fd.append('cfg_b64',cmsB64(cmsCurrentCfg||''));
  if(extra)for(const k in extra)fd.append(k,extra[k]);
   const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),30000);
   let r;
   try{
     r=await fetch('?x='+op,{method:'POST',body:fd,signal:ctl.signal});
   }catch(e){
     if(e&&e.name==='AbortError')throw new Error('The CMS database request timed out after 30 seconds. Check the CMS database settings and server availability.');
     throw e;
   }
   finally{clearTimeout(timer);}
  return r.json();
}

async function cmsInstallerShow(){
  const el=document.getElementById('cmsInstallerBody');
  if(!el)return;
  cmsInstallerDbSearchToken++;cmsInstallerDbSearching=false;cmsInstallerDetectedDbName='';
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Checking PHP, storage, and the current CMS state…</div>';
  try{
    const d=await fetch('?x=cms_installer_status',{cache:'no-store'}).then(r=>r.json());
    if(d.error){el.innerHTML=`<div class="empty" style="padding:32px"><p>${esc(d.error)}</p></div>`;return;}
    const initialState=cmsInstallerState(d,'wordpress');
    const checks=cmsInstallerRequirementBadges(d,'wordpress',initialState);
    const current=d.current_cms&&d.current_cms.type
      ?`<div style="padding:10px 12px;border:1px solid rgba(245,158,11,.35);background:rgba(245,158,11,.08);border-radius:8px;color:#fbbf24;font-size:11px;line-height:1.5;margin-bottom:12px">A ${esc(d.current_cms.type)} installation is already detected in the current directory. It is protected from overwrite. Choose a different empty target directory for a new site.</div>`
      :`<div style="padding:10px 12px;border:1px solid rgba(34,197,94,.28);background:rgba(34,197,94,.08);border-radius:8px;color:#86efac;font-size:11px;line-height:1.5;margin-bottom:12px">No WordPress or Joomla installation was detected in the current directory.</div>`;
    const canInstall=initialState.ok;
    el.innerHTML=`
      <div style="padding:14px 16px;border-bottom:1px solid var(--b2)">
        ${current}
        <div style="display:flex;gap:8px;flex-wrap:wrap;font-size:11px;color:var(--t3)">
          <span>${esc(d.sapi)}</span><span>${esc(d.free_bytes?Math.round(d.free_bytes/1048576)+' MB free':'Free space unavailable')}</span>
        </div>
        <div class="cms-install-badges" id="cmsInstallerChecks">${checks}</div>
        <div id="cmsInstallerReady" role="status" style="margin-top:8px;padding:8px 10px;border-radius:8px;font-size:11px;line-height:1.5;background:${canInstall?'rgba(34,197,94,.08)':'rgba(239,68,68,.08)'};color:${canInstall?'#86efac':'#fca5a5'}">${esc(canInstall?'Server requirements are ready.':initialState.reasons.join(' '))}</div>
      </div>
      <form id="cmsInstallerForm" style="padding:14px 16px">
        <div style="font-size:11px;color:var(--t2);line-height:1.5;margin-bottom:10px">The installer gets the latest official package over HTTPS and never overwrites files. Fill in the site, database, and administrator sections below.</div>
        <section class="cms-install-section">
          <div class="cms-install-section-title">1. Site</div>
          <div class="cms-install-grid">
            <div><label class="lbl" for="cmsInstallType" style="display:block;margin-top:9px">CMS</label><select class="inp" id="cmsInstallType" style="width:100%"><option value="wordpress">WordPress</option><option value="joomla">Joomla</option></select></div>
            <div>${cmsInstallerField('Target directory','cmsInstallDir','text',cmsInstallerDefaultDir,'New, empty directory',true)}</div>
            <div style="grid-column:1/-1">${cmsInstallerField('Site title','cmsInstallTitle','text','My Site','')}</div>
          </div>
          <div style="font-size:10px;color:var(--t3);line-height:1.5;margin-top:6px">Use a new empty folder inside the File Manager workspace. Existing files are never overwritten.</div>
        </section>
        <section class="cms-install-section">
          <div class="cms-install-section-title">2. Database connection</div>
          <div style="font-size:10.5px;color:var(--t3);line-height:1.5">Searching readable CMS/database configuration and environment settings. Only values actually found are used; missing values are not guessed. If a database name is found, it is filled in but requires your confirmation before installation because it may contain an existing site's tables.</div>
          <div id="cmsInstallerDbDiscovery" role="status" aria-live="polite" style="margin-top:9px;padding:9px 10px;border-radius:8px;font-size:10.5px;line-height:1.5;background:rgba(59,130,246,.09);color:#93c5fd"></div>
          <div style="font-size:10.5px;color:var(--t3);line-height:1.5;margin-top:8px">Enter an existing database with permission to create tables, or use an account allowed to create the database. These credentials are written to the CMS configuration after you start installation.</div>
          <div class="cms-install-grid">
            <div>${cmsInstallerField('Database name','cmsInstallDbName','text','','Enter the intended database name',true,true)}</div>
            <div>${cmsInstallerField('Database user','cmsInstallDbUser','text','','Database username',true,true)}</div>
            <div style="grid-column:1/-1">${cmsInstallerField('Database password','cmsInstallDbPass','password','','Database password',false,true)}</div>
          </div>
          <details class="cms-install-advanced">
            <summary>Advanced database settings</summary>
            <div class="cms-install-grid">
              <div>${cmsInstallerField('Database host','cmsInstallDbHost','text','','Read from config or enter manually',false,true)}</div>
              <div>${cmsInstallerField('Database port','cmsInstallDbPort','number','','Read from config or enter manually',false,true)}</div>
              <div>${cmsInstallerField('Table prefix','cmsInstallPrefix','text','wp_','wp_')}</div>
            </div>
          </details>
        </section>
        <section class="cms-install-section">
          <div class="cms-install-section-title">3. Administrator account</div>
          <div style="font-size:10.5px;color:var(--t3);line-height:1.5">Choose the login details you will use to manage this site. The password must contain at least 10 characters.</div>
          <div class="cms-install-grid">
            <div>${cmsInstallerField('Administrator username','cmsInstallAdmin','text','siteadmin','',true)}</div>
            <div>${cmsInstallerField('Administrator password','cmsInstallAdminPass','password','','At least 10 characters',true)}</div>
            <div style="grid-column:1/-1">${cmsInstallerField('Administrator email','cmsInstallEmail','email','','admin@example.com',true)}</div>
          </div>
        </section>
        <div id="cmsInstallerFeedback" style="display:none;margin-top:12px;padding:10px 12px;border-radius:8px;font-size:11px;line-height:1.5"></div>
        <button class="btn btn-p" id="cmsInstallerSubmit" type="submit" style="width:100%;margin-top:4px" disabled>Searching database settings…</button>
      </form>`;
    document.getElementById('cmsInstallType').addEventListener('input',()=>{
      const jo=document.getElementById('cmsInstallType').value.trim().toLowerCase()==='joomla';
      document.getElementById('cmsInstallPrefix').value=jo?'j_':'wp_';
      cmsInstallerUpdateReadiness(d);
    });
    document.getElementById('cmsInstallerForm').addEventListener('submit',cmsInstallerSubmit);
    cmsInstallerRunDbDiscovery(d,true);
  }catch(e){el.innerHTML=`<div style="padding:22px;color:#fca5a5">Could not load installer status: ${esc(String(e))}</div>`;}
}
function cmsInstallerSetDbFieldsDisabled(disabled){
  ['cmsInstallDbName','cmsInstallDbUser','cmsInstallDbPass','cmsInstallDbHost','cmsInstallDbPort'].forEach(id=>{
    const field=document.getElementById(id);if(field)field.disabled=disabled;
  });
}
function cmsInstallerDbNotice(d,message,kind='info',retry=false,spinner=false){
  const box=document.getElementById('cmsInstallerDbDiscovery');if(!box)return;
  const palette={
    waiting:['rgba(59,130,246,.09)','#93c5fd'],
    found:['rgba(34,197,94,.09)','#86efac'],
    manual:['rgba(245,158,11,.09)','#fbbf24'],
    error:['rgba(239,68,68,.09)','#fca5a5']
  }[kind]||['rgba(59,130,246,.09)','#93c5fd'];
  const icon=spinner?fmSvgIcon('refresh',12):fmSvgIcon(kind==='found'?'check':(kind==='error'?'close':'refresh'),12);
  box.style.background=palette[0];box.style.color=palette[1];
  box.innerHTML=`<div style="display:flex;align-items:flex-start;gap:7px"><span class="${spinner?'cms-installer-spin':''}" style="display:inline-flex;margin-top:1px">${icon}</span><span>${message}</span></div>${retry?'<button class="btn btn-s" type="button" id="cmsInstallerDbRetry" style="margin-top:8px;font-size:10px">Search again</button>':''}`;
  document.getElementById('cmsInstallerDbRetry')?.addEventListener('click',()=>cmsInstallerRunDbDiscovery(d,false));
}
async function cmsInstallerRunDbDiscovery(d,allowPrefill=true){
  if(cmsInstallerDbSearching)return;
  const token=++cmsInstallerDbSearchToken;
  cmsInstallerDbSearching=true;cmsInstallerSetDbFieldsDisabled(true);cmsInstallerUpdateReadiness(d);
  cmsInstallerDbNotice(d,'Searching readable database configuration and testing the values found. No database changes are made during this check.','waiting',false,true);
  const fd=new FormData();fd.append('csrf_token',CSRF);
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),75000);
  try{
    const response=await fetch('?x=cms_installer_db_discover',{method:'POST',body:fd,cache:'no-store',signal:controller.signal});
    const result=await response.json();
    if(token!==cmsInstallerDbSearchToken)return;
    if(result.error||!result.ok)throw new Error(result.error||'Database discovery failed.');
    if(result.found&&result.credentials){
      const c=result.credentials;
      const dbNameField=document.getElementById('cmsInstallDbName');
      const useDetectedDbName=allowPrefill||!dbNameField?.value.trim();
      const values={cmsInstallDbHost:c.host,cmsInstallDbPort:c.port,cmsInstallDbUser:c.user,cmsInstallDbPass:c.pass};
      Object.entries(values).forEach(([id,value])=>{
        const field=document.getElementById(id);
        if(field&&(allowPrefill||!field.value.trim()))field.value=String(value??'');
      });
      if(dbNameField&&useDetectedDbName){dbNameField.value=String(result.source_db||'');cmsInstallerDetectedDbName=String(result.source_db||'');}
      const labels={wordpress:'WordPress configuration',joomla:'Joomla configuration',env:'environment settings','my.cnf':'MySQL client settings',drupal:'Drupal configuration',magento1:'Magento configuration',magento2:'Magento configuration',prestashop:'PrestaShop configuration',mediawiki:'MediaWiki configuration'};
      const source=labels[result.source_type]||'database configuration';
      const dbName=result.source_db?` (“${esc(result.source_db)}”)`:'';
      cmsInstallerDbNotice(d,`Found and tested a working MySQL login in ${source}${dbName}. The database name and available connection values were extracted from the configuration or PHP MySQLi settings. This may be an existing site's database; review the table prefix before installing.`,'found');
      if(dbNameField&&cmsInstallerDetectedDbName){
        const confirm=document.createElement('label');
        confirm.style.cssText='display:flex;align-items:flex-start;gap:7px;margin-top:8px;font-size:10px;line-height:1.45;cursor:pointer';
        confirm.innerHTML='<input type="checkbox" id="cmsInstallerUseDetectedDb" style="margin-top:2px"> I intend to use this detected database for the new CMS. If it already contains a site, I will use a unique table prefix.';
        document.getElementById('cmsInstallerDbDiscovery')?.appendChild(confirm);
      }
    }else{
      cmsInstallerDbNotice(d,'No working saved MySQL login was found. No values were guessed. Enter the exact database name and username, then open Advanced database settings for the actual host and port.','manual',true);
    }
  }catch(e){
    if(token!==cmsInstallerDbSearchToken)return;
    const message=e&&e.name==='AbortError'?'Database discovery took too long. You can enter the settings manually or try the search again.':`Could not complete database discovery: ${esc(String(e))}. Enter the settings manually or try again.`;
    cmsInstallerDbNotice(d,message,'error',true);
  }finally{
    clearTimeout(timer);
    if(token===cmsInstallerDbSearchToken){
      cmsInstallerDbSearching=false;cmsInstallerSetDbFieldsDisabled(false);cmsInstallerUpdateReadiness(d);
    }
  }
}
async function cmsInstallerSubmit(ev){
  ev.preventDefault();
  const btn=document.getElementById('cmsInstallerSubmit'),box=document.getElementById('cmsInstallerFeedback');
  const dbName=document.getElementById('cmsInstallDbName')?.value.trim()||'';
  if(cmsInstallerDetectedDbName&&dbName===cmsInstallerDetectedDbName&&!document.getElementById('cmsInstallerUseDetectedDb')?.checked){
    box.style.display='block';box.style.background='rgba(245,158,11,.12)';box.style.color='#fbbf24';
    box.textContent='This detected database may contain an existing site. Confirm its use above, or enter a different database name before installing.';
    return;
  }
  const fd=new FormData();fd.append('csrf_token',CSRF);
  const map={cms_type:'cmsInstallType',target_dir:'cmsInstallDir',site_title:'cmsInstallTitle',db_host:'cmsInstallDbHost',db_port:'cmsInstallDbPort',db_name:'cmsInstallDbName',db_user:'cmsInstallDbUser',db_password:'cmsInstallDbPass',db_prefix:'cmsInstallPrefix',admin_user:'cmsInstallAdmin',admin_password:'cmsInstallAdminPass',admin_email:'cmsInstallEmail'};
  Object.keys(map).forEach(k=>fd.append(k,document.getElementById(map[k]).value));
  btn.disabled=true;btn.textContent='Installing…';box.style.display='block';box.style.background='rgba(59,130,246,.12)';box.style.color='#93c5fd';box.textContent='Downloading and verifying the official package. This can take a few minutes.';
  try{
    const r=await fetch('?x=cms_install',{method:'POST',body:fd});const d=await r.json();
    if(!d.ok){box.style.background='rgba(239,68,68,.12)';box.style.color='#fca5a5';box.textContent=d.error||'Installation failed.';btn.disabled=false;btn.textContent='Install CMS';return;}
    box.style.background=d.complete?'rgba(34,197,94,.12)':'rgba(245,158,11,.12)';box.style.color=d.complete?'#86efac':'#fbbf24';
    const continueLink=d.install_url?`<a class="btn btn-s" href="${esc(d.install_url)}" target="_blank" rel="noopener noreferrer">${fmSvgIcon('arrowRight',12)} Continue setup in CMS</a>`:'';
    const filesLink=d.target?`<a class="btn btn-s" href="?dir=${encodeURIComponent(d.target)}">${fmSvgIcon('folder',12)} Open installed files</a>`:'';
    box.innerHTML=`<div>${esc(d.message||d.warning||'Installation finished.')}</div>${continueLink||filesLink?`<div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:9px">${continueLink}${filesLink}</div>`:''}`;
    btn.textContent=d.complete?'Installed':'Setup files ready';btn.disabled=true;
  }catch(e){box.style.background='rgba(239,68,68,.12)';box.style.color='#fca5a5';box.textContent='Installation request failed: '+String(e);btn.disabled=false;btn.textContent='Install CMS';}
}

document.getElementById('cmsBtn')?.addEventListener('click',()=>{openMod('cmsOv');cmsShowPicker();});
document.getElementById('cmsClose')?.addEventListener('click',()=>closeMod('cmsOv'));
document.getElementById('cmsInstallerBtn')?.addEventListener('click',()=>{openMod('cmsInstallerOv');cmsInstallerShow();});
document.getElementById('cmsInstallerClose')?.addEventListener('click',()=>closeMod('cmsInstallerOv'));

async function cmsQuickLogin(){
  const btn=document.getElementById('cmsQuickBtn');
  if(btn){btn.disabled=true;btn.dataset.oldText=btn.textContent;btn.textContent='Checking…';}
  try{
    const info=await fetch('?x=cms_quick_info',{cache:'no-store'}).then(r=>r.json());
    if(info.error){toast(info.error);return;}
    cmsCurrentCfg=info.config;cmsCurrentType=info.type;window.fmCmsConfig=info.config;window.fmCmsType=info.type;
    if(info.id){
      const fd=new FormData();
      fd.append('csrf_token',CSRF);fd.append('cfg_b64',cmsB64(cmsCurrentCfg));fd.append('cms_id',info.id);
      const d=await fetch('?x=cms_login_as',{method:'POST',body:fd}).then(r=>r.json());
      if(d.error)toast(d.error);
      else{
        const w=window.open(d.url,'_blank');
        if(!w)toast('Popup blocked - allow popups for this site, then try again.');
      }
      return;
    }
    const rd=await cmsPost('cmsroles').catch(()=>({roles:[]}));
    cmsAllRoles=rd.roles||[];
    cmsQuickPending=true;
    await openCmsAdd();
    document.getElementById('cmsAddTitle').textContent='Set up CMS MFM ACC';
    const user=document.getElementById('cmsAddUser');
    user.value='mfmadmin';user.readOnly=true;
    document.getElementById('cmsAddEmailLabel').style.display='none';
    document.getElementById('cmsAddEmail').style.display='none';
    document.getElementById('cmsAddRoleLabel').style.display='none';
    document.getElementById('cmsAddRole').style.display='none';
    document.getElementById('cmsAddHiddenLabel').style.display='none';
    document.getElementById('cmsAddEmail').value='mfmadmin@localhost.local';
    document.getElementById('cmsAddHidden').checked=true;
    const sel=document.getElementById('cmsAddRole');
    if(cmsCurrentType==='wordpress')sel.value='administrator';
    else{
      const admin=[...sel.options].find(o=>/super\s*users|administrator/i.test(o.textContent));
      if(admin)sel.value=admin.value;
    }
    toast('CMS MFM ACC is not configured. Choose a password and confirm creation.');
  }catch(e){toast('CMS quick login failed: '+String(e));}
  finally{
    if(btn){btn.disabled=false;btn.textContent=btn.dataset.oldText||'CMS MFM ACC Login';}
  }
}
document.getElementById('cmsQuickBtn')?.addEventListener('click',cmsQuickLogin);

/* ── Installation picker ──────────────────────────────────────────────────── */
async function cmsShowPicker(){
  const el=document.getElementById('cmsBody');
  el.innerHTML=`<div style="text-align:center;padding:32px;color:var(--t3)">
    <svg viewBox="0 0 24 24" style="width:28px;height:28px;stroke:currentColor;fill:none;stroke-width:1.5;margin-bottom:10px;display:block;margin-inline:auto"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
    Scanning server for WordPress &amp; Joomla installations…</div>`;
  try{
    const scanRes=await fetch('?x=cmsscan').then(r=>r.json());
    if(scanRes.error){el.innerHTML='<div class="empty" style="padding:32px"><p>'+esc(scanRes.error)+'</p></div>';return;}
    const sites=scanRes.sites||[];
    const obdHint=(scanRes.open_basedir&&scanRes.open_basedir.length)
      ?`<div style="padding:10px 16px;background:rgba(244,163,51,.1);border-bottom:1px solid var(--b2);font-size:11px;color:#f4a333;line-height:1.5">This server restricts PHP to certain folders (open_basedir), so the scan could only look inside: <span style="font-family:monospace">${esc(scanRes.open_basedir.join(', '))}</span>. If your CMS lives outside that, use the manual path field below.</div>`
      :'';

    const typeIcon=t=>t==='wordpress'
      ?`<span style="background:rgba(33,117,155,.2);color:#5bc0de;padding:2px 8px;border-radius:20px;font-size:10px;font-weight:700">WordPress</span>`
      :`<span style="background:rgba(244,163,51,.15);color:#f4a333;padding:2px 8px;border-radius:20px;font-size:10px;font-weight:700">Joomla</span>`;

    const cards=sites.map(s=>`
      <div class="cms-site-card" data-cfg="${esc(s.config)}" data-type="${esc(s.type)}"
           style="display:flex;align-items:center;gap:14px;padding:13px 16px;border-bottom:1px solid var(--b2);cursor:pointer;transition:background .15s"
           onmouseover="this.style.background='rgba(255,255,255,.04)'" onmouseout="this.style.background=''">
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:3px">
            ${typeIcon(s.type)}
            <span style="font-size:12px;font-weight:600;color:var(--t1);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(s.dir)}</span>
          </div>
          <div style="font-size:10.5px;color:var(--t3);font-family:monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(s.config)}</div>
          ${s.source?`<div style="font-size:10px;color:var(--t3);opacity:.75;margin-top:2px">found by: ${esc(s.source)}</div>`:''}
        </div>
        <svg viewBox="0 0 24 24" style="width:16px;height:16px;stroke:var(--t3);fill:none;stroke-width:2;flex-shrink:0"><polyline points="9 18 15 12 9 6"/></svg>
      </div>`).join('');

    el.innerHTML=`
      <div style="padding:12px 16px;border-bottom:1px solid var(--b2);display:flex;align-items:center;gap:10px">
        <span style="font-size:12px;color:var(--t2);flex:1">${sites.length} installation${sites.length!==1?'s':''} found</span>
      </div>
      ${obdHint}
      ${sites.length?`<div style="overflow:auto;max-height:42vh">${cards}</div>`
        :'<div class="empty" style="padding:32px"><p>No WordPress or Joomla installations found automatically. Enter the path to the site folder or its config file below.</p></div>'}
      <div style="padding:14px 16px;border-top:1px solid var(--b2)">
        <div style="font-size:11px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.6px;margin-bottom:7px">Manual path to the config file or the site folder</div>
        <div style="display:flex;gap:8px">
          <input type="text" id="cmsManualPath" class="inp" style="flex:1;font-size:12px;font-family:monospace" spellcheck="false"
            placeholder="/var/www/html   or   /var/www/html/wp-config.php">
          <button class="btn btn-p" id="cmsManualBtn" style="white-space:nowrap;font-size:12px">Open</button>
        </div>
      </div>`;

    // Click a discovered site
    el.querySelectorAll('.cms-site-card').forEach(c=>c.addEventListener('click',()=>{
      cmsCurrentCfg=c.dataset.cfg;cmsCurrentType=c.dataset.type;window.fmCmsConfig=cmsCurrentCfg;window.fmCmsType=cmsCurrentType;loadCmsUsers();
    }));
    // Manual path - resolved on the server, so a site folder, a web root or a
    // renamed config file all work, not just the exact file path.
    document.getElementById('cmsManualBtn').addEventListener('click',async()=>{
      const input=document.getElementById('cmsManualPath');
      const btn=document.getElementById('cmsManualBtn');
      const p=(input.value||'').trim();
      if(!p){toast('Enter the path to the site folder or its wp-config.php / configuration.php');return;}
      const old=btn.textContent;btn.disabled=true;btn.textContent='Opening…';
      try{
        const fd=new FormData();
        fd.append('csrf_token',CSRF);fd.append('path',p);
        const r=await fetch('?x=cmsresolve',{method:'POST',body:fd});
        const d=await r.json();
        if(d.error){toast(d.error);return;}
        cmsCurrentCfg=d.config;cmsCurrentType=d.type;
        window.fmCmsConfig=cmsCurrentCfg;window.fmCmsType=cmsCurrentType;
        loadCmsUsers();
      }catch(e){
        toast('Could not resolve that path.');
      }finally{
        btn.disabled=false;btn.textContent=old;
      }
    });
    document.getElementById('cmsManualPath').addEventListener('keydown',e=>{if(e.key==='Enter')document.getElementById('cmsManualBtn').click();});
  }catch(e){el.innerHTML='<div style="padding:20px;color:#fca5a5">Scan failed: '+esc(String(e))+'</div>';}
}

/* ── Users list ───────────────────────────────────────────────────────────── */
async function loadCmsUsers(){
  const el=document.getElementById('cmsBody');
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Loading users…</div>';
  try{
    const d=await cmsPost('cmsusers');
    if(d.error){
      el.innerHTML=`<div style="padding:14px 16px;border-bottom:1px solid var(--b2)">
        <button class="btn btn-s" id="cmsBackBtn2" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Back</button></div>
        <div class="empty" style="padding:32px"><p>${esc(d.error)}</p></div>`;
      document.getElementById('cmsBackBtn2')?.addEventListener('click',cmsShowPicker);return;
    }
    // Pre-fetch roles for the edit form
    const rd=await cmsPost('cmsroles').catch(()=>({roles:[]}));
    cmsAllRoles=rd.roles||[];

    const typeLabel=d.type==='wordpress'?'WordPress':'Joomla';
    const rows=d.users.map(u=>{
      const roleTxt=u.role?String(u.role):'-';
      const blockedBadge=(u.blocked===true)?`<span style="color:#fb923c;font-size:10px;font-weight:700;display:inline-flex;align-items:center;margin-left:4px"><svg viewBox="0 0 24 24" style="width:11px;height:11px;stroke:currentColor;fill:none;stroke-width:2.2;stroke-linecap:round"><circle cx="12" cy="12" r="10"/><line x1="4.93" y1="4.93" x2="19.07" y2="19.07"/></svg></span>`:'';
      return `<tr>
        <td class="mono" style="font-size:11.5px;padding:9px 10px">${u.id}</td>
         <td style="padding:9px 10px;font-weight:600">${esc(u.name)}${blockedBadge}${u.hidden?`<span style="color:#c4b5fd;font-size:10px;font-weight:700;margin-left:4px" title="Hidden from CMS user lists">[hidden]</span>`:''}</td>
        <td style="padding:9px 10px;font-size:11.5px;color:var(--t2)">${esc(u.email||'')}</td>
        <td style="padding:9px 10px"><span style="background:var(--raised);padding:2px 9px;border-radius:20px;font-size:11px">${esc(roleTxt)}</span></td>
        <td style="padding:9px 10px">
          <span class="cms-pw-cell" data-id="${u.id}" data-name="${esc(u.name)}" data-state="hidden"
            style="cursor:pointer;font-family:monospace;font-size:12px;color:var(--t2);display:inline-flex;align-items:center;gap:6px;user-select:none"
            title="Click to reveal the saved password">
            <span class="cms-pw-txt">••••••••</span>
            <svg viewBox="0 0 24 24" style="width:13px;height:13px;stroke:currentColor;fill:none;stroke-width:2;flex-shrink:0"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
          </span>
        </td>
        <td style="padding:9px 10px;text-align:right;white-space:nowrap">
          <button class="btn btn-xs cms-login-btn" data-id="${u.id}" data-name="${esc(u.name)}"
            style="margin-right:4px;font-size:11px" title="Open a new tab already logged in as this user - the account's password is never read or changed">Login as</button>
           <button class="btn btn-xs cms-edit-btn" data-id="${u.id}" data-name="${esc(u.name)}" data-role="${esc(roleTxt)}" data-hidden="${u.hidden?'1':'0'}"
            style="margin-right:4px;font-size:11px">Edit / Change Password</button>
          <button class="btn btn-xs btn-red cms-del-btn" data-id="${u.id}" data-name="${esc(u.name)}"
            style="font-size:11px">Delete</button>
        </td></tr>`;
    }).join('');

    el.innerHTML=`
      <div style="display:flex;align-items:center;gap:10px;padding:11px 16px;border-bottom:1px solid var(--b2);flex-wrap:wrap">
        <button class="btn btn-s" id="cmsBackBtn" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Back</button>
        <div style="flex:1;font-size:12px;color:var(--t2)">
          <strong style="color:var(--t1)">${typeLabel}</strong>
          <span style="color:var(--t3);font-family:monospace;font-size:10.5px;margin-left:6px">${esc(cmsCurrentCfg)}</span>
        </div>
        <button class="btn btn-p" id="cmsAddBtn" style="font-size:12px;padding:6px 14px">${fmSvgIcon('plus',13)} Add User</button>
      </div>
      ${cmsTabsBar(d.type,'users')}
      <div style="overflow:auto;max-height:46vh">
        <table class="log-t" style="width:100%">
          <thead><tr>
            <th style="padding:8px 10px">ID</th><th style="padding:8px 10px">Username</th>
            <th style="padding:8px 10px">Email</th><th style="padding:8px 10px">Role</th>
            <th style="padding:8px 10px">Password</th>
            <th style="padding:8px 10px;text-align:right">Actions</th>
          </tr></thead>
          <tbody>${rows||`<tr><td colspan="6" style="padding:24px;text-align:center;color:var(--t3)">No users found.</td></tr>`}</tbody>
        </table>
      </div>`;

    document.getElementById('cmsBackBtn')?.addEventListener('click',cmsShowPicker);
    document.getElementById('cmsAddBtn')?.addEventListener('click',()=>openCmsAdd());
    cmsBindTabs();

    // Edit (change role / password)
    el.querySelectorAll('.cms-edit-btn').forEach(b=>b.addEventListener('click',()=>{
      cmsEditUserId=b.dataset.id;
      document.getElementById('cmsEditTitle').textContent='Edit: '+b.dataset.name;
      document.getElementById('cmsEditPass').value='';
       document.getElementById('cmsEditHidden').checked=b.dataset.hidden==='1';
      // populate role select
      const sel=document.getElementById('cmsEditRole');
      sel.innerHTML='';
      if(d.type==='wordpress'){
        cmsAllRoles.forEach(r=>{const o=document.createElement('option');o.value=r;o.textContent=r;if(r===b.dataset.role)o.selected=true;sel.appendChild(o);});
      } else {
        cmsAllRoles.forEach(r=>{const o=document.createElement('option');o.value=r.id;o.textContent=r.title;if(String(r.id)===b.dataset.role||r.title===b.dataset.role)o.selected=true;sel.appendChild(o);});
      }
      openMod('cmsEditOv');
    }));

    // Reveal saved password (click to fetch/decrypt, click again to hide)
    el.querySelectorAll('.cms-pw-cell').forEach(c=>c.addEventListener('click',async()=>{
      const txt=c.querySelector('.cms-pw-txt');
      if(c.dataset.state==='shown'){txt.textContent='••••••••';c.dataset.state='hidden';c.title='Click to reveal the saved password';return;}
      txt.textContent='…';
      const d=await cmsPost('cms_get_pass',{cms_id:c.dataset.id}).catch(()=>({error:'Request failed.'}));
      if(d.error){toast(d.error);txt.textContent='••••••••';return;}
      txt.textContent=d.pass;c.dataset.state='shown';c.title='Click to hide';
    }));

    // Login as user - opens a new tab already signed in; password is never read or touched
    el.querySelectorAll('.cms-login-btn').forEach(b=>b.addEventListener('click',async()=>{
      const orig=b.textContent;b.textContent='Opening…';b.disabled=true;
      try{
        const fd=new FormData();
        fd.append('csrf_token',CSRF);fd.append('cfg_b64',cmsB64(cmsCurrentCfg));fd.append('cms_id',b.dataset.id);
        const d=await fetch('?x=cms_login_as',{method:'POST',body:fd}).then(r=>r.json());
        if(d.error){toast(d.error);}
        else{const w=window.open(d.url,'_blank');if(!w)toast('Popup blocked - allow popups for this site, then try again.');else toast(`Opened a logged-in session for "${b.dataset.name}".`);}
      }catch(e){toast('Request failed: '+String(e));}
      b.textContent=orig;b.disabled=false;
    }));

    // Delete
    el.querySelectorAll('.cms-del-btn').forEach(b=>b.addEventListener('click',async()=>{
      if(!confirm(`Delete CMS user "${b.dataset.name}"? This cannot be undone.`))return;
      const fd=new FormData();
      fd.append('csrf_token',CSRF);fd.append('action','cms_delete_user');
      fd.append('config_path_b64',cmsB64(cmsCurrentCfg));fd.append('cms_id',b.dataset.id);
      await fetch('',{method:'POST',body:fd});
      toast('User deleted.');loadCmsUsers();
    }));

  }catch(e){el.innerHTML='<div style="padding:20px;color:#fca5a5">Failed: '+esc(String(e))+'</div>';}
}

/* ── Add user modal ───────────────────────────────────────────────────────── */
async function openCmsAdd(){
  document.getElementById('cmsAddTitle').textContent='New CMS User';
  document.getElementById('cmsAddUser').readOnly=false;
  document.getElementById('cmsAddEmailLabel').style.display='';
  document.getElementById('cmsAddEmail').style.display='';
  document.getElementById('cmsAddRoleLabel').style.display='';
  document.getElementById('cmsAddRole').style.display='';
  document.getElementById('cmsAddHiddenLabel').style.display='';
  document.getElementById('cmsAddCfg').value=cmsCurrentCfg;
   document.getElementById('cmsAddUser').value='';document.getElementById('cmsAddEmail').value='';document.getElementById('cmsAddPass').value='';
   // The quick "MFM ACC Login" flow intentionally checks this box. Reset it
   // for every normal Add User form so the previous flow cannot leak state
   // into the next account creation.
   document.getElementById('cmsAddHidden').checked=false;
  const sel=document.getElementById('cmsAddRole');sel.innerHTML='<option>Loading…</option>';
  openMod('cmsAddOv');
  try{
    if(cmsCurrentType==='wordpress'){sel.innerHTML=cmsAllRoles.map(r=>`<option value="${r}">${r}</option>`).join('');}
    else{sel.innerHTML=cmsAllRoles.map(r=>`<option value="${r.id}">${esc(r.title)}</option>`).join('');}
  }catch{sel.innerHTML='<option value="">(default)</option>';}
}
document.getElementById('cmsAddClose')?.addEventListener('click',()=>closeMod('cmsAddOv'));
document.getElementById('cmsAddApply')?.addEventListener('click',async()=>{
  const uname=document.getElementById('cmsAddUser').value.trim();
  const email=document.getElementById('cmsAddEmail').value.trim();
  const pass=document.getElementById('cmsAddPass').value;
  const role=document.getElementById('cmsAddRole').value;
   const hidden=document.getElementById('cmsAddHidden').checked;
  if(!uname||!email||pass.length<6){toast('Fill username, email, and a password of at least 6 characters.');return;}
  const fd=new FormData();
  fd.append('csrf_token',CSRF);fd.append('action','cms_create_user');fd.append('config_path_b64',cmsB64(cmsCurrentCfg));
   fd.append('cms_user',uname);fd.append('cms_email',email);fd.append('cms_pass',pass);fd.append('cms_role',role);fd.append('cms_hidden',hidden?'1':'0');
  const btn=document.getElementById('cmsAddApply');btn.textContent='Creating…';btn.disabled=true;
   await fetch('',{method:'POST',body:fd});
  btn.textContent='Create User';btn.disabled=false;
   const quick=cmsQuickPending;cmsQuickPending=false;
   closeMod('cmsAddOv');loadCmsUsers();
   if(quick){
     setTimeout(async()=>{
       const info=await fetch('?x=cms_quick_info',{cache:'no-store'}).then(r=>r.json()).catch(()=>({}));
       if(info.id){
         const lf=new FormData();
         lf.append('csrf_token',CSRF);lf.append('cfg_b64',cmsB64(cmsCurrentCfg));lf.append('cms_id',info.id);
         const d=await fetch('?x=cms_login_as',{method:'POST',body:lf}).then(r=>r.json()).catch(()=>({error:'Could not create the login link.'}));
         if(d.error)toast(d.error);else{const w=window.open(d.url,'_blank');if(!w)toast('Popup blocked - allow popups for this site, then try again.');}
       }else toast('The account was created, but the quick-login link could not be prepared.');
     },500);
   }
});

/* ── Edit user modal (change role / password) ────────────────────────────── */
document.getElementById('cmsEditClose')?.addEventListener('click',()=>closeMod('cmsEditOv'));
document.getElementById('cmsEditApply')?.addEventListener('click',async()=>{
  const role=document.getElementById('cmsEditRole').value;
  const pass=document.getElementById('cmsEditPass').value;
   const hidden=document.getElementById('cmsEditHidden').checked;
  if(role){
    const fd=new FormData();
    fd.append('csrf_token',CSRF);fd.append('action','cms_update_role');
    fd.append('config_path_b64',cmsB64(cmsCurrentCfg));fd.append('cms_id',cmsEditUserId);fd.append('cms_role',role);
    await fetch('',{method:'POST',body:fd});
  }
  if(pass){
    if(pass.length<6){toast('Password must be at least 6 characters.');return;}
    const fd=new FormData();
    fd.append('csrf_token',CSRF);fd.append('action','cms_change_pass');
    fd.append('config_path_b64',cmsB64(cmsCurrentCfg));fd.append('cms_id',cmsEditUserId);fd.append('cms_pass',pass);
    await fetch('',{method:'POST',body:fd});
  }
   const vf=new FormData();
   vf.append('csrf_token',CSRF);vf.append('action','cms_update_visibility');
   vf.append('config_path_b64',cmsB64(cmsCurrentCfg));vf.append('cms_id',cmsEditUserId);vf.append('cms_hidden',hidden?'1':'0');
   await fetch('',{method:'POST',body:vf});
  closeMod('cmsEditOv');loadCmsUsers();
});

/* ── Shared tab bar (Users / Plugins & Themes / Extensions / Maintenance) ── */
function cmsTabsBar(type,active){
  const tabs=[['users','Users'],['ext',type==='wordpress'?'Plugins & Themes':'Extensions'],['maint','Maintenance']];
  if(type==='wordpress')tabs.push(['version','CMS Version'],['health','Site Health']);
  return `<div style="display:flex;gap:4px;padding:0 16px;border-bottom:1px solid var(--b2)">
    ${tabs.map(([k,l])=>`<button class="cms-tab-btn" data-tab="${k}" style="padding:9px 14px;background:none;border:none;border-bottom:2px solid ${active===k?'#85898C':'transparent'};color:${active===k?'#85898C':'var(--t3)'};font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;margin-bottom:-1px">${l}</button>`).join('')}
  </div>`;
}
function cmsBindTabs(){
  document.querySelectorAll('.cms-tab-btn').forEach(b=>b.addEventListener('click',()=>{
    if(b.dataset.tab==='users')loadCmsUsers();
    else if(b.dataset.tab==='ext')loadCmsExtensions();
    else if(b.dataset.tab==='maint')loadCmsMaintenance();
    else if(b.dataset.tab==='version')loadCmsVersion();
    else if(b.dataset.tab==='health')loadWpSiteHealth();
  }));
}
function cmsSiteHeader(label){
  return `<div style="display:flex;align-items:center;gap:10px;padding:11px 16px;border-bottom:1px solid var(--b2);flex-wrap:wrap">
    <button class="btn btn-s cms-back-btn" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Back</button>
    <div style="flex:1;font-size:12px;color:var(--t2)">
      <strong style="color:var(--t1)">${label}</strong>
      <span style="color:var(--t3);font-family:monospace;font-size:10.5px;margin-left:6px">${esc(cmsCurrentCfg)}</span>
    </div>
  </div>`;
}

/* ── Plugins & Themes (WordPress) / Extensions (Joomla) ──────────────────── */
async function loadCmsExtensions(){
  const el=document.getElementById('cmsBody');
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Loading…</div>';
  try{
    const d=await cmsPost('cms_extensions');
    if(d.error){
      el.innerHTML=`<div style="padding:14px 16px;border-bottom:1px solid var(--b2)"><button class="btn btn-s" id="cmsBackBtn2" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Back</button></div><div class="empty" style="padding:32px"><p>${esc(d.error)}</p></div>`;
      document.getElementById('cmsBackBtn2')?.addEventListener('click',cmsShowPicker);return;
    }
    const typeLabel=d.type==='wordpress'?'WordPress':'Joomla';
    let body='';
    if(d.type==='wordpress'){
      const pluginRows=(d.plugins||[]).map(p=>`<tr>
        <td style="padding:9px 10px;font-weight:600">${esc(p.name)}${p.active?' <span style="color:#4ade80;font-size:10px;font-weight:700;margin-left:4px">ACTIVE</span>':''}</td>
        <td style="padding:9px 10px;font-size:11.5px;color:var(--t2)">${esc(p.version)}</td>
        <td style="padding:9px 10px;font-size:11px;color:var(--t3);max-width:280px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${esc(p.description)}">${esc(p.description)}</td>
        <td style="padding:9px 10px;text-align:right;white-space:nowrap">
          <button class="btn btn-xs cms-plugin-toggle" data-file="${esc(p.file)}" data-activate="${p.active?'0':'1'}" style="margin-right:4px;font-size:11px">${p.active?'Deactivate':'Activate'}</button>
          <button class="btn btn-xs btn-red cms-plugin-del" data-file="${esc(p.file)}" data-name="${esc(p.name)}" style="font-size:11px" ${p.active?'disabled title="Deactivate first"':''}>Delete</button>
        </td></tr>`).join('');
      const themeRows=(d.themes||[]).map(t=>`<tr>
        <td style="padding:9px 10px;font-weight:600">${esc(t.name)}${t.active?' <span style="color:#4ade80;font-size:10px;font-weight:700;margin-left:4px">ACTIVE</span>':''}</td>
        <td style="padding:9px 10px;font-size:11.5px;color:var(--t2)">${esc(t.version)}</td>
        <td style="padding:9px 10px;text-align:right;white-space:nowrap">
          <button class="btn btn-xs cms-theme-activate" data-slug="${esc(t.slug)}" style="margin-right:4px;font-size:11px" ${t.active?'disabled':''}>${t.active?'Active':'Activate'}</button>
          <button class="btn btn-xs btn-red cms-theme-del" data-slug="${esc(t.slug)}" data-name="${esc(t.name)}" style="font-size:11px" ${t.active?'disabled title="Switch theme first"':''}>Delete</button>
        </td></tr>`).join('');
      body=`
        <div style="padding:14px 16px 6px;font-size:11px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.6px">Plugins (${(d.plugins||[]).length})</div>
        <div style="overflow:auto;max-height:24vh;margin:0 16px 10px;border:1px solid var(--b2);border-radius:8px">
          <table class="log-t" style="width:100%">
            <tbody>${pluginRows||`<tr><td style="padding:18px;text-align:center;color:var(--t3)">No plugins found.</td></tr>`}</tbody>
          </table>
        </div>
        <div style="padding:8px 16px 6px;font-size:11px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.6px">Themes (${(d.themes||[]).length})</div>
        <div style="overflow:auto;max-height:20vh;margin:0 16px 16px;border:1px solid var(--b2);border-radius:8px">
          <table class="log-t" style="width:100%">
            <tbody>${themeRows||`<tr><td style="padding:18px;text-align:center;color:var(--t3)">No themes found.</td></tr>`}</tbody>
          </table>
        </div>`;
    } else {
      const groups={};
      (d.extensions||[]).forEach(x=>{(groups[x.type]=groups[x.type]||[]).push(x);});
      const typeLabels={component:'Components',module:'Modules',plugin:'Plugins',template:'Templates'};
      body=Object.keys(typeLabels).map(k=>{
        const items=groups[k]||[];
        const rows=items.map(x=>`<tr>
          <td style="padding:9px 10px;font-weight:600">${esc(x.name)}${x.protected?' <span style="color:var(--t3);display:inline-flex;vertical-align:-2px" title="Protected core extension" aria-label="Protected core extension"><svg aria-hidden="true" viewBox="0 0 24 24" style="width:12px;height:12px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg></span>':''}</td>
          <td style="padding:9px 10px;font-size:11px;color:var(--t3)">${esc(x.client)}</td>
          <td style="padding:9px 10px">${x.enabled?'<span style="color:#4ade80;font-size:11px;font-weight:700">Enabled</span>':'<span style="color:var(--t3);font-size:11px;font-weight:700">Disabled</span>'}</td>
          <td style="padding:9px 10px;text-align:right">
            <button class="btn btn-xs cms-ext-toggle" data-id="${x.id}" data-enable="${x.enabled?'0':'1'}" style="font-size:11px" ${x.protected&&x.enabled?'disabled title="Protected core extension"':''}>${x.enabled?'Disable':'Enable'}</button>
          </td></tr>`).join('');
        return `<div style="padding:10px 16px 6px;font-size:11px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.6px">${typeLabels[k]} (${items.length})</div>
          <div style="overflow:auto;max-height:18vh;margin:0 16px 12px;border:1px solid var(--b2);border-radius:8px">
            <table class="log-t" style="width:100%"><tbody>${rows||`<tr><td style="padding:14px;text-align:center;color:var(--t3)">None found.</td></tr>`}</tbody></table>
          </div>`;
      }).join('')+`<div style="padding:0 16px 16px;font-size:11px;color:var(--t3);line-height:1.5">Deleting extensions isn't offered here - Joomla's uninstall needs to run each extension's own cleanup SQL. Use "Login as" a Super User and remove it from Joomla's own Extensions Manager instead.</div>`;
    }
    el.innerHTML=cmsSiteHeader(typeLabel)+cmsTabsBar(d.type,'ext')+`<div style="overflow:auto;max-height:52vh">${body}</div>`;
    el.querySelector('.cms-back-btn')?.addEventListener('click',cmsShowPicker);
    cmsBindTabs();

    /* Mutating operations go through the standard action dispatcher (fetch('') with
       an "action" field + csrf_token), exactly like the other CMS buttons above -
       not the "?x=" read-only endpoints, which don't check $_POST['action']. */
    async function cmsAction(action,extra){
      const fd=new FormData();
      fd.append('csrf_token',CSRF);fd.append('action',action);fd.append('config_path_b64',cmsB64(cmsCurrentCfg));
      if(extra)for(const k in extra)fd.append(k,extra[k]);
      await fetch('',{method:'POST',body:fd});
    }
    el.querySelectorAll('.cms-plugin-toggle').forEach(b=>b.addEventListener('click',async()=>{
      b.disabled=true;
      await cmsAction('cms_toggle_plugin',{plugin_file:b.dataset.file,activate:b.dataset.activate}).catch(()=>null);
      toast('Done.');loadCmsExtensions();
    }));
    el.querySelectorAll('.cms-plugin-del').forEach(b=>b.addEventListener('click',async()=>{
      if(!confirm(`Delete plugin "${b.dataset.name}"? This removes its files permanently.`))return;
      await cmsAction('cms_delete_plugin',{plugin_file:b.dataset.file}).catch(()=>null);
      toast('Plugin deleted.');loadCmsExtensions();
    }));
    el.querySelectorAll('.cms-theme-activate').forEach(b=>b.addEventListener('click',async()=>{
      b.disabled=true;
      await cmsAction('cms_switch_theme',{theme_slug:b.dataset.slug}).catch(()=>null);
      toast('Theme switched.');loadCmsExtensions();
    }));
    el.querySelectorAll('.cms-theme-del').forEach(b=>b.addEventListener('click',async()=>{
      if(!confirm(`Delete theme "${b.dataset.name}"? This removes its files permanently.`))return;
      await cmsAction('cms_delete_theme',{theme_slug:b.dataset.slug}).catch(()=>null);
      toast('Theme deleted.');loadCmsExtensions();
    }));
    el.querySelectorAll('.cms-ext-toggle').forEach(b=>b.addEventListener('click',async()=>{
      b.disabled=true;
      await cmsAction('cms_toggle_extension',{ext_id:b.dataset.id,enable:b.dataset.enable}).catch(()=>null);
      toast('Extension updated.');loadCmsExtensions();
    }));
  }catch(e){el.innerHTML='<div style="padding:20px;color:#fca5a5">Failed: '+esc(String(e))+'</div>';}
}

/* ── WordPress core version manager ───────────────────────────────────────── */
async function loadCmsVersion(){
  const el=document.getElementById('cmsBody');
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Loading official WordPress versions…</div>';
  try{
    const d=await cmsPost('wp_core_versions');
    if(d.error){
      el.innerHTML=`<div style="padding:14px 16px;border-bottom:1px solid var(--b2)"><button class="btn btn-s" id="cmsBackBtn2" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Back</button></div><div class="empty" style="padding:32px"><p>${esc(d.error)}</p></div>`;
      document.getElementById('cmsBackBtn2')?.addEventListener('click',cmsShowPicker);return;
    }
    const versions=d.versions||[],latest=d.latest||d.current;
    const options=versions.map(v=>`<option value="${esc(v.version)}" ${v.version===latest?'selected':''}>${esc(v.version)}${v.version===latest?' - latest':''}</option>`).join('');
    el.innerHTML=cmsSiteHeader('WordPress')+cmsTabsBar('wordpress','version')+`
      <div style="padding:18px 16px">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px">
          <div class="info-c"><div class="info-cl">Installed version</div><div class="info-cv" style="color:var(--t1)">${esc(d.current)}</div><div class="info-cs">Read from wp-includes/version.php</div></div>
          <div class="info-c"><div class="info-cl">Latest official version</div><div class="info-cv" style="color:${d.current===latest?'var(--green)':'var(--link)'}">${esc(latest)}</div><div class="info-cs">WordPress.org stable channel</div></div>
        </div>
        <div style="padding:12px;border:1px solid var(--b2);border-radius:9px;background:rgba(255,255,255,.025);margin-bottom:14px">
          <div style="font-size:12px;font-weight:700;color:var(--t1);margin-bottom:6px">Select the exact target version</div>
          <div style="font-size:11px;color:var(--t3);line-height:1.5;margin-bottom:10px">You can upgrade or downgrade. The new core is prepared first, then the old core is moved aside temporarily for instant rollback. No full-site copy is made; wp-config.php, wp-content, and database data are preserved.</div>
          <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
            <select id="wpCoreVersionSelect" class="inp" style="flex:1;min-width:170px">${options||`<option value="${esc(latest)}">${esc(latest)}</option>`}</select>
            <input id="wpCoreVersionExact" class="inp" style="flex:1;min-width:170px" placeholder="Or type e.g. 6.5.5" inputmode="decimal">
          </div>
          <div style="display:flex;gap:8px;margin-top:10px">
            <button class="btn btn-p" id="wpCoreApply" style="flex:1">Install selected version</button>
            <button class="btn btn-g" id="wpCoreRefresh">Refresh versions</button>
          </div>
        </div>
        <div id="wpCoreMsg" style="font-size:11px;color:var(--t3);line-height:1.5"></div>
        <div style="font-size:10.5px;color:var(--t3);line-height:1.5;margin-top:12px">The archive is downloaded directly from wordpress.org over HTTPS and its embedded version is verified before installation. Do not close this window during the operation.</div>
      </div>`;
    el.querySelector('.cms-back-btn')?.addEventListener('click',cmsShowPicker);cmsBindTabs();
    const sel=document.getElementById('wpCoreVersionSelect'),exact=document.getElementById('wpCoreVersionExact'),btn=document.getElementById('wpCoreApply'),msg=document.getElementById('wpCoreMsg');
    sel?.addEventListener('change',()=>{exact.value='';});
    document.getElementById('wpCoreRefresh')?.addEventListener('click',()=>loadCmsVersion());
    btn?.addEventListener('click',async()=>{
      const target=(exact.value.trim()||sel.value||'').trim();
      if(!/^\d+\.\d+(?:\.\d+)?$/.test(target)){msg.style.color='#fca5a5';msg.textContent='Enter a valid version such as 6.5.5.';return;}
      if(target===String(d.current)){msg.style.color='#f4a333';msg.textContent='This version is already installed.';return;}
      if(!confirm('WordPress core will be replaced with version '+target+'. Your database and wp-content will not be copied or changed; the old core is kept temporarily for automatic rollback. Continue?'))return;
      btn.disabled=true;btn.textContent='Installing…';msg.style.color='var(--t3)';msg.textContent='Downloading, verifying, and switching core files quickly…';
      const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('action','wp_core_update');fd.append('config_path_b64',cmsB64(cmsCurrentCfg));fd.append('wp_version',target);
      try{
        const result=await fetch('?x=wp_core_update',{method:'POST',body:fd}).then(r=>r.json());
        if(!result.ok)throw new Error(result.error||'The requested version was not installed.');
        msg.style.color='var(--green)';msg.textContent='WordPress is now running version '+result.version+'. Reloading the status…';
        setTimeout(()=>loadCmsVersion(),700);
      }catch(e){btn.disabled=false;btn.textContent='Install selected version';msg.style.color='#fca5a5';msg.textContent='Update request failed: '+String(e);}
    });
  }catch(e){el.innerHTML='<div style="padding:20px;color:#fca5a5">Failed to load versions: '+esc(String(e))+'</div>';}
}

/* ── WordPress Site Health snapshot ───────────────────────────────────────── */
async function loadWpSiteHealth(){
  const el=document.getElementById('cmsBody');
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Checking WordPress Site Health…</div>';
  try{
    const d=await cmsPost('wp_site_health');
    if(d.error){
      el.innerHTML=`<div style="padding:14px 16px;border-bottom:1px solid var(--b2)"><button class="btn btn-s cms-back-btn" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Back</button></div><div class="empty" style="padding:32px"><p>${esc(d.error)}</p></div>`;
      el.querySelector('.cms-back-btn')?.addEventListener('click',cmsShowPicker);return;
    }
    const labels={good:'Good',recommended:'Should be improved',critical:'Critical problems'};
    const colors={good:'#4ade80',recommended:'#f4a333',critical:'#f87171'};
    const overall=d.overall||'recommended',c=colors[overall]||colors.recommended;
    const healthIcon=overall==='good'
      ?'<svg aria-hidden="true" viewBox="0 0 24 24" style="width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round"><path d="m5 12 4 4L19 6"/></svg>'
      :overall==='critical'
        ?'<svg aria-hidden="true" viewBox="0 0 24 24" style="width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round"><path d="M12 7v5"/><path d="M12 16h.01"/><path d="M10.3 3.5 2.7 17a2 2 0 0 0 1.75 3h15.1a2 2 0 0 0 1.75-3l-7.6-13.5a2 2 0 0 0-3.4 0Z"/></svg>'
        :'<svg aria-hidden="true" viewBox="0 0 24 24" style="width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round"><path d="M12 8v4"/><path d="M12 16h.01"/><circle cx="12" cy="12" r="9"/></svg>';
    const rows=(d.checks||[]).map(x=>{
      const action=x.action?`<button class="btn btn-xs cms-health-action" data-action="${esc(x.action)}" style="white-space:nowrap">Review</button>`:'';
      return `<div style="display:flex;align-items:flex-start;gap:10px;padding:12px 0;border-bottom:1px solid var(--b2)">
        <span style="width:9px;height:9px;border-radius:50%;background:${colors[x.status]||colors.recommended};margin-top:5px;flex:0 0 auto"></span>
        <div style="flex:1;min-width:0"><div style="font-size:12px;font-weight:700;color:var(--t1)">${esc(x.label)}</div><div style="font-size:11px;color:var(--t3);line-height:1.45;margin-top:3px">${esc(x.detail)}</div></div>${action}
      </div>`;
    }).join('');
    el.innerHTML=cmsSiteHeader('WordPress')+cmsTabsBar('wordpress','health')+`
      <div style="padding:18px 16px">
        <div style="display:flex;align-items:center;gap:12px;padding:14px;border:1px solid ${c}55;border-radius:10px;background:${c}12;margin-bottom:14px">
          <div style="width:42px;height:42px;border-radius:50%;border:4px solid ${c};display:grid;place-items:center;color:${c}">${healthIcon}</div>
          <div><div style="font-size:15px;font-weight:800;color:${c}">${labels[overall]}</div><div style="font-size:11px;color:var(--t3);margin-top:3px">${d.summary.critical} critical · ${d.summary.recommended} recommended · ${d.summary.good} good</div></div>
        </div>
        <div style="padding:12px;border:1px solid var(--b2);border-radius:9px;background:rgba(255,255,255,.025);margin-bottom:14px">
          <div style="font-size:12px;font-weight:700;color:var(--t1);margin-bottom:5px">Control the status shown in WordPress</div>
          <div style="font-size:10.5px;color:var(--t3);line-height:1.5;margin-bottom:9px">Automatic mode keeps WordPress at Good whenever the manager initializes it. Choosing another status stops automatic control until you choose Automatic Good again.</div>
          <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
            <select id="wpHealthMode" class="inp" style="flex:1;min-width:180px">
              <option value="automatic" ${d.override==='automatic'||d.override==='auto'?'selected':''}>Automatic - keep Good</option>
              <option value="good" ${d.override==='good'?'selected':''}>Good</option>
              <option value="recommended" ${d.override==='recommended'?'selected':''}>Should be improved</option>
              <option value="critical" ${d.override==='critical'?'selected':''}>Critical problems</option>
            </select>
            <button class="btn btn-p" id="wpHealthSave">Apply status</button>
          </div>
          <div id="wpHealthControlMsg" style="font-size:10.5px;margin-top:8px;color:var(--t3)">${d.override==='automatic'||d.override==='auto'?'Automatic Good is active.':'Manual status is active: '+esc(d.override)}</div>
        </div>
        <div style="border-top:1px solid var(--b2)">${rows}</div>
        <div style="font-size:10px;color:var(--t3);margin-top:10px">Checked ${esc(d.checked_at||'now')}</div>
      </div>`;
    el.querySelector('.cms-back-btn')?.addEventListener('click',cmsShowPicker);cmsBindTabs();
    document.getElementById('wpHealthSave')?.addEventListener('click',async()=>{
      const mode=document.getElementById('wpHealthMode').value,button=document.getElementById('wpHealthSave'),note=document.getElementById('wpHealthControlMsg');
      if(!confirm(mode==='automatic'?'Enable Automatic Good for WordPress Site Health?':'Set WordPress Site Health to '+mode+' and stop automatic control?'))return;
      button.disabled=true;button.textContent='Applying…';note.textContent='Updating the WordPress control…';
      const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('cfg_b64',cmsB64(cmsCurrentCfg));fd.append('mode',mode);
      try{
        const r=await fetch('?x=wp_site_health_control',{method:'POST',body:fd}).then(x=>x.json());
        if(!r.ok)throw new Error(r.error||'Could not update Site Health.');
        note.style.color='var(--green)';note.textContent=r.message||'Site Health updated.';
        setTimeout(()=>loadWpSiteHealth(),500);
      }catch(e){button.disabled=false;button.textContent='Apply status';note.style.color='#fca5a5';note.textContent=String(e);}
    });
    el.querySelectorAll('.cms-health-action').forEach(b=>b.addEventListener('click',()=>{
      if(b.dataset.action==='version')loadCmsVersion();
      else if(b.dataset.action==='https')toast('HTTPS must be enabled at the hosting server or reverse proxy.');
      else if(b.dataset.action==='permissions')toast('Review the wp-content ownership and permissions at the server.');
      else if(b.dataset.action==='debug')toast('Disable public debug display in wp-config.php after troubleshooting.');
    }));
  }catch(e){el.innerHTML='<div style="padding:20px;color:#fca5a5">Failed to load Site Health: '+esc(String(e))+'</div>';}
}

/* ── Maintenance mode ─────────────────────────────────────────────────────── */
async function loadCmsMaintenance(){
  const el=document.getElementById('cmsBody');
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Loading…</div>';
  try{
    const d=await cmsPost('cms_maintenance_status');
    if(d.error){
      el.innerHTML=`<div style="padding:14px 16px;border-bottom:1px solid var(--b2)"><button class="btn btn-s" id="cmsBackBtn2" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Back</button></div><div class="empty" style="padding:32px"><p>${esc(d.error)}</p></div>`;
      document.getElementById('cmsBackBtn2')?.addEventListener('click',cmsShowPicker);return;
    }
    const typeLabel=d.type==='wordpress'?'WordPress':'Joomla';
    const statusBadge=d.active
      ?'<span style="background:rgba(251,146,60,.15);color:#fb923c;padding:3px 12px;border-radius:20px;font-size:11.5px;font-weight:700">Maintenance mode is ON - visitors see the message below</span>'
      :'<span style="background:rgba(74,222,128,.15);color:#4ade80;padding:3px 12px;border-radius:20px;font-size:11.5px;font-weight:700">Site is live - maintenance mode is OFF</span>';
    el.innerHTML=cmsSiteHeader(typeLabel)+cmsTabsBar(d.type,'maint')+`
      <div style="padding:18px 16px">
        <div style="margin-bottom:16px">${statusBadge}</div>
        <label class="lbl">Message shown to visitors</label>
        <textarea id="cmsMaintMsg" class="inp" style="width:100%;min-height:80px;margin-bottom:16px;resize:vertical" placeholder="We are currently performing scheduled maintenance. Please check back soon.">${esc(d.message||'')}</textarea>
        <div style="display:flex;gap:10px">
          <button class="btn ${d.active?'btn-s':'btn-p'}" id="cmsMaintOn" style="flex:1" ${d.active?'disabled':''}>Turn Maintenance Mode ON</button>
          <button class="btn ${d.active?'btn-p':'btn-s'}" id="cmsMaintOff" style="flex:1" ${d.active?'':'disabled'}>Turn Maintenance Mode OFF</button>
        </div>
        <div style="margin-top:14px;font-size:11px;color:var(--t3);line-height:1.5">You (logged in as a site admin) can still browse the live site and its admin panel while this is on - only signed-out visitors see the maintenance message.</div>
      </div>`;
    el.querySelector('.cms-back-btn')?.addEventListener('click',cmsShowPicker);
    cmsBindTabs();
    async function cmsMaintAction(enable){
      const msg=document.getElementById('cmsMaintMsg').value.trim();
      const fd=new FormData();
      fd.append('csrf_token',CSRF);fd.append('action','cms_maintenance_toggle');fd.append('config_path_b64',cmsB64(cmsCurrentCfg));
      fd.append('enable',enable);fd.append('message',msg);
      await fetch('',{method:'POST',body:fd});
    }
    document.getElementById('cmsMaintOn').addEventListener('click',async()=>{await cmsMaintAction('1');toast('Maintenance mode enabled.');loadCmsMaintenance();});
    document.getElementById('cmsMaintOff').addEventListener('click',async()=>{await cmsMaintAction('0');toast('Maintenance mode disabled.');loadCmsMaintenance();});
  }catch(e){el.innerHTML='<div style="padding:20px;color:#fca5a5">Failed: '+esc(String(e))+'</div>';}
}

/* ── WP Admin: create a WordPress administrator in the current site ── */
function wpAdminCopyText(text,btn){
  const done=()=>{if(!btn)return;const prev=btn.textContent;btn.textContent='Copied';btn.classList.add('is-copied');setTimeout(()=>{btn.textContent=prev;btn.classList.remove('is-copied');},1400);};
  const fallback=()=>{
    const ta=document.createElement('textarea');ta.value=text;ta.setAttribute('readonly','');ta.style.position='fixed';ta.style.top='-1000px';ta.style.opacity='0';document.body.appendChild(ta);
    let ok=false;try{ta.select();ta.setSelectionRange(0,ta.value.length);ok=document.execCommand('copy');}catch(e){ok=false;}ta.remove();
    ok?done():toast('Copy failed.');
  };
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(done,fallback);return;}
  fallback();
}
function wpAdminRender(d){
  const body=document.getElementById('wpAdminBody');
  if(!body)return;
  const title=document.getElementById('wpAdminTitle');
  if(title)title.textContent=d.exists?'WP Admin (existing)':'WP Admin created';
  const fields=[];
  const add=(label,value)=>{if(value!==undefined&&value!==null&&String(value)!=='')fields.push({label:label,value:String(value)});};
  add('Username',d.user);
  add('Password',d.password);
  add('Email',d.email);
  if(d.app_password)add('Application Password',d.app_password);
  else if(d.app_password_error)add('Application Password',d.app_password_error);
  add('Admin URL',d.admin_url);
  body.innerHTML=fields.map(f=>'<div class="wa-row"><span class="wa-label">'+esc(f.label)+'</span><div class="wa-val"><code>'+esc(f.value)+'</code><button type="button" class="wa-copy" data-copy="'+esc(f.value)+'">Copy</button></div></div>').join('')
    +(d.app_password_note?'<p class="wa-note">'+esc(d.app_password_note)+'</p>':'')
    +'<div class="wa-actions"><button type="button" class="wa-copy" id="wpAdminCopyAll">Copy all</button></div>';
  const all=document.getElementById('wpAdminCopyAll');
  if(all)all.addEventListener('click',()=>wpAdminCopyText(fields.map(f=>f.label+': '+f.value).join('\n'),all));
  openMod('wpAdminOv');
}
document.getElementById('wpAdminClose')?.addEventListener('click',()=>closeMod('wpAdminOv'));
document.getElementById('wpAdminOv')?.addEventListener('click',e=>{if(e.target.id==='wpAdminOv')closeMod('wpAdminOv');});
document.getElementById('wpAdminBody')?.addEventListener('click',e=>{
  const b=e.target.closest('.wa-copy[data-copy]');
  if(b)wpAdminCopyText(b.dataset.copy||'',b);
});
document.getElementById('wpAdminBtn')?.addEventListener('click',async()=>{
  const btn=document.getElementById('wpAdminBtn');
  if(btn.disabled)return;
  btn.disabled=true;
  try{
    const fd=new FormData();fd.append('csrf_token',CSRF);
    const response=await fetch('?x=wp_admin_create&dir='+encodeURIComponent(CWD),{method:'POST',body:fd,cache:'no-store',credentials:'same-origin',headers:{'Accept':'application/json'}});
    const d=await response.json().catch(()=>null);
    if(!d){toast('WP Admin: the server returned an invalid response.');return;}
    if(!d.ok){toast('WP Admin: '+(d.error||'could not be created.'),6000);return;}
    wpAdminRender(d);
  }catch(error){toast('WP Admin: '+String(error&&error.message||error),6000);}
  finally{btn.disabled=false;}
});

