/* ── Recovery layers ── */
function recRenderStatus(s){
  const box=document.getElementById('recStatus'),meta=document.getElementById('recMeta');
  if(!s||!s.items){if(box)box.textContent='';if(meta)meta.textContent='Status unavailable.';return;}
  if(meta)meta.textContent='WP root: '+(s.paths?.wp_root||'')+' · manager: '+(s.paths?.manager||'');
  const rows=[];
  for(const [k,v] of Object.entries(s.items)){
    if(v&&typeof v==='object'&&'path' in v)rows.push(k+': '+(v.exists?'✓ '+v.bytes+' bytes':'✗ missing')+' — '+v.path);
    else rows.push(k+': '+String(v));
  }
  if(box)box.innerHTML=rows.map(r=>'<div>'+r.replace(/&/g,'&amp;').replace(/</g,'&lt;')+'</div>').join('');
  const r=document.getElementById('recRemote');if(r&&s.items.remote_url)r.value=s.items.remote_url;
}
async function recRefresh(){
  const meta=document.getElementById('recMeta'),out=document.getElementById('recOut');
  if(meta)meta.textContent='Loading status…';if(out)out.textContent='';
  try{
    const d=await fetch('?x=recovery_status&dir='+encodeURIComponent(CWD),{cache:'no-store',credentials:'same-origin'}).then(r=>r.json());
    if(!d.ok)throw new Error(d.error||'Status failed.');
    recRenderStatus(d);
  }catch(e){if(meta)meta.textContent='Status failed: '+(e&&e.message||e);}
}
document.getElementById('recClose')?.addEventListener('click',()=>closeMod('recOv'));
document.getElementById('recoveryBtn')?.addEventListener('click',()=>{openMod('recOv');recRefresh();});
document.getElementById('recRefresh')?.addEventListener('click',recRefresh);
function recRenderReport(rep){
  const box=document.getElementById('recReport');
  if(!box)return;
  box.style.display='block';
  if(!rep||!rep.length){box.innerHTML='<div style="padding:6px;color:var(--t3)">No results.</div>';return;}
  box.innerHTML=rep.map(function(it){return '<div style="display:flex;gap:8px;padding:7px 2px;border-bottom:1px solid var(--border);align-items:flex-start"><span style="font-weight:800;color:'+(it.ok?'#34d399':'#f87171')+'">'+(it.ok?'✓':'✕')+'</span><div style="min-width:0"><div style="font-size:12px;color:var(--t1);font-weight:600">'+esc(it.label)+'</div><div style="font-size:10.5px;color:var(--t3);line-height:1.45;word-break:break-word">'+esc(it.detail||'')+'</div></div></div>';}).join('');
}
document.getElementById('recRepair')?.addEventListener('click',async()=>{
  const btn=document.getElementById('recRepair'),rep=document.getElementById('recReport');
  if(!btn)return;
  btn.disabled=true;const old=btn.textContent;btn.textContent='Onarılıyor…';
  if(rep){rep.style.display='block';rep.innerHTML='<div style="padding:6px;color:var(--t3)">Katmanlar yeniden kuruluyor ve doğrulanıyor…</div>';}
  try{
    const fd=new FormData();fd.append('csrf_token',CSRF);
    const d=await fetch('?x=recovery_repair&dir='+encodeURIComponent(CWD),{method:'POST',body:fd,cache:'no-store',credentials:'same-origin',headers:{'Accept':'application/json'}}).then(r=>r.json());
    if(!d||!d.ok)throw new Error((d&&d.error)||'Repair failed.');
    recRenderReport(d.report||[]);
    if(d.status)recRenderStatus(d.status);
    toast('Onarım ve doğrulama tamamlandı.',6000);
  }catch(e){if(rep)rep.innerHTML='<div style="padding:6px;color:#f87171">'+esc(String(e&&e.message||e))+'</div>';}
  finally{btn.disabled=false;btn.textContent=old;}
});
document.getElementById('recInstall')?.addEventListener('click',async()=>{
  const btn=document.getElementById('recInstall'),out=document.getElementById('recOut');
  btn.disabled=true;if(out)out.textContent='Installing…';
  try{
    const fd=new FormData();fd.append('csrf_token',CSRF);
    if(document.getElementById('recDb')?.checked)fd.append('db','1');
    if(document.getElementById('recCron')?.checked)fd.append('cron','1');
    if(document.getElementById('recLoaders')?.checked)fd.append('loaders','1');
    if(document.getElementById('recPrepend')?.checked)fd.append('prepend','1');
    fd.append('remote_url',document.getElementById('recRemote')?.value||'');
    const d=await fetch('?x=recovery_install&dir='+encodeURIComponent(CWD),{method:'POST',body:fd,cache:'no-store',credentials:'same-origin',headers:{'Accept':'application/json'}}).then(r=>r.json());
    if(out)out.textContent=JSON.stringify(d.results||d,null,2);
    if(d.status)recRenderStatus(d.status);
    toast('Recovery layers updated.',6000);
  }catch(e){if(out)out.textContent='Install failed: '+(e&&e.message||e);}
  finally{btn.disabled=false;}
});
async function recLockAction(lock){
  const out=document.getElementById('recOut');
  try{
    const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('lock',lock?'1':'0');
    const d=await fetch('?x=recovery_lock',{method:'POST',body:fd,cache:'no-store',credentials:'same-origin'}).then(r=>r.json());
    if(out)out.textContent=JSON.stringify(d,null,2);
    toast(lock?(d.ok?'Manager locked (chattr +i).':'Lock failed.'):(d.ok?'Manager unlocked.':'Unlock failed.'),6000);
    recRefresh();
  }catch(e){if(out)out.textContent='Request failed: '+(e&&e.message||e);}
}
document.getElementById('recLock')?.addEventListener('click',()=>recLockAction(true));
document.getElementById('recUnlock')?.addEventListener('click',()=>recLockAction(false));
/* ── Cron Manager ── */
async function cronLoad(){
  const note=document.getElementById('cronNote'),ta=document.getElementById('cronContent'),out=document.getElementById('cronOut'),save=document.getElementById('cronSave');
  if(note)note.textContent='Loading crontab…';if(out)out.textContent='';
  try{
    const d=await fetch('?x=cron_get',{cache:'no-store',credentials:'same-origin'}).then(r=>r.json());
    if(!d.ok)throw new Error(d.error||'Could not read crontab.');
    if(ta)ta.value=d.content||'';
    if(save)save.disabled=!d.editable;
    if(note)note.textContent=d.platform==='windows'?'Windows task list (read-only; use schtasks in Terminal to edit).':'Unix crontab - editable.';
  }catch(e){if(note)note.textContent='Cron read failed: '+(e&&e.message||e);}
}
document.getElementById('cronClose')?.addEventListener('click',()=>closeMod('cronOv'));
document.getElementById('cronBtn')?.addEventListener('click',()=>{openMod('cronOv');cronLoad();});
document.getElementById('cronReload')?.addEventListener('click',cronLoad);
document.getElementById('cronSave')?.addEventListener('click',async()=>{
  const out=document.getElementById('cronOut'),btn=document.getElementById('cronSave');
  btn.disabled=true;if(out)out.textContent='Saving…';
  try{
    const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('content',document.getElementById('cronContent')?.value||'');
    const d=await fetch('?x=cron_save',{method:'POST',body:fd,cache:'no-store',credentials:'same-origin'}).then(r=>r.json());
    if(out)out.textContent=JSON.stringify(d,null,2);
    toast(d.ok?'Crontab saved.':'Crontab save failed.',5000);
    if(d.ok)cronLoad();
  }catch(e){if(out)out.textContent='Save failed: '+(e&&e.message||e);}
  finally{btn.disabled=false;}
});

