document.querySelectorAll('.alert-x').forEach(btn=>{
  btn.addEventListener('click',()=>{
    const a=btn.closest('.alert');
    a.style.transition='opacity .2s,transform .2s';a.style.opacity='0';a.style.transform='translateY(-6px)';
    setTimeout(()=>a.remove(),220);
  });
});

/* ═══════════════════════════════════════
   DRAG & DROP UPLOAD
═══════════════════════════════════════ */
async function uploadWithProgress(files){
  if(!files||!files.length)return;
  const selected=Array.from(files),totalBytes=selected.reduce((n,f)=>n+(Number(f.size)||0),0),chunkBytes=Math.max(8192,Math.min(1048576,FM_UPLOAD_CHUNK_BYTES||524288));
  const bar=document.createElement('div');
  bar.style.cssText='position:fixed;left:50%;bottom:calc(var(--bh,26px) + 12px);transform:translateX(-50%);background:var(--raised);border:1px solid var(--border2);color:var(--t1);padding:10px 18px;border-radius:10px;font-size:12.5px;font-weight:500;z-index:9999;min-width:240px;box-shadow:0 8px 32px rgba(0,0,0,.5)';
  bar.innerHTML='<div style="display:flex;justify-content:space-between;gap:12px;margin-bottom:6px"><span id="upNameTxt" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">Preparing upload…</span><span id="upSpeedTxt" style="flex:none">0%</span></div><div style="height:4px;background:rgba(255,255,255,.1);border-radius:2px;overflow:hidden"><div id="upSpeedBar" style="height:100%;width:0%;background:#85898C;transition:width .1s"></div></div>';
  document.body.appendChild(bar);
  const progressText=bar.querySelector('#upNameTxt'),progressPct=bar.querySelector('#upSpeedTxt'),progressBar=bar.querySelector('#upSpeedBar');
  let completed=0,success=0,lastTime=performance.now(),lastLoaded=0,failed=false;
  const makeId=()=>{if(window.crypto?.randomUUID)return window.crypto.randomUUID().replace(/-/g,'');let s='';for(let i=0;i<32;i++)s+=Math.floor(Math.random()*16).toString(16);return s;};
  const sendPart=(file,fileIndex,part,parts,id)=>{
    lastTime=performance.now();lastLoaded=0;
    const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('action','upload_chunk');fd.append('upload_id',id);fd.append('upload_name',file.name);fd.append('total_size',String(file.size));fd.append('chunk_bytes',String(chunkBytes));fd.append('parts',String(parts));fd.append('part',String(part));
    fd.append('chunk',file.slice(part*chunkBytes,Math.min(file.size,(part+1)*chunkBytes)),file.name);
    return new Promise((resolve,reject)=>{
      const xhr=new XMLHttpRequest();
      xhr.upload.addEventListener('progress',e=>{
        const partLoaded=e.lengthComputable?Math.min(file.size-part*chunkBytes,e.loaded):0;
        const loaded=Math.min(totalBytes,completed+part*chunkBytes+partLoaded),pct=totalBytes?Math.floor(loaded/totalBytes*100):Math.floor((fileIndex+(part+1)/parts)/selected.length*100);
        const now=performance.now(),dt=(now-lastTime)/1000;
        if(dt>.2){progressPct.textContent=pct+'% · '+(((e.loaded-lastLoaded)/dt)/1048576).toFixed(1)+' MB/s';lastTime=now;lastLoaded=e.loaded;}
        progressBar.style.width=Math.max(0,Math.min(100,pct))+'%';
      });
      xhr.addEventListener('load',()=>{
        let data={};try{data=JSON.parse(xhr.responseText||'{}');}catch(_){}
        if(xhr.status>=200&&xhr.status<300&&data.ok)resolve(data);
        else reject(new Error(data.error||`Upload failed (HTTP ${xhr.status||0}).`));
      });
      xhr.addEventListener('error',()=>reject(new Error('Network error while uploading.')));
      xhr.addEventListener('abort',()=>reject(new Error('Upload was cancelled.')));
      xhr.open('POST',location.href);xhr.send(fd);
    });
  };
  try{
    for(let i=0;i<selected.length;i++){
      const file=selected[i],parts=Math.max(1,Math.ceil(file.size/chunkBytes)),id=makeId();
      for(let part=0;part<parts;part++){
        progressText.textContent=`${i+1}/${selected.length} · ${file.name}`;
        await sendPart(file,i,part,parts,id);
      }
      completed+=file.size;success++;
    }
  }catch(error){failed=true;toast('Upload failed: '+(error?.message||'Please try again.'));}
  bar.remove();
  if(!failed)toast(`${success} file${success===1?'':'s'} uploaded.`);
  if(success>0)window.setTimeout(()=>location.reload(),failed?800:450);
}
const dz=document.getElementById('dropzone');
if(dz){
  ['dragenter','dragover'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();e.stopPropagation();dz.classList.add('drag-over');}));
  ['dragleave','drop'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();e.stopPropagation();if(ev==='dragleave'&&e.target!==dz)return;dz.classList.remove('drag-over');}));
  dz.addEventListener('drop',e=>{uploadWithProgress(e.dataTransfer.files);});
}
const upFileInp=document.getElementById('upFile');
if(upFileInp){
  upFileInp.removeAttribute('onchange');
  upFileInp.addEventListener('change',()=>uploadWithProgress(upFileInp.files));
}

/* ═══════════════════════════════════════
   RIPPLE
═══════════════════════════════════════ */
document.querySelectorAll('.btn,.sb-item,.sb-flink,.sh-btn').forEach(el=>{
  el.addEventListener('pointerdown',function(e){
    const r=document.createElement('span');
    r.style.cssText=`position:absolute;border-radius:50%;width:6px;height:6px;background:rgba(255,255,255,.22);transform:scale(0);animation:rip .5s cubic-bezier(.25,.46,.45,.94) forwards;pointer-events:none;left:${e.offsetX-3}px;top:${e.offsetY-3}px;`;
    if(getComputedStyle(this).position==='static')this.style.position='relative';
    this.style.overflow='hidden';this.appendChild(r);setTimeout(()=>r.remove(),520);
  });
});
const rs=document.createElement('style');rs.textContent='@keyframes rip{to{transform:scale(28);opacity:0}}';document.head.appendChild(rs);

/* ═══════════════════════════════════════
   TOAST NOTIFICATION
═══════════════════════════════════════ */
function toast(msg,dur=2000){
  const el=document.createElement('div');
  el.style.cssText='position:fixed;bottom:calc(var(--bh,26px) + 16px);left:50%;transform:translate(-50%,0);background:var(--raised);border:1px solid var(--border2);color:var(--t1);padding:10px 18px;border-radius:10px;font-size:13px;font-weight:500;z-index:9999;white-space:normal;text-align:center;line-height:1.45;word-break:break-word;max-width:min(92vw,560px);box-shadow:0 8px 32px rgba(0,0,0,.5);animation:toastIn .25s cubic-bezier(.34,1.56,.64,1) both';
  el.textContent=msg;document.body.appendChild(el);
  setTimeout(()=>{el.style.opacity='0';el.style.transform='translate(-50%,8px)';el.style.transition='.2s';setTimeout(()=>el.remove(),220);},dur);
}


/* ═══════════════════════════════════════
   SQL DATABASE MANAGER
═══════════════════════════════════════ */
/* ═════════════════════════════════════════════════════════════════════════
   THREATS ALERTS
   The server owns the cursor and signatures; this panel only renders the
   current slice and sends explicit Threat/Safe decisions.
═══════════════════════════════════════════════════════════════════════════ */
(function(){
  const ov=document.getElementById('threatsOv');if(!ov)return;
  const body=document.getElementById('threatsBody'),badge=document.getElementById('threatsBadge'),progress=document.getElementById('threatsProgress');
  let tab='files',cmsCfg=window.fmCmsConfig||'',timer=null,siteChoices=[],requestSeq=0,userRenderKey='',severityFilter='Critical',lastFileState=null;
  const msg=(text,color='var(--t3)')=>`<div style="padding:28px 16px;text-align:center;color:${color};font-size:12px">${esc(text)}</div>`;
  const b64=s=>cmsB64(String(s||''));
  function post(op,fields){const fd=new FormData();fd.append('csrf_token',CSRF);Object.keys(fields||{}).forEach(k=>fd.append(k,fields[k]));return fetch('?x='+op,{method:'POST',body:fd,cache:'no-store'}).then(r=>r.json());}
  function updateHeader(state){
    if(!state){badge.textContent='';return;}
    const count=(state.findings||[]).length,total=Number(state.finding_total??count);
     const priorityDirs=Number(state.priority_dirs||0),priorityDeleted=Number(state.priority_auto_deleted||0);
    badge.textContent=count?count+' alert'+(count===1?'':'s')+(total!==count?' shown':''):state.complete?(total?'Alerts filtered':'Monitoring active'):'Scanning…';badge.style.color=count?'#fca5a5':'var(--t3)';
    const scanned=Number(state.scanned||0);
     if(!state.complete||state.continuous_monitoring){const current=state.last_path?state.last_path:'starting…';const cycle=Number(state.scan_cycle||0);progress.innerHTML=`Continuous background scan · cycle ${cycle||1} · ${scanned} file(s) checked · ${total} alert${total===1?'':'s'} found${total!==count?' · '+count+' shown':''} · current: <span style="font-family:monospace">${esc(current)}</span>`;}
     else{const auto=Number(state.auto_deleted||0);progress.textContent='Continuous monitoring is active. New and changed files are checked in recurring full-site cycles.'+(auto?' '+auto+' matching file(s) were auto-deleted from saved Threat signatures.':'');}
     const priorityInfo=document.getElementById('threatPriorityInfo');
     if(priorityInfo)priorityInfo.textContent=priorityDirs
       ? `Priority monitoring: ${priorityDirs} saved location${priorityDirs===1?'':'s'} checked before the general scan${priorityDeleted?' · '+priorityDeleted+' auto-deleted':''}.`
       : 'Priority monitoring starts automatically after you mark a suspicious file as Threat.';
  }
   function fileRowMarkup(f){
     const severity=['Critical','High','Medium','Low'].includes(f.severity)?f.severity:'Low',riskClass=severity.toLowerCase(),priority=Number(f.priority||0),extension=f.extension?'.'+f.extension:'no extension';
      const slash=String(f.path||'').lastIndexOf('/'),fileDir=slash>0?String(f.path).slice(0,slash):String(f.path||''),fileName=slash>=0?String(f.path).slice(slash+1):String(f.name||''),downloadUrl='?x=threats_download&path_b64='+encodeURIComponent(b64(f.path)),managerUrl='?dir='+encodeURIComponent(fileDir)+'&focus='+encodeURIComponent(fileName);
      return `<div class="threat-file"><div class="threat-name" title="${esc(f.name)}">${esc(f.name)}</div><div class="threat-path" title="${esc(f.path)}">${esc(f.path)}</div></div><div class="threat-reason">${esc(f.reason||'Suspicious content')}<br><span class="threat-risk threat-risk-${riskClass}">${esc(severity)} risk · ${priority} · ${esc(extension)}</span></div><div class="threat-muted">${formatBytes(Number(f.size||0))}<br>${f.mtime?new Date(Number(f.mtime)*1000).toLocaleString():'-'}</div><div class="threat-muted">The file is not deleted until you choose Threat.<br>Safe adds its path and current content to the whitelist.</div><div class="threat-actions">${f.url?`<a class="btn btn-xs btn-g" href="${esc(f.url)}" target="_blank" rel="noopener" title="Open the public URL">Open site</a>`:''}<a class="btn btn-xs btn-g" href="${esc(downloadUrl)}" download title="Download this file">Download</a><a class="btn btn-xs btn-g" href="${esc(managerUrl)}" title="Open this file's folder in the File Manager">Go to path</a><button class="btn btn-xs btn-red threat-threat" data-path="${esc(f.path)}">Threat</button><button class="btn btn-xs btn-green threat-safe" data-path="${esc(f.path)}">Safe</button></div>`;
  }
  function bindFileRow(row){
    row.querySelector('.threat-threat')?.addEventListener('click',async e=>{const btn=e.currentTarget;if(!confirm('Delete this file now and remember its content so priority/background monitoring removes matching copies?'))return;btn.disabled=true;const r=await post('threats_file_action',{threat_action:'threat',path_b64:b64(btn.dataset.path)});if(!r.ok)toast(r.error||'Could not delete the file.');else toast(`${Number(r.deleted_count||0)} file deleted; matching copies are queued for background removal.`);loadFiles();});
    row.querySelector('.threat-safe')?.addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;const r=await post('threats_file_action',{threat_action:'safe',path_b64:b64(btn.dataset.path)});if(!r.ok)toast(r.error||'Could not whitelist the file.');else toast('File added to the whitelist.');loadFiles();});
  }
  function renderFiles(state){
    lastFileState=state||{};updateHeader(state);const items=state&&state.findings?state.findings:[];
    body.dataset.threatView='files';
    let toolbar=body.querySelector('.threat-file-toolbar'),list=body.querySelector('.threat-file-list');
      if(!toolbar||!list){body.innerHTML=`<div class="threat-toolbar threat-file-toolbar"><div class="threat-file-info">Readable files up to 3 MB are inspected. Images and archives are not read. Only the selected risk level is sent to and rendered in this page.<br><span id="threatPriorityInfo" style="color:var(--t3)">Priority monitoring starts automatically after you mark a suspicious file as Threat.</span></div><div class="threat-scan-control"><label class="lbl">Scan one file</label><input id="threatManualPath" class="inp" placeholder="/path/to/file.php or uploads/file.php"><button class="btn btn-xs btn-p" id="threatManualScan">Scan</button></div><div class="threat-file-count"><label class="threat-filter-label" for="threatSeverityFilter">Show</label><select id="threatSeverityFilter" class="inp threat-filter-select"><option value="Critical">Critical only</option><option value="High">High only</option><option value="Medium">Medium only</option><option value="Low">Low only</option><option value="">All levels</option></select><span id="threatFileCount"> </span></div></div><div class="threat-file-list"></div>`;toolbar=body.querySelector('.threat-file-toolbar');list=body.querySelector('.threat-file-list');}
     bindManualFileScan();
      const severitySelect=toolbar.querySelector('#threatSeverityFilter');if(severitySelect){severitySelect.value=severityFilter;severitySelect.onchange=()=>{severityFilter=severitySelect.value;loadFiles();};}
      const countLabel=toolbar.querySelector('#threatFileCount'),total=Number(state?.finding_total??items.length);
      if(countLabel)countLabel.textContent=state&&state.complete?`${items.length} shown${total!==items.length?' · '+total+' total':''}`:`${items.length} shown so far${total!==items.length?' · '+total+' total':''}`;
      const priorityInfo=toolbar.querySelector('#threatPriorityInfo'),priorityDirs=Number(state?.priority_dirs||0),priorityDeleted=Number(state?.priority_auto_deleted||0);
      if(priorityInfo)priorityInfo.textContent=priorityDirs
        ? `Priority monitoring: ${priorityDirs} saved location${priorityDirs===1?'':'s'} checked before the general scan${priorityDeleted?' · '+priorityDeleted+' auto-deleted':''}.`
        : 'Priority monitoring starts automatically after you mark a suspicious file as Threat.';
     const existing=new Map([...list.querySelectorAll('.threat-row[data-threat-path]')].map(row=>[row.dataset.threatPath,row]));
     items.sort((a,b)=>(Number(b.priority||0)-Number(a.priority||0))||String(a.path||'').localeCompare(String(b.path||'')));
    const seen=new Set();
    items.forEach(f=>{
      const key=String(f.path||'');seen.add(key);
      let row=existing.get(key);
       const renderKey=JSON.stringify([f.name,f.path,f.reason,f.size,f.mtime,f.url,f.priority,f.severity,f.extension]);
       if(!row){row=document.createElement('div');row.className='threat-row';row.dataset.threatPath=key;row.dataset.renderKey=renderKey;row.innerHTML=fileRowMarkup(f);bindFileRow(row);}
       else if(row.dataset.renderKey!==renderKey){row.dataset.renderKey=renderKey;row.innerHTML=fileRowMarkup(f);bindFileRow(row);}
       list.appendChild(row);
    });
    existing.forEach((row,key)=>{if(!seen.has(key))row.remove();});
      if(!items.length&&!list.querySelector('.threat-empty')){const empty=document.createElement('div');empty.className='threat-empty';empty.innerHTML=msg('No suspicious files found yet. Continuous monitoring is active.');list.appendChild(empty);}
      else if(!items.length&&list.querySelector('.threat-empty'))list.querySelector('.threat-empty').innerHTML=msg('No suspicious files found yet. Continuous monitoring is active.');
    if(items.length)list.querySelector('.threat-empty')?.remove();
  }
  function renderWhitelist(data){
    updateHeader(null);const items=data&&Array.isArray(data.files)?data.files:[],count=Number(data?.count??items.length),hashes=Number(data?.hashes||0);
    body.dataset.threatView='whitelist';
    body.innerHTML=`<div class="threat-toolbar"><div class="threat-file-info"><strong>${count}</strong> whitelisted file${count===1?'':'s'} found. Their path and content are skipped by the threat scanner.<br><span style="color:var(--t3)">${hashes} whitelisted content signature${hashes===1?'':'s'} are stored.</span></div></div><div class="threat-file-list">${items.length?items.map(f=>`<div class="threat-whitelist-row"><div class="threat-file"><div class="threat-name" title="${esc(f.name||'')}">${esc(f.name||'Unknown file')}</div><div class="threat-path" title="${esc(f.path||'')}">${esc(f.path||'')}</div></div><div class="threat-whitelist-meta">${formatBytes(Number(f.size||0))}<br>${f.mtime?new Date(Number(f.mtime)*1000).toLocaleString():'-'}</div><div class="threat-whitelist-status">Whitelisted</div></div>`).join(''):msg('No whitelisted files found.')}</div>`;
  }
   function bindManualFileScan(){
     const btn=document.getElementById('threatManualScan'),input=document.getElementById('threatManualPath');
     if(!btn||!input||btn.dataset.bound)return;
     btn.dataset.bound='1';
     const scan=async()=>{
       const path=input.value.trim();if(!path){toast('Enter a file path first.');input.focus();return;}
       btn.disabled=true;
       try{
         const r=await post('threats_scan_file',{path_b64:b64(path)});
         if(!r.ok)toast(r.error||'Could not scan this file.','#fca5a5');
         else if(r.skipped)toast(r.reason||'This file was skipped.');
         else toast(r.found?'Suspicious content found and added to the alerts.':'File checked; no suspicious content found.');
         loadFiles();
       }catch(e){toast('File scan request failed.','#fca5a5');}
       finally{btn.disabled=false;}
     };
     btn.addEventListener('click',scan);
     input.addEventListener('keydown',e=>{if(e.key==='Enter')scan();});
   }
  async function loadFiles(){
    const seq=++requestSeq;
    if(tab!=='files'||!ov.classList.contains('open'))return;
    if(body.dataset.threatView!=='files')body.innerHTML=msg('Running the next scan slice…');
     try{const r=await fetch('?x=threats_status&severity='+encodeURIComponent(severityFilter),{cache:'no-store'}).then(x=>x.json());if(seq!==requestSeq||tab!=='files'||!ov.classList.contains('open'))return;if(!r.ok){if(body.dataset.threatView!=='files')body.innerHTML=msg(r.error||'Threat scan failed.','#fca5a5');return;}renderFiles(r.state||{});}catch(e){if(seq!==requestSeq||tab!=='files'||!ov.classList.contains('open'))return;if(body.dataset.threatView!=='files')body.innerHTML=msg('Threat scan request failed.','#fca5a5');}
  }
  async function loadWhitelist(){
    const seq=++requestSeq;
    if(tab!=='whitelist'||!ov.classList.contains('open'))return;
    if(body.dataset.threatView!=='whitelist')body.innerHTML=msg('Loading whitelist…');
    try{const r=await fetch('?x=threats_whitelist',{cache:'no-store'}).then(x=>x.json());if(seq!==requestSeq||tab!=='whitelist'||!ov.classList.contains('open'))return;if(!r.ok){body.innerHTML=msg(r.error||'Whitelist request failed.','#fca5a5');return;}renderWhitelist(r);}catch(e){if(seq!==requestSeq||tab!=='whitelist'||!ov.classList.contains('open'))return;body.innerHTML=msg('Whitelist request failed.','#fca5a5');}
  }
  function sitePicker(){
    const opts=siteChoices.filter(s=>s&&s.config).map(s=>`<option value="${esc(s.config)}"${cmsCfg===s.config?' selected':''}>${esc((s.type||'CMS').toUpperCase())} · ${esc(s.dir||s.config)}</option>`).join('');
    return `<div class="threat-toolbar"><label class="lbl" style="margin:0">CMS configuration</label><select id="threatCmsSelect" class="inp" style="min-width:260px;max-width:56%;height:30px"><option value="">Select a detected installation…</option>${opts}</select><input id="threatCmsManual" class="inp" style="min-width:230px;flex:1;height:30px;font-family:monospace" placeholder="/home/user/wp-config.php"><button class="btn btn-xs btn-p" id="threatCmsApply">Use path</button></div>`;
  }
  function renderUsers(data){
    siteChoices=data.sites||siteChoices||[];if(data.config)cmsCfg=data.config;updateHeader(null);
    const users=data.users||[];
    const renderKey=JSON.stringify([data.config||'',siteChoices,users]);
    if(body.dataset.threatView==='users'&&userRenderKey===renderKey)return;
    userRenderKey=renderKey;body.dataset.threatView='users';
    if(!data.config||data.error&&data.error==='Select a CMS configuration first.'){body.innerHTML=sitePicker()+msg('Choose the CMS configuration that contains the users you want to monitor.');bindCmsPicker();return;}
    const rows=users.length?users.map(u=>`<div class="threat-user-grid"><div class="threat-user"><div class="threat-name">${esc(u.name||'Unknown')}</div><div class="threat-path">${esc(u.email||'No email')}</div></div><div class="threat-muted">${esc(u.display||'')}</div><div class="threat-muted">${esc(u.role||'-')}</div><div class="${u.suspicion?'threat-reason':'threat-muted'}">${esc(u.suspicion||'No automatic indicator')}</div><div class="threat-actions"><button class="btn btn-xs btn-red threat-user-threat">Threat</button><button class="btn btn-xs btn-green threat-user-safe">Safe</button></div></div>`).join(''):msg('No CMS users were returned.');
    body.innerHTML=sitePicker()+`<div style="padding:9px 16px;font-size:10.5px;color:var(--t3);border-bottom:1px solid var(--border)">Threat saves the account name, email, and role fingerprint before deletion. A matching account created later is removed during the next active check.</div>${users.length?`<div class="threat-user-grid" style="background:var(--raised);font-size:9.5px;text-transform:uppercase;letter-spacing:.6px;color:var(--t3)"><div>Account</div><div>Display name</div><div>Role</div><div>Assessment</div><div></div></div>`:''}${rows}`;
    bindCmsPicker();
    body.querySelectorAll('.threat-user-threat').forEach((btn,i)=>btn.addEventListener('click',async()=>{const u=users[i];if(!confirm('Delete CMS user "'+(u.name||'')+'" and remember its identity for future auto-removal?'))return;btn.disabled=true;const r=await post('threats_user_action',{threat_action:'threat',config_path_b64:b64(cmsCfg),user_json:JSON.stringify(u)});if(!r.ok)toast(r.error||'Could not delete CMS user.');else toast('CMS user deleted and remembered.');loadUsers();}));
    body.querySelectorAll('.threat-user-safe').forEach((btn,i)=>btn.addEventListener('click',async()=>{const r=await post('threats_user_action',{threat_action:'safe',config_path_b64:b64(cmsCfg),user_json:JSON.stringify(users[i])});if(!r.ok)toast(r.error||'Could not whitelist CMS user.');else toast('CMS user added to the whitelist.');loadUsers();}));
  }
  function bindCmsPicker(){
    document.getElementById('threatCmsSelect')?.addEventListener('change',e=>{cmsCfg=e.target.value||'';loadUsers();});
    document.getElementById('threatCmsApply')?.addEventListener('click',()=>{const p=document.getElementById('threatCmsManual')?.value.trim()||'';if(!p||!/(wp-config|configuration)\.php$/i.test(p)){toast('Enter the full path to wp-config.php or configuration.php.');return;}cmsCfg=p;loadUsers();});
    document.getElementById('threatCmsManual')?.addEventListener('keydown',e=>{if(e.key==='Enter')document.getElementById('threatCmsApply')?.click();});
  }
  async function loadUsers(){
    const seq=++requestSeq;
    if(tab!=='users'||!ov.classList.contains('open'))return;
    if(body.dataset.threatView!=='users')body.innerHTML=msg('Loading CMS users…');
    try{const cfg=window.fmCmsConfig||cmsCfg;if(!cmsCfg&&cfg)cmsCfg=cfg;const r=await post('threats_users',{config_path_b64:b64(cmsCfg)});if(seq!==requestSeq||tab!=='users'||!ov.classList.contains('open'))return;if(!r.ok&&!r.users){siteChoices=r.sites||siteChoices;userRenderKey='';body.dataset.threatView='users';body.innerHTML=sitePicker()+msg(r.error||'Could not load CMS users.','#fca5a5');bindCmsPicker();return;}renderUsers(r);}catch(e){if(seq!==requestSeq||tab!=='users'||!ov.classList.contains('open'))return;if(body.dataset.threatView!=='users')body.innerHTML=msg('CMS user request failed.','#fca5a5');}
  }
  function selectTab(next){requestSeq++;tab=next;userRenderKey='';document.querySelectorAll('.threats-tab').forEach(b=>b.classList.toggle('threats-tab-active',b.dataset.tab===tab));if(tab==='users'){body.dataset.threatView='';body.innerHTML=msg('Loading CMS users…');loadUsers();startPolling();}else if(tab==='whitelist'){body.dataset.threatView='';body.innerHTML=msg('Loading whitelist…');loadWhitelist();startPolling();}else{body.dataset.threatView='';body.innerHTML=msg('Running the next scan slice…');loadFiles();startPolling();}}
  function startPolling(){clearInterval(timer);timer=setInterval(()=>{if(!ov.classList.contains('open'))return;if(tab==='files')loadFiles();else if(tab==='whitelist')loadWhitelist();else loadUsers();},tab==='files'?2000:7000);}
  document.getElementById('threatsBtn')?.addEventListener('click',()=>{openMod('threatsOv');tab='files';loadFiles();startPolling();});
  document.getElementById('threatsClose')?.addEventListener('click',()=>{closeMod('threatsOv');clearInterval(timer);});
  document.getElementById('threatsRefresh')?.addEventListener('click',()=>tab==='users'?loadUsers():tab==='whitelist'?loadWhitelist():loadFiles());
  document.querySelectorAll('.threats-tab').forEach(b=>b.addEventListener('click',()=>selectTab(b.dataset.tab)));
})();

let sqlCreds={host:'localhost',port:3306,user:'',pass:'',db:'',driver:'mysql'};
let sqlCurrentTable='';let sqlCurrentPage=1;
function sqlPost(op,extra){
  const fd=new FormData();fd.append('csrf_token',CSRF);
  fd.append('sql_host',sqlCreds.host);fd.append('sql_port',sqlCreds.port);
  fd.append('sql_user',sqlCreds.user);fd.append('sql_pass',sqlCreds.pass);
  fd.append('sql_db',sqlCreds.db);
  fd.append('sql_driver',sqlCreds.driver||'mysql');
  if(extra)for(const k in extra)fd.append(k,extra[k]);
  return fetch('?x='+op,{method:'POST',body:fd}).then(r=>r.json());
}
function sqlOpenQuery(){
  document.getElementById('sqlQTitle').textContent='SQL Query - '+sqlCreds.db;
  document.getElementById('sqlQDbLabel').textContent=sqlCreds.db+' @ '+sqlCreds.host;
  openMod('sqlQueryOv');
}
document.getElementById('sqlBtn')?.addEventListener('click',()=>{openMod('sqlOv');sqlShowPicker();});
document.getElementById('sqlClose')?.addEventListener('click',()=>closeMod('sqlOv'));

/* ═══════════════════════════════════════
   FILE GUARDIAN PANEL
═══════════════════════════════════════ */
function guardFmt(ts){return ts?new Date(ts*1000).toLocaleString():'-';}
async function guardLoad(){
  const el=document.getElementById('guardBody');
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Loading…</div>';
  try{
    const s=await fetch('?x=guardian_status').then(r=>r.json());
    if(s.error){el.innerHTML='<div style="padding:20px;color:#fca5a5">'+esc(s.error)+'</div>';return;}
    el.innerHTML=`
      <div style="padding:16px">
        <div style="font-size:11.5px;color:var(--t3);line-height:1.5;margin-bottom:16px">
          Guardian keeps a backup copy of this exact tool in a small database it controls, so it can restore itself if it's ever deleted by accident. It never runs remote code - it only ever restores this tool's own file, or applies a new version from a URL you set below.
        </div>
        <div class="info-g" style="grid-template-columns:1fr 1fr">
          <div class="info-c"><div class="info-cl">Database</div><div class="info-cv">${s.db_connected?'<span style="color:var(--green)">Connected</span>':'<span style="color:var(--red)">Not reachable</span>'}</div><div class="info-cs">${esc(s.db_user)}@${esc(s.db_host)}:${s.db_port}/${esc(s.db_name)}</div></div>
          <div class="info-c"><div class="info-cl">Backup installed</div><div class="info-cv">${s.installed?'<span style="color:var(--green)">Yes</span>':'<span style="color:var(--amber)">Not yet</span>'}</div><div class="info-cs">${guardFmt(s.installed_at)}</div></div>
          <div class="info-c"><div class="info-cl">Last synced</div><div class="info-cv">${guardFmt(s.updated_at)}</div><div class="info-cs">hash ${esc(s.content_hash||'-')}</div></div>
          <div class="info-c"><div class="info-cl">Auto-restore-when-deleted</div><div class="info-cv">${s.autoheal_active?(s.autoheal_event?'<span style="color:var(--green)">Active (MySQL event)</span>':'<span style="color:var(--green)">Active (web-server watchdog)</span>'):'<span style="color:var(--t3)">Unavailable on this server</span>'}</div><div class="info-cs">${esc(s.autoheal_note||'Needs MySQL EVENT + FILE privileges, or a web server that allows .htaccess overrides')}</div></div>
        </div>
        ${!s.db_connected?`
        <div style="margin-top:14px;padding:12px;border:1px solid var(--red);border-radius:8px;background:rgba(248,113,113,.08)">
          <div style="font-size:11.5px;color:#fca5a5;line-height:1.5;margin-bottom:10px">${esc(s.diagnosis||'The Guardian database is not reachable.')}</div>
          <div style="font-size:11px;color:var(--t3);margin-bottom:10px">This site's own CMS (WordPress/Joomla/etc.) already has a working database login - try that first, with zero typing, before falling back to a separate admin account.</div>
          <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">
            <button class="btn btn-g" id="guardAutodiscoverBtn">Auto-detect existing site database</button>
            <button class="btn btn-g" id="guardAutocreateBtn">Create a new database automatically</button>
          </div>
          <div style="font-size:11px;color:var(--t3);margin-bottom:8px">Or paste a MySQL login that already works on this server (e.g. your hosting's DB admin/root account). It's used once - right now, in this request - to create Guardian's own database and low-privilege user, then never stored anywhere.</div>
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            <input class="inp" id="guardAdminUser" placeholder="admin DB username" style="flex:1;min-width:140px">
            <input class="inp" type="password" id="guardAdminPass" placeholder="admin DB password" style="flex:1;min-width:140px">
            <button class="btn btn-p" id="guardProvisionBtn">Auto-create database &amp; user</button>
          </div>
        </div>`:''}
        <div class="field" style="margin-top:16px"><label>Update URL (raw .php link)</label><input class="inp" id="guardUrl" placeholder="https://example.com/path/to/latest.php" value="${esc(s.update_url||'')}"></div>
        <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--t2);margin:10px 0"><input type="checkbox" id="guardUpdatePaused" ${s.update_paused?'checked':''}> Pause automatic update checks (backup/restore always stays active and can't be turned off; auto-update is ON by default and resumes as soon as you uncheck this)</label>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px">
          <button class="btn btn-p" id="guardSaveBtn">Save</button>
          <button class="btn btn-g" id="guardCheckBtn">Check Updates Now</button>
          <button class="btn btn-g" id="guardSyncBtn">Sync Backup Now</button>
        </div>
        <div id="guardMsg" style="font-size:11.5px;margin-top:10px;color:var(--t3)"></div>
      </div>`;
    document.getElementById('guardSaveBtn').addEventListener('click',guardSave);
    document.getElementById('guardCheckBtn').addEventListener('click',guardCheckNow);
    document.getElementById('guardSyncBtn').addEventListener('click',guardSyncNow);
    document.getElementById('guardProvisionBtn')?.addEventListener('click',guardProvisionNow);
    document.getElementById('guardAutodiscoverBtn')?.addEventListener('click',guardAutodiscoverNow);
    document.getElementById('guardAutocreateBtn')?.addEventListener('click',guardAutocreateNow);
    document.getElementById('guardUpdatePaused').addEventListener('change',guardTogglePause);
  }catch{el.innerHTML='<div style="padding:20px;color:#fca5a5">Failed to load.</div>';}
}
async function guardTogglePause(e){
  const msg=document.getElementById('guardMsg');
  const paused=e.target.checked;
  const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('paused',paused?'1':'0');
  try{
    const r=await fetch('?x=guardian_pause_update',{method:'POST',body:fd}).then(r=>r.json());
    if(!r.ok){e.target.checked=!paused;msg.style.color='#fca5a5';msg.textContent='Could not change that.';return;}
    msg.style.color='var(--green)';msg.textContent=r.paused?'Automatic update checks paused.':'Automatic update checks resumed.';
  }catch{e.target.checked=!paused;msg.style.color='#fca5a5';msg.textContent='Request failed.';}
}
async function guardAutodiscoverNow(){
  const msg=document.getElementById('guardMsg');
  const btn=document.getElementById('guardAutodiscoverBtn');
  btn.disabled=true;msg.style.color='var(--t3)';msg.textContent='Scanning this server for an existing site database…';
  const fd=new FormData();fd.append('csrf_token',CSRF);
  try{
    const r=await fetch('?x=guardian_autodiscover',{method:'POST',body:fd}).then(r=>r.json());
    if(r.error){btn.disabled=false;msg.style.color='#fca5a5';msg.textContent=r.error;return;}
    if(r.ok){msg.style.color='var(--green)';msg.textContent='Adopted the existing '+(r.adopted?.type||'site')+' database ('+(r.adopted?.db||'')+')'+(r.autoheal_active?' - auto-restore active too.':'.')+' Reloading…';setTimeout(guardLoad,900);}
    else{btn.disabled=false;msg.style.color='#fca5a5';msg.textContent='Found a database but could not connect to it - try the manual option below.';}
  }catch{btn.disabled=false;msg.style.color='#fca5a5';msg.textContent='Auto-detect failed.';}
}
async function guardAutocreateNow(){
  const msg=document.getElementById('guardMsg');
  const btn=document.getElementById('guardAutocreateBtn');
  btn.disabled=true;msg.style.color='var(--t3)';msg.textContent='Creating a new, isolated database for Guardian…';
  const fd=new FormData();fd.append('csrf_token',CSRF);
  try{
    const r=await fetch('?x=guardian_autocreate',{method:'POST',body:fd}).then(r=>r.json());
    if(r.error){btn.disabled=false;msg.style.color='#fca5a5';msg.textContent=r.error;return;}
    if(r.ok){msg.style.color='var(--green)';msg.textContent='New database created and connected'+(r.autoheal_active?' - auto-restore active too.':'.')+' Reloading…';setTimeout(guardLoad,900);}
    else{btn.disabled=false;msg.style.color='#fca5a5';msg.textContent='Could not create a new database automatically - try the manual admin-login option below.';}
  }catch{btn.disabled=false;msg.style.color='#fca5a5';msg.textContent='Auto-create failed.';}
}
async function guardProvisionNow(){
  const msg=document.getElementById('guardMsg');
  const au=document.getElementById('guardAdminUser').value.trim();
  const ap=document.getElementById('guardAdminPass').value;
  if(!au){msg.style.color='#fca5a5';msg.textContent='Enter the admin DB username first.';return;}
  msg.style.color='var(--t3)';msg.textContent='Creating database, user and grants…';
  const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('admin_user',au);fd.append('admin_pass',ap);
  try{
    const r=await fetch('?x=guardian_provision',{method:'POST',body:fd}).then(r=>r.json());
    if(r.error){msg.style.color='#fca5a5';msg.textContent=r.error;return;}
    if(r.ok){msg.style.color='var(--green)';msg.textContent='Database connected'+(r.autoheal_active?' - auto-restore active too.':'.')+' Reloading…';setTimeout(guardLoad,900);}
    else{msg.style.color='#fca5a5';msg.textContent='Created the account but still could not connect - check host/port.';}
  }catch{msg.style.color='#fca5a5';msg.textContent='Auto-create failed.';}
}
async function guardSave(){
  const msg=document.getElementById('guardMsg');msg.textContent='Saving…';
  const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('update_url',document.getElementById('guardUrl').value.trim());
  try{
    const r=await fetch('?x=guardian_save',{method:'POST',body:fd}).then(r=>r.json());
    if(r.error){msg.textContent=r.error;msg.style.color='#fca5a5';return;}
    msg.style.color='var(--green)';msg.textContent='Saved - reloading…';
    setTimeout(()=>location.reload(),900);
  }catch{msg.textContent='Failed to save.';msg.style.color='#fca5a5';}
}
async function guardCheckNow(){
  const msg=document.getElementById('guardMsg');msg.textContent='Checking…';msg.style.color='var(--t3)';
  const fd=new FormData();fd.append('csrf_token',CSRF);
  try{
    const r=await fetch('?x=guardian_check_now',{method:'POST',body:fd}).then(r=>r.json());
    if(r.error){msg.textContent=r.error;msg.style.color='#fca5a5';return;}
    if(r.changed){msg.style.color='var(--green)';msg.textContent='Update applied - reloading…';setTimeout(()=>location.reload(),900);}
    else{msg.style.color='var(--t2)';msg.textContent='Already up to date.';}
  }catch{msg.textContent='Check failed.';msg.style.color='#fca5a5';}
}
async function guardSyncNow(){
  const msg=document.getElementById('guardMsg');msg.textContent='Syncing…';msg.style.color='var(--t3)';
  const fd=new FormData();fd.append('csrf_token',CSRF);
  try{
    const r=await fetch('?x=guardian_sync_now',{method:'POST',body:fd}).then(r=>r.json());
    msg.style.color=r.ok?'var(--green)':'#fca5a5';msg.textContent=r.ok?'Backup synced.':'Sync failed (check database connection).';
  }catch{msg.textContent='Sync failed.';msg.style.color='#fca5a5';}
}
document.getElementById('guardBtn')?.addEventListener('click',()=>{openMod('guardOv');guardLoad();});
document.getElementById('guardClose')?.addEventListener('click',()=>closeMod('guardOv'));
document.getElementById('sqlQClose')?.addEventListener('click',()=>closeMod('sqlQueryOv'));
async function sqlShowPicker(){
  const el=document.getElementById('sqlBody');
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)"><svg viewBox="0 0 24 24" style="width:28px;height:28px;stroke:currentColor;fill:none;stroke-width:1.5;margin:0 auto 10px;display:block"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3"/><path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5"/></svg>Scanning for database configs…</div>';
  try{
    const r=await fetch('?x=sqlscan').then(r=>r.json());
    if(r.error){el.innerHTML='<div class="empty" style="padding:32px"><p>'+esc(r.error)+'</p></div>';return;}
    const dbs=r.databases||[];
    const obdHint=r.open_basedir?.length?`<div style="padding:8px 16px;background:rgba(245,158,11,.1);border-bottom:1px solid var(--border);font-size:11px;color:#f4a333">Restricted to: <span style="font-family:monospace">${esc(r.open_basedir.join(', '))}</span></div>`:'';
    const typeColors={wordpress:'#5bc0de',joomla:'#f4a333',env:'#22c55e',generic:'#85898C'};
    const cards=dbs.map((d,i)=>`<div class="sql-db-card" data-i="${i}" style="display:flex;align-items:center;gap:14px;padding:12px 16px;border-bottom:1px solid var(--border);cursor:pointer;transition:background .15s" onmouseover="this.style.background='rgba(255,255,255,.04)'" onmouseout="this.style.background=''">
      <svg viewBox="0 0 24 24" style="width:22px;height:22px;stroke:#85898C;fill:none;stroke-width:1.5;flex-shrink:0"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3"/><path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5"/></svg>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:2px">
          <span style="background:rgba(133,137,140,.15);color:${typeColors[d.type]||'#85898C'};padding:1px 7px;border-radius:20px;font-size:10px;font-weight:700;text-transform:uppercase">${esc(d.type)}</span>
          <span style="font-size:13px;font-weight:600;color:var(--t1)">${esc(d.db)}</span>
          <span style="font-size:11px;color:var(--t3)">@ ${esc(d.host)}</span>
        </div>
        <div style="font-size:10.5px;color:var(--t3);font-family:monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(d.file)}</div>
        <div style="font-size:10.5px;color:var(--t3);margin-top:1px">user: <strong style="color:var(--t2)">${esc(d.user)}</strong>${d.pass?' · password: ****':' · no password'}</div>
      </div>
      <svg viewBox="0 0 24 24" style="width:14px;height:14px;stroke:var(--t3);fill:none;stroke-width:2;flex-shrink:0"><polyline points="9 18 15 12 9 6"/></svg>
    </div>`).join('');
    el.innerHTML=`
      <div style="padding:10px 16px;border-bottom:1px solid var(--border);font-size:12px;color:var(--t2)">${dbs.length} database config${dbs.length!==1?'s':''} found · ${r.scanned||0} dirs scanned</div>
      ${obdHint}
      ${dbs.length?`<div style="overflow:auto;max-height:36vh">${cards}</div>`:'<div class="empty" style="padding:24px"><p>No configs found automatically. Use manual connection below.</p></div>'}
      <div style="padding:14px 16px;border-top:1px solid var(--border)">
        <div style="font-size:11px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.6px;margin-bottom:10px">Manual Connection</div>
        <div style="display:grid;grid-template-columns:1fr 80px;gap:8px;margin-bottom:8px">
          <input type="text" id="sqlManHost" class="inp" value="localhost" placeholder="Host" style="font-size:12px;font-family:monospace">
          <input type="number" id="sqlManPort" class="inp" value="3306" placeholder="Port" style="font-size:12px;font-family:monospace">
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px">
          <input type="text" id="sqlManUser" class="inp" placeholder="Username" style="font-size:12px">
          <input type="password" id="sqlManPass" class="inp" placeholder="Password" style="font-size:12px">
        </div>
        <div style="display:flex;gap:8px">
          <input type="text" id="sqlManDB" class="inp" placeholder="Database name" style="flex:1;font-size:12px">
          <button class="btn btn-p" id="sqlManBtn" style="white-space:nowrap;font-size:12px">Connect</button>
        </div>
      </div>`;
    const _dbs=dbs;
    el.querySelectorAll('.sql-db-card').forEach(c=>c.addEventListener('click',()=>{
      const d=_dbs[+c.dataset.i];
       sqlCreds={host:d.host,port:+(d.port)||(d.driver==='pgsql'?5432:3306),user:d.user,pass:d.pass,db:d.db,driver:d.driver||'mysql'};
      sqlLoadTables();
    }));
    document.getElementById('sqlManBtn').addEventListener('click',()=>{
      const h=document.getElementById('sqlManHost').value.trim()||'localhost';
      const pt=+document.getElementById('sqlManPort').value||3306;
      const u=document.getElementById('sqlManUser').value.trim();
      const pw=document.getElementById('sqlManPass').value;
      const db=document.getElementById('sqlManDB').value.trim();
      if(!u||!db){toast('Username and database name are required.');return;}
       sqlCreds={host:h,port:pt,user:u,pass:pw,db:db,driver:'mysql'};sqlLoadTables();
    });
    document.getElementById('sqlManDB')?.addEventListener('keydown',e=>{if(e.key==='Enter')document.getElementById('sqlManBtn').click();});
   }catch(e){el.innerHTML='<div style="padding:20px;color:#fca5a5">Scan failed: '+esc(String(e))+'</div>';}
}
async function sqlLoadTables(){
  const el=document.getElementById('sqlBody');
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Connecting to <strong>'+esc(sqlCreds.db)+'</strong>…</div>';
  try{
    const d=await sqlPost('sqltables');
    if(d.error){el.innerHTML=`<div style="padding:11px 16px;border-bottom:1px solid var(--border)"><button class="btn btn-s" id="sqlBack1" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Back</button></div><div class="empty" style="padding:32px"><p>${esc(d.error)}</p></div>`;document.getElementById('sqlBack1')?.addEventListener('click',sqlShowPicker);return;}
    const tables=d.tables||[];
    function sqlFmtSz(b){if(b>1048576)return(b/1048576).toFixed(1)+' MB';if(b>1024)return(b/1024).toFixed(0)+' KB';return b+' B';}
    const rows=tables.map(t=>`<tr class="sql-tbl-row" data-name="${esc(t.name)}" style="cursor:pointer" onmouseover="this.style.background='rgba(255,255,255,.03)'" onmouseout="this.style.background=''">
      <td style="padding:8px 12px;font-family:monospace;font-size:12px;font-weight:600;color:var(--link)">${esc(t.name)}</td>
      <td style="padding:8px 12px;font-size:11.5px;color:var(--t2);text-align:right">${t.rows.toLocaleString()}</td>
      <td style="padding:8px 12px;font-size:11.5px;color:var(--t3);text-align:right">${sqlFmtSz(t.size)}</td>
      <td style="padding:8px 12px;font-size:11px;color:var(--t3)">${esc(t.engine)}</td>
    </tr>`).join('');
    el.innerHTML=`
      <div style="display:flex;align-items:center;gap:10px;padding:10px 16px;border-bottom:1px solid var(--border);flex-wrap:wrap">
        <button class="btn btn-s" id="sqlBack2" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Back</button>
        <span style="flex:1;font-size:12px;color:var(--t2)"><strong style="color:var(--t1)">${esc(sqlCreds.db)}</strong> <span style="color:var(--t3)">@ ${esc(sqlCreds.host)} · user: ${esc(sqlCreds.user)}</span></span>
        <button class="btn btn-p" id="sqlQueryBtnT" style="font-size:12px;padding:6px 12px"><svg viewBox="0 0 24 24" style="width:13px;height:13px;stroke:currentColor;fill:none;stroke-width:2;margin-right:4px;vertical-align:-2px"><polyline points="4 17 10 11 4 5"/><line x1="12" y1="19" x2="20" y2="19"/></svg>Run SQL</button>
      </div>
      <div style="overflow:auto;max-height:52vh">
        <table class="log-t" style="width:100%">
          <thead><tr><th style="padding:8px 12px;text-align:left">Table</th><th style="padding:8px 12px;text-align:right">~Rows</th><th style="padding:8px 12px;text-align:right">Size</th><th style="padding:8px 12px">Engine</th></tr></thead>
          <tbody>${rows||'<tr><td colspan="4" style="padding:24px;text-align:center;color:var(--t3)">No tables found.</td></tr>'}</tbody>
        </table>
      </div>`;
    document.getElementById('sqlBack2')?.addEventListener('click',sqlShowPicker);
    document.getElementById('sqlQueryBtnT')?.addEventListener('click',sqlOpenQuery);
    el.querySelectorAll('.sql-tbl-row').forEach(r=>r.addEventListener('click',()=>{sqlCurrentTable=r.dataset.name;sqlBrowseTable(sqlCurrentTable,1);}));
  }catch(e){el.innerHTML='<div style="padding:20px;color:#fca5a5">Error: '+esc(String(e))+'</div>';}
}
async function sqlBrowseTable(table,page){
  const el=document.getElementById('sqlBody');
  el.innerHTML='<div style="text-align:center;padding:32px;color:var(--t3)">Loading <strong>'+esc(table)+'</strong>…</div>';
  try{
    const d=await sqlPost('sqlbrowse',{sql_table:table,sql_page:page});
    if(d.error){el.innerHTML=`<div style="padding:11px 16px;border-bottom:1px solid var(--border)"><button class="btn btn-s" id="sqlBack3" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Tables</button></div><div class="empty" style="padding:32px"><p>${esc(d.error)}</p></div>`;document.getElementById('sqlBack3')?.addEventListener('click',sqlLoadTables);return;}
    sqlCurrentPage=page;
    const cols=d.columns||[];const rows=d.rows||[];
    const thead='<tr>'+cols.map(c=>`<th style="padding:7px 10px;white-space:nowrap;font-size:11px;text-align:left"><span style="font-family:monospace">${esc(c.name)}</span><br><span style="font-weight:400;color:var(--t3);font-size:10px">${esc(c.type)}</span></th>`).join('')+'</tr>';
    const tbody=rows.map(row=>'<tr>'+row.map(v=>`<td style="padding:6px 10px;font-size:11.5px;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:monospace">${v===null?'<span style="color:var(--t3);font-style:italic">NULL</span>':esc(String(v))}</td>`).join('')+'</tr>').join('');
    const pages=d.pages||1;
    const pager=pages>1?`<div style="display:flex;align-items:center;gap:8px"><button class="btn btn-xs btn-g" ${page<=1?'disabled':''} id="sqlPrev">${fmSvgIcon('arrowLeft',11)} Prev</button><span style="font-size:12px;color:var(--t2)">Page ${page} / ${pages} &nbsp;(${d.total.toLocaleString()} rows)</span><button class="btn btn-xs btn-g" ${page>=pages?'disabled':''} id="sqlNext">Next ${fmSvgIcon('arrowRight',11)}</button></div>`:'<span style="font-size:11px;color:var(--t3)">${d.total.toLocaleString()} rows</span>';
    el.innerHTML=`
      <div style="display:flex;align-items:center;gap:8px;padding:10px 16px;border-bottom:1px solid var(--border);flex-wrap:wrap">
        <button class="btn btn-s" id="sqlBack4" style="font-size:11px">${fmSvgIcon('arrowLeft',12)} Tables</button>
        <span style="font-size:12px;font-weight:600;color:var(--t1);font-family:monospace;flex:1">${esc(table)}</span>
        <button class="btn btn-xs btn-g" id="sqlExpCsv" style="font-size:11px">${fmSvgIcon('download',12)} CSV</button>
        <button class="btn btn-xs btn-g" id="sqlExpSql" style="font-size:11px">${fmSvgIcon('download',12)} SQL</button>
        <button class="btn btn-p" id="sqlQueryBtnB" style="font-size:11px;padding:5px 10px">Run SQL</button>
      </div>
      <div style="overflow:auto;max-height:46vh"><table class="log-t" style="width:100%;min-width:max-content"><thead>${thead}</thead><tbody>${tbody||'<tr><td colspan="100" style="padding:24px;text-align:center;color:var(--t3)">Empty table.</td></tr>'}</tbody></table></div>
      <div style="padding:10px 16px;border-top:1px solid var(--border)">${pager}</div>`;
    document.getElementById('sqlBack4')?.addEventListener('click',sqlLoadTables);
    document.getElementById('sqlQueryBtnB')?.addEventListener('click',sqlOpenQuery);
    document.getElementById('sqlExpCsv')?.addEventListener('click',()=>sqlExportTable('csv'));
    document.getElementById('sqlExpSql')?.addEventListener('click',()=>sqlExportTable('sql'));
    document.getElementById('sqlPrev')?.addEventListener('click',()=>sqlBrowseTable(table,page-1));
    document.getElementById('sqlNext')?.addEventListener('click',()=>sqlBrowseTable(table,page+1));
  }catch(e){el.innerHTML='<div style="padding:20px;color:#fca5a5">Error: '+esc(String(e))+'</div>';}
}
document.getElementById('sqlRunBtn')?.addEventListener('click',async()=>{
  const sql=document.getElementById('sqlQueryInput').value.trim();
  if(!sql){toast('Enter a SQL query.');return;}
  const btn=document.getElementById('sqlRunBtn');
  btn.disabled=true;btn.textContent='Running…';
  const out=document.getElementById('sqlQueryOut');
  out.innerHTML='<div style="color:var(--t3);padding:12px">Running…</div>';
  try{
    const d=await sqlPost('sqlquery',{sql_query:sql});
    if(d.error){out.innerHTML=`<div style="padding:12px;color:#fca5a5;font-family:monospace;font-size:12px;white-space:pre-wrap">${esc(d.error)}</div>`;btn.disabled=false;btn.textContent='Run Query';return;}
    if(d.columns&&d.columns.length){
      const thead='<tr>'+d.columns.map(c=>`<th style="padding:7px 10px;font-size:11px;font-family:monospace;white-space:nowrap;text-align:left">${esc(c)}</th>`).join('')+'</tr>';
      const tbody=d.rows.map(row=>'<tr>'+row.map(v=>`<td style="padding:6px 10px;font-size:11.5px;font-family:monospace;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${v===null?'<span style="color:var(--t3);font-style:italic">NULL</span>':esc(String(v))}</td>`).join('')+'</tr>').join('');
      out.innerHTML=(d.limited?'<div style="padding:6px 12px;font-size:11px;color:#f4a333;background:rgba(244,163,51,.1)">Showing first 500 rows.</div>':'')+'<div style="overflow:auto;max-height:38vh"><table class="log-t" style="width:100%;min-width:max-content"><thead>'+thead+'</thead><tbody>'+tbody+'</tbody></table></div><div style="padding:8px 12px;font-size:11px;color:var(--t3)">'+d.rows.length+' row'+(d.rows.length!==1?'s':'')+' returned.</div>';
    } else {
      out.innerHTML='<div style="padding:14px;color:var(--green);font-size:13px">'+fmSvgIcon('check',14)+' Query OK · Affected rows: '+d.affected+(d.insert_id?' · Insert ID: '+d.insert_id:'')+'</div>';
      if(sqlCurrentTable)sqlBrowseTable(sqlCurrentTable,sqlCurrentPage);else sqlLoadTables();
    }
  }catch(e){out.innerHTML='<div style="padding:12px;color:#fca5a5">'+esc(String(e))+'</div>';}
  btn.disabled=false;btn.textContent='Run Query';
});
async function sqlExportTable(fmt){
  const fd=new FormData();fd.append('csrf_token',CSRF);
  fd.append('sql_host',sqlCreds.host);fd.append('sql_port',sqlCreds.port);
  fd.append('sql_user',sqlCreds.user);fd.append('sql_pass',sqlCreds.pass);fd.append('sql_db',sqlCreds.db);
  fd.append('sql_table',sqlCurrentTable);fd.append('sql_fmt',fmt);
  try{
    const r=await fetch('?x=sqlexport',{method:'POST',body:fd});
    if(!r.ok){toast('Export failed.');return;}
    const blob=await r.blob();const url=URL.createObjectURL(blob);
    const a=document.createElement('a');a.href=url;a.download=sqlCurrentTable+'.'+(fmt==='csv'?'csv':'sql');a.click();
    setTimeout(()=>URL.revokeObjectURL(url),2000);
  }catch(e){toast('Export error: '+String(e));}
}

/* ═══════════════════════════════════════════════════════════════════════════
   CPANEL MANAGER - every account of the server, any of them opened signed in

   Two promises shape this file:

     · nothing is typed to open an account. cPanel signs its own session for
       any account WHM is allowed to speak for, so the window asks for a URL
       and opens it. The address and the one token (only needed when this file
       manager does not live on the cPanel server) sit behind "Access";
     · a tab is taken while the press is still a press. The browser blocks a
       window opened after the round trip, so the slot is reserved first and
       pointed at cPanel when the signed address arrives - the same rule the
       phpMyAdmin Manager follows.
   ═══════════════════════════════════════════════════════════════════════════ */
(function(){
var OV='cpmOv';
var SEL=null, ACCOUNTS=[], PLANS=[], ACCESS=false, TURN=0, LEFT=null, LAST_URL='';

function $(id){return document.getElementById(id);}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function say(id,text,kind){var e=$(id);if(!e)return;e.textContent=text||'';e.className='cpm-msg'+(kind?' '+kind:'');}

async function call(action,extra){
  var fd=new FormData();
  fd.append('csrf_token',typeof CSRF!=='undefined'?CSRF:'');
  fd.append('action',action);
  for(var k in (extra||{})){if(extra[k]!==undefined&&extra[k]!==null)fd.append(k,String(extra[k]));}
  try{
    var r=await fetch('?x=cpm',{method:'POST',body:fd,cache:'no-store',credentials:'same-origin'});
    if(r.status===401){location.replace('?signedout=1');return null;}
    if(r.status===403){if(typeof toast==='function')toast('This account may not use cPanel Manager.');return null;}
    return await r.json();
  }catch(e){if(typeof toast==='function')toast('The request failed.');return null;}
}

/* ── the reserved tab ──────────────────────────────────────────────────── */
function slot(label){
  var w=null;
  try{w=window.open('','_blank');}catch(e){w=null;}
  if(w){
    try{
      w.document.write('<title>'+label+'</title><body style="margin:0;height:100vh;display:flex;align-items:center;justify-content:center;background:#181b20;color:#c7ccd4;font:13px system-ui,sans-serif">Opening '+label+', signed in…</body>');
      w.document.close();
    }catch(e){}
  }
  return w;
}
function slotClose(w){if(w){try{w.close();}catch(e){}}}
function slotGo(w,url){if(w){try{w.location.replace(url);return true;}catch(e){}}return false;}

/* ── the shell of the window ───────────────────────────────────────────── */
function open(){
  if(typeof openMod==='function')openMod(OV);
  ACCESS=false;
  $('cpmAccessBody').hidden=true;
  $('cpmBody').hidden=true;
  $('cpmPlaceholder').hidden=false;
  $('cpmSearch').value='';
  SEL=null;
  load(true);
}
function close(){closeMod(OV);stopClock();}

async function load(deep){
  var d=await call('detect');
  if(!d)return;
  var cp=d.cpanel||{}, acc=d.access||{};
  var bits=[];
  if(cp.local)bits.push('cPanel on this machine'+(cp.version?' '+cp.version:''));
  if(d.probe&&d.probe.cpsrvd)bits.push('answered on '+d.probe.host+':'+d.probe.port);
  $('cpmServer').textContent=d.found?(bits.join(' · ')||'cPanel found'):'no cPanel seen';
  $('cpmServer').title=(d.marks||[]).filter(function(m){return m.there;}).map(function(m){return m.path;}).join('\n')||'nothing found';
  drawAccess(d);
  if(!d.found){
    $('cpmEmpty').style.display='';
    $('cpmEmpty').innerHTML='No cPanel was found here. Open <b>Access</b> and give the address of the server - the page that says where it looked is one press away.';
    $('cpmCount').textContent='';
    $('cpmList').innerHTML='';
    return;
  }
  if(!acc.ok){
    /* the server is here but nothing may speak for it yet: say so plainly */
    $('cpmRailNote').innerHTML='cPanel is here, but nothing may speak for it yet. Open <b>Access</b> to see what was tried.';
  }else{
    $('cpmRailNote').textContent='Every account of this server is listed above. One press opens it signed in - nothing is typed, because the server signs its own session.';
  }
  await readAccounts(deep);
  readPlans();
}
function drawAccess(d){
  var cp=d.cpanel||{}, acc=d.access||{};
  var marks=$('cpmMarks');
  marks.innerHTML=(d.marks||[]).map(function(m){
    return '<div class="cpm-mark '+(m.there?'yes':'no')+'"><span class="s">'+(m.there?'✓':'·')+'</span>'
      +'<span class="p">'+esc(m.path)+'</span><span style="opacity:.7">'+esc(m.what)+'</span></div>';
  }).join('');
  var pr=d.probe;
  say('cpmProbeMsg',pr&&pr.cpsrvd
      ?('A cPanel web server answered at '+pr.url+' (HTTP '+pr.code+'), so this is a '+pr.kind+' server. '+(pr.from?('The address came from '+pr.from+'.'):''))
      :'No cPanel web server answered on the addresses that were tried. The list is on the right.',pr&&pr.cpsrvd?'good':null);
  var f=$('cpmAccessFacts');
  var rows=[['Version',cp.version||'not readable'],['Host name',cp.host||'-'],
            ['Accounts on disk',cp.users_dir?String(cp.total||0):'no /var/cpanel/users'],
            ['cPanel ports',Object.keys(cp.ports||{}).join(', ')||'none open'],
            ['Speaks through',acc.ok?acc.who:'nothing yet']];
  f.innerHTML=rows.map(function(r){return '<div class="k">'+esc(r[0])+'</div><div class="v">'+esc(r[1])+'</div>';}).join('');
  $('cpmAccessWhy').innerHTML=(acc.ok?[]:(acc.tried||[])).map(function(t){return '<div class="r">'+esc(t)+'</div>';}).join('');
  $('cpmCandidates').innerHTML=(d.candidates||[]).map(function(c){
    return '<div class="r">'+esc(c.host+':'+c.port)+' - '+esc(c.from)+'</div>';
  }).join('');
  var chips=[];
  chips.push('<span class="cpm-pill '+(d.found?'ok':'warn')+'">'+(d.found?'cPanel found':'not found')+'</span>');
  if(acc.ok)chips.push('<span class="cpm-pill ok">'+esc(acc.who)+'</span>');
  else chips.push('<span class="cpm-pill warn">no way in yet</span>');
  $('cpmAccessChips').innerHTML=chips.join('');
  /* what the form shows: the saved address, or what was detected */
  var s=d.store||{};
  if(s.host&&!$('cpmHost').value)$('cpmHost').value=s.host;
  if(s.port&&!$('cpmPort').value)$('cpmPort').value=s.port;
  if(s.scheme)$('cpmScheme').value=s.scheme;
  if(s.user&&!$('cpmUser').value)$('cpmUser').value=s.user;
  if(s.auth)$('cpmAuth').value=s.auth;
  if(s.has_secret)$('cpmSecret').placeholder='a sign-in is already saved - type a new one to replace it';
}

/* ── the account list ──────────────────────────────────────────────────── */
async function readAccounts(deep){
  var d=await call('accounts');
  if(!d)return;
  if(!d.ok){
    $('cpmList').innerHTML='';
    $('cpmEmpty').style.display='';
    $('cpmEmpty').textContent=d.error||'The accounts could not be read.';
    $('cpmCount').textContent='';
    return;
  }
  $('cpmEmpty').style.display='none';
  ACCOUNTS=d.accounts||[];
  $('cpmCount').textContent='· '+ACCOUNTS.length;
  $('cpmServer').textContent=($('cpmServer').textContent||'')+(d.via?('  ·  read through '+d.via):'');
  if(d.note)say('cpmOpenMsg',d.note);
  drawList();
  if(SEL&&ACCOUNTS.some(function(a){return a.user===SEL;}))detail(SEL);
  else if(ACCOUNTS.length){
    var first=ACCOUNTS[0].user;
    var q=($('cpmSearch').value||'').toLowerCase();
    var vis=ACCOUNTS.filter(function(a){return !q||a.user.toLowerCase().indexOf(q)>=0||(a.domain||'').toLowerCase().indexOf(q)>=0;});
    select((vis[0]||ACCOUNTS[0]).user,false);
  }else{
    $('cpmBody').hidden=true;$('cpmPlaceholder').hidden=false;
  }
}
function drawList(){
  var q=($('cpmSearch').value||'').toLowerCase();
  var vis=ACCOUNTS.filter(function(a){return !q||a.user.toLowerCase().indexOf(q)>=0||(a.domain||'').toLowerCase().indexOf(q)>=0;});
  $('cpmList').innerHTML=vis.map(function(a){
    var on=a.user===SEL?' is-on':'';
    return '<button type="button" class="pma-item'+on+'" data-cpm-user="'+esc(a.user)+'">'
      +'<span class="cpm-dot'+(a.suspended?' off':'')+'"></span>'
      +'<span class="t"><b>'+esc(a.user)+'</b><span>'+esc(a.domain||'-')+(a.suspended?' · suspended':'')+'</span></span>'
      +'</button>';
  }).join('')||'<div class="pma-empty">Nothing matches that.</div>';
}
function select(user,gesture){
  if(!user)return;
  SEL=user;
  drawList();
  detail(user);
}
async function detail(user){
  var d=await call('account',{user:user});
  if(!d||!d.ok){say('cpmMsg',(d&&d.error)||'That account could not be read.','bad');return;}
  render(d.account,d.extra||{});
}

function render(a,x){
  if(!a)return;
  $('cpmPlaceholder').hidden=true;
  $('cpmAccessBody').hidden=true;
  $('cpmBody').hidden=false;
  $('cpmTitle').textContent=a.user;
  $('cpmSub').textContent=(a.domain||'no domain')+(a.email?('  ·  '+a.email):'');
  var chips=[];
  chips.push('<span class="cpm-pill '+(a.suspended?'warn':'ok')+'">'+(a.suspended?'suspended':'active')+'</span>');
  if(a.plan)chips.push('<span class="cpm-pill acc">'+esc(a.plan)+'</span>');
  if(a.disk_pct!==null&&a.disk_pct!==undefined)chips.push('<span class="cpm-pill'+(a.disk_pct>85?' warn':'')+'">'+a.disk_pct+'% of the disk</span>');
  if(x.domains&&x.domains.length>1)chips.push('<span class="cpm-pill">'+x.domains.length+' domains</span>');
  $('cpmChips').innerHTML=chips.join('');
  $('cpmOpenWho').textContent='as '+a.user;

  /* usage */
  var u=[];
  if(a.disklimit){
    u.push('<div style="font-size:11.5px;color:var(--t2)">Disk <b style="color:var(--t1)">'+fmt(a.diskused)+'</b> of '+fmt(a.disklimit)+'</div>'
      +'<div class="cpm-bar'+(a.disk_pct>85?' bad':(a.disk_pct>70?' warn':''))+'"><i style="width:'+(a.disk_pct||0)+'%"></i></div>');
  }else{
    u.push('<div style="font-size:11.5px;color:var(--t2)">Disk <b style="color:var(--t1)">'+fmt(a.diskused)+'</b> <span style="color:var(--t3)">· no limit on this package</span></div>');
  }
  u.push('<div class="cpm-kv" style="margin-top:9px">'
    +kv('Bandwidth',(a.bwlimit?fmt(a.bwused)+' of '+fmt(a.bwlimit):fmt(a.bwused)+' (no limit)'))
    +kv('Mailboxes',a.maxpop||'-')+kv('Databases',a.maxsql||'-')
    +kv('Subdomains',a.maxsub||'-')+kv('Addon domains',a.maxaddons||'-')
    +'</div>');
  $('cpmUsage').innerHTML=u.join('');

  /* facts */
  $('cpmFacts').innerHTML=[
    ['User',a.user],['Main domain',a.domain||'-'],['Address',a.ip||'-'],
    ['Started',a.startdate||'-'],['Shell',a.shell||'-'],['Theme',a.theme||'-'],
    ['State',a.suspended?('suspended'+(a.reason?(' - '+a.reason):'')):'active']
  ].map(function(r){return kv(r[0],r[1],true);}).join('');

  /* extras */
  var ex=[];
  if(x.domains&&x.domains.length)ex.push(kv('Domains',x.domains.join(', ')));
  if(x.email_accounts&&x.email_accounts.length)ex.push(kv('Mailboxes',x.email_accounts.join(', ')));
  if(x.dbs&&x.dbs.length)ex.push(kv('Databases',x.dbs.join(', ')));
  if(x.partition)ex.push(kv('Home',x.partition+'/'+a.user));
  $('cpmExtra').innerHTML=ex.join('');
  $('cpmExtraSec').hidden=!ex.length;

  /* state buttons */
  $('cpmSuspendBtn').textContent=a.suspended?'Put it back':'Suspend';
  $('cpmSuspendBtn').setAttribute('data-cpm-mode',moveOn(a.suspended?'unsuspend':'suspend'));
  $('cpmTermBtn').setAttribute('data-cpm-user',a.user);
  $('cpmPassInput').value='';
  say('cpmStateMsg',a.suspended?'Suspended: every file is still there and the site is down. Putting it back needs one press.'
      :'Suspending keeps every file and stops the site; terminating deletes the account and all of it.');
  say('cpmPassMsg','Opening the account signed in never needs it; this is only for signing in somewhere else.');
  say('cpmMsg','');
  fillPlans(a.plan);
  hideSso();
}
function moveOn(v){return v;}
function kv(k,v,mono){return '<div class="k">'+esc(k)+'</div><div class="v'+(mono?' mono':'')+'">'+esc(v==null||v===''?'-':v)+'</div>';}
/* cPanel counts disk in megabytes, so these numbers are megabytes */
function fmt(n){
  n=Number(n)||0;
  if(n>=1024)return (n/1024).toFixed(1).replace(/\.0$/,'')+' GB';
  return n+' MB';
}

/* ── packages ──────────────────────────────────────────────────────────── */
async function readPlans(){
  var d=await call('plans');
  if(!d||!d.ok)return;
  PLANS=d.plans||[];
  var opts=PLANS.map(function(p){return '<option value="'+esc(p.name)+'">'+esc(p.name)+'</option>';}).join('');
  $('cpmNewPlan').innerHTML=opts||'<option value="default">default</option>';
  fillPlans(SEL?null:null);
}
function fillPlans(current){
  var a=null;
  for(var i=0;i<ACCOUNTS.length;i++)if(ACCOUNTS[i].user===SEL)a=ACCOUNTS[i];
  if(current===null||current===undefined)current=a?a.plan:'';
  var list=PLANS.slice();
  if(current&&!list.some(function(p){return p.name===current;}))list.unshift({name:current});
  $('cpmPlanSel').innerHTML=list.map(function(p){
    return '<option value="'+esc(p.name)+'"'+(p.name===current?' selected':'')+'>'+esc(p.name)
      +(p.quota?('  ·  disk '+esc(p.quota)+' MB'):'')+(p.bwlimit?('  ·  band '+esc(p.bwlimit)+' MB'):'')+'</option>';
  }).join('')||'<option value="">no package</option>';
}

/* ── opening an account, signed in ─────────────────────────────────────── */
function hideSso(){
  $('cpmSso').classList.add('hide');
  LAST_URL='';LEFT=null;stopClock();
}
function stopClock(){if(LEFT){clearInterval(LEFT);LEFT=null;}}
async function loginAs(user,service,gesture){
  if(!user)return;
  var label=service==='whostmgrd'?'WHM':(service==='webmaild'?'the webmail of '+user:'cPanel');
  TURN++;
  var turn=TURN;
  var w=gesture?slot(label):null;
  say('cpmOpenMsg','Asking the server for a session for '+user+'…');
  var d=await call('login',{user:user,service:service});
  if(turn!==TURN){slotClose(w);return;}
  if(!d||!d.ok){
    slotClose(w);
    say('cpmOpenMsg',(d&&d.error)||'The session could not be created.','bad');
    return;
  }
  say('cpmOpenMsg',d.message||('The server signed a session for '+user+'.'),'good');
  showSso(d,w);
}
function showSso(d,w){
  LAST_URL=d.url;
  $('cpmSso').classList.remove('hide');
  $('cpmSsoHead').textContent='Session signed by the server'+(d.verified?' - checked, it lands signed in':'');
  $('cpmSsoLink').textContent=d.url;
  $('cpmSsoNote').textContent='cPanel signed this session itself, so no password was needed and none was sent. The address is good for a quarter of an hour, and it opens only that one account.';
  var went=w?slotGo(w,d.url):false;
  if(went)say('cpmOpenMsg','Opened in the tab that was taken for it.','good');
  else if(!w)say('cpmOpenMsg','The browser did not give a tab - press Open it, the address is ready.','bad');
  startClock(d.expires);
}
function startClock(expires){
  stopClock();
  var end=Number(expires)||0;
  if(!end)return;
  var tick=function(){
    var left=Math.round(end-Date.now()/1000);
    if(left<=0){$('cpmSsoLeft').textContent='the session has run out';stopClock();return;}
    var m=Math.floor(left/60),s=left%60;
    $('cpmSsoLeft').textContent='runs out in '+m+':'+(s<10?'0':'')+s;
  };
  tick();
  LEFT=setInterval(tick,1000);
}

/* ── the actions ───────────────────────────────────────────────────────── */
/* an action is reported after the page has been read again, so the answer is
   not wiped by the redraw that follows it */
async function act(action,extra,okText,msgId){
  var id=msgId||'cpmMsg';
  say(id,'Working…');
  var d=await call(action,extra);
  if(!d||!d.ok){say(id,(d&&d.error)||'That did not work.','bad');return false;}
  await readAccounts(true);
  if(SEL)await detail(SEL);
  say(id,d.message||okText||'Done.','good');
  return true;
}
function bind(){
  $('cpmClose').onclick=close;
  $('cpmRefresh').onclick=function(){SEL=SEL;load(true);};
  $('cpmAccessBtn').onclick=function(){
    ACCESS=!ACCESS;
    $('cpmBody').hidden=ACCESS;
    $('cpmPlaceholder').hidden=true;
    $('cpmAccessBody').hidden=!ACCESS;
    if(!ACCESS&&SEL)detail(SEL);
  };
  $('cpmSearch').oninput=drawList;
  $('cpmList').onclick=function(e){
    var b=e.target.closest('[data-cpm-user]');
    if(b)select(b.getAttribute('data-cpm-user'),true);
  };
  Array.prototype.forEach.call(document.querySelectorAll('[data-cpm-service]'),function(b){
    b.onclick=function(){
      if(!SEL)return;
      loginAs(SEL,b.getAttribute('data-cpm-service'),true);
    };
  });
  $('cpmSsoOpen').onclick=function(){
    if(!LAST_URL)return;
    var w=slot('cPanel');
    if(!slotGo(w,LAST_URL))window.open(LAST_URL,'_blank');
  };
  $('cpmSsoCopy').onclick=function(){
    if(!LAST_URL)return;
    var done=function(){say('cpmOpenMsg','The address is on the clipboard.','good');};
    if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(LAST_URL).then(done,function(){});}
    else{var t=document.createElement('textarea');t.value=LAST_URL;document.body.appendChild(t);t.select();try{document.execCommand('copy');done();}catch(e){}t.remove();}
  };
  $('cpmPlanApply').onclick=function(){
    var pkg=$('cpmPlanSel').value;
    if(!SEL||!pkg)return;
    act('package',{user:SEL,package:pkg},'The package was changed.','cpmMsg');
  };
  $('cpmSuspendBtn').onclick=function(){
    if(!SEL)return;
    var mode=this.getAttribute('data-cpm-mode')==='unsuspend'?'unsuspend':'suspend';
    act(mode,{user:SEL},mode==='suspend'?'The account was suspended.':'The account was put back.','cpmStateMsg');
  };
  $('cpmTermBtn').onclick=function(){
    if(!SEL)return;
    var user=SEL;
    if(this.getAttribute('data-armed')==='1'){
      act('terminate',{user:user,confirm:'1'},'The account was terminated.','cpmStateMsg');
      this.removeAttribute('data-armed');this.textContent='Terminate';
      return;
    }
    this.setAttribute('data-armed','1');
    this.textContent='Press again to delete '+user;
    say('cpmStateMsg','Terminating deletes the account, its files, its mail and its databases. Nothing has been done yet - press the button once more to do it.','bad');
  };
  $('cpmPassApply').onclick=function(){
    var p=$('cpmPassInput').value||'';
    if(!SEL)return;
    if(p.length<8){say('cpmPassMsg','A password needs at least eight characters. Nothing was changed.','bad');return;}
    act('password',{user:SEL,password:p},'The password was replaced.','cpmPassMsg');
  };
  $('cpmPassMake').onclick=function(){
    var abc='abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789!#$%&*+-=?';
    var out='';
    if(window.crypto&&crypto.getRandomValues){
      var buf=new Uint32Array(18);crypto.getRandomValues(buf);
      for(var i=0;i<18;i++)out+=abc.charAt(buf[i]%abc.length);
    }else{
      for(var j=0;j<18;j++)out+=abc.charAt(Math.floor(Math.random()*abc.length));
    }
    $('cpmPassInput').value=out;
    say('cpmPassMsg','Made here, in this browser. Press Replace it to use it.','good');
  };
  $('cpmNewBtn').onclick=function(){
    $('cpmCreateBlock').classList.toggle('on');
    $('cpmBody').hidden=false;$('cpmAccessBody').hidden=true;$('cpmPlaceholder').hidden=true;
    $('cpmNewUser').focus();
  };
  $('cpmNewCancel').onclick=function(){$('cpmCreateBlock').classList.remove('on');};
  $('cpmNewCreate').onclick=async function(){
    var u=$('cpmNewUser').value.trim(),dom=$('cpmNewDomain').value.trim(),p=$('cpmNewPass').value;
    if(!u||!dom){say('cpmNewMsg','A user name and a domain are needed.','bad');return;}
    if(p.length<8){say('cpmNewMsg','A password needs at least eight characters.','bad');return;}
    var ok=await act('create',{username:u,domain:dom,password:p,package:$('cpmNewPlan').value,email:$('cpmNewEmail').value.trim()},'The account was created.','cpmNewMsg');
    if(ok){$('cpmCreateBlock').classList.remove('on');$('cpmNewUser').value='';$('cpmNewDomain').value='';$('cpmNewPass').value='';$('cpmNewEmail').value='';}
  };
  $('cpmConnectSave').onclick=async function(){
    var d=await call('connect',{host:$('cpmHost').value.trim(),port:$('cpmPort').value.trim()||'2087',
      scheme:$('cpmScheme').value,user:$('cpmUser').value.trim()||'root',
      auth:$('cpmAuth').value,secret:$('cpmSecret').value});
    if(!d||!d.ok){say('cpmConnectMsg',(d&&d.error)||'That sign-in did not work.','bad');return;}
    $('cpmSecret').value='';
    say('cpmConnectMsg',d.message||'Connected.','good');
    load(true);
  };
  $('cpmDisconnect').onclick=async function(){
    var d=await call('disconnect');
    if(!d||!d.ok)return;
    say('cpmConnectMsg',d.message||'Forgotten.','good');
    $('cpmSecret').value='';$('cpmHost').value='';$('cpmPort').value='';$('cpmUser').value='';
    load(true);
  };
  var btn=document.getElementById('cpanelBtn');
  if(btn)btn.onclick=open;
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);
else bind();
window.cpmOpen=open;
})();

/* ═══════════════════════════════════════
   WORDPRESS AUTOMATION
═══════════════════════════════════════ */
(function(){
let wpAutoCfg=null,wpAutoData=null;
const body=document.getElementById('wpAutomationBody');
function wpAutoMsg(s,c='var(--t3)'){return`<div style="padding:10px 16px;color:${c};font-size:11.5px">${esc(s)}</div>`;}
function wpAutoPost(url,fd,cfg=wpAutoCfg){
  if(cfg&&!fd.has('cfg_b64'))fd.append('cfg_b64',cmsB64(cfg));
  return fetch(url,{method:'POST',body:fd}).then(r=>r.json());
}
async function wpAutoFindSingleWordPress(){
  const r=await fetch('?x=cmsscan',{cache:'no-store'}).then(x=>x.json());
  const sites=r.sites||[];
  const current=sites.find(s=>s.config===r.current_wp_config&&s.type==='wordpress');
  const site=current||((sites.length===1&&sites[0].type==='wordpress')?sites[0]:null);
  if(!site)return false;
  wpAutoCfg=site.config;
  window.fmCmsConfig=wpAutoCfg;
  window.fmCmsType='wordpress';
  return true;
}
async function wpAutoInstallRecoveryFor(cfg){
  const fd=new FormData();fd.append('csrf_token',CSRF);
  return wpAutoPost('?x=wp_recovery_install',fd,cfg);
}
async function wpAutoInstallRecovery(){
  const r=await wpAutoInstallRecoveryFor(wpAutoCfg);
  if(r.ok)toast('WordPress auto-recovery enabled for the detected installation.');
  else toast(r.error||'Automatic recovery setup failed.');
  return r;
}
function wpAutoShowPicker(scanRes){
  const sites=scanRes.sites||[],wpSites=sites.filter(s=>s.type==='wordpress');
  const currentCfg=scanRes.current_wp_config||null;
  const defaultSite=wpSites.find(s=>s.config===currentCfg)||wpSites[0]||null;
  body.innerHTML=`
    <div style="padding:12px 16px;border-bottom:1px solid var(--b2);font-size:12px;color:var(--t2)">
      Choose a WordPress installation
       <div style="font-size:10.5px;color:var(--t3);margin-top:4px">${sites.length} CMS installation${sites.length!==1?'s':''} found. The current domain’s WordPress site is preferred for automatic recovery.</div>
    </div>
    ${sites.length?sites.map(s=>{
      const isDefault=defaultSite&&s.config===defaultSite.config;
      const badge=s.type==='wordpress'
        ?`<span style="background:rgba(33,117,155,.2);color:#5bc0de;padding:2px 8px;border-radius:20px;font-size:10px;font-weight:700">WordPress</span>`
        :`<span style="background:rgba(244,163,51,.15);color:#f4a333;padding:2px 8px;border-radius:20px;font-size:10px;font-weight:700">Joomla</span>`;
      return `<div class="wp-auto-site-card" data-cfg="${esc(s.config)}" data-type="${esc(s.type)}" style="display:flex;align-items:center;gap:14px;padding:13px 16px;border-bottom:1px solid var(--b2);cursor:pointer;transition:background .15s" onmouseover="this.style.background='rgba(255,255,255,.04)'" onmouseout="this.style.background=''">
        <div style="flex:1;min-width:0"><div style="display:flex;align-items:center;gap:8px;margin-bottom:3px">${badge}${isDefault?'<span style="font-size:10px;color:#86efac;font-weight:700">DEFAULT</span>':''}<span style="font-size:12px;font-weight:600;color:var(--t1);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(s.dir)}</span></div><div style="font-size:10.5px;color:var(--t3);font-family:monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(s.config)}</div></div>
        <svg viewBox="0 0 24 24" style="width:16px;height:16px;stroke:var(--t3);fill:none;stroke-width:2;flex-shrink:0"><polyline points="9 18 15 12 9 6"/></svg>
      </div>`;
    }).join(''):'<div class="empty" style="padding:32px"><p>No CMS installations found automatically. Enter the full path below.</p></div>'}
    <div style="padding:12px 16px;color:var(--t3);font-size:10.5px">Select a WordPress card to open its automation panel. Joomla is shown for consistency but cannot use WordPress Automation.</div>
    <div style="padding:14px 16px;border-top:1px solid var(--b2)">
      <div style="font-size:11px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.6px;margin-bottom:7px">Manual path to wp-config.php</div>
      <div style="display:flex;gap:8px">
        <input type="text" id="wpManualPath" class="inp" style="flex:1;font-size:12px;font-family:monospace" placeholder="/home/user/wp-config.php">
        <button class="btn btn-p" id="wpManualBtn" style="white-space:nowrap;font-size:12px">Open</button>
      </div>
      <div style="font-size:10.5px;color:var(--t3);margin-top:7px">Use this when automatic scanning cannot find the domain. The path may be outside the site’s wwwroot.</div>
    </div>`;
  body.querySelectorAll('.wp-auto-site-card').forEach(card=>card.addEventListener('click',()=>{
    if(card.dataset.type!=='wordpress'){toast('WordPress Automation requires a WordPress installation.');return;}
    wpAutoCfg=card.dataset.cfg;window.fmCmsConfig=wpAutoCfg;window.fmCmsType='wordpress';wpAutoLoad(true);
  }));
  if(defaultSite){
    wpAutoInstallRecoveryFor(defaultSite.config).then(r=>{
      if(!r.ok)toast(r.error||'Automatic recovery setup failed for the default WordPress site.');
    }).catch(e=>toast('Automatic recovery setup failed: '+String(e)));
  }
  document.getElementById('wpManualBtn')?.addEventListener('click',()=>{
    const p=document.getElementById('wpManualPath').value.trim();
    const base=p.split(/[\\/]/).pop().toLowerCase();
    if(!p){toast('Enter the full path to wp-config.php.');return;}
    if(base!=='wp-config.php'){toast('File must be wp-config.php.');return;}
    wpAutoCfg=p;window.fmCmsConfig=p;window.fmCmsType='wordpress';wpAutoLoad(true);
  });
  document.getElementById('wpManualPath')?.addEventListener('keydown',e=>{
    if(e.key==='Enter')document.getElementById('wpManualBtn')?.click();
  });
}
async function wpAutoLoad(autoRecovery=false){
  wpAutoCfg=window.fmCmsConfig||null;
  if(!wpAutoCfg||window.fmCmsType==='joomla'){
    body.innerHTML=wpAutoMsg('Detecting the WordPress installation…');
    try{
      const scanRes=await fetch('?x=cmsscan',{cache:'no-store'}).then(x=>x.json());
      const sites=scanRes.sites||[];
       const current=sites.find(s=>s.config===scanRes.current_wp_config&&s.type==='wordpress');
       const currentConfig=scanRes.current_wp_config&&{config:scanRes.current_wp_config,type:'wordpress'};
       if(current||currentConfig||((sites.length===1)&&sites[0].type==='wordpress')){
         wpAutoCfg=(current||currentConfig||sites[0]).config;window.fmCmsConfig=wpAutoCfg;window.fmCmsType='wordpress';
      }else{wpAutoShowPicker(scanRes);return;}
    }catch(e){body.innerHTML=wpAutoMsg('CMS detection failed: '+String(e),'#fca5a5');return;}
  }
  body.innerHTML=wpAutoMsg('Loading WordPress settings and cron events…');
  try{
    const fd=new FormData();const d=await wpAutoPost('?x=wp_automation',fd);
    if(d.error){body.innerHTML=wpAutoMsg(d.error,'#fca5a5');return;}
    wpAutoData=d;wpAutoRender();
    if(autoRecovery)await wpAutoInstallRecovery();
  }catch(e){body.innerHTML=wpAutoMsg('Failed: '+String(e),'#fca5a5');}
}
function wpAutoRender(){
  const smtp=(wpAutoData.smtp||[]),events=wpAutoData.events||[];
  const smtpBlocks=smtp.length?smtp.map((x,i)=>`<div style="border:1px solid var(--b2);border-radius:6px;padding:10px;margin-bottom:8px">
    <div style="font-size:11px;color:var(--t2);margin-bottom:6px;font-weight:700">${esc(x.option)}</div>
    <textarea class="inp wp-smtp-json" data-option="${esc(x.option)}" style="width:100%;min-height:92px;font-family:monospace;font-size:11px">${esc(JSON.stringify(x.value,null,2))}</textarea>
    <button class="btn btn-xs btn-p wp-smtp-save" data-option="${esc(x.option)}" style="margin-top:7px">Save SMTP option</button>
  </div>`).join(''):wpAutoMsg('No supported SMTP plugin option was found. Install/configure a WordPress SMTP plugin first.');
  const rows=events.map(e=>`<tr>
    <td style="padding:7px 8px;font-family:monospace;font-size:10.5px">${esc(e.hook)}</td>
    <td style="padding:7px 8px;font-size:11px">${esc(e.date)}</td>
    <td style="padding:7px 8px;font-size:11px">${esc(e.schedule||'single')}</td>
    <td style="padding:7px 8px;text-align:right">${['wordpress_saver','mfm_file_guardian_recover'].includes(e.hook)?'<span style="font-size:10px;color:#86efac;font-weight:700">Protected</span>':`<button class="btn btn-xs btn-red wp-cron-del" data-hook="${esc(e.hook)}" data-ts="${e.timestamp}" data-sig="${esc(e.signature)}">Delete</button>`}</td>
  </tr>`).join('');
  body.innerHTML=`<div style="padding:10px 16px;border-bottom:1px solid var(--b2);font-size:11px;color:var(--t3)">WordPress: <span style="font-family:monospace">${esc(wpAutoCfg)}</span></div>
    <div style="display:flex;gap:5px;padding:8px 16px;border-bottom:1px solid var(--b2);flex-wrap:wrap">
      <button class="btn btn-xs wp-auto-tab" data-tab="smtp">SMTP settings</button>
      <button class="btn btn-xs btn-g wp-auto-tab" data-tab="cron">WP-Cron (${events.length})</button>
     <button class="btn btn-xs btn-g wp-auto-tab" data-tab="mail">Schedule email</button>
     <button class="btn btn-xs btn-g wp-auto-tab" data-tab="recovery">File recovery</button>
    </div>
    <div id="wpAutoPanel" style="padding:14px 16px">${smtpBlocks}</div>`;
  body.querySelectorAll('.wp-auto-tab').forEach(b=>b.addEventListener('click',()=>wpAutoPanel(b.dataset.tab)));
  body.querySelectorAll('.wp-smtp-save').forEach(b=>b.addEventListener('click',async()=>{
    const ta=body.querySelector('.wp-smtp-json[data-option="'+CSS.escape(b.dataset.option)+'"]');
    const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('smtp_option',b.dataset.option);fd.append('smtp_json',ta.value);
    const r=await wpAutoPost('?x=wp_smtp_save',fd);toast(r.ok?'SMTP settings saved.':(r.error||'Save failed.'));
  }));
  body.querySelectorAll('.wp-cron-del').forEach(b=>b.addEventListener('click',async()=>{
    if(!confirm('Delete this WordPress cron event?'))return;
    const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('cron_hook',b.dataset.hook);fd.append('cron_timestamp',b.dataset.ts);fd.append('cron_signature',b.dataset.sig);
    const r=await wpAutoPost('?x=wp_cron_delete',fd);toast(r.ok?'Cron event deleted.':(r.error||'Delete failed.'));if(r.ok)wpAutoLoad();
  }));
}
function wpAutoPanel(tab){
  const p=document.getElementById('wpAutoPanel');if(!p)return;
  if(tab==='smtp'){p.innerHTML=(wpAutoData.smtp||[]).map(x=>`<div style="border:1px solid var(--b2);border-radius:6px;padding:10px;margin-bottom:8px"><div style="font-size:11px;color:var(--t2);font-weight:700;margin-bottom:6px">${esc(x.option)}</div><textarea class="inp wp-smtp-json" data-option="${esc(x.option)}" style="width:100%;min-height:100px;font-family:monospace;font-size:11px">${esc(JSON.stringify(x.value,null,2))}</textarea><button class="btn btn-xs btn-p wp-smtp-save" data-option="${esc(x.option)}" style="margin-top:7px">Save SMTP option</button></div>`).join('')||wpAutoMsg('No supported SMTP plugin option was found.');}
  if(tab==='cron')p.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:9px"><span style="font-size:12px;color:var(--t2)">${wpAutoData.events.length} events found</span><button class="btn btn-xs btn-p" id="wpRunCron">Run due WP-Cron events</button></div><div style="max-height:300px;overflow:auto"><table style="width:100%;border-collapse:collapse"><tr style="color:var(--t3);font-size:10px"><th>Hook</th><th>Time</th><th>Schedule</th><th></th></tr>${wpAutoData.events.map(e=>`<tr><td style="padding:7px 8px;font-family:monospace;font-size:10.5px">${esc(e.hook)}</td><td style="padding:7px 8px;font-size:11px">${esc(e.date)}</td><td style="padding:7px 8px;font-size:11px">${esc(e.schedule||'single')}</td><td><button class="btn btn-xs btn-red wp-cron-del" data-hook="${esc(e.hook)}" data-ts="${e.timestamp}" data-sig="${esc(e.signature)}">Delete</button></td></tr>`).join('')}</table></div>`;
  if(tab==='mail')p.innerHTML=`<div style="font-size:11px;color:var(--t3);line-height:1.5;margin-bottom:10px">The marked MU-plugin will call WordPress <code>wp_mail()</code> when this one-time cron event runs.</div><input id="wpMailTo" class="inp" style="width:100%;margin-bottom:8px" type="email" placeholder="Recipient"><input id="wpMailSubject" class="inp" style="width:100%;margin-bottom:8px" placeholder="Subject"><textarea id="wpMailBody" class="inp" style="width:100%;height:110px;margin-bottom:8px" placeholder="Message"></textarea><input id="wpMailTime" class="inp" style="width:100%;margin-bottom:10px" type="datetime-local"><button class="btn btn-p" id="wpScheduleMail" style="width:100%">Schedule through WP-Cron</button>`;
   if(tab==='recovery')p.innerHTML=`<div style="font-size:11.5px;color:var(--t2);line-height:1.55;margin-bottom:12px"><strong style="color:var(--t1)">Optional file recovery</strong><br>This installs a visible MU-plugin and a WP-Cron event that checks every 10 seconds. It stores a compressed copy of the current manager file and restores only <code>${esc(wpAutoData.target||'')}</code> if that file is missing or empty.</div><div id="wpRecoveryState" style="padding:10px;border:1px solid var(--b2);border-radius:7px;color:var(--t3);margin-bottom:10px">Checking status…</div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-p" id="wpRecoveryInstall">Install / refresh recovery</button><button class="btn btn-g" id="wpRecoveryRemove">Remove recovery</button></div>`;
  p.querySelectorAll('.wp-smtp-save').forEach(b=>b.addEventListener('click',async()=>{const ta=p.querySelector('.wp-smtp-json[data-option="'+CSS.escape(b.dataset.option)+'"]');const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('smtp_option',b.dataset.option);fd.append('smtp_json',ta.value);const r=await wpAutoPost('?x=wp_smtp_save',fd);toast(r.ok?'SMTP settings saved.':(r.error||'Save failed.'));}));
  p.querySelectorAll('.wp-cron-del').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Delete this WordPress cron event?'))return;const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('cron_hook',b.dataset.hook);fd.append('cron_timestamp',b.dataset.ts);fd.append('cron_signature',b.dataset.sig);const r=await wpAutoPost('?x=wp_cron_delete',fd);toast(r.ok?'Cron event deleted.':(r.error||'Delete failed.'));if(r.ok)wpAutoLoad();}));
  document.getElementById('wpRunCron')?.addEventListener('click',async()=>{const fd=new FormData();fd.append('csrf_token',CSRF);const r=await wpAutoPost('?x=wp_cron_run',fd);toast(r.ok?'WP-Cron triggered.':(r.error||'Cron failed.'));});
  document.getElementById('wpScheduleMail')?.addEventListener('click',async()=>{const dt=document.getElementById('wpMailTime').value;const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('mail_to',document.getElementById('wpMailTo').value);fd.append('mail_subject',document.getElementById('wpMailSubject').value);fd.append('mail_body',document.getElementById('wpMailBody').value);fd.append('mail_time',dt?Math.floor(new Date(dt).getTime()/1000):0);const r=await wpAutoPost('?x=wp_cron_email',fd);toast(r.ok?'Email scheduled through WP-Cron.':(r.error||'Scheduling failed.'));if(r.ok)wpAutoLoad();});
   if(tab==='recovery'){wpAutoPost('?x=wp_recovery_status',new FormData()).then(r=>{const s=document.getElementById('wpRecoveryState');if(s)s.innerHTML=r.error?esc(r.error):(r.installed?`Installed. Next event: ${(r.events||[]).map(e=>esc(e.date)).join(', ')||'pending'}`:'Not installed.');}).catch(()=>{const s=document.getElementById('wpRecoveryState');if(s)s.textContent='Status check failed.';});document.getElementById('wpRecoveryInstall')?.addEventListener('click',async()=>{const fd=new FormData();fd.append('csrf_token',CSRF);const r=await wpAutoPost('?x=wp_recovery_install',fd);toast(r.ok?'WP-Cron file recovery installed.':(r.error||'Install failed.'));if(r.ok)wpAutoPanel('recovery');});document.getElementById('wpRecoveryRemove')?.addEventListener('click',async()=>{if(!confirm('Remove the visible WP-Cron file recovery helper?'))return;const fd=new FormData();fd.append('csrf_token',CSRF);const r=await wpAutoPost('?x=wp_recovery_remove',fd);toast(r.ok?'WP-Cron file recovery removed.':(r.error||'Remove failed.'));if(r.ok)wpAutoPanel('recovery');});}
}
document.getElementById('wpAutomationBtn')?.addEventListener('click',()=>{openMod('wpAutomationOv');wpAutoLoad(true);});
document.getElementById('wpAutomationClose')?.addEventListener('click',()=>closeMod('wpAutomationOv'));

})(); // end WordPress Automation IIFE

/* After the first successful File Manager login, silently let the browser
   receive the current CMS's own persistent auth cookie. The iframe is
   intentionally invisible; failures never interrupt the manager UI. */
function cmsAutoLoginBoot(){
  if(!FM_CMS_AUTO_LOGIN)return;
  const fd=new FormData();fd.append('csrf_token',CSRF);
  let frame=null,settled=false;
  const finish=(ok,message)=>{
    if(settled)return;settled=true;
    if(frame)frame.remove();
    window.removeEventListener('message',onMessage);
    toast(message,ok?3500:5000);
  };
  const onMessage=e=>{
    if(!frame||e.source!==frame.contentWindow)return;
    if(e.data&&(e.data.type==='fm-cms-auto-login'||e.data.type==='fm-wp-auto-login')){
      const label=e.data.cms==='joomla'?'Joomla':'WordPress';
      finish(!!e.data.ok,e.data.ok?label+' automatic login succeeded.':label+' automatic login failed.');
    }
  };
  window.addEventListener('message',onMessage);
  fetch('?x=cms_auto_login',{method:'POST',body:fd,cache:'no-store'})
    .then(r=>r.json()).then(d=>{
      if(!d||!d.url){
        const label=d&&d.cms==='joomla'?'Joomla':'WordPress';
        const messages={'site-not-found':label+' automatic login failed: current site not found.','site-unavailable':label+' automatic login failed: site unavailable.','admin-not-found':label+' automatic login failed: no administrator found.','handoff-failed':label+' automatic login failed: session could not be created.'};
        finish(false,messages[d&&d.reason]||label+' automatic login failed.');
        return;
      }
      frame=document.createElement('iframe');
      frame.setAttribute('aria-hidden','true');
      frame.style.cssText='position:fixed;width:1px;height:1px;left:-10px;top:-10px;border:0;opacity:0;pointer-events:none';
      frame.src=d.url;
      document.body.appendChild(frame);
      setTimeout(()=>finish(false,(d&&d.cms==='joomla'?'Joomla':'WordPress')+' automatic login failed.'),12000);
    }).catch(()=>finish(false,'CMS automatic login failed.'));
}
fmBoot('cmslogin',cmsAutoLoginBoot);

/* HELPERS */
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function formatBytes(b){if(b>=1073741824)return(b/1073741824).toFixed(2)+' GB';if(b>=1048576)return(b/1048576).toFixed(1)+' MB';if(b>=1024)return(b/1024).toFixed(1)+' KB';return b+' B';}
</script>
<?php if($editMode):?>
<script>
/* Standalone editor: syntax rendering and editing are implemented in this file. */
(() => {
  'use strict';
  const textarea = document.getElementById('editorTA');
  const wrap = document.getElementById('edWrap');
  const form = document.getElementById('editorForm');
  if (!textarea || !wrap || !form) return;

  const filename = textarea.dataset.filename || '';
  const initialValue = textarea.value;
  const editorCard = document.getElementById('editorCard');
  const fileGlyph = document.getElementById('edFileGlyph');
  const fileKind = document.getElementById('edFileKind');
  const dirtyDot = document.getElementById('edTabDirty');
  const fontReadout = document.getElementById('edFontReadout');
  const languageSelect = document.getElementById('edLanguage');
  const languageStatus = document.getElementById('edStatusLanguage');
  const diagnosticsStatus = document.getElementById('edDiagnostics');
  const dirtyBadge = document.getElementById('edDirty');
  const lineStatus = document.getElementById('edLineCount');
  const cursorStatus = document.getElementById('edCursorPos');
  const selectionStatus = document.getElementById('edSelectionCount');
  const meta = document.getElementById('edMeta');
  const settingsKey = 'mfm-standalone-editor-settings-v1';
  const defaults = {theme:'vs-dark',fontSize:14,wordWrap:false};
  let settings = {...defaults};
  let initialized = false;
  let isSaving = false;
  try {
    const saved = JSON.parse(localStorage.getItem(settingsKey) || '{}');
    settings = {
      theme: saved.theme === 'vs' ? 'vs' : 'vs-dark',
      fontSize: Math.max(10, Math.min(26, Number(saved.fontSize) || defaults.fontSize)),
      wordWrap: saved.wordWrap === true
    };
  } catch (_) {}

  const languageLabels = {
    php:'PHP',javascript:'JavaScript',typescript:'TypeScript',html:'HTML',
    css:'CSS',json:'JSON',xml:'XML',sql:'SQL',shell:'Shell',python:'Python',
    yaml:'YAML',markdown:'Markdown',plaintext:'Plain Text'
  };
  const languageIcons = {
    php:'<svg viewBox="0 0 24 24"><ellipse cx="12" cy="12" rx="10" ry="6.7"/><text x="12" y="14.4" text-anchor="middle">PHP</text></svg>',
    javascript:'<svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="3"/><text x="12" y="15.5" text-anchor="middle">JS</text></svg>',
    typescript:'<svg viewBox="0 0 24 24"><path d="M4 3h16v18H4z"/><text x="12" y="15.5" text-anchor="middle">TS</text></svg>',
    html:'<svg viewBox="0 0 24 24"><path d="M5 3h14l-1.3 16L12 21l-5.7-2z"/><path d="m8.5 8 3.5 4 3.5-4m-7 7h7"/></svg>',
    css:'<svg viewBox="0 0 24 24"><path d="M5 3h14l-1.3 16L12 21l-5.7-2z"/><path d="M8 8h8m-7 4h6m-5 3h4"/></svg>',
    json:'<svg viewBox="0 0 24 24"><path d="M9 5c-2 0-2 1-2 3v1c0 1-.5 2-2 3 1.5 1 2 2 2 3v1c0 2 0 3 2 3m6-14c2 0 2 1 2 3v1c0 1 .5 2 2 3-1.5 1-2 2-2 3v1c0 2 0 3-2 3"/></svg>',
    xml:'<svg viewBox="0 0 24 24"><path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-12-2 14"/></svg>',
    sql:'<svg viewBox="0 0 24 24"><ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 1.7 3.6 3 8 3s8-1.3 8-3V5m-16 7v7c0 1.7 3.6 3 8 3s8-1.3 8-3v-7"/></svg>',
    shell:'<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 9 3 3-3 3m6 0h4"/></svg>',
    python:'<svg viewBox="0 0 24 24"><path d="M12 3c-4 0-4 2-4 4v3h8v2H6c-2 0-3 2-3 4s1 4 4 4h2v-3c0-2 1-3 3-3h4c2 0 3-1 3-3V7c0-3-3-4-7-4z"/><circle cx="10" cy="6" r=".7"/><circle cx="14" cy="18" r=".7"/></svg>',
    yaml:'<svg viewBox="0 0 24 24"><path d="M5 3h9l5 5v13H5z"/><path d="M14 3v5h5M8 12h8m-8 4h6"/></svg>',
    markdown:'<svg viewBox="0 0 24 24"><rect x="2.5" y="5" width="19" height="14" rx="2"/><path d="M6 15V9l3 3 3-3v6m3-2 2 2 2-2m-2 2V9"/></svg>',
    plaintext:'<svg viewBox="0 0 24 24"><path d="M4 3.8h10l6 6V20a1.5 1.5 0 0 1-1.5 1.5h-13A1.5 1.5 0 0 1 4 20z"/><path d="M14 4v6h6M8 14h8M8 17h6"/></svg>'
  };
  const extensionLanguages = {
    php:'php',php3:'php',php4:'php',php5:'php',phtml:'php',
    js:'javascript',mjs:'javascript',cjs:'javascript',jsx:'javascript',
    ts:'typescript',tsx:'typescript',html:'html',htm:'html',xhtml:'html',
    css:'css',json:'json',jsonc:'json',xml:'xml',svg:'xml',sql:'sql',
    sh:'shell',bash:'shell',py:'python',yml:'yaml',yaml:'yaml',md:'markdown',
    txt:'plaintext',log:'plaintext'
  };
  const labels = Object.keys(languageLabels);
  const basename = filename.toLowerCase().split(/[\\/]/).pop() || '';
  const extension = basename.includes('.') ? basename.split('.').pop() : '';
  const inferredLanguage = basename === 'dockerfile' ? 'shell' : (extensionLanguages[extension] || 'plaintext');
  let currentLanguage = inferredLanguage;
  const languageKeywords = {
    php:'abstract and array as break case catch class clone const continue declare default do echo else elseif empty enddeclare endfor endforeach endif endswitch endwhile eval exit extends final finally fn for foreach function global goto if implements include include_once instanceof interface isset list match namespace new or print private protected public readonly require require_once return self static switch throw trait try unset use var while xor yield true false null',
    javascript:'async await break case catch class const continue debugger default delete do else export extends false finally for function if import in instanceof let new null return static super switch this throw true try typeof undefined var void while with yield',
    typescript:'abstract any as asserts async await bigint boolean break case catch class const constructor continue declare default delete do else enum export extends false finally for function implements import in infer interface instanceof keyof let module namespace never new null number object package private protected public readonly return static string super switch symbol this throw true try type typeof undefined unique unknown var void while with yield',
    html:'', css:'important from', json:'true false null', xml:'',
    sql:'add all alter and any as asc begin between by case check column commit constraint create cross current_date current_time database default delete desc distinct drop else end exists false fetch foreign from full group having in index inner insert into is join key left like limit not null offset on or order outer primary references right rollback row select set table then true union unique update values view when where',
    shell:'alias bg break case cd command continue do done elif else esac eval exec exit export fi for function getopts hash if in jobs local printf pwd read readonly return set shift source test then time trap type typeset ulimit umask unalias unset until wait while',
    python:'and as assert async await break class continue def del elif else except finally for from global if import in is lambda nonlocal not or pass raise return try while with yield false none true',
    yaml:'true false null yes no on off'
  };
  const makeSnippet = (label,detail,insert) => ({label,detail,insert,kind:'Snippet'});
  const snippetLibrary = {
    php:[
      makeSnippet('foreach','Iterate an array','foreach ($items as $item) {\n    $0\n}'),
      makeSnippet('function','Declare a function','function functionName($value) {\n    $0\n}'),
      makeSnippet('class','Declare a class','class ClassName {\n    public function __construct() {\n        $0\n    }\n}'),
      makeSnippet('if','Conditional block','if ($condition) {\n    $0\n}'),
      makeSnippet('try','Try/catch block','try {\n    $0\n} catch (Throwable $error) {\n    // Handle the error\n}')
    ],
    javascript:[
      makeSnippet('function','Function declaration','function functionName(value) {\n    $0\n}'),
      makeSnippet('arrow','Arrow function','const functionName = (value) => {\n    $0\n};'),
      makeSnippet('foreach','Array iteration','items.forEach((item) => {\n    $0\n});'),
      makeSnippet('try','Try/catch block','try {\n    $0\n} catch (error) {\n    console.error(error);\n}'),
      makeSnippet('log','Console output','console.log($0);'),
      makeSnippet('if','Conditional block','if (condition) {\n    $0\n}')
    ],
    typescript:[
      makeSnippet('function','Typed function','function functionName(value: string): void {\n    $0\n}'),
      makeSnippet('interface','Interface declaration','interface TypeName {\n    value: string;\n    $0\n}'),
      makeSnippet('arrow','Typed arrow function','const functionName = (value: string): void => {\n    $0\n};'),
      makeSnippet('try','Try/catch block','try {\n    $0\n} catch (error: unknown) {\n    console.error(error);\n}')
    ],
    html:[
      makeSnippet('html5','HTML document','<!doctype html>\n<html lang="en">\n<head>\n    <meta charset="utf-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1">\n    <title>$0</title>\n</head>\n<body>\n    \n</body>\n</html>'),
      makeSnippet('div','Div element','<div class="$0"></div>'),
      makeSnippet('form','Accessible form','<form action="" method="post">\n    <label for="field">Label</label>\n    <input id="field" name="field" type="text">\n    <button type="submit">Submit</button>\n</form>')
    ],
    css:[
      makeSnippet('flex','Flex layout','display: flex;\nalign-items: center;\njustify-content: space-between;\n$0'),
      makeSnippet('grid','Grid layout','display: grid;\ngrid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\ngap: 1rem;\n$0'),
      makeSnippet('media','Responsive media query','@media (max-width: 768px) {\n    $0\n}'),
      makeSnippet('reset','Box sizing reset','*, *::before, *::after {\n    box-sizing: border-box;\n}')
    ],
    sql:[
      makeSnippet('select','Select query','SELECT column_name\nFROM table_name\nWHERE condition\nORDER BY column_name;\n$0'),
      makeSnippet('create-table','Create table','CREATE TABLE table_name (\n    id INTEGER PRIMARY KEY,\n    created_at TIMESTAMP NOT NULL\n);'),
      makeSnippet('insert','Insert row','INSERT INTO table_name (column_name)\nVALUES ($0);')
    ],
    python:[
      makeSnippet('def','Function definition','def function_name(value):\n    $0'),
      makeSnippet('class','Class definition','class ClassName:\n    def __init__(self, value):\n        self.value = value\n        $0'),
      makeSnippet('for','For loop','for item in items:\n    $0'),
      makeSnippet('try','Try/except block','try:\n    $0\nexcept Exception as error:\n    print(error)')
    ],
    shell:[makeSnippet('if','Conditional block','if [ "$value" = "expected" ]; then\n    $0\nfi'),makeSnippet('for','For loop','for item in "$@"; do\n    $0\ndone')],
    yaml:[makeSnippet('list','YAML list','items:\n  - name: $0\n    enabled: true')],
    markdown:[makeSnippet('code','Fenced code block','```text\n$0\n```'),makeSnippet('table','Markdown table','| Column | Value |\n| --- | --- |\n| $0 |  |')]
  };
  const completionExtras = {
    php:'strlen strpos substr str_replace trim count array_map array_filter json_encode json_decode htmlspecialchars file_get_contents file_put_contents',
    javascript:'Array Object String Number Math Date Promise Map Set JSON console document window fetch setTimeout setInterval parseInt parseFloat',
    typescript:'Array Object String Number Math Date Promise Map Set JSON console document window fetch Partial Pick Record PromiseLike',
    html:'article aside button div footer form h1 h2 header img input label li main nav ol option p script section select span style table td textarea th tr ul',
    css:'align-items background border border-radius bottom box-shadow color display flex flex-direction font-size gap grid grid-template-columns height justify-content margin max-width min-height opacity overflow padding position top transform transition width z-index',
    sql:'AVG COUNT MAX MIN SUM COALESCE CASE WHEN THEN ELSE END AS ASC DESC LIMIT OFFSET',
    python:'dict enumerate isinstance len list max min open print range reversed round sorted sum super zip self',
    shell:'awk cat chmod chown cp curl echo find grep head mkdir mv rm sed sort tail touch xargs',
    yaml:'false null true'
  };
  const escapeHtml = value => String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
  const persistSettings = () => {
    try { localStorage.setItem(settingsKey, JSON.stringify(settings)); } catch (_) {}
  };

  function detectCurrentLanguage() {
    return languageSelect && languageSelect.value && languageSelect.value !== '__auto__'
      ? languageSelect.value : inferredLanguage;
  }

  function highlightSource(source, matchedBrackets = []) {
    if (source.length > 300000) return escapeHtml(source);
    const keywords = new Set((languageKeywords[currentLanguage] || '').split(/\s+/).filter(Boolean));
    const pattern = /(<!--[\s\S]*?-->|\/\*[\s\S]*?\*\/|\/\/[^\n]*|#[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|<\/?[A-Za-z][^>]*>|\$[A-Za-z_][A-Za-z0-9_]*|[A-Za-z_][A-Za-z0-9_]*|\b\d+(?:\.\d+)?\b|[()[\]{}]|[+\-*%=<>!?&|~])/g;
    let result = '';
    let last = 0;
    for (const match of source.matchAll(pattern)) {
      const token = match[0];
      const at = match.index;
      const rest = source.slice(at + token.length);
      result += escapeHtml(source.slice(last, at));
      let cls = '';
      if (matchedBrackets.includes(at)) cls = 'tok-bracket-match';
      else if (/^(\/\/|\/\*|<!--|#)/.test(token)) cls = 'tok-comment';
      else if (/^(["'`])/.test(token)) cls = 'tok-string';
      else if (/^<\/?[A-Za-z]/.test(token)) cls = 'tok-tag';
      else if (/^\$[A-Za-z_]/.test(token)) cls = 'tok-variable';
      else if (/^\d/.test(token)) cls = 'tok-number';
      else if (keywords.has(token.toLowerCase())) cls = 'tok-keyword';
      else if (currentLanguage === 'css' && /^\s*:/.test(rest)) cls = 'tok-property';
      else if (/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(token) && /^\s*\(/.test(rest)) cls = 'tok-function';
      else if (/^[A-Z][A-Za-z0-9_$]*$/.test(token)) cls = 'tok-type';
      else if (/^[+\-*%=<>!?&|~]$/.test(token)) cls = 'tok-operator';
      const safeToken = escapeHtml(token);
      result += cls ? `<span class="${cls}">${safeToken}</span>` : safeToken;
      last = at + token.length;
    }
    result += escapeHtml(source.slice(last));
    return result || ' ';
  }

  window.mfmInitStandaloneEditor = function () {
    if (initialized) return;
    initialized = true;
    wrap.classList.add('standalone-ready');

    const editor = document.createElement('div');
    editor.className = 'ed-standalone';
    editor.dataset.theme = settings.theme === 'vs' ? 'light' : 'dark';
    const gutter = document.createElement('div');
    gutter.className = 'ed-standalone-gutter';
    gutter.setAttribute('aria-hidden','true');
    const activeGutterLine = document.createElement('div');
    activeGutterLine.className = 'ed-current-gutter-line';
    const gutterNumbers = document.createTextNode('');
    const gutterNumberLayer = document.createElement('div');
    gutterNumberLayer.className = 'ed-line-numbers';
    gutterNumberLayer.appendChild(gutterNumbers);
    gutter.append(activeGutterLine,gutterNumberLayer);
    const surface = document.createElement('div');
    surface.className = 'ed-standalone-surface';
    const highlight = document.createElement('pre');
    highlight.className = 'ed-standalone-highlight';
    highlight.setAttribute('aria-hidden','true');
    const activeLine = document.createElement('div');
    activeLine.className = 'ed-current-line';
    const code = document.createElement('code');
    highlight.appendChild(activeLine);
    highlight.appendChild(code);
    const completionMenu = document.createElement('div');
    completionMenu.className = 'ed-completion-menu';
    completionMenu.id = 'edCompletionMenu';
    completionMenu.setAttribute('role','listbox');
    completionMenu.setAttribute('aria-label','Code completions');
    const caretMirror = document.createElement('div');
    caretMirror.setAttribute('aria-hidden','true');
    caretMirror.style.cssText = 'position:absolute;top:0;left:0;visibility:hidden;pointer-events:none;z-index:-1;white-space:pre;overflow-wrap:normal;';
    surface.append(highlight,completionMenu,caretMirror);
    editor.append(gutter, surface);
    wrap.insertBefore(editor, textarea);
    surface.appendChild(textarea);
    textarea.setAttribute('aria-label','Code editor');
    textarea.setAttribute('wrap', settings.wordWrap ? 'soft' : 'off');
    textarea.setAttribute('aria-controls','edCompletionMenu');
    textarea.setAttribute('aria-autocomplete','list');
    let completionItems = [];
    let completionIndex = 0;
    let completionStart = 0;
    let completionEnd = 0;
    let completionMode = '';
    let suppressCompletion = false;

    if (languageSelect) {
      const options = [['__auto__',`Auto · ${languageLabels[inferredLanguage] || inferredLanguage}`],
        ...labels.filter(id => id !== 'plaintext').map(id => [id,languageLabels[id]]),
        ['plaintext','Plain Text']];
      languageSelect.replaceChildren(...options.map(([value,label]) => {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = label;
        return option;
      }));
      languageSelect.value = '__auto__';
    }

    const updateNumbers = () => {
      const count = textarea.value.split('\n').length;
      gutterNumbers.nodeValue = Array.from({length:count},(_,i)=>String(i+1)).join('\n');
      if (lineStatus) lineStatus.textContent = `${count} lines`;
    };
    const updateCursor = () => {
      const pos = textarea.selectionStart || 0;
      const before = textarea.value.slice(0,pos);
      const line = before.split('\n').length;
      const column = pos - before.lastIndexOf('\n');
      if (cursorStatus) cursorStatus.textContent = `Ln ${line}, Col ${column}`;
      const selected = Math.abs((textarea.selectionEnd || 0) - pos);
      if (selectionStatus) selectionStatus.textContent = selected ? `${selected} selected` : '';
    };
    const findMatchingBrackets = (source, caret) => {
      if (source.length > 300000) return [];
      const pairs = {'(':')','[':']','{':'}'};
      const reverse = {')':'(',']':'[','}':'{'};
      const stack = [];
      const matched = new Map();
      const slashComments = ['php','javascript','typescript'].includes(currentLanguage);
      const hashComments = ['php','shell','python','yaml'].includes(currentLanguage);
      let quote = '';
      let escaped = false;
      let blockComment = false;
      let lineComment = false;
      let htmlComment = false;
      for (let i=0;i<source.length;i++) {
        const ch = source[i];
        const next = source[i+1] || '';
        if (htmlComment) {
          if (source.startsWith('-->',i)) { htmlComment = false; i+=2; }
          continue;
        }
        if (blockComment) {
          if (ch==='*' && next==='/') { blockComment=false; i++; }
          continue;
        }
        if (lineComment) {
          if (ch==='\n') lineComment=false;
          continue;
        }
        if (quote) {
          if (escaped) escaped=false;
          else if (ch==='\\') escaped=true;
          else if (ch===quote) quote='';
          continue;
        }
        if (['html','xml','markdown'].includes(currentLanguage) && source.startsWith('<!--',i)) { htmlComment=true; i+=3; continue; }
        if (ch==='/' && next==='*') { blockComment=true; i++; continue; }
        if (slashComments && ch==='/' && next==='/') { lineComment=true; i++; continue; }
        if (hashComments && ch==='#') { lineComment=true; continue; }
        if (currentLanguage==='sql' && ch==='-' && next==='-') { lineComment=true; i++; continue; }
        if (ch==='"' || ch==="'" || (ch==='`' && ['javascript','typescript'].includes(currentLanguage))) { quote=ch; continue; }
        if (pairs[ch]) stack.push({char:ch,index:i});
        else if (reverse[ch]) {
          const last=stack[stack.length-1];
          if (last && last.char===reverse[ch]) {
            stack.pop();
            matched.set(last.index,i);
            matched.set(i,last.index);
          }
        }
      }
      const atCaret=source[caret]||'';
      const beforeCaret=caret>0?(source[caret-1]||''):'';
      const candidate = atCaret&&'()[]{}'.includes(atCaret) ? caret : beforeCaret&&'()[]{}'.includes(beforeCaret) ? caret-1 : -1;
      const other = matched.get(candidate);
      return other === undefined ? [] : [candidate,other];
    };
    const renderHighlight = () => {
      const source = textarea.value;
      const cursor = textarea.selectionStart || 0;
      const line = source.slice(0,cursor).split('\n').length - 1;
      const rowHeight = settings.fontSize * 1.65;
      activeLine.style.transform = `translateY(${line*rowHeight}px)`;
      activeGutterLine.style.transform = `translateY(${line*rowHeight-textarea.scrollTop}px)`;
      code.innerHTML = highlightSource(source,findMatchingBrackets(source,cursor));
    };
    const updateDirty = () => {
      const value = textarea.value;
      const isDirty = value !== initialValue;
      if (dirtyBadge) dirtyBadge.classList.toggle('show', isDirty);
      if (dirtyDot) dirtyDot.classList.toggle('show', isDirty);
      if (meta) {
        const bytes = new Blob([value]).size;
        meta.textContent = `${bytes >= 1048576 ? (bytes/1048576).toFixed(1)+' MB' : bytes >= 1024 ? (bytes/1024).toFixed(1)+' KB' : bytes+' B'} · ${value.split('\n').length} lines`;
      }
    };
    const updateLanguageStatus = () => {
      currentLanguage = detectCurrentLanguage();
      if (fileGlyph && fileGlyph.dataset.language !== currentLanguage) {
        fileGlyph.dataset.language = currentLanguage;
        fileGlyph.innerHTML = languageIcons[currentLanguage] || languageIcons.plaintext;
      }
      if (fileKind) fileKind.textContent = languageLabels[currentLanguage] || currentLanguage;
      if (editorCard) editorCard.dataset.editorTheme = settings.theme === 'vs' ? 'light' : 'dark';
      if (editor) editor.dataset.language = currentLanguage;
      if (languageStatus) {
        languageStatus.textContent = `${languageLabels[currentLanguage] || currentLanguage} · standalone`;
        languageStatus.classList.add('ed-standalone-status');
        languageStatus.title = 'Standalone syntax highlighting with no external libraries or downloads.';
      }
      if (diagnosticsStatus) diagnosticsStatus.textContent = 'Local editor';
    };
    const update = () => {
      updateLanguageStatus();
      updateNumbers();
      updateCursor();
      updateDirty();
      renderHighlight();
    };
    const syncScroll = () => {
      highlight.style.transform = `translate(${-textarea.scrollLeft}px,${-textarea.scrollTop}px)`;
      gutterNumberLayer.style.transform = `translateY(${-textarea.scrollTop}px)`;
      const currentLine=textarea.value.slice(0,textarea.selectionStart||0).split('\n').length-1;
      activeGutterLine.style.transform=`translateY(${currentLine*settings.fontSize*1.65-textarea.scrollTop}px)`;
      if(completionMenu.classList.contains('show'))positionCompletions();
    };
    const setWrap = enabled => {
      settings.wordWrap = enabled;
      editor.classList.toggle('standalone-wrap', enabled);
      textarea.setAttribute('wrap', enabled ? 'soft' : 'off');
      const button = document.getElementById('edWrapToggle');
      if (button) {
        button.classList.toggle('is-active',enabled);
